def _load_dotenv(path: str = ".env") -> None:
    """Load KEY=VALUE pairs from `.env` without overriding existing env vars."""
    env_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), path)
    if not os.path.isfile(env_path):
        return
    try:
        with open(env_path, encoding="utf-8") as handle:
            for raw_line in handle:
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, _, value = line.partition("=")
                key = key.strip()
                if not key:
                    continue
                value = value.strip().strip('"').strip("'")
                os.environ.setdefault(key, value)
    except OSError as exc:
        print(f"⚠️ Could not read {env_path}: {exc}")


_load_dotenv()


def _env_bool(name: str, default: bool = False) -> bool:
    raw = os.getenv(name)
    if raw is None:
        return default
    return raw.strip().lower() in ("1", "true", "yes", "on")


def _env_int(name: str, default: int) -> int:
    """Read an integer env var. Blank or non-numeric values keep `default`."""
    raw = os.getenv(name)
    if raw is None or not raw.strip():
        return default
    try:
        return int(raw.strip())
    except ValueError:
        print(f"⚠️ {name}={raw!r} is not a whole number — using {default}.")
        return default


def _build_db_config() -> dict:
    host = os.getenv("MYSQL_HOST")
    user = os.getenv("MYSQL_USER")
    password = os.getenv("MYSQL_PASSWORD")
    database = os.getenv("MYSQL_DATABASE")
    missing = [
        key for key, val in (
            ("MYSQL_HOST", host),
            ("MYSQL_USER", user),
            ("MYSQL_PASSWORD", password),
            ("MYSQL_DATABASE", database),
        )
        if not val
    ]
    if missing:
        raise RuntimeError(f"Missing MySQL env vars: {', '.join(missing)}")
    return {
        "host": host,
        "user": user,
        "password": password,
        "database": database,
        "port": int(os.getenv("MYSQL_PORT", "3306")),
        "ssl_disabled": _env_bool("MYSQL_SSL_DISABLED", True),
        # use_pure=True is REQUIRED for connection_timeout to act as a socket-level
        # timeout on every read/write (the C extension only applies it to the
        # connect phase). Without this, a dead socket blocks its worker thread
        # forever, permanently leaking that pooled connection — after 10 leaks the
        # pool is exhausted and every command times out until a manual restart.
        "use_pure": True,
        "connection_timeout": 20,
    }


