# ==========================================================================
# PER-SERVER RUNTIME (multi-server, docs/server-setup.md Stage 2)
#
# One bot process serves every server that added it. Each command, button,
# event, web request and loop iteration runs "for" one server: cur_gid().
# It defaults to the home server (GUILD_ID), so code that never sets it
# behaves exactly as before. Entry points set it once (enter_guild /
# guild_scope); tasks started from there inherit it.
#
# Per-server settings live in a GuildRuntime per server:
#   - dicts / lists (ROLE_IDS, MODE_CONFIG, HOST_BRANCHES, ALLOWED_HOST_ROLES…)
#     are proxies at module level that read the current server's copy;
#   - scalars (HOST_LOG_CHANNEL_ID, WARNINGS_FOR_BAN…) are read as
#     `G.NAME` inside functions.
# The home server's runtime holds the values written in this file until its
# website settings are applied (_install_guild_runtime / _apply_settings).
# ==========================================================================
_CURRENT_GUILD: contextvars.ContextVar[int] = contextvars.ContextVar("gamemaster_guild", default=GUILD_ID)


def cur_gid() -> int:
    """The server the current work is for (the home server by default)."""
    return _CURRENT_GUILD.get()


def _as_gid(value) -> int:
    try:
        gid = int(value or 0)
    except (TypeError, ValueError):
        gid = 0
    return gid or GUILD_ID


def enter_guild(gid) -> int:
    """Set the server for the rest of the current task (entry points)."""
    gid = _as_gid(gid)
    _CURRENT_GUILD.set(gid)
    return gid


class guild_scope:
    """`with guild_scope(gid):` — run a block for one server, then go back."""

    __slots__ = ("gid", "_token")

    def __init__(self, gid):
        self.gid = _as_gid(gid)
        self._token = None

    def __enter__(self):
        self._token = _CURRENT_GUILD.set(self.gid)
        return self.gid

    def __exit__(self, *exc):
        _CURRENT_GUILD.reset(self._token)
        return False


class GuildRuntime:
    """One server's roles, channels, game modes, numbers and status."""

    def __init__(self, gid: int):
        self.gid = int(gid)
        self.dicts: dict = {}
        self.lists: dict = {}
        self.scalars: dict = {}
        self.settings: dict | None = None
        self.version = 0
        self.status = "needs_setup"
        self.present = True

    @property
    def active(self) -> bool:
        """The bot works in this server (setup finished and still in it).
        The home server needs its setup finished too."""
        return self.status == "active" and self.present


_RUNTIMES: dict[int, GuildRuntime] = {}
_RUNTIME_INSTALLED = False


def _rt(gid=None) -> GuildRuntime:
    """The runtime of a server (the current one by default). A server the
    bot has no runtime for gets an empty one — never the home server's."""
    gid = _as_gid(gid if gid is not None else cur_gid())
    rt = _RUNTIMES.get(gid)
    if rt is None:
        rt = _RUNTIMES[gid] = _new_runtime(gid) if _RUNTIME_INSTALLED else GuildRuntime(gid)
    return rt


class _GuildScalars:
    """`G.HOST_LOG_CHANNEL_ID` — the current server's value of a setting."""

    def __getattr__(self, name):
        if _RUNTIME_INSTALLED:
            scalars = _rt().scalars
            if name in scalars:
                return scalars[name]
        return globals()[name]


G = _GuildScalars()


class _GuildDict(collections.abc.MutableMapping):
    """A module-level dict (ROLE_IDS, MODE_CONFIG…) that is the current server's copy."""

    __slots__ = ("_name",)

    def __init__(self, name: str):
        self._name = name

    def _d(self) -> dict:
        return _rt().dicts[self._name]

    def __getitem__(self, key):
        return self._d()[key]

    def __setitem__(self, key, value):
        self._d()[key] = value

    def __delitem__(self, key):
        del self._d()[key]

    def __iter__(self):
        return iter(self._d())

    def __len__(self):
        return len(self._d())

    def __contains__(self, key):
        return key in self._d()

    def get(self, key, default=None):
        return self._d().get(key, default)

    def copy(self) -> dict:
        return dict(self._d())

    def __repr__(self):
        return f"<{self._name} for {cur_gid()}: {self._d()!r}>"


class _GuildList(collections.abc.MutableSequence):
    """A module-level list (ALLOWED_HOST_ROLES…) that is the current server's copy."""

    __slots__ = ("_name",)

    def __init__(self, name: str):
        self._name = name

    def _l(self) -> list:
        return _rt().lists[self._name]

    def __getitem__(self, index):
        return self._l()[index]

    def __setitem__(self, index, value):
        self._l()[index] = value

    def __delitem__(self, index):
        del self._l()[index]

    def __len__(self):
        return len(self._l())

    def __iter__(self):
        return iter(self._l())

    def __contains__(self, value):
        return value in self._l()

    def insert(self, index, value):
        self._l().insert(index, value)

    def __add__(self, other):
        return list(self._l()) + list(other)

    def __radd__(self, other):
        return list(other) + list(self._l())

    def __repr__(self):
        return f"<{self._name} for {cur_gid()}: {self._l()!r}>"


