# Numerical web role_tier derived 100% from live Discord role flags.
# Lower = more privileged (mirrors the web's ROLE_TIER_RANK ordering):
#   VIP = 0 · Trusted = 1 · Verified/Authenticated = 2 · None = 3
_ROLE_TIER_NUM = {"vip": 0, "trusted": 1, "verified": 2, "none": 3}


def _persist_web_access_token_sync(
    token: str,
    user_id: int,
    expires_at: float,
    can_roll_majors: bool,
    role_tier: int = _ROLE_TIER_NUM["none"],
    game_id: str | None = None,
    username: str | None = None,
    is_vip: bool = False,
    is_trusted: bool = False,
    is_verified: bool = False,
    is_authenticated: bool = False,
    is_banned: bool = False,
    receipt_view: bool = False,
    force_receipt: bool = False,
    is_grant: bool = False,
    grant_config: str | None = None,
) -> None:
    """Mirror one token into MySQL (runs in a worker thread — never on the
    event loop). A failed mirror means the web app cannot validate the link.
    `can_roll_majors` is the multiplayer role gate persisted at mint time so
    the web app never has to talk to Discord; the numeric `role_tier` +
    `game_id` let /api/access resolve the DYNAMIC automated-unlock lock
    level at validation time. `username`, `is_vip`, `is_trusted`,
    `is_verified`, `is_authenticated` and `is_banned` are the ZERO-TRUST
    identity flags resolved from the LIVE Discord member roles at mint time
    (no database role reads).

    RESILIENT INSERT: tries the full zero-trust column set first; if the
    columns don't exist yet (bot restarted before the self-heal ran), it
    falls back to the minimal original columns — token persistence can
    NEVER silently fail again.

    VIP INVARIANT: is_vip is minted from the LIVE VIP role flag — and,
    regardless of flag plumbing, a numeric tier of 0 (VIP) ALWAYS forces
    is_vip = 1. The tier can never contradict the flag."""
    # Tier 0 (VIP) implies is_vip = 1 — unconditional, no matter how the
    # flag arrived (single source of truth: the live Discord role check).
    is_vip = bool(is_vip) or (role_tier is not None and int(role_tier) == _ROLE_TIER_NUM["vip"])
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        try:
            cur.execute(
                "INSERT INTO web_access_tokens "
                "(token, user_id, username, is_vip, is_trusted, is_verified, is_authenticated, is_banned, receipt_view, force_receipt, is_grant, grant_config, created_at, expires_at, can_roll_majors, role_tier, game_id) "
                "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)",
                (
                    token,
                    str(user_id),
                    (str(username)[:64] if username else None),
                    1 if is_vip else 0,
                    1 if is_trusted else 0,
                    1 if is_verified else 0,
                    1 if is_authenticated else 0,
                    1 if is_banned else 0,
                    1 if receipt_view else 0,
                    1 if force_receipt else 0,
                    1 if is_grant else 0,
                    grant_config,
                    int(time.time()),
                    int(expires_at),
                    1 if can_roll_majors else 0,
                    int(role_tier),
                    str(game_id) if game_id else None,
                ),
            )
        except Exception:
            # Fallback: legacy schema without the zero-trust columns.
            try:
                cur.execute(
                    "INSERT INTO web_access_tokens "
                    "(token, user_id, receipt_view, force_receipt, is_grant, grant_config, created_at, expires_at, can_roll_majors, role_tier, game_id) "
                    "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)",
                    (
                        token,
                        str(user_id),
                        1 if receipt_view else 0,
                        1 if force_receipt else 0,
                        1 if is_grant else 0,
                        grant_config,
                        int(time.time()),
                        int(expires_at),
                        1 if can_roll_majors else 0,
                        int(role_tier),
                        str(game_id) if game_id else None,
                    ),
                )
            except Exception:
                cur.execute(
                    "INSERT INTO web_access_tokens "
                    "(token, user_id, created_at, expires_at, can_roll_majors, role_tier, game_id) "
                    "VALUES (%s, %s, %s, %s, %s, %s, %s)",
                    (
                        token,
                        str(user_id),
                        int(time.time()),
                        int(expires_at),
                        1 if can_roll_majors else 0,
                        int(role_tier),
                        str(game_id) if game_id else None,
                    ),
                )
                print("[WARN] web token persisted with LEGACY columns (zero-trust flags missing)")
        conn.commit()
    except Exception as e:
        print(f"[WARN] Could not persist web access token to MySQL: {e}")
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _member_identity_flags(member) -> tuple:
    """ZERO-TRUST identity flags resolved at token-mint time:
    returns (username, is_banned).

    Permissions (VIP/Trusted/Verified/Authenticated) are resolved SEPARATELY
    by `_live_role_flags` — 100% live Discord guild roles, no database role
    reads. Bans stay dual-source (Discord ban roles + the users.banned flag)
    because a ban is a denial, never a permission grant."""
    username = getattr(member, "name", None) if member is not None else None
    uid = getattr(member, "id", None)
    role_ids = {int(getattr(r, "id", 0) or 0) for r in getattr(member, "roles", [])}
    banned_by_role = bool(role_ids.intersection(ALL_BAN_IDS))
    stats = get_cached_player_stats() or {}
    banned_in_db = bool((stats.get(str(uid)) or {}).get("banned")) if uid else False
    return username, (banned_by_role or banned_in_db)


async def _generate_web_access_token(
    user_id: int,
    can_roll_majors: bool = False,
    role_tier: int = _ROLE_TIER_NUM["none"],
    game_id: str | None = None,
    username: str | None = None,
    is_vip: bool = False,
    is_trusted: bool = False,
    is_verified: bool = False,
    is_authenticated: bool = False,
    is_banned: bool = False,
    receipt_view: bool = False,
    ttl_seconds: int | None = None,
    force_receipt: bool = False,
    is_grant: bool = False,
    grant_config: str | None = None,
) -> str:
    """Create a single-use, 60-second web access token for a verified member.
    `can_roll_majors` (VIP/Trusted/Verified/Authenticated live role check) is
    persisted with the token so the web app can gate the multiplayer nation
    pool; the numeric `role_tier` + `game_id` let /api/access step the lock
    level down over time (automated_unlock ladder). `username`, `is_vip`,
    `is_trusted`, `is_verified`, `is_authenticated` and `is_banned` are the
    zero-trust identity flags resolved from the LIVE Discord member roles at
    mint time — the web consumes ONLY what this token carries.

    `receipt_view=True` mints a MULTI-USE receipt-view token (longer TTL,
    never burned by /api/access) — used for locked-reservation redirect links
    so the player can re-open their receipt/resume as often as they like.
    `force_receipt=True` additionally tells /api/access to route the link
    DIRECTLY to Stage 5 (the locked receipt) — only FINALIZED links set it;
    IN_PROGRESS resume links stay receipt_view WITHOUT force_receipt.
    `is_grant=True` marks a HOST OVERRIDE grant: /api/access skips ALL
    resume/receipt routing for it (the override config drives the stage).
    `grant_config` (JSON {stage: count}) stamps the host's per-room re-roll
    allowances onto the token so /api/access can hydrate the client's
    redrawsRemainingByStage with the custom grant budgets."""
    # VIP INVARIANT (same as the persist worker): Tier 0 = VIP, always.
    is_vip = bool(is_vip) or (role_tier is not None and int(role_tier) == _ROLE_TIER_NUM["vip"])
    # Mint-time diagnostic trace — proves the role flag and the persisted
    # is_vip column agree for every token.
    print(
        f"[TOKEN-MINT] User: {user_id} | Role VIP Flag: {is_vip} | "
        f"Minted is_vip: {1 if is_vip else 0} | receipt_view: {1 if receipt_view else 0}"
    )
    token = uuid.uuid4().hex
    now = time.time()
    expires = now + (ttl_seconds if ttl_seconds is not None else WEB_ACCESS_TOKEN_TTL_SEC)
    for key in [k for k, (_uid, exp) in _web_access_tokens.items() if exp < now]:
        _web_access_tokens.pop(key, None)
    _web_access_tokens[token] = (int(user_id), expires)
    try:
        await asyncio.wait_for(
            asyncio.to_thread(
                _persist_web_access_token_sync,
                token, user_id, expires, can_roll_majors, role_tier, game_id,
                username, is_vip, is_trusted, is_verified, is_authenticated, is_banned,
                receipt_view, force_receipt, is_grant, grant_config,
            ),
            timeout=10,
        )
    except Exception as e:
        print(f"[WARN] Web access token MySQL mirror failed (web validation will fail): {e}")
    return token


