# Columns the Merit / Dishonored / host-tier systems need on `users`.
# Apollo often never ran schema.sql ALTERs (and older MySQL rejects
# "ADD COLUMN IF NOT EXISTS"), so the bot self-heals on startup.
_USERS_SCHEMA_COLUMNS = (
    ("hoi4_host_tier", "VARCHAR(20) NOT NULL DEFAULT 'None'"),
    ("merit_points", "INT NOT NULL DEFAULT 0"),
    ("dishonored", "TINYINT(1) NOT NULL DEFAULT 0"),
    ("dishonored_data", "JSON NULL"),
    # Dual VIP lookup: the Discord VIP role is primary, but this column is
    # the MySQL half of the check — written by /make_vip and read by
    # _member_has_vip as a fallback when the member cache/role sync lags.
    ("vip", "TINYINT(1) NOT NULL DEFAULT 0"),
    # Hearts of Valor: the Trusted role the host team approved for this user
    # ("Roleplay" / "Historical"; NULL = none).
    ("valor_trusted", "VARCHAR(16) NULL"),
    # HOI4 in-game nickname set through the web reservation dashboard
    # (shown on roster tags and the Discord profile popover).
    ("ingame_nickname", "VARCHAR(64) NULL"),
    # Hist Verified (Historical games); hoi4_verified is RP Verified.
    ("hist_verified", "TINYINT(1) NOT NULL DEFAULT 0"),
    # HIST host rank (hoi4_host_tier is the RP rank).
    ("hist_host_tier", "VARCHAR(20) NOT NULL DEFAULT 'None'"),
)


def _ensure_users_schema_mysql() -> list[str]:
    """Add any missing Merit/Dishonored/host-tier columns on `users`.

    Uses information_schema checks + plain ADD COLUMN (no IF NOT EXISTS) so it
    works on stock MySQL 5.7/8.0 as well as MariaDB. Returns names added.
    """
    conn = None
    cursor = None
    added: list[str] = []
    try:
        conn = _db_get_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT DATABASE()")
        row = cursor.fetchone()
        db_name = row[0] if row else None
        if not db_name:
            print("⚠️ _ensure_users_schema_mysql: no DATABASE() selected — skipped.")
            return added

        cursor.execute(_USERS_TABLE_DDL)

        cursor.execute(
            """
            SELECT COLUMN_NAME FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'users'
            """,
            (db_name,),
        )
        existing = {r[0] for r in cursor.fetchall()}

        for col_name, col_def in _USERS_SCHEMA_COLUMNS:
            if col_name in existing:
                continue
            sql = f"ALTER TABLE users ADD COLUMN {col_name} {col_def}"
            try:
                cursor.execute(sql)
                added.append(col_name)
                print(f"✅ users schema: added column `{col_name}`")
            except Exception as col_err:
                # Race with another instance / partial apply — ignore "Duplicate column"
                err = str(col_err)
                if "1060" in err or "Duplicate column" in err:
                    print(f"ℹ️ users schema: `{col_name}` already present (race).")
                else:
                    print(f"⚠️ users schema: failed to add `{col_name}`: {col_err}")
                    raise

        if added:
            conn.commit()
            print(f"✅ users schema migration complete — added: {', '.join(added)}")
        else:
            print("✅ users schema OK (merit_points / dishonored columns present).")

        # Web Randomizer: single-use access token table (bot writes, web app
        # validates + burns). Idempotent — the commit also covers this DDL.
        cursor.execute(_WEB_ACCESS_TOKENS_DDL)

        # Host Configuration Panel (Phase 2): long-lived host tokens + the
        # web-edited per-slot settings the sync loop pushes to the board.
        cursor.execute(_HOST_ACCESS_TOKENS_DDL)
        cursor.execute(_HOST_SETTINGS_DDL)
        # Reservation-time role gating (2-tier locks) — player session records.
        cursor.execute(_WEB_SESSIONS_DDL)
        # Self-heal the resume-progress columns on web_sessions for tables
        # created by older deployments. CREATE TABLE IF NOT EXISTS cannot add
        # columns to an EXISTING table — without this heal, /api/access's
        # resume read and /api/session's checkpoint write throw
        # "Unknown column" and resume links silently load fresh defaults.
        # This bot runs with the privileged DB user that always has ALTER
        # rights (the web's own ALTER may be denied on shared hosting).
        cursor.execute(
            """
            SELECT COLUMN_NAME FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'web_sessions'
            """,
            (db_name,),
        )
        existing_ws = {r[0] for r in cursor.fetchall()}
        for col_name, col_ddl in (
            ("current_stage", "INT NOT NULL DEFAULT 0"),
            ("progress", "TEXT NULL"),
            ("status", "VARCHAR(16) NOT NULL DEFAULT 'IN_PROGRESS'"),
            # Zero-trust identity mirrors — needed by the receipt-DM worker
            # and the FINALIZED audit payload. Tables created before the
            # identity columns existed must be healed here (the receipt-DM
            # worker's SELECT username... used to 1054 on these).
            ("username", "VARCHAR(64) NULL"),
            ("is_vip", "TINYINT(1) NOT NULL DEFAULT 0"),
            ("is_banned", "TINYINT(1) NOT NULL DEFAULT 0"),
            # Last-checkpoint timestamp (epoch seconds) — touched by
            # /api/access re-validation and every /api/session upsert.
            ("updated_at", "BIGINT NULL"),
            # Receipt-DM dedupe + in-place audit editing (Phase 13).
            ("receipt_dm_sent", "TINYINT(1) NOT NULL DEFAULT 0"),
            ("audit_message_id", "VARCHAR(64) NULL"),
        ):
            if col_name not in existing_ws:
                try:
                    cursor.execute(
                        f"ALTER TABLE web_sessions ADD COLUMN {col_name} {col_ddl}"
                    )
                    print(f"✅ web_sessions schema: added column `{col_name}`")
                except Exception as col_err:
                    err = str(col_err)
                    if "1060" not in err and "Duplicate column" not in err:
                        print(f"⚠️ web_sessions schema: failed to add `{col_name}`: {col_err}")
                        raise

        # Web → Discord reservation sync queue (Phase 7).
        cursor.execute(_RESERVATION_SYNC_QUEUE_DDL)
        # Self-heal the unreserve `action` column — web unreserves enqueue
        # events with action='unreserve' (or an empty slot_key); the sync
        # loop treats either as "remove this user's reservation".
        cursor.execute(
            """
            SELECT COLUMN_NAME FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'reservation_sync_queue'
            """,
            (db_name,),
        )
        existing_rsq = {r[0] for r in cursor.fetchall()}
        if "action" not in existing_rsq:
            try:
                cursor.execute(
                    "ALTER TABLE reservation_sync_queue "
                    "ADD COLUMN action VARCHAR(16) NULL"
                )
                print("✅ reservation_sync_queue schema: added column `action`")
            except Exception as col_err:
                err = str(col_err)
                if "1060" not in err and "Duplicate column" not in err:
                    print(f"⚠️ reservation_sync_queue schema: failed to add `action`: {col_err}")
                    raise
        # Web → Discord receipt DM queue (run FINALIZED at Stage 5).
        cursor.execute(_RECEIPT_DM_QUEUE_DDL)
        # Self-heal the OFFLINE receipt payload column — offline casino runs
        # (thread_id='offline') carry their roll summary here so the DM
        # worker can deliver the receipt without any game thread.
        cursor.execute(
            """
            SELECT COLUMN_NAME FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'receipt_dm_queue'
            """,
            (db_name,),
        )
        existing_rq = {r[0] for r in cursor.fetchall()}
        if "payload" not in existing_rq:
            try:
                cursor.execute(
                    "ALTER TABLE receipt_dm_queue ADD COLUMN payload TEXT NULL"
                )
                print("✅ receipt_dm_queue schema: added column `payload`")
            except Exception as rq_err:
                err = str(rq_err)
                if "1060" not in err and "Duplicate column" not in err:
                    print(f"⚠️ receipt_dm_queue schema: failed to add `payload`: {rq_err}")
                    raise
        # Zero-trust audit trail queue (Phase 9) → Discord audit channel.
        cursor.execute(_AUDIT_EVENTS_DDL)

        # House Receipt logging (Phase 3): game_reservations gains an optional
        # log_message_id column (self-healed for tables created before it).
        cursor.execute(_GAME_RESERVATIONS_DDL)
        # Host Override Panel (Phase 4): override request queue.
        cursor.execute(_HOST_OVERRIDE_REQUESTS_DDL)
        cursor.execute(
            """
            SELECT COLUMN_NAME FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'game_reservations'
            """,
            (db_name,),
        )
        existing_gr = {r[0] for r in cursor.fetchall()}
        if "log_message_id" not in existing_gr:
            try:
                cursor.execute(
                    "ALTER TABLE game_reservations "
                    "ADD COLUMN log_message_id BIGINT NULL"
                )
                print("✅ game_reservations schema: added column `log_message_id`")
            except Exception as col_err:
                err = str(col_err)
                if "1060" not in err and "Duplicate column" not in err:
                    print(f"⚠️ game_reservations schema: failed to add `log_message_id`: {col_err}")
                    raise
        if "rerolls_used" not in existing_gr:
            try:
                cursor.execute(
                    "ALTER TABLE game_reservations "
                    "ADD COLUMN rerolls_used INT NOT NULL DEFAULT 0"
                )
                print("✅ game_reservations schema: added column `rerolls_used`")
            except Exception as col_err:
                err = str(col_err)
                if "1060" not in err and "Duplicate column" not in err:
                    print(f"⚠️ game_reservations schema: failed to add `rerolls_used`: {col_err}")
                    raise

        # RACE-CONDITION GUARDRAIL: a UNIQUE(thread_id, slot_key) constraint
        # physically prevents two players from ever holding the same nation
        # under concurrency. Fresh tables get it via the PRIMARY KEY in the
        # DDL; legacy tables without any unique key on the pair get one
        # self-healed here (the web's duplicate-key retry depends on it).
        try:
            cursor.execute(
                """
                SELECT COUNT(*) FROM information_schema.STATISTICS
                WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'game_reservations'
                  AND INDEX_NAME != 'PRIMARY'
                  AND COLUMN_NAME IN ('thread_id', 'slot_key')
                  AND NON_UNIQUE = 0
                GROUP BY INDEX_NAME HAVING COUNT(DISTINCT COLUMN_NAME) >= 2
                """,
                (db_name,),
            )
            has_unique_pair = bool(cursor.fetchone())
            if not has_unique_pair:
                cursor.execute(
                    "ALTER TABLE game_reservations "
                    "ADD UNIQUE KEY uq_game_reservations_slot (thread_id, slot_key)"
                )
                print("✅ game_reservations schema: added UNIQUE(thread_id, slot_key)")
        except Exception as idx_err:
            err = str(idx_err)
            if "1061" not in err and "Duplicate key name" not in err:
                print(f"⚠️ game_reservations schema: unique index check failed: {idx_err}")

        # Per-player lookups (web portfolios: a player's whole game history)
        # need an index that STARTS with user_id — the existing keys all lead
        # with thread_id, so without this every portfolio scans the table.
        try:
            cursor.execute(
                """
                SELECT COUNT(*) FROM information_schema.STATISTICS
                WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'game_reservations'
                  AND COLUMN_NAME = 'user_id' AND SEQ_IN_INDEX = 1
                """,
                (db_name,),
            )
            row = cursor.fetchone()
            if not (row and row[0]):
                cursor.execute(
                    "ALTER TABLE game_reservations ADD INDEX idx_game_reservations_user_only (user_id)"
                )
                print("✅ game_reservations schema: added INDEX(user_id) for player history lookups")
        except Exception as idx_err:
            err = str(idx_err)
            if "1061" not in err and "Duplicate key name" not in err:
                print(f"⚠️ game_reservations schema: user_id index check failed: {idx_err}")

        # Self-heal the can_roll_majors column for tables created by older
        # deployments (stock MySQL lacks ADD COLUMN IF NOT EXISTS, so check
        # information_schema first).
        cursor.execute(
            """
            SELECT COLUMN_NAME FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'web_access_tokens'
            """,
            (db_name,),
        )
        existing_wa = {r[0] for r in cursor.fetchall()}
        if "can_roll_majors" not in existing_wa:
            try:
                cursor.execute(
                    "ALTER TABLE web_access_tokens "
                    "ADD COLUMN can_roll_majors TINYINT(1) NOT NULL DEFAULT 0"
                )
                print("✅ web_access_tokens schema: added column `can_roll_majors`")
            except Exception as col_err:
                err = str(col_err)
                if "1060" not in err and "Duplicate column" not in err:
                    print(f"⚠️ web_access_tokens schema: failed to add `can_roll_majors`: {col_err}")
                    raise

        # Dynamic lock-level gating (Phase 6) + LIVE-ROLE identity flags:
        # numeric role_tier (0=vip · 1=trusted · 2=verified/auth · 3=none) +
        # optional game_id let /api/access resolve the session's ACTIVE
        # automated-unlock lock level at validation time. Zero-trust identity
        # flags (username / is_vip / is_trusted / is_verified /
        # is_authenticated / is_banned) are resolved from the LIVE Discord
        # member roles at mint time (no database role reads).
        # NOTE: legacy tables keep role_tier as VARCHAR — the writer stores
        # numeric tiers either way, and /api/access parses both shapes.
        for col_name, col_ddl in (
            ("role_tier", "INT NOT NULL DEFAULT 3"),
            ("game_id", "VARCHAR(64) NULL"),
            ("username", "VARCHAR(64) NULL"),
            ("is_vip", "TINYINT(1) NOT NULL DEFAULT 0"),
            ("is_trusted", "TINYINT(1) NOT NULL DEFAULT 0"),
            ("is_verified", "TINYINT(1) NOT NULL DEFAULT 0"),
            ("is_authenticated", "TINYINT(1) NOT NULL DEFAULT 0"),
            ("is_banned", "TINYINT(1) NOT NULL DEFAULT 0"),
            # Multi-use receipt-view tokens (/gamble locked-reservation links):
            # /api/access skips the single-use burn for these rows.
            ("receipt_view", "TINYINT(1) NOT NULL DEFAULT 0"),
            # FINALIZED-only receipt links: /api/access forces resumeStage=5
            # for these tokens (IN_PROGRESS resume links are receipt_view
            # WITHOUT force_receipt and must resume mid-run instead).
            ("force_receipt", "TINYINT(1) NOT NULL DEFAULT 0"),
            # Host-override grant tokens: /api/access skips ALL resume/
            # receipt routing for these — the override config drives the
            # stage (never bounce an override link to Stage 5).
            ("is_grant", "TINYINT(1) NOT NULL DEFAULT 0"),
            # Per-room grant allowances (JSON {stage: count}) stamped onto
            # override tokens so /api/access can hydrate the client's
            # redrawsRemainingByStage with the HOST's custom budgets.
            ("grant_config", "TEXT NULL"),
        ):
            if col_name not in existing_wa:
                try:
                    cursor.execute(
                        f"ALTER TABLE web_access_tokens ADD COLUMN {col_name} {col_ddl}"
                    )
                    print(f"✅ web_access_tokens schema: added column `{col_name}`")
                except Exception as col_err:
                    err = str(col_err)
                    if "1060" not in err and "Duplicate column" not in err:
                        print(f"⚠️ web_access_tokens schema: failed to add `{col_name}`: {col_err}")
                        raise

        # Host ID resolution fix (Phase 6): Discord snowflakes exceed 32-bit
        # INT range — ensure schedule_slots.host_id / games.host_id are BIGINT
        # so IDs never truncate to 0/garbage. CREATE for fresh databases, then
        # widen any existing INT columns.
        cursor.execute(_SCHEDULE_SLOTS_DDL)
        cursor.execute(_GAMES_DDL)
        for table_name, column_name in (("schedule_slots", "host_id"), ("games", "host_id")):
            cursor.execute(
                """
                SELECT DATA_TYPE FROM information_schema.COLUMNS
                WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = %s
                """,
                (db_name, table_name, column_name),
            )
            type_row = cursor.fetchone()
            data_type = str(type_row[0]).lower() if type_row else None
            if data_type and data_type != "bigint":
                try:
                    cursor.execute(
                        f"ALTER TABLE {table_name} MODIFY COLUMN {column_name} BIGINT NOT NULL DEFAULT 0"
                    )
                    print(f"✅ {table_name} schema: `{column_name}` widened to BIGINT")
                except Exception as col_err:
                    print(f"⚠️ {table_name} schema: could not widen `{column_name}`: {col_err}")
                    # Don't raise — the table may be locked; the web falls back
                    # to slot_data.host_id which still carries the real ID.

        # Shared Host Access Key + username resolution (2-tier refactor):
        # schedule_slots gains host_key (8-char shared panel key) and
        # host_username (clean Discord handle) — self-healed for old tables.
        cursor.execute(
            """
            SELECT COLUMN_NAME FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'schedule_slots'
            """,
            (db_name,),
        )
        existing_slots = {r[0] for r in cursor.fetchall()}
        for col_name, col_ddl in (
            ("host_key", "VARCHAR(16) NULL"),
            ("host_username", "VARCHAR(64) NULL"),
            ("status", "VARCHAR(32) NULL"),
            ("current_tier", "TINYINT(1) NOT NULL DEFAULT 1"),
        ):
            if col_name not in existing_slots:
                try:
                    cursor.execute(
                        f"ALTER TABLE schedule_slots ADD COLUMN {col_name} {col_ddl}"
                    )
                    print(f"✅ schedule_slots schema: added column `{col_name}`")
                except Exception as col_err:
                    err = str(col_err)
                    if "1060" not in err and "Duplicate column" not in err:
                        print(f"⚠️ schedule_slots schema: failed to add `{col_name}`: {col_err}")
                        raise

        # Web Scheduling Calendar: request queue + host roster mirror.
        cursor.execute(_WEB_SCHEDULE_REQUESTS_DDL)
        cursor.execute(_WEB_HOST_ROSTER_DDL)
        cursor.execute(_WEB_MEMBER_DIRECTORY_DDL)
        # Self-heal the profile-card columns on directories created before them.
        cursor.execute(
            """
            SELECT COLUMN_NAME FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'web_member_directory'
            """,
            (db_name,),
        )
        existing_dir = {r[0] for r in cursor.fetchall()}
        for col_name, col_ddl in (
            ("role_ids", "TEXT NULL"),
            ("banner_hash", "VARCHAR(64) NULL"),
            ("accent_color", "INT NULL"),
        ):
            if col_name not in existing_dir:
                try:
                    cursor.execute(
                        f"ALTER TABLE web_member_directory ADD COLUMN {col_name} {col_ddl}"
                    )
                    print(f"✅ web_member_directory schema: added column `{col_name}`")
                except Exception as col_err:
                    err = str(col_err)
                    if "1060" not in err and "Duplicate column" not in err:
                        print(f"⚠️ web_member_directory schema: failed to add `{col_name}`: {col_err}")
                        raise
        cursor.execute(_WEB_GUILD_ROLES_DDL)
        # Web portfolios (scale plan, Phase 1).
        cursor.execute(_PLAYER_SUMMARY_DDL)
        cursor.execute(_MODERATION_EVENTS_DDL)
        # Web Attendance page audit trail.
        cursor.execute(_ATTENDANCE_EVENTS_DDL)
        # Web Presets page (game mode presets).
        cursor.execute(_GAME_PRESETS_DDL)
        # VIP grants shared by every server (web Database page).
        cursor.execute(_VIP_GRANTS_DDL)
        # Host → member messages (web Database page, formerly /dm).
        cursor.execute(_HOST_MESSAGES_DDL)
        # Server settings for the website setup (multi-server, Stage 1).
        cursor.execute(_GUILD_SETTINGS_DDL)
        cursor.execute(_GUILD_SETTINGS_HISTORY_DDL)
        cursor.execute(_WEB_GUILD_SNAPSHOT_DDL)
        # Host branches: HIST Acclamations / Violations, roster branches.
        cursor.execute(
            "CREATE TABLE IF NOT EXISTS host_stats (host_id BIGINT NOT NULL PRIMARY KEY, "
            "hosted_games INT NOT NULL DEFAULT 0, acclamations INT NOT NULL DEFAULT 0, "
            "violations INT NOT NULL DEFAULT 0, history JSON NULL)"
        )
        for table_name, col_name, col_ddl in (
            ("host_stats", "hist_acclamations", "INT NOT NULL DEFAULT 0"),
            ("host_stats", "hist_violations", "INT NOT NULL DEFAULT 0"),
            ("web_host_roster", "branches", "VARCHAR(16) NULL"),
        ):
            cursor.execute(
                "SELECT COUNT(*) FROM information_schema.COLUMNS "
                "WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = %s",
                (db_name, table_name, col_name),
            )
            if not cursor.fetchone()[0]:
                try:
                    cursor.execute(f"ALTER TABLE {table_name} ADD COLUMN {col_name} {col_ddl}")
                    print(f"✅ {table_name} schema: added column `{col_name}`")
                except Exception as col_err:
                    if "1060" not in str(col_err) and "Duplicate column" not in str(col_err):
                        raise

        _ensure_multiguild_schema_mysql(cursor, db_name)

        conn.commit()
        return added
    except Exception as e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print(f"⚠️ _ensure_users_schema_mysql failed: {e}")
        raise
    finally:
        if cursor is not None:
            try:
                cursor.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


# ==========================================================================
# MULTI-SERVER SCHEMA (Stage 2): other servers' player records live in
# guild_users; shared tables get a guild_id column (older rows = the home
# server) and per-server keys. Idempotent: checks information_schema first.
# ==========================================================================
_GUILD_USERS_DDL = """
CREATE TABLE IF NOT EXISTS guild_users (
    guild_id VARCHAR(32) NOT NULL,
    discord_id BIGINT NOT NULL,
    total_games INT NOT NULL DEFAULT 0,
    hoi4_verified TINYINT(1) NOT NULL DEFAULT 0,
    stellaris_verified TINYINT(1) NOT NULL DEFAULT 0,
    rp_commends INT NOT NULL DEFAULT 0,
    rp_warns INT NOT NULL DEFAULT 0,
    blacklisted TINYINT(1) NOT NULL DEFAULT 0,
    banned TINYINT(1) NOT NULL DEFAULT 0,
    hist_banned TINYINT(1) NOT NULL DEFAULT 0,
    hist_commends INT NOT NULL DEFAULT 0,
    hist_warns INT NOT NULL DEFAULT 0,
    stel_commends INT NOT NULL DEFAULT 0,
    stel_warns INT NOT NULL DEFAULT 0,
    stel_blacklisted TINYINT(1) NOT NULL DEFAULT 0,
    stel_banned TINYINT(1) NOT NULL DEFAULT 0,
    hosted_games INT NOT NULL DEFAULT 0,
    host_acclamations INT NOT NULL DEFAULT 0,
    host_violations INT NOT NULL DEFAULT 0,
    minor_streaks TEXT NULL,
    hoi4_host_tier VARCHAR(20) NOT NULL DEFAULT 'None',
    merit_points INT NOT NULL DEFAULT 0,
    dishonored TINYINT(1) NOT NULL DEFAULT 0,
    dishonored_data JSON NULL,
    valor_trusted VARCHAR(16) NULL,
    vip TINYINT(1) NOT NULL DEFAULT 0,
    hist_verified TINYINT(1) NOT NULL DEFAULT 0,
    hist_host_tier VARCHAR(20) NOT NULL DEFAULT 'None',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (guild_id, discord_id),
    INDEX idx_guild_users_user (discord_id)
)
"""

# table → (new primary key or None, extra index (name, columns) or None)
_GUILD_SCOPED_TABLES = (
    ("games", None, ("idx_games_guild", "guild_id, status")),
    ("schedule_slots", None, ("idx_schedule_slots_guild", "guild_id, week")),
    ("locked_days", None, None),
    ("host_stats", "guild_id, host_id", None),
    ("player_summary", "guild_id, user_id", None),
    ("moderation_events", None, ("idx_moderation_events_guild", "guild_id, user_id, created_at")),
    ("attendance_events", None, ("idx_attendance_events_guild", "guild_id, created_at")),
    ("web_host_roster", "guild_id, user_id", None),
    ("web_member_directory", "guild_id, user_id", None),
    ("web_guild_roles", None, ("idx_web_guild_roles_guild", "guild_id")),
    ("web_schedule_requests", None, ("idx_web_schedule_requests_guild", "guild_id, status")),
)


def _ensure_multiguild_schema_mysql(cursor, db_name: str) -> None:
    cursor.execute(_GUILD_USERS_DDL)
    for table, primary_key, index in _GUILD_SCOPED_TABLES:
        cursor.execute(
            "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s",
            (db_name, table),
        )
        if not cursor.fetchone()[0]:
            continue
        cursor.execute(
            "SELECT COUNT(*) FROM information_schema.COLUMNS "
            "WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = 'guild_id'",
            (db_name, table),
        )
        if not cursor.fetchone()[0]:
            cursor.execute(
                f"ALTER TABLE {table} ADD COLUMN guild_id VARCHAR(32) NOT NULL DEFAULT '{int(GUILD_ID)}'"
            )
            print(f"✅ {table} schema: added column `guild_id` (existing rows = home server)")
        if primary_key:
            cursor.execute(
                "SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE "
                "WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND CONSTRAINT_NAME = 'PRIMARY' "
                "ORDER BY ORDINAL_POSITION",
                (db_name, table),
            )
            current = ", ".join(r[0] for r in cursor.fetchall())
            if current != primary_key:
                cursor.execute(f"ALTER TABLE {table} DROP PRIMARY KEY, ADD PRIMARY KEY ({primary_key})")
                print(f"✅ {table} schema: primary key is now ({primary_key})")
        if index:
            name, columns = index
            cursor.execute(
                "SELECT COUNT(*) FROM information_schema.STATISTICS "
                "WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND INDEX_NAME = %s",
                (db_name, table, name),
            )
            if not cursor.fetchone()[0]:
                cursor.execute(f"ALTER TABLE {table} ADD INDEX {name} ({columns})")
    # Day locks: one per server per day (the old unique key was one per day).
    cursor.execute(
        "SELECT INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) FROM information_schema.STATISTICS "
        "WHERE TABLE_SCHEMA = %s AND TABLE_NAME = 'locked_days' AND NON_UNIQUE = 0 AND INDEX_NAME <> 'PRIMARY' "
        "GROUP BY INDEX_NAME",
        (db_name,),
    )
    for index_name, columns in cursor.fetchall() or []:
        if columns == "week,day":
            cursor.execute(f"ALTER TABLE locked_days DROP INDEX {index_name}")
            cursor.execute("ALTER TABLE locked_days ADD UNIQUE KEY uniq_locked_guild_week_day (guild_id, week, day)")
            print("✅ locked_days schema: one lock per server per day")


_MYSQL_IO_TIMEOUT = 25.0
# 1020 = record changed since last read (snapshot isolation / concurrent upserts)
# 1020 = record-has-changed optimistic-lock race, 1205 = lock wait timeout,
# 1213 = deadlock, 2006/2013 = connection lost
_MYSQL_RETRYABLE_ERRNOS = {1020, 1205, 1213, 2006, 2013}
# Message fallbacks for when the driver reports these without a numeric errno.
_MYSQL_RETRYABLE_MESSAGES = (
    "record has changed since last read",  # 1020
    "deadlock found",                      # 1213
    "lock wait timeout exceeded",          # 1205
    "server has gone away",                # 2006
    "lost connection",                     # 2013
)
# 4 backoff delays = up to 5 attempts per write (0.1s -> 1s, jittered in _run_mysql_io).
_MYSQL_RETRY_DELAYS = (0.1, 0.25, 0.5, 1.0)


def _mysql_errno(exc) -> int | None:
    """Best-effort errno from mysql-connector (including wrapped errors)."""
    errno = getattr(exc, "errno", None)
    if isinstance(errno, int):
        return errno
    cause = getattr(exc, "__cause__", None)
    if cause is not None and cause is not exc:
        nested = _mysql_errno(cause)
        if nested is not None:
            return nested
    text = str(exc)
    if "1020" in text and "Record has changed since last read" in text:
        return 1020
    return None


def _is_mysql_retryable(exc) -> bool:
    """True for transient MySQL failures worth retrying: optimistic-lock race
    (1020), deadlock (1213), lock wait timeout (1205), and lost connections
    (2006/2013). Matches on errno first, then on message text as a fallback
    for drivers that raise without a numeric errno."""
    errno = _mysql_errno(exc)
    if errno in _MYSQL_RETRYABLE_ERRNOS:
        return True
    text = str(exc).lower()
    return any(marker in text for marker in _MYSQL_RETRYABLE_MESSAGES)


# Must exceed MySQL I/O timeout: write_json holds the games lock for the whole
# bulk save, so waiters need enough headroom to survive one in-flight write.
_FILE_LOCK_TIMEOUT = 40.0

_reservation_locks: dict[str, asyncio.Lock] = {}


def _get_reservation_lock(thread_id: str) -> asyncio.Lock:
    lock = _reservation_locks.get(thread_id)
    if lock is None:
        lock = asyncio.Lock()
        _reservation_locks[thread_id] = lock
    return lock


def _normalize_uid_set(ids) -> set[int]:
    """Coerce stored Discord IDs (int or str) into a set of ints for comparisons."""
    result: set[int] = set()
    for x in ids or []:
        try:
            result.add(int(x))
        except (TypeError, ValueError):
            pass
    return result


async def _scan_voice_presence(guild: discord.Guild, game: dict) -> list[int]:
    """Scan voice channels and return user IDs currently present in game VCs.

    Gated on the game's own dynamic Gamer Pass role (granted only when a player
    clicks the green "Yes" participation button, or via an explicit host
    late-join). Without that role there is no reliable way to tell this game's
    players apart from everyone else on voice — so if the role is missing
    (most commonly: /game_start was never run for this thread) this returns
    an EMPTY list instead of falling back to "every member in any VC", which
    used to wrongly mark unrelated members (in unrelated voice channels
    elsewhere on the server) as having "played" this game.
    """
    present, _details = _scan_voice_states(guild, game)
    return present


def _scan_voice_states(guild: discord.Guild, game: dict) -> tuple[list[int], dict[str, dict]]:
    """The attendance scan plus why each RESERVED player did or didn't count
    (shown on the web Attendance page). Same presence rule as before: any
    voice channel except the Lobby VC, while holding this game's Gamer Pass.

    Returns (present ids, {uid: {state, vc, pass, status}}) where state is
    present · lobby · no_pass (in voice without the pass) · no_voice · unknown."""
    gamer_pass_role_id = game.get("temp_gamer_pass_role")
    lobby_ids = {int(cid) for cid in LOBBY_VC_IDS if cid}
    present: list[int] = []
    if gamer_pass_role_id:
        for vc in guild.voice_channels:
            if vc.id in lobby_ids:
                continue
            for member in vc.members:
                if any(role.id == gamer_pass_role_id for role in member.roles):
                    present.append(member.id)
    present = list(dict.fromkeys(present))
    present_set = set(present)

    details: dict[str, dict] = {}
    for value in (game.get("reservations") or {}).values():
        if not str(value).isdigit() or str(value) in details:
            continue
        member = guild.get_member(int(value))
        if member is None:
            details[str(value)] = {"state": "unknown", "vc": None, "pass": False, "status": "unknown"}
            continue
        has_pass = bool(gamer_pass_role_id) and any(role.id == gamer_pass_role_id for role in member.roles)
        channel = member.voice.channel if member.voice else None
        if member.id in present_set:
            state = "present"
        elif channel is not None and channel.id in lobby_ids:
            state = "lobby"
        elif channel is not None:
            state = "no_pass"
        else:
            state = "no_voice"
        details[str(member.id)] = {
            "state": state,
            "vc": getattr(channel, "name", None),
            "pass": has_pass,
            "status": _discord_presence_label(member),
        }
    return present, details


