CASINO_RULES_ENTRY = {
    "name": "Casino / Casino Protocol Rules",
    "link": "https://docs.google.com/document/d/1xtIZYGCW4HOGbt8_LVyrUFhxjy5uTtlYu4YRD8bSM3s/edit?usp=sharing",
}

# Per game: up to 5 mods and 5 rulesets. A preset / the calendar may set 4
# rulesets, so casino games always have room for the casino rules.
WEB_GAME_MAX_MODS = 5
WEB_GAME_MAX_RULES = 5
WEB_SCHEDULE_MAX_RULES = 4


def _announce_base_mode(mode: str) -> str:
    """The MODE_CONFIG key whose rules channel and standard rulesets a game uses."""
    if "Kaiserreich" in mode:
        return "Kaiserreich (FFA)"
    if "Roleplay" in mode:
        return "Roleplay"
    if "Historical" in mode:
        return "Historical"
    return mode


def _default_resource_entries(mode: str, resource_type: str) -> list[dict]:
    """A mode's standard mods (its own MODE_CONFIG) or rulesets (its base mode's)."""
    if resource_type == "mods":
        links = (MODE_CONFIG.get(mode) or {}).get("mod_links", [])
    else:
        links = (MODE_CONFIG.get(_announce_base_mode(mode)) or {}).get("rule_links", [])
    return _links_to_resource_entries(list(links))


def _slot_resource_entries(slot: dict, mode: str, resource_type: str, casino: bool = False) -> list[dict]:
    """The mods / rulesets a scheduled game posts: the list its preset or the
    calendar set, else the mode's standard one. Casino games add the casino
    rules."""
    raw = (slot or {}).get("mods" if resource_type == "mods" else "rules")
    if isinstance(raw, list):
        entries = [dict(e) for e in raw if isinstance(e, dict) and e.get("name") and e.get("link")]
    else:
        entries = _default_resource_entries(mode, resource_type)
    if casino and resource_type == "rules" and not any(e.get("link") == CASINO_RULES_ENTRY["link"] for e in entries):
        entries.append(dict(CASINO_RULES_ENTRY))
    return entries


def _game_resource_embed(resource_type: str, entries: list[dict], mode: str, game_timestamp) -> discord.Embed:
    """The public mods / rules post of one game."""
    is_mod = resource_type == "mods"
    icon = "🔗" if is_mod else "📜"
    description = "\n\n".join(
        f"{icon} [{discord.utils.escape_markdown(entry['name'])}]({entry['link']})"
        for entry in entries
    ) or ("*No mods are currently required.*" if is_mod else "*No rulesets are currently assigned.*")
    # Native <t:F> tag only — every reader sees their own localized full
    # date & time (no manually formatted date strings).
    game_date = f"<t:{int(game_timestamp)}:F>" if game_timestamp else "Scheduled"
    embed = discord.Embed(
        title=f"🛠️ Mods in use for {game_date} {mode} game" if is_mod else f"📖 Rules for {game_date} {mode} game",
        description=description,
        color=discord.Color.blue() if is_mod else discord.Color.gold(),
    )
    embed.set_footer(text=(
        "Click the links above to subscribe on the Steam Workshop!"
        if is_mod else "Please read the rules carefully before the game begins!"
    ))
    return embed


async def post_mod_embed(guild: discord.Guild, game_mode: str, game_timestamp: int, entries: list | None = None):
    """Posts the mod list to the specific channel for the selected mode and returns the message ID.
    `entries` = the game's own [{name, link}] list (a preset's), else the
    mode's standard mods. `game_timestamp` is a raw integer unix timestamp —
    rendered with a native Discord <t:...:F> tag."""
    config = MODE_CONFIG.get(game_mode)

    if not config:
        print(f"No config found for mode: {game_mode}")
        return None

    target_channel_id = config.get("mods_channel_id")
    if entries is None:
        entries = _default_resource_entries(game_mode, "mods")

    if not target_channel_id or not entries:
        print(f"No mod channel or mods for {game_mode}")
        return None

    channel = guild.get_channel(target_channel_id)
    if not channel:
        print(f"Could not find the mod channel ({target_channel_id}) for {game_mode}.")
        return None

    try:
        msg = await channel.send(embed=_game_resource_embed("mods", entries, game_mode, game_timestamp))
        return msg.id
    except Exception as e:
        print(f"Failed to post mod embed: {e}")
        return None

async def post_rules_embed(guild: discord.Guild, base_mode: str, game_mode: str, game_timestamp: int, randomizer_only: bool, entries: list | None = None):
    """Posts the rules links to the rules channel of `base_mode` and returns the message ID.
    `entries` = the game's own [{name, link}] list (a preset's), else the base
    mode's standard rulesets; casino games (randomizer_only) add the casino
    rules. `game_timestamp` is a raw integer unix timestamp."""

    config = MODE_CONFIG.get(base_mode)
    if not config:
        print(f"No config found for base mode: {base_mode}")
        return None

    target_channel_id = config.get("rules_channel_id")
    entries = [dict(e) for e in (
        entries if entries is not None else _links_to_resource_entries(list(config.get("rule_links", [])))
    )]
    if randomizer_only and not any(e.get("link") == CASINO_RULES_ENTRY["link"] for e in entries):
        entries.append(dict(CASINO_RULES_ENTRY))

    if not target_channel_id or not entries:
        print(f"No rules channel or rulesets for {base_mode}")
        return None

    channel = guild.get_channel(target_channel_id)
    if not channel:
        print(f"Could not find the rules channel ({target_channel_id}) for {base_mode}.")
        return None

    try:
        msg = await channel.send(embed=_game_resource_embed("rules", entries, game_mode, game_timestamp))
        return msg.id
    except Exception as e:
        print(f"Failed to post rules embed: {e}")
        return None

