async def send_tfr_info_dm(member: discord.Member, nation_name: str):
    """Sends a lightweight DM deployment profile to players joining a TFR lobby."""
    nat = TFR_DATA["Nations"].get(nation_name)
    if not nat:
        return

    faction_colors = {
        "NATO": 0x1a6bbf, "CSTO": 0xcc2222, "EADI": 0xcc8800,
        "PDTO": 0x2ecc71, "USA": 0x555555,
    }
    embed = discord.Embed(
        title=f"{nat['flag']} TFR — Deployment Profile",
        description=f"You have reserved **{nation_name}**!",
        color=faction_colors.get(nat["faction"], 0x888888),
    )
    embed.add_field(name="🏛️ Faction", value=TFR_FACTION_HEADERS.get(nat["faction"], nat["faction"]), inline=True)
    embed.add_field(name="📊 Tier", value=nat["tier"], inline=True)
    embed.set_footer(text="TFR • Choose your side carefully.")

    try:
        await member.send(embed=embed)
    except discord.Forbidden:
        pass


def _build_tfr_list(reservations: dict, game_started: bool = False, game: dict = None) -> List[str]:
    """Generates a 2-message lobby overview for TFR.

    Majors render with their national flag emoji; minors follow the standard
    circle status logic (🟢 open / 🟡 reserved / 🔴 started / ⚫ locked / 🟣 late-join).
    """
    if 'TFR_DATA' not in globals():
        return ["# TFR\nError: TFR_DATA is missing."]

    target_game = game or {}
    _major_lock = target_game.get("major_lock_level", "Trusted")
    _minor_lock = target_game.get("minor_lock_level", "All Users")
    late_joins  = target_game.get("late_join_nations", [])

    if game_started:
        footer = "🚨 **Game Started**"
    else:
        _parts = []
        if _major_lock != "All Users": _parts.append(f"Majors: **{_lock_label(_major_lock)}**")
        if _minor_lock != "All Users": _parts.append(f"Minors: **{_lock_label(_minor_lock)}**")
        footer = f"⚠️ {' | '.join(_parts)}" if _parts else "✅ **All Nations Unlocked.**"

    def _coop_suffix(nat: str) -> str:
        coops = "\n".join(
            f" ↳ *Co-op:* {_reservation_mention(cuid)}"
            for k, cuid in reservations.items()
            if k == f"{nat}_coop" or k.startswith(f"{nat}_coop_")
        )
        return ("\n" + coops) if coops else ""

    def _major_line(nat: str) -> str:
        info = TFR_DATA["Nations"].get(nat, {})
        flag = info.get("flag", "🏳️")
        uid  = reservations.get(nat)
        base = f"{flag} **{nat}**: {_reservation_mention(uid)}" if uid else f"{flag} **{nat}**"
        return base + _coop_suffix(nat)

    def _minor_line(nat: str) -> str:
        uid = reservations.get(nat)
        if uid:
            status = EMOJI_LATE_JOIN_CIRCLE if nat in late_joins else (EMOJI_STARTED_CIRCLE if game_started else EMOJI_RESERVED_CIRCLE)
            base   = f"{status} **{nat}**: {_reservation_mention(uid)}"
        else:
            status = EMOJI_LOCKED_CIRCLE if game_started else EMOJI_UNRESERVED_CIRCLE
            base   = f"{status} **{nat}**"
        return base + _coop_suffix(nat)

    def _faction_block(key: str) -> str:
        data   = TFR_DATA["Factions"][key]
        majors = data.get("Majors", [])
        minors = data.get("Minors", [])
        lines  = [f"**{TFR_FACTION_HEADERS.get(key, key)}**"]
        if majors:
            lines.append("__Majors__")
            lines.extend(_major_line(n) for n in majors)
        if minors:
            lines.append("__Minors__" if majors else "__Nations__")
            lines.extend(_minor_line(n) for n in minors)
        return "\n".join(lines)

    # ── MESSAGE 1: NATO + CSTO + EADI ─────────────────────────────────────────
    msg1  = "# 🌍 TFR — Deployment Lobby\n\n"
    msg1 += "\n\n".join(_faction_block(k) for k in ("NATO", "CSTO", "EADI"))

    # ── MESSAGE 2: PDTO + USA + Fillers + Footer ──────────────────────────────
    msg2  = "\n\n".join(_faction_block(k) for k in ("PDTO", "USA"))

    filler_keys = sorted([k for k in reservations if k.startswith("_FILL_")])
    if filler_keys:
        msg2 += "\n\n**🛡️ Fillers / Extras**\n"
        for fk in filler_keys:
            display = fk[6:].replace("_", " ")
            status  = EMOJI_STARTED_CIRCLE if game_started else EMOJI_RESERVED_CIRCLE
            msg2   += f"{status} **{display}**: <@{reservations[fk]}>\n"

    msg2 += f"\n__**Total Reservations: {format_reservation_totals(reservations, 'TFR')}**__\n\n{footer}"

    return [msg1, msg2]


