# ==========================================================================
# ROCKET ROULETTE ENGINE — self-contained rewrite of the legacy randomizer
# build system. Balance is enforced purely through logic rules — there is NO
# point math anywhere in this section (no `pts` keys, no score arithmetic).
#
# Core rules encoded here:
#   * DECOUPLED DOCTRINES — Land/Naval/Air doctrines are standalone rolls
#     that never restrict or dictate build options.
#   * MAJORS: 5 land slots + 1 navy slot + 3 air slots + 3 doctrine rolls.
#   * MINORS: 5 land slots + Land Doctrine ONLY. Navy and Air are output as
#     "Player Choice (Unrestricted)".
#   * European Major Armor Parity (lobby-scoped): if ANY European Major rolls
#     Medium or Heavy Tank, ALL European Majors must roll Medium or Heavy
#     (Light is banned for them in that lobby execution). Mixed Medium/Heavy
#     among European Majors is intended (e.g. Germany Mediums, USSR Heavies).
#   * Minors_Medium / Minors_Weak: Light Tank only. Minors_Strong: any tank.
#   * Armored Cars: minors only AND only when no tank build was assigned —
#     NOTE: the Primary Armor slot always assigns a tank, so under the current
#     spec Armored Cars are unreachable. The constraint logic is kept so the
#     slot remains functional if the spec ever adds a "no tank" outcome.
#   * Bicycle: Belgium / Netherlands / Japan only.
#   * Irregular & Militia: minors only.
#   * Air anti-meta rule: Majors may never roll (Light Fighter + CAS). Valid
#     pairs are (Light + TAC), (Heavy + CAS), (Heavy + TAC) only.
#   * Carrier aircraft interaction: when the navy roll is "Carrier", carrier
#     plane variants are allowed ONLY for rolled aircraft types and explicitly
#     BANNED for non-rolled types.
#
# Game modes: focused on "Roleplay" and "Roleplay (trusted)". Any unknown or
# modded HOI4 nation defaults to Minor (Weak) with a visible flag in output.
# ==========================================================================

EUROPEAN_MAJORS = ["Germany", "Soviet Union", "France", "United Kingdom", "Italy"]

ALL_MAJORS = [
    "U.S.A", "Soviet Union", "Germany", "United Kingdom", "France", "Italy", "Japan",
]

MINORS_STRONG = [
    "Belgium", "Czechoslovakia", "Poland", "Romania", "Spain", "Sweden", "British Raj",
    "China", "Turkey", "Canada", "Mexico", "Argentina", "Brazil", "South Africa",
]

MINORS_MEDIUM = [
    "Austria", "Bulgaria", "Denmark", "Finland", "Greece", "Hungary", "Netherlands",
    "Norway", "Portugal", "Switzerland", "Yugoslavia", "Iran", "Manchuria", "Mongolia",
    "Australia", "Chile", "Egypt",
]

MINORS_WEAK = [
    "Estonia", "Iceland", "Ireland", "Latvia", "Lithuania", "Afghanistan",
    "Chinese Soviet Republic", "French Indochina", "Iraq", "Palestine", "Saudi Arabia",
    "Siam", "Tibet", "British Malaya", "Dutch East Indies", "New Zealand", "Philippines",
    "Honduras", "Colombia", "Venezuela", "Cuba", "Paraguay", "Peru", "Uruguay",
    "Belgian Congo", "Ethiopia",
]

# Nations that may roll the Bicycle special-infantry slot.
BICYCLE_NATIONS = ["Belgium", "Netherlands", "Japan"]

# Internal keys for tank-type armor rolls (used by parity logic).
TANK_KEYS = ("light_tank", "medium_tank", "heavy_tank")


class NationTier(enum.Enum):
    """Rocket Roulette nation tier. Values double as the display labels."""

    MAJOR = "Major"
    MINOR_STRONG = "Strong"
    MINOR_MEDIUM = "Medium"
    MINOR_WEAK = "Weak"


def classify_nation(nation: str) -> Tuple[NationTier, bool]:
    """Return (tier, unlisted) for a nation name.

    Unlisted (modded/unknown) nations default to MINOR_WEAK with
    ``unlisted=True`` so callers can flag them in the output.
    """
    if nation in ALL_MAJORS:
        return NationTier.MAJOR, False
    if nation in MINORS_STRONG:
        return NationTier.MINOR_STRONG, False
    if nation in MINORS_MEDIUM:
        return NationTier.MINOR_MEDIUM, False
    if nation in MINORS_WEAK:
        return NationTier.MINOR_WEAK, False
    return NationTier.MINOR_WEAK, True


def _base_nation(nation: str) -> str:
    """Strip co-op/filler suffixes so lobby keys classify correctly."""
    return (nation or "").split("_coop", 1)[0].replace("_FILL_", "").strip()


# --------------------------------------------------------------------------
# TYPED DATA MODELS
# --------------------------------------------------------------------------


@dataclass(frozen=True)
class SlotItem:
    """A single rollable slot entry (build item or doctrine)."""

    key: str
    name: str
    emoji: str
    notes: Tuple[str, ...] = ()


@dataclass(frozen=True)
class LandBuild:
    armor: SlotItem
    transport: SlotItem
    special_infantry: SlotItem
    special_forces: SlotItem
    line_specialty_category: str          # "Anti-Tank" / "Anti-Infantry" / "Anti-Air"
    line_specialty: SlotItem
    line_specialty_note: str


@dataclass(frozen=True)
class Doctrines:
    """Independent doctrine rolls — never coupled to build options."""

    land: SlotItem
    naval: Optional[SlotItem] = None      # Majors only
    air: Optional[SlotItem] = None        # Majors only


@dataclass(frozen=True)
class NavyBuild:
    option_key: str                        # "submarines_only" | "capital_ship"
    item: SlotItem
    note: str
    # 5-slot parity (v0 web slot machine schema): the 5th Navy/Air slot.
    # Destroyer / Light Cruiser when a capital navy is rolled; None under
    # "Submarines Only" (that option bans ALL new screens by design).
    screen: Optional[SlotItem] = None
    screen_note: str = ""


@dataclass(frozen=True)
class AirBuild:
    fighter: SlotItem                      # Light Fighter | Heavy Fighter
    bomber: SlotItem                       # CAS | TAC (anti-meta constrained)
    specialty: SlotItem                    # Strategic Bomber | Naval Bomber


@dataclass(frozen=True)
class CarrierRules:
    """Carrier plane permissions derived from the rolled Air slots."""

    fighters_allowed: bool
    cas_allowed: bool
    naval_bombers_allowed: bool

    def lines(self) -> List[str]:
        return [
            "Carrier variants for non-rolled aircraft types are BANNED.",
            ("✅ Carrier Fighter ALLOWED (Light Fighter rolled)"
             if self.fighters_allowed
             else "🚫 Carrier Fighter BANNED (Light Fighter NOT rolled)"),
            ("✅ Carrier CAS ALLOWED (Light Fighter frame + CAS rolled)"
             if self.cas_allowed
             else "🚫 Carrier CAS BANNED (Light Fighter frame + CAS NOT rolled)"),
            ("✅ Carrier NAV ALLOWED (Naval Bomber rolled)"
             if self.naval_bombers_allowed
             else "🚫 Carrier NAV BANNED (Naval Bomber NOT rolled)"),
        ]


@dataclass(frozen=True)
class PlayerRoll:
    """One nation's complete Rocket Roulette roll."""

    player_id: Any
    nation: str
    tier: NationTier
    unlisted: bool
    flag: str
    land: LandBuild
    doctrines: Doctrines
    navy: Optional[NavyBuild] = None       # Majors only
    air: Optional[AirBuild] = None         # Majors only
    carrier_rules: Optional[CarrierRules] = None

    @property
    def tier_label(self) -> str:
        return self.tier.value

    @property
    def is_major(self) -> bool:
        return self.tier is NationTier.MAJOR


@dataclass(frozen=True)
class RocketRouletteLobby:
    """Full-lobby result of generate_rocket_roulette_lobby()."""

    players: Dict[Any, PlayerRoll]
    parity: str                              # "light" | "medium_heavy" | "none"
    european_major_armor: Dict[str, str]     # nation -> armor name


