# Convenience pools (module-level; derived once from RANDOMIZER_DATA).
_ARMOR_ALL: List[SlotItem] = list(RANDOMIZER_DATA["Land"]["Armor"].values())
_ARMOR_MEDIUM_HEAVY: List[SlotItem] = [
    RANDOMIZER_DATA["Land"]["Armor"]["medium_tank"],
    RANDOMIZER_DATA["Land"]["Armor"]["heavy_tank"],
]
_LAND_DOCTRINES: List[SlotItem] = RANDOMIZER_DATA["Doctrines"]["Land"]
_NAVAL_DOCTRINES: List[SlotItem] = RANDOMIZER_DATA["Doctrines"]["Naval"]
_AIR_DOCTRINES: List[SlotItem] = RANDOMIZER_DATA["Doctrines"]["Air"]

_LINE_SPECIALTY_NOTE: str = RANDOMIZER_DATA["Land"]["Line_Specialty_Note"]

_SUBS_ITEM: SlotItem = RANDOMIZER_DATA["Navy"]["Submarines Only"]
_CAPITAL_ITEMS: List[SlotItem] = list(RANDOMIZER_DATA["Navy"]["Capitals"].values())
_CAPITAL_NOTE: str = RANDOMIZER_DATA["Navy"]["Capital_Note"]
_SCREEN_ITEMS: List[SlotItem] = list(RANDOMIZER_DATA["Navy"]["Screens"].values())

_LIGHT_FIGHTER: SlotItem = RANDOMIZER_DATA["Air"]["Fighters"]["light_fighter"]
_HEAVY_FIGHTER: SlotItem = RANDOMIZER_DATA["Air"]["Fighters"]["heavy_fighter"]
_CAS_ITEM: SlotItem = RANDOMIZER_DATA["Air"]["Bombers"]["cas"]
_TAC_ITEM: SlotItem = RANDOMIZER_DATA["Air"]["Bombers"]["tac"]


# --------------------------------------------------------------------------
# SLOT ROLLERS
# --------------------------------------------------------------------------

def _roll_armor(
    nation: str,
    tier: NationTier,
    rng,
    armor_pool: Optional[Sequence[SlotItem]] = None,
) -> SlotItem:
    """Primary Armor slot.

    * Minors_Medium / Minors_Weak: Light Tank only.
    * European Majors: constrained by the lobby parity pool when given.
    * Everyone else (Majors, Minors_Strong): free choice of Light/Medium/Heavy.
    """
    if tier in (NationTier.MINOR_MEDIUM, NationTier.MINOR_WEAK):
        return RANDOMIZER_DATA["Land"]["Armor"]["light_tank"]
    if armor_pool is not None and nation in EUROPEAN_MAJORS:
        return rng.choice(list(armor_pool))
    return rng.choice(_ARMOR_ALL)


def _roll_transport(tier: NationTier, has_tank: bool, rng) -> SlotItem:
    """Mobile Transport slot.

    * Armored Cars: minors ONLY, and only when no tank build was assigned.
      (The Primary Armor slot always assigns a tank under the current spec,
      so Armored Cars are currently unreachable — the logic remains in place.)
    * Majors can NEVER roll Armored Cars.
    """
    pool: List[SlotItem] = [
        RANDOMIZER_DATA["Land"]["Transport"]["motorized"],
        RANDOMIZER_DATA["Land"]["Transport"]["mechanized"],
        RANDOMIZER_DATA["Land"]["Transport"]["amtracs"],
    ]
    if tier is not NationTier.MAJOR and not has_tank:
        pool.append(RANDOMIZER_DATA["Land"]["Transport"]["armored_cars"])
    return rng.choice(pool)


def _roll_special_infantry(nation: str, tier: NationTier, rng) -> SlotItem:
    """Special Infantry slot.

    * Bicycle: Belgium / Netherlands / Japan only.
    * Irregular & Militia: minors only.
    """
    infantry = RANDOMIZER_DATA["Land"]["Special_Infantry"]
    # Garrison is deliberately EXCLUDED — removed from the Special Infantry
    # roster entirely (players can never roll a Garrison build).
    pool: List[SlotItem] = [
        infantry["jaeger"], infantry["jungle"], infantry["desert"],
        infantry["cavalry"], infantry["camelry"],
    ]
    if nation in BICYCLE_NATIONS:
        pool.append(infantry["bicycle"])
    if tier is not NationTier.MAJOR:
        pool.append(infantry["irregular"])
        pool.append(infantry["militia"])
    return rng.choice(pool)


def _roll_special_forces(rng) -> SlotItem:
    """Special Forces slot — all tiers; Paratroopers/Rangers carry exemption notes."""
    return rng.choice(list(RANDOMIZER_DATA["Land"]["Special_Forces"].values()))


def _roll_line_specialty(rng) -> Tuple[str, SlotItem]:
    """Line Specialty slot — bot picks ONE category, then ONE sub-type."""
    categories = RANDOMIZER_DATA["Land"]["Line_Specialty"]
    category = rng.choice(list(categories.keys()))
    sub_type = rng.choice(categories[category])
    return category, sub_type


def _roll_doctrines(tier: NationTier, rng) -> Doctrines:
    """Independent doctrine rolls — fully decoupled from build options."""
    naval = rng.choice(_NAVAL_DOCTRINES) if tier is NationTier.MAJOR else None
    air = rng.choice(_AIR_DOCTRINES) if tier is NationTier.MAJOR else None
    return Doctrines(land=rng.choice(_LAND_DOCTRINES), naval=naval, air=air)


def _roll_navy(rng) -> NavyBuild:
    """Navy slots (Majors only) — 50/50 between the two capital options.

    * Option A: "Submarines Only" — no new screens/capitals, refits allowed
      (Navy Screen slot shows "— Submarines Only").
    * Option B: one capital ship type — no OTHER capital production/refits;
      screens are restricted by the rolled Navy Screen slot (Destroyer or
      Light Cruiser; Destroyer bans new Light Cruiser production).
    """
    if rng.random() < 0.5:
        item = _SUBS_ITEM
        option_key = "submarines_only"
        note = item.notes[0] if item.notes else ""
        screen = None
        screen_note = ""
    else:
        item = rng.choice(_CAPITAL_ITEMS)
        option_key = "capital_ship"
        note = _CAPITAL_NOTE
        screen = rng.choice(_SCREEN_ITEMS)
        screen_note = screen.notes[0] if screen.notes else ""
    return NavyBuild(
        option_key=option_key,
        item=item,
        note=note,
        screen=screen,
        screen_note=screen_note,
    )


def _roll_air(rng) -> AirBuild:
    """Air slots (Majors only).

    Anti-meta rule: (Light Fighter + CAS) is forbidden. Light Fighter forces
    TAC; Heavy Fighter may pair with CAS or TAC.
    """
    fighter = rng.choice([_LIGHT_FIGHTER, _HEAVY_FIGHTER])
    if fighter.key == "light_fighter":
        bomber = _TAC_ITEM
    else:
        bomber = rng.choice([_CAS_ITEM, _TAC_ITEM])
    specialty = rng.choice(
        [
            RANDOMIZER_DATA["Air"]["Specialty"]["strategic_bomber"],
            RANDOMIZER_DATA["Air"]["Specialty"]["naval_bomber"],
        ]
    )
    return AirBuild(fighter=fighter, bomber=bomber, specialty=specialty)


def _build_carrier_rules(navy: NavyBuild, air: AirBuild) -> Optional[CarrierRules]:
    """Dynamic carrier-plane permissions when the Navy roll is 'Carrier'."""
    if navy.item.key != "carrier":
        return None
    return CarrierRules(
        fighters_allowed=(air.fighter.key == "light_fighter"),
        # Carrier CAS rides the LIGHT FIGHTER frame in HOI4 — it needs BOTH
        # the frame and the CAS roll (an anti-meta-impossible pair for majors).
        cas_allowed=(
            air.fighter.key == "light_fighter" and air.bomber.key == "cas"
        ),
        naval_bombers_allowed=(air.specialty.key == "naval_bomber"),
    )


def _generate_nation_build(
    nation: str,
    tier: NationTier,
    unlisted: bool,
    *,
    player_id: Any,
    flag: str,
    rng,
    armor_pool: Optional[Sequence[SlotItem]] = None,
) -> PlayerRoll:
    """Roll every slot for one nation (armor may be pre-resolved by the lobby)."""
    is_major = tier is NationTier.MAJOR

    armor = _roll_armor(nation, tier, rng, armor_pool=armor_pool)
    transport = _roll_transport(tier, has_tank=(armor.key in TANK_KEYS), rng=rng)
    special_infantry = _roll_special_infantry(nation, tier, rng)
    special_forces = _roll_special_forces(rng)
    line_category, line_specialty = _roll_line_specialty(rng)

    land = LandBuild(
        armor=armor,
        transport=transport,
        special_infantry=special_infantry,
        special_forces=special_forces,
        line_specialty_category=line_category,
        line_specialty=line_specialty,
        line_specialty_note=_LINE_SPECIALTY_NOTE,
    )

    doctrines = _roll_doctrines(tier, rng)

    navy: Optional[NavyBuild] = None
    air: Optional[AirBuild] = None
    carrier_rules: Optional[CarrierRules] = None
    if is_major:
        navy = _roll_navy(rng)
        air = _roll_air(rng)
        carrier_rules = _build_carrier_rules(navy, air)

    return PlayerRoll(
        player_id=player_id,
        nation=nation,
        tier=tier,
        unlisted=unlisted,
        flag=flag,
        land=land,
        doctrines=doctrines,
        navy=navy,
        air=air,
        carrier_rules=carrier_rules,
    )


# --------------------------------------------------------------------------
# PUBLIC API
# --------------------------------------------------------------------------

def generate_rocket_roulette_build(
    nation: str,
    *,
    player_id: Any = None,
    european_armor_locked: bool = False,
    flag_map: Optional[Dict[str, str]] = None,
    rng=None,
) -> PlayerRoll:
    """Roll one nation's full Rocket Roulette build (per-player /gamble flow).

    ``european_armor_locked`` — pass True when the reservation thread's saved
    lobby state shows any European Major currently holding a Medium/Heavy
    Tank; the rolling European Major is then forced to re-roll within
    {Medium, Heavy} to maintain parity (smart stateful re-roll rule, Q6).
    """
    rng = rng or random
    base = _base_nation(nation)
    tier, unlisted = classify_nation(base)
    flags = flag_map or {}
    flag = flags.get(base, "🏳️")

    armor_pool: Optional[List[SlotItem]] = None
    if base in EUROPEAN_MAJORS and european_armor_locked:
        armor_pool = _ARMOR_MEDIUM_HEAVY

    return _generate_nation_build(
        base, tier, unlisted,
        player_id=player_id, flag=flag, rng=rng, armor_pool=armor_pool,
    )


def generate_rocket_roulette_lobby(
    players_dict: Dict[Any, str],
    *,
    flag_map: Optional[Dict[str, str]] = None,
    rng=None,
) -> RocketRouletteLobby:
    """Roll an entire lobby of ``{player_id: nation_name}``.

    Step 1 — European Major Armor Parity: every European Major's armor is
    rolled independently first. If ANY rolls Medium or Heavy, every European
    Major must hold Medium or Heavy (Light-rollers are re-rolled within
    {Medium, Heavy}); otherwise they all keep Light. Mixed Medium/Heavy
    among European Majors is intended.

    Step 2 — every remaining slot is rolled per nation (Majors: land + navy +
    air + 3 doctrines; Minors: land + Land Doctrine only).

    Step 3 — returns a RocketRouletteLobby ready for embed formatting.
    """
    rng = rng or random
    flags = flag_map or {}

    base_players: Dict[Any, str] = {pid: _base_nation(n) for pid, n in players_dict.items()}

    # ---- Step 1: European Major Armor Parity -----------------------------
    euro_ids = [pid for pid, nation in base_players.items() if nation in EUROPEAN_MAJORS]
    first_pass: Dict[Any, SlotItem] = {pid: rng.choice(_ARMOR_ALL) for pid in euro_ids}

    if not euro_ids:
        parity = "none"
    elif any(item.key != "light_tank" for item in first_pass.values()):
        parity = "medium_heavy"
    else:
        parity = "light"

    resolved_armor: Dict[Any, SlotItem] = {}
    if parity == "medium_heavy":
        for pid, item in first_pass.items():
            resolved_armor[pid] = item if item.key != "light_tank" else rng.choice(_ARMOR_MEDIUM_HEAVY)
    else:
        resolved_armor = dict(first_pass)

    # ---- Step 2: full builds for every nation ----------------------------
    players: Dict[Any, PlayerRoll] = {}
    for pid, nation in base_players.items():
        tier, unlisted = classify_nation(nation)
        armor_pool = (
            [resolved_armor[pid]]
            if pid in resolved_armor
            else (_ARMOR_MEDIUM_HEAVY if (nation in EUROPEAN_MAJORS and parity == "medium_heavy") else None)
        )
        players[pid] = _generate_nation_build(
            nation, tier, unlisted,
            player_id=pid,
            flag=flags.get(nation, "🏳️"),
            rng=rng,
            armor_pool=armor_pool,
        )

    european_major_armor: Dict[str, str] = {
        base_players[pid]: resolved_armor[pid].name for pid in resolved_armor
    }

    return RocketRouletteLobby(
        players=players,
        parity=parity,
        european_major_armor=european_major_armor,
    )


# --------------------------------------------------------------------------
# OUTPUT FORMATTERS (text + Discord embeds)
# --------------------------------------------------------------------------

_DEFAULT_CATEGORY_EMOJIS = {"land": "🛡️", "navy": "⚓", "air": "✈️"}


def _spoiler(text: str, enabled: bool) -> str:
    return f"|| {text} ||" if enabled else text


def format_build_block(
    roll: PlayerRoll,
    *,
    category_emojis: Optional[Dict[str, str]] = None,
    spoiler: bool = False,
) -> str:
    """Multi-line DM/embed text block for one nation's build."""
    cat = dict(_DEFAULT_CATEGORY_EMOJIS)
    if category_emojis:
        cat.update(category_emojis)

    land = roll.land
    doc = roll.doctrines

    lines: List[str] = [
        f"{cat['land']} **Primary Armor:** {_spoiler(f'{land.armor.emoji} {land.armor.name}', spoiler)}",
        f"**Mobile Transport:** {_spoiler(f'{land.transport.emoji} {land.transport.name}', spoiler)}",
        f"**Special Infantry:** {_spoiler(f'{land.special_infantry.emoji} {land.special_infantry.name}', spoiler)}",
        f"**Special Forces:** {_spoiler(f'{land.special_forces.emoji} {land.special_forces.name}', spoiler)}",
    ]
    for note in land.special_forces.notes:
        lines.append(f"   *Exemption:* {note}")
    lines.append(
        f"**Line Specialty:** {_spoiler(f'{land.line_specialty_category} → {land.line_specialty.emoji} {land.line_specialty.name}', spoiler)}"
    )
    lines.append(f"   *Rule:* {land.line_specialty_note}")
    lines.append(f"**Land Doctrine:** {_spoiler(f'{doc.land.emoji} {doc.land.name}', spoiler)}")

    if roll.is_major and roll.navy and roll.air and doc.naval and doc.air:
        navy = roll.navy
        air = roll.air
        naval_doc = doc.naval
        air_doc = doc.air
        lines.append("")
        lines.append(f"{cat['navy']} **Navy:** {_spoiler(f'{navy.item.emoji} {navy.item.name}', spoiler)}")
        lines.append(f"   *Rule:* {navy.note}")
        # 5th Navy/Air slot — Navy Screen (Destroyer / Light Cruiser).
        if navy.screen:
            lines.append(
                f"**Navy Screen:** {_spoiler(f'{navy.screen.emoji} {navy.screen.name}', spoiler)}"
            )
            for note_text in navy.screen.notes:
                lines.append(f"> {note_text}")
        else:
            lines.append("**Navy Screen:** *— Submarines Only*")
        lines.append(f"**Naval Doctrine:** {_spoiler(f'{naval_doc.emoji} {naval_doc.name}', spoiler)}")
        lines.append("")
        lines.append(
            f"{cat['air']} **Fighter:** {_spoiler(f'{air.fighter.emoji} {air.fighter.name}', spoiler)}"
            f"  **Bomber:** {_spoiler(f'{air.bomber.emoji} {air.bomber.name}', spoiler)}"
            f"  **Specialty:** {_spoiler(f'{air.specialty.emoji} {air.specialty.name}', spoiler)}"
        )
        lines.append(f"**Air Doctrine:** {_spoiler(f'{air_doc.emoji} {air_doc.name}', spoiler)}")
        if roll.carrier_rules:
            lines.append("")
            lines.append("   ✈️ **Carrier Aircraft Rules:**")
            for rule_line in roll.carrier_rules.lines():
                lines.append(f"      {rule_line}")
    else:
        lines.append(f"{cat['navy']} **Navy:** *Player Choice (Unrestricted)*")
        lines.append(f"{cat['air']} **Air:** *Player Choice (Unrestricted)*")

    return "\n".join(lines)


def format_build_slots(roll: PlayerRoll) -> str:
    """Compact emoji slot string for the ephemeral reveal message."""
    land = roll.land
    doc = roll.doctrines
    parts = [
        f"[{land.armor.emoji}]",
        f"[{land.transport.emoji}]",
        f"[{land.special_infantry.emoji}]",
        f"[{land.special_forces.emoji}]",
        f"[{land.line_specialty.emoji}]",
        f"[{doc.land.emoji}]",
    ]
    if roll.is_major and roll.navy and roll.air and doc.naval and doc.air:
        navy = roll.navy
        air = roll.air
        naval_doc = doc.naval
        air_doc = doc.air
        parts += [
            f"[{navy.item.emoji}]",
            # 5th Navy/Air slot: Navy Screen (⛔ under Submarines Only).
            f"[{navy.screen.emoji if navy.screen else '⛔'}]",
            f"[{naval_doc.emoji}]",
            f"[{air.fighter.emoji}]",
            f"[{air.bomber.emoji}]",
            f"[{air.specialty.emoji}]",
            f"[{air_doc.emoji}]",
        ]
    return " ".join(parts)


def format_build_log(roll: PlayerRoll) -> str:
    """Host-log text block for one nation's build (no spoilers, no points)."""
    land = roll.land
    doc = roll.doctrines

    lines = [
        f"**Land Doctrine:** {doc.land.name}",
        f"**Armor:** {land.armor.name} | **Transport:** {land.transport.name} | "
        f"**Special Infantry:** {land.special_infantry.name} | "
        f"**Special Forces:** {land.special_forces.name} | "
        f"**Line Specialty:** {land.line_specialty_category} → {land.line_specialty.name}",
    ]
    for note in land.special_forces.notes:
        lines.append(f"*SF Exemption:* {note}")
    lines.append(f"*Line Rule:* {land.line_specialty_note}")

    if roll.is_major and roll.navy and roll.air and doc.naval and doc.air:
        navy = roll.navy
        air = roll.air
        naval_doc = doc.naval
        air_doc = doc.air
        lines.append(f"**Navy:** {navy.item.name} — {navy.note}")
        if navy.screen:
            screen_log = f"**Navy Screen:** {navy.screen.name}"
            if navy.screen_note:
                screen_log += f" — {navy.screen_note}"
            lines.append(screen_log)
        else:
            lines.append("**Navy Screen:** — Submarines Only")
        lines.append(f"**Naval Doctrine:** {naval_doc.name}")
        lines.append(f"**Air:** {air.fighter.name} + {air.bomber.name} + {air.specialty.name}")
        lines.append(f"**Air Doctrine:** {air_doc.name}")
        if roll.carrier_rules:
            lines.append(f"**Carrier Rules:** {' | '.join(roll.carrier_rules.lines())}")
    else:
        lines.append("**Navy:** Player Choice (Unrestricted)")
        lines.append("**Air:** Player Choice (Unrestricted)")

    return "\n".join(lines) + "\n"


def build_player_embed(
    roll: PlayerRoll,
    *,
    title: str = "🚀 ROCKET ROULETTE",
    color: int = 0xF1C40F,
) -> discord.Embed:
    """Discord embed for one nation's full roll."""
    description = f"{roll.flag} **{roll.nation}** — {roll.tier_label}"
    if roll.unlisted:
        description += " *(⚠️ unlisted nation — treated as Minor (Weak))*"
    embed = discord.Embed(title=title, description=description, color=color)

    land = roll.land
    doc = roll.doctrines
    embed.add_field(name="Primary Armor", value=f"{land.armor.emoji} {land.armor.name}", inline=True)
    embed.add_field(name="Mobile Transport", value=f"{land.transport.emoji} {land.transport.name}", inline=True)
    embed.add_field(name="Special Infantry", value=f"{land.special_infantry.emoji} {land.special_infantry.name}", inline=True)
    embed.add_field(name="Special Forces", value=f"{land.special_forces.emoji} {land.special_forces.name}", inline=True)
    embed.add_field(
        name="Line Specialty",
        value=f"{land.line_specialty_category} → {land.line_specialty.emoji} {land.line_specialty.name}",
        inline=True,
    )
    embed.add_field(name="Land Doctrine", value=f"{doc.land.emoji} {doc.land.name}", inline=True)

    if land.special_forces.notes:
        embed.add_field(
            name="SF Exemptions",
            value="\n".join(land.special_forces.notes),
            inline=False,
        )
    embed.add_field(name="Line Rule", value=land.line_specialty_note, inline=False)

    if roll.is_major and roll.navy and roll.air and doc.naval and doc.air:
        navy = roll.navy
        air = roll.air
        naval_doc = doc.naval
        air_doc = doc.air
        # Symmetrical 5-slot Navy/Air schema (v0 web slot machine parity):
        # 1 Air Fighter · 2 Air Bomber · 3 Air Specialty · 4 Navy Capital
        # · 5 Navy Screen — rendered as five inline fields.
        embed.add_field(name="Air Fighter", value=f"{air.fighter.emoji} {air.fighter.name}", inline=True)
        embed.add_field(name="Air Bomber", value=f"{air.bomber.emoji} {air.bomber.name}", inline=True)
        embed.add_field(name="Air Specialty", value=f"{air.specialty.emoji} {air.specialty.name}", inline=True)
        embed.add_field(name="Navy Capital", value=f"{navy.item.emoji} {navy.item.name}", inline=True)
        embed.add_field(
            name="Navy Screen",
            value=(
                f"{navy.screen.emoji} {navy.screen.name}"
                if navy.screen else "*— Submarines Only*"
            ),
            inline=True,
        )
        embed.add_field(name="Air Doctrine", value=f"{air_doc.emoji} {air_doc.name}", inline=True)
        embed.add_field(name="Naval Doctrine", value=f"{naval_doc.emoji} {naval_doc.name}", inline=True)
        embed.add_field(name="Navy Rule", value=navy.note, inline=False)
        if navy.screen_note:
            # Exact Screen Rule annotation (the bold "Screen Rule:" label stays
            # in the markdown DM block; embeds carry the clean warning text).
            embed.add_field(
                name="Screen Rule",
                value=navy.screen_note.replace("⚠️ **Screen Rule:** ", "⚠️ "),
                inline=False,
            )
        if roll.carrier_rules:
            embed.add_field(
                name="Carrier Aircraft Rules",
                value="\n".join(roll.carrier_rules.lines()),
                inline=False,
            )
    else:
        embed.add_field(name="Navy", value="Player Choice (Unrestricted)", inline=True)
        embed.add_field(name="Air", value="Player Choice (Unrestricted)", inline=True)

    return embed


def build_lobby_summary_embed(
    lobby: RocketRouletteLobby,
    *,
    title: str = "🚀 Rocket Roulette — Lobby Results",
    color: int = 0xF1C40F,
) -> discord.Embed:
    """Compact overview embed for a full lobby roll."""
    parity_label = {
        "light": "Light Tank",
        "medium_heavy": "Medium / Heavy Tank",
        "none": "No European Majors in lobby",
    }[lobby.parity]

    lines = [f"**European Major Armor Parity:** {parity_label}"]
    for roll in lobby.players.values():
        land = roll.land
        entry = (
            f"{roll.flag} **{roll.nation}** ({roll.tier_label}): "
            f"{land.armor.emoji} {land.armor.name} · {land.transport.name} · "
            f"{land.special_infantry.name} · {land.special_forces.name} · "
            f"{land.line_specialty.name} · {roll.doctrines.land.name}"
        )
        doc = roll.doctrines
        if roll.is_major and roll.navy and roll.air and doc.naval and doc.air:
            navy = roll.navy
            air = roll.air
            naval_doc = doc.naval
            air_doc = doc.air
            screen_label = navy.screen.name if navy.screen else "— Submarines Only"
            entry += (
                f" | ⚓ {navy.item.name} · {naval_doc.name} "
                f"· Screen: {screen_label} | "
                f"✈️ {air.fighter.name} + {air.bomber.name} + "
                f"{air.specialty.name} · {air_doc.name}"
            )
        lines.append(entry)

    description = "\n".join(lines)
    if len(description) > 4096:
        description = description[:4093] + "..."
    return discord.Embed(title=title, description=description, color=color)

# ==========================================================================
# HOI4 ACHIEVEMENT RANDOMIZER ENGINE (v2.0) — START
# --------------------------------------------------------------------------
# Self-contained engine that rolls ONE IronLegion Commendation achievement
# for a target query (Nation + Ideology + Path + Risk bracket) out of
# achievements.md, using the spec'd 7-level cascading fallback (Levels 0-6)
# so an empty pool can never produce a null return.
#
# Data source: achievements.md (markdown tables, one row per achievement).
# The parser below is pure Python and lives in this file — Apollo Panel
# deploys bot.py.py plus its data files; no external .py modules involved.
#
# Engine API:
#   roll_achievement(nation, ideology, path, risk) -> result dict
#   format_achievement_result(result)              -> spec output text
#   achievement_nations()                          -> concrete nation names
#   achievement_paths_for(nation, ideology)        -> path names for nation
# ==========================================================================

ACHIEVEMENTS_FILE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "achievements.md"
)

# Risk bracket -> allowed commendation point values (spec section 1.A).
ACH_RISK_POINTS: Dict[str, List[int]] = {
    "Cautious": [1, 2],      # Casual, Challenging
    "Dangerous": [2, 3],     # Challenging, Tough
    "Lethal": [4, 5],        # Hardcore, Nightmare
    "Any": [1, 2, 3, 4, 5],  # All tiers
}

ACH_DIFFICULTY_TIERS: Dict[str, int] = {
    "Casual": 1, "Challenging": 2, "Tough": 3, "Hardcore": 4, "Nightmare": 5,
}

ACH_IDEOLOGIES = ["Any", "Democratic", "Fascist", "Communist", "Non-Aligned"]
ACH_RISK_BRACKETS = ["Any", "Cautious", "Dangerous", "Lethal"]

# Alternate spellings users (or the bot's own nation lists, e.g. "U.S.A")
# may use. Values are the canonical names used in achievements.md.
_ACH_NATION_ALIASES: Dict[str, str] = {
    "u.s.a": "united states",
    "usa": "united states",
    "united states of america": "united states",
    "uk": "united kingdom",
    "great britain": "united kingdom",
    "ussr": "soviet union",
    "soviet russia": "soviet union",
    "raj": "british raj",
    "dei": "dutch east indies",
    "congo": "belgian congo",
}

_ACHIEVEMENTS: Optional[List[dict]] = None
_ACHIEVEMENTS_LOCK = threading.Lock()
_ACHIEVEMENTS_LOAD_ERROR: Optional[str] = None


def _ach_norm(value: str) -> str:
    """Collapse whitespace + lowercase — the comparison key for all text fields."""
    return " ".join((value or "").strip().lower().split())


def _ach_nation_key(nation: str) -> str:
    """Canonical comparison key for a nation name (applies user aliases)."""
    return _ACH_NATION_ALIASES.get(_ach_norm(nation), _ach_norm(nation))


def _parse_achievements_md(path: Optional[str] = None) -> List[dict]:
    """Parse achievements.md's IronLegion table rows into achievement dicts.

    Only tables whose header is `Nation | Difficulty | ... | Points` are read
    (the wiki key tables at the top of the file are ignored). Row cells:
    Nation, Difficulty, Ideology, Path, Objective, Description, Native, Points.
    """
    path = path or ACHIEVEMENTS_FILE
    with open(path, encoding="utf-8") as handle:
        lines = handle.read().splitlines()

    rows: List[dict] = []
    in_table = False
    for line in lines:
        stripped = line.strip()
        # Blank lines separate individual rows in this file — they must NOT
        # end the current table. Only non-`|` content lines (section headers,
        # totals, notes) end it.
        if not stripped:
            continue
        if not stripped.startswith("|"):
            in_table = False
            continue
        cells = [cell.strip() for cell in stripped.strip("|").split("|")]
        if (
            len(cells) >= 8
            and cells[0].lower() == "nation"
            and cells[1].lower() == "difficulty"
        ):
            in_table = True
            continue
        if not in_table:
            continue
        # Skip markdown separator rows (|---|---|...) and malformed rows.
        if len(cells) < 8 or set(cells[0]) <= {"-"}:
            continue

        nation_cell = cells[0]
        difficulty = cells[1].strip()
        ideology = cells[2].strip()
        path_cell = cells[3].strip()
        objective_cell = cells[4].strip()
        description = cells[5].strip().strip('"')
        native = cells[6].strip()

        try:
            points = int(cells[7].strip())
        except (ValueError, IndexError):
            points = ACH_DIFFICULTY_TIERS.get(difficulty, 1)
        tier = ACH_DIFFICULTY_TIERS.get(difficulty, points)

        # Objective cell: `**Title** — rest`.
        title = ""
        objective = objective_cell
        match = re.search(r"\*\*(.+?)\*\*", objective_cell)
        if match:
            title = match.group(1).strip()
            rest = objective_cell[match.end():].strip()
            if rest[:1] in ("—", "-"):
                rest = rest[1:].strip()
            objective = rest

        rows.append({
            "nation": nation_cell,                        # raw cell (display)
            "nations": [t.strip() for t in nation_cell.split("/") if t.strip()],
            "wildcard": _ach_norm(nation_cell).startswith("any"),
            "difficulty": difficulty,
            "tier": tier,
            "points": points,
            "ideology": ideology,                         # raw cell (display)
            "ideologies": [x.strip() for x in ideology.split("/") if x.strip()],
            "path": path_cell,                            # raw cell (display)
            "paths": [p.strip() for p in re.split(r"\s+or\s+|/", path_cell) if p.strip()],
            "title": title or objective_cell[:60],
            "objective": objective,
            "description": description,
            "native": native,
        })
    return rows


def _load_achievements(force: bool = False) -> Optional[List[dict]]:
    """Parse achievements.md once and cache the rows (thread-safe)."""
    global _ACHIEVEMENTS, _ACHIEVEMENTS_LOAD_ERROR
    with _ACHIEVEMENTS_LOCK:
        if _ACHIEVEMENTS is not None and not force:
            return _ACHIEVEMENTS
        _ACHIEVEMENTS = None
        _ACHIEVEMENTS_LOAD_ERROR = None
        try:
            _ACHIEVEMENTS = _parse_achievements_md()
        except Exception as exc:
            _ACHIEVEMENTS_LOAD_ERROR = f"{type(exc).__name__}: {exc}"
        return _ACHIEVEMENTS


def _ach_nation_matches(entry: dict, nation: str) -> bool:
    """True when `nation` is one of the entry's playable starting tags.

    Wildcard rows (`Any Chinese nation`, `Any warlord`, ...) never match a
    concrete nation query — they only enter the pool via the Level 6 global
    fallback.
    """
    if entry.get("wildcard"):
        return False
    key = _ach_nation_key(nation)
    return any(_ach_nation_key(tag) == key for tag in entry["nations"])


def _ach_ideology_matches(entry: dict, target: str) -> bool:
    if _ach_norm(target) == "any":
        return True
    wanted = _ach_norm(target)
    for ideology in entry["ideologies"]:
        if _ach_norm(ideology) in ("any", wanted):
            return True
    return False


def _ach_path_matches(
    entry: dict,
    target_path: str,
    ideology_filter_on: bool,
    target_ideology: str,
) -> bool:
    """Path matching incl. `Any X` wildcard paths (e.g. `Any Fascist`).

    `Any Fascist` / `Any Communist` rows are playable with any sub-path of
    that ideology: they match when the ideology filter is active and equals
    X, or when the ideology filter is relaxed (then the path constraint
    effectively vanishes for them).
    """
    if _ach_norm(target_path) == "any":
        return True
    wanted = _ach_norm(target_path)
    for path in entry["paths"]:
        norm = _ach_norm(path)
        if norm == "any":
            return True
        if norm == wanted:
            return True
        if norm.startswith("any "):
            if not ideology_filter_on:
                return True
            if _ach_norm(target_ideology) == norm[4:]:
                return True
    return False


# Cascading fallback ladder (spec section 2). Each level relaxes exactly the
# filters listed; Nation is required at every level 0-5.
_ACH_CASCADE = (
    {"level": 0, "ideology": True,  "path": True,  "risk": True},
    {"level": 1, "ideology": True,  "path": False, "risk": True},
    {"level": 2, "ideology": False, "path": False, "risk": True},
    {"level": 3, "ideology": True,  "path": True,  "risk": False},
    {"level": 4, "ideology": True,  "path": False, "risk": False},
    {"level": 5, "ideology": False, "path": False, "risk": False},
)


def roll_achievement(
    nation: str,
    ideology: str = "Any",
    path: str = "Any",
    risk: str = "Any",
    rng=None,
) -> dict:
    """Roll one achievement for the query using the Level 0-6 cascade.

    Returns a dict with `achievement` (the rolled row), `status`
    (MATCH_SUCCESS | FALLBACK_TRIGGERED), `level` (0-6), `explanation` and
    an echo of the `query`. Never returns None for a successful data load;
    on a load failure the dict carries `error` and `achievement: None`.
    """
    rng = rng or random
    entries = _load_achievements()
    if entries is None:
        return {
            "achievement": None,
            "error": _ACHIEVEMENTS_LOAD_ERROR or "achievements.md could not be loaded.",
            "status": "ERROR",
            "level": -1,
            "explanation": "",
            "query": {"nation": nation, "ideology": ideology, "path": path, "risk": risk},
        }

    target_risk = risk if risk in ACH_RISK_POINTS else "Any"
    risk_points = set(ACH_RISK_POINTS[target_risk])
    target_ideology = ideology if ideology in ACH_IDEOLOGIES else "Any"
    target_path = path or "Any"

    def in_pool(entry: dict, spec: dict) -> bool:
        return (
            _ach_nation_matches(entry, nation)
            and (not spec["ideology"] or _ach_ideology_matches(entry, target_ideology))
            and (
                not spec["path"]
                or _ach_path_matches(entry, target_path, spec["ideology"], target_ideology)
            )
            and (not spec["risk"] or entry["points"] in risk_points)
        )

    for spec in _ACH_CASCADE:
        pool = [entry for entry in entries if in_pool(entry, spec)]
        if pool:
            return _build_achievement_result(
                pool, spec["level"], nation, target_ideology, target_path, target_risk, rng
            )

    # Level 6: the nation has no achievements mapped at all — fall back to
    # the global pool of the requested risk bracket across all nations.
    global_pool = [entry for entry in entries if entry["points"] in risk_points]
    if not global_pool:
        # Defensive only: every bracket exists in the shipped dataset.
        global_pool = entries
    return _build_achievement_result(
        global_pool, 6, nation, target_ideology, target_path, target_risk, rng
    )


def _build_achievement_result(
    pool: List[dict],
    level: int,
    nation: str,
    ideology: str,
    path: str,
    risk: str,
    rng,
) -> dict:
    chosen = rng.choice(pool)
    status = "MATCH_SUCCESS" if level == 0 else "FALLBACK_TRIGGERED"
    return {
        "achievement": chosen,
        "status": status,
        "level": level,
        "explanation": _ach_fallback_explanation(level, nation, ideology, path, risk),
        "pool_size": len(pool),
        "query": {"nation": nation, "ideology": ideology, "path": path, "risk": risk},
    }


def _ach_fallback_explanation(
    level: int, nation: str, ideology: str, path: str, risk: str
) -> str:
    pts = "/".join(str(p) for p in ACH_RISK_POINTS.get(risk, [1, 2, 3, 4, 5]))
    if level == 0:
        return "Full match — no filters were relaxed."
    if level == 1:
        return (
            f"No {risk} ({pts} pt) achievements exist for Path=`{path}`; "
            f"expanded search to Path: Any (Level 1)."
        )
    if level == 2:
        return (
            f"No {risk} ({pts} pt) achievements exist for Ideology=`{ideology}`; "
            f"expanded search to Ideology: Any and Path: Any (Level 2)."
        )
    if level == 3:
        return (
            f"No {risk} ({pts} pt) achievements exist for Ideology=`{ideology}`, "
            f"Path=`{path}`; expanded search to Risk: Any (Level 3)."
        )
    if level == 4:
        return (
            f"No {risk} ({pts} pt) achievements exist for Ideology=`{ideology}`; "
            f"expanded search to Risk: Any and Path: Any (Level 4)."
        )
    if level == 5:
        return (
            f"No matching achievement was found under the strict filters; "
            f"rolled from Nation=`{nation}`'s full pool (any Ideology, Path or Risk) (Level 5)."
        )
    return (
        f"Nation=`{nation}` has no achievements mapped; fell back to the global "
        f"{risk} ({pts} pt) pool across all nations (Level 6)."
    )


def format_achievement_result(result: dict) -> str:
    """Render the spec-required output blocks as plain markdown text."""
    if result.get("error"):
        return f"❌ Achievement engine error: {result['error']}"
    achievement_row = result["achievement"]
    query = result["query"]
    points_label = "Point" if achievement_row["points"] == 1 else "Points"
    lines = [
        "### 🎲 Achievement Roll Result",
        "",
        f"- **Achievement Title**: {achievement_row['title']}",
        f"- **Nation**: {achievement_row['nation']}",
        f"- **Target Ideology**: {achievement_row['ideology']}",
        f"- **Sub-Path**: {achievement_row['path']}",
        f"- **Difficulty & Points**: Tier {achievement_row['tier']} "
        f"({achievement_row['difficulty']}) — {achievement_row['points']} "
        f"Commendation {points_label}",
        f"- **Objective / Requirements**: {achievement_row['objective']}",
        "",
        "### ⚙️ Engine Fallback Telemetry",
        "",
        f"- **Target Query**: Nation=`{query['nation']}` | Ideology=`{query['ideology']}` | "
        f"Path=`{query['path']}` | Risk=`{query['risk']}`",
        f"- **Execution Status**: `{result['status']}`",
        f"- **Cascade Level Reached**: Level {result['level']}",
        f"- **Fallback Explanation**: {result['explanation']}",
    ]
    return "\n".join(lines)


def achievement_nations() -> List[str]:
    """Distinct concrete nation names in achievements.md (wildcards excluded)."""
    entries = _load_achievements() or []
    seen = set()
    nations = []
    for entry in entries:
        if entry.get("wildcard"):
            continue
        for tag in entry["nations"]:
            key = _ach_nation_key(tag)
            if key in seen:
                continue
            seen.add(key)
            nations.append(tag)
    return sorted(nations, key=str.lower)


def achievement_paths_for(nation: str, ideology: str = "Any") -> List[str]:
    """Distinct path names available for a nation (optionally ideology-filtered)."""
    entries = _load_achievements() or []
    paths = set()
    for entry in entries:
        if not _ach_nation_matches(entry, nation):
            continue
        if _ach_norm(ideology) != "any" and not _ach_ideology_matches(entry, ideology):
            continue
        paths.update(entry["paths"])
    return sorted(paths, key=str.lower)

