# Map the various ideology spellings/typos in the raw block to the canonical
# ideology NAME used by RANDOMIZER_DATA["Ideologies"].
_PATH_IDEOLOGY_MAP = {
    "communist": "Communism", "communism": "Communism", "commmunist": "Communism",
    "democratic": "Democracy", "democracy": "Democracy",
    "fascist": "Fascism", "fascism": "Fascism",
    "non-aligned": "Non-Aligned", "nonaligned": "Non-Aligned", "non aligned": "Non-Aligned",
}


def _canon_path_key(name: str) -> str:
    """Canonical lookup key so file spellings and bot nation names match
    (e.g. 'USA'/'U.S.A', 'UK'/'United Kingdom', 'Germany (Vanilla Tree)'/'Germany')."""
    if not name:
        return ""
    n = re.sub(r"\s*\(vanilla tree\)\s*", "", str(name), flags=re.I).strip()
    n = {"uk": "united kingdom", "usa": "u.s.a"}.get(n.lower(), n)
    return re.sub(r"[^a-z0-9]", "", n.lower())


def _normalize_path_ideology(token: str):
    return _PATH_IDEOLOGY_MAP.get((token or "").strip().strip("()").strip().lower())


def _parse_path_line(line: str):
    """Return (path_name, [ideologies]) from a raw path line, tolerating
    missing/extra parens and dual 'A/B' ideologies. [] if unresolvable."""
    idx = line.rfind("(")
    if idx == -1:
        return line.strip(), []
    name = line[:idx].strip().rstrip("(").strip()
    ideo_str = line[idx + 1:].strip().rstrip(")")
    ideos = []
    for tok in ideo_str.split("/"):
        norm = _normalize_path_ideology(tok)
        if norm and norm not in ideos:
            ideos.append(norm)
    return name, ideos


def _parse_random_paths(raw: str) -> dict:
    """Parse the raw block into {canon_nation_key: [{'name','ideologies'}, ...]}."""
    data: dict = {}
    current_key = None
    for line in raw.splitlines():
        s = line.strip()
        if not s:
            current_key = None
            continue
        if current_key is None:
            current_key = _canon_path_key(s)
            data.setdefault(current_key, [])
            continue
        name, ideos = _parse_path_line(s)
        if name and ideos:
            data[current_key].append({"name": name, "ideologies": ideos})
    return data


PATHS_DATA = _parse_random_paths(_RANDOM_PATHS_RAW)


def _paths_for_nation(nation: str) -> list:
    """All parsed paths for a nation (empty list if the nation has no path data)."""
    return PATHS_DATA.get(_canon_path_key(nation), [])


def _roll_random_path(nation: str, ideology_name: str = None, exclude_name: str = None):
    """Pick a random path for a nation. If ``ideology_name`` is given, only
    paths matching that ideology are eligible (keeps Path consistent with
    Ideology). If ``exclude_name`` is given, that path is avoided as long as
    at least one other option remains — used so a re-roll/re-gamble for the
    same nation doesn't hand the player the identical path twice in a row.
    Returns a path dict {'name','ideologies'} or None."""
    paths = _paths_for_nation(nation)
    if not paths:
        return None
    if ideology_name:
        matching = [p for p in paths if ideology_name in p["ideologies"]]
        if not matching:
            return None
    else:
        matching = paths
    if exclude_name:
        filtered = [p for p in matching if p["name"] != exclude_name]
        if filtered:
            matching = filtered
    return random.choice(matching)


def _roll_random_ideology(exclude_name: str = None):
    """Pick a random ideology, avoiding ``exclude_name`` as long as at least
    one other option remains — same no-repeat guarantee as _roll_random_path,
    for nations/games that roll Ideology independently of Path."""
    pool = RANDOMIZER_DATA["Ideologies"]
    if exclude_name:
        filtered = [i for i in pool if i[0] != exclude_name]
        if filtered:
            pool = filtered
    return random.choice(pool)


def _ideology_tuple(name: str):
    """(name, emoji) tuple from RANDOMIZER_DATA for an ideology name."""
    for t in RANDOMIZER_DATA["Ideologies"]:
        if t[0] == name:
            return t
    return (name, "🏳️")


_EMERGENCY_UNRESERVE_DENIAL = (
    "❌ **Denied:** You previously used Emergency Unreserve and cannot reserve "
    "another nation in this game."
)


def _is_emergency_unreserved_blocked(game: dict, user_id) -> bool:
    """True when the player used the Emergency Unreserve panel for THIS game
    and is permanently blocked from self-service re-reserving.

    ANTI-EXPLOIT: without this check the Emergency Unreserve panel + a fresh
    /gamble (or /draw / /reserve) link would grant infinite fresh
    rolls. Host-initiated re-add paths (/gamble_for, /draw_for, host override
    panel) intentionally bypass this — they are the documented way a removed
    player gets back on the list."""
    blocked = game.get("randomizer_unreserved")
    if not isinstance(blocked, (list, set, tuple)):
        return False
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        uid = None
    for entry in blocked:
        if entry == user_id:
            return True
        if uid is not None and entry == uid:
            return True
        if str(entry) == str(user_id):
            return True
    return False


class RandomizerUnreserveModal(discord.ui.Modal, title="Emergency Unreserve"):
    reason = discord.ui.TextInput(
        label="Reason for removal?",
        style=discord.TextStyle.long,
        placeholder="I have a real life emergency and can't make it...",
        required=True,
        max_length=300
    )

    def __init__(self, thread_id: int, reserved_nation: str, is_major: bool):
        super().__init__()
        self.thread_id = thread_id
        self.reserved_nation = reserved_nation
        self.is_major = is_major

    async def on_submit(self, interaction: discord.Interaction):
        games_data = await read_json(GAMES_FILE)
        game = games_data.get(str(self.thread_id))

        if not game:
            return await interaction.response.send_message("❌ Game not found.", ephemeral=True)

        # Remove player from the active reservation list
        if self.reserved_nation in game["reservations"]:
            del game["reservations"][self.reserved_nation]

        user_id = interaction.user.id

        if game.get("fortunes_only", False):
            _clear_fortunes_player_state(game, user_id)

        # Emergency Unreserve always permanently blocks re-reserving — for randomizer
        # games, a player who just wants a different roll should use the "Do you wish to
        # re-roll?" Yes/No buttons attached to their /gamble result instead (governed by
        # this game's Competitive/Casual re-roll allowance). This panel is only for players
        # leaving the game entirely. They can only get back on the list via /gamble_for or
        # /draw_for (host override).
        if "randomizer_unreserved" not in game:
            game["randomizer_unreserved"] = []
        if user_id not in game["randomizer_unreserved"]:
            game["randomizer_unreserved"].append(user_id)

        await write_json(GAMES_FILE, games_data)

        # MIRROR TO MYSQL IMMEDIATELY — games.game_data carries
        # `randomizer_unreserved` (the web /api/access gate enforces it), and
        # the reservation rewrite removes the player's game_reservations row
        # so a stale receipt link can never re-lock them into a run.
        try:
            await save_single_game(str(self.thread_id), game, rewrite_reservations=True)
        except Exception as mirror_err:
            print(f"[WARN] emergency unreserve MySQL mirror failed: {mirror_err}")

        # Update the public lobby board automatically
        try: schedule_reservation_update(self.thread_id)
        except: pass

        # Phase 3: flip the receipt log embed to red [UNRESERVED / LEGACY ROLL].
        await _mark_receipt_log_unreserved(self.thread_id, user_id)

        # Clear the player's web run state so a future /gamble_for (host
        # re-gamble) starts clean instead of bouncing to the old FINALIZED
        # receipt.
        await _run_mysql_io(
            _purge_web_session_mysql, str(self.thread_id), user_id,
            label="web session purge (emergency unreserve)",
        )

        if game.get("fortunes_only", False):
            try:
                await _update_fortunes_script_message(str(self.thread_id))
            except Exception:
                pass

        # --- LOG THE REASON TO HOST CHANNEL (route to add-on's channel) ---
        log_channel_id = FORTUNES_LOG_CHANNEL_ID if game.get("fortunes_only", False) else RANDOMIZER_LOG_CHANNEL_ID
        log_channel = interaction.client.get_channel(log_channel_id)
        if not log_channel:
            try: log_channel = await interaction.client.fetch_channel(log_channel_id)
            except: pass

        if log_channel:
            log_embed = discord.Embed(title="🚨 Emergency Unreserve", color=0xe74c3c)
            log_embed.add_field(name="Player", value=f"<@{user_id}>", inline=True)
            log_embed.add_field(name="Nation", value=f"{self.reserved_nation} ({'Major' if self.is_major else 'Minor'})", inline=True)
            log_embed.add_field(name="Reason", value=self.reason.value, inline=False)
            await log_channel.send(embed=log_embed)

        await interaction.response.send_message(f"✅ You have been successfully removed from **{self.reserved_nation}**.", ephemeral=True)


class RandomizerUnreserveView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None) # Timeout=None makes it a permanent button!

    @discord.ui.button(label="Emergency Unreserve", style=discord.ButtonStyle.danger, emoji="🚨", custom_id="btn_randomizer_unreserve")
    async def btn_unreserve(self, interaction: discord.Interaction, button: discord.ui.Button):
        games_data = await read_json(GAMES_FILE)
        game = games_data.get(str(interaction.channel.id))

        if not game:
            return await interaction.response.send_message("❌ Game not found.", ephemeral=True)

        user_id = interaction.user.id
        reservations = game.get("reservations", {})

        # Scan what nation they actually own (string-tolerant id match)
        reserved_nation = None
        for nat, uid in reservations.items():
            if str(uid) == str(user_id):
                reserved_nation = nat
                break

        if not reserved_nation:
            return await interaction.response.send_message("❌ You do not have a reservation in this game to remove!", ephemeral=True)

        # Detect if their nation was a Major
        mode = game.get("mode", "")
        major_nations = []
        try: major_nations = get_major_nations_for_mode(mode)
        except: pass

        is_major = reserved_nation in major_nations

        # Open the popup form
        await interaction.response.send_modal(RandomizerUnreserveModal(interaction.channel.id, reserved_nation, is_major))


_locks = {}
log_update_lock = asyncio.Lock()
_games_cache = {}

def _get_lock(filename):
    if filename not in _locks: _locks[filename] = asyncio.Lock()
    return _locks[filename]


async def _acquire_file_lock(filename, timeout: float = _FILE_LOCK_TIMEOUT):
    """Acquire a file/DB serialisation lock with a hard timeout so commands cannot
    sit on 'thinking...' forever when MySQL I/O is wedged behind the lock."""
    lock = _get_lock(filename)
    try:
        await asyncio.wait_for(lock.acquire(), timeout=timeout)
    except asyncio.TimeoutError:
        name = os.path.basename(filename)
        raise TimeoutError(
            f"Timed out waiting for {name} lock — a previous MySQL operation is likely stuck. "
            f"Restart the bot if this keeps happening."
        )
    return lock

def get_cached_games_data() -> dict:
    """Instant read of the current server's games (no lock / DB I/O)."""
    return _games_view()


def _all_games() -> dict:
    """Every server's games (thread id → game). Most code wants only the
    current server's: read_json(GAMES_FILE) / get_cached_games_data()."""
    return _games_cache if isinstance(_games_cache, dict) else {}


def _games_view(games: dict | None = None, gid=None) -> dict:
    """The games of one server (the current one by default) — same game dicts
    as the shared map, so changing a game changes it everywhere."""
    g = _as_gid(gid if gid is not None else cur_gid())
    source = _all_games() if games is None else games
    return {tid: game for tid, game in source.items() if isinstance(game, dict) and _as_gid(game.get("guild_id")) == g}


def _merge_games_view(view) -> dict:
    """Write one server's games back into the shared map (in place): games of
    this server missing from the view were removed, the rest are kept."""
    cache = _all_games()
    if view is cache or view is None:
        return cache
    g = cur_gid()
    for tid in [t for t, game in cache.items() if isinstance(game, dict) and _as_gid(game.get("guild_id")) == g and t not in view]:
        cache.pop(tid, None)
    for tid, game in view.items():
        if isinstance(game, dict):
            game.setdefault("guild_id", str(g))
        cache[tid] = game
    return cache


def _item_gid(item) -> int:
    """The server of a schedule slot / day lock (older ones: the home server)."""
    return _as_gid((item or {}).get("guild_id")) if isinstance(item, dict) else GUILD_ID


def _list_view(items, gid=None) -> list:
    g = _as_gid(gid if gid is not None else cur_gid())
    return [item for item in (items or []) if isinstance(item, dict) and _item_gid(item) == g]


def _merge_list_view(shared: list, view) -> list:
    """Write one server's slots / locks back into a shared list (in place)."""
    if view is shared or view is None:
        return shared
    g = cur_gid()
    mine = [item for item in view if isinstance(item, dict)]
    for item in mine:
        item.setdefault("guild_id", str(g))
    shared[:] = [item for item in shared if not (isinstance(item, dict) and _item_gid(item) == g)] + mine
    return shared

def _set_games_cache(data: dict):
    global _games_cache
    _games_cache = data


def _parse_mysql_json(value):
    """Normalize MySQL JSON column values to Python objects."""
    if value is None:
        return {}
    if isinstance(value, (bytes, bytearray)):
        value = value.decode("utf-8")
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return {}
    if isinstance(value, dict):
        return value
    return {}


def _parse_mysql_json_list(value):
    """Like _parse_mysql_json but for JSON array columns (e.g. host history)."""
    if value is None:
        return []
    if isinstance(value, (bytes, bytearray)):
        value = value.decode("utf-8")
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return parsed if isinstance(parsed, list) else []
        except Exception:
            return []
    if isinstance(value, list):
        return value
    return []


def _parse_mysql_json_obj(value):
    """Like _parse_mysql_json_list but for JSON object columns (e.g. dishonored_data)."""
    if value is None:
        return {}
    if isinstance(value, (bytes, bytearray)):
        value = value.decode("utf-8")
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    if isinstance(value, dict):
        return value
    return {}


def _game_row_to_dict(row: dict, reservations: dict | None = None) -> dict:
    """Rebuild the legacy in-memory game dict from a MySQL games row."""
    game = _parse_mysql_json(row.get("game_data"))
    if not isinstance(game, dict):
        game = {}
    game["mode"] = row.get("mode") or game.get("mode") or "Unknown"
    game["host_id"] = int(row["host_id"]) if row.get("host_id") is not None else game.get("host_id", 0)
    if row.get("status") is not None:
        game["status"] = row["status"]
    elif "status" not in game:
        game["status"] = None
    if row.get("thread_name") is not None:
        game["thread_name"] = row["thread_name"]
    game["game_started"] = bool(row["game_started"]) if row.get("game_started") is not None else bool(game.get("game_started"))
    if row.get("start_timestamp") is not None:
        game["start_timestamp"] = int(row["start_timestamp"])
    if row.get("announcement_message_id") is not None:
        game["announcement_message_id"] = int(row["announcement_message_id"])
    if row.get("announcement_channel_id") is not None:
        game["announcement_channel_id"] = int(row["announcement_channel_id"])
    game["thread_id"] = str(row.get("thread_id") or game.get("thread_id") or "")
    try:
        game["reservations_rev"] = int(row.get("reservations_rev") or 0)
    except (TypeError, ValueError):
        game["reservations_rev"] = 0
    game["reservations"] = reservations if reservations is not None else game.get("reservations", {})
    # The server the game belongs to (column; older games: the home server).
    game["guild_id"] = str(row.get("guild_id") or game.get("guild_id") or GUILD_ID)
    return game


def _split_game_for_mysql(thread_id: str, game: dict) -> tuple[tuple, list[tuple]]:
    """Split a legacy game dict into a games row + reservation rows."""
    reservations = game.get("reservations") or {}
    if not isinstance(reservations, dict):
        reservations = {}
    payload = {k: v for k, v in game.items() if k not in ("reservations", "reservations_rev")}
    payload.setdefault("thread_id", str(thread_id))

    def _as_int(value, default=None):
        if value is None:
            return default
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    try:
        rev = int(game.get("reservations_rev") or 0)
    except (TypeError, ValueError):
        rev = 0

    row = (
        str(thread_id),
        str(game.get("mode") or "Unknown")[:128],
        _as_int(game.get("host_id"), 0) or 0,
        (str(game["status"])[:32] if game.get("status") is not None else None),
        (str(game["thread_name"])[:255] if game.get("thread_name") is not None else None),
        1 if game.get("game_started") else 0,
        _as_int(game.get("start_timestamp")),
        _as_int(game.get("announcement_message_id")),
        _as_int(game.get("announcement_channel_id")),
        rev,
        json.dumps(payload, ensure_ascii=False),
        str(game.setdefault("guild_id", str(cur_gid()))),
    )
    res_rows = []
    for slot_key, user_id in reservations.items():
        uid = _as_int(user_id)
        if uid is None:
            continue
        res_rows.append((str(thread_id), str(slot_key)[:128], uid))
    return row, res_rows


_STICKY_GAME_FIELDS = (
    "host_panel_thread_id",
    "host_panel_message_id",
    "lobby_thread_id",
    "original_thread_id",
    "participation_tracker_msg_ids",
    "participation_tracker_msg_id",
    "public_log_msg_ids",
    "public_log_message_id",
    # Single-message Public Archive refactor: one post per game, edited forever.
    "archive_message_id",
    "feedback_merit_awarded",
    "game_action_counts",
)


def _preserve_sticky_game_fields(incoming: dict, existing: dict | None) -> dict:
    """Keep Host Control Center / lobby IDs if a stale save omitted them."""
    if not isinstance(incoming, dict) or not isinstance(existing, dict):
        return incoming
    for key in _STICKY_GAME_FIELDS:
        if incoming.get(key) in (None, "", [], {}):
            prior = existing.get(key)
            if prior not in (None, "", [], {}):
                incoming[key] = prior
    _merge_game_moderation_fields(incoming, existing)
    _merge_public_archive_ids(incoming, existing)
    _merge_feedback_refs(incoming, existing)
    return incoming


def _merge_feedback_refs(incoming: dict, existing: dict) -> None:
    """Keep the live feedback poll id, and never let a stale save un-archive it.

    A lost id made /game_end post a second poll. Archiving both copies is what
    left two feedback messages in the host log.
    """
    if existing.get("feedback_archived"):
        incoming["feedback_archived"] = True
        if existing.get("feedback_archived_at") and not incoming.get("feedback_archived_at"):
            incoming["feedback_archived_at"] = existing["feedback_archived_at"]
    ids: list[str] = []
    seen: set[str] = set()
    for src in (existing, incoming):
        raw_ids = list(src.get("feedback_message_ids") or [])
        raw_ids.append(src.get("feedback_message_id"))
        for raw in raw_ids:
            text = str(raw or "").strip()
            if text.isdigit() and text not in seen:
                seen.add(text)
                ids.append(text)
    if ids:
        incoming["feedback_message_ids"] = ids
        if not str(incoming.get("feedback_message_id") or "").strip().isdigit():
            incoming["feedback_message_id"] = ids[-1]
    if not incoming.get("feedback_channel_id") and existing.get("feedback_channel_id"):
        incoming["feedback_channel_id"] = existing["feedback_channel_id"]


def _normalize_public_log_ids(raw) -> list[str]:
    ids = []
    seen = set()
    values = raw if isinstance(raw, (list, tuple)) else [raw]
    for item in values:
        text = str(item or "").strip()
        if text.isdigit() and text not in seen:
            seen.add(text)
            ids.append(text)
    return ids


def _merge_public_archive_ids(incoming: dict, existing: dict) -> None:
    """Keep the ordered archive-message list. A stale save that only kept the
    last chunk ID used to drop the first-half message so later edits missed it.
    """
    inc = _normalize_public_log_ids(incoming.get("public_log_msg_ids"))
    exc = _normalize_public_log_ids(existing.get("public_log_msg_ids"))
    primary = None
    for candidate in (
        incoming.get("public_log_message_id"),
        existing.get("public_log_message_id"),
    ):
        text = str(candidate or "").strip()
        if text.isdigit():
            primary = text
            break
    merged = inc or list(exc)
    # Stale write kept only the 2nd+ chunk IDs; put the missing prefix back.
    if exc and inc and len(inc) < len(exc) and exc[-len(inc):] == inc:
        merged = list(exc)
    elif not inc and exc:
        merged = list(exc)
    if primary and merged and primary not in merged:
        # Never put a later-chunk ID in front of an already-ordered list.
        if not (len(merged) > 1 and primary == merged[-1]):
            merged = [primary] + merged
    elif primary and not merged:
        merged = [primary]
    if merged:
        incoming["public_log_msg_ids"] = merged
        incoming["public_log_message_id"] = merged[0]
    # Single-message archive refactor: never let a stale bulk save drop the
    # archive_message_id the game started with.
    arch = incoming.get("archive_message_id") or existing.get("archive_message_id")
    if arch:
        incoming["archive_message_id"] = str(arch)
    elif merged:
        incoming["archive_message_id"] = merged[0]


def _merge_game_moderation_fields(incoming: dict, existing: dict) -> None:
    """Union per-game merit/moderation so a vote save can't wipe a /give, or vice versa."""
    a = {str(x) for x in (incoming.get("feedback_merit_awarded") or []) if str(x).isdigit()}
    b = {str(x) for x in (existing.get("feedback_merit_awarded") or []) if str(x).isdigit()}
    if a or b:
        incoming["feedback_merit_awarded"] = list(a | b)

    dst = incoming.get("game_action_counts")
    src = existing.get("game_action_counts")
    if not isinstance(src, dict):
        return
    if not isinstance(dst, dict):
        incoming["game_action_counts"] = dict(src)
        return
    for uid, actions in src.items():
        if not isinstance(actions, dict):
            continue
        key = str(uid)
        bucket = dst.setdefault(key, {})
        if not isinstance(bucket, dict):
            dst[key] = dict(actions)
            continue
        for action, value in actions.items():
            if action not in bucket:
                bucket[action] = value


def _fetch_all_games_mysql() -> dict:
    """Load every game + reservation into the legacy {thread_id: game} map."""
    conn = None
    cursor = None
    try:
        conn = _db_get_connection()
        cursor = conn.cursor(dictionary=True)
        cursor.execute("SELECT * FROM games")
        game_rows = cursor.fetchall()
        cursor.execute("SELECT thread_id, slot_key, user_id FROM game_reservations")
        res_by_thread: dict[str, dict] = {}
        for r in cursor.fetchall():
            tid = str(r["thread_id"])
            bucket = res_by_thread.setdefault(tid, {})
            bucket[str(r["slot_key"])] = int(r["user_id"])
        out = {}
        for row in game_rows:
            tid = str(row["thread_id"])
            out[tid] = _game_row_to_dict(row, res_by_thread.get(tid, {}))
        return out
    except Exception as e:
        print(f"⚠️ Error bulk reading games from MySQL: {e}")
        return {}
    finally:
        if cursor is not None:
            cursor.close()
        if conn is not None:
            conn.close()


def _save_all_games_mysql(games_dict: dict):
    """Persist the full games map to MySQL (games + reservations)."""
    conn = None
    cursor = None
    try:
        conn = _db_get_connection()
        cursor = conn.cursor()
        conn.start_transaction()
        upsert = """
            INSERT INTO games (
                thread_id, mode, host_id, status, thread_name, game_started,
                start_timestamp, announcement_message_id, announcement_channel_id,
                reservations_rev, game_data, guild_id
            ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            ON DUPLICATE KEY UPDATE
                guild_id = VALUES(guild_id),
                mode = VALUES(mode),
                host_id = VALUES(host_id),
                status = VALUES(status),
                thread_name = VALUES(thread_name),
                game_started = VALUES(game_started),
                start_timestamp = VALUES(start_timestamp),
                announcement_message_id = VALUES(announcement_message_id),
                announcement_channel_id = VALUES(announcement_channel_id),
                reservations_rev = VALUES(reservations_rev),
                game_data = VALUES(game_data)
        """
        game_rows = []
        res_rows = []
        thread_ids = []
        for tid, game in (games_dict or {}).items():
            if not isinstance(game, dict):
                continue
            thread_ids.append(str(tid))
            row, rrows = _split_game_for_mysql(str(tid), game)
            game_rows.append(row)
            res_rows.extend(rrows)

        # Refuse empty wipes — that used to happen when games.json got corrupted to {}.
        if not thread_ids:
            print("⚠️ Refusing to wipe MySQL games tables with an empty in-memory map")
            conn.rollback()
            return

        # Stale-cache guard: lock rows and skip reservation rewrites when MySQL
        # already has a newer reservations_rev from _commit_reservation_mysql.
        cursor.execute(
            f"SELECT thread_id, reservations_rev, game_data FROM games WHERE thread_id IN ({','.join(['%s'] * len(thread_ids))}) FOR UPDATE",
            thread_ids,
        )
        db_meta = {}
        for r in cursor.fetchall():
            db_meta[str(r[0])] = (int(r[1] or 0), r[2])

        skip_res_threads = set()
        filtered_game_rows = []
        for row in game_rows:
            tid = str(row[0])
            cache_rev = int(row[9] or 0)
            db_rev, db_game_data = db_meta.get(tid, (0, None))
            if tid in (games_dict or {}) and isinstance(games_dict[tid], dict) and db_game_data is not None:
                _preserve_sticky_game_fields(games_dict[tid], _parse_mysql_json(db_game_data))
                row, _rrows = _split_game_for_mysql(tid, games_dict[tid])
            if cache_rev < db_rev:
                # Keep the DB revision; still write metadata + game_data.
                row = row[:9] + (db_rev,) + row[10:]
                skip_res_threads.add(tid)
                if tid in (games_dict or {}):
                    games_dict[tid]["reservations_rev"] = db_rev
            filtered_game_rows.append(row)

        if filtered_game_rows:
            cursor.executemany(upsert, filtered_game_rows)

        placeholders = ",".join(["%s"] * len(thread_ids))
        # Delete orphaned games (e.g. host-panel thread migration via pop()).
        cursor.execute(
            f"DELETE FROM games WHERE thread_id NOT IN ({placeholders})",
            thread_ids,
        )

        rewrite_ids = [tid for tid in thread_ids if tid not in skip_res_threads]
        if rewrite_ids:
            rh = ",".join(["%s"] * len(rewrite_ids))
            # Preserve receipt log message ids AND the web re-roll budget
            # (`rerolls_used`) across the rewrite — dropping it would reset
            # the casino wheel's re-roll counter mid-session.
            cursor.execute(
                f"SELECT thread_id, slot_key, user_id, log_message_id, rerolls_used FROM game_reservations WHERE thread_id IN ({rh})",
                rewrite_ids,
            )
            preserved_meta = {}
            for r in cursor.fetchall():
                preserved_meta[(str(r[0]), str(r[1]), int(r[2]))] = (
                    int(r[3]) if r[3] is not None else None,
                    int(r[4] or 0),
                )
            cursor.execute(
                f"DELETE FROM game_reservations WHERE thread_id IN ({rh})",
                rewrite_ids,
            )
            kept_res = []
            for r in res_rows:
                if r[0] in skip_res_threads:
                    continue
                tid_r, slot_r, uid_r = str(r[0]), str(r[1]), int(r[2])
                log_id, rerolls_used = preserved_meta.get(
                    (tid_r, slot_r, uid_r), (None, 0)
                )
                kept_res.append((tid_r, slot_r, uid_r, log_id, rerolls_used))
            if kept_res:
                cursor.executemany(
                    "INSERT INTO game_reservations (thread_id, slot_key, user_id, log_message_id, rerolls_used) VALUES (%s, %s, %s, %s, %s)",
                    kept_res,
                )
            # Intentional reservation rewrite wins over concurrent atomic inserts
            # that raced between cache load and this save; bump so losers can detect.
            cursor.execute(
                f"UPDATE games SET reservations_rev = reservations_rev + 1 WHERE thread_id IN ({rh})",
                rewrite_ids,
            )
            cursor.execute(
                f"SELECT thread_id, reservations_rev FROM games WHERE thread_id IN ({rh})",
                rewrite_ids,
            )
            for tid, rev in cursor.fetchall():
                tid = str(tid)
                if tid in (games_dict or {}) and isinstance(games_dict[tid], dict):
                    games_dict[tid]["reservations_rev"] = int(rev or 0)

        # If we skipped reservation rewrites (newer DB rev), pull the truth into
        # the caller's map so _set_games_cache doesn't keep a stale snapshot.
        if skip_res_threads:
            sh = ",".join(["%s"] * len(skip_res_threads))
            cursor.execute(
                f"SELECT thread_id, slot_key, user_id FROM game_reservations WHERE thread_id IN ({sh})",
                list(skip_res_threads),
            )
            refreshed: dict[str, dict] = {tid: {} for tid in skip_res_threads}
            for r in cursor.fetchall():
                refreshed[str(r[0])][str(r[1])] = int(r[2])
            for tid, res in refreshed.items():
                if tid in (games_dict or {}) and isinstance(games_dict[tid], dict):
                    games_dict[tid]["reservations"] = res
        conn.commit()
    except Exception as e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print(f"⚠️ Error bulk saving games to MySQL: {e}")
    finally:
        if cursor is not None:
            cursor.close()
        if conn is not None:
            conn.close()


def _fetch_all_schedule_mysql() -> list:
    """Load every schedule slot from MySQL into the legacy list-of-dicts shape."""
    conn = None
