def _fetch_bot_config_mysql() -> dict:
    """Load the bot_config key/value table into a plain dict."""
    conn = None
    cursor = None
    try:
        conn = _db_get_connection()
        cursor = conn.cursor(dictionary=True)
        cursor.execute("SELECT config_key, config_value FROM bot_config")
        out = {}
        for row in cursor.fetchall():
            raw = row["config_value"]
            if raw is None:
                out[row["config_key"]] = None
                continue
            try:
                out[row["config_key"]] = json.loads(raw)
            except Exception:
                out[row["config_key"]] = raw
        return out
    except Exception as e:
        print(f"⚠️ Error bulk reading bot config from MySQL: {e}")
        return {}
    finally:
        if cursor is not None:
            cursor.close()
        if conn is not None:
            conn.close()


