# Every bot_config key: the home server's keys as they always were, plus one
# "guild:<id>" entry per other server holding that server's keys.
_BOT_CONFIG_ALL: dict = {}
_BOT_CONFIG_LOADED = False


def _bot_config_section_key(gid=None) -> str | None:
    gid = _as_gid(gid if gid is not None else cur_gid())
    return None if gid == GUILD_ID else f"guild:{gid}"


class _BotConfigView(collections.abc.MutableMapping):
    """bot_config as the current server sees it."""

    def _d(self) -> dict:
        key = _bot_config_section_key()
        if key is None:
            return _BOT_CONFIG_ALL
        section = _BOT_CONFIG_ALL.get(key)
        if not isinstance(section, dict):
            section = _BOT_CONFIG_ALL[key] = {}
        return section

    def __getitem__(self, key):
        return self._d()[key]

    def __setitem__(self, key, value):
        self._d()[key] = value

    def __delitem__(self, key):
        del self._d()[key]

    def __iter__(self):
        return iter(self._d())

    def __len__(self):
        return len(self._d())

    def __contains__(self, key):
        return key in self._d()

    def get(self, key, default=None):
        return self._d().get(key, default)


_bot_config_cache = _BotConfigView()


def _bot_config_load_all(data: dict) -> None:
    """Every key read from MySQL (startup / first read)."""
    global _BOT_CONFIG_LOADED
    _BOT_CONFIG_ALL.clear()
    _BOT_CONFIG_ALL.update(data or {})
    _BOT_CONFIG_LOADED = True


def _set_bot_config_cache(data: dict):
    """The current server's keys after a write (the view itself, or a dict)."""
    if data is _bot_config_cache or data is _BOT_CONFIG_ALL:
        return
    key = _bot_config_section_key()
    if key is None:
        sections = {k: v for k, v in _BOT_CONFIG_ALL.items() if str(k).startswith("guild:")}
        _BOT_CONFIG_ALL.clear()
        _BOT_CONFIG_ALL.update({k: v for k, v in dict(data or {}).items() if not str(k).startswith("guild:")})
        _BOT_CONFIG_ALL.update(sections)
    else:
        _BOT_CONFIG_ALL[key] = dict(data or {})


