# Dedicated thread pool for autocomplete — never queue behind MySQL bulk reads.
_AUTOCOMPLETE_EXECUTOR = concurrent.futures.ThreadPoolExecutor(
    max_workers=8, thread_name_prefix="ac"
)
_AUTOCOMPLETE_TIMEOUT = 2.5
_AUDIT_SLOW_CMD_SEC = 2.0
_AUDIT_SLOW_AC_SEC = 0.5


def _audit_log(level: str, msg: str):
    ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    print(f"[BOT-AUDIT {level}] {ts} | {msg}")


def _normalize_ac_current(current: str) -> str:
    """Treat whitespace-only input (e.g. pressing space) as empty — show all options."""
    return (current or "").strip()


async def _defer_ephemeral(interaction: discord.Interaction):
    if not interaction.response.is_done():
        await interaction.response.defer(ephemeral=True)


async def _get_game_data(thread_id: str) -> tuple[dict, dict | None]:
    """Read game state from cache, falling back to a fresh disk read."""
    games_data = get_cached_games_data()
    game = games_data.get(thread_id)
    if game:
        return games_data, game
    games_data = await _read_games_fresh()
    return games_data, games_data.get(thread_id)


async def _autocomplete_in_thread(func, *args):
    """Run blocking autocomplete work off the event loop with a hard timeout."""
    loop = asyncio.get_running_loop()
    try:
        return await asyncio.wait_for(
            loop.run_in_executor(_AUTOCOMPLETE_EXECUTOR, func, *args),
            timeout=_AUTOCOMPLETE_TIMEOUT,
        )
    except asyncio.TimeoutError:
        _audit_log("WARN", f"Autocomplete timeout: {getattr(func, '__name__', func)}")
        return []
    except Exception as e:
        _audit_log("ERROR", f"Autocomplete error in {getattr(func, '__name__', func)}: {e}")
        return []


def _run_autocomplete_sync(func, *args, label: str = ""):
    """Run lightweight autocomplete logic synchronously (sub-ms to low-ms)."""
    t0 = time.monotonic()
    try:
        return func(*args)
    finally:
        elapsed = time.monotonic() - t0
        if elapsed > _AUDIT_SLOW_AC_SEC:
            _audit_log("WARN", f"AC slow {label or func.__name__}: {elapsed:.3f}s")


async def _ephemeral_reply(interaction: discord.Interaction, content: str = None, **kwargs):
    """Send an ephemeral response whether or not the interaction was already deferred."""
    kwargs.setdefault("ephemeral", True)
    if interaction.response.is_done():
        return await interaction.followup.send(content, **kwargs)
    return await interaction.response.send_message(content, **kwargs)


def _get_player_stats_data_sync() -> dict:
    """Return cached player stats, or {} if the cache has not been warmed yet."""
    return _player_stats_cache or {}


async def _ensure_player_stats_cache(force: bool = False) -> dict:
    """Load player stats into the in-memory cache without blocking the event loop."""
    global _stats_loading
    if _player_stats_cache and not force:
        return _player_stats_cache
    if _stats_loading:
        for _ in range(100):
            await asyncio.sleep(0.1)
            if _player_stats_cache and not force:
                return _player_stats_cache
            if not _stats_loading:
                break
        if _player_stats_cache:
            return _player_stats_cache
    _stats_loading = True
    try:
        return await read_json(PLAYER_STATS_FILE)
    finally:
        _stats_loading = False


async def _refresh_stats_cache_after_write():
    """Force-refresh player stats cache immediately after a mutation."""
    await _refresh_player_stats_cache()


_log_webhook_session: aiohttp.ClientSession | None = None


async def _get_log_session() -> aiohttp.ClientSession:
    """Lazily create and reuse a single aiohttp session for webhook logging."""
    global _log_webhook_session
    if _log_webhook_session is None or _log_webhook_session.closed:
        _log_webhook_session = aiohttp.ClientSession()
    return _log_webhook_session


async def _post_webhook(payload: dict, wait: bool = False):
    """POST a payload to the host-log webhook. Returns True on success, or —
    with `wait=True` — the created message as a dict (Discord's `?wait=true`),
    so callers can link to it. False on any failure.

    Hardened delivery (never raises, never crashes the caller):
      · URL validated once (scheme + Discord host) — a mangled env value is
        refused with a clear warning instead of a mystery 400/404,
      · empty `content` strings are dropped (Discord 400s on them),
      · empty payloads are skipped outright,
      · 4xx/5xx responses include a bounded response-body snippet so
        'Host log webhook failed' logs are actually diagnosable.
    """
    try:
        url = G.HOST_LOG_WEBHOOK_URL
        if not url:
            return False
        parsed = urllib.parse.urlsplit(url)
        if parsed.scheme != "https" or parsed.hostname not in _DISCORD_WEBHOOK_HOSTS:
            _audit_log(
                "WARN",
                f"Host log webhook URL invalid (scheme={parsed.scheme!r} "
                f"host={parsed.hostname!r}) — using channel fallback.",
            )
            return False

        body = dict(payload or {})
        # Discord rejects empty `content` with HTTP 400 — strip it so an empty
        # log line degrades to an embeds-only (or channel-fallback) post.
        if body.get("content") == "":
            body.pop("content", None)
        if not body.get("content") and not body.get("embeds") and not body.get("attachments"):
            _audit_log("WARN", "Host log webhook skipped — empty payload.")
            return False

        session = await _get_log_session()
        post_url = url
        if wait:
            post_url = f"{url}{'&' if parsed.query else '?'}wait=true"
        async with session.post(
            post_url,
            json=body,
            timeout=aiohttp.ClientTimeout(total=3 if wait else 2),
        ) as resp:
            if resp.status >= 400:
                try:
                    detail = (await resp.text())[:300]
                except Exception:
                    detail = ""
                _audit_log(
                    "WARN",
                    f"Host log webhook failed: HTTP {resp.status} — {detail}",
                )
                return False
            if wait:
                try:
                    message = await resp.json()
                    return message if isinstance(message, dict) else True
                except Exception:
                    return True
            return True
    except Exception as e:
        _audit_log("WARN", f"Host log webhook error: {e}")
        return False


async def send_host_log_embed(embed: discord.Embed, content: str = None) -> dict | None:
    """Post to host log via webhook (separate rate-limit bucket) or fall back to channel.

    Returns {"url", "message_id"} of the posted log when known (moderation
    events store it as their evidence link), else None."""
    if G.HOST_LOG_WEBHOOK_URL:
        payload: dict = {"embeds": [embed.to_dict()]}
        if content:
            payload["content"] = content
        result = await _post_webhook(payload, wait=True)
        if result:
            if isinstance(result, dict) and str(result.get("id", "")).isdigit():
                channel_id = result.get("channel_id") or G.HOST_LOG_CHANNEL_ID
                return {
                    "url": f"https://discord.com/channels/{cur_gid()}/{channel_id}/{result['id']}",
                    "message_id": int(result["id"]),
                }
            return None
    channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
    if channel:
        message = await channel.send(content=content, embed=embed)
        return {"url": message.jump_url, "message_id": message.id}
    return None


async def send_log_message(content: str):
    """Plain-text host log via webhook or channel fallback."""
    if G.HOST_LOG_WEBHOOK_URL:
        if await _post_webhook({"content": content}):
            return
    channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
    if channel:
        await channel.send(content)


def _invalidate_reservation_message_cache(thread_key: str, msg_id: int = None):
    if msg_id is not None:
        bucket = _reservation_message_cache.get(thread_key)
        if bucket:
            bucket.pop(msg_id, None)
    else:
        _reservation_message_cache.pop(thread_key, None)


async def _get_reservation_message(thread, thread_key: str, msg_id: int) -> discord.Message | None:
    bucket = _reservation_message_cache.setdefault(thread_key, {})
    cached = bucket.get(msg_id)
    if cached:
        return cached
    try:
        msg = await thread.fetch_message(msg_id)
        bucket[msg_id] = msg
        return msg
    except (discord.NotFound, discord.HTTPException):
        _invalidate_reservation_message_cache(thread_key, msg_id)
        return None


async def _debounced_reservation_update(channel_id):
    try:
        await asyncio.sleep(RESERVATION_DEBOUNCE_SEC)
        await update_reservation_message(channel_id)
    except asyncio.CancelledError:
        pass
    finally:
        _pending_reservation_updates.pop(str(channel_id), None)


def schedule_reservation_update(channel_id):
    key = str(channel_id)
    existing = _pending_reservation_updates.get(key)
    if existing and not existing.done():
        existing.cancel()
    _pending_reservation_updates[key] = asyncio.create_task(_debounced_reservation_update(channel_id))


def schedule_log_update(channel_id):
    """Debounced, coalesced Public Archive refresh — never races/duplicates itself."""
    key = f"publiclog:{channel_id}"
    _schedule_coalesced_update(key, RESERVATION_DEBOUNCE_SEC, lambda: update_public_log(channel_id))


async def _assign_roles_batched(members: list, role: discord.Role):
    valid = [m for m in members if m]
    for i in range(0, len(valid), 10):
        batch = valid[i:i + 10]
        async with _discord_api_sem:
            await asyncio.gather(*[m.add_roles(role, reason="Gamer Pass") for m in batch], return_exceptions=True)
        if i + 10 < len(valid):
            await asyncio.sleep(1.0)


async def _create_vcs_batched(category, names: list, chan_id_list: list, placed: set = None):
    for i in range(0, len(names), 5):
        for n in names[i:i + 5]:
            async with _discord_api_sem:
                vc = await category.create_voice_channel(name=n)
                chan_id_list.append(vc.id)
                if placed is not None:
                    placed.add(n)
        if i + 5 < len(names):
            await asyncio.sleep(1.0)


async def _send_dms_batched(members: list, content: str):
    for member in members:
        if not member:
            continue
        async with _discord_api_sem:
            try:
                await member.send(content)
            except Exception:
                pass
        await asyncio.sleep(0.3)


async def _refresh_player_stats_cache():
    """Background refresh of the full player-stats cache."""
    def _fetch():
        conn = None
        cursor = None
        all_profiles = {}
        try:
            conn = _db_get_connection()
            cursor = conn.cursor(dictionary=True)
            cursor.execute(*_users_select_all())
            for row in cursor.fetchall():
                d_id = str(row["discord_id"])
                all_profiles[d_id] = {
                    "total_games": row["total_games"],
                    "hoi4_verified": bool(row["hoi4_verified"]),
                    "commends": row["rp_commends"],
                    "warns": row["rp_warns"],
                    "banned": bool(row["banned"]),
                    "hist_banned": bool(row["hist_banned"]),
                    "hist_commends": row["hist_commends"],
                    "hist_warns": row["hist_warns"],
                    "hosted_games": row["hosted_games"],
                    "host_acclamations": row["host_acclamations"],
                    "host_violations": row["host_violations"],
                    "minor_streaks": json.loads(row["minor_streaks"]) if row["minor_streaks"] else {},
                    "hoi4_host_tier": row.get("hoi4_host_tier") or "None",
                    "merit_points": int(row.get("merit_points", 0) or 0),
                    "dishonored": bool(row.get("dishonored")),
                    "dishonored_data": _parse_mysql_json_obj(row.get("dishonored_data")),
                    "valor_trusted": row.get("valor_trusted") or None,
                    # Dual VIP lookup's MySQL half — backfilled at startup for
                    # every Discord VIP role holder.
                    "vip": bool(row.get("vip")),
                    "hist_verified": bool(row.get("hist_verified")),
                    "hist_host_tier": row.get("hist_host_tier") or "None",
                }
            return all_profiles
        except Exception as e:
            print(f"⚠️ Error refreshing player stats cache: {e}")
            return _player_stats_cache or {}
        finally:
            if cursor is not None:
                cursor.close()
            if conn is not None:
                conn.close()

    data = await _run_mysql_io(_fetch, label="player stats cache refresh")
    if data:
        _set_player_stats_cache(data)
    return data

async def _read_games_fresh() -> dict:
    """Reload games from MySQL, bypassing the stale in-memory cache."""
    lock = await _acquire_file_lock(GAMES_FILE)
    try:
        data = await asyncio.wait_for(
            asyncio.to_thread(_fetch_all_games_mysql),
            timeout=_MYSQL_IO_TIMEOUT,
        )
        _set_games_cache(data)
        return _games_view()
    except asyncio.TimeoutError:
        raise TimeoutError("MySQL games reload timed out — connection may be stuck after a network blip.")
    finally:
        lock.release()


async def _run_mysql_io(func, *args, label: str = "MySQL"):
    """Run blocking MySQL work off-thread with a hard timeout and exponential
    backoff retry for transient MySQL failures (1020 optimistic-lock race,
    1213 deadlock, 1205 lock wait timeout, 2006/2013 lost connections).

    Retries up to len(_MYSQL_RETRY_DELAYS) times with jittered backoff
    (0.1s -> 1s), re-running the ENTIRE sync function each time so a 1020
    "Record has changed since last read" write simply re-reads fresh state and
    re-applies. Timeouts are NOT retried — they mean a dead connection, and
    the watchdog/rebuild path is what recovers those.
    """
    last_err = None
    attempts = len(_MYSQL_RETRY_DELAYS) + 1
    for attempt in range(1, attempts + 1):
        try:
            return await asyncio.wait_for(
                asyncio.to_thread(func, *args),
                timeout=_MYSQL_IO_TIMEOUT,
            )
        except asyncio.TimeoutError:
            raise TimeoutError(
                f"{label} timed out after {_MYSQL_IO_TIMEOUT:.0f}s — "
                f"the DB connection is likely dead. Restart the bot if this keeps happening."
            )
        except Exception as e:
            last_err = e
            if not _is_mysql_retryable(e) or attempt >= attempts:
                raise
            delay = _MYSQL_RETRY_DELAYS[attempt - 1] * (0.7 + random.random() * 0.6)
            errno = _mysql_errno(e)
            print(
                f"⚠️ {label} MySQL {errno} (attempt {attempt}/{attempts}); "
                f"retrying in {delay:.2f}s"
            )
            await asyncio.sleep(delay)
    raise last_err

async def init_files_async():
    """Warm all MySQL-backed caches off the event loop (safe for on_ready)."""
    # Ensure Merit / Dishonored / host-tier / vip columns exist before any
    # INSERT uses them.
    try:
        await _run_mysql_io(_ensure_users_schema_mysql, label="startup users schema")
    except Exception as e:
        print(f"⚠️ users schema ensure failed (Merit/Dishonored writes may break): {e}")

    # STARTUP VIP BACKFILL — must run AFTER the schema self-heal (which
    # creates the `users.vip` column) and BEFORE any consumer reads the
    # cached player stats, so existing Discord VIP role holders have their
    # MySQL `vip` flag set from the very first cache warm. Best-effort:
    # a failure here never blocks the rest of the startup sequence.
    try:
        await _backfill_users_vip_flags()
    except Exception as e:
        print(f"⚠️ VIP backfill failed (startup continues): {e}")

    async def _load(label: str, fetch_fn, setter, empty):
        try:
            data = await _run_mysql_io(fetch_fn, label=f"startup {label}")
            setter(data)
            count = len(data) if hasattr(data, "__len__") else "?"
            print(f"✅ Loaded {count} {label} from MySQL")
        except Exception as e:
            print(f"⚠️ Could not load {label} from MySQL at startup: {e}")
            setter(empty)

    await asyncio.gather(
        _load("games", _fetch_all_games_mysql, _set_games_cache, {}),
        _load("schedule slots", _fetch_all_schedule_mysql, _set_schedule_cache, []),
        _load("locked days", _fetch_all_locked_days_mysql, _set_locked_days_cache, []),
        _load("bot config", _fetch_bot_config_mysql, _bot_config_load_all, {}),
        _load("host stats", _fetch_host_stats_mysql, _set_host_stats_cache, {}),
    )

intents = discord.Intents.default()
# Message Content is intentionally DISABLED: the bot only reads its own
# board messages (always available without the intent), interaction
# payloads, embeds, and DM attachments — none of which require the
# privileged Message Content intent. Re-enable here AND in the developer
# portal only if /search_logs or /report ever need to scan messages
# written by OTHER users in scanned channels.
# Message Content: the text people write in tickets, for readable ticket
# transcripts. Turn it on in the Discord Developer Portal first (Bot →
# Privileged Gateway Intents → Message Content), then set
# MESSAGE_CONTENT_INTENT=1. Switching it on here without the portal stops the
# bot from logging in, so it stays off by default.
intents.message_content = os.getenv("MESSAGE_CONTENT_INTENT", "").strip().lower() in ("1", "true", "yes", "on")
intents.members = True
# Receipt DM delivery: DM send() itself needs no privileged intent, but
# dm_messages is set EXPLICITLY so DM dispatch logging/state stays enabled
# regardless of future discord.py default changes.
intents.dm_messages = True
intents.voice_states = True
intents.guilds = True
intents.presences = True

bot = commands.Bot(command_prefix="!", intents=intents)
start_time = time.time()

async def read_json(filename):
    # Fast paths — never touch MySQL or file locks when caches are warm.
    if filename == PLAYER_STATS_FILE and _player_stats_cache.loaded():
        return _player_stats_cache
    if filename == GAMES_FILE and _games_cache:
        return _games_view()
    if filename == DRAFTS_FILE and _drafts_cache:
        return _drafts_cache
    if filename == SCHEDULE_FILE and _schedule_cache:
        return _list_view(_schedule_cache)
    if filename == LOCKED_DAYS_FILE and _locked_days_cache:
        return _list_view(_locked_days_cache)
    if filename == BOT_CONFIG_FILE and _BOT_CONFIG_LOADED:
        return _bot_config_cache
    if filename == HOST_STATS_FILE and _host_stats_cache.loaded():
        return _host_stats_cache

    lock = await _acquire_file_lock(filename)
    try:
        if filename == PLAYER_STATS_FILE:
            if _player_stats_cache.loaded():
                return _player_stats_cache

            def _fetch_all_mysql_profiles():
                conn = None
                cursor = None
                all_profiles = {}
                try:
                    conn = _db_get_connection()
                    cursor = conn.cursor(dictionary=True)
                    cursor.execute(*_users_select_all())
                    rows = cursor.fetchall()
                    for row in rows:
                        d_id = str(row["discord_id"])
                        all_profiles[d_id] = {
                            "total_games": row["total_games"],
                            "hoi4_verified": bool(row["hoi4_verified"]),
                            "commends": row["rp_commends"],
                            "warns": row["rp_warns"],
                            "banned": bool(row["banned"]),
                            "hist_banned": bool(row["hist_banned"]),
                            "hist_commends": row["hist_commends"],
                            "hist_warns": row["hist_warns"],
                            "hosted_games": row["hosted_games"],
                            "host_acclamations": row["host_acclamations"],
                            "host_violations": row["host_violations"],
                            "minor_streaks": json.loads(row["minor_streaks"]) if row["minor_streaks"] else {},
                            "hoi4_host_tier": row.get("hoi4_host_tier") or "None",
                            "merit_points": int(row.get("merit_points", 0) or 0),
                            "dishonored": bool(row.get("dishonored")),
                            "dishonored_data": _parse_mysql_json_obj(row.get("dishonored_data")),
                            "valor_trusted": row.get("valor_trusted") or None,
                            # Dual VIP lookup's MySQL half — backfilled at
                            # startup for every Discord VIP role holder.
                            "vip": bool(row.get("vip")),
                            "hist_verified": bool(row.get("hist_verified")),
                            "hist_host_tier": row.get("hist_host_tier") or "None",
                        }
                    return all_profiles
                except Exception as e:
                    print(f"⚠️ Error bulk reading player stats from MySQL: {e}")
                    return {}
                finally:
                    if cursor is not None:
                        cursor.close()
                    if conn is not None:
                        conn.close()

            data = await _run_mysql_io(_fetch_all_mysql_profiles, label="MySQL player-stats read")
            _set_player_stats_cache(data)
            return _player_stats_cache

        # 🔵 SPECIAL INTERCEPT 2: If code asks for drafts, reconstruct the dictionary from MySQL JSON storage
        if "drafts.json" in filename:
            if _drafts_cache:
                return _drafts_cache

            def _fetch_all_drafts():
                conn = None
                cursor = None
                all_drafts = {}
                try:
                    conn = _db_get_connection()
                    cursor = conn.cursor(dictionary=True)
                    cursor.execute("SELECT * FROM drafts")
                    rows = cursor.fetchall()
                    for row in rows:
                        all_drafts[str(row["draft_id"])] = json.loads(row["draft_data"])
                    return all_drafts
                except Exception as e:
                    print(f"⚠️ Error bulk reading drafts from MySQL: {e}")
                    return {}
                finally:
                    if cursor is not None:
                        cursor.close()
                    if conn is not None:
                        conn.close()

            data = await _run_mysql_io(_fetch_all_drafts, label="MySQL drafts read")
            _set_drafts_cache(data)
            return data

        # 🟢 GAMES: reconstruct the legacy dict from MySQL (games + game_reservations).
        if filename == GAMES_FILE:
            if _games_cache:
                return _games_view()
            data = await _run_mysql_io(_fetch_all_games_mysql, label="MySQL games read")
            _set_games_cache(data)
            return _games_view()

        # 🟢 SCHEDULE: reconstruct the legacy list-of-slots from MySQL.
        if filename == SCHEDULE_FILE:
            if _schedule_cache:
                return _list_view(_schedule_cache)
            data = await _run_mysql_io(_fetch_all_schedule_mysql, label="MySQL schedule read")
            _set_schedule_cache(data)
            return _list_view(_schedule_cache)

        # 🟢 LOCKED DAYS: reconstruct the legacy list-of-locks from MySQL.
        if filename == LOCKED_DAYS_FILE:
            if _locked_days_cache:
                return _list_view(_locked_days_cache)
            data = await _run_mysql_io(_fetch_all_locked_days_mysql, label="MySQL locked-days read")
            _set_locked_days_cache(data)
            return _list_view(_locked_days_cache)

        # 🟢 BOT CONFIG: reconstruct the key/value dict from MySQL.
        if filename == BOT_CONFIG_FILE:
            if _BOT_CONFIG_LOADED:
                return _bot_config_cache
            data = await _run_mysql_io(_fetch_bot_config_mysql, label="MySQL bot-config read")
            _bot_config_load_all(data)
            return _bot_config_cache

        # 🟢 HOST STATS: reconstruct the legacy {host_id: stats} dict from MySQL.
        if filename == HOST_STATS_FILE:
            if _host_stats_cache.loaded():
                return _host_stats_cache
            data = await _run_mysql_io(_fetch_host_stats_mysql, label="MySQL host-stats read")
            _set_host_stats_cache(data)
            return _host_stats_cache

        # 🟢 GENERAL FALLBACK: Standard behavior for normal local configuration files
        try:
            with open(filename, 'r') as f: return json.load(f)
        except: return {} if filename in [GAMES_FILE, PLAYER_STATS_FILE] else []
    finally:
        lock.release()

async def write_json(filename, data):
    lock = await _acquire_file_lock(filename)
    try:
        # 🔵 SPECIAL INTERCEPT 1: If code saves player stats, update the database using an optimized batch query!
        if filename == PLAYER_STATS_FILE:
            def _save_all_mysql_profiles(profiles_dict):
                conn = None
                cursor = None
                try:
                    conn = _db_get_connection()
                    cursor = conn.cursor()
                    # Retired columns (Stellaris, blacklist) are only filled
                    # with 0 on brand-new rows, for tables that lack defaults.
                    table, key_cols, key_marks, key_vals = _users_target()
                    query = f"""
                        INSERT INTO {table} (
                            {key_cols}, total_games, hoi4_verified, stellaris_verified,
                            rp_commends, rp_warns, blacklisted, banned, hist_banned,
                            hist_commends, hist_warns, stel_commends, stel_warns,
                            stel_blacklisted, stel_banned, hosted_games, host_acclamations,
                            host_violations, minor_streaks, merit_points, dishonored,
                            dishonored_data
                        ) VALUES ({key_marks}, %s, %s, 0, %s, %s, 0, %s, %s, %s, %s, 0, 0, 0, 0, %s, %s, %s, %s, %s, %s, %s)
                        ON DUPLICATE KEY UPDATE
                            total_games = VALUES(total_games),
                            hoi4_verified = VALUES(hoi4_verified),
                            rp_commends = VALUES(rp_commends),
                            rp_warns = VALUES(rp_warns),
                            banned = VALUES(banned),
                            hist_banned = VALUES(hist_banned),
                            hist_commends = VALUES(hist_commends),
                            hist_warns = VALUES(hist_warns),
                            hosted_games = VALUES(hosted_games),
                            host_acclamations = VALUES(host_acclamations),
                            host_violations = VALUES(host_violations),
                            minor_streaks = VALUES(minor_streaks),
                            merit_points = VALUES(merit_points),
                            dishonored = VALUES(dishonored),
                            dishonored_data = VALUES(dishonored_data);
                    """

                    batch_values = []
                    for d_id, stats in profiles_dict.items():
                        minor_streaks_str = json.dumps(stats.get("minor_streaks", []))
                        values = key_vals + (
                            str(d_id),
                            stats.get("total_games", 0),
                            1 if stats.get("hoi4_verified") else 0,
                            stats.get("commends", 0),
                            stats.get("warns", 0),
                            1 if stats.get("banned") else 0,
                            1 if stats.get("hist_banned") else 0,
                            stats.get("hist_commends", 0),
                            stats.get("hist_warns", 0),
                            stats.get("hosted_games", 0),
                            stats.get("host_acclamations", 0),
                            stats.get("host_violations", 0),
                            minor_streaks_str,
                            int(stats.get("merit_points", 0) or 0),
                            1 if stats.get("dishonored") else 0,
                            json.dumps(stats.get("dishonored_data", {}) or {}),
                        )
                        batch_values.append(values)

                    if batch_values:
                        cursor.executemany(query, batch_values)
                        conn.commit()
                except Exception as e:
                    print(f"⚠️ Error bulk saving player stats to MySQL: {e}")
                finally:
                    if cursor is not None:
                        cursor.close()
                    if conn is not None:
                        conn.close()

            _set_player_stats_cache(data)
            return await _run_mysql_io(_save_all_mysql_profiles, data, label="MySQL player-stats write")

        # 🔵 SPECIAL INTERCEPT 2: Save active draft data blocks to MySQL using standard JSON dumps
        if "drafts.json" in filename:
            def _save_all_drafts(drafts_dict):
                conn = None
                cursor = None
                try:
                    conn = _db_get_connection()
                    cursor = conn.cursor()
                    query = """
                        INSERT INTO drafts (draft_id, mode, host_id, phase, draft_data)
                        VALUES (%s, %s, %s, %s, %s)
                        ON DUPLICATE KEY UPDATE
                            mode = VALUES(mode),
                            host_id = VALUES(host_id),
                            phase = VALUES(phase),
                            draft_data = VALUES(draft_data);
                    """

                    batch_values = []
                    for draft_id, draft in drafts_dict.items():
                        batch_values.append((
                            str(draft_id),
                            draft.get("mode", "Unknown"),
                            int(draft.get("host_id", 0)),
                            draft.get("phase", "UNKNOWN"),
                            json.dumps(draft)
                        ))

                    if batch_values:
                        cursor.executemany(query, batch_values)
                        conn.commit()
                except Exception as e:
                    print(f"⚠️ Error bulk saving drafts to MySQL: {e}")
                finally:
                    if cursor is not None:
                        cursor.close()
                    if conn is not None:
                        conn.close()

            _set_drafts_cache(data)
            return await _run_mysql_io(_save_all_drafts, data, label="MySQL drafts write")

        # 🟢 GAMES: persist to MySQL (games + game_reservations) and refresh cache.
        if filename == GAMES_FILE:
            # A server's view is merged back into the shared map first.
            data = _merge_games_view(data)
            # Snapshot participation fields before the (threaded) bulk write so we
            # can detect in-place mutations from concurrent save_single_game calls
            # that share this same dict object with the live cache.
            def _participation_sig(g):
                if not isinstance(g, dict):
                    return None
                return (
                    tuple(sorted(int(x) for x in (g.get("confirmed_ids") or []) if str(x).isdigit())),
                    tuple(sorted(int(x) for x in (g.get("declined_ids") or []) if str(x).isdigit())),
                    tuple(sorted(int(x) for x in (g.get("dropped_out") or []) if str(x).isdigit())),
                )

            cached = _games_cache if isinstance(_games_cache, dict) else {}
            for tid, g in list((data or {}).items()):
                cg = cached.get(tid)
                if cg is not None and cg is not g and isinstance(g, dict):
                    _merge_participation_fields(g, cg)
                    _preserve_sticky_game_fields(g, cg)

            pre_sig = {str(tid): _participation_sig(g) for tid, g in (data or {}).items()}
            await _run_mysql_io(_save_all_games_mysql, data, label="MySQL games write")

            # Re-merge from live cache (separate object case) and re-upsert any
            # games whose participation fields changed during the bulk IO.
            cached = _games_cache if isinstance(_games_cache, dict) else {}
            dirty = []
            for tid, g in list((data or {}).items()):
                tid = str(tid)
                if not isinstance(g, dict):
                    continue
                cg = cached.get(tid)
                if cg is not None and cg is not g:
                    _merge_participation_fields(g, cg)
                after = _participation_sig(g)
                if pre_sig.get(tid) != after:
                    dirty.append((tid, g))
            for tid, g in dirty:
                try:
                    await _run_mysql_io(
                        _upsert_single_game_mysql, tid, g, False,
                        label=f"MySQL games participation re-merge({tid})",
                    )
                except Exception as e:
                    print(f"[WARN] participation re-merge upsert failed for {tid}: {e}")
            _set_games_cache(data)
            return

        # 🟢 SCHEDULE: persist the list-of-slots to MySQL and refresh cache.
        if filename == SCHEDULE_FILE:
            data = _merge_list_view(_schedule_cache, data)
            await _run_mysql_io(_save_all_schedule_mysql, data, label="MySQL schedule write")
            _set_schedule_cache(data)
            return

        # 🟢 LOCKED DAYS: persist the list-of-locks to MySQL and refresh cache.
        if filename == LOCKED_DAYS_FILE:
            data = _merge_list_view(_locked_days_cache, data)
            await _run_mysql_io(_save_all_locked_days_mysql, data, label="MySQL locked-days write")
            _set_locked_days_cache(data)
            return

        # 🟢 BOT CONFIG: persist the key/value dict to MySQL and refresh cache.
        if filename == BOT_CONFIG_FILE:
            _set_bot_config_cache(data)
            section = _bot_config_section_key()
            to_save = {section: _BOT_CONFIG_ALL.get(section) or {}} if section else {
                k: v for k, v in _BOT_CONFIG_ALL.items() if not str(k).startswith("guild:")
            }
            await _run_mysql_io(_save_bot_config_mysql, to_save, label="MySQL bot-config write")
            return

        # 🟢 HOST STATS: persist the {host_id: stats} dict to MySQL and refresh cache.
        if filename == HOST_STATS_FILE:
            await _run_mysql_io(_save_host_stats_mysql, data, label="MySQL host-stats write")
            _set_host_stats_cache(data)
            return

        # 🟢 GENERAL FALLBACK: Standard write configuration for local static JSON configuration logs
        with open(filename, 'w') as f:
            json.dump(data, f, indent=4)
    finally:
        lock.release()


async def _finalize_game_attendance(guild: discord.Guild, game_id: str) -> None:
    """Called at /game_end (only for games that actually reached /game_start).

    Two cases:
      • The automatic 5-sample attendance snapshot already finished
        (`snapshot_done`) — this just does one last-moment VC scan merge as a
        safety net (e.g. someone rejoined VC in the seconds before /game_end),
        and does NOT re-post the Advanced Log Tracker (it was already posted
        when the 5th sample completed).
      • The snapshot did NOT finish — e.g. the host set a long delay
        (40 min × 5 = 200 min) but the session ran shorter. In that case this
        performs an early finalize using whatever partial samples were
        persisted so far (plus one bonus live scan right now), applying the
        same hit-count logic as a normal finish. The Advanced Log Tracker is
        intentionally reserved for complete five-snapshot runs.
    """
    thread_key = str(game_id)
    games_data = await _load_games_resilient()
    storage_key, game = _find_game_entry(games_data, thread_key)
    if not game:
        return
    thread_key = storage_key or thread_key

    if game.get("snapshot_done"):
        # Finalized attendance is immutable. Rewriting from a stale full-map
        # snapshot here could erase tracker IDs written concurrently.
        return

    # Snapshot never finished — early finalize using whatever samples were
    # collected so far, plus one bonus live scan (catches anyone still in VC).
    sample_logs = list(game.get("presence_snapshots", []) or [])
    sample_sets = [
        {int(u) for u in (entry.get("present_ids") or []) if str(u).isdigit()}
        for entry in sample_logs
    ]
    try:
        dropped_out_set = {int(x) for x in game.get("dropped_out", []) if str(x).isdigit()}
        scanned = await _scan_voice_presence(guild, game)
        bonus_present = {p for p in scanned if p not in dropped_out_set}
        sample_logs.append({
            "index": len(sample_logs) + 1,
            "ts": int(time.time()),
            "present_ids": sorted(bonus_present),
            "count": len(bonus_present),
            "final_bonus": True,
        })
        sample_sets.append(bonus_present)
    except Exception as e:
        print(f"[WARN] Bonus live scan at /game_end failed: {e}")

    delay = game.get("snapshot_interval_minutes", "?")
    await _finalize_attendance_results(thread_key, guild, delay, sample_sets, sample_logs)


async def _commit_reservation(thread_id: str, nation: str, user_id: int):
    """Atomically claim one reservation slot (prevents double-booking races).

    Uses a MySQL transaction + UNIQUE(thread_id, slot_key) so concurrent button
    presses cannot overwrite each other the way games.json did.

    Returns (ok, error_message, games_data, game).
    """
    # Warm _games_cache for the lock/commit logic further down.
    peek_games_data = _games_cache or {}
    if peek_games_data.get(thread_id) is None:
        peek_games_data = await _run_mysql_io(_fetch_all_games_mysql, label="MySQL games read (mode peek)")
        _set_games_cache(peek_games_data)

    # Strict authentication guard — central choke point for nearly every
    # reservation path (/reserve, filler, coop, draw, gamble, reroll,
    # /gamble_for). Checked before acquiring any locks since a rejected
    # member shouldn't block/contend for them.
    guild = bot.get_guild(cur_gid())
    member = guild.get_member(user_id) if guild else None
    if not await is_user_authenticated(member, thread_id):
        return False, RESERVATION_REJECTED_UNVERIFIED_MESSAGE, None, None

    async with _get_reservation_lock(thread_id):
        # Serialize against full-map write_json saves so a stale bulk write cannot
        # wipe a reservation that just landed in MySQL.
        lock = await _acquire_file_lock(GAMES_FILE)
        try:
            games_data = _games_cache or {}
            game = games_data.get(thread_id)
            if not game:
                games_data = await _run_mysql_io(_fetch_all_games_mysql, label="MySQL games read")
                _set_games_cache(games_data)
                game = games_data.get(thread_id)
            if not game:
                return False, "Game not found.", None, None

            game_mode = game.get("mode", "")
            max_cap = get_game_capacity(game_mode)
            ok, err, updated = await _run_mysql_io(
                _commit_reservation_mysql, thread_id, nation, user_id, max_cap,
                label="MySQL reservation commit",
            )
            if not ok or not updated:
                return ok, err, games_data, game

            games_data = dict(_games_cache) if _games_cache else {}
            games_data[thread_id] = updated
            _set_games_cache(games_data)
            return True, None, games_data, updated
        finally:
            lock.release()


def _upsert_single_game_mysql(thread_id: str, game: dict, rewrite_reservations: bool = False):
    """Persist one game row without rewriting the entire games table.

    By default only upserts `games` metadata/JSON. Set rewrite_reservations=True
    when the caller intentionally replaced the reservation map for this thread.

    Connection-leak hardening: the pooled connection and cursor are used as
    context managers, so `cursor.close()` and return-to-pool are guaranteed even
    when the write raises. Optimistic-lock races (1020) are handled by
    `_run_mysql_io`'s exponential-backoff retry, which re-runs this whole
    function from scratch.
    """
    conn = None
    try:
        with _db_get_connection() as conn:
            with conn.cursor() as cursor:
                tid = str(thread_id)
                # Lock the row for the whole upsert. A non-locking SELECT + UPDATE is
                # what raises 1020 under concurrent GameFeedbackButton / archive writes.
                conn.start_transaction()
                cursor.execute(
                    "SELECT game_data FROM games WHERE thread_id = %s FOR UPDATE",
                    (tid,),
                )
                prev = cursor.fetchone()
                if prev:
                    _preserve_sticky_game_fields(game, _parse_mysql_json(prev[0]))
                row, res_rows = _split_game_for_mysql(tid, game)
                cursor.execute(
                    """
                    INSERT INTO games (
                        thread_id, mode, host_id, status, thread_name, game_started,
                        start_timestamp, announcement_message_id, announcement_channel_id,
                        reservations_rev, game_data, guild_id
                    ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    ON DUPLICATE KEY UPDATE
                        guild_id = VALUES(guild_id),
                        mode = VALUES(mode),
                        host_id = VALUES(host_id),
                        status = VALUES(status),
                        thread_name = VALUES(thread_name),
                        game_started = VALUES(game_started),
                        start_timestamp = VALUES(start_timestamp),
                        announcement_message_id = VALUES(announcement_message_id),
                        announcement_channel_id = VALUES(announcement_channel_id),
                        reservations_rev = VALUES(reservations_rev),
                        game_data = VALUES(game_data)
                    """,
                    row,
                )
                if rewrite_reservations:
                    # Preserve receipt log message ids AND the web re-roll
                    # budget (`rerolls_used`) across the rewrite. The casino
                    # web app increments game_reservations.rerolls_used on
                    # every wheel re-roll; dropping it here would silently
                    # reset the counter and re-grant spent re-rolls.
                    cursor.execute(
                        "SELECT slot_key, user_id, log_message_id, rerolls_used FROM game_reservations WHERE thread_id = %s",
                        (str(thread_id),),
                    )
                    preserved_meta = {}
                    for r in cursor.fetchall():
                        preserved_meta[(str(r[0]), int(r[1]))] = (
                            int(r[2]) if r[2] is not None else None,
                            int(r[3] or 0),
                        )
                    cursor.execute(
                        "DELETE FROM game_reservations WHERE thread_id = %s",
                        (str(thread_id),),
                    )
                    if res_rows:
                        cursor.executemany(
                            "INSERT INTO game_reservations (thread_id, slot_key, user_id, log_message_id, rerolls_used) VALUES (%s, %s, %s, %s, %s)",
                            [
                                (
                                    str(r[0]),
                                    str(r[1]),
                                    int(r[2]),
                                    preserved_meta.get((str(r[1]), int(r[2])), (None, 0))[0],
                                    preserved_meta.get((str(r[1]), int(r[2])), (None, 0))[1],
                                )
                                for r in res_rows
                            ],
                        )
                    cursor.execute(
                        "UPDATE games SET reservations_rev = reservations_rev + 1 WHERE thread_id = %s",
                        (str(thread_id),),
                    )
                    cursor.execute(
                        "SELECT reservations_rev FROM games WHERE thread_id = %s",
                        (str(thread_id),),
                    )
                    rev_row = cursor.fetchone()
                    if rev_row is not None:
                        game["reservations_rev"] = int(rev_row[0] or 0)
            conn.commit()
    except Exception as e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print(f"⚠️ Error upserting single game {thread_id}: {e}")
        raise


async def save_single_game(thread_id: str, game: dict, rewrite_reservations: bool = False):
    """Update one game in MySQL + keep the in-memory cache coherent.

    Does not hold the games file lock during MySQL I/O (unlike write_json's full
    map rewrite), so hot paths like participation Yes/No stay responsive under load.
    """
    tid = str(thread_id)
    cache = _games_cache if isinstance(_games_cache, dict) else {}
    cached_game = cache.get(tid)
    if cached_game is not None and cached_game is not game and isinstance(cached_game, dict):
        _preserve_sticky_game_fields(game, cached_game)
    # Hard-timeout guarded (like every other MySQL write) so a dead/slow
    # connection can't hang the calling command (and the entire caller's flow,
    # e.g. /give, /take DMs) forever — see _run_mysql_io.
    await _run_mysql_io(_upsert_single_game_mysql, tid, game, rewrite_reservations, label=f"save_single_game({tid})")
    cache = _games_cache if isinstance(_games_cache, dict) else {}
    cache[tid] = game
    _set_games_cache(cache)


def _merge_participation_fields(dst_game: dict, src_game: dict) -> None:
    """Union participation / dropout fields so a bulk write can't wipe concurrent confirms."""
    if not isinstance(dst_game, dict) or not isinstance(src_game, dict):
        return
    for key in ("confirmed_ids", "declined_ids", "dropped_out"):
        a = {int(x) for x in (dst_game.get(key) or []) if str(x).isdigit()}
        b = {int(x) for x in (src_game.get(key) or []) if str(x).isdigit()}
        if a or b:
            dst_game[key] = list(a | b)
    da = dst_game.get("drop_reasons") if isinstance(dst_game.get("drop_reasons"), dict) else {}
    sb = src_game.get("drop_reasons") if isinstance(src_game.get("drop_reasons"), dict) else {}
    if da or sb:
        merged = dict(da)
        merged.update(sb)
        dst_game["drop_reasons"] = merged


async def _resolve_dm_target(user_id: int, preferred=None):
    """Resolve a Discord user object for DM delivery with a hard fallback:
    `bot.get_user()` returns None for uncached users (which silently skipped
    DM delivery) — so fall back to `fetch_user()` before giving up."""
    user = preferred
    if user is None:
        user = bot.get_user(int(user_id))
    if user is None:
        try:
            user = await bot.fetch_user(int(user_id))
        except Exception as e:
            print(f"[DM] Could not resolve user {user_id}: {e}")
            user = None
    return user


async def _dm_user_safe(user, *, content: str = None, embed: discord.Embed = None, view: discord.ui.View = None, label: str = "moderation") -> bool:
    """Send a DM with a hard timeout so closed DMs / rate limits can't hang the command."""
    try:
        await asyncio.wait_for(user.send(content=content, embed=embed, view=view), timeout=8.0)
        return True
    except Exception as e:
        print(f"[WARN] {label} DM to {getattr(user, 'id', '?')} failed: {e}")
        return False


def _users_target(gid=None) -> tuple[str, str, str, tuple]:
    """Where a server's player records live: (table, key columns, key
    placeholders, key values before discord_id). The home server keeps the
    original `users` table; every other server shares `guild_users`."""
    gid = _as_gid(gid if gid is not None else cur_gid())
    if gid == GUILD_ID:
        return "users", "discord_id", "%s", ()
    return "guild_users", "guild_id, discord_id", "%s, %s", (str(gid),)


def _users_select_all(gid=None) -> tuple[str, tuple]:
    table, _, _, keys = _users_target(gid)
    if table == "users":
        return "SELECT * FROM users", ()
    return "SELECT * FROM guild_users WHERE guild_id = %s", keys


def _users_where_one(discord_id, gid=None) -> tuple[str, str, tuple]:
    """(table, WHERE clause, params) for one player's record row."""
    table, _, _, keys = _users_target(gid)
    if table == "users":
        return "users", "discord_id = %s", (str(discord_id),)
    return "guild_users", "guild_id = %s AND discord_id = %s", keys + (str(discord_id),)


async def get_mysql_player_stats(discord_id: str) -> dict:
    """Fetches a single user's profile from MySQL and returns it as a dictionary."""
    def _fetch():
        conn = None
        cursor = None
        try:
            conn = _db_get_connection()
            cursor = conn.cursor(dictionary=True)
            table, where, params = _users_where_one(discord_id)
            cursor.execute(f"SELECT * FROM {table} WHERE {where}", params)
            row = cursor.fetchone()
            if row:
                return {
                    "total_games": row["total_games"],
                    "hoi4_verified": bool(row["hoi4_verified"]),
                    "commends": row["rp_commends"],
                    "warns": row["rp_warns"],
                    "banned": bool(row["banned"]),
                    "hist_banned": bool(row["hist_banned"]),
                    "hist_commends": row["hist_commends"],
                    "hist_warns": row["hist_warns"],                  # Fixed & Mapped!
                    "hosted_games": row["hosted_games"],
                    "host_acclamations": row["host_acclamations"],
                    "host_violations": row["host_violations"],
                    "minor_streaks": json.loads(row["minor_streaks"]) if row["minor_streaks"] else {},
                    # Per-game host tier ("None" / "Trial" / "Full" / "Senior"). Defensive
                    # .get() so this keeps working before schema.sql's ALTER TABLE runs.
                    "hoi4_host_tier": row.get("hoi4_host_tier") or "None",
                    "merit_points": int(row.get("merit_points", 0) or 0),
                    "dishonored": bool(row.get("dishonored")),
                    "dishonored_data": _parse_mysql_json_obj(row.get("dishonored_data")),
                    "valor_trusted": row.get("valor_trusted") or None,
                    # Round-trip the VIP flag so a save never clears it.
                    "vip": bool(row.get("vip")),
                    "hist_verified": bool(row.get("hist_verified")),
                    "hist_host_tier": row.get("hist_host_tier") or "None",
                }
            else:
                return {
                    "total_games": 0, "hoi4_verified": False,
                    "commends": 0, "warns": 0, "banned": False,
                    "hist_banned": False, "hist_commends": 0, "hist_warns": 0,
                    "hosted_games": 0, "host_acclamations": 0,
                    "host_violations": 0, "minor_streaks": {},
                    "hoi4_host_tier": "None",
                    "merit_points": 0, "dishonored": False, "dishonored_data": {},
                    "valor_trusted": None, "vip": False, "hist_verified": False, "hist_host_tier": "None",
                }
        finally:
            if cursor is not None:
                cursor.close()
            if conn is not None:
                conn.close()

    # Hard-timeout guarded — an unprotected asyncio.to_thread here used to be
    # able to hang forever on a dead/slow connection, stalling /give, /take,
    # /verify, etc. before they ever reached the DM/description step.
    return await _run_mysql_io(_fetch, label=f"get_mysql_player_stats({discord_id})")


async def save_mysql_player_stats(discord_id: str, stats: dict):
    """Updates or inserts a single user's profile data in the MySQL database."""
    def _save():
        conn = None
        cursor = None
        try:
            conn = _db_get_connection()
            cursor = conn.cursor()
            # Retired columns (Stellaris, blacklist) are only filled with 0
            # on brand-new rows, for tables that lack defaults.
            table, key_cols, key_marks, key_vals = _users_target()
            query = f"""
                INSERT INTO {table} (
                    {key_cols}, total_games, hoi4_verified, stellaris_verified,
                    rp_commends, rp_warns, blacklisted, banned, hist_banned,
                    hist_commends, hist_warns, stel_commends, stel_warns,
                    stel_blacklisted, stel_banned, hosted_games, host_acclamations,
                    host_violations, minor_streaks, hoi4_host_tier,
                    merit_points, dishonored, dishonored_data, vip
                ) VALUES ({key_marks}, %s, %s, 0, %s, %s, 0, %s, %s, %s, %s, 0, 0, 0, 0, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                ON DUPLICATE KEY UPDATE
                    total_games = VALUES(total_games),
                    hoi4_verified = VALUES(hoi4_verified),
                    rp_commends = VALUES(rp_commends),
                    rp_warns = VALUES(rp_warns),
                    banned = VALUES(banned),
                    hist_banned = VALUES(hist_banned),
                    hist_commends = VALUES(hist_commends),
                    hist_warns = VALUES(hist_warns),                  -- Fixed & Mapped!
                    hosted_games = VALUES(hosted_games),
                    host_acclamations = VALUES(host_acclamations),
                    host_violations = VALUES(host_violations),
                    minor_streaks = VALUES(minor_streaks),
                    hoi4_host_tier = VALUES(hoi4_host_tier),
                    merit_points = VALUES(merit_points),
                    dishonored = VALUES(dishonored),
                    dishonored_data = VALUES(dishonored_data),
                    vip = VALUES(vip);
            """
            minor_streaks_str = json.dumps(stats.get("minor_streaks", []))

            values = key_vals + (
                str(discord_id),
                stats.get("total_games", 0),
                1 if stats.get("hoi4_verified") else 0,
                stats.get("commends", 0),
                stats.get("warns", 0),
                1 if stats.get("banned") else 0,
                1 if stats.get("hist_banned") else 0,
                stats.get("hist_commends", 0),
                stats.get("hist_warns", 0),                     # Fixed & Mapped!
                stats.get("hosted_games", 0),
                stats.get("host_acclamations", 0),
                stats.get("host_violations", 0),
                minor_streaks_str,
                stats.get("hoi4_host_tier") or "None",
                int(stats.get("merit_points", 0) or 0),
                1 if stats.get("dishonored") else 0,
                json.dumps(stats.get("dishonored_data", {}) or {}),
                1 if stats.get("vip") else 0,
            )
            cursor.execute(query, values)
            # Hist Verified: only written when the dict carries it, so
            # partial stats dicts never erase it.
            if "hist_host_tier" in stats:
                try:
                    cursor.execute(
                        f"UPDATE {table} SET hist_host_tier = %s WHERE {_users_where_one(discord_id)[1]}",
                        (str(stats.get("hist_host_tier") or "None")[:20],) + _users_where_one(discord_id)[2],
                    )
                except Exception as e:
                    print(f"[WARN] hist_host_tier save failed for {discord_id}: {e}")
            if "hist_verified" in stats:
                try:
                    cursor.execute(
                        f"UPDATE {table} SET hist_verified = %s WHERE {_users_where_one(discord_id)[1]}",
                        (1 if stats.get("hist_verified") else 0,) + _users_where_one(discord_id)[2],
                    )
                except Exception as e:
                    print(f"[WARN] hist_verified save failed for {discord_id}: {e}")
            # Hearts of Valor Trusted pick: only written when the dict carries
            # it, so partial stats dicts never erase an approved pick.
            if "valor_trusted" in stats:
                try:
                    cursor.execute(
                        f"UPDATE {table} SET valor_trusted = %s WHERE {_users_where_one(discord_id)[1]}",
                        (stats.get("valor_trusted") or None,) + _users_where_one(discord_id)[2],
                    )
                except Exception as e:
                    print(f"[WARN] valor_trusted save failed for {discord_id}: {e}")
            conn.commit()
        finally:
            if cursor is not None:
                cursor.close()
            if conn is not None:
                conn.close()

    # Hard-timeout guarded — see get_mysql_player_stats for why this matters.
    await _run_mysql_io(_save, label=f"save_mysql_player_stats({discord_id})")
    if _player_stats_cache.loaded():
        _player_stats_cache[str(discord_id)] = stats

def is_host():
    async def predicate(interaction: discord.Interaction) -> bool:
        if interaction.user.guild_permissions.administrator:
            return True
        user_roles = [r.id for r in interaction.user.roles]
        if any(role_id in user_roles for role_id in ALLOWED_HOST_ROLES):
            return True
        if not interaction.response.is_done():
            await interaction.response.send_message(
                "❌ Missing Permissions (Host/Admin required).",
                ephemeral=True,
            )
        return False
    return app_commands.check(predicate)

def is_admin_staff():
    """Gate for /verify and /make_host: Admins or Host Management staff only."""
    async def predicate(interaction: discord.Interaction) -> bool:
        if interaction.user.guild_permissions.administrator:
            return True
        user_roles = [r.id for r in interaction.user.roles]
        if any(rid in SENIOR_MANAGEMENT_ROLES for rid in user_roles):
            return True
        if not interaction.response.is_done():
            await interaction.response.send_message("❌ **Access Denied.** Admins/Staff only.", ephemeral=True)
        return False
    return app_commands.check(predicate)


async def _assign_discord_role(member: discord.Member, role_id: int, *, reason: str) -> str:
    """Assign a Discord role with hierarchy/permission checks and post-verify.

    Returns a human-readable status line (success / already had / error).
    """
    guild = member.guild
    if guild is None:
        return f"❌ Role `{role_id}`: member has no guild."

    role = guild.get_role(int(role_id))
    if role is None:
        try:
            # Rare: role missing from cache — refresh guild roles.
            await guild.fetch_roles()
            role = guild.get_role(int(role_id))
        except Exception:
            role = None
    if role is None:
        return f"❌ Role ID `{role_id}` not found on this server."

    # Refresh member so role checks aren't stale.
    try:
        member = guild.get_member(member.id) or await guild.fetch_member(member.id)
    except Exception:
        pass

    if role in member.roles:
        return f"ℹ️ Already had **{role.name}**."

    me = guild.me
    if me is None and bot.user is not None:
        try:
            me = await guild.fetch_member(bot.user.id)
        except Exception:
            me = None
    if me is not None:
        if not me.guild_permissions.manage_roles:
            return (
                f"❌ Cannot assign **{role.name}** — bot lacks **Manage Roles** permission."
            )
        if role >= me.top_role:
            return (
                f"❌ Cannot assign **{role.name}** — that role is higher than (or equal to) "
                f"the bot's top role (**{me.top_role.name}**). Move the bot role above it."
            )
        if role.managed:
            return f"❌ Cannot assign **{role.name}** — it is a managed/integration role."

    try:
        await member.add_roles(role, reason=reason)
        await asyncio.sleep(0.4)
        # Confirm it stuck.
        try:
            fresh = await guild.fetch_member(member.id)
        except Exception:
            fresh = member
        if role not in fresh.roles:
            return (
                f"❌ Tried to assign **{role.name}** but it is not on the member afterward "
                f"(hierarchy/permissions or another bot may have blocked it)."
            )
        return f"✅ Assigned **{role.name}**."
    except discord.Forbidden as e:
        return f"❌ Forbidden assigning **{role.name}**: `{e}`"
    except Exception as e:
        return f"❌ Failed assigning **{role.name}**: `{e}`"



# ==========================================================================
# UNIVERSAL SYSTEMS — MERIT POINTS & DISHONORED TITLE
# --------------------------------------------------------------------------
# Merit points are cumulative ("Valor" points) and never become commends.
# 25 Merit + 50 attended games = Hearts of Valor (see _sync_valor_role).
# The Dishonored title bans a user from reserving specific Majors/Minors within a
# base category (Roleplay / Historical).
# ==========================================================================
def _merit_points(stats: dict) -> int:
    return int((stats or {}).get("merit_points", 0) or 0)


def _valor_game_count(user_id, stats: dict | None = None) -> int:
    """Games the user ATTENDED (marked present in the attendance log) — the
    Hearts of Valor requirement. Reservations alone don't count."""
    return sum(1 for game in build_player_game_history(user_id, get_cached_games_data()) if game.get("present"))


def _qualifies_for_valor(user_id, stats: dict) -> bool:
    """Merit + attended-games requirements (warnings / bans checked separately)."""
    return (
        _merit_points(stats) >= G.MERIT_VALOR_THRESHOLD
        and _valor_game_count(user_id, stats) >= G.MERIT_VALOR_GAMES_REQUIRED
    )


def _current_warnings(stats: dict) -> int:
    """Warnings across both modes (any warning blocks the Hearts of Valor promotion)."""
    return int((stats or {}).get("warns", 0) or 0) + int((stats or {}).get("hist_warns", 0) or 0)


def _base_category_for_mode(mode: str) -> str:
    """Collapse a full game mode into a Dishonored base category:
    'Roleplay' / 'Historical'. Anything not clearly Roleplay (historical
    mods, ...) is treated as Historical."""
    if not mode:
        return "Roleplay"
    try:
        mapped = get_mapped_mode(mode)
    except Exception:
        mapped = mode
    if "Roleplay" in (mapped or ""):
        return "Roleplay"
    return "Historical"


def _dishonored_nations_for_category(base_category: str) -> tuple[list, list]:
    """(all_nations, major_nations) representative of a Dishonored base category,
    published to the web Database page's nation pickers."""
    rep = {
        "Roleplay": "Roleplay",
        "Historical": "Historical (Vanilla)",
    }.get(base_category, "Roleplay")
    try:
        return get_all_nations_for_mode(rep), get_major_nations_for_mode(rep)
    except Exception:
        return [], []


def _dishonored_entry_active(entry: dict, now: int | None = None) -> bool:
    if not isinstance(entry, dict):
        return False
    expires_at = int(entry.get("expires_at") or 0)
    if expires_at and int(now or time.time()) >= expires_at:
        return False
    return bool(entry.get("all_majors") or entry.get("majors") or entry.get("minors"))


# The Dishonored role of each branch (server settings → Player roles).
DISHONORED_ROLE_KEYS = {"Roleplay": "DISHONORED", "Historical": "HIST_DISHONORED"}


def _has_active_dishonored(stats: dict, category: str | None = None) -> bool:
    """An active restriction (in one category — Roleplay / Historical — or any)."""
    data = (stats or {}).get("dishonored_data") or {}
    for cat, entry in data.items():
        if category and cat != category:
            continue
        if _dishonored_entry_active(entry):
            return True
    return False


def _dishonored_role_ids() -> set[int]:
    return {int(ROLE_IDS.get(key) or 0) for key in DISHONORED_ROLE_KEYS.values()} - {0}


def _dishonored_summary(entry: dict, cat: str) -> str:
    """Human-readable one-liner of what a single-category restriction bans."""
    parts = []
    if entry.get("all_majors"):
        parts.append("**all Majors**")
    elif entry.get("majors"):
        parts.append("Majors: " + ", ".join(entry["majors"]))
    if entry.get("minors"):
        parts.append("Minors: " + ", ".join(entry["minors"]))
    restr = "; ".join(parts) if parts else "none"
    desc = (entry.get("description") or "").strip()
    issued = entry.get("ts")
    when = f" · since <t:{int(issued)}:d>" if issued else ""
    expires_at = entry.get("expires_at")
    until = f" · until <t:{int(expires_at)}:F> (<t:{int(expires_at)}:R>)" if expires_at else ""
    reason = f"\n **For:** {desc}" if desc else "\n **For:** *(no reason recorded)*"
    return f"**{cat}** — banned from {restr}{when}{until}{reason}"


def _dishonored_full_summary(stats: dict) -> str:
    """Multi-category summary for DMs / /report / confirmations."""
    data = (stats or {}).get("dishonored_data") or {}
    lines = []
    for cat, entry in data.items():
        if not isinstance(entry, dict):
            continue
        if not _dishonored_entry_active(entry):
            continue
        lines.append(f"• {_dishonored_summary(entry, cat)}")
    return "\n".join(lines) if lines else "No active restrictions."


def _dishonored_block_reason(stats: dict, mode: str, nation: str, is_major_nation: bool) -> str | None:
    """Returns a user-facing block message if the Dishonored title bans this
    reservation, else None."""
    data = (stats or {}).get("dishonored_data") or {}
    if not data:
        return None
    cat = _base_category_for_mode(mode)
    entry = data.get(cat)
    if not isinstance(entry, dict):
        # Tolerate older/alternate keys (e.g. full mode name stored by mistake).
        for key, cand in data.items():
            if not isinstance(cand, dict):
                continue
            if _base_category_for_mode(str(key)) == cat:
                entry = cand
                break
    if not isinstance(entry, dict):
        return None
    if not _dishonored_entry_active(entry):
        return None
    base_nation = (nation or "").replace("_coop", "").replace("_FILL_", "")
    majors = set(entry.get("majors") or [])
    minors = set(entry.get("minors") or [])
    all_majors = bool(entry.get("all_majors"))

    if is_major_nation:
        if all_majors:
            return (f"🚫 **Dishonored Title:** You are banned from reserving **all Major nations** in "
                    f"**{cat}** games.\n{_dishonored_summary(entry, cat)}")
        if base_nation in majors:
            return (f"🚫 **Dishonored Title:** You are banned from reserving **{base_nation}** in "
                    f"**{cat}** games.\n{_dishonored_summary(entry, cat)}")
    else:
        if base_nation in minors:
            return (f"🚫 **Dishonored Title:** You are banned from reserving **{base_nation}** in "
                    f"**{cat}** games.\n{_dishonored_summary(entry, cat)}")
    return None


def _member_has_dishonored_role(member) -> bool:
    """True if the member currently holds a Dishonored role (either branch)."""
    ids = _dishonored_role_ids()
    if not ids or member is None:
        return False
    try:
        return any(int(getattr(r, "id", 0) or 0) in ids for r in getattr(member, "roles", []))
    except Exception:
        return False


async def _dishonored_block_for_member(member, mode: str, nation: str, is_major_nation: bool,
                                       stats: dict | None = None) -> str | None:
    """Dishonored check with optional fresh MySQL read when the Discord role is present.

    Ensures a just-issued /sentence (which also grants the Dishonored role) cannot
    be skipped because of a stale player-stats cache.
    """
    uid = str(getattr(member, "id", "") or "")
    resolved = stats
    if resolved is None:
        cache = _get_player_stats_data_sync() or {}
        resolved = cache.get(uid, {}) if uid else {}

    # Role holders: prefer a fresh profile so restriction data matches the badge.
    if member is not None and _member_has_dishonored_role(member):
        try:
            fresh = await get_mysql_player_stats(uid)
            if isinstance(fresh, dict) and fresh:
                resolved = fresh
                if _player_stats_cache is not None:
                    _player_stats_cache[uid] = fresh
        except Exception as e:
            print(f"[WARN] Fresh Dishonored stats read failed for {uid}: {e}")

    return _dishonored_block_reason(resolved, mode, nation, is_major_nation)


async def _get_member_safe(guild, user_id):
    if guild is None or not str(user_id).isdigit():
        return None
    member = guild.get_member(int(user_id))
    if member is None:
        try:
            member = await guild.fetch_member(int(user_id))
        except Exception:
            member = None
    return member


async def _sync_dishonored_role(member, stats) -> None:
    """Each branch's Dishonored role matches whether that branch has an active
    restriction (a server using one role for both: any restriction)."""
    if member is None or member.guild is None:
        return
    wanted: dict[int, bool] = {}
    for category, key in DISHONORED_ROLE_KEYS.items():
        rid = int(ROLE_IDS.get(key) or 0)
        if rid:
            wanted[rid] = wanted.get(rid, False) or _has_active_dishonored(stats, category)
    for rid, active in wanted.items():
        role = member.guild.get_role(rid)
        if not role:
            continue
        has_role = role in member.roles
        try:
            if active and not has_role:
                await member.add_roles(role, reason="Dishonored title active")
            elif not active and has_role:
                await member.remove_roles(role, reason="Dishonored title cleared")
        except Exception as e:
            print(f"[WARN] Dishonored role sync failed for {getattr(member, 'id', '?')}: {e}")


# ==========================================================================
# HEARTS OF VALOR — promotion, perks and the host-approved Trusted pick
# --------------------------------------------------------------------------
# 25 Merit + 50 attended games → the Valor role, unless the user has a game
# ban (never) or a current warning (held back: they're DMed to open a ticket,
# once). Perks: a DM 1 hour before every scheduled game announcement
# (_send_valor_early_notices) and ONE Trusted role of their choice — they
# pick it from the perks DM, the host team approves / declines it in the
# host channel. The approved pick is stored in users.valor_trusted and kept
# while they hold Valor (the role scan won't remove it below 5 commends).
# ==========================================================================
# Where the host team gets Valor Trusted requests and player appeals.
HOST_TEAM_CHANNEL_ID = HOST_LOG_CHANNEL_ID
VALOR_EARLY_NOTICE_SEC = 3600
class _ValorTrustedChoices(collections.abc.Mapping):
    """{"rp": ("Roleplay", RP Trusted role), "hist": ("Historical", MP Trusted role)}
    for the current server (read when used, so each server gets its own roles)."""

    def _d(self) -> dict:
        return {
            "rp": ("Roleplay", ROLE_IDS["HOI4_RP_TRUSTED"]),
            "hist": ("Historical", ROLE_IDS["HOI4_MP_TRUSTED"]),
        }

    def __getitem__(self, key):
        return self._d()[key]

    def __iter__(self):
        return iter(self._d())

    def __len__(self):
        return 2


class _ValorTrustedLabelRole(collections.abc.Mapping):
    """{"Roleplay": role id, "Historical": role id} for the current server."""

    def _d(self) -> dict:
        return {label: role_id for label, role_id in VALOR_TRUSTED_CHOICES.values()}

    def __getitem__(self, key):
        return self._d()[key]

    def __iter__(self):
        return iter(self._d())

    def __len__(self):
        return 2


VALOR_TRUSTED_CHOICES = _ValorTrustedChoices()
_VALOR_TRUSTED_LABEL_ROLE = _ValorTrustedLabelRole()
_VALOR_WARNING_NOTIFIED_KEY = "valor_warning_notified"   # bot_config: uids told "a warning holds it back"
_VALOR_REQUESTS_KEY = "valor_trusted_requests"           # bot_config: {uid: {"mode": label, "ts": int}}
_VALOR_EARLY_NOTIFIED_KEY = "valor_early_notified"       # bot_config: schedule slots already pre-announced


async def _bot_config_mutate(mutator):
    """Read-modify-write one bot_config value set (small, rare writes)."""
    cfg = await read_json(BOT_CONFIG_FILE)
    # The current server's view (a Mapping, not a dict) — never start from {}.
    if not isinstance(cfg, collections.abc.MutableMapping):
        cfg = {}
    result = mutator(cfg)
    await write_json(BOT_CONFIG_FILE, cfg)
    return result


async def _drop_valor_trusted(member, stats: dict, reason: str) -> str | None:
    """Valor lost: remove the Trusted role it gave (unless earned by 5+
    commends or VIP) and forget the pick. Caller saves `stats`."""
    label = stats.get("valor_trusted")
    if not label:
        return None
    stats["valor_trusted"] = None
    role_id = _VALOR_TRUSTED_LABEL_ROLE.get(label)
    ctx = get_mod_context(label)
    if member is None or not role_id or ctx is None or _member_has_vip(member):
        return None
    if int(stats.get(ctx["key_commend"], 0) or 0) >= G.MIN_TRUSTED_COMMENDS:
        return None
    role = member.guild.get_role(role_id)
    if role and role in member.roles:
        try:
            await member.remove_roles(role, reason=reason)
            return f"Removed {role.name} (it came with Hearts of Valor)."
        except Exception as e:
            print(f"[WARN] Valor Trusted removal failed for {member.id}: {e}")
    return None


def build_valor_perks_embed(member, stats: dict) -> discord.Embed:
    embed = discord.Embed(
        title="🎖️ You earned Hearts of Valor!",
        description=(
            f"You reached **{_merit_points(stats)} Merit** and **{_valor_game_count(member.id, stats)} attended "
            f"games**. Thank you for everything you do for the community — here are your perks:"
        ),
        color=discord.Color.gold(),
    )
    embed.add_field(
        name="📣 Early game notice",
        value="You get a DM **1 hour before** every scheduled game announcement, so you can plan ahead.",
        inline=False,
    )
    embed.add_field(
        name="🛡️ A Trusted role of your choice",
        value=(
            "Pick **Roleplay Trusted** or **Historical Trusted** below. "
            "The host team reviews your request and approves it."
        ),
        inline=False,
    )
    return embed


def build_valor_choice_view(user_id, disabled_label: str | None = None) -> discord.ui.View:
    view = discord.ui.View(timeout=None)
    if disabled_label:
        view.add_item(discord.ui.Button(label=disabled_label, style=discord.ButtonStyle.secondary, disabled=True))
        return view
    for key in VALOR_TRUSTED_CHOICES:
        view.add_item(ValorTrustedChoiceButton(key, int(user_id)))
    return view


async def _sync_valor_role(member, stats) -> list[str]:
    """Grant / hold back / remove Hearts of Valor. Returns plain-text notes."""
    notes: list[str] = []
    if member is None or member.guild is None:
        return notes
    if not SERVER_FEATURES.get("valor_merit", True):
        return notes  # Hearts of Valor is switched off in the server settings
    valor_role = member.guild.get_role(ROLE_IDS["VALOR"])
    if valor_role is None:
        return notes
    uid = str(member.id)
    has_role = valor_role in member.roles
    meets = _qualifies_for_valor(member.id, stats)
    banned = _is_game_banned_any(stats)

    if has_role and (banned or not meets):
        reason = "Game banned" if banned else "Hearts of Valor requirements no longer met"
        try:
            await member.remove_roles(valor_role, reason=reason)
            notes.append("Hearts of Valor removed — " + ("game banned." if banned else "requirements no longer met."))
        except Exception as e:
            print(f"[WARN] Valor role removal failed for {member.id}: {e}")
        dropped = await _drop_valor_trusted(member, stats, reason)
        if dropped:
            notes.append(dropped)
        await save_mysql_player_stats(uid, stats)
        return notes
    if has_role or banned or not meets:
        return notes

    attended = _valor_game_count(member.id, stats)
    if _current_warnings(stats) > 0:
        # Held back: tell the user (once) to open a ticket; the host team sees it too.
        def mark(cfg):
            seen = set(str(x) for x in (cfg.get(_VALOR_WARNING_NOTIFIED_KEY) or []))
            first = uid not in seen
            seen.add(uid)
            cfg[_VALOR_WARNING_NOTIFIED_KEY] = sorted(seen)
            return first
        if await _bot_config_mutate(mark):
            await _dm_user_safe(
                member,
                content=(
                    f"🎖️ You have just hit **{_merit_points(stats)} Merit points** and attended "
                    f"**{attended} games** ({G.MERIT_VALOR_GAMES_REQUIRED}+), but your current warning "
                    f"prevents the automatic approval of **Hearts of Valor**. Please open a ticket."
                ),
                label="valor held back",
            )
            held = discord.Embed(
                title="🎖️ Hearts of Valor — held back by a warning",
                description=(
                    f"<@{uid}> has {_merit_points(stats)} Merit and {attended} attended games, but "
                    f"{_current_warnings(stats)} current warning(s). They were told to open a ticket."
                ),
                color=discord.Color.orange(),
            )
            try:
                await send_host_log_embed(held)
            except Exception:
                pass
        notes.append("Meets the Hearts of Valor requirements, but a current warning holds the promotion back.")
        return notes

    try:
        await member.add_roles(
            valor_role,
            reason=f"Hearts of Valor: {G.MERIT_VALOR_THRESHOLD} Merit and {G.MERIT_VALOR_GAMES_REQUIRED} attended games",
        )
    except Exception as e:
        print(f"[WARN] Valor role grant failed for {member.id}: {e}")
        return notes
    notes.append("🎖️ Hearts of Valor earned — perks DM sent (Trusted role pick goes to the host team).")

    def clear_notice(cfg):
        cfg[_VALOR_WARNING_NOTIFIED_KEY] = [x for x in (cfg.get(_VALOR_WARNING_NOTIFIED_KEY) or []) if str(x) != uid]
    await _bot_config_mutate(clear_notice)

    await _dm_user_safe(member, embed=build_valor_perks_embed(member, stats), view=build_valor_choice_view(uid), label="valor perks")
    valor_embed = discord.Embed(
        title="🎖️ Hearts of Valor Earned",
        description=(
            f"{member.mention} earned **Hearts of Valor** with **{_merit_points(stats)} Merit Points** "
            f"and **{attended} attended games**. They can now request a Trusted role of their choice."
        ),
        color=discord.Color.gold(),
    )
    try:
        log_ref = await send_host_log_embed(valor_embed)
    except Exception as e:
        log_ref = None
        print(f"[WARN] Hearts of Valor webhook log failed for {member.id}: {e}")
    record_moderation_event(
        member.id,
        "valor_earned",
        reason=f"{_merit_points(stats)} Merit and {attended} attended games",
        automatic=True,
        log=log_ref,
    )
    return notes


async def _interaction_notice(interaction: discord.Interaction, text: str) -> None:
    try:
        if interaction.response.is_done():
            await interaction.followup.send(text, ephemeral=True)
        else:
            await interaction.response.send_message(text, ephemeral=True)
    except Exception:
        pass


class ValorTrustedChoiceButton(discord.ui.DynamicItem[discord.ui.Button],
                               template=r"valortr:(?P<mode>rp|hist):(?P<uid>\d+)(?::g\d+)?"):
    """Perks DM: the Valor holder picks the Trusted role they want (restart-proof)."""

    def __init__(self, mode: str, user_id: int):
        self.mode, self.user_id = mode, int(user_id)
        label, _ = VALOR_TRUSTED_CHOICES[mode]
        super().__init__(discord.ui.Button(
            label=f"{label} Trusted",
            emoji="🎭" if mode == "rp" else "⚔️",
            style=discord.ButtonStyle.primary,
            custom_id=f"valortr:{mode}:{user_id}{_guild_suffix()}",
        ))

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(match["mode"], int(match["uid"]))

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.user_id:
            return await _interaction_notice(interaction, "❌ This choice belongs to someone else.")
        label, _ = VALOR_TRUSTED_CHOICES[self.mode]
        uid = str(self.user_id)
        guild = bot.get_guild(cur_gid())
        member = await _get_member_safe(guild, uid)
        if member is None or member.get_role(ROLE_IDS["VALOR"]) is None:
            return await _interaction_notice(interaction, "ℹ️ You don't hold Hearts of Valor right now.")
        stats = await _load_stats_for_write(uid)
        if stats.get("valor_trusted"):
            return await _interaction_notice(interaction, f"ℹ️ Your **{stats['valor_trusted']} Trusted** pick was already approved.")

        def add_request(cfg):
            pending = dict(cfg.get(_VALOR_REQUESTS_KEY) or {})
            if uid in pending:
                return pending[uid].get("mode")
            pending[uid] = {"mode": label, "ts": int(time.time())}
            cfg[_VALOR_REQUESTS_KEY] = pending
            return None
        existing = await _bot_config_mutate(add_request)
        if existing:
            return await _interaction_notice(interaction, f"⏳ You already asked for **{existing} Trusted** — the host team will get back to you.")

        channel = bot.get_channel(G.HOST_TEAM_CHANNEL_ID)
        request = discord.Embed(
            title="🎖️ Hearts of Valor — Trusted request",
            description=f"<@{uid}> holds **Hearts of Valor** and asks for **{label} Trusted**.",
            color=discord.Color.gold(),
        )
        request.add_field(name="Merit", value=str(_merit_points(stats)), inline=True)
        request.add_field(name="Attended games", value=str(_valor_game_count(uid, stats)), inline=True)
        request.add_field(name="Warnings", value=str(_current_warnings(stats)), inline=True)
        view = discord.ui.View(timeout=None)
        view.add_item(ValorTrustedDecisionButton("ok", self.mode, self.user_id))
        view.add_item(ValorTrustedDecisionButton("no", self.mode, self.user_id))
        try:
            await channel.send(embed=request, view=view)
        except Exception as e:
            print(f"[WARN] Valor Trusted request post failed: {e}")
        try:
            await interaction.response.edit_message(view=build_valor_choice_view(uid, f"Requested: {label} Trusted"))
        except Exception:
            pass
        await _interaction_notice(interaction, f"📨 Request sent — the host team will review your **{label} Trusted** pick.")


class ValorTrustedDecisionButton(discord.ui.DynamicItem[discord.ui.Button],
                                 template=r"valortrdec:(?P<decision>ok|no):(?P<mode>rp|hist):(?P<uid>\d+)"):
    """Host channel: approve / decline a Valor holder's Trusted pick (restart-proof)."""

    def __init__(self, decision: str, mode: str, user_id: int):
        self.decision, self.mode, self.user_id = decision, mode, int(user_id)
        super().__init__(discord.ui.Button(
            label="Approve" if decision == "ok" else "Decline",
            emoji="✅" if decision == "ok" else "✖️",
            style=discord.ButtonStyle.success if decision == "ok" else discord.ButtonStyle.danger,
            custom_id=f"valortrdec:{decision}:{mode}:{user_id}",
        ))

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(match["decision"], match["mode"], int(match["uid"]))

    async def callback(self, interaction: discord.Interaction):
        if not _member_is_host(interaction.user):
            return await _interaction_notice(interaction, "❌ Only the host team can decide this.")
        await interaction.response.defer(ephemeral=True)
        label, role_id = VALOR_TRUSTED_CHOICES[self.mode]
        uid = str(self.user_id)
        member = await _get_member_safe(interaction.guild, uid)
        stats = await _load_stats_for_write(uid)
        outcome = ""
        if self.decision == "ok":
            # The Trusted role needs the Verified role of its own game type.
            verified = interaction.guild.get_role(_verified_role_id(label))
            if member is None:
                return await interaction.followup.send("❌ That user is no longer in the server.", ephemeral=True)
            if member.get_role(ROLE_IDS["VALOR"]) is None:
                return await interaction.followup.send("❌ They no longer hold Hearts of Valor.", ephemeral=True)
            if _is_game_banned_any(stats):
                return await interaction.followup.send("❌ Game-banned players can't get Trusted.", ephemeral=True)
            if verified is not None and verified not in member.roles:
                return await interaction.followup.send(
                    f"❌ {label} Trusted needs the {VERIFIED_TRACKS[label]['label']} role first.", ephemeral=True
                )
            role = interaction.guild.get_role(role_id)
            try:
                if role and role not in member.roles:
                    await member.add_roles(role, reason=f"Hearts of Valor pick approved by {interaction.user.display_name}")
            except Exception as e:
                return await interaction.followup.send(f"❌ Couldn't add the role: `{e}`", ephemeral=True)
            stats["valor_trusted"] = label
            await save_mysql_player_stats(uid, stats)
            outcome = f"✅ Approved by {interaction.user.mention}"
            await _dm_user_safe(member, content=f"🛡️ The host team approved your **{label} Trusted** role — enjoy!", label="valor approved")
            record_moderation_event(uid, "valor_trusted", mode=label, reason="Hearts of Valor perk", actor_id=interaction.user.id)
        else:
            outcome = f"✖️ Declined by {interaction.user.mention}"
            target = member or await _resolve_dm_target(int(uid))
            if target is not None:
                await _dm_user_safe(
                    target,
                    content=f"🛡️ Your **{label} Trusted** request wasn't approved this time. Open a ticket if you'd like to know more.",
                    label="valor declined",
                )

        def drop_request(cfg):
            pending = dict(cfg.get(_VALOR_REQUESTS_KEY) or {})
            pending.pop(uid, None)
            cfg[_VALOR_REQUESTS_KEY] = pending
        await _bot_config_mutate(drop_request)
        try:
            embed = interaction.message.embeds[0] if interaction.message and interaction.message.embeds else None
            if embed is not None:
                embed.add_field(name="Decision", value=outcome, inline=False)
            await interaction.message.edit(embed=embed, view=None)
        except Exception as e:
            print(f"[WARN] Valor decision message edit failed: {e}")
        await interaction.followup.send(outcome, ephemeral=True)


# ==========================================================================
# ACKNOWLEDGE / APPEAL — buttons on warning, game ban and Dishonored DMs
# --------------------------------------------------------------------------
# Acknowledge just marks the DM as read. Appeal opens a short form; the
# appeal goes to the host team channel and into moderation_events (it shows
# on the player's record on the web Database page). Both work once.
# ==========================================================================
def build_moderation_feedback_view(done_label: str | None = None) -> discord.ui.View:
    view = discord.ui.View(timeout=None)
    if done_label:
        view.add_item(discord.ui.Button(label=done_label, style=discord.ButtonStyle.secondary, disabled=True))
        return view
    view.add_item(ModerationFeedbackButton("ack"))
    view.add_item(ModerationFeedbackButton("appeal"))
    return view


def _moderation_dm_summary(message) -> tuple[str, str | None]:
    """(plain summary, mode) of a moderation DM, from its embed or text."""
    if message is not None and message.embeds:
        embed = message.embeds[0]
        lines = [embed.title or "Moderation update"]
        lines += [f"{field.name}: {field.value}" for field in embed.fields]
        text = "\n".join(lines)
    else:
        text = (getattr(message, "content", "") or "Moderation update").strip()
    mode = next((m for m in DISHONORED_CATEGORIES if m in text), None)
    return text[:1000], mode


class ModerationAppealModal(discord.ui.Modal, title="Appeal"):
    appeal = discord.ui.TextInput(
        label="Why should the host team reconsider?",
        style=discord.TextStyle.paragraph,
        min_length=10,
        max_length=1000,
        placeholder="Explain what happened from your side.",
    )

    def __init__(self, dm_message):
        super().__init__()
        self.dm_message = dm_message

    async def on_submit(self, interaction: discord.Interaction):
        summary, mode = _moderation_dm_summary(self.dm_message)
        embed = discord.Embed(
            title="📨 Appeal",
            description=f"<@{interaction.user.id}> appealed:",
            color=discord.Color.blurple(),
            timestamp=discord.utils.utcnow(),
        )
        embed.add_field(name="About", value=_trim_field(summary), inline=False)
        embed.add_field(name="Appeal", value=_trim_field(str(self.appeal.value)), inline=False)
        embed.set_footer(text="Answer the player via a ticket / DM. Change the record on the web Database page.")
        channel = bot.get_channel(G.HOST_TEAM_CHANNEL_ID)
        try:
            await channel.send(embed=embed)
        except Exception as e:
            print(f"[WARN] Appeal post failed: {e}")
            return await _interaction_notice(interaction, "⚠️ Couldn't send your appeal right now — please open a ticket instead.")
        record_moderation_event(
            interaction.user.id,
            "appeal",
            mode=mode,
            reason=str(self.appeal.value),
            actor_id=interaction.user.id,
            details={"about": summary[:300]},
        )
        try:
            await self.dm_message.edit(view=build_moderation_feedback_view("📨 Appeal sent"))
        except Exception:
            pass
        await _interaction_notice(interaction, "📨 Your appeal was sent to the host team. They'll get back to you.")


class ModerationFeedbackButton(discord.ui.DynamicItem[discord.ui.Button],
                               template=r"modfb:(?P<action>ack|appeal)(?::g\d+)?"):
    """Acknowledge (green) / Appeal (red) on a moderation DM (restart-proof)."""

    def __init__(self, action: str):
        self.action = action
        super().__init__(discord.ui.Button(
            label="Acknowledge" if action == "ack" else "Appeal",
            emoji="✅" if action == "ack" else "📨",
            style=discord.ButtonStyle.success if action == "ack" else discord.ButtonStyle.danger,
            custom_id=f"modfb:{action}{_guild_suffix()}",
        ))

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(match["action"])

    async def callback(self, interaction: discord.Interaction):
        if self.action == "ack":
            try:
                await interaction.response.edit_message(view=build_moderation_feedback_view("✅ Acknowledged"))
            except Exception:
                await _interaction_notice(interaction, "✅ Acknowledged.")
            return
        await interaction.response.send_modal(ModerationAppealModal(interaction.message))


async def _send_valor_early_notices(schedule_data: list, locked_days, now: int) -> None:
    """Hearts of Valor perk: DM every Valor holder 1 hour before each
    scheduled game announcement (once per slot)."""
    due = []
    for item in schedule_data or []:
        ann = item.get("announce_timestamp")
        if not ann or item.get("announced") or not (int(ann) - VALOR_EARLY_NOTICE_SEC <= now < int(ann)):
            continue
        if _find_day_lock(locked_days, _item_week(item), item.get("day")):
            continue
        due.append((f"{int(ann)}:{item.get('host_id')}:{item.get('mode')}", item))
    if not due:
        return

    def claim(cfg):
        sent = [str(x) for x in (cfg.get(_VALOR_EARLY_NOTIFIED_KEY) or [])]
        fresh = [(key, item) for key, item in due if key not in sent]
        # Keep two days of keys (they start with the announce timestamp).
        sent = [x for x in sent if int(x.split(":", 1)[0] or 0) > now - 2 * 86400] + [key for key, _ in fresh]
        cfg[_VALOR_EARLY_NOTIFIED_KEY] = sent
        return fresh
    fresh = await _bot_config_mutate(claim)
    guild = bot.get_guild(cur_gid())
    valor_role = guild.get_role(ROLE_IDS["VALOR"]) if guild else None
    if not fresh or valor_role is None:
        return
    holders = [m for m in valor_role.members if not m.bot]
    for _key, item in fresh:
        ann = int(item["announce_timestamp"])
        host = guild.get_member(item.get("host_id")) if item.get("host_id") else None
        embed = discord.Embed(
            title="📣 Early notice — Hearts of Valor",
            description=(
                f"A **{resolve_mode_name(item.get('mode')) or 'game'}** game"
                f"{f' hosted by **{host.display_name}**' if host else ''} will be announced "
                f"<t:{ann}:R> (<t:{ann}:t>)."
                + (f"\nThe game starts <t:{int(item['game_timestamp'])}:F>." if item.get("game_timestamp") else "")
            ),
            color=discord.Color.gold(),
        )
        for member in holders:
            async with _discord_api_sem:
                await _dm_user_safe(member, embed=embed, label="valor early notice")
            await asyncio.sleep(0.3)


async def _load_stats_for_write(user_id) -> dict:
    """Fetch a user's stats, preferring the warm cache so we don't clobber it."""
    uid = str(user_id)
    if _player_stats_cache and uid in _player_stats_cache:
        return _player_stats_cache[uid]
    return await get_mysql_player_stats(uid)


async def _apply_merit_change(user_id, delta: int, *, reason: str = "", issuer=None, guild=None) -> dict:
    """Add (delta>0) or remove (delta<0) merit points and sync Hearts of
    Valor. Merit never turns into commends and never touches warnings.

    Returns merit, Valor notes, member, and stats details.
    """
    uid = str(user_id)
    stats = await _load_stats_for_write(uid)

    old = _merit_points(stats)
    new = max(0, old + int(delta))
    stats["merit_points"] = new
    await save_mysql_player_stats(uid, stats)

    if guild is None:
        guild = bot.get_guild(cur_gid())
    member = await _get_member_safe(guild, uid)

    notes: list[str] = []
    if member:
        notes = await _sync_valor_role(member, stats)

    return {"old": old, "new": new, "notes": notes, "member": member, "stats": stats}


async def _set_dishonored_restriction(user_id, base_category: str, *, all_majors: bool,
                                      majors: list, minors: list, description: str,
                                      issuer_id, duration_days: int, guild=None) -> dict:
    """Give (set/replace) a Dishonored restriction for one base category.

    A time-out only: it blocks the chosen nations until it expires and leaves
    every stat and role untouched (besides the Dishonored marker role)."""
    uid = str(user_id)
    stats = await _load_stats_for_write(uid)
    data = dict(stats.get("dishonored_data") or {})
    issued_at = int(time.time())
    data[base_category] = {
        "all_majors": bool(all_majors),
        "majors": list(majors or []),
        "minors": list(minors or []),
        "description": description or "",
        "issued_by": issuer_id,
        "ts": issued_at,
        "expires_at": issued_at + (int(duration_days) * 86400),
    }
    stats["dishonored_data"] = data
    stats["dishonored"] = _has_active_dishonored(stats)
    await save_mysql_player_stats(uid, stats)

    if guild is None:
        guild = bot.get_guild(cur_gid())
    member = await _get_member_safe(guild, uid)
    if member:
        await _sync_dishonored_role(member, stats)
    return {"stats": stats, "member": member}


async def _clear_dishonored_restriction(user_id, base_category: str, guild=None) -> dict:
    """Take (remove) a Dishonored restriction for one base category."""
    uid = str(user_id)
    stats = await _load_stats_for_write(uid)
    data = dict(stats.get("dishonored_data") or {})
    existed = base_category in data
    data.pop(base_category, None)
    stats["dishonored_data"] = data
    stats["dishonored"] = _has_active_dishonored(stats)
    await save_mysql_player_stats(uid, stats)

    if guild is None:
        guild = bot.get_guild(cur_gid())
    member = await _get_member_safe(guild, uid)
    if member:
        await _sync_dishonored_role(member, stats)
    return {"stats": stats, "member": member, "existed": existed}

async def is_not_banned(interaction: discord.Interaction) -> bool:
    user = interaction.user
    user_roles = [r.id for r in user.roles]

    # 1. Check if we are in a game thread to be specific
    games_data = get_cached_games_data()
    thread_id = str(interaction.channel.id)

    if thread_id in games_data:
        mode = games_data[thread_id].get("mode", "Roleplay")
        config = MODE_CONFIG.get(mode, {})
        ban_role_id = config.get("banned_role_id")

        if ban_role_id and ban_role_id in user_roles:
            await interaction.response.send_message("❌ You are banned from this game mode.", ephemeral=True)
            return False
    else:
        # 2. Global Check
        if any(ban_id in user_roles for ban_id in ALL_BAN_IDS):
            await interaction.response.send_message("❌ You are Game Banned.", ephemeral=True)
            return False

    # 3. Ban check — cache only (never block the event loop with MySQL during checks).
    cached = get_cached_player_stats()
    if cached and cached.get(str(user.id), {}).get("banned"):
        await interaction.response.send_message("❌ You are flagged as banned in database.", ephemeral=True)
        return False

    return True


