def get_mapped_mode(mode: str) -> str:
    if not mode: return "Roleplay"

    # --- MOD-SPECIFIC MAPPINGS ---
    if "Novum Vexillum" in mode:
        return "Roleplay (Novum Vexillum)"
    if "Millennium Dawn" in mode or "MD" in mode:
        return "Roleplay (Millennium Dawn)"
    if "Kaiserreich" in mode or "KR" in mode:
        return "Kaiserreich (FFA)"

    # --- HISTORICAL VARIANTS ---
    if "TFB" in mode: return "Historical (TFB)"
    if "Oak" in mode: return "Historical (Oak)"
    if "Horst" in mode: return "Historical (Horst)"
    if "BFFU" in mode: return "Historical (BFFU)"
    if "Vanilla" in mode or "Historical" in mode: return "Historical (Vanilla)"

    # Fallback to standard RP
    return "Roleplay"


def is_roleplay_family_mode(mode: str) -> bool:
    """True for Roleplay-style reservation boards (including Kaiserreich FFA).

    After the KR rename, get_mapped_mode() returns 'Kaiserreich (FFA)', which
    no longer contains 'Roleplay' — without this check the list builder
    falls through to 'Unknown Game Mode'.
    """
    mapped = get_mapped_mode(mode or "")
    return (
        "Roleplay" in mapped
        or "Kaiserreich" in mapped
    )

