def get_all_nations_for_mode(mode: str) -> List[str]:
    # --- TFR OVERRIDE ---
    if mode == "TFR" and 'TFR_DATA' in globals():
        return list(TFR_DATA["Nations"].keys())

    cat_key = get_mapped_mode(mode)
    data = NATION_CATEGORIES.get(cat_key, {})
    all_nations = []

    for key, val in data.items():
        # Handle Historical/faction nested structures (Majors/Minors groups)
        if isinstance(val, dict):
            for group_list in val.values():
                if isinstance(group_list, list):
                    all_nations.extend(group_list)
        # Handle RP/MD/KR flat lists (Europe: [Nation, Nation])
        elif isinstance(val, list):
            all_nations.extend(val)

    return sorted(list(set(all_nations)))


def get_major_nations_for_mode(mode: str) -> list:
    # --- TFR OVERRIDE ---
    if mode == "TFR" and 'TFR_DATA' in globals():
        majors = []
        for fac in TFR_DATA["Factions"].values():
            majors.extend(fac.get("Majors", []))
        return majors

    # Safely define variables for standard modes
    cat_key = get_mapped_mode(mode)
    data = NATION_CATEGORIES.get(cat_key, {})

    if "Roleplay" in cat_key:
        # Flat Roleplay modes use a top-level "Majors" list; faction-based ones
        # (Kaiserreich) nest "Majors" inside each faction dict.
        majors = list(data.get("Majors", []))
        for structure in data.values():
            if isinstance(structure, dict) and isinstance(structure.get("Majors"), list):
                majors.extend(structure["Majors"])
        return majors

    # Grabs Majors from each faction (Axis/Allies/...)
    majors = []
    for faction, structure in data.items():
        if isinstance(structure, dict) and "Majors" in structure:
            majors.extend(structure["Majors"])
    return majors


_nations_by_mode_cache: dict[str, tuple[list, set]] = {}


def _get_mode_nation_data(mode: str) -> tuple[list, set]:
    """Cached (all_nations, majors_set) for autocomplete — built once per mode."""
    cached = _nations_by_mode_cache.get(mode)
    if cached is not None:
        return cached

    if mode == "TFR" and 'TFR_DATA' in globals():
        all_nations = list(TFR_DATA["Nations"].keys())
        majors_set = set(get_major_nations_for_mode(mode))
    else:
        all_nations = get_all_nations_for_mode(mode)
        majors_set = set(get_major_nations_for_mode(mode))

    cached = (all_nations, majors_set)
    _nations_by_mode_cache[mode] = cached
    return cached


def _build_locked_nation_set(mode: str, locked_list: list) -> frozenset:
    """Expand region locks into a nation set once (O(regions), not O(nations×regions))."""
    if not locked_list:
        return frozenset()

    locked_set = set(locked_list)
    locked_region_names = set(locked_list)
    cat_key = get_mapped_mode(mode)
    config = NATION_CATEGORIES.get(cat_key, {})
    for region_name, content in config.items():
        if region_name not in locked_region_names:
            continue
        if isinstance(content, list):
            locked_set.update(content)
        elif isinstance(content, dict):
            for group_nations in content.values():
                if isinstance(group_nations, list):
                    locked_set.update(group_nations)
    return frozenset(locked_set)


def _warm_nation_list_caches():
    """Pre-build nation lists at startup so first autocomplete keystroke is instant."""
    for mode in MODE_CONFIG.keys():
        try:
            _get_mode_nation_data(mode)
        except Exception:
            pass
    for mode in ("TFR",):
        try:
            _get_mode_nation_data(mode)
        except Exception:
            pass


def is_major(nation: str, mode: str) -> bool:
    # --- TFR OVERRIDE ---
    if mode == "TFR" and 'TFR_DATA' in globals():
        return nation in get_major_nations_for_mode(mode)

    return nation in get_major_nations_for_mode(mode)


# ==========================================================================
# MAJOR STREAK COOLDOWN HELPERS
# A player who plays a Major must play one Minor (and be logged present) before
# they can take another Major. VIP members bypass this restriction entirely.
# ==========================================================================
def _member_has_vip(member) -> bool:
    """VIP STATUS — SINGLE SOURCE OF TRUTH: the member's LIVE Discord roles.

    No MySQL `is_vip` column and no `users`-table lookups are consulted for
    VIP checks. The Discord session claims (the member object's role set)
    are the sole authority; the resolved boolean is stamped onto the
    single-use web token at mint time so the web app never needs to query
    Discord (or any database) for VIP status."""
    vip_id = ROLE_IDS.get("VIP_ROLE_ID")
    if vip_id and member is not None:
        try:
            # Prefer get_role when available (Member), else scan role ids.
            if hasattr(member, "get_role"):
                return member.get_role(int(vip_id)) is not None
            return any(
                int(getattr(r, "id", 0) or 0) == int(vip_id)
                for r in getattr(member, "roles", [])
            )
        except Exception:
            pass
    return False


def _user_is_vip(guild, user_id) -> bool:
    """VIP check by guild + user id (for attendance / background paths)."""
    if guild is None or not str(user_id).isdigit():
        return False
    member = guild.get_member(int(user_id))
    return _member_has_vip(member)


def _backfill_vip_flags_mysql(user_ids: list) -> int:
    """STARTUP VIP BACKFILL (MySQL worker — runs off the event loop).

    Set `users.vip = 1` for every given Discord id:
      · primary path: INSERT ... ON DUPLICATE KEY UPDATE — covers existing
        rows AND creates minimal rows for VIPs the table hasn't met yet,
      · fallback path: plain UPDATE when the table shape rejects the minimal
        INSERT (older schemas with NOT-NULL columns without defaults).

    Returns the number of rows touched."""
    if not user_ids:
        return 0
    conn = None
    cur = None
    touched = 0
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        ids = [int(u) for u in user_ids]
        try:
            cur.executemany(
                "INSERT INTO users (discord_id, vip) VALUES (%s, 1) "
                "ON DUPLICATE KEY UPDATE vip = 1",
                [(u,) for u in ids],
            )
            touched += cur.rowcount
        except Exception as insert_err:
            # Legacy table shape — fall back to touching existing rows only.
            print(f"[VIP-BACKFILL] minimal INSERT unavailable, falling back to UPDATE: {insert_err}")
            placeholders = ",".join(["%s"] * len(ids))
            cur.execute(
                f"UPDATE users SET vip = 1 WHERE discord_id IN ({placeholders}) "
                f"AND (vip IS NULL OR vip = 0)",
                tuple(ids),
            )
            touched += cur.rowcount
        conn.commit()
    except Exception as e:
        print(f"[VIP-BACKFILL] MySQL write failed: {e}")
        return 0
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return touched


async def _backfill_users_vip_flags() -> None:
    if cur_gid() != GUILD_ID:
        return  # one-time home-server migration
    """STARTUP VIP BACKFILL — existing holders of the Discord VIP role get
    `users.vip = 1` in MySQL automatically, so the dual VIP lookup's MySQL
    half works for every current VIP without waiting for /make_vip re-grants.

    Runs once per cold boot, immediately AFTER the users schema self-heal
    (which creates the `vip` column). Best-effort: never raises, never
    blocks startup — the live Discord role check remains authoritative
    regardless of backfill success."""
    try:
        vip_id = ROLE_IDS.get("VIP_ROLE_ID")
        guild = bot.get_guild(cur_gid())
        if guild is None or not vip_id:
            print("[VIP-BACKFILL] skipped — guild or VIP_ROLE_ID unavailable")
            return
        vip_holders = [
            m.id
            for m in list(guild.members)
            if m.get_role(int(vip_id)) is not None
        ]
        if not vip_holders:
            print("[VIP-BACKFILL] no VIP role holders in the member cache — nothing to backfill")
            return
        touched = await _run_mysql_io(
            _backfill_vip_flags_mysql, vip_holders, label="vip backfill"
        )
        # Mirror the flag into the in-memory stats cache too, so
        # _member_has_vip's DB fallback sees it immediately even if the
        # cache was warmed before (or without) a full MySQL refresh.
        cache = get_cached_player_stats() or {}
        for uid in vip_holders:
            entry = cache.setdefault(str(uid), {})
            if isinstance(entry, dict):
                entry["vip"] = True
        print(
            f"[VIP-BACKFILL] ✅ {len(vip_holders)} VIP role holders processed "
            f"({touched or 0} users rows touched) — `users.vip` backfilled."
        )
    except Exception as e:
        print(f"[VIP-BACKFILL] failed (startup continues): {e}")


def _is_on_major_cooldown(games_data: dict, user_id, mode: str, exclude_thread_id=None) -> bool:
    """True if the player's last logged participation in this mode was a Major.
    Only counts games where the player was actually marked present — reservations
  alone (or cancelled games) do not advance the streak."""
    if "Roleplay" not in (mode or ""):
        return False
    last = _last_participated_nation_in_mode(games_data, user_id, mode, exclude_thread_id)
    if not last:
        return False
    try:
        return is_major(last, mode)
    except Exception:
        return False


def _last_major_nation(games_data: dict, user_id, mode: str, exclude_thread_id=None) -> str:
    """The Major nation the player most recently logged as present in this mode."""
    if _is_on_major_cooldown(games_data, user_id, mode, exclude_thread_id):
        last = _last_participated_nation_in_mode(games_data, user_id, mode, exclude_thread_id)
        if last:
            return last
    return "a Major"


