async def create_game_voice_channels(guild, game_mode, reservations, game_id):

    # ==========================================
    # 1. DYNAMIC GAMER PASS CREATION & ASSIGNMENT
    # ==========================================
    gamer_pass_role = await guild.create_role(
        name=f"🎮 {game_mode} Pass",
        permissions=discord.Permissions.none(),
        reason=f"Dynamic Gamer Pass for game {game_id}"
    )

    # NOTE: The pass role is intentionally NOT assigned to reserved players here.
    # Players now receive it individually only after confirming participation via
    # the "Yes" button in their game-start DM (see ParticipationButton).

    # Filter out fillers and co-ops for VC logic
    active_res = {k: v for k, v in reservations.items() if not k.startswith("_FILL_") and "_coop" not in k}

    # ==========================================
    # 2. PERMISSIONS SETUP
    # ==========================================
    base_overwrites = {guild.default_role: discord.PermissionOverwrite(view_channel=False)}
    base_overwrites[gamer_pass_role] = discord.PermissionOverwrite(view_channel=True, connect=True)

    # Host Management (server settings → Staff & access) manages these channels.
    for manager_role_id in GAME_VOICE_MANAGER_ROLES:
        manager_role = guild.get_role(int(manager_role_id))
        if manager_role:
            base_overwrites[manager_role] = discord.PermissionOverwrite(
                view_channel=True, manage_channels=True, manage_permissions=True, connect=True, move_members=True,
                manage_messages=True,
            )

    host_roles = globals().get("ALLOWED_HOST_ROLES", [])
    for r_id in host_roles:
        role = guild.get_role(r_id)
        if role:
            base_overwrites[role] = discord.PermissionOverwrite(view_channel=True, connect=True, move_members=True)

    # ==========================================
    # 3. CHANNEL GENERATION PREP
    # ==========================================
    voice_bucket = _base_category_for_mode(game_mode)
    # Where game voice categories go (server settings → Channels).
    anchor_id, lower_anchor_id = GAME_VOICE_ANCHORS["HIST" if voice_bucket == "Historical" else "RP"]

    top_cat = guild.get_channel(anchor_id)
    lower_cat = guild.get_channel(lower_anchor_id) if lower_anchor_id else None
    target_pos = top_cat.position + 1 if top_cat else 1

    gen_chan_ids, gen_cat_ids = [], []
    created_categories = [] # Store category objects to force-sort them at the end
    placed_nations = set()
    kaiserreich_faction_vcs_only = False

    cat_key = get_mapped_mode(game_mode) if 'get_mapped_mode' in globals() else game_mode
    mode_data = NATION_CATEGORIES.get(cat_key, {})
    fillers_list = FILLER_NATIONS_BY_MODE.get(cat_key, [])

    # ==========================================
    # PHASE 2D: TFR
    # ==========================================
    if game_mode == "TFR" and 'TFR_DATA' in globals():
        tfr_f = TFR_DATA["Factions"]
        for fac_key, header in TFR_FACTION_HEADERS.items():
            nation_pool = [*tfr_f[fac_key].get("Majors", []), *tfr_f[fac_key].get("Minors", [])]
            # Preserve Majors-first ordering, then minors, only for reserved slots.
            nations_in_cat = [n for n in nation_pool if n in active_res and n not in placed_nations]
            if nations_in_cat:
                new_cat = await guild.create_category(name=f"🌍 {header}", overwrites=base_overwrites, position=target_pos)
                gen_cat_ids.append(new_cat.id)
                created_categories.append(new_cat)
                target_pos += 1
                await _create_vcs_batched(new_cat, nations_in_cat, gen_chan_ids, placed_nations)

    # ==========================================
    # PHASE 2E: KAISERREICH FFA (fixed faction voice channels)
    # ==========================================
    elif "Kaiserreich" in game_mode:
        kaiserreich_faction_vcs_only = True
        KAISERREICH_VOICE_CHANNELS = [
            "Reichspact",
            "Donau-Adriabund",
            "3rd Internationale",
            "Moscow Accord",
            "Co-prosperity sphere",
            "Entente",
        ]
        new_cat = await guild.create_category(
            name="🎮 KAISERREICH FFA", overwrites=base_overwrites, position=target_pos
        )
        gen_cat_ids.append(new_cat.id)
        created_categories.append(new_cat)
        target_pos += 1
        await _create_vcs_batched(new_cat, KAISERREICH_VOICE_CHANNELS, gen_chan_ids, placed_nations)

    # ==========================================
    # PHASE 3: HISTORICAL / FACTION BASED
    # ==========================================
    elif "Historical" in game_mode:
        for faction, groups in mode_data.items():
            f_majors = [n for n in groups.get("Majors", []) if n in active_res]
            f_imps = [n for n in groups.get("Important Minors", []) if n in active_res]
            f_mins = sorted([n for n in groups.get("Minors", []) if n in active_res])

            final_f_list = f_majors + f_imps + f_mins
            if final_f_list:
                new_cat = await guild.create_category(name=f"🛡️ {faction.upper()}", overwrites=base_overwrites, position=target_pos)
                gen_cat_ids.append(new_cat.id)
                created_categories.append(new_cat)
                target_pos += 1
                await _create_vcs_batched(new_cat, final_f_list, gen_chan_ids, placed_nations)

    # ==========================================
    # PHASE 4: REGIONAL (Standard RP)
    # ==========================================
    else:
        regions_to_use = REGION_GROUPS

        all_majors = get_major_nations_for_mode(game_mode)

        for cat_name, sub_regions in regions_to_use.items():
            found_majors, found_minors = [], []

            for sub in sub_regions:
                nations_in_sub = mode_data.get(sub, [])
                for n in nations_in_sub:
                    if n in active_res and n not in placed_nations:
                        if n in all_majors: found_majors.append(n)
                        else: found_minors.append(n)
                        placed_nations.add(n)

            # Check for Majors assigned via MAJOR_LOCATIONS logic
            for res_nation in active_res:
                if res_nation in all_majors and res_nation not in placed_nations:
                    if MAJOR_LOCATIONS.get(res_nation) == cat_name:
                        found_majors.append(res_nation)
                        placed_nations.add(res_nation)

            if found_majors or found_minors:
                found_minors.sort()
                final_order = found_majors + found_minors
                new_cat = await guild.create_category(name=f"🎮 {cat_name.upper()}", overwrites=base_overwrites, position=target_pos)
                gen_cat_ids.append(new_cat.id)
                created_categories.append(new_cat)
                target_pos += 1
                await _create_vcs_batched(new_cat, final_order, gen_chan_ids, placed_nations)

    # ==========================================
    # PHASE 5: FILLER NATIONS
    # ==========================================
    reserved_fillers = [n for n in reservations.keys() if n.startswith("_FILL_") or n in fillers_list]
    unplaced_fillers = [n for n in reserved_fillers if n not in placed_nations]

    if unplaced_fillers and not kaiserreich_faction_vcs_only:
        unplaced_fillers.sort()
        fill_cat = await guild.create_category(name="📦 FILLER NATIONS", overwrites=base_overwrites, position=target_pos)
        gen_cat_ids.append(fill_cat.id)
        created_categories.append(fill_cat)
        target_pos += 1
        filler_names = [n.replace("_FILL_", "") for n in unplaced_fillers]
        await _create_vcs_batched(fill_cat, filler_names, gen_chan_ids)
        placed_nations.update(unplaced_fillers)

    # ==========================================
    # PHASE 6: UNMAPPED NATIONS
    # ==========================================
    leftovers = [n for n in active_res if n not in placed_nations]
    if leftovers and not kaiserreich_faction_vcs_only:
        leftovers.sort()
        safe_cat = await guild.create_category(name="⚠️ UNMAPPED NATIONS", overwrites=base_overwrites, position=target_pos)
        gen_cat_ids.append(safe_cat.id)
        created_categories.append(safe_cat)
        target_pos += 1
        await _create_vcs_batched(safe_cat, leftovers, gen_chan_ids)

    # ==========================================
    # FINAL SORTING FORCE (THE SAFETY NET)
    # ==========================================
    insert_pos = top_cat.position + 1 if top_cat else 1
    # Reinsert in reverse at the same slot. This keeps every generated category
    # contiguous directly below its mode anchor and pushes the lower anchor down,
    # instead of allowing Discord's position shifts to scatter the categories.
    for cat_obj in reversed(created_categories):
        try:
            await cat_obj.edit(position=insert_pos)
        except Exception as e:
            print(f"Failed to force sort category {cat_obj.name}: {e}")

    if lower_cat and created_categories:
        refreshed_lower = guild.get_channel(lower_cat.id)
        if refreshed_lower and any(cat.position >= refreshed_lower.position for cat in created_categories):
            print(
                f"[WARN] Generated {voice_bucket} categories could not all be placed "
                f"before lower anchor {refreshed_lower.name}."
            )

    return gen_cat_ids, gen_chan_ids, gamer_pass_role.id


# CLEANUP FUNCTION
async def cleanup_game_voice_channels(guild, cat_ids, vc_ids, role_id=None):
    """Deletes game-related voice channels, categories, and the dynamic Gamer Pass role."""
    for i in range(0, len(vc_ids), 5):
        for vc_id in vc_ids[i:i + 5]:
            try:
                async with _discord_api_sem:
                    channel = guild.get_channel(int(vc_id))
                    if channel is None:
                        channel = await guild.fetch_channel(int(vc_id))
                    if channel:
                        await channel.delete()
            except Exception as e:
                print(f"Error deleting VC {vc_id}: {e}")
        if i + 5 < len(vc_ids):
            await asyncio.sleep(1.0)

    for i in range(0, len(cat_ids), 5):
        for cat_id in cat_ids[i:i + 5]:
            try:
                async with _discord_api_sem:
                    category = guild.get_channel(int(cat_id))
                    if category is None:
                        category = await guild.fetch_channel(int(cat_id))
                    if category:
                        await category.delete()
            except Exception as e:
                print(f"Error deleting Category {cat_id}: {e}")
        if i + 5 < len(cat_ids):
            await asyncio.sleep(1.0)

    if role_id:
        try:
            async with _discord_api_sem:
                role = guild.get_role(role_id)
                if role:
                    await role.delete(reason="Game cleanup: Deleting dynamic Gamer Pass")
        except Exception as e:
            print(f"Error deleting Gamer Pass role {role_id}: {e}")


tree = bot.tree

def is_locked_for_mode(nation: str, mode: str, locked_list: list) -> bool:
    if not locked_list:
        return False

    if nation in locked_list:
        return True

    cat_key = get_mapped_mode(mode)
    config = NATION_CATEGORIES.get(cat_key, {})

    found_region = None

    for region_name, content in config.items():
        if isinstance(content, list):
            if nation in content:
                found_region = region_name
                break
        elif isinstance(content, dict):
            for group_nations in content.values():
                if nation in group_nations:
                    found_region = region_name
                    break
            if found_region: break

    if found_region and found_region in locked_list:
        return True

    return False

def _build_nation_autocomplete_choices(mode: str, reservations: dict, locked_regions: list,
                                       command_name: str, current: str) -> List[app_commands.Choice[str]]:
    """Nation filtering for autocomplete — pure in-memory, never touches MySQL."""
    if mode == "Other":
        return []

    mapped_mode = get_mapped_mode(mode)
    all_nations, majors_set = _get_mode_nation_data(mode)

    if not all_nations:
        error_msg = f"❌ ERROR: 0 nations found for mode [{mapped_mode}]"
        return [app_commands.Choice(name=error_msg[:100], value="error")]

    is_coop_command = command_name in ["reserve_coop", "add_coop"]
    reserved_set = set(reservations.keys())
    current_lower = _normalize_ac_current(current).lower()
    locked_set = _build_locked_nation_set(mode, locked_regions) if locked_regions else frozenset()

    if is_coop_command:
        pool = sorted(majors_set)
    else:
        pool = None

    if not current_lower:
        if is_coop_command:
            available = list(pool)
        else:
            available_majors = [n for n in all_nations if n in majors_set and n not in reserved_set and n not in locked_set]
            available_minors = [n for n in all_nations if n not in majors_set and n not in reserved_set and n not in locked_set]
            available = available_majors[:25]
            if len(available) < 25:
                available.extend(available_minors[:25 - len(available)])
        return [app_commands.Choice(name=n[:100], value=n[:100]) for n in available[:25] if n.strip()]

    if is_coop_command:
        candidates = pool
    else:
        candidates = [n for n in all_nations if n not in reserved_set and n not in locked_set]

    filtered = [n for n in candidates if current_lower in n.lower()]

    if not filtered:
        error_msg = f"❌ '{current_lower}' not found or Region Locked."
        return [app_commands.Choice(name=error_msg[:100], value="error")]

    found_majors = sorted(n for n in filtered if n in majors_set)
    found_minors = sorted(n for n in filtered if n not in majors_set)
    final_list = found_majors + found_minors

    return [app_commands.Choice(name=n[:100], value=n[:100]) for n in final_list[:25] if n.strip()]


async def nation_autocomplete(interaction: discord.Interaction, current: str) -> List[app_commands.Choice[str]]:
    if not get_cached_games_data():
        return []

    current = _normalize_ac_current(current)
    game = get_cached_games_data().get(str(interaction.channel.id))
    if not game:
        return [app_commands.Choice(name="❌ Error: Not in a valid game thread", value="error")]

    command_name = interaction.command.name if interaction.command else ""
    return _run_autocomplete_sync(
        _build_nation_autocomplete_choices,
        game.get("mode", ""),
        dict(game.get("reservations", {})),
        list(game.get("locked_regions", [])),
        command_name,
        current,
        label="nation_autocomplete",
    )


def _build_game_autocomplete_choices(
    games_data: dict,
    current: str,
    ended_only: bool,
    reserved_user_id: int | None = None,
) -> List[app_commands.Choice[str]]:
    current_lower = current.lower()
    uid_str = str(reserved_user_id) if reserved_user_id is not None else None
    choices = []
    for thread_id, data in reversed(list(games_data.items())):
        if ended_only:
            if data.get("status") != "ended":
                continue
        else:
            if data.get("status") in ("ended", "cancelled"):
                continue

        # /give and /take: only games where this user held any reservation slot.
        if uid_str is not None:
            reservations = data.get("reservations") or {}
            if not isinstance(reservations, dict):
                continue
            if not any(str(v) == uid_str for v in reservations.values()):
                continue

        display_name = data.get("thread_name", f"Thread #{thread_id}")
        label = display_name
        if not ended_only:
            game_started = data.get("game_started", False)
            status_tag = "🔵 STARTED" if game_started else "🟢 OPEN"
            label = f"[{status_tag}] {display_name}"

        if current_lower in label.lower() or current_lower in str(thread_id):
            choices.append(app_commands.Choice(name=label[:100], value=str(thread_id)))
        if len(choices) >= 25:
            break
    return choices


# AUTOCOMPLETE FUNCTIONS (Must be at the top, before commands!)
async def game_autocomplete(interaction: discord.Interaction, current: str) -> List[app_commands.Choice[str]]:
    return await _autocomplete_in_thread(
        _build_game_autocomplete_choices,
        dict(get_cached_games_data()),
        current,
        True,
    )


async def game_nation_autocomplete(interaction: discord.Interaction, current: str) -> List[app_commands.Choice[str]]:
    selected_game_id = getattr(interaction.namespace, 'game', None)
    if not selected_game_id:
        return []

    def _build():
        games_data = get_cached_games_data()
        choices = []
        target_game = games_data.get(selected_game_id)
        if not target_game:
            return choices
        reservations = target_game.get("reservations", {})
        if not isinstance(reservations, dict):
            return choices
        current_lower = current.lower()
        for nat in reservations.keys():
            if current_lower in nat.lower():
                choices.append(app_commands.Choice(name=nat[:100], value=nat[:100]))
                if len(choices) >= 25:
                    break
        return choices

    return await _autocomplete_in_thread(_build)


def _build_unified_lock_choices(current: str) -> List[app_commands.Choice[str]]:
    options = ["Verified", "Trusted", "All Users", "Europe", "Asia", "Oceania", "North America", "South America", "Africa"]
    if 'NATION_CATEGORIES' in globals():
        for mode_data in NATION_CATEGORIES.values():
            if isinstance(mode_data, dict):
                for key, val in mode_data.items():
                    options.append(key)
                    if isinstance(val, list):
                        options.extend(val)
                    elif isinstance(val, dict):
                        for sub in val.values():
                            options.extend(sub)
            elif isinstance(mode_data, list):
                options.extend(mode_data)

    current_lower = current.lower()
    filtered = sorted(set(o for o in options if current_lower in o.lower()))
    return [app_commands.Choice(name=o, value=o) for o in filtered[:25]]


async def unified_lock_autocomplete(interaction: discord.Interaction, current: str) -> List[app_commands.Choice[str]]:
    return await _autocomplete_in_thread(_build_unified_lock_choices, current)


def _build_late_join_nation_choices(thread_id: str, current: str) -> List[app_commands.Choice[str]]:
    options = []
    try:
        games_data = get_cached_games_data()
        if thread_id in games_data:
            mode = games_data[thread_id].get("mode", "Historical")
            options = _get_mode_nation_data(mode)[0]
    except Exception:
        pass

    fillers = ["Filler 1", "Filler 2", "Filler 3", "Filler 4", "Filler 5"]
    for f in fillers:
        if f not in options:
            options.append(f)

    current_lower = current.lower()
    matches = [opt for opt in options if current_lower in opt.lower()]
    if current and not any(current_lower == opt.lower() for opt in options):
        matches.insert(0, current)
    return [app_commands.Choice(name=match, value=match) for match in matches][:25]


# =============================================================================
# RESERVATION MESSAGE SIZE SAFETY
# Discord hard-caps a single message at 2000 characters. On nearly-full games the
# reservation list (which embeds a raw <@id> mention per player, ~21 chars each)
# can push a single template message past that cap. When that happened the edit/
# send silently failed and the cleanup loop then DELETED the message — making 20+
# players appear to vanish from the board. These helpers guarantee no reservation
# message is ever built over the cap by re-splitting on line boundaries, and warn
# the host when the list is getting close.
# =============================================================================
RESERVATION_MSG_LIMIT = 1900        # Hard split threshold (kept safely under 2000).
RESERVATION_WARN_THRESHOLD = 1750   # Warn the host once a section approaches the cap.


def _enforce_message_limits(content_list, limit: int = RESERVATION_MSG_LIMIT):
    """Return a new content list where no single message exceeds ``limit`` chars.

    Oversized messages are split on line boundaries so no reservation line is ever
    dropped. A single line longer than the limit (should never happen for a normal
    reservation entry) is hard-sliced as a last resort. This is the safety net that
    prevents the '2000-char = message deleted = players disappear' bug.
    """
    result = []
    for content in content_list:
        if not content:
            continue
        if len(content) <= limit:
            result.append(content)
            continue

        buf = ""
        for line in content.split("\n"):
            # Pathological single line (e.g. a huge coop chain) — hard-slice it.
            if len(line) > limit:
                if buf:
                    result.append(buf)
                    buf = ""
                for i in range(0, len(line), limit):
                    result.append(line[i:i + limit])
                continue
            if buf and len(buf) + 1 + len(line) > limit:
                result.append(buf)
                buf = line
            else:
                buf = f"{buf}\n{line}" if buf else line
        if buf:
            result.append(buf)
    return result


async def _send_reservation_limit_warning(game: dict, thread, msg_count: int, peak_len: int):
    """Post a throttled warning embed to the host when the list nears the size cap.

    Prefers the Host Control Center thread, falling back to the host-log channel.
    Auto-splitting already guarantees no data loss — this is purely a heads-up so
    hosts understand why the board now spans extra messages.
    """
    host_id = game.get("host_id")
    ping = f"<@{host_id}>" if host_id else None
    mode = game.get("mode", "Game")
    thread_mention = getattr(thread, "mention", "the reservation thread")

    embed = discord.Embed(
        title="⚠️ Reservation List Nearing Discord's Size Limit",
        description=(
            f"The **{mode}** reservation list in {thread_mention} is getting large "
            f"(a section reached **{peak_len} / 2000** characters).\n\n"
            f"✅ **No reservations are lost.** The bot now automatically spreads the "
            f"list across **{msg_count}** message(s) so nothing gets dropped.\n\n"
            f"ℹ️ This is just a heads-up that the board is close to full."
        ),
        color=discord.Color.orange(),
    )

    channel = await _resolve_host_control_center(game, getattr(thread, "id", None))
    if not channel:
        channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID)

    if channel:
        try:
            await channel.send(
                content=ping,
                embed=embed,
                allowed_mentions=discord.AllowedMentions(users=True),
            )
            print(f"[ResLimit] Warned host for thread {getattr(thread, 'id', '?')}: "
                  f"peak={peak_len} chars across {msg_count} msgs.")
            return True
        except Exception as e:
            print(f"[ResLimit] warning send failed: {e}")
    return False


async def get_initial_list(mode, game=None):
    # Always run the raw output through the size guard so the very first post can
    # never exceed Discord's 2000-char cap either.
    if game and game.get("nation_layout"):
        return _enforce_message_limits(_build_layout_list({}, game))
    return _enforce_message_limits(await _get_initial_list_raw(mode))


async def _get_initial_list_raw(mode):
    mapped = get_mapped_mode(mode)

    if mode == "TFR":
        return _build_tfr_list({})

    if is_roleplay_family_mode(mode):
        return await _build_roleplay_list({}, [], True, False, mode=mode)

    if "Historical" in mapped:
        return await _build_historical_list({}, [], True, False, mode=mode)

    if mode == "Other":
        return ["# Other Game Mode\nReservations are open.\n\n__**Total Reservations: 0**__"]

    return ["# Unknown Game Mode\nError: Mode not recognized."]


async def update_reservation_message(thread_id):
    try:
        games_data = await read_json(GAMES_FILE)
        thread_key = str(thread_id)
        game = games_data.get(thread_key)

        if not game:
            print(f"Update failed: Thread {thread_id} not found in games DB")
            return
        # No thread: the website map is the reservation list.
        if not _game_has_thread(game):
            return

        mode = game.get("mode", "Unknown")
        mapped_mode = get_mapped_mode(mode)
        thread = bot.get_channel(thread_id)

        if not thread:
            try: thread = await bot.fetch_channel(thread_id)
            except: return

        reservations = game.get("reservations", {})
        locked_regions = game.get("locked_regions", [])
        locked_majors = game.get("locked_majors", True)
        game_started = game.get("game_started", False)

        new_content_list = []

        # Preset games with their own nation groups list from the game's layout.
        if game.get("nation_layout"):
            new_content_list = _build_layout_list(reservations, game)

        # --- TFR CUSTOM INTERCEPTOR ---
        elif mode == "TFR":
            new_content_list = _build_tfr_list(reservations, game_started, game=game)

        elif is_roleplay_family_mode(mode):
            new_content_list = await _build_roleplay_list(reservations, locked_regions, locked_majors, game_started, game=game, mode=mode)

        elif "Historical" in mapped_mode:
            new_content_list = await _build_historical_list(reservations, locked_regions, locked_majors, game_started, game=game, mode=mode)

        elif mode == "Other":
            other_list_items = []
            for nation_key, user_id in reservations.items():
                display_name = nation_key.replace("_FILL_", "").replace("_", " ")
                status = "🟡"
                other_list_items.append(f"{status} {display_name} - {_reservation_mention(user_id)}")

            new_content_list.append(
                "# Other Game Mode\n"
                + ("\n".join(other_list_items) if other_list_items else "Reservations are open.")
                + f"\n\n__**Total Reservations: {format_reservation_totals(reservations, mode)}**__"
            )
        else:
            new_content_list.append(f"Error: Invalid game mode {mode}.")

        new_content_list = [c for c in new_content_list if c and c.strip()]

        # =====================================================================
        # SIZE SAFETY NET (fixes the "bot removed 20+ people" bug)
        # Measure the largest section BEFORE splitting so we can warn the host,
        # then guarantee every outgoing message is under Discord's 2000-char cap.
        # Without this, an oversized edit/send failed and the cleanup loop wiped
        # the message, making a chunk of the reservation list disappear.
        # =====================================================================
        peak_len = max((len(c) for c in new_content_list), default=0)
        new_content_list = _enforce_message_limits(new_content_list)

        near_limit = peak_len >= RESERVATION_WARN_THRESHOLD
        already_warned = bool(game.get("res_near_limit_warned"))
        if near_limit and not already_warned:
            game["res_near_limit_warned"] = True
            try:
                await _send_reservation_limit_warning(game, thread, len(new_content_list), peak_len)
            except Exception as e:
                print(f"[ResLimit] warning dispatch failed: {e}")
        elif (not near_limit) and already_warned:
            # List shrank back below the threshold — allow a fresh warning if it grows again.
            game["res_near_limit_warned"] = False

        message_ids = game.get("message_ids", [])
        new_message_ids = []
        # Headings in the reservation lists were causing Discord to drop user mentions
        # on the following lines unless mentions are explicitly allowed.
        list_mentions = discord.AllowedMentions(everyone=False, users=True, roles=False)

        # --- SAFE MESSAGE UPDATING LOOP ---
        thread_key = str(thread_id)
        for i, content in enumerate(new_content_list):
            if i < len(message_ids):
                msg_id = message_ids[i]
                try:
                    msg = await _get_reservation_message(thread, thread_key, msg_id)
                    if msg is None:
                        msg = await thread.send(content, allowed_mentions=list_mentions)
                        _reservation_message_cache.setdefault(thread_key, {})[msg.id] = msg
                        new_message_ids.append(msg.id)
                    elif msg.content != content:
                        await _safe_message_edit(
                            msg, content=content, allowed_mentions=list_mentions, skip_if_unchanged=False
                        )
                        new_message_ids.append(msg.id)
                    else:
                        new_message_ids.append(msg.id)
                except discord.NotFound:
                    _invalidate_reservation_message_cache(thread_key, msg_id)
                    try:
                        msg = await thread.send(content, allowed_mentions=list_mentions)
                        _reservation_message_cache.setdefault(thread_key, {})[msg.id] = msg
                        new_message_ids.append(msg.id)
                    except Exception as e:
                        print(f"Failed to send replacement msg: {e}")
                except discord.HTTPException:
                    _invalidate_reservation_message_cache(thread_key, msg_id)
                    new_message_ids.append(msg_id)
                except Exception as e:
                    print(f"Failed to edit message {msg_id}: {e}")
                    new_message_ids.append(msg_id)
            else:
                try:
                    msg = await thread.send(content, allowed_mentions=list_mentions)
                    _reservation_message_cache.setdefault(thread_key, {})[msg.id] = msg
                    new_message_ids.append(msg.id)
                except Exception as e:
                    print(f"Failed to send new msg: {e}")

        # Cleanup extra messages at the end
        if len(message_ids) > len(new_message_ids):
            for i in range(len(new_message_ids), len(message_ids)):
                try:
                    old_msg = await _get_reservation_message(thread, thread_key, message_ids[i])
                    if old_msg:
                        await old_msg.delete()
                    _invalidate_reservation_message_cache(thread_key, message_ids[i])
                except Exception:
                    pass

        game["message_ids"] = new_message_ids
        await write_json(GAMES_FILE, games_data)

    except Exception as e:
        print(f"Update error: {e}")


def _draft_pool_lines(game: dict) -> List[str]:
    draft = game.get("draft", {})
    pool = draft.get("pool", {})
    if not pool:
        return ["*Nobody yet — join from the website map (Major, Minor, Major Co-op or Filler).*"]
    lines = []
    for uid_str, entry in pool.items():
        preference = _draft_pool_preference(game, entry).replace(" Nation", "")
        lines.append(f"• <@{uid_str}> — **{preference}**")
    return lines


def _build_draft_pool_embed(game: dict) -> discord.Embed:
    """The always-visible board in the game thread: teams and captains, the
    phase / whose turn, and every pooled player with their Major / Minor /
    Co-op / Filler choice (notes stay on the website for the host and captains). Real
    assignments show on the normal reservation list."""
    draft = game.get("draft", {})
    phase = draft.get("phase", "ENLISTING")
    pool = draft.get("pool", {})
    pool_cap = draft.get("pool_cap") or get_draft_pool_capacity(game.get("mode", ""))
    teams = _draft_teams(game)

    color = {"ENLISTING": discord.Color.blurple(), "DRAFTING": discord.Color.gold()}.get(phase, discord.Color.green())
    embed = discord.Embed(title="🎯 Draft Pool", color=color)
    for team in teams:
        embed.add_field(name=f"🚩 {team.get('name')}", value=f"Captain <@{team.get('captain_id')}>", inline=True)
    first = next((team.get("name") for team in teams if team.get("key") == draft.get("first_picker")), None)
    order_txt = "🪙 Coin flip decides first pick" if draft.get("coin_flip") else f"{first or teams[0].get('name')} picks first"
    embed.add_field(name="Pick Order", value=order_txt, inline=True)

    if phase == "ENLISTING":
        status_txt = "🟦 **SIGN-UPS OPEN** — join on the website map; the host starts the draft"
    elif phase == "DRAFTING":
        team = _draft_turn_team(game)
        remaining = draft.get("picks_remaining_this_turn", 1)
        status_txt = (
            f"🟨 **DRAFTING** — 👉 {team.get('name')}'s turn (<@{team.get('captain_id')}>), "
            f"{remaining} pick(s) left · captains pick on the website map"
            if team else "🟨 **DRAFTING**"
        )
    else:
        status_txt = "🟩 **COMPLETE** — the host can now start the game on the website"
    embed.add_field(name="Status", value=status_txt, inline=False)

    pool_lines = _draft_pool_lines(game)
    chunks = []
    current_chunk = ""
    for line in pool_lines:
        if len(current_chunk) + len(line) + 1 > 1000:
            chunks.append(current_chunk)
            current_chunk = line
        else:
            current_chunk = f"{current_chunk}\n{line}" if current_chunk else line
    if current_chunk:
        chunks.append(current_chunk)
    for i, chunk in enumerate(chunks[:5]):
        embed.add_field(name=f"👥 Pool ({len(pool)}/{pool_cap})" if i == 0 else "​", value=chunk or "​", inline=False)

    embed.set_footer(text="Players choose Major, Minor, Major Co-op or Filler; the captains (and the host) place them.")
    return embed


async def update_draft_pool_message(thread_id: int, *, resend: bool = False) -> None:
    """Rebuild the Draft Pool board embed in-place. Safe to call after every
    /reserve, /unreserve, and pick — mirrors update_reservation_message's
    resilience (missing channel/message just gets recreated)."""
    try:
        games_data = await read_json(GAMES_FILE)
        game = games_data.get(str(thread_id))
        if not _is_draft_game(game) or not _game_has_thread(game):
            return

        thread = bot.get_channel(thread_id)
        if not thread:
            try:
                thread = await bot.fetch_channel(thread_id)
            except Exception:
                return

        embed = _build_draft_pool_embed(game)
        board_msg_id = game["draft"].get("board_message_id")
        msg = None
        if board_msg_id and not resend:
            try:
                msg = await thread.fetch_message(board_msg_id)
            except (discord.NotFound, discord.HTTPException):
                msg = None
        if msg is not None:
            try:
                await msg.edit(embed=embed)
                return
            except discord.HTTPException:
                pass
        new_msg = await thread.send(embed=embed)
        game["draft"]["board_message_id"] = new_msg.id
        await write_json(GAMES_FILE, games_data)
    except Exception as e:
        print(f"Draft pool board update error: {e}")


def _lock_label(level: str) -> str:
    """Converts a lock level value into a display label."""
    return {"VIP": "VIP+ Only", "Trusted": "Trusted+", "Verified": "Verified+"}.get(level, level)


def _member_meets_lock_level(member, level: str, mode_cfg: dict) -> bool:
    """Return True if a member satisfies a reservation lock tier.

    Shared by /reserve, /draw and /gamble so every entry point enforces
    the exact same Verified / Trusted / VIP+ gating. Admins and hosts always pass.
    """
    if level == "All Users":
        return True

    user_role_ids = [r.id for r in getattr(member, "roles", [])]

    try:
        if member.guild_permissions.administrator:
            return True
    except Exception:
        pass
    if any(rid in user_role_ids for rid in ALLOWED_HOST_ROLES):
        return True

    trusted_id = mode_cfg.get("trusted_role_id")
    verified_id = mode_cfg.get("verified_role_id")
    vip_id = ROLE_IDS.get("VIP_ROLE_ID")

    has_vip = (vip_id in user_role_ids) if vip_id else False
    has_trusted = (trusted_id in user_role_ids) if trusted_id else False
    has_verified = (verified_id in user_role_ids) if verified_id else False

    if level == "VIP":
        return has_vip
    if level == "Trusted":
        return has_trusted
    if level == "Verified":
        return has_verified or has_trusted
    return False


def get_reservation_count(reservations: dict, include_fillers: bool = True) -> int:
    if not isinstance(reservations, dict):
        return 0
    return sum(1 for key in reservations if include_fillers or not key.startswith("_FILL_"))


def is_capacity_slot(key: str) -> bool:
    """True if a reservation key occupies a nation (capacity) slot.

    Co-op slots (``Nation_coop`` / ``Nation_coop_2``) and Filler slots
    (``_FILL_...``) are bonus slots that do NOT consume the nation capacity pool.
    """
    return ("_coop" not in key) and (not key.startswith("_FILL_"))


def count_nation_reservations(reservations: dict) -> int:
    """Count only real nation slots (majors + minors).

    This is the number that counts against a lobby's capacity — Co-ops and
    Fillers are tracked separately so they never block nation reservations.
    """
    if not isinstance(reservations, dict):
        return 0
    return sum(1 for key in reservations if is_capacity_slot(key))


def count_coop_reservations(reservations: dict) -> int:
    """Count Co-op reservation slots (do not count toward nation capacity)."""
    if not isinstance(reservations, dict):
        return 0
    return sum(1 for key in reservations if "_coop" in key)


def count_filler_reservations(reservations: dict) -> int:
    """Count Filler reservation slots (do not count toward nation capacity)."""
    if not isinstance(reservations, dict):
        return 0
    return sum(1 for key in reservations if key.startswith("_FILL_"))


def format_reservation_totals(reservations: dict, mode: str) -> str:
    """Standard total line, e.g. ``12/57 + 🤝5 (Coop) + ❕4 (Fillers)``.

    Only main nations count toward the ``/capacity`` pool (capacity = number of
    reservable nations for that mode). Co-ops and Fillers are shown separately
    when present and never inflate the denominator.
    """
    nations = count_nation_reservations(reservations)
    coops = count_coop_reservations(reservations)
    fillers = count_filler_reservations(reservations)
    out = f"{nations}/{get_game_capacity(mode)}"
    if coops:
        out += f" + 🤝{coops} (Coop)"
    if fillers:
        out += f" + ❕{fillers} (Fillers)"
    return out


# ==========================================================================
# GAME-HISTORY RECONSTRUCTION
# Player / host game history was moved off player_stats and now lives in the
# authoritative games record. These helpers rebuild "which game they played
# what" straight from the games data so /info, /report and /report_host can
# always show an accurate, up-to-date career instead of the empty legacy field.
# ==========================================================================
DISCORD_EPOCH_MS = 1420070400000


def _snowflake_to_unix(snowflake) -> int:
    """Convert a Discord snowflake (thread/message id) into a unix timestamp (s)."""
    try:
        return ((int(snowflake) >> 22) + DISCORD_EPOCH_MS) // 1000
    except Exception:
        return 0


def _normalize_epoch_seconds(value) -> int | None:
    """Canonicalize a host-supplied unix timestamp into UTC epoch seconds.

    Returns None for invalid input. The returned integer is the SINGLE source
    of truth: it is persisted verbatim to MySQL, rendered exclusively through
    native Discord <t:F>/<t:R> tags, and is the exact value the web casino
    engine (`new Date(unix_timestamp * 1000)`) and /api/access use — it is
    never reformatted or timezone-shifted anywhere in between."""
    try:
        ts = int(value)
    except (TypeError, ValueError):
        return None
    try:
        # Round-trip through UTC datetime so out-of-range values fail loudly
        # instead of silently corrupting renders.
        return int(datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).timestamp())
    except (OverflowError, OSError, ValueError):
        return None


def _game_unix_ts(game: dict, game_id) -> int:
    """Best-effort start time for a game: scheduled timestamp, else id snowflake."""
    ts = game.get("start_timestamp") if isinstance(game, dict) else None
    if isinstance(ts, (int, float)) and ts > 0:
        return int(ts)
    return _snowflake_to_unix(game_id)


def _pretty_reservation_name(key: str) -> str:
    """Turn a raw reservation key into a human-readable slot name."""
    if not isinstance(key, str):
        return str(key)
    if key.startswith("_FILL_"):
        return "Filler"
    if "_coop" in key:
        base = key.split("_coop", 1)[0]
        suffix = key.split("_coop", 1)[1].strip("_")
        if suffix.isdigit():
            return f"{base} (Co-op {suffix})"
        return f"{base} (Co-op)"
    return key


def build_player_game_history(user_id, games_data: dict) -> list[dict]:
    """Reconstruct every game a user reserved in, oldest first.

    Returns a list of dicts: {thread_id, mode, nation, present, ts, status}.
    """
    uid = str(user_id)
    if not isinstance(games_data, dict):
        return []
    entries = []
    for gid, game in games_data.items():
        if not isinstance(game, dict):
            continue
        if game.get("status") == "cancelled":
            continue
        reservations = game.get("reservations", {})
        if not isinstance(reservations, dict):
            continue
        held = [k for k, v in reservations.items() if str(v) == uid]
        if not held:
            continue
        # Prefer a real nation slot for the display name over a coop/filler slot.
        primary = next((k for k in held if is_capacity_slot(k)), held[0])
        present_ids = {str(x) for x in (game.get("present_ids") or [])}
        entries.append({
            "thread_id": str(gid),
            "mode": game.get("mode", "Unknown"),
            "nation": _pretty_reservation_name(primary),
            "present": uid in present_ids,
            "ts": _game_unix_ts(game, gid),
            "status": game.get("status", "active"),
        })
    entries.sort(key=lambda e: e["ts"])
    return entries


# ==========================================================================
# WEB PORTFOLIO DATA (scale plan, Phase 1 — docs/realtime-and-scale-plan.md)
#
# player_summary     one precomputed row per player (history-derived numbers +
#                    latest 20 games) so a web portfolio is a single PK read.
#                    Kept fresh by player_summary_loop, which diffs a small
#                    signature of every cached game and rebuilds only the
#                    players of games that changed (plus anyone a moderation
#                    event touched). Full rebuild on startup.
# moderation_events  every moderation action (commend / warn / ban / merit /
#                    Dishonored / ... and their removals) with its
#                    reason, issuer, game and host-log link — the web
#                    portfolio's evidence list and ban details, and /report's
#                    evidence without scanning the log channel.
# ==========================================================================
_PLAYER_SUMMARY_DDL = """
CREATE TABLE IF NOT EXISTS player_summary (
    user_id BIGINT PRIMARY KEY,
    total_games INT NOT NULL DEFAULT 0,
    attended INT NOT NULL DEFAULT 0,
    attendance_tracked INT NOT NULL DEFAULT 0,
    recent_games JSON NULL,
    ban_games JSON NULL,
    version INT NOT NULL DEFAULT 1,
    updated_at BIGINT NOT NULL
)
"""

_MODERATION_EVENTS_DDL = """
CREATE TABLE IF NOT EXISTS moderation_events (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT NOT NULL,
    action VARCHAR(32) NOT NULL,
    mode VARCHAR(32) NULL,
    amount INT NULL,
    reason TEXT NULL,
    actor_id BIGINT NULL,
    thread_id VARCHAR(64) NULL,
    automatic TINYINT(1) NOT NULL DEFAULT 0,
    details JSON NULL,
    log_url VARCHAR(255) NULL,
    source VARCHAR(16) NOT NULL DEFAULT 'live',
    source_message_id BIGINT NULL,
    created_at BIGINT NOT NULL,
    INDEX idx_moderation_events_user (user_id, created_at),
    UNIQUE KEY uq_moderation_events_message (source_message_id)
)
"""

PLAYER_SUMMARY_RECENT = 20
PLAYER_SUMMARY_BATCH = 300

# Players whose summary must be rebuilt, and the last-seen signature/members
# of every cached game (so removed players are rebuilt too).
_summary_dirty: set[str] = set()
_summary_game_sigs: dict[str, str] = {}
_summary_game_members: dict[str, set[str]] = {}
_summary_full_rebuild = True  # first pass after startup rebuilds everyone
_background_tasks: set = set()


def _spawn_background(coro, label: str) -> None:
    """Fire-and-forget with a held reference and logged failures."""
    task = asyncio.create_task(coro)
    _background_tasks.add(task)

    def _done(t):
        _background_tasks.discard(t)
        if not t.cancelled() and t.exception():
            print(f"[WARN] {label} failed: {t.exception()}")

    task.add_done_callback(_done)


def _summary_members(game: dict) -> set[tuple[str, str]]:
    """(server, player) for everyone in a game (summaries are per server)."""
    reservations = game.get("reservations") if isinstance(game, dict) else None
    if not isinstance(reservations, dict):
        return set()
    gid = str(_game_guild_id(game))
    return {(gid, str(uid)) for uid in reservations.values() if str(uid).isdigit()}


def _summary_signature(game: dict) -> str:
    """Everything a player summary depends on for this game."""
    reservations = game.get("reservations") if isinstance(game.get("reservations"), dict) else {}
    return json.dumps(
        [
            sorted((str(k), str(v)) for k, v in reservations.items()),
            sorted(str(x) for x in (game.get("present_ids") or [])),
            sorted(str(x) for x in (game.get("game_bans") or [])),
            bool(game.get("snapshot_done")),
            game.get("status"),
            game.get("start_timestamp"),
            game.get("mode"),
        ],
        default=str,
    )


def _attendance_taken(game: dict) -> bool:
    """snapshot_done marks attendance; legacy ended games only have present_ids."""
    if game.get("snapshot_done"):
        return True
    return game.get("status") == "ended" and isinstance(game.get("present_ids"), list)


def mark_player_summary_dirty(user_id) -> None:
    if str(user_id).isdigit():
        _summary_dirty.add((str(cur_gid()), str(user_id)))


def _scan_games_for_summaries(games: dict) -> None:
    """Queue the players of every game whose signature changed since last scan."""
    seen = set()
    for gid, game in games.items():
        if not isinstance(game, dict):
            continue
        gid = str(gid)
        seen.add(gid)
        sig = _summary_signature(game)
        if _summary_game_sigs.get(gid) == sig:
            continue
        members = _summary_members(game)
        _summary_dirty.update(members | _summary_game_members.get(gid, set()))
        _summary_game_sigs[gid] = sig
        _summary_game_members[gid] = members
    for gid in [g for g in _summary_game_sigs if g not in seen]:
        _summary_dirty.update(_summary_game_members.pop(gid, set()))
        _summary_game_sigs.pop(gid, None)


def _build_player_summary_rows(keys: set, games: dict) -> list[tuple]:
    """Summary rows for (server, player) pairs — each server's games only."""
    by_guild: dict[str, set[str]] = {}
    for key in keys:
        guild_id, uid = key if isinstance(key, tuple) else (str(GUILD_ID), str(key))
        by_guild.setdefault(str(guild_id), set()).add(str(uid))
    rows: list[tuple] = []
    for guild_id, user_ids in by_guild.items():
        guild_games = {tid: g for tid, g in games.items() if isinstance(g, dict) and str(_game_guild_id(g)) == guild_id}
        rows.extend((guild_id,) + row for row in _build_guild_summary_rows(user_ids, guild_games))
    return rows


def _build_guild_summary_rows(user_ids: set[str], games: dict) -> list[tuple]:
    """build_player_game_history for many players in ONE pass over the games,
    plus attendance-taken / ban-recorded flags per game."""
    per_user: dict[str, list[dict]] = {uid: [] for uid in user_ids}
    for gid, game in games.items():
        if not isinstance(game, dict) or game.get("status") == "cancelled":
            continue
        reservations = game.get("reservations")
        if not isinstance(reservations, dict):
            continue
        held: dict[str, list[str]] = {}
        for key, uid in reservations.items():
            uid = str(uid)
            if uid in per_user:
                held.setdefault(uid, []).append(str(key))
        if not held:
            continue
        taken = _attendance_taken(game)
        present = {str(x) for x in (game.get("present_ids") or [])}
        bans = {str(x) for x in (game.get("game_bans") or [])}
        mode = game.get("mode", "Unknown")
        ts = _game_unix_ts(game, gid)
        for uid, slots in held.items():
            primary = next((k for k in slots if is_capacity_slot(k)), slots[0])
            per_user[uid].append({
                "thread_id": str(gid),
                "mode": mode,
                "nation": _pretty_reservation_name(primary),
                "present": (uid in present) if taken else None,
                "ts": ts,
                "banned_here": uid in bans,
            })

    now = int(time.time())
    rows = []
    for uid, entries in per_user.items():
        entries.sort(key=lambda e: e["ts"])
        tracked = [e for e in entries if e["present"] is not None]
        ban_games = {}
        for entry in entries:
            if entry["banned_here"]:
                category = (get_mod_context(entry["mode"]) or {}).get("label", "Roleplay")
                ban_games[category] = {k: entry[k] for k in ("thread_id", "mode", "nation", "ts")}
        recent = [
            {k: entry[k] for k in ("thread_id", "mode", "nation", "present", "ts")}
            for entry in reversed(entries[-PLAYER_SUMMARY_RECENT:])
        ]
        rows.append((
            int(uid),
            len(entries),
            sum(1 for e in tracked if e["present"]),
            len(tracked),
            json.dumps(recent),
            json.dumps(ban_games),
            now,
        ))
    return rows


def _upsert_player_summaries_mysql(rows: list[tuple]) -> None:
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        cur.executemany(
            "INSERT INTO player_summary "
            "(guild_id, user_id, total_games, attended, attendance_tracked, recent_games, ban_games, updated_at) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s, %s) "
            "ON DUPLICATE KEY UPDATE total_games = VALUES(total_games), attended = VALUES(attended), "
            "attendance_tracked = VALUES(attendance_tracked), recent_games = VALUES(recent_games), "
            "ban_games = VALUES(ban_games), updated_at = VALUES(updated_at), version = version + 1",
            rows,
        )
        conn.commit()
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


async def rebuild_player_summaries(full: bool = False) -> int:
    """Rebuild queued (or all) player summaries from the games cache.
    Returns how many players were written."""
    global _summary_full_rebuild
    games = _all_games()
    if not isinstance(games, dict) or not games:
        return 0
    if full:
        _summary_game_sigs.clear()
        _summary_game_members.clear()
    _scan_games_for_summaries(games)
    if not _summary_dirty:
        return 0
    pending = list(_summary_dirty)
    _summary_dirty.clear()
    written = 0
    try:
        for start in range(0, len(pending), PLAYER_SUMMARY_BATCH):
            batch = set(pending[start:start + PLAYER_SUMMARY_BATCH])
            rows = _build_player_summary_rows(batch, games)
            await _run_mysql_io(_upsert_player_summaries_mysql, rows, label="player summary write")
            written += len(rows)
            await asyncio.sleep(0)  # let the event loop breathe between batches
    except Exception:
        # Re-queue whatever wasn't written so the next tick retries.
        _summary_dirty.update(pending[written:])
        raise
    _summary_full_rebuild = False
    return written


@tasks.loop(seconds=15)
async def player_summary_loop():
    """Keep player_summary in step with the games cache (see block comment)."""
    await bot.wait_until_ready()
    try:
        await rebuild_player_summaries(full=_summary_full_rebuild)
    except Exception as e:
        print(f"⚠️ player_summary_loop error: {e}")


def _insert_moderation_events_mysql(rows: list[tuple], ignore_duplicates: bool = False) -> int:
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        verb = "INSERT IGNORE" if ignore_duplicates else "INSERT"
        gid = str(cur_gid())
        cur.executemany(
            f"{verb} INTO moderation_events "
            "(user_id, action, mode, amount, reason, actor_id, thread_id, automatic, details, "
            "log_url, source, source_message_id, created_at, guild_id) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)",
            [tuple(row) + (gid,) if len(row) == 13 else tuple(row) for row in rows],
        )
        conn.commit()
        return int(cur.rowcount or 0)
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def record_moderation_event(
    user_id,
    action: str,
    *,
    mode: str | None = None,
    amount: int | None = None,
    reason: str | None = None,
    actor_id=None,
    thread_id=None,
    automatic: bool = False,
    details: dict | None = None,
    log: dict | None = None,
) -> None:
    """Store one moderation action (fire-and-forget; never blocks or raises).

    `log` is what send_host_log_embed returned — its message link becomes the
    portfolio's evidence link, and its id dedupes against the log backfill."""
    try:
        if not str(user_id).isdigit():
            return
        row = (
            int(user_id),
            str(action)[:32],
            (mode or None) and str(mode)[:32],
            int(amount) if amount is not None else None,
            (reason or None) and str(reason)[:4000],
            int(actor_id) if actor_id is not None and str(actor_id).isdigit() else None,
            str(thread_id)[:64] if thread_id else None,
            1 if automatic else 0,
            json.dumps(details, default=str) if details else None,
            (log or {}).get("url"),
            "live",
            (log or {}).get("message_id"),
            int(time.time()),
        )
        mark_player_summary_dirty(user_id)
        _spawn_background(
            _run_mysql_io(_insert_moderation_events_mysql, [row], True, label="moderation event write"),
            "moderation event write",
        )
    except Exception as e:
        print(f"[WARN] record_moderation_event({action}) failed: {e}")


# attendance_events: the per-game attendance audit trail shown on the web
# Attendance page (samples, participation replies, late joins, host
# overrides, finalize, no-show warnings and their reversals). Keyed by the
# game's stable lobby id so it survives the /game_end storage-key migration.
_ATTENDANCE_EVENTS_DDL = """
CREATE TABLE IF NOT EXISTS attendance_events (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    game_id VARCHAR(64) NOT NULL,
    kind VARCHAR(32) NOT NULL,
    user_id BIGINT NULL,
    actor_id BIGINT NULL,
    details JSON NULL,
    created_at BIGINT NOT NULL,
    INDEX idx_attendance_events_game (game_id, created_at)
)
"""


def _attendance_stable_id(game: dict | None, fallback=None) -> str:
    game = game or {}
    return str(game.get("lobby_thread_id") or game.get("original_thread_id") or fallback or game.get("thread_id") or "")


def _insert_attendance_event_mysql(row: tuple) -> None:
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        cur.execute(
            "INSERT INTO attendance_events (game_id, kind, user_id, actor_id, details, created_at, guild_id) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s)",
            tuple(row) + (str(cur_gid()),),
        )
        conn.commit()
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def record_attendance_event(game_id, kind: str, *, user_id=None, actor_id=None, details: dict | None = None) -> None:
    """Append one attendance audit event (fire-and-forget; never blocks or raises)."""
    try:
        if not game_id:
            return
        row = (
            str(game_id)[:64],
            str(kind)[:32],
            int(user_id) if user_id is not None and str(user_id).isdigit() else None,
            int(actor_id) if actor_id is not None and str(actor_id).isdigit() else None,
            json.dumps(details, default=str) if details else None,
            int(time.time()),
        )
        _spawn_background(
            _run_mysql_io(_insert_attendance_event_mysql, row, label="attendance event write"),
            "attendance event write",
        )
    except Exception as e:
        print(f"[WARN] record_attendance_event({kind}) failed: {e}")


# Human labels for moderation_events.action (/report evidence lines).

# Host-log embed title → (action, automatic). Order matters: specific first.
_HOST_LOG_TITLE_RULES = (
    ("warnings redeemed", "redeem", False),
    ("warning removed", "warn_removed", False),
    ("automatic no-show warning", "warn", True),
    ("commend removed", "commend_removed", False),
    ("commendation", "commend", False),
    ("crash report merit", "merit", True),
    ("merit removed", "merit_removed", False),
    ("merit awarded", "merit", False),
    ("unbanned", "unban", False),
    ("game banned", "ban", False),
    ("dishonored title lifted", "dishonored_take", False),
    ("dishonored title applied", "dishonored_give", False),
    ("hearts of valor earned", "valor_earned", True),
    (" warning", "warn", False),
)
_MENTION_RE = re.compile(r"<@!?(\d+)>")


def _parse_host_log_message(message) -> tuple | None:
    """One past host-log message → a moderation_events row (or None).

    Mirrors the embeds /give, /take, the no-show warner, /sentence, crash
    reports and Hearts of Valor post; anything else is skipped."""
    for embed in message.embeds or []:
        title = (embed.title or "").strip()
        lowered = title.lower()
        rule = next((r for r in _HOST_LOG_TITLE_RULES if r[0] in lowered), None)
        if not rule:
            continue
        _, action, automatic = rule
        fields = {str(f.name).strip().lower(): str(f.value or "") for f in embed.fields}
        target = _MENTION_RE.search(fields.get("target", "")) or _MENTION_RE.search(embed.description or "")
        if not target:
            continue
        actor = _MENTION_RE.search(fields.get("admin", ""))
        mode = fields.get("mode") or next(
            (m for m in ("Roleplay", "Historical") if m in title), None
        )
        amount_match = re.search(r"\d+", fields.get("amount", ""))
        reason = fields.get("reason") or fields.get("description") or fields.get("for") or None
        details = {
            name: value
            for name, value in fields.items()
            if name not in ("target", "admin", "mode", "amount", "reason", "description", "for")
        }
        return (
            int(target.group(1)),
            action,
            (mode or None) and mode[:32],
            int(amount_match.group(0)) if amount_match and action not in ("ban", "unban") else None,
            reason and reason[:4000],
            int(actor.group(1)) if actor else None,
            None,
            1 if automatic else 0,
            json.dumps(details) if details else None,
            message.jump_url,
            "backfill",
            int(message.id),
            int(message.created_at.timestamp()),
        )
    return None


async def backfill_portfolio_data(progress=None) -> dict:
    """Rebuild every player summary, then import the host-log channel's past
    moderation messages into moderation_events (re-runnable: rows are keyed
    by the log message id, so nothing is imported twice)."""
    async def report(text: str):
        if progress:
            try:
                await progress(text)
            except Exception:
                pass

    summaries = await rebuild_player_summaries(full=True)
    await report(f"✅ {summaries} player summaries rebuilt.\n⏳ Importing moderation history from the host log…")

    channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID) or await bot.fetch_channel(G.HOST_LOG_CHANNEL_ID)
    scanned = imported = 0
    batch: list[tuple] = []
    async for message in channel.history(limit=None, oldest_first=True):
        scanned += 1
        row = _parse_host_log_message(message)
        if row:
            batch.append(row)
        if len(batch) >= 200:
            imported += await _run_mysql_io(
                _insert_moderation_events_mysql, list(batch), True, label="moderation backfill write"
            )
            batch.clear()
        if scanned % 2000 == 0:
            await report(
                f"✅ {summaries} player summaries rebuilt.\n"
                f"⏳ Host log: {scanned} messages scanned, {imported} actions imported…"
            )
    if batch:
        imported += await _run_mysql_io(
            _insert_moderation_events_mysql, list(batch), True, label="moderation backfill write"
        )
    return {"summaries": summaries, "scanned": scanned, "imported": imported}


def _last_participated_nation_in_mode(games_data: dict, user_id, mode: str, exclude_thread_id=None) -> str:
    """Base nation the user most recently PLAYED (was marked present) in this exact mode.

    Derived from persisted game data (MySQL games tables), so it survives bot restarts and
    cache refreshes — unlike the transient `last_major_nation` field. Returns '' if the
    player has no completed game in this mode. Mode-specific: a game in 'Roleplay' does
    not affect 'Kaiserreich (FFA)' (or any other mode).

    A game only counts if it actually reached /game_start AND the player is in
    present_ids — reservations from a game that never started (and therefore
    never had a Gamer Pass role / "Yes" participation prompt to gate presence)
    must never count as having "played" that nation.
    """
    uid = str(user_id)
    if not isinstance(games_data, dict) or not mode:
        return ""
    best_ts = -1
    best_nation = ""
    for gid, game in games_data.items():
        if exclude_thread_id is not None and str(gid) == str(exclude_thread_id):
            continue
        if not isinstance(game, dict):
            continue
        if game.get("status") == "cancelled":
            continue
        # The game must have actually been started via /game_start — a
        # reservation-only game (host cancelled/closed it before launch) never
        # had a Gamer Pass role or a "Yes" participation prompt, so nobody
        # could have legitimately "played" a nation in it.
        if not game.get("game_started", False):
            continue
        if game.get("mode") != mode:
            continue
        reservations = game.get("reservations", {})
        if not isinstance(reservations, dict):
            continue
        held = [k for k, v in reservations.items() if str(v) == uid]
        if not held:
            continue
        # Only games the player actually showed up to count (mirrors the major-streak
        # rule, which only advances when the player is present). In practice this
        # requires having held the game's Gamer Pass role — granted only by clicking
        # the green "Yes" participation button, or an explicit host add/late-join.
        present_ids = {str(x) for x in (game.get("present_ids") or [])}
        if uid not in present_ids:
            continue
        personal_slots = [k for k in held if "_coop" not in k]
        if not personal_slots:
            # Co-op attendance counts as participation, but never as personally
            # playing that nation's Major/Minor slot for streak restrictions.
            continue
        primary = next((k for k in personal_slots if is_capacity_slot(k)), personal_slots[0])
        base = primary.replace("_FILL_", "").split("_coop", 1)[0]
        ts = _game_unix_ts(game, gid)
        if ts > best_ts:
            best_ts = ts
            best_nation = base
    return best_nation


def _is_minor_repeat(games_data: dict, user_id, mode: str, base_nation: str, exclude_thread_id=None) -> bool:
    """True if reserving `base_nation` would repeat the same Minor the player most recently
    played in this same Roleplay mode (no back-to-back same minor).

    A Major game in between breaks the chain (because we only look at the single most
    recent participated game in that mode). Mode-specific, so the same minor is fine in a
    different gamemode (e.g. Poland in Roleplay then Poland in Kaiserreich)."""
    if "Roleplay" not in (mode or ""):
        return False
    if not base_nation:
        return False
    last = _last_participated_nation_in_mode(games_data, user_id, mode, exclude_thread_id)
    if not last:
        return False
    return str(base_nation).strip().lower() == str(last).strip().lower()


def _count_configured_nations(mode: str) -> int:
    """Unique reservable nation count for a mode (main slots only)."""
    return len(get_all_nations_for_mode(mode))


def get_game_capacity(mode: str) -> int:
    """Total reservable nations for the lobby capacity display (X/Y).

    Co-ops and Fillers are NOT included in Y — only main nation slots.
    Always derived from the live nation lists so it stays correct when
    nations are added/removed (old hardcoded 64 for Roleplay was stale).
    """
    total = _count_configured_nations(mode)
    if total > 0:
        return total
    # Absolute last resort if a brand-new mode has no nation data yet.
    return 0


# =============================================================================
# DRAFT MODE — helpers
# =============================================================================
# Draft games store ALL of their state (teams, captains, pick order, the
# sign-up pool) inside game["draft"] on the SAME games_data[thread_id] entry
# used by every other game — there is no separate file to keep in sync.
# Actual nation assignments are written straight into game["reservations"]
# using the normal key formats (plain nation name, "<Nation>_coop"/"_coop_2",
# "_FILL_Filler N") so every downstream system (VC creation, attendance,
# late-join, the reservation list) keeps working unchanged.
#
# Everything happens on the website (formerly /reserve, /start_draft,
# /draft_pick and /empty_draft_pool): players join the pool from the map as a
# Major, a Minor, a Major Co-op or a Filler with an optional note, the two team captains pick on the
# map, and the host can place anyone at any time and runs the draft from the
# Games page. See _process_web_draft.
#
# game["draft"] = {
#   "phase": "ENLISTING" | "DRAFTING" | "COMPLETE",
#   "teams": [{"key", "name", "captain_id", "groups", "majors", "minors"}],
#   "coin_flip": bool, "first_picker": team key | None,
#   "current_turn": team key | None, "picks_remaining_this_turn": int,
#   "pool": {"<user_id>": {"preference", "note", "reserved_by", "reserved_at", "name"}},
#   "pool_cap": int, "history": [...], "board_message_id": int,
# }

DRAFT_MAX_COOPS_PER_NATION = 2  # matches WEB_ROSTER_MAX_COOP_SLOTS (live map host tools)
DRAFT_MAX_GENERIC_FILLERS = 10
DRAFT_RESERVE_PREFERENCES = (
    "Major Nation",
    "Minor Nation",
    "Major Co-op",
    "Filler",
)
# What players choose when they join the pool on the website.
DRAFT_POOL_CHOICES = {
    "major": "Major Nation",
    "minor": "Minor Nation",
    "coop": "Major Co-op",
    "filler": "Filler",
}
DRAFT_NOTE_MAX = 300
DRAFT_HISTORY_MAX = 80
DRAFT_TEAM_KEYS = ("A", "B")
# A coin-flip winner opens with this many picks; after that teams alternate 1 by 1.
DRAFT_COIN_FLIP_OPENING_PICKS = 3
# Casino / Fortunes games hand out nations by luck — they can't be drafts.
DRAFT_BLOCKED_ADDONS = ("randomizer", "fortunes")


def get_draft_pool_capacity(mode: str, not_playable: int = 0, *, hidden_majors: int = 0) -> int:
    """Max players in a draft pool: every seat a player can be placed on —
    the playable nations, the co-op seats of the playable Majors and the
    generic fillers. Leftovers who never get placed are cleared when the
    host finishes the draft."""
    nations = max(0, get_game_capacity(mode) - int(not_playable or 0))
    majors = max(0, len(get_major_nations_for_mode(mode)) - int(hidden_majors or 0))
    return nations + majors * DRAFT_MAX_COOPS_PER_NATION + DRAFT_MAX_GENERIC_FILLERS


def _is_draft_game(game: Optional[dict]) -> bool:
    return bool(game) and bool(game.get("is_draft")) and isinstance(game.get("draft"), dict)


def _new_draft_state(*, teams: list, coin_flip: bool, first_picker: Optional[str], pool_cap: int) -> dict:
    return {
        "phase": "ENLISTING",  # ENLISTING -> DRAFTING -> COMPLETE
        "teams": teams,
        "coin_flip": coin_flip,
        "first_picker": first_picker,  # team key, only meaningful when coin_flip is False
        "current_turn": None,          # set once drafting actually starts
        "picks_remaining_this_turn": 0,
        "pool": {},
        "pool_cap": pool_cap,
        "history": [],
    }


def _extract_draft_config(slot: dict) -> Optional[dict]:
    """The draft settings of a SCHEDULE_FILE slot, or None (== a normal game).

    Website calendar: draft_teams = [{name, groups, captain_id}] x2,
    draft_coin_flip, draft_first_picker (team index). Slots made with the old
    Discord wizard only have Allies / Axis captains — their teams follow the
    mode's factions (groups None)."""
    if not slot or not slot.get("is_draft"):
        return None
    teams = slot.get("draft_teams")
    if isinstance(teams, list) and len(teams) == 2 and all(
        isinstance(team, dict) and str(team.get("captain_id") or "").isdigit() for team in teams
    ):
        first = slot.get("draft_first_picker")
        return {
            "teams": [
                {
                    "key": DRAFT_TEAM_KEYS[index],
                    "name": str(team.get("name") or f"Team {index + 1}")[:30],
                    "groups": [str(group) for group in team.get("groups") or []],
                    "captain_id": int(team["captain_id"]),
                }
                for index, team in enumerate(teams)
            ],
            "coin_flip": slot.get("draft_coin_flip") is not False,
            "first_picker": (
                DRAFT_TEAM_KEYS[first] if isinstance(first, int) and not isinstance(first, bool) and first in (0, 1) else None
            ),
        }
    allies_id = slot.get("draft_allies_captain_id")
    axis_id = slot.get("draft_axis_captain_id")
    if not allies_id or not axis_id:
        return None
    first = slot.get("draft_first_picker")
    return {
        "teams": [
            {"key": "Allies", "name": "Allies", "groups": None, "captain_id": int(allies_id)},
            {"key": "Axis", "name": "Axis", "groups": None, "captain_id": int(axis_id)},
        ],
        "coin_flip": bool(slot.get("draft_coin_flip", True)),
        "first_picker": first if first in ("Allies", "Axis") else None,
    }


def _draft_build_teams(config: dict, game: dict) -> list:
    """Each team's nations, from the nation groups the host put in it (the
    game's own preset groups, else the mode's standard ones). A preset's
    not-playable nations never belong to a team."""
    mode = game.get("mode", "")
    hidden = set(game.get("layout_disabled_nations") or [])
    majors = set(get_major_nations_for_mode(mode))
    by_group = {
        str(category).lower(): [nation for _sub, nations in subs for nation in nations]
        for category, subs in _get_archive_layout(mode, game)
    }
    teams = []
    for team in config["teams"]:
        if team.get("groups") is None:
            nations = _draft_faction_nations(game, team["key"])
        else:
            nations = list(dict.fromkeys(
                nation for group in team["groups"] for nation in by_group.get(str(group).lower(), [])
            ))
        nations = [nation for nation in nations if nation not in hidden]
        teams.append({
            "key": team["key"],
            "name": team["name"],
            # Text: the website reads game_data with JavaScript numbers, which
            # can't hold a Discord id exactly.
            "captain_id": str(int(team["captain_id"])),
            "groups": team.get("groups"),
            "majors": [nation for nation in nations if nation in majors],
            "minors": [nation for nation in nations if nation not in majors],
        })
    return teams


def _draft_teams(game: dict) -> list:
    """The game's two teams (drafts from before the website: Allies / Axis
    captains, sides from the mode's factions)."""
    draft = game.get("draft") or {}
    teams = draft.get("teams")
    if isinstance(teams, list) and teams:
        return teams
    return _draft_build_teams(
        {
            "teams": [
                {"key": "Allies", "name": "Allies", "groups": None, "captain_id": int(draft.get("allies_captain_id") or 0)},
                {"key": "Axis", "name": "Axis", "groups": None, "captain_id": int(draft.get("axis_captain_id") or 0)},
            ]
        },
        game,
    )


def _draft_team(game: dict, key) -> Optional[dict]:
    return next((team for team in _draft_teams(game) if team.get("key") == key), None)


def _draft_turn_team(game: dict) -> Optional[dict]:
    return _draft_team(game, (game.get("draft") or {}).get("current_turn"))


def _draft_next_filler_key(reservations: dict) -> Optional[str]:
    for i in range(1, DRAFT_MAX_GENERIC_FILLERS + 1):
        key = f"_FILL_Filler {i}"
        if key not in reservations:
            return key
    return None


def _draft_pool_preference(game: dict, entry: dict) -> str:
    """Read the pool preference while tolerating pre-rework pool entries."""
    preference = str((entry or {}).get("preference") or "").strip()
    if preference in DRAFT_RESERVE_PREFERENCES:
        return preference
    legacy = str((entry or {}).get("nation_1") or "").strip()
    if legacy == "Coop":
        return "Major Co-op"
    if legacy == "Filler":
        return "Filler"
    if legacy in set(get_major_nations_for_mode(game.get("mode", ""))):
        return "Major Nation"
    return "Minor Nation"


def _draft_flatten_group(group) -> List[str]:
    if isinstance(group, list):
        return list(group)
    if isinstance(group, dict):
        out = []
        for nations in group.values():
            if isinstance(nations, list):
                out.extend(nations)
        return out
    return []


def _draft_faction_nations(game: dict, faction: str) -> List[str]:
    """Old Allies / Axis sides: Axis + GEACPS factions vs the rest; modes
    without factions fall back to every nation."""
    mode = game.get("mode", "")
    all_nations = get_all_nations_for_mode(mode)
    config = NATION_CATEGORIES.get(get_mapped_mode(mode), {})
    if not config or not any(isinstance(value, dict) for value in config.values()):
        return list(all_nations)

    axis_group_names = {"axis", "geacps"}
    selected = []
    for group_name, group in config.items():
        is_axis_group = str(group_name).strip().lower() in axis_group_names
        if (faction == "Axis" and is_axis_group) or (faction != "Axis" and not is_axis_group):
            selected.extend(_draft_flatten_group(group))

    valid = set(all_nations)
    return list(dict.fromkeys(nation for nation in selected if nation in valid))


def _draft_assignment_entries(game: dict, team_key=None) -> List[tuple[str, str]]:
    """Free slots a pool player can be placed on, as (label, reservation key).
    team_key = a captain's team: its own free nations (locked ones excluded),
    co-ops of its taken majors, and a filler. None = the host: any playable
    nation (locked ones included), any co-op, a filler."""
    mode = game.get("mode", "")
    reservations = game.get("reservations", {}) or {}
    major_set = set(get_major_nations_for_mode(mode))
    hidden = set(game.get("layout_disabled_nations") or [])
    if team_key is None:
        nations = [nation for nation in get_all_nations_for_mode(mode) if nation not in hidden]
        locked = []
    else:
        team = _draft_team(game, team_key)
        if team is None:
            return []
        nations = list(team.get("majors") or []) + list(team.get("minors") or [])
        locked = game.get("locked_regions", []) or []
    free = [
        nation for nation in nations
        if nation not in reservations and not is_locked_for_mode(nation, mode, locked)
    ]
    entries = [(nation, nation) for nation in sorted(n for n in free if n in major_set)]
    for nation in sorted(n for n in nations if n in major_set and n in reservations):
        for index in range(1, DRAFT_MAX_COOPS_PER_NATION + 1):
            key = f"{nation}_coop" if index == 1 else f"{nation}_coop_{index}"
            if key not in reservations:
                entries.append((f"{nation} Co-op" if index == 1 else f"{nation} Co-op {index}", key))
                break
    entries.extend((nation, nation) for nation in sorted(n for n in free if n not in major_set))
    filler_key = _draft_next_filler_key(reservations)
    if filler_key:
        entries.append(("Filler", filler_key))
    return entries


def _draft_has_room(game: dict) -> bool:
    """Whether any team can still place a pool player (an open nation, co-op
    or filler) — drafting closes by itself once slots run out."""
    return any(_draft_assignment_entries(game, team.get("key")) for team in _draft_teams(game))


def _draft_advance_turn(game: dict) -> None:
    """After a captain's pick: the same team again while it has picks left,
    else the next team that still has room."""
    draft = game["draft"]
    keys = [team.get("key") for team in _draft_teams(game)]
    current = draft.get("current_turn")
    remaining = max(0, int(draft.get("picks_remaining_this_turn") or 1) - 1)
    if remaining > 0 and current in keys and _draft_assignment_entries(game, current):
        draft["picks_remaining_this_turn"] = remaining
        return
    index = keys.index(current) if current in keys else -1
    for step in range(1, len(keys) + 1):
        candidate = keys[(index + step) % len(keys)]
        if _draft_assignment_entries(game, candidate):
            draft["current_turn"] = candidate
            draft["picks_remaining_this_turn"] = 1
            return
    draft["current_turn"] = None
    draft["picks_remaining_this_turn"] = 0


def _draft_check_complete(game: dict) -> bool:
    """A running draft is complete once the pool is empty or nobody has room."""
    draft = game["draft"]
    if draft.get("phase") == "DRAFTING" and (not draft.get("pool") or not _draft_has_room(game)):
        draft["phase"] = "COMPLETE"
        draft["current_turn"] = None
        draft["picks_remaining_this_turn"] = 0
        return True
    return False


def _build_kaiserreich_list(reservations, locked_regions, game_started, game=None, mode="Kaiserreich (FFA)"):
    """Faction-based reservation list for Kaiserreich.

    Majors use the custom star emojis (green=open, yellow=reserved, red=locked);
    minors use the standard status circles. Nation order follows KAISERREICH_REGIONS.
    """
    cats = NATION_CATEGORIES.get("Kaiserreich (FFA)", KAISERREICH_REGIONS)

    target_game = game or {}
    _major_lock = target_game.get("major_lock_level", "Trusted")
    _minor_lock = target_game.get("minor_lock_level", "All Users")
    late_joins  = target_game.get("late_join_nations", [])

    std_res  = {k: v for k, v in reservations.items() if not k.startswith("_FILL_")}
    fill_res = {k: v for k, v in reservations.items() if k.startswith("_FILL_")}

    if game_started:
        footer = "🚨 **Game Started**"
    else:
        _parts = []
        if _major_lock != "All Users": _parts.append(f"Majors: **{_lock_label(_major_lock)}**")
        if _minor_lock != "All Users": _parts.append(f"Minors: **{_lock_label(_minor_lock)}**")
        footer = f"⚠️ {' | '.join(_parts)}" if _parts else "✅ **All Nations Unlocked.**"

    FACTION_EMOJI = {
        "Entente": "🤝",
        "Third International": "🚩",
        "Reichspakt": "🦅",
        "Moscow Accord": "❄️",
    }

    counts = {"majors": 0, "minors": 0, "coops": 0}
    totals = {"majors": 0, "minors": 0}

    def _coop_suffix(nation):
        mentions = [
            _reservation_mention(std_res[k])
            for k in sorted(std_res)
            if k == f"{nation}_coop" or k.startswith(f"{nation}_coop_")
        ]
        if mentions:
            counts["coops"] += len(mentions)
            return "\n" + "\n".join(f" ↳ *Co-op:* {m}" for m in mentions)
        return ""

    faction_sections = []
    faction_names = []
    for faction, groups in cats.items():
        is_region_locked = faction in locked_regions
        section = [f"**{FACTION_EMOJI.get(faction, '🏳️')} {faction}**"]

        for nation in groups.get("Majors", []):
            totals["majors"] += 1
            uid = std_res.get(nation)
            if uid:
                counts["majors"] += 1
                status = EMOJI_RESERVED_STAR
                line = f"{status} **{nation}** - {_reservation_mention(uid)}"
            elif game_started or is_region_locked or (nation in locked_regions):
                status = EMOJI_LOCKED_STAR
                line = f"{status} **{nation}**"
            else:
                status = EMOJI_UNRESERVED_STAR
                line = f"{status} **{nation}**"
            section.append(line + _coop_suffix(nation))

        for nation in groups.get("Minors", []):
            totals["minors"] += 1
            uid = std_res.get(nation)
            if uid:
                counts["minors"] += 1
                if nation in late_joins:
                    status = EMOJI_LATE_JOIN_CIRCLE
                elif game_started:
                    status = EMOJI_STARTED_CIRCLE
                else:
                    status = EMOJI_RESERVED_CIRCLE
                line = f"{status} {nation} - {_reservation_mention(uid)}"
            # Host-locked nations (Games page / Calendar) are stored by exact nation
            # name in locked_regions alongside whole-faction locks — check both.
            elif game_started or is_region_locked or (nation in locked_regions):
                status = EMOJI_LOCKED_CIRCLE
                line = f"{status} {nation}"
            else:
                status = EMOJI_UNRESERVED_CIRCLE
                line = f"{status} {nation}"
            section.append(line + _coop_suffix(nation))

        faction_sections.append("\n".join(section))
        faction_names.append(faction)

    filler_lines = []
    if fill_res:
        filler_lines.append("\n__*Fillers:*__")
        for k, v in fill_res.items():
            disp = k.replace("_FILL_", "").replace("_", " ")
            status = EMOJI_STARTED_CIRCLE if game_started else EMOJI_RESERVED_CIRCLE
            filler_lines.append(f"{status} {disp} - {_reservation_mention(v)}")
    filler_block = "\n".join(filler_lines)

    summary = f"\n__**Total Reservations: {format_reservation_totals(reservations, mode)}**__\n{footer}"

    # Split the board into two messages, mirroring the standard Roleplay list:
    # message 1 = factions before Reichspakt, message 2 = Reichspakt onward + footer.
    header = "# Kaiserreich FFA Reservation List\n═══════════════════════════"
    split_idx = next((i for i, name in enumerate(faction_names) if name == "Reichspakt"), len(faction_names))

    part1 = header + "".join("\n\n" + s for s in faction_sections[:split_idx])
    part2 = "\n\n".join(faction_sections[split_idx:])
    part2 += ("\n" + filler_block if filler_block else "") + "\n" + summary

    return [part1, part2]


async def _build_roleplay_list(reservations, locked_regions, locked_majors, game_started, game=None, mode="Roleplay"):
    # Kaiserreich uses a dedicated faction-based layout (majors with star emojis).
    if "Kaiserreich" in mode:
        return _build_kaiserreich_list(reservations, locked_regions, game_started, game=game, mode=mode)

    cat_key = get_mapped_mode(mode)
    cats = NATION_CATEGORIES.get(cat_key, NATION_CATEGORIES.get("Roleplay", {}))

    lists = {"majors_list": []}
    counts = {"majors": 0, "minors": 0, "total": 0, "fillers": 0, "coops": 0}
    standard_res = {k: v for k, v in reservations.items() if not k.startswith("_FILL_")}
    filler_res = {k: v for k, v in reservations.items() if k.startswith("_FILL_")}

    major_nations = sorted(cats.get("Majors", []))
    for nation in major_nations:
        u_m, c_m = None, None
        is_reserved = nation in standard_res
        is_nation_locked = (not is_reserved) and (nation in locked_regions)

        if is_reserved:
            u_m = _reservation_mention(standard_res[nation])
            counts["total"] += 1; counts["majors"] += 1
        coop_mentions = [
            _reservation_mention(standard_res[key])
            for key in sorted(standard_res)
            if key == f"{nation}_coop" or key.startswith(f"{nation}_coop_")
        ]
        if coop_mentions:
            c_m = ", ".join(coop_mentions)
            counts["coops"] += len(coop_mentions); counts["total"] += len(coop_mentions)

        # --- THE FIX: DYNAMIC HEARTS FOR MISSING FLAGS ---
        base_flag = get_flag_emoji(nation)
        if base_flag == "🏳️":
            if is_reserved:
                status = "💛" # Reserved
            elif game_started or is_nation_locked:
                status = "❤️" # Game Started / Host-Locked
            else:
                status = "💚" # Open and Available
        else:
            status = base_flag # Uses the real flag if one exists in your dictionary

        lists["majors_list"].append(_generate_nation_line(nation, status, u_m, c_m))

    minor_lines = []
    minors_total = sum(len(v) for k, v in cats.items() if k != "Majors")
    for category, nations in cats.items():
        if category == "Majors": continue
        is_region_locked = category in locked_regions

        # --- FIXED BROKEN UNDERLINES ---
        minor_lines.append(f"\n__{category}:__")

        late_joins = (game or {}).get("late_join_nations", [])
        for nation in sorted(nations):
            u_m = None
            if nation in standard_res:
                u_m = _reservation_mention(standard_res[nation])
                counts["minors"] += 1; counts["total"] += 1
                if nation in late_joins:
                    status = EMOJI_LATE_JOIN_CIRCLE
                elif game_started:
                    status = EMOJI_STARTED_CIRCLE
                else:
                    status = EMOJI_RESERVED_CIRCLE
            # Host-locked nations (Games page / Calendar) are stored by exact nation
            # name in locked_regions alongside whole-region locks — check both.
            elif game_started or is_region_locked or (nation in locked_regions):
                status = EMOJI_LOCKED_CIRCLE
            else:
                status = EMOJI_UNRESERVED_CIRCLE
            minor_lines.append(_generate_nation_line(nation, status, u_m))

    filler_lines = []
    if filler_res:
        counts["fillers"] = len(filler_res); counts["total"] += counts["fillers"]
        filler_lines.append(f"\n__*Fillers:*__")
        for k, v in filler_res.items():
            disp = k.replace("_FILL_", "").replace("_", " ")
            status = "🔴" if game_started else "🟡"
            filler_lines.append(f"{status} {disp} - {_reservation_mention(v)}")

    # --- FIXED FOOTER INJECTION (Indentation Fixed) ---
    target_game = game or {}
    _major_lock = target_game.get("major_lock_level", "Trusted")
    _minor_lock = target_game.get("minor_lock_level", "All Users")

    if game_started:
        footer = "🚨 **Game Started**"
    else:
        _parts = []
        if _major_lock != "All Users":
            _parts.append(f"Majors: **{_lock_label(_major_lock)}**")
        if _minor_lock != "All Users":
            _parts.append(f"Minors: **{_lock_label(_minor_lock)}**")
        footer = f"⚠️ {' | '.join(_parts)}" if _parts else "✅ **All Nations Unlocked.**"

    # --- THE FIX: Split point detection ---
    if "Millennium Dawn" in mode or "Novum Vexillum" in mode:
        split_target = "__Middle East:__"
    elif "Kaiserreich" in mode:
        split_target = "__Asia:__"
    else:
        split_target = "__Asia:__" # Default for standard RP

    split_idx = next((i for i, line in enumerate(minor_lines) if split_target in line), len(minor_lines) // 2)

    return [
        ROLEPLAY_TEMPLATE_START.format(
            mode_name=cat_key,
            majors_reserved=counts["majors"],
            majors_total=len(major_nations),
            majors_list="\n".join(lists["majors_list"]),
            minors_total=minors_total,
            minors_reserved=counts["minors"],
            europe_list="\n".join(minor_lines[:split_idx])
        ),
        ROLEPLAY_TEMPLATE_END.format(
            rest_of_minors="\n".join(minor_lines[split_idx:]),
            filler_section="\n".join(filler_lines),
            total_reserved=format_reservation_totals(reservations, mode),
            footer=footer
        )
    ]

async def _build_historical_list(reservations, locked_regions, locked_majors, game_started, game=None, mode="Historical (Vanilla)"):
    cat_key = get_mapped_mode(mode)
    config = NATION_CATEGORIES.get(cat_key, {})

    std_res = {k: v for k, v in reservations.items() if not k.startswith("_FILL_")}
    fill_res = {k: v for k, v in reservations.items() if k.startswith("_FILL_")}

    target_game = game or {}
    _major_lock = target_game.get("major_lock_level", "Trusted")
    _minor_lock = target_game.get("minor_lock_level", "All Users")

    if game_started:
        footer = "🚨 **Game Started**"
    else:
        _parts = []
        if _major_lock != "All Users":
            _parts.append(f"Majors: **{_lock_label(_major_lock)}**")
        if _minor_lock != "All Users":
            _parts.append(f"Minors: **{_lock_label(_minor_lock)}**")
        footer = f"⚠️ {' | '.join(_parts)}" if _parts else "✅ **All Nations Unlocked.**"

    # Standard historical layout (single message).
    sections = []
    total_reserved = 0

    for faction, structure in config.items():
        faction_lines = [f"\n**__{faction}__**"]

        for group_name in ["Majors", "Important Minors", "Minors", "Minors Minors"]:
            if group_name not in structure: continue
            nations = structure[group_name]
            if not nations: continue

            faction_lines.append(f"\n**{group_name}:**")
            for nation in sorted(nations):
                u_id = std_res.get(nation)
                is_locked = game_started or (faction in locked_regions) or (nation in locked_regions)

                late_joins = (game or {}).get("late_join_nations", [])
                if u_id:
                    total_reserved += 1
                    user_str = _reservation_mention(u_id)
                    if nation in late_joins:
                        status = EMOJI_LATE_JOIN_CIRCLE
                    elif game_started:
                        status = EMOJI_STARTED_CIRCLE if group_name not in ("Majors", "Important Minors") else (EMOJI_LOCKED_STAR if group_name == "Important Minors" else get_flag_emoji(nation))
                    else:
                        if group_name == "Important Minors": status = EMOJI_RESERVED_STAR
                        elif group_name == "Majors": status = get_flag_emoji(nation)
                        else: status = EMOJI_RESERVED_CIRCLE
                elif is_locked:
                    user_str = None
                    if group_name == "Important Minors": status = EMOJI_LOCKED_STAR
                    elif group_name == "Majors": status = get_flag_emoji(nation)
                    else: status = EMOJI_LOCKED_CIRCLE
                else:
                    user_str = None
                    if group_name == "Important Minors": status = EMOJI_UNRESERVED_STAR
                    elif group_name == "Majors": status = get_flag_emoji(nation)
                    else: status = EMOJI_UNRESERVED_CIRCLE

                line = _generate_nation_line(nation, status, user_str)

                coop_mentions = [
                    _reservation_mention(std_res[k])
                    for k in sorted(std_res)
                    if k == f"{nation}_coop" or k.startswith(f"{nation}_coop_")
                ]
                if coop_mentions:
                    line += f"\n🤝 {nation} - " + ", ".join(coop_mentions)
                    total_reserved += len(coop_mentions)

                faction_lines.append(line)

        sections.append("\n".join(faction_lines))

    filler_txt = []
    if fill_res:
        filler_txt.append(f"\n**__Fillers__**")
        for k, v in fill_res.items():
            total_reserved += 1
            name = k.replace("_FILL_", "").replace("_", " ")
            status = "🔴" if game_started else "🟡"
            filler_txt.append(f"{status} {name} - {_reservation_mention(v)}")

    return [HISTORICAL_TEMPLATE.format(
        mode_name=mode,
        faction_sections="\n".join(sections),
        filler_section="\n".join(filler_txt),
        total_reserved=format_reservation_totals(reservations, mode),
        footer=footer
    )]


def _build_layout_list(reservations: dict, game: dict) -> List[str]:
    """Reservation list of a preset game with its own nation groups
    (game["nation_layout"] = [{name, tiers: [{label | None, nations}]}]).
    Nations outside the playable groups aren't listed (they're locked).
    Majors show their flag (or a heart when there's no flag emoji), other
    nations the usual status circles. Whole groups are packed into each
    message so a split never lands in the middle of a group."""
    mode = game.get("mode", "Game")
    locked_regions = game.get("locked_regions") or []
    game_started = bool(game.get("game_started"))
    late_joins = game.get("late_join_nations") or []
    majors = set(get_major_nations_for_mode(mode))
    std_res = {k: v for k, v in reservations.items() if not k.startswith("_FILL_")}
    fill_res = {k: v for k, v in reservations.items() if k.startswith("_FILL_")}

    sections = []
    for group in game.get("nation_layout") or []:
        lines = [f"**__{group.get('name') or 'Nations'}__**"]
        for tier in group.get("tiers") or []:
            if tier.get("label"):
                lines.append(f"**{tier['label']}:**")
            for nation in tier.get("nations") or []:
                uid = std_res.get(nation)
                locked = game_started or is_locked_for_mode(nation, mode, locked_regions)
                if nation in majors:
                    status = get_flag_emoji(nation)
                    if status == "🏳️":
                        status = "💛" if uid else ("❤️" if locked else "💚")
                elif uid:
                    if nation in late_joins:
                        status = EMOJI_LATE_JOIN_CIRCLE
                    elif game_started:
                        status = EMOJI_STARTED_CIRCLE
                    else:
                        status = EMOJI_RESERVED_CIRCLE
                else:
                    status = EMOJI_LOCKED_CIRCLE if locked else EMOJI_UNRESERVED_CIRCLE
                coops = [
                    _reservation_mention(std_res[k])
                    for k in sorted(std_res)
                    if k == f"{nation}_coop" or k.startswith(f"{nation}_coop_")
                ]
                lines.append(_generate_nation_line(
                    nation, status,
                    _reservation_mention(uid) if uid else None,
                    ", ".join(coops) if coops else None,
                ))
        sections.append("\n".join(lines))

    filler_lines = []
    if fill_res:
        filler_lines.append("**__Fillers__**")
        for k, v in fill_res.items():
            name = k.replace("_FILL_", "").replace("_", " ")
            filler_lines.append(f"{'🔴' if game_started else '🟡'} {name} - {_reservation_mention(v)}")

    if game_started:
        footer = "🚨 **Game Started**"
    else:
        parts = []
        if game.get("major_lock_level", "Trusted") != "All Users":
            parts.append(f"Majors: **{_lock_label(game.get('major_lock_level', 'Trusted'))}**")
        if game.get("minor_lock_level", "All Users") != "All Users":
            parts.append(f"Minors: **{_lock_label(game.get('minor_lock_level', 'All Users'))}**")
        footer = f"⚠️ {' | '.join(parts)}" if parts else "✅ **All Nations Unlocked.**"

    tail = (
        ("\n".join(filler_lines) + "\n\n" if filler_lines else "")
        + f"__***Total Reservations: {format_reservation_totals(reservations, mode)}***__\n\n{footer}"
    )
    messages = []
    buf = f"# {mode} Reservation List\n═══════════════════════════"
    for block in [*sections, tail]:
        if len(buf) + 2 + len(block) > RESERVATION_MSG_LIMIT - 100:
            messages.append(buf)
            buf = block
        else:
            buf = f"{buf}\n\n{block}"
    messages.append(buf)
    return messages

