class PuppetPermissionView(View):
    def __init__(self, nation, overlord, main_player_id, applicant, interaction_original):
        super().__init__(timeout=60)
        self.nation = nation
        self.overlord = overlord
        self.main_player_id = main_player_id
        self.applicant = applicant
        self.value = None

    @discord.ui.button(label="Yes, I have permission", style=discord.ButtonStyle.green)
    async def yes_button(self, interaction: discord.Interaction, button: Button):
        self.value = "yes"
        for child in self.children: child.disabled = True
        await interaction.response.edit_message(view=self)
        self.stop()

    @discord.ui.button(label="No, I don't", style=discord.ButtonStyle.red)
    async def no_button(self, interaction: discord.Interaction, button: Button):
        self.value = "no"
        for child in self.children: child.disabled = True
        await interaction.response.edit_message(view=self)
        self.stop()

LOCKDOWN_MESSAGE = "🔒 **Reservation Lockdown:** Reservations are closed. Please ask a host if you need to be added."

async def _perform_reservation(interaction: discord.Interaction, nation: str, games_data: dict, game: dict):
    """Shared reservation logic used by /reserve and /draw.

    Returns a tuple (success: bool, nation: str | None, milestone_message: str).
    On failure it sends its own error message. On success it writes data and refreshes
    the board, but leaves the final confirmation message to the caller.
    """
    user_id = interaction.user.id

    # PERMANENT EMERGENCY-UNRESERVE BLOCK — covers the /reserve and /draw
    # self-service re-entry paths (defense in depth with the per-command
    # checks).
    if _is_emergency_unreserved_blocked(game, user_id):
        await _ephemeral_reply(interaction, _EMERGENCY_UNRESERVE_DENIAL)
        return False, None, ""

    player_stats_data = _get_player_stats_data_sync()
    if not player_stats_data:
        player_stats_data = await _ensure_player_stats_cache()
    game_mode = game.get("mode")
    reservations = game.get("reservations", {})

    max_cap = get_game_capacity(game_mode)
    if count_nation_reservations(reservations) >= max_cap:
        await _ephemeral_reply(interaction, f"❌ **All {max_cap} nation slots are filled.** Ask a host about Co-op or Filler slots!")
        return False, None, ""

    is_other_mode = game_mode == "Other"
    if not is_other_mode:
        all_nations = get_all_nations_for_mode(game_mode)

        # --- CASE-INSENSITIVE AUTO-CORRECT ---
        correct_nation = next((n for n in all_nations if n.lower() == nation.strip().lower()), None)
        if not correct_nation:
            await _ephemeral_reply(interaction, f"❌ '{nation}' is not valid.")
            return False, None, ""
        nation = correct_nation

    # --- IDENTIFY MAJORS & CO-OPS ---
    base_nation = nation.replace("_coop", "")
    try:
        is_major_nation = is_major(base_nation, game_mode)
    except:
        is_major_nation = False

    user_stats = player_stats_data.get(str(user_id), {})

    # --- DISHONORED TITLE CHECK (DB restriction + Discord role / fresh stats) ---
    thread_id_str = str(interaction.channel.id)
    dish_block = await _dishonored_block_for_member(
        interaction.user, game_mode, base_nation, is_major_nation, stats=user_stats
    )
    if dish_block:
        await _ephemeral_reply(interaction, dish_block)
        return False, None, ""

    # --- MAJOR COOLDOWN CHECK (Roleplay Only; VIP bypasses) ---
    if is_major_nation and _is_on_major_cooldown(games_data, user_id, game_mode, thread_id_str):
        if not _member_has_vip(interaction.user):
            last_major = _last_major_nation(games_data, user_id, game_mode, thread_id_str)
            await _ephemeral_reply(
                interaction,
                f"❌ **Major Cooldown:** You played **{last_major}** (Major) in your last logged session. "
                f"You must complete **1 Minor nation** game before picking a Major again.")
            return False, None, ""

    # --- MINOR REPEAT CHECK (Roleplay Only; can't play the same Minor twice in a row; VIP bypasses) ---
    if not is_major_nation and _is_minor_repeat(
            games_data, user_id, game_mode, base_nation, str(interaction.channel.id)):
        if not _member_has_vip(interaction.user):
            await _ephemeral_reply(
                interaction,
                f"❌ **No Repeats:** You played **{base_nation}** in your last {game_mode} game. "
                f"You must play a different Minor before picking it again "
                f"(you can still play **{base_nation}** in a different gamemode).")
            return False, None, ""

    mode_cfg = MODE_CONFIG.get(game_mode, {})

    if nation in reservations:
        await _ephemeral_reply(interaction, f"❌ **{nation}** is already reserved.")
        return False, None, ""

    if user_id in reservations.values():
        await _ephemeral_reply(interaction, "❌ You already have a reservation.")
        return False, None, ""

    # --- ROLE LOCK HELPER ---
    def _check_lock_level(level: str, user_role_ids: list, mode_cfg: dict) -> bool:
        """Returns True if the user has the exact role tier required for this game mode."""
        return _member_meets_lock_level(interaction.user, level, mode_cfg)

    user_role_ids = [r.id for r in interaction.user.roles]

    # --- MAJOR LOCK LOGIC ---
    major_lock_level = game.get("major_lock_level", "Trusted")
    if is_major_nation and not _check_lock_level(major_lock_level, user_role_ids, mode_cfg):
        await _ephemeral_reply(
            interaction, f"❗ Major nations are locked to **{_lock_label(major_lock_level)}** users.")
        return False, None, ""

    # --- MINOR LOCK LOGIC ---
    minor_lock_level = game.get("minor_lock_level", "All Users")
    if not is_major_nation and not _check_lock_level(minor_lock_level, user_role_ids, mode_cfg):
        await _ephemeral_reply(
            interaction, f"❗ Minor nations are locked to **{_lock_label(minor_lock_level)}** users.")
        return False, None, ""

    # --- REGION LOCK ---
    if not is_other_mode:
        locked_list = game.get("locked_regions", [])
        if is_locked_for_mode(nation, game_mode, locked_list):
            await _ephemeral_reply(interaction, f"'{nation}' is currently locked via Region/Faction lock.")
            return False, None, ""

    # --- SPECIAL NATION PERMISSION CHECKS ---
    # 1. ETHIOPIA PERMISSION CHECK (Vanilla/Oak/TFB)
    if "Historical" in game_mode and nation == "Ethiopia" and "Italy" in reservations:
        italy_id = reservations["Italy"]
        view = PuppetPermissionView(nation, "Italy", italy_id, interaction.user, interaction)
        perm_msg = (f"🛡️ **Permission Check**\n**Ethiopia** requires permission from **Italy** (<@{italy_id}>).\nDo you have their permission?")
        if interaction.response.is_done():
            await interaction.followup.send(perm_msg, view=view, ephemeral=True)
        else:
            await interaction.response.send_message(perm_msg, view=view, ephemeral=True)
        await view.wait()
        if view.value != "yes":
            return False, None, ""

    # 2. HORST SPECIFIC CHECKS
    if game_mode == "Historical (Horst)":
        if nation == "Finland":
            soviet_count = sum(1 for n in reservations.keys() if n == "Soviet Union" or n.startswith("Soviet Union_coop"))
            if soviet_count < 4:
                await _ephemeral_reply(
                    interaction,
                    f"❌ **Finland** is locked! Horst rules require **4 Soviet players** (1 Major + 3 Co-ops) before Finland can be picked. Current Soviets: {soviet_count}/4")
                return False, None, ""

        if nation == "Croatia":
            if "Italy" not in reservations:
                await _ephemeral_reply(interaction, "❌ **Croatia** cannot be reserved until **Italy** has been picked.")
                return False, None, ""

            italy_id = reservations["Italy"]
            view = PuppetPermissionView(nation, "Italy", italy_id, interaction.user, interaction)
            perm_msg = (f"🛡️ **Permission Check**\n**Croatia** replaces an Italy coop slot and requires permission from **Italy** (<@{italy_id}>).\nDo you have their permission?")
            if interaction.response.is_done():
                await interaction.followup.send(perm_msg, view=view, ephemeral=True)
            else:
                await interaction.response.send_message(perm_msg, view=view, ephemeral=True)
            await view.wait()
            if view.value != "yes":
                return False, None, ""

        if nation == "Manchukuo":
            if "Japan" not in reservations:
                await _ephemeral_reply(interaction, "❌ **Manchukuo** cannot be reserved until **Japan** has been picked.")
                return False, None, ""

            japan_id = reservations["Japan"]
            view = PuppetPermissionView(nation, "Japan", japan_id, interaction.user, interaction)
            perm_msg = (f"🛡️ **Permission Check**\n**Manchukuo** replaces a Japan coop slot and requires permission from **Japan** (<@{japan_id}>).\nDo you have their permission?")
            if interaction.response.is_done():
                await interaction.followup.send(perm_msg, view=view, ephemeral=True)
            else:
                await interaction.response.send_message(perm_msg, view=view, ephemeral=True)
            await view.wait()
            if view.value != "yes":
                return False, None, ""

    if not interaction.response.is_done():
        await interaction.response.defer(ephemeral=True)

    thread_id_str = str(interaction.channel.id)
    ok, err, games_data, game = await _commit_reservation(thread_id_str, nation, user_id)
    if not ok:
        await _ephemeral_reply(interaction, err)
        return False, None, ""

    game_mode = game.get("mode")

    # Milestone Check (RP)
    milestone_message = ""
    if "Roleplay" in game_mode and len(game["reservations"]) == 30 and game.get("locked_regions"):
        game["locked_regions"] = []
        milestone_message = "\n🔓 **Milestone Hit!** All regions unlocked."
        await write_json(GAMES_FILE, games_data)

    schedule_reservation_update(interaction.channel.id)

    # --- GAMEMODE DM INJECTION ---
    user = interaction.user
    if game_mode == "TFR":
        await send_tfr_info_dm(user, nation)

    return True, nation, milestone_message


