_HOI4_NAME_TO_TAG = {name.lower(): tag for tag, name in HOI4_TAGS.items()}


def _hoi4_tag_for_nation(nation: str) -> str | None:
    """Resolves a reserved nation's name to its HOI4 country tag, if known."""
    if not nation:
        return None
    base = nation.replace("_coop", "").replace("_FILL_", "").strip()
    key = base.lower()
    if key in HOI4_NATION_ALIASES:
        key = HOI4_NATION_ALIASES[key].lower()
    return _HOI4_NAME_TO_TAG.get(key)


