def _slot_autocomplete_value(item: dict) -> str:
    return f"{item.get('host_id', 0)}|{_item_week(item)}|{item.get('day', '')}|{item.get('game_timestamp', 0)}"


async def _resolve_slot_casino_config(slot: dict) -> tuple[list, str, str, str]:
    """Resolve a scheduled slot's casino configuration from the Web Host
    Scheduling Panel (host_settings → nested `randomizers`), falling back to
    the slot's legacy fields when no web config has been saved yet.

    Returns (randomizer_type, randomizer_mode, major_lock, minor_lock)."""
    settings: Optional[dict] = None
    slot_id = str(slot.get("slot_id") or "")
    if slot_id:
        try:
            raw = await _run_mysql_io(
                _fetch_host_settings_mysql, label="host settings read"
            )
            row = (raw or {}).get(slot_id)
            if isinstance(row, dict):
                settings = row.get("settings") or {}
        except Exception as e:
            print(f"[WARN] could not read host settings for slot {slot_id}: {e}")

    rtype = _normalize_randomizer_types(slot.get("randomizer_type") or "all")
    mode = str(slot.get("randomizer_mode") or "casual")
    major = str(slot.get("major_lock_level") or "Trusted")
    minor = str(slot.get("minor_lock_level") or "All Users")

    randomizers = (settings or {}).get("randomizers")
    if isinstance(randomizers, dict):
        types: list = []
        if (randomizers.get("nation") or {}).get("enabled"):
            types.append("nation")
        if (randomizers.get("ideology") or {}).get("enabled"):
            types.append("ideology")
        if (randomizers.get("path") or {}).get("enabled"):
            types.append("path")
        if (randomizers.get("build") or {}).get("enabled"):
            types.append("build")
        rtype = types or ["nation", "ideology"]
        entry = (randomizers.get("nation") or {}).get("entry") or {}
        major = _WEB_ENTRY_LOCK_LEVELS.get(entry.get("major"), major)
        minor = _WEB_ENTRY_LOCK_LEVELS.get(entry.get("minor"), minor)
    return rtype, mode, major, minor






# Used by web calendar edits of announced games (_web_edit_announced_slot).
async def _dm_reservation_schedule_changes(guild: discord.Guild, game_data: dict, thread_id: str,
                                           changes: dict) -> int:
    """DM every reserved player when day, time, or host changed. Returns count sent."""
    reservations = game_data.get("reservations", {}) or {}
    if not changes or not reservations:
        return 0

    mode = game_data.get("mode", "Game")
    lines = []
    if "day" in changes:
        lines.append(f"**Day:** {changes['day']['old']} → **{changes['day']['new']}**")
    if "time" in changes:
        lines.append(
            f"**Time:** <t:{changes['time']['old']}:F> → <t:{changes['time']['new']}:F> "
            f"(<t:{changes['time']['new']}:R>)")
    if "host" in changes:
        lines.append(
            f"**Host:** <@{changes['host']['old']}> → <@{changes['host']['new']}>")

    body = (
        f"📢 **Game Update — {mode}**\n\n"
        f"The game you're reserved for has been updated:\n"
        + "\n".join(lines)
        + f"\n\n**Game:** {_game_discord_ref(game_data, thread_id)}"
    )

    sent = 0
    seen: set[int] = set()
    for uid in reservations.values():
        try:
            uid_int = int(uid)
        except (TypeError, ValueError):
            continue
        if uid_int in seen:
            continue
        seen.add(uid_int)
        try:
            member = guild.get_member(uid_int)
            user = member or await guild.fetch_member(uid_int)
            await user.send(body)
            sent += 1
        except Exception as e:
            print(f"[WARN] Could not DM schedule-change notice to {uid_int}: {e}")
        await asyncio.sleep(0.25)
    return sent


# ==========================================================================
# GAME RULES & MODS — each game's public mods and rules posts (in the mode's
# mods / rules channels). A game starts with its preset's lists or the
# mode's standard ones (posted at announcement); hosts change them on the
# website's Games page (formerly /post_mods and /post_rules).
# ==========================================================================
_game_resource_embed_locks: dict[str, asyncio.Lock] = {}


def _resource_settings(game: dict, resource_type: str) -> dict:
    is_mod = resource_type == "mods"
    mode = game.get("mode", "Unknown")
    base_mode = game.get("base_mode", mode)
    return {
        "is_mod": is_mod,
        "limit": WEB_GAME_MAX_MODS if is_mod else WEB_GAME_MAX_RULES,
        "managed_key": "managed_mods" if is_mod else "managed_rulesets",
        "legacy_key": "custom_mods" if is_mod else "custom_rulesets",
        "message_key": "mod_message_id" if is_mod else "rules_message_id",
        "channel_key": "mods_channel_id" if is_mod else "rules_channel_id",
        "links_key": "mod_links" if is_mod else "rule_links",
        "config": MODE_CONFIG.get(mode if is_mod else base_mode) or {},
    }


def _links_to_resource_entries(links: list[str]) -> list[dict]:
    entries = []
    for raw in links:
        for name, link in re.findall(r"\[([^\]]+)\]\((https?://[^)]+)\)", str(raw), re.IGNORECASE):
            entries.append({"name": name.strip(), "link": link.strip()})
    return entries


def _game_resource_entries(game: dict, resource_type: str) -> list[dict]:
    settings = _resource_settings(game, resource_type)
    if settings["managed_key"] in game:
        return [dict(entry) for entry in game.get(settings["managed_key"]) or []]

    entries = _links_to_resource_entries(list(settings["config"].get(settings["links_key"], [])))
    if not settings["is_mod"] and (game.get("randomizer_only") or game.get("chaos")):
        entries.append(dict(CASINO_RULES_ENTRY))
    entries.extend(dict(entry) for entry in game.get(settings["legacy_key"]) or [])
    return entries


async def _apply_game_resource_entries(guild, key: str, resource_type: str, entries: list[dict]):
    """Replace one game's mods or rules list and edit its public post (or
    post it, if it has none yet). Returns the post (None when the list is
    empty and nothing was posted). Raises ModerationError."""
    lock = _game_resource_embed_locks.setdefault(str(key), asyncio.Lock())
    async with lock:
        games = await _read_games_fresh()
        fresh_key, game = _find_game_entry(games, str(key))
        if not game:
            raise ModerationError("❌ Game not found — it may have been removed.")
        settings = _resource_settings(game, resource_type)
        channel_id = settings["config"].get(settings["channel_key"])
        if not channel_id:
            raise ModerationError(f"❌ No {resource_type} channel is set up for {game.get('mode')}.")
        channel = guild.get_channel(channel_id) or await guild.fetch_channel(channel_id)
        embed = _game_resource_embed(resource_type, entries, game.get("mode", "Unknown"), game.get("start_timestamp"))

        message = None
        message_id = game.get(settings["message_key"])
        if message_id:
            try:
                message = await channel.fetch_message(int(message_id))
            except discord.NotFound:
                message = None
        if message is not None:
            await message.edit(embed=embed)
        elif entries:
            message = await channel.send(embed=embed)
            game[settings["message_key"]] = message.id

        game[settings["managed_key"]] = [dict(entry) for entry in entries]
        game.pop(settings["legacy_key"], None)
        await save_single_game(str(fresh_key or key), game, rewrite_reservations=False)
        return message


async def _process_web_game_resources(req: dict):
    """Games page → replace one game's mods or rules list."""
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None or not _member_is_host(actor):
        return False, None, "❌ Only hosts can change a game's rules and mods."
    thread_id = str(payload.get("thread_id") or "").strip()
    games = await _read_games_fresh()
    key, game = _find_game_entry(games, thread_id)
    if not game:
        return False, None, "❌ Game not found — it may have been removed."
    key = str(key or thread_id)
    if not _can_end_assigned_game(actor, game):
        return False, None, f"❌ Only the game's host (<@{game.get('host_id')}>) or Host Management can do that."
    if str(game.get("status") or "").strip().lower() in ("ended", "cancelled"):
        return False, None, "❌ This game has ended or was cancelled."

    resource = str(payload.get("resource") or "")
    if resource not in ("mods", "rules"):
        return False, None, "❌ Pick the mods or the rules."
    is_mod = resource == "mods"
    entries, err = _web_parse_resource_entries(
        payload.get("entries") if isinstance(payload.get("entries"), list) else [],
        WEB_GAME_MAX_MODS if is_mod else WEB_GAME_MAX_RULES,
        "mods" if is_mod else "rulesets",
    )
    if err:
        return False, None, err
    noun = "Mods" if is_mod else "Rules"
    if entries == _game_resource_entries(game, resource):
        return True, {"resources": {
            "title": f"ℹ️ {noun} unchanged", "summary": "The list already looks like that.",
            "notes": [], "stats": {}, "log_url": None, "entries": entries,
        }}, None
    try:
        message = await _apply_game_resource_entries(bot.get_guild(cur_gid()), key, resource, entries)
    except ModerationError as e:
        return False, None, str(e)
    except discord.HTTPException as e:
        return False, None, f"❌ Discord refused the update: {e}"[:600]
    count = len(entries)
    summary = (
        f"{count} {'mod' if is_mod else 'ruleset'}{'' if count == 1 else 's'} in the public post."
        if count else ("No mods are listed now." if is_mod else "No rulesets are listed now.")
    )
    _audit_log("INFO", f"web {resource} update game={key} by={actor.id} count={count}")
    return True, {"resources": {
        "title": f"{'🛠️' if is_mod else '📖'} {noun} updated",
        "summary": summary,
        "notes": [],
        "stats": {},
        "log_url": message.jump_url if message is not None else None,
        "entries": entries,
    }}, None


# /post_mods and /post_rules moved to the website's Games page
# (_process_web_game_resources above).


def _get_archive_layout(mode, game=None):
    """Return the FULL ordered nation layout for a mode, mirroring the live
    reservation list grouping.

    Returns a list of (category_label, [(subheader_or_None, [nation, ...]), ...]).
    Used by the public archive so it can display EVERY nation (including
    unreserved ones) split into the same categories as the reservation list.
    "Other" returns an empty layout because its nations are dynamic. A preset
    game with its own nation groups (game["nation_layout"]) uses those.
    """
    if game and game.get("nation_layout"):
        return [
            (
                str(group.get("name") or "Nations"),
                [(tier.get("label") or None, list(tier.get("nations") or [])) for tier in group.get("tiers") or []],
            )
            for group in game["nation_layout"]
        ]

    def _from_factions(factions):
        out = []
        for fac, content in factions.items():
            if isinstance(content, dict):
                subs = [(sub, list(nl)) for sub, nl in content.items() if isinstance(nl, list)]
                out.append((fac, subs))
            elif isinstance(content, list):
                out.append((fac, [(None, list(content))]))
        return out

    try:
        if mode == "TFR" and 'TFR_DATA' in globals():
            return _from_factions(TFR_DATA["Factions"])

        cat_key = get_mapped_mode(mode) if 'get_mapped_mode' in globals() else mode
        # "Other" nations are user-named at reserve time, so there is no fixed
        # list to render as "open" — fall back to dynamic (reserved-only) display.
        if mode == "Other":
            return []

        categories = globals().get('NATION_CATEGORIES', {}).get(cat_key, {})
        out = []
        if isinstance(categories, dict):
            for cat, content in categories.items():
                if isinstance(content, list):
                    out.append((cat, [(None, list(content))]))
                elif isinstance(content, dict):
                    subs = [(sub, list(nl)) for sub, nl in content.items() if isinstance(nl, list)]
                    out.append((cat, subs))
        return out
    except Exception as e:
        print(f"⚠️ _get_archive_layout failed for mode {mode}: {e}")
        return []


def _game_action_counts_for_user(game: dict, user_id) -> dict:
    counts = game.get("game_action_counts") or {}
    if not isinstance(counts, dict):
        return {}
    uid = str(user_id)
    action_map = counts.get(uid)
    if not isinstance(action_map, dict) and str(user_id).isdigit():
        try:
            action_map = counts.get(int(user_id))
        except (TypeError, ValueError):
            action_map = None
    return action_map if isinstance(action_map, dict) else {}


def _stored_game_action_amount(game: dict, user_id, action: str) -> int:
    """Host /give /take quantity stored on this game, ignoring feedback-vote merit."""
    uid = str(user_id)
    action_map = _game_action_counts_for_user(game, user_id)
    if action in action_map:
        try:
            return max(0, int(action_map.get(action) or 0))
        except (TypeError, ValueError):
            return 0

    legacy_key = {
        "commend": "game_commends",
        "merit": "game_merits",
        "warn": "game_warns",
        "dishonored": "game_dishonored",
        "ban": "game_bans",
    }.get(action)
    legacy = game.get(legacy_key, []) if legacy_key else []
    if action == "warn":
        applied = (game.get("applied_warns") or {}).get(uid)
        if applied is None:
            applied = (game.get("applied_warns") or {}).get(user_id)
        if applied is not None:
            try:
                return max(0, int(applied))
            except (TypeError, ValueError):
                pass
    if isinstance(legacy, dict):
        try:
            return max(0, int(legacy.get(uid) or legacy.get(user_id) or 0))
        except (TypeError, ValueError):
            return 0
    if isinstance(legacy, list):
        return len([x for x in legacy if str(x) == uid])
    return int(bool(legacy))


def _game_action_amount(game: dict, user_id, action: str) -> int:
    """Net quantity shown beside a player in this game's archive."""
    amount = _stored_game_action_amount(game, user_id, action)
    if action == "merit":
        awarded = game.get("feedback_merit_awarded") or []
        if str(user_id) in {str(x) for x in awarded}:
            amount += int(FEEDBACK_VOTE_MERIT)
    return amount


def _adjust_game_action_count(
    game: dict,
    user_id,
    action: str,
    delta: int = 0,
    *,
    active: bool | None = None,
) -> int:
    """Persist the host-assigned quantity shown beside a player in this game's archive."""
    uid = str(user_id)
    counts = game.setdefault("game_action_counts", {})
    user_counts = counts.setdefault(uid, {})
    if not isinstance(user_counts, dict):
        user_counts = {}
        counts[uid] = user_counts
    if active is None:
        value = max(0, _stored_game_action_amount(game, user_id, action) + int(delta))
    else:
        value = 1 if active else 0
    user_counts[action] = value
    return value


# ==========================================================================
# PUBLIC ARCHIVE SPLIT + SAFETY-CAP HELPERS
# --------------------------------------------------------------------------
# The archive renders category blocks (Majors / Europe / Asia / ...) and is
# packed into multiple Discord messages like the live reservation lists: for
# Roleplay-family modes the split is FORCED above the Asia / Middle East /
# Rhovanion category. Only the newest games may post/edit their archive.
# ==========================================================================

# HARD-CAPPED: only the newest N game sessions may post or edit their public
# archive. Older archives are frozen in place — zero Discord API calls for
# them, even when /give or /take fires (guards the mass-edit / API-leak
# incident from the previous Public Archive system).
PUBLIC_ARCHIVE_EDIT_WINDOW = 7
PUBLIC_ARCHIVE_MAX_CHARS = 2000


def _is_game_in_archive_window(games_data: dict, storage_key: str, game: dict) -> bool:
    """True when `game` is among the newest PUBLIC_ARCHIVE_EDIT_WINDOW game
    sessions. Started sessions always rank above unstarted ones (by their
    start timestamp, snowflake fallback), so upcoming games can never crowd
    a live session out of the window."""
    ranked = []
    for idx, (key, entry) in enumerate((games_data or {}).items()):
        if not isinstance(entry, dict):
            continue
        started = bool(entry.get("game_started")) or entry.get("status") in ("ended", "cancelled")
        ranked.append((0 if started else 1, _game_unix_ts(entry, key), idx))
    if not ranked:
        return False
    ranked.sort(key=lambda item: (item[0], -item[1]))
    top_idx = {item[2] for item in ranked[:PUBLIC_ARCHIVE_EDIT_WINDOW]}
    for idx, (key, entry) in enumerate((games_data or {}).items()):
        if entry is game:
            return idx in top_idx
    return False


def _archive_split_category(mode: str):
    """Category that MUST start a fresh archive chunk (mirrors the live
    reservation-list split points). None = no forced split (faction modes)."""
    if not mode:
        return None
    if "Millennium Dawn" in mode or "Novum Vexillum" in mode:
        return "Middle East"
    if "Kaiserreich" in mode:
        return "Asia"
    if "Roleplay" in mode:
        return "Asia"
    return None


def _build_public_archive_chunks(
    mode: str,
    thread_display: str,
    header_text: str,
    blocks,
    footer: str,
    max_chars: int = PUBLIC_ARCHIVE_MAX_CHARS,
) -> list[str]:
    """Pack header + category blocks + footer into Discord-safe messages.

    Splits land on category boundaries like the live reservation lists (for
    Roleplay-family modes the split is FORCED above the Asia / Middle East /
    Rhovanion category). A single category that alone exceeds the limit falls
    back to line-level splits. The header lives in chunk 1, the footer at the
    very end (never hard-truncated with "…"). Returns ordered chunk strings.
    """
    if not blocks:
        content = f"{header_text}\n{footer}"
        if len(content) > max_chars:
            content = content[: max_chars - 1].rstrip() + "…"
        return [content]

    split_cat = _archive_split_category(mode)
    cont_template = (
        "# 📝 Public Attendance Log: {mode} (Part {i}/{t})\n"
        "**Thread:** {th} — continued"
    )

    block_texts = [
        ("\n".join(block) if isinstance(block, list) else str(block))
        for block in blocks
    ]

    hard_split_idx = None
    if split_cat:
        for idx, block in enumerate(blocks):
            label = (block[0] if block else "").strip()
            if split_cat.lower() in label.lower():
                hard_split_idx = idx
                break
    if hard_split_idx in (0, None):
        hard_split_idx = None

    # Worst-case continuation header keeps the 2000-char budget exact
    # (real part numbers are never longer than "99/99").
    cont_placeholder = cont_template.format(mode=mode, i="99", t="99", th=thread_display)

    groups: list[list[str]] = []
    current: list[str] = []
    current_len = len(header_text)

    def flush():
        nonlocal current, current_len
        if current:
            groups.append(current)
        current = []
        current_len = len(cont_placeholder)

    for idx, text in enumerate(block_texts):
        if idx == hard_split_idx and current:
            flush()  # reservation-list style boundary above the split category
        if current_len + 1 + len(text) <= max_chars:
            current.append(text)
            current_len += 1 + len(text)
            continue
        # Block doesn't fit the current chunk: flush, then re-add — splitting
        # at line boundaries when a single block exceeds a fresh chunk.
        flush()
        for line in text.split("\n"):
            if current_len + 1 + len(line) <= max_chars:
                current.append(line)
                current_len += 1 + len(line)
            else:
                flush()
                current.append(line)
                current_len += 1 + len(line)

    # Footer packs as a final piece so it is never hard-truncated.
    for line in footer.split("\n"):
        if current_len + 1 + len(line) <= max_chars:
            current.append(line)
            current_len += 1 + len(line)
        else:
            flush()
            current.append(line)
            current_len += 1 + len(line)
    flush()

    total = len(groups)
    chunks: list[str] = []
    for idx, group in enumerate(groups):
        if idx == 0:
            chunks.append(header_text + "\n" + "\n".join(group))
        else:
            real = cont_template.format(mode=mode, i=idx + 1, t=total, th=thread_display)
            chunks.append(real + "\n" + "\n".join(group))
    return chunks


def _render_public_archive_content(game: dict):
    """Pure render of the Public Attendance Log for one game.

    Returns (header_text, blocks, footer). Blocks are category groups (lists
    of lines starting with the bold category header) so the chunk packer can
    split on category boundaries exactly like the live reservation lists.
    Kept free of Discord I/O so the whole split logic is testable standalone.
    """
    current_status = game.get("status", "active")
    reservations = game.get("reservations", {})
    present_ids_set = _normalize_uid_set(game.get("present_ids", []))
    dropped_out_set = _normalize_uid_set(game.get("dropped_out", []))
    mode = game.get("mode")

    status_label = "🟢 ACTIVE"
    if current_status == "ended": status_label = "🔴 CLOSED"
    elif current_status == "cancelled": status_label = "🚫 CANCELLED"

    host_id = game.get("host_id")
    host_display = f"<@{host_id}>" if host_id else "Unknown"
    thread_display = game.get("thread_name", "Unknown")

    bot_obj = globals().get("bot")
    banhammer = "🔨"
    if bot_obj is not None:
        try:
            found = discord.utils.get(bot_obj.emojis, name="banhammer")
            if found is not None:
                banhammer = str(found)
        except Exception:
            pass

    def get_status_emojis(uid):
        emojis = ""
        emojis += " ⭐" * _game_action_amount(game, uid, "commend")
        emojis += " 🎖️" * _game_action_amount(game, uid, "merit")
        emojis += " ⚠️" * _game_action_amount(game, uid, "warn")
        if _game_action_amount(game, uid, "dishonored"):
            emojis += " 🩸"
        if _game_action_amount(game, uid, "ban"):
            emojis += f" {banhammer}"
        return emojis

    lines = [
        f"# 📝 Public Attendance Log: {mode}",
        f"**Status:** {status_label}",
        f"**Thread:** {thread_display}",
        f"**Host:** {host_display}",
        "\n> **Explanations:**",
        "> ✅ : Reserved & Present",
        "> ❌ : Reserved — No-Show",
        "> 🚪 : Could not make it — Alerted Host",
        "> 🔑 : Late Join/Hot-Join",
        "> ⛔ : Open / Unreserved Nation",
        "> ⭐ : Received Commendation(s)",
        "> 🎖️ : Received Merit(s)",
        "> ⚠️ : Received Warning(s)",
        "> 🩸 : Received Dishonored",
        f"> {banhammer} : Game Banned",
        "---"
    ]

    late_join_nations = set(game.get("late_join_nations") or [])

    def _presence_emoji(uid, reservation_key=None):
        try:
            uid_int = int(uid)
            if uid_int in dropped_out_set:
                return "🚪"
            if reservation_key in late_join_nations:
                return "🔑"
            return "✅" if uid_int in present_ids_set else "❌"
        except (TypeError, ValueError):
            return "❌"

    def _coop_keys_for(nation):
        """Ordered coop reservation keys for a base nation (nation_coop, nation_coop_2, ...)."""
        keys = []
        if f"{nation}_coop" in reservations:
            keys.append(f"{nation}_coop")
        i = 2
        while f"{nation}_coop_{i}" in reservations:
            keys.append(f"{nation}_coop_{i}")
            i += 1
        return keys

    def _render_reservation(nation, key, uid, is_coop=False, coop_slot=""):
        label = nation
        if is_coop:
            label += f" (Co-op {coop_slot})" if coop_slot else " (Co-op)"
        return f"{_presence_emoji(uid, key)} {label} - <@{uid}>{get_status_emojis(uid)}"

    processed_nations = set()
    layout = _get_archive_layout(mode, game)

    # Each category becomes its own "block" so message splits land on category
    # boundaries (e.g. a new message starting at "Asia"), mirroring the live
    # reservation list instead of cutting a category in half.
    blocks = []

    # --- FULL NATION LIST (every nation, reserved or not) ---
    for category, subsections in layout:
        block = []
        for subheader, nation_list in subsections:
            sub_lines = []
            for nation in nation_list:
                if nation in processed_nations:
                    continue
                processed_nations.add(nation)
                main_id = reservations.get(nation)
                coop_keys = _coop_keys_for(nation)

                if main_id:
                    sub_lines.append(_render_reservation(nation, nation, main_id))
                else:
                    # No one holds the main slot → open nation.
                    sub_lines.append(f"⛔ {nation}")

                for ck in coop_keys:
                    cid = reservations[ck]
                    processed_nations.add(ck)
                    slot = ck[len(nation):].replace("_coop", "").strip("_")
                    sub_lines.append(_render_reservation(nation, ck, cid, is_coop=True, coop_slot=slot))

            if sub_lines:
                if subheader:
                    block.append(f"*{subheader}*")
                block.extend(sub_lines)
        if block:
            blocks.append([f"\n**__{category}__**"] + block)

    # --- OTHER / DYNAMIC NATIONS (custom names, stray coops) ---
    unmapped_keys = [k for k in reservations.keys() if k not in processed_nations and not k.startswith("_FILL_")]
    if unmapped_keys:
        other_block = [f"\n**__Other Nations__**"]
        for k in unmapped_keys:
            uid = reservations[k]
            name = k.replace("_coop_2", " (Co-op 2)").replace("_coop_3", " (Co-op 3)").replace("_coop", " (Co-op)")
            other_block.append(f"{_presence_emoji(uid, k)} {name} - <@{uid}>{get_status_emojis(uid)}")
        blocks.append(other_block)

    filler_keys = [k for k in reservations.keys() if k.startswith("_FILL_")]
    if filler_keys:
        filler_block = [f"\n**__Fillers__**"]
        for k in filler_keys:
            uid = reservations[k]
            name = k.replace("_FILL_", "").replace("_", " ")
            filler_block.append(f"{_presence_emoji(uid, k)} {name} - <@{uid}>{get_status_emojis(uid)}")
        blocks.append(filler_block)

    timestamp = int(datetime.datetime.now().timestamp())
    reservation_count = len(reservations) if isinstance(reservations, dict) else len(reservations or [])
    participant_count = len(present_ids_set)
    footer = (
        f"\n---\n**Reserved:** {reservation_count}\n"
        f"**Users Participated:** {participant_count}\n"
        f"*Last Updated: <t:{timestamp}:f> (<t:{timestamp}:R>)*"
    )

    return "\n".join(lines), blocks, footer


_public_log_update_locks: dict[str, asyncio.Lock] = {}


async def update_public_log(thread_id):
    """Serialize the complete read/render/edit/persist archive refresh per game."""
    key = str(thread_id)
    try:
        games_data = await _load_games_resilient()
        storage_key, game = _find_game_entry(games_data, key)
        if game:
            key = str(
                game.get("lobby_thread_id")
                or game.get("original_thread_id")
                or storage_key
                or key
            )
    except Exception:
        pass
    lock = _public_log_update_locks.setdefault(key, asyncio.Lock())
    async with lock:
        await _update_public_log_unlocked(thread_id)


async def _update_public_log_unlocked(thread_id):
    try:
        games_data = await read_json(GAMES_FILE)

        thread_id_str = str(thread_id)
        storage_key, game = _find_game_entry(games_data, thread_id_str)
        if not game:
            return

        # ── HARD-CAPPED SAFETY VALVE ─────────────────────────────────────
        # Only the newest PUBLIC_ARCHIVE_EDIT_WINDOW game sessions may post or
        # edit their public archive. Anything older is frozen in place — zero
        # Discord API calls for it, even when /give or /take fires for that
        # game (guards the mass-edit / API-leak incident from the old system).
        if not _is_game_in_archive_window(games_data, storage_key or thread_id_str, game):
            return

        current_status = game.get("status", "active")

        # Only post once the game has started, or when finalizing ended/cancelled sessions.
        if not game.get("game_started", False) and current_status not in ("ended", "cancelled"):
            return

        thread_channel = bot.get_channel(int(thread_id)) if _game_has_thread(game) else None
        if not thread_channel and _game_has_thread(game):
            try: thread_channel = await bot.fetch_channel(int(thread_id))
            except: pass

        if thread_channel:
            game["thread_name"] = thread_channel.name

        mode = game.get("mode")
        thread_display = game.get("thread_name", f"Thread #{thread_id}")

        # Pure render: header + category blocks + footer, then packed into
        # Discord-safe chunks (category-boundary splits like the live lists).
        header_text, blocks, footer = _render_public_archive_content(game)
        chunks = _build_public_archive_chunks(mode, thread_display, header_text, blocks, footer)

        mode_config = globals().get("MODE_CONFIG", {}).get(mode, {})
        log_channel_id = mode_config.get("public_log_channel_id")

        if not log_channel_id:
            return

        channel = bot.get_channel(log_channel_id)
        if not channel:
            try:
                channel = await bot.fetch_channel(log_channel_id)
            except discord.NotFound:
                print(f"⚠️ Public Log Channel {log_channel_id} not found.")
                return
            except Exception as e:
                print(f"⚠️ Error fetching log channel: {e}")
                return

        # ── MULTI-CHUNK MESSAGE MANAGEMENT ──────────────────────────────
        # Chunk i of this render lives in public_log_msg_ids[i]. Existing
        # messages are EDITED in place; deleted chunks are re-created once;
        # leftovers from a previous (longer) render are deleted once. All
        # chunk IDs are logged per-game so every later edit targets the same
        # messages of THIS game.
        stored_ids = _normalize_public_log_ids(game.get("public_log_msg_ids"))
        final_ids: list[str] = []

        for idx, chunk in enumerate(chunks):
            existing_id = stored_ids[idx] if idx < len(stored_ids) else ""
            if existing_id.isdigit():
                try:
                    msg = await channel.fetch_message(int(existing_id))
                    await _safe_message_edit(msg, content=chunk)
                    final_ids.append(str(msg.id))
                    continue
                except discord.NotFound:
                    pass  # stored message deleted — recreate it below
                except Exception as e:
                    # Transient edit failure: keep the ID so a retry edits the
                    # same message instead of spamming a duplicate.
                    print(f"[WARN] Public archive edit failed for {existing_id}: {e}")
                    final_ids.append(existing_id)
                    continue
            try:
                msg = await _safe_channel_send(channel, content=chunk)
                final_ids.append(str(msg.id))
            except Exception as e:
                print(f"[WARN] Public archive chunk post failed: {e}")
                if existing_id.isdigit():
                    final_ids.append(existing_id)

        if not final_ids:
            return

        # Delete leftover chunks from an older (longer) render.
        for lid in stored_ids[len(chunks):]:
            try:
                old = await channel.fetch_message(int(lid))
                await old.delete()
            except discord.NotFound:
                pass
            except Exception as e:
                print(f"[WARN] Public archive extra-chunk cleanup for {lid} failed: {e}")

        async with log_update_lock:
            games_data = await _load_games_resilient()
            current_key, game = _find_game_entry(games_data, storage_key or thread_id_str)
            if not game:
                return
            ordered = [str(i) for i in final_ids if str(i).isdigit()]
            game["public_log_msg_ids"] = ordered
            game["public_log_message_id"] = ordered[0] if ordered else None
            # Legacy first-chunk alias (sticky-save merge + old consumers).
            game["archive_message_id"] = ordered[0] if ordered else game.get("archive_message_id")
            await save_single_game(
                current_key or storage_key or thread_id_str,
                game,
                rewrite_reservations=False,
            )

    except Exception as e:
        print(f"⚠️ Critical Error in update_public_log: {e}")
        import traceback
        traceback.print_exc()


# Multi-sample attendance: take SAMPLE_COUNT VC scans spaced `delay` minutes apart.
# A reserved player is logged present only if seen in at least REQUIRED_PRESENT of them.
ATTENDANCE_SAMPLE_COUNT = 5
ATTENDANCE_REQUIRED_PRESENT = 2

# Attendance lives on the web Attendance page (live samples, voice checks,
# participation, overrides, finalize and the audit log). The Discord thread
# only gets a link — no Participation Tracker, Multi-Snapshot Complete or
# Advanced Log Tracker messages. Set False to bring the thread panels back.
ATTENDANCE_WEB_ONLY = True
# The map web app (it hosts /schedule, /database and /attendance).
WEB_SITE_URL = os.getenv("WEB_SITE_URL", HOST_CALENDAR_URL.rsplit("/schedule", 1)[0]).rstrip("/")


def _map_game_url(thread_id) -> str:
    """The website map opened on one game — where players reserve and unreserve."""
    return f"{WEB_SITE_URL}/?game={thread_id}"


def _crash_report_url(game_id) -> str:
    """The website's crash report form for one game."""
    return f"{WEB_SITE_URL}/crash?game={game_id}"


def _game_has_thread(game) -> bool:
    """Games announced before late October 2026 have a reservation thread;
    newer ones only have the announcement post (the website does the rest)."""
    return isinstance(game, collections.abc.Mapping) and not game.get("no_thread")


def _game_discord_ref(game, key) -> str:
    """Where to point people at a game in embeds and DMs: its reservation
    thread (older games), else its page on the website map."""
    return f"<#{key}>" if _game_has_thread(game) else _map_game_url(key)


def _attendance_page_url(game_id) -> str:
    return f"{WEB_SITE_URL}/attendance?game={game_id}"


async def _post_attendance_link(game: dict, thread_key, *, finalized: bool = False) -> None:
    """Point the Host Control Center at the web Attendance page (once when
    the game starts, once when attendance is finalized)."""
    try:
        channel = await _resolve_host_control_center(game, thread_key)
        if channel is None:
            return
        url = _attendance_page_url(_attendance_stable_id(game, thread_key))
        view = discord.ui.View()
        view.add_item(discord.ui.Button(label="Open attendance", emoji="📡", style=discord.ButtonStyle.link, url=url))
        if finalized:
            players = len({str(v) for v in (game.get("reservations") or {}).values()})
            present = len(game.get("present_ids") or [])
            host_id = game.get("host_id")
            await channel.send(
                (f"<@{host_id}> " if host_id else "")
                + f"✅ **Attendance finalized** — {present}/{players} present. "
                  "Review it, fix mistakes and read the full log on the web.",
                view=view,
            )
            return
        if game.get("attendance_link_message_id"):
            return
        message = await channel.send(
            "📡 **Attendance is tracked on the web** — live samples, who's in voice, participation "
            "replies, host overrides and the full audit log.",
            view=view,
        )
        games = await _load_games_resilient()
        key, fresh = _find_game_entry(games, thread_key)
        if fresh:
            fresh["attendance_link_message_id"] = str(message.id)
            await save_single_game(key or str(thread_key), fresh, rewrite_reservations=False)
    except Exception as e:
        print(f"[WARN] Attendance link post failed for {thread_key}: {e}")

# Give players time to press Yes/No before the Participation Tracker renders its
# first real list — posting immediately at /game_start just shows a wall of
# "pending" entries that all flip a few seconds later, causing extra edits/noise.
PARTICIPATION_TRACKER_DELAY_SEC = 300

# In-memory registry so we never double-launch the same lobby's snapshot loop
# (e.g. /game_start + on_ready resume).
_attendance_snapshot_tasks: dict[str, asyncio.Task] = {}


async def _load_games_resilient() -> dict:
    """Prefer a fresh MySQL reload; fall back to the in-memory cache on blips."""
    try:
        return await _read_games_fresh()
    except Exception as e:
        print(f"⚠️ Fresh games reload failed ({e}); using cache fallback.")
        cached = get_cached_games_data()
        if cached:
            return dict(cached)
        try:
            return await read_json(GAMES_FILE)
        except Exception as e2:
            print(f"⚠️ Cache/read_json games fallback also failed: {e2}")
            return {}


def _find_game_entry(games: dict, thread_id) -> tuple[str | None, dict | None]:
    """Locate a game by lobby thread id, host-panel id, or migrated key."""
    key = str(thread_id)
    if key in games:
        return key, games[key]
    for k, g in (games or {}).items():
        if not isinstance(g, dict):
            continue
        for field in ("lobby_thread_id", "original_thread_id", "host_panel_thread_id", "thread_id"):
            if str(g.get(field) or "") == key:
                return str(k), g
    return None, None


async def _resolve_host_control_center(game: dict, *candidate_ids):
    """Resolve only a thread inside the configured chatlogs forum."""
    if not _game_has_thread(game) and not game.get("host_panel_thread_id"):
        return None  # newer games have no threads at all
    ids = [
        game.get("host_panel_thread_id"),
        game.get("thread_id"),
        *candidate_ids,
    ]
    seen = set()
    for raw_id in ids:
        if not raw_id or str(raw_id) in seen or not str(raw_id).isdigit():
            continue
        seen.add(str(raw_id))
        channel = bot.get_channel(int(raw_id))
        if channel is None:
            try:
                channel = await bot.fetch_channel(int(raw_id))
            except Exception:
                channel = None
        if channel is None:
            continue
        parent_id = getattr(channel, "parent_id", None)
        parent = getattr(channel, "parent", None)
        if int(parent_id or getattr(parent, "id", 0) or 0) == G.HOST_FORUM_CHANNEL_ID:
            return channel
    return None


async def _game_still_snapshottable(thread_id) -> tuple[str | None, dict | None]:
    """Return (storage_key, game) if the lobby is still eligible for sampling.

    Never treats a transient MySQL failure as "game over" — that was aborting
    the loop after sample 1 whenever the DB hiccuped during a long session.
    """
    games = await _load_games_resilient()
    storage_key, game = _find_game_entry(games, thread_id)
    if not game or not game.get("game_started", False):
        return None, None
    if game.get("status") in ("ended", "cancelled"):
        return None, None
    if game.get("snapshot_done"):
        return None, None
    return storage_key, game


def _attendance_meta(game: dict, guild) -> None:
    """Per-slot no-show penalty and VIP immunity, so the web Attendance page
    can show what finalize will do before it happens."""
    mode = game.get("mode")
    logging_mode = game.get("logging_mode", "Strict")
    penalties = {}
    for slot in (game.get("reservations") or {}):
        try:
            penalties[str(slot)] = _attendance_no_show_penalty(slot, mode, logging_mode)
        except Exception:
            pass
    game["attendance_penalties"] = penalties
    vip_ids = []
    for value in {str(v) for v in (game.get("reservations") or {}).values()}:
        if not value.isdigit():
            continue
        member = guild.get_member(int(value)) if guild else None
        try:
            if _member_has_vip(member) or _user_is_vip(guild, int(value)):
                vip_ids.append(value)
        except Exception:
            pass
    game["attendance_vip_ids"] = sorted(vip_ids)


async def _take_attendance_sample(thread_key, guild, *, manual_by=None) -> tuple[dict | None, int, str | None]:
    """Take and persist the next of the ATTENDANCE_SAMPLE_COUNT samples.

    Used by the background loop and by "Take sample now" on the web. Each
    sample stores who counted plus why every reserved player did or didn't
    (state / voice channel / Gamer Pass / Discord status).
    Returns (sample entry or None, samples done, user-facing error or None)."""
    games = await _load_games_resilient()
    storage_key, game = _find_game_entry(games, thread_key)
    if not game:
        return None, 0, "❌ Game not found."
    # Refresh the member / voice cache before taking the lock (can take a while).
    try:
        if hasattr(guild, "chunk"):
            await asyncio.wait_for(guild.chunk(cache=True), timeout=30)
    except Exception:
        pass

    stable_id = _attendance_stable_id(game, storage_key)
    lock = _attendance_finalize_locks.setdefault(stable_id, asyncio.Lock())
    async with lock:
        games = await _load_games_resilient()
        storage_key, game = _find_game_entry(games, storage_key or thread_key)
        if not game:
            return None, 0, "❌ Game not found."
        logs = list(game.get("presence_snapshots") or [])
        if not game.get("game_started"):
            return None, len(logs), "⚠️ This game hasn't started yet."
        if game.get("snapshot_done"):
            return None, len(logs), "ℹ️ Attendance is already finalized."
        if game.get("status") in ("ended", "cancelled"):
            return None, len(logs), "ℹ️ The game is over — attendance finalizes from the samples already taken."
        if len(logs) >= ATTENDANCE_SAMPLE_COUNT:
            return None, len(logs), "ℹ️ All samples are already taken."

        dropped = {int(x) for x in game.get("dropped_out", []) if str(x).isdigit()}
        try:
            scanned, details = _scan_voice_states(guild, game)
        except Exception as scan_err:
            print(f"⚠️ Sample VC scan failed for {thread_key}: {scan_err}")
            scanned, details = [], {}
        for uid in dropped:
            if str(uid) in details:
                details[str(uid)]["state"] = "dropped"
        present_now = sorted(p for p in scanned if p not in dropped)
        entry = {
            "index": len(logs) + 1,
            "ts": int(time.time()),
            "present_ids": present_now,
            "count": len(present_now),
            "states": details,
        }
        if manual_by:
            entry["manual"] = True
            entry["by"] = str(manual_by)
        logs.append(entry)
        game["presence_snapshots"] = logs
        game["snapshot_samples_done"] = len(logs)
        _attendance_meta(game, guild)
        await save_single_game(storage_key or str(thread_key), game, rewrite_reservations=False)

    record_attendance_event(
        stable_id,
        "sample",
        actor_id=manual_by,
        details={"index": entry["index"], "count": entry["count"], "manual": bool(manual_by)},
    )
    print(f"📸 Sample {entry['index']}/{ATTENDANCE_SAMPLE_COUNT} for {thread_key}: {entry['count']} present"
          + (" (taken from the web)" if manual_by else ""))
    return entry, len(logs), None


def _launch_attendance_snapshot(thread_id, delay, guild_id=None, resume: bool = False):
    """Create (or no-op) the background snapshot task for a lobby."""
    thread_key = str(thread_id)
    existing = _attendance_snapshot_tasks.get(thread_key)
    if existing and not existing.done():
        print(f"📸 Snapshot task already running for {thread_key} — skip launch.")
        return existing

    task = bot.loop.create_task(
        perform_attendance_snapshot(thread_id, delay, guild_id=guild_id, resume=resume),
        name=f"attendance_snapshot_{thread_key}",
    )
    _attendance_snapshot_tasks[thread_key] = task

    def _cleanup(t: asyncio.Task, key=thread_key):
        cur = _attendance_snapshot_tasks.get(key)
        if cur is t:
            _attendance_snapshot_tasks.pop(key, None)

    task.add_done_callback(_cleanup)
    return task


# How long to leave an ended game for /game_end's own finalize (with its bonus
# live scan) before the sampling loop finalizes it as a fallback.
ATTENDANCE_END_GRACE_SEC = 120


async def perform_attendance_snapshot(thread_id, delay, guild_id=None, resume: bool = False):
    """Run the ATTENDANCE_SAMPLE_COUNT VC samples (interval = host delay), then
    finalize. Example: delay=20 → samples at T+20, T+40 … T+100. Present if ≥2/5.

    Due-time based and restart-proof: every pass re-reads the persisted
    samples, so a sample taken early from the web Attendance page simply moves
    the next one along (each is due `delay` minutes after the latest one), and
    a bot restart resumes exactly where it left off.
    """
    thread_key = str(thread_id)
    try:
        interval_sec = max(1, int(delay)) * 60
        print(
            f"📸 Multi-snapshot {'resumed' if resume else 'started'} for {thread_key}: "
            f"{ATTENDANCE_SAMPLE_COUNT} samples every {delay} min "
            f"(need {ATTENDANCE_REQUIRED_PRESENT}+ to count as present)..."
        )

        gid = int(guild_id) if guild_id else cur_gid()
        enter_guild(gid)  # this task works for the game's server from here on
        guild = bot.get_guild(gid)
        if not guild:
            try:
                guild = await bot.fetch_guild(gid)
            except Exception:
                guild = None
        if not guild:
            print(f"📸 Snapshot aborted for {thread_key}: guild unavailable.")
            return

        launched_at = int(time.time())
        ended_seen_at = None
        while True:
            storage_key, game = await _game_still_snapshottable(thread_key)
            if not game:
                games_check = await _load_games_resilient()
                sk2, g2 = _find_game_entry(games_check, thread_key)
                if g2 and (g2.get("snapshot_done") or g2.get("status") == "cancelled"):
                    return
                if g2 and g2.get("status") == "ended":
                    # /game_end finalizes with a bonus live scan; only step in
                    # if that didn't happen.
                    ended_seen_at = ended_seen_at or int(time.time())
                    if int(time.time()) - ended_seen_at < ATTENDANCE_END_GRACE_SEC:
                        await asyncio.sleep(30)
                        continue
                    logs = list(g2.get("presence_snapshots") or [])
                    if logs:
                        print(f"📸 Game {thread_key} ended mid-sampling ({len(logs)}/{ATTENDANCE_SAMPLE_COUNT}) — fallback finalize.")
                        sets = [{int(u) for u in (e.get("present_ids") or []) if str(u).isdigit()} for e in logs]
                        await _finalize_attendance_results(sk2 or thread_key, guild, delay, sets, logs)
                    return
                if g2 and not g2.get("game_started"):
                    return
                # Missing / unreadable for now (DB blip) — keep trying.
                await asyncio.sleep(30)
                continue

            logs = list(game.get("presence_snapshots") or [])
            if len(logs) >= ATTENDANCE_SAMPLE_COUNT:
                sets = [{int(u) for u in (e.get("present_ids") or []) if str(u).isdigit()} for e in logs]
                await _finalize_attendance_results(storage_key or thread_key, guild, delay, sets, logs)
                return

            last_ts = int(logs[-1].get("ts") or 0) if logs else int(game.get("game_started_at") or launched_at)
            wait = last_ts + interval_sec - int(time.time())
            if wait > 0:
                await asyncio.sleep(min(wait, 30))
                continue

            entry, _done, err = await _take_attendance_sample(thread_key, guild)
            if entry is None:
                print(f"📸 Sample skipped for {thread_key}: {err}")
                await asyncio.sleep(30)

    except asyncio.CancelledError:
        print(f"📸 Snapshot task cancelled for {thread_key}.")
        raise
    except Exception as e:
        print(f"⚠️ Error during snapshot for thread {thread_id}: {e}")
        import traceback
        traceback.print_exc()
        # Last-ditch: if all samples are on disk, don't lose the finalize.
        try:
            games = await _load_games_resilient()
            sk, g = _find_game_entry(games, thread_key)
            logs = list((g or {}).get("presence_snapshots") or [])
            if logs and g and not g.get("snapshot_done"):
                sets = [
                    {int(u) for u in (entry.get("present_ids") or []) if str(u).isdigit()}
                    for entry in logs
                ]
                guild = bot.get_guild(cur_gid())
                if guild and len(sets) >= ATTENDANCE_SAMPLE_COUNT:
                    await _finalize_attendance_results(
                        sk or thread_key, guild, delay, sets, logs
                    )
        except Exception as e2:
            print(f"⚠️ Snapshot recovery finalize failed: {e2}")


async def resume_incomplete_attendance_snapshots():
    """After a bot restart, continue any lobby that still needs samples 2–5."""
    try:
        games = await _load_games_resilient()
    except Exception as e:
        print(f"⚠️ Could not resume attendance snapshots: {e}")
        return

    resumed = 0
    for key, game in list((games or {}).items()):
        if not isinstance(game, dict):
            continue
        if not game.get("game_started"):
            continue
        if game.get("snapshot_done"):
            continue
        if game.get("status") in ("ended", "cancelled"):
            continue
        done = int(game.get("snapshot_samples_done") or 0)
        delay = int(game.get("snapshot_interval_minutes") or 20)
        # Prefer the original lobby thread id so lookups stay stable across migration.
        launch_id = game.get("lobby_thread_id") or game.get("original_thread_id") or key
        print(
            f"📸 Resuming attendance for {launch_id} "
            f"(storage={key}, {done}/{ATTENDANCE_SAMPLE_COUNT} done, delay={delay}m)"
        )
        _launch_attendance_snapshot(launch_id, delay, guild_id=_game_guild_id(game), resume=True)
        resumed += 1

    if resumed:
        print(f"📸 Resumed {resumed} incomplete attendance snapshot task(s).")
    else:
        print("📸 No incomplete attendance snapshots to resume.")


_attendance_finalize_locks: dict[str, asyncio.Lock] = {}


def _attendance_no_show_penalty(slot_key: str, mode: str, logging_mode: str) -> int:
    """Canonical no-show penalty for main, filler, and co-op reservation slots."""
    slot_key = str(slot_key)
    is_filler = slot_key.startswith("_FILL_")
    is_coop = "_coop" in slot_key
    base_nation = slot_key.replace("_FILL_", "").split("_coop", 1)[0]
    nation_is_major = bool(is_major(base_nation, mode))
    if logging_mode == "Casual" and (not nation_is_major or is_filler or is_coop):
        return 0
    return 2 if nation_is_major and not is_filler and not is_coop else 1


async def _finalize_attendance_results(thread_key: str, guild, delay, sample_sets: list, sample_logs: list,
                                       *, by=None) -> None:
    """Serialize all attendance finalization paths for the same game.
    `by` = the host who finalized early from the web (None = automatic)."""
    games = await _load_games_resilient()
    storage_key, game = _find_game_entry(games, thread_key)
    stable_key = str(
        (game or {}).get("lobby_thread_id")
        or (game or {}).get("original_thread_id")
        or storage_key
        or thread_key
    )
    lock = _attendance_finalize_locks.setdefault(stable_key, asyncio.Lock())
    async with lock:
        await _finalize_attendance_results_locked(
            thread_key, guild, delay, sample_sets, sample_logs, by=by
        )


async def _finalize_attendance_results_locked(thread_key: str, guild, delay, sample_sets: list, sample_logs: list,
                                              *, by=None) -> None:
    """Shared attendance finalization — computes hit-counts / present_ids, applies
    no-show warnings, persists everything, and posts the Advanced Log Tracker panel.

    Used by BOTH:
      • The normal path: all `ATTENDANCE_SAMPLE_COUNT` samples were taken (called
        from the tail of `perform_attendance_snapshot`).
      • The early-finalize path: `/game_end` ran before all samples were taken
        (called from `_finalize_game_attendance`, using whatever partial samples
        were persisted so far plus one bonus live scan).

    Idempotent/race-safe: no-ops if the game is missing, never started, was
    cancelled, or was already finalized (`snapshot_done`).
    """
    games = await _load_games_resilient()
    storage_key, game = _find_game_entry(games, thread_key)
    if not game:
        game = games.get(str(thread_key))
        storage_key = str(thread_key) if game else None
    if not game or not game.get("game_started", False):
        return
    if game.get("snapshot_done"):
        return
    if game.get("status") == "cancelled":
        print(f"📸 Snapshot finalize aborted for {thread_key}: status=cancelled.")
        return
    thread_id = storage_key or str(thread_key)
    thread_key = thread_id
    dropped_out_set = {int(x) for x in game.get("dropped_out", []) if str(x).isdigit()}
    # Host overrides set on the web Attendance page before finalize:
    # present / absent win over the samples; excused = like a dropped-out
    # player (no warning, not counted as attended).
    overrides = {
        int(k): v for k, v in (game.get("attendance_overrides") or {}).items()
        if str(k).isdigit() and isinstance(v, dict)
    }
    dropped_out_set |= {uid for uid, o in overrides.items() if o.get("verdict") == "excused"}
    hit_counts: dict[int, int] = {}
    for s in sample_sets:
        for uid in s:
            hit_counts[uid] = hit_counts.get(uid, 0) + 1

    total_samples = len(sample_sets)
    # Full run → the usual 2-of-5 rule applies. If the game ended early with
    # fewer samples taken, we can't demand 2/5 out of only 1-2 samples — fall
    # back to "present in every sample that was actually taken" instead, and
    # (below) skip auto-punishing no-shows since the evidence is too thin.
    confident = total_samples >= ATTENDANCE_REQUIRED_PRESENT
    required = ATTENDANCE_REQUIRED_PRESENT if confident else (total_samples if total_samples > 0 else None)

    # Anyone host already marked present via mid-game tools still counts.
    host_marked = _normalize_uid_set(game.get("present_ids", []))
    present = []
    if required is not None:
        present = [uid for uid, hits in hit_counts.items() if hits >= required and uid not in dropped_out_set]
    for uid in host_marked:
        if uid not in dropped_out_set and uid not in present:
            present.append(uid)
    for uid, override in overrides.items():
        if override.get("verdict") == "present" and uid not in dropped_out_set and uid not in present:
            present.append(uid)
        elif override.get("verdict") == "absent" and uid in present:
            present.remove(uid)
    present = sorted(set(present))
    present_set = set(present)

    game["present_ids"] = present
    game["presence_snapshots"] = sample_logs
    game["presence_hit_counts"] = {str(uid): hits for uid, hits in hit_counts.items()}
    game["snapshot_done"] = True
    game["snapshot_samples_done"] = total_samples
    game["attendance_confident"] = confident
    game["attendance_early_ended"] = total_samples < ATTENDANCE_SAMPLE_COUNT
    game["attendance_finalized_at"] = int(time.time())
    game["attendance_finalized_by"] = str(by) if by else "auto"
    _attendance_meta(game, guild)

    player_stats = await read_json(PLAYER_STATS_FILE)
    reservations = game.get("reservations", {})
    game.setdefault("game_warns", [])
    game.setdefault("game_bans", [])
    game.setdefault("spent_commends", {})
    game.setdefault("applied_warns", {})

    new_warned_users = []
    automatic_warning_records = []
    absent_report = []
    mode = game.get("mode")
    gamer_pass_role_id = game.get("temp_gamer_pass_role")
    logging_mode = game.get("logging_mode", "Strict")
    is_major_func = globals().get("is_major", lambda n, m: False)

    for nation, uid in reservations.items():
        uid_str = str(uid)

        try:
            if int(uid) in dropped_out_set:
                continue
        except (TypeError, ValueError):
            pass

        if uid_str not in player_stats:
            player_stats[uid_str] = {
                "total_games": 0, "history": [], "commends": 0,
                "warns": 0, "banned": False
            }
        if "history" not in player_stats[uid_str]:
            player_stats[uid_str]["history"] = []

        stats = player_stats[uid_str]
        member = guild.get_member(int(uid)) if (guild and str(uid).isdigit()) else None
        hits = hit_counts.get(int(uid), 0) if str(uid).isdigit() else 0
        mod_context = get_mod_context(mode) or get_mod_context("Roleplay")
        warn_key = mod_context["key_warn"]
        ban_key = mod_context["key_ban"]

        if int(uid) not in present_set:
            reason = (
                f"Seen in {hits}/{total_samples} sample(s) taken "
                f"(need {ATTENDANCE_REQUIRED_PRESENT}+ of {ATTENDANCE_SAMPLE_COUNT})"
            )
            if member and member.voice and member.voice.channel:
                if member.voice.channel.id in {int(cid) for cid in LOBBY_VC_IDS if cid}:
                    reason += " · now in Lobby VC"
                elif gamer_pass_role_id and not any(r.id == gamer_pass_role_id for r in member.roles):
                    reason += f" · now in {member.voice.channel.name} without Gamer Pass"
                else:
                    reason += f" · now in {member.voice.channel.name}"
            elif not member or not member.voice:
                reason += f" · Discord status: {_discord_presence_label(member)} · not in VC at final sample"
            override = overrides.get(int(uid)) if str(uid).isdigit() else None
            host_marked_absent = bool(override and override.get("verdict") == "absent")
            if host_marked_absent:
                reason = f"Marked absent by the host — {override.get('reason') or 'no reason given'}"

            absent_report.append((uid, reason, nation))

            # Not enough sampling evidence yet (game ended very early) — don't
            # auto-punish unless the host explicitly marked them absent; the
            # web Attendance page lists them for manual review.
            if not confident and not host_marked_absent:
                continue

            # VIP players are immune to automatic no-show warnings.
            if _member_has_vip(member) or _user_is_vip(guild, uid):
                continue

            is_coop = "_coop" in nation
            penalty = _attendance_no_show_penalty(nation, mode, logging_mode)
            if penalty == 0:
                continue

            # Commends never cancel warnings automatically: hosts redeem them
            # on purpose from the web Database page.
            warns_to_add = penalty

            if warns_to_add > 0:
                stats[warn_key] = stats.get(warn_key, 0) + warns_to_add
                game["applied_warns"][uid_str] = (
                    int(game["applied_warns"].get(uid_str, 0)) + warns_to_add
                )
                if uid not in game["game_warns"]:
                    game["game_warns"].append(uid)
                new_warned_users.append(uid)
                automatic_warning_records.append({
                    "user_id": uid,
                    "amount": warns_to_add,
                    "mode": mod_context["label"],
                    "nation": nation,
                    "reason": reason,
                    "warns_total": stats[warn_key],
                    "auto_banned": stats[warn_key] >= G.WARNINGS_FOR_BAN and not stats.get(ban_key),
                })

                if stats[warn_key] >= G.WARNINGS_FOR_BAN:
                    newly_banned = not stats.get(ban_key)
                    stats[ban_key] = True
                    if uid not in game["game_bans"]:
                        game["game_bans"].append(uid)
                    if member:
                        ban_role = guild.get_role(mod_context["role_banned"])
                        try:
                            if ban_role:
                                await member.add_roles(ban_role, reason=f"Auto-Ban: {G.WARNINGS_FOR_BAN} warns")
                        except Exception:
                            pass
                    if newly_banned:
                        # Same as every game ban: banned mode's commends + all
                        # Merit to 0, Trusted (RP + MP) and Valor removed.
                        await _apply_game_ban_wipe(stats, member, mod_context, f"Auto-Ban: {G.WARNINGS_FOR_BAN} warns")

            if member:
                dm_lines = []
                if warns_to_add > 0:
                    dm_lines.append(
                        f"⚠️ You were marked as **No-Show** for the {mode} game "
                        f"(present in {hits}/{ATTENDANCE_SAMPLE_COUNT} attendance checks) "
                        f"and received **{warns_to_add} warning(s)**."
                    )
                    dm_lines.append(f"Your current {mod_context['label']} warnings: {stats[warn_key]}/3.")
                if stats.get(ban_key):
                    dm_lines.append(
                        f"🚨 **You have reached 3 {mod_context['label']} warnings and are now GAME BANNED.**"
                    )
                if dm_lines:
                    try:
                        await member.send(
                            "\n".join(dm_lines),
                            view=build_moderation_feedback_view() if warns_to_add > 0 else None,
                        )
                    except Exception:
                        pass
        else:
            stats["total_games"] = stats.get("total_games", 0) + 1

            is_coop = "_coop" in nation
            if "Roleplay" in mode and not is_coop:
                if not isinstance(stats.get("minor_streaks"), dict):
                    stats["minor_streaks"] = {}
                if not isinstance(stats.get("last_major_nation"), dict):
                    stats["last_major_nation"] = {}

                base_nation = nation.replace("_FILL_", "").split("_coop", 1)[0]
                if is_major_func(base_nation, mode):
                    stats["minor_streaks"][mode] = 0
                    stats["last_major_nation"][mode] = base_nation
                else:
                    stats["minor_streaks"][mode] = 1
                    stats["last_major_nation"].pop(mode, None)

            today = datetime.datetime.now().strftime("%Y-%m-%d")
            stats["history"].append({
                "date": today,
                "nation": nation,
                "mode": mode,
                "participated": True,
                "game_id": str(
                    game.get("lobby_thread_id")
                    or game.get("original_thread_id")
                    or thread_key
                ),
            })

    await write_json(PLAYER_STATS_FILE, player_stats)
    await _refresh_player_stats_cache()
    await save_single_game(thread_key, game, rewrite_reservations=False)

    for record in automatic_warning_records:
        try:
            warning_embed = discord.Embed(
                title="⚠️ Automatic No-Show Warning",
                color=discord.Color.orange(),
                timestamp=discord.utils.utcnow(),
            )
            warning_embed.add_field(
                name="Target", value=f"<@{record['user_id']}>", inline=True
            )
            warning_embed.add_field(
                name="Amount", value=str(record["amount"]), inline=True
            )
            warning_embed.add_field(
                name="Mode", value=record["mode"], inline=True
            )
            warning_embed.add_field(
                name="Reservation", value=record["nation"], inline=False
            )
            warning_embed.add_field(
                name="Reason", value=record["reason"][:1024], inline=False
            )
            log_ref = await send_host_log_embed(warning_embed)
        except Exception as log_error:
            log_ref = None
            print(
                f"[WARN] Automatic no-show warning log failed for "
                f"{record['user_id']}: {log_error}"
            )
        # Web portfolio record (moderation_events).
        record_moderation_event(
            record["user_id"],
            "warn",
            mode=record["mode"],
            amount=record["amount"],
            reason=record["reason"],
            thread_id=thread_key,
            automatic=True,
            details={"nation": record["nation"], "kind": "no-show"},
            log=log_ref,
        )
        if record.get("auto_banned"):
            record_moderation_event(
                record["user_id"],
                "ban",
                mode=record["mode"],
                reason=f"Automatic: reached {record['warns_total']} {record['mode']} warnings (no-show)",
                thread_id=thread_key,
                automatic=True,
                log={"url": log_ref["url"]} if log_ref else None,
            )

    # Web Attendance page audit trail.
    stable_id = _attendance_stable_id(game, thread_key)
    for record in automatic_warning_records:
        record_attendance_event(
            stable_id, "no_show_warning", user_id=record["user_id"],
            details={"amount": record["amount"], "nation": record["nation"], "reason": record["reason"],
                     "auto_banned": bool(record.get("auto_banned"))},
        )
    record_attendance_event(
        stable_id,
        "finalized",
        actor_id=by,
        details={
            "present": len(present),
            "absent": len(absent_report),
            "samples": total_samples,
            "confident": confident,
            "warnings": sum(int(r["amount"]) for r in automatic_warning_records),
            "how": "web" if by else ("full" if total_samples >= ATTENDANCE_SAMPLE_COUNT else "early"),
        },
    )

    try:
        schedule_log_update(int(thread_id))
    except Exception as e:
        print(f"Snapshot public-log refresh failed: {e}")

    embed = None
    full_snapshot_run = total_samples >= ATTENDANCE_SAMPLE_COUNT
    try:
        title = (
            "📸 Multi-Snapshot Complete"
            if full_snapshot_run
            else "📸 Early Attendance Finalize"
        )
        description = (
            f"Took **{total_samples}/{ATTENDANCE_SAMPLE_COUNT}** samples every **{delay}** min. "
            f"Present if seen in **{required or ATTENDANCE_REQUIRED_PRESENT}+** of them."
        )
        if not confident:
            description += (
                "\n⚠️ Game ended before enough samples were taken — "
                "no-show warnings were **not** auto-applied. Review the attendance data manually."
            )
        embed = discord.Embed(
            title=f"{title}: {game.get('thread_name', thread_id)}",
            description=description,
            color=discord.Color.brand_red() if absent_report else discord.Color.brand_green(),
            url=_attendance_page_url(stable_id),
        )
        embed.add_field(name="✅ Present", value=f"{len(present)} players", inline=True)
        embed.add_field(name="❌ Absent / Unlogged", value=f"{len(absent_report)} players", inline=True)
        sample_summary = " · ".join(
            f"S{s['index']}:{s['count']}" for s in sample_logs
        )
        embed.add_field(name="Sample counts", value=sample_summary or "—", inline=False)

        if absent_report:
            absent_details = ""
            for missing_uid, missing_reason, missing_nation in absent_report:
                absent_details += f"• <@{missing_uid}> ({missing_nation}): {missing_reason}\n"
            if len(absent_details) > 1024:
                absent_details = absent_details[:1020] + "..."
            embed.add_field(name="Detailed Absentee Report", value=absent_details, inline=False)

        host_log_id = G.HOST_LOG_CHANNEL_ID
        host_log = bot.get_channel(host_log_id)
        if host_log:
            await host_log.send(embed=embed)

        if embed is not None and full_snapshot_run and not ATTENDANCE_WEB_ONLY:
            await _sync_multi_snapshot_complete(thread_key, embed)
    except Exception as e:
        print(f"Host Log Error: {e}")

    if ATTENDANCE_WEB_ONLY:
        # The results live on the web Attendance page; one short note in the
        # Host Control Center points the host there.
        await _post_attendance_link(game, thread_key, finalized=True)
    elif total_samples >= ATTENDANCE_SAMPLE_COUNT:
        try:
            await _post_advanced_log_tracker(thread_key, guild)
        except Exception as e:
            print(f"[WARN] Advanced Log Tracker post failed: {e}")


_multi_snapshot_forward_locks: dict[str, asyncio.Lock] = {}


async def _sync_multi_snapshot_complete(thread_key: str, embed: discord.Embed = None) -> bool:
    """Edit-or-send the completed snapshot embed in the game's original HCC."""
    games_data = await _load_games_resilient()
    storage_key, game = _find_game_entry(games_data, thread_key)
    if not game or int(game.get("snapshot_samples_done") or 0) < ATTENDANCE_SAMPLE_COUNT:
        return False
    stable_key = str(
        game.get("lobby_thread_id")
        or game.get("original_thread_id")
        or storage_key
        or thread_key
    )
    lock = _multi_snapshot_forward_locks.setdefault(stable_key, asyncio.Lock())
    async with lock:
        games_data = await _load_games_resilient()
        storage_key, game = _find_game_entry(games_data, thread_key)
        if not game:
            return False

        if embed is not None:
            game["multi_snapshot_embed"] = embed.to_dict()
            await save_single_game(
                storage_key or str(thread_key), game, rewrite_reservations=False
            )
        else:
            payload = game.get("multi_snapshot_embed")
            if not isinstance(payload, dict):
                return False
            embed = discord.Embed.from_dict(payload)

        channel = await _resolve_host_control_center(game, storage_key, thread_key)
        if not channel:
            print(
                f"[WARN] Multi-Snapshot Complete deferred for {thread_key}: "
                "Host Control Center could not be resolved."
            )
            return False

        message = None
        message_id = game.get("multi_snapshot_message_id")
        if message_id:
            try:
                message = await channel.fetch_message(int(message_id))
                await message.edit(content="**Multi-Snapshot Complete:**", embed=embed)
            except discord.NotFound:
                message = None
            except Exception as e:
                print(f"[WARN] Multi-Snapshot Complete edit failed for {thread_key}: {e}")
                return False
        if message is None:
            try:
                message = await channel.send(
                    content="**Multi-Snapshot Complete:**", embed=embed
                )
            except Exception as e:
                print(f"[WARN] Multi-Snapshot Complete send failed for {thread_key}: {e}")
                return False

        fresh_games = await _load_games_resilient()
        fresh_key, fresh_game = _find_game_entry(
            fresh_games, storage_key or thread_key
        )
        if fresh_game:
            fresh_game["multi_snapshot_message_id"] = str(message.id)
            fresh_game["multi_snapshot_forwarded_at"] = int(time.time())
            fresh_game.setdefault("multi_snapshot_embed", embed.to_dict())
            await save_single_game(
                fresh_key or storage_key or str(thread_key),
                fresh_game,
                rewrite_reservations=False,
            )
        return True


@tasks.loop(seconds=30)
async def multi_snapshot_forward_retry_loop():
    """Runs once per active server (_multi_snapshot_forward_retry_loop_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_multi_snapshot_forward_retry_loop_for_guild, "multi_snapshot_forward_retry_loop")


async def _multi_snapshot_forward_retry_loop_for_guild():
    """Retry transiently failed 5/5 snapshot forwards without creating duplicates."""
    await bot.wait_until_ready()
    if ATTENDANCE_WEB_ONLY:
        return  # attendance results live on the web Attendance page
    games_data = await _load_games_resilient()
    for storage_key, game in (games_data or {}).items():
        if not isinstance(game, dict):
            continue
        if int(game.get("snapshot_samples_done") or 0) < ATTENDANCE_SAMPLE_COUNT:
            continue
        if not game.get("multi_snapshot_message_id") and game.get("multi_snapshot_embed"):
            await _sync_multi_snapshot_complete(str(storage_key))
        if not game.get("advanced_log_tracker_posted"):
            try:
                await _post_advanced_log_tracker(
                    str(storage_key), bot.get_guild(cur_gid())
                )
            except Exception as e:
                print(
                    f"[WARN] Advanced Log Tracker retry failed for {storage_key}: {e}"
                )


@multi_snapshot_forward_retry_loop.before_loop
async def before_multi_snapshot_forward_retry_loop():
    await _wait_ready_staggered(30)


# ==========================================================================
# ADVANCED LOG TRACKER
# --------------------------------------------------------------------------
# Posted to the original Host Control Center thread only after all 5 attendance
# snapshots complete. Lists everyone who held
# the game's Gamer Pass (i.e. pressed the green "Yes" participation button,
# or was added by the host/late-join), what nation they reserved, whether
# they were logged as present, and in how many snapshots they were seen.
# It also prompts the host to run AI Analysis, which cross-references
# country tags detected in the uploaded chat log against this same table
# (see _post_attendance_log_mismatch_review) to catch cases where a player
# was clearly in-game (their tag shows up joining/talking) but the bot never
# counted them as present.
# ==========================================================================
def _discord_presence_label(member: discord.Member | None) -> str:
    """Human-readable, informational presence; never an attendance decision."""
    if member is None:
        return "unknown"
    status = str(getattr(member, "status", "offline")).lower()
    return {
        "online": "online",
        "idle": "idle",
        "dnd": "do not disturb",
        "offline": "offline",
        "invisible": "offline",
    }.get(status, status or "unknown")


def _advanced_log_tracker_roster(game: dict, guild: discord.Guild = None) -> list[dict]:
    """One row per unique player who ever held this game's Gamer Pass.

    Roster = confirmed_ids (pressed "Yes") ∪ present_ids (logged present by any
    means) ∪ late-joined reservation holders ∪ current holders of the dynamic
    Gamer Pass role (covers a restart/edge-case where confirmed_ids wasn't
    updated). Using several sources keeps this accurate even if one of them
    is stale.
    """
    reservations = game.get("reservations", {}) or {}
    confirmed = {int(x) for x in game.get("confirmed_ids", []) if str(x).isdigit()}
    present = _normalize_uid_set(game.get("present_ids", []))
    late_join_nations = set(game.get("late_join_nations", []) or [])
    hit_counts = game.get("presence_hit_counts", {}) or {}
    total_samples = game.get("snapshot_samples_done", 0) or 0

    roster_ids: set[int] = set(confirmed) | set(present)
    for nation, uid in reservations.items():
        if nation in late_join_nations and str(uid).isdigit():
            roster_ids.add(int(uid))

    role_id = game.get("temp_gamer_pass_role")
    if guild and role_id:
        role = guild.get_role(int(role_id))
        if role:
            roster_ids |= {m.id for m in role.members}

    # One representative nation per unique player (mirrors the Participation Tracker).
    nation_by_uid: dict[int, str] = {}
    for key, val in reservations.items():
        try:
            uid = int(val)
        except (TypeError, ValueError):
            continue
        nation_by_uid.setdefault(uid, _pretty_reservation_name(key))

    rows = []
    for uid in roster_ids:
        rows.append({
            "user_id": uid,
            "nation": nation_by_uid.get(uid, "*(no matching reservation)*"),
            "logged": uid in present,
            "hits": int(hit_counts.get(str(uid), 0)),
            "total_samples": total_samples,
            "presence": _discord_presence_label(guild.get_member(uid) if guild else None),
        })
    # Confirmed/logged first, then alphabetical-ish by nation for readability.
    rows.sort(key=lambda r: (not r["logged"], r["nation"]))
    return rows


def _build_advanced_log_tracker_chunks(game: dict, guild: discord.Guild = None) -> list[str]:
    """Render the Advanced Log Tracker as one or more <=1900-char messages,
    splitting on section boundaries — same never-truncate approach as
    `_build_participation_tracker_chunks`."""
    rows = _advanced_log_tracker_roster(game, guild)
    total_samples = game.get("snapshot_samples_done", 0) or 0
    sample_goal = ATTENDANCE_SAMPLE_COUNT
    confident = game.get("attendance_confident", total_samples >= ATTENDANCE_REQUIRED_PRESENT)
    early_ended = game.get("attendance_early_ended", total_samples < ATTENDANCE_SAMPLE_COUNT)

    logged_lines, unlogged_lines = [], []
    for r in rows:
        line = (
            f"{'✅' if r['logged'] else '❌'} <@{r['user_id']}> — **{r['nation']}** · "
            f"seen in `{r['hits']}/{total_samples or sample_goal}` snapshot(s) · "
            f"Discord: `{r['presence']}`"
        )
        (logged_lines if r["logged"] else unlogged_lines).append(line)

    warn_banner = ""
    if early_ended:
        warn_banner = (
            f"\n⚠️ **Session ended early** — only **{total_samples}/{sample_goal}** snapshot(s) were "
            f"taken before the game was ended. No-show warnings were **not** auto-applied; please "
            f"review the ❌ list below manually.\n"
        )
    elif not confident:
        warn_banner = "\n⚠️ Attendance data is incomplete — review manually.\n"

    header = (
        f"# 📡 Advanced Log Tracker\n"
        f"Attendance + Gamer Pass audit for **{game.get('mode', '')}** — "
        f"**{total_samples}/{sample_goal}** snapshot(s) completed."
        f"{warn_banner}\n"
    )
    footer = (
        "\n**🤖 Next step — Run AI Analysis:** upload the session's chat log `.txt` in this "
        "thread and click **Run AI Analysis** on the panel above. In addition to the RP "
        "quality report, I'll automatically scan the log for country tags (e.g. `GERnikoloza "
        "joined` → tag **GER** = Germany) and cross-check them against this table. If someone's "
        "tag shows up in the log but they're marked ❌ here, I'll post a follow-up asking you to "
        "confirm whether they should be manually logged as present.\n"
    )

    sections = [
        (f"✅ Logged Present ({len(logged_lines)})", logged_lines),
        (f"❌ Not Logged / Unconfirmed ({len(unlogged_lines)})", unlogged_lines),
    ]

    CHUNK_LIMIT = 1900
    chunks: list[str] = []
    current = header

    def _flush():
        nonlocal current
        if current.strip():
            chunks.append(current)
        current = ""

    for title, lines in sections:
        if not lines:
            block_text = f"\n**{title}**\n> —\n"
            if len(current) + len(block_text) > CHUNK_LIMIT:
                _flush()
            current += block_text
            continue

        block_header = f"\n**{title}**\n"
        if len(current) + len(block_header) > CHUNK_LIMIT:
            _flush()
        current += block_header

        for line in lines:
            piece = line + "\n"
            if len(piece) > CHUNK_LIMIT:
                piece = piece[: CHUNK_LIMIT - 5] + "...\n"
            if len(current) + len(piece) > CHUNK_LIMIT:
                _flush()
            current += piece

    if len(current) + len(footer) > CHUNK_LIMIT:
        _flush()
        current = footer
    else:
        current += footer

    _flush()
    if not chunks:
        chunks = [header + footer]
    return chunks


_advanced_tracker_locks: dict[str, asyncio.Lock] = {}


async def _post_advanced_log_tracker(thread_key: str, guild: discord.Guild = None) -> None:
    games_data = await _load_games_resilient()
    storage_key, game = _find_game_entry(games_data, thread_key)
    if not game:
        return
    stable_key = str(
        game.get("lobby_thread_id")
        or game.get("original_thread_id")
        or storage_key
        or thread_key
    )
    lock = _advanced_tracker_locks.setdefault(stable_key, asyncio.Lock())
    async with lock:
        await _post_advanced_log_tracker_locked(thread_key, guild)


async def _post_advanced_log_tracker_locked(thread_key: str, guild: discord.Guild = None) -> None:
    """Posts the Advanced Log Tracker panel to the Host Control Center thread
    and edits its persisted message set on retries. Never falls back to the
    private host-log channel or double-posts during finalize races."""
    games_data = await _load_games_resilient()
    storage_key, game = _find_game_entry(games_data, thread_key)
    if not game:
        return

    channel = await _resolve_host_control_center(game, storage_key, thread_key)
    if not channel:
        print(
            f"[WARN] Advanced Log Tracker deferred for {thread_key}: "
            "Host Control Center could not be resolved."
        )
        return

    if guild is None:
        guild = getattr(channel, "guild", None) or bot.get_guild(cur_gid())

    chunks = _build_advanced_log_tracker_chunks(game, guild)
    host_id = game.get("host_id")
    if host_id and chunks:
        chunks[0] = f"<@{host_id}> your attendance tracker is ready.\n{chunks[0]}"

    old_msg_ids = list(game.get("advanced_log_tracker_msg_ids") or [])
    try:
        msg_ids = await _sync_multi_message_list(channel, old_msg_ids, chunks)
    except Exception as e:
        print(f"[WARN] Advanced Log Tracker sync failed: {e}")
        return
    sync_complete = len(msg_ids) == len(chunks) and bool(msg_ids)
    if sync_complete:
        try:
            first_message = await channel.fetch_message(int(msg_ids[0]))
            sync_complete = first_message.content == chunks[0]
        except Exception:
            sync_complete = False

    # Re-read fresh before writing back, in case attendance finalize wrote
    # other fields to this same game in between.
    games_data = await _load_games_resilient()
    current_key, g = _find_game_entry(games_data, storage_key or thread_key)
    if g:
        g["advanced_log_tracker_posted"] = sync_complete
        g["advanced_log_tracker_msg_ids"] = msg_ids
        await save_single_game(current_key or str(thread_key), g, rewrite_reservations=False)


class AdminTriggerView(discord.ui.View):
    def __init__(self, game_id: str):
        super().__init__(timeout=None)
        self.game_id = game_id

    @discord.ui.button(label="Admin Actions", style=discord.ButtonStyle.primary, emoji="🛠️", custom_id="admin_trigger_btn")
    async def btn_admin_actions(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer(ephemeral=True)

        games_data = await read_json(GAMES_FILE)
        game = games_data.get(str(self.game_id))

        if not game:
            return await interaction.followup.send("❌ Game data not found.", ephemeral=True)

        logs = game.get("action_logs", [])
        table_content = "\n".join(logs) if logs else "No actions recorded yet."

        present_count = len(game.get("present_ids", []))
        reserve_count = len(game.get("reservations", {}))

        # Build standard text instead of an Embed
        panel_text = (
            f"🕹️ **HOST CONTROL CENTER**\n"
            f"**Game:** {game.get('thread_name', 'Unknown')} | **Mode:** {game.get('mode', 'Unknown')}\n"
            f"✅ **Present:** `{present_count}` | 📝 **Reserved:** `{reserve_count}`\n"
            f"────────────────────────────────\n"
            f"📊 **LIVE SESSION LOG**\n"
            f"```md\n{table_content}\n```\n"
            "*Use the buttons below to manage attendance and players live.*"
        )

        host_id = game.get("host_id")
        if not host_id:
            return await interaction.followup.send("❌ No host is assigned to this game.", ephemeral=True)
        view = MasterHostPanel(str(self.game_id), host_id, locked=not _game_status_is_ended(game))
        # Send ephemeral text, ensuring embed=None clears out anything else
        await interaction.followup.send(content=panel_text, embed=None, view=view, ephemeral=True)


# ==========================================================================
# PARTICIPATION CONFIRMATION SYSTEM
# At /game_start each reserved player is DM'd with Yes/No buttons. The 🎮 pass
# role (and info-channel access) is granted ONLY when they press "Yes". Pressing
# "No" opens a reason modal; what happens next depends on their nation tier and
# the game's logging mode. Warnings are never touched here — they remain entirely
# with the multi-sample attendance snapshot; the "No" flow only notifies the host
# and tells the player their dispute path. Buttons lock lazily once sampling finishes.
# ==========================================================================
TICKET_CHANNEL_ID = 0


def _participation_dm_text(game_mode: str, role_name: str, info_channel_id, crash_url: str | None = None) -> str:
    info = f"<#{info_channel_id}>" if info_channel_id else "the secret game-information room"
    crash = f":rotating_light: Game crashed? Send your logs on the website: {crash_url}\n" if crash_url else ""
    return (
        f":alarm_clock: The **{game_mode}** game is starting soon!\n"
        f":game_die: Press **Yes** below to receive the **{role_name}** — access to the secret "
        f"{info} where the ID, Password and Checksum are posted.\n"
        f":pen_ballpoint: Please rename your Discord username to the nation you're playing.\n"
        f":no_entry_sign: Do **not** share any information under any circumstance.\n"
        f"{crash}\n"
        f"**Do you wish to participate in this game?**"
    )


def _build_reservation_vc_map(guild, reservations: dict, vc_ids: list, game_mode: str) -> dict:
    """Map reservation slot keys to the actual voice channels created for them."""
    channels = {
        channel.name: channel
        for channel_id in vc_ids
        if (channel := guild.get_channel(int(channel_id))) is not None
    }
    result = {}
    for slot_key in reservations:
        base = str(slot_key).replace("_FILL_", "", 1).split("_coop", 1)[0]
        vc_name = base
        if "Kaiserreich" in (game_mode or ""):
            faction_names = {
                "Entente": "Entente",
                "Third International": "3rd Internationale",
                "Reichspakt": "Reichspact",
                "Moscow Accord": "Moscow Accord",
            }
            for faction, groups in KAISERREICH_REGIONS.items():
                nations = list(groups.get("Majors", [])) + list(groups.get("Minors", []))
                if base in nations:
                    vc_name = faction_names.get(faction, faction)
                    break
        channel = channels.get(vc_name)
        result[str(slot_key)] = {
            "name": getattr(channel, "name", vc_name),
            "id": getattr(channel, "id", None),
        }
    return result


class ParticipationButton(discord.ui.DynamicItem[discord.ui.Button],
                          template=r"gpass:(?P<action>yes|no):(?P<thread>\d+)"):
    """A persistent (restart-proof) Yes/No participation button for a game DM."""

    def __init__(self, action: str, thread_id: int):
        self.action = action
        self.thread_id = int(thread_id)
        if action == "yes":
            button = discord.ui.Button(
                label="Yes — I'm playing", style=discord.ButtonStyle.success,
                emoji="✅", custom_id=f"gpass:yes:{thread_id}",
            )
        else:
            button = discord.ui.Button(
                label="No — I can't make it", style=discord.ButtonStyle.danger,
                emoji="🚫", custom_id=f"gpass:no:{thread_id}",
            )
        super().__init__(button)

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(match["action"], int(match["thread"]))

    async def callback(self, interaction: discord.Interaction):
        try:
            await handle_participation_response(interaction, self.thread_id, self.action)
        except TimeoutError as e:
            print(f"[WARN] Participation button TimeoutError: {e}")
            try:
                msg = (
                    "⏳ The bot is busy saving game data right now. "
                    "Please click the button again in a few seconds."
                )
                if interaction.response.is_done():
                    await interaction.followup.send(msg, ephemeral=True)
                else:
                    await interaction.response.send_message(msg, ephemeral=True)
            except Exception:
                pass
        except Exception as e:
            print(f"[WARN] Participation button failed: {e}")
            try:
                msg = "⚠️ Something went wrong confirming participation. Please try again."
                if interaction.response.is_done():
                    await interaction.followup.send(msg, ephemeral=True)
                else:
                    await interaction.response.send_message(msg, ephemeral=True)
            except Exception:
                pass


def build_participation_view(thread_id) -> discord.ui.View:
    view = discord.ui.View(timeout=None)
    view.add_item(ParticipationButton("yes", int(thread_id)))
    view.add_item(ParticipationButton("no", int(thread_id)))
    return view


async def _send_participation_dms(
    guild, reservations: dict, thread_id, dm_text: str, vc_map: dict | None = None
) -> int:
    """DM every unique reserved player the participation prompt with Yes/No buttons."""
    sent = 0
    by_user: dict[int, list[str]] = {}
    for slot_key, val in reservations.items():
        try:
            uid = int(val)
        except (TypeError, ValueError):
            continue
        entry = (vc_map or {}).get(str(slot_key), {})
        vc_id = entry.get("id")
        vc_name = entry.get("name")
        vc_label = f"<#{vc_id}> (**{vc_name}**)" if vc_id else f"**{vc_name or 'Ask the host'}**"
        by_user.setdefault(uid, [])
        if vc_label not in by_user[uid]:
            by_user[uid].append(vc_label)

    for uid, vc_labels in by_user.items():
        member = guild.get_member(uid)
        if not member:
            continue
        personalized = dm_text
        if vc_labels:
            personalized += "\n\n🔊 **Your voice channel:** " + ", ".join(vc_labels)
        async with _discord_api_sem:
            try:
                await member.send(content=personalized, view=build_participation_view(thread_id))
                sent += 1
            except Exception:
                pass
        await asyncio.sleep(0.3)
    return sent


def _vip_privilege_dm_text() -> str:
    return (
        "👑 **VIP Privileges — Active for this session**\n\n"
        "Because you hold **VIP** status, you receive these benefits for this game:\n\n"
        "🛡️ **Immune to warnings** — VIP players are not issued session warnings.\n\n"
        "🔄 **Immune to Major & Minor streak cooldowns** — after playing a Major you "
        "normally must play a Minor next, and you can't take the same Minor twice in a "
        "row. As VIP, those cooldowns do not apply to you.\n\n"
        "📣 **Request Host Presence immediately** — use the button below to summon the "
        "host into your voice channel right away."
    )


class VipHostPresenceButton(discord.ui.DynamicItem[discord.ui.Button],
                            template=r"viphost:(?P<thread>\d+):(?P<vip>\d+)"):
    """VIP-only button: warn host in DMs, then move them into the VIP's VC."""

    def __init__(self, thread_id: int, vip_user_id: int):
        self.thread_id = int(thread_id)
        self.vip_user_id = int(vip_user_id)
        button = discord.ui.Button(
            label="Request Host Presence",
            style=discord.ButtonStyle.primary,
            emoji="👑",
            custom_id=f"viphost:{thread_id}:{vip_user_id}",
        )
        super().__init__(button)

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(int(match["thread"]), int(match["vip"]))

    async def callback(self, interaction: discord.Interaction):
        await handle_vip_host_presence_request(
            interaction, self.thread_id, self.vip_user_id
        )


def build_vip_privilege_view(thread_id, vip_user_id) -> discord.ui.View:
    view = discord.ui.View(timeout=None)
    view.add_item(VipHostPresenceButton(int(thread_id), int(vip_user_id)))
    return view


async def handle_vip_host_presence_request(interaction: discord.Interaction,
                                           thread_id: int, vip_user_id: int):
    """DM the host a presence alert, then move them into the VIP's voice channel."""
    if interaction.user.id != int(vip_user_id):
        return await interaction.response.send_message(
            "❌ This VIP control is not yours.", ephemeral=True
        )

    await interaction.response.defer(ephemeral=True)

    guild = interaction.guild or bot.get_guild(cur_gid())
    if guild is None:
        return await interaction.followup.send("❌ Could not resolve the server.", ephemeral=True)

    # Button lives in DMs — resolve VIP via guild member (User objects have no roles).
    vip_member = guild.get_member(int(vip_user_id))
    if vip_member is None:
        try:
            vip_member = await guild.fetch_member(int(vip_user_id))
        except Exception:
            vip_member = None
    if not _member_has_vip(vip_member):
        return await interaction.followup.send(
            "❌ VIP privileges are required to use this.", ephemeral=True
        )

    games_data = await read_json(GAMES_FILE)
    storage_key, game = _find_game_entry(games_data, thread_id)
    if not game:
        game = games_data.get(str(thread_id))
    if not game:
        return await interaction.followup.send("❌ Game not found.", ephemeral=True)

    if game.get("status") in ("ended", "cancelled"):
        return await interaction.followup.send("❌ This game has already ended.", ephemeral=True)

    host_id = game.get("host_id")
    if not host_id:
        return await interaction.followup.send("❌ No host is assigned to this game.", ephemeral=True)

    try:
        host_member = guild.get_member(int(host_id)) or await guild.fetch_member(int(host_id))
    except Exception:
        host_member = None
    if host_member is None:
        return await interaction.followup.send("❌ Could not find the host on the server.", ephemeral=True)

    vip_voice = getattr(getattr(vip_member, "voice", None), "channel", None)
    if vip_voice is None:
        return await interaction.followup.send(
            "❌ Join a **game voice channel** first, then click the button again.",
            ephemeral=True,
        )

    host_voice = getattr(getattr(host_member, "voice", None), "channel", None)
    vip_name = vip_member.display_name or str(vip_member)

    # Warn the host in DMs before (and regardless of) the move attempt.
    warn_msg = (
        f"👑 **VIP Host Presence Request**\n\n"
        f"**VIP {vip_name}** ({vip_member.mention}) has requested your presence.\n"
        f"The bot will automatically **move you** from your current voice channel "
        f"into **{vip_voice.name}**.\n\n"
        f"⚠️ **Please stay in a voice channel** so the bot can drag you — "
        f"if you leave VC, the move will fail."
    )
    try:
        await host_member.send(warn_msg)
    except Exception as e:
        print(f"[WARN] Could not DM host about VIP presence request: {e}")
        return await interaction.followup.send(
            "❌ Could not DM the host (their DMs may be closed). Presence request aborted.",
            ephemeral=True,
        )

    if host_voice is None:
        return await interaction.followup.send(
            f"✅ Host {host_member.mention} was warned in DMs, but they are **not in a voice channel** "
            f"right now — ask them to join VC so the bot can move them.",
            ephemeral=True,
        )

    if host_voice.id == vip_voice.id:
        return await interaction.followup.send(
            f"✅ Host {host_member.mention} was notified — they are **already** in your channel "
            f"(**{vip_voice.name}**).",
            ephemeral=True,
        )

    try:
        await host_member.move_to(vip_voice, reason=f"VIP presence request by {vip_name}")
    except discord.Forbidden:
        return await interaction.followup.send(
            "✅ Host was warned in DMs, but I **lack permission** to move them "
            "(need Move Members). Ask them to join you manually.",
            ephemeral=True,
        )
    except Exception as e:
        return await interaction.followup.send(
            f"✅ Host was warned in DMs, but the move failed: `{e}`",
            ephemeral=True,
        )

    await interaction.followup.send(
        f"✅ Host {host_member.mention} was notified and moved into **{vip_voice.name}**.",
        ephemeral=True,
    )
    try:
        await host_member.send(
            f"✅ You were moved into **{vip_voice.name}** for VIP **{vip_name}**'s request."
        )
    except Exception:
        pass


async def _send_vip_privilege_dms(guild, reservations: dict, thread_id) -> int:
    """After game-start participation DMs, send VIP-only privilege notice + host button."""
    sent = 0
    seen = set()
    for val in reservations.values():
        try:
            uid = int(val)
        except (TypeError, ValueError):
            continue
        if uid in seen:
            continue
        seen.add(uid)
        member = guild.get_member(uid)
        if not member or not _member_has_vip(member):
            continue
        async with _discord_api_sem:
            try:
                await member.send(
                    content=_vip_privilege_dm_text(),
                    view=build_vip_privilege_view(thread_id, uid),
                )
                sent += 1
            except Exception as e:
                print(f"[WARN] VIP privilege DM failed for {uid}: {e}")
        await asyncio.sleep(0.3)
    return sent


async def _disable_participation_buttons(msg, note: str = None):
    """Strip the Yes/No buttons off a DM message and optionally append a note."""
    try:
        if msg is None:
            return
        content = msg.content or ""
        if note:
            content = f"{content}\n\n{note}".strip()
        await msg.edit(content=content, view=None)
    except Exception:
        pass


async def _forward_participation_to_host(game: dict, text: str):
    """Post a participation notice to the Host Control Center thread, pinging the host."""
    host_id = game.get("host_id")
    ping = f"<@{host_id}> " if host_id else ""
    channel = await _resolve_host_control_center(game)
    if channel:
        try:
            await channel.send(f"{ping}{text}", allowed_mentions=discord.AllowedMentions(users=True))
        except Exception as e:
            print(f"[WARN] Participation host forward failed: {e}")


def _build_participation_tracker_chunks(game: dict) -> list[str]:
    """Render the tracker as one or more messages, splitting on section boundaries
    so nothing is ever truncated — a busy game just gets a couple of extra messages
    instead of a cut-off list."""
    reservations = game.get("reservations", {})
    confirmed = {int(x) for x in game.get("confirmed_ids", []) if str(x).isdigit()}
    declined = {int(x) for x in game.get("declined_ids", []) if str(x).isdigit()}
    dropped = {int(x) for x in game.get("dropped_out", []) if str(x).isdigit()}
    reasons = game.get("drop_reasons", {}) or {}
    guild = bot.get_guild(cur_gid())

    # One representative nation per unique player.
    seen: dict[int, str] = {}
    for key, val in reservations.items():
        try:
            uid = int(val)
        except (TypeError, ValueError):
            continue
        seen.setdefault(uid, _pretty_reservation_name(key))

    conf_lines, dec_lines, drop_lines, pend_lines = [], [], [], []
    for uid, nation in seen.items():
        reason = reasons.get(str(uid), "")
        if uid in dropped:
            drop_lines.append(f"🚪 <@{uid}> — {nation}" + (f" · *{reason}*" if reason else ""))
        elif uid in declined:
            dec_lines.append(f"🚫 <@{uid}> — {nation}" + (f" · *{reason}*" if reason else ""))
        elif uid in confirmed:
            conf_lines.append(f"✅ <@{uid}> — {nation}")
        else:
            member = guild.get_member(uid) if guild else None
            pend_lines.append(
                f"⌛ <@{uid}> — {nation} · Discord: `{_discord_presence_label(member)}`"
            )

    header = (
        f"# 🎟️ Participation Tracker\n"
        f"Live confirmations for **{game.get('mode', '')}** — updates as players respond.\n"
    )
    sections = [
        (f"✅ Confirmed ({len(conf_lines)})", conf_lines),
        (f"⌛ Awaiting response ({len(pend_lines)})", pend_lines),
        (f"🚫 Declined / will be warned ({len(dec_lines)})", dec_lines),
        (f"🚪 Dropped out (excused) ({len(drop_lines)})", drop_lines),
    ]

    CHUNK_LIMIT = 1900
    chunks: list[str] = []
    current = header

    def _flush():
        nonlocal current
        if current.strip():
            chunks.append(current)
        current = ""

    for title, lines in sections:
        if not lines:
            block_text = f"\n**{title}**\n> —\n"
            if len(current) + len(block_text) > CHUNK_LIMIT:
                _flush()
            current += block_text
            continue

        block_header = f"\n**{title}**\n"
        if len(current) + len(block_header) > CHUNK_LIMIT:
            _flush()
        current += block_header

        for line in lines:
            piece = line + "\n"
            if len(piece) > CHUNK_LIMIT:
                piece = piece[: CHUNK_LIMIT - 5] + "...\n"
            if len(current) + len(piece) > CHUNK_LIMIT:
                _flush()
            current += piece

    _flush()
    if not chunks:
        chunks = [header]
    return chunks


async def _sync_multi_message_list(
    channel, msg_ids: list, chunks: list[str], *, skip_if_unchanged: bool = True
) -> list[str]:
    """Edit existing messages in place for each chunk, create new ones only for
    chunks beyond the current list, and delete any leftovers if the list shrank.
    Shared by the Participation Tracker and (mirrors) the Public Archive updater
    so both use the exact same never-duplicate message bookkeeping pattern.
    Unchanged content is not PATCHed — that was the startup 429 storm.
    """
    ordered_ids: list[str | None] = []
    for item in (msg_ids or []):
        if item is None:
            ordered_ids.append(None)
            continue
        text = str(item).strip()
        if text == "":
            ordered_ids.append(None)
        elif text.isdigit():
            ordered_ids.append(text)
    new_msg_ids: list[str] = []
    for i, chunk in enumerate(chunks):
        slot = ordered_ids[i] if i < len(ordered_ids) else None
        try:
            if slot:
                msg = await channel.fetch_message(int(slot))
                await _safe_message_edit(msg, content=chunk, skip_if_unchanged=skip_if_unchanged)
                new_msg_ids.append(str(slot))
            else:
                new_msg = await _safe_channel_send(channel, content=chunk)
                new_msg_ids.append(str(new_msg.id))
        except discord.NotFound:
            try:
                new_msg = await _safe_channel_send(channel, content=chunk)
                new_msg_ids.append(str(new_msg.id))
            except Exception as e:
                print(f"[WARN] Multi-message replacement send failed at chunk {i + 1}: {e}")
                new_msg_ids.extend(str(x) for x in ordered_ids[i + 1:] if x)
                break
        except Exception as e:
            # Preserve every ID already discovered plus untouched existing IDs.
            # Callers persist this partial checkpoint, so a retry edits rather
            # than duplicating messages sent before the failure.
            print(f"[WARN] Multi-message sync paused at chunk {i + 1}: {e}")
            new_msg_ids.extend(str(x) for x in ordered_ids[i:] if x)
            break

    if len(ordered_ids) > len(chunks):
        for extra_id in ordered_ids[len(chunks):]:
            if not extra_id:
                continue
            try:
                old_msg = await channel.fetch_message(int(extra_id))
                await old_msg.delete()
            except Exception:
                pass
    return new_msg_ids


_participation_tracker_locks: dict[str, asyncio.Lock] = {}


def _get_participation_tracker_lock(game_id) -> asyncio.Lock:
    key = str(game_id)
    lock = _participation_tracker_locks.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _participation_tracker_locks[key] = lock
    return lock


async def _update_participation_tracker(game_id: str, force: bool = False):
    """Rebuild the live Participation Tracker in the host panel.

    Only runs for a started, non-ended game. Updates are event-driven
    (Yes/No clicks, host add/remove/hot-join) — never a polling loop.
    With ATTENDANCE_WEB_ONLY the tracker lives on the web Attendance page.
    """
    if ATTENDANCE_WEB_ONLY:
        return
    async with _get_participation_tracker_lock(game_id):
        games_data = await _load_games_resilient()
        storage_key, game = _find_game_entry(games_data, game_id)
        if not game:
            return
        if not game.get("game_started") or game.get("status") in ("ended", "cancelled"):
            return
        panel_thread_id = game.get("host_panel_thread_id")
        if not panel_thread_id:
            return

        channel = bot.get_channel(int(panel_thread_id))
        if not channel:
            try:
                channel = await bot.fetch_channel(int(panel_thread_id))
            except Exception:
                return

        chunks = _build_participation_tracker_chunks(game)
        msg_ids = game.get("participation_tracker_msg_ids")
        if not msg_ids:
            legacy_id = game.get("participation_tracker_msg_id")
            msg_ids = [legacy_id] if legacy_id else []

        try:
            new_msg_ids = await _sync_multi_message_list(channel, msg_ids, chunks)
        except Exception as e:
            print(f"[WARN] Participation tracker sync failed: {e}")
            return

        games_data = await _load_games_resilient()
        current_key, game = _find_game_entry(games_data, storage_key or game_id)
        if not game:
            return
        saved_ids = [str(x) for x in (game.get("participation_tracker_msg_ids") or []) if str(x).strip()]
        # Another update already recorded tracker messages. Drop the copies we
        # just created so the host panel does not keep two trackers.
        if saved_ids and saved_ids != [str(x) for x in new_msg_ids]:
            for extra_id in new_msg_ids:
                if str(extra_id) in saved_ids:
                    continue
                try:
                    extra = await channel.fetch_message(int(extra_id))
                    await extra.delete()
                except Exception:
                    pass
            new_msg_ids = saved_ids
        game["participation_tracker_msg_ids"] = [str(x) for x in new_msg_ids]
        game.pop("participation_tracker_msg_id", None)
        game["participation_tracker_ready"] = True
        if not game.get("participation_tracker_activated_at"):
            game["participation_tracker_activated_at"] = int(time.time())
        await save_single_game(current_key or str(game_id), game, rewrite_reservations=False)


def schedule_participation_tracker_update(game_id):
    """Debounced tracker refresh for a live game. No-op if the game is not started."""
    try:
        games = get_cached_games_data() or {}
        _, game = _find_game_entry(games, game_id)
        if not game or not game.get("game_started") or game.get("status") in ("ended", "cancelled"):
            return
    except Exception:
        return
    key = f"ptracker:{game_id}"
    _schedule_coalesced_update(key, RESERVATION_DEBOUNCE_SEC, lambda: _update_participation_tracker(str(game_id)))


async def _activate_participation_tracker(game_id: str, delay_sec: int = PARTICIPATION_TRACKER_DELAY_SEC):
    """Waits out the grace period announced at /game_start, then renders the
    real Participation Tracker for the first time (replacing the placeholder)."""
    try:
        await asyncio.sleep(delay_sec)
        games_data = await _load_games_resilient()
        storage_key, game = _find_game_entry(games_data, game_id)
        if not game or game.get("status") in ("ended", "cancelled"):
            return
        game["participation_tracker_ready"] = True
        await save_single_game(storage_key or str(game_id), game, rewrite_reservations=False)
        await _update_participation_tracker(str(game_id), force=True)
    except asyncio.CancelledError:
        pass
    except Exception as e:
        print(f"[WARN] Participation tracker activation failed for {game_id}: {e}")


async def resume_participation_trackers() -> None:
    """Boot must not PATCH trackers. Live games update only on Yes/No or host roster changes."""
    print("🎟️ Participation Tracker: boot refresh disabled (event-driven only).")


@tasks.loop(seconds=30)
async def participation_tracker_activation_loop():
    """Runs once per active server (_participation_tracker_activation_loop_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_participation_tracker_activation_loop_for_guild, "participation_tracker_activation_loop")


async def _participation_tracker_activation_loop_for_guild():
    """Hard deadline safety net: render every due tracker five minutes after game start."""
    await bot.wait_until_ready()
    games_data = await _load_games_resilient()
    now = int(time.time())
    for storage_key, game in (games_data or {}).items():
        if not isinstance(game, dict) or not game.get("game_started"):
            continue
        if game.get("status") in ("ended", "cancelled") or game.get("participation_tracker_activated_at"):
            continue
        started_at = int(game.get("game_started_at") or 0)
        activate_at = int(
            game.get("participation_tracker_activate_at")
            or (started_at + PARTICIPATION_TRACKER_DELAY_SEC if started_at else 0)
        )
        if not activate_at or activate_at > now or not game.get("host_panel_thread_id"):
            continue
        msg_ids = game.get("participation_tracker_msg_ids") or []
        if not msg_ids and game.get("participation_tracker_msg_id"):
            msg_ids = [game.get("participation_tracker_msg_id")]
        if msg_ids and game.get("participation_tracker_ready"):
            game["participation_tracker_activated_at"] = now
            await save_single_game(storage_key, game, rewrite_reservations=False)
            continue
        lobby_id = game.get("lobby_thread_id") or game.get("original_thread_id") or storage_key
        await _activate_participation_tracker(str(lobby_id), 0)


@participation_tracker_activation_loop.before_loop
async def before_participation_tracker_activation_loop():
    await _wait_ready_staggered(12)


async def _reply_participation_dm(interaction: discord.Interaction, content: str):
    """Acknowledge a DM button click. Never use ephemeral — Discord rejects it in DMs."""
    try:
        if interaction.response.is_done():
            await interaction.followup.send(content)
        else:
            await interaction.response.send_message(content)
    except Exception as e:
        print(f"[WARN] Participation DM reply failed: {e}")
        try:
            await interaction.user.send(content)
        except Exception:
            pass


async def handle_participation_response(interaction: discord.Interaction, thread_id: int, action: str):
    # Acknowledge FIRST — Discord expires unread button clicks after ~3s.
    # "No" opens a modal, so it must use send_modal (cannot defer first).
    if action == "yes":
        try:
            if not interaction.response.is_done():
                await interaction.response.defer()
        except Exception as e:
            print(f"[WARN] Participation Yes defer failed: {e}")

    # Prefer warm cache for the No path so send_modal always beats the 3s deadline.
    games_data = get_cached_games_data()
    _, game = _find_game_entry(games_data, thread_id) if games_data else (None, None)
    if not game:
        try:
            games_data = await asyncio.wait_for(read_json(GAMES_FILE), timeout=1.5)
        except Exception:
            games_data = get_cached_games_data() or {}
        _, game = _find_game_entry(games_data, thread_id) if games_data else (None, None)

    if not game:
        if action == "yes":
            await _reply_participation_dm(interaction, "❌ This game no longer exists.")
        else:
            try:
                await interaction.response.send_message("❌ This game no longer exists.")
            except Exception:
                pass
        await _disable_participation_buttons(interaction.message)
        return

    # Lazy lock: once the snapshot is taken (or the game is over), voting is closed.
    if game.get("snapshot_done") or game.get("status") in ("ended", "cancelled"):
        msg = "⛔ Participation is closed — attendance for this game has already been recorded."
        if action == "yes":
            await _reply_participation_dm(interaction, msg)
        else:
            try:
                await interaction.response.send_message(msg)
            except Exception:
                pass
        await _disable_participation_buttons(interaction.message, note="⛔ Voting closed.")
        return

    uid = interaction.user.id
    reservations = game.get("reservations", {})
    held = [k for k, v in reservations.items() if str(v) == str(uid)]
    if not held:
        msg = "❌ You don't have a reservation in this game anymore."
        if action == "yes":
            await _reply_participation_dm(interaction, msg)
        else:
            try:
                await interaction.response.send_message(msg)
            except Exception:
                pass
        await _disable_participation_buttons(interaction.message)
        return

    nation_key = next((k for k in held if is_capacity_slot(k)), held[0])
    nation_display = _pretty_reservation_name(nation_key)
    mode = game.get("mode", "")
    logging_mode = game.get("logging_mode", "Strict")
    try:
        major_nations = set(get_major_nations_for_mode(mode))
    except Exception:
        major_nations = set()
    base_nation = nation_key.replace("_FILL_", "").split("_coop", 1)[0]
    is_major = base_nation in major_nations and "_coop" not in nation_key

    if action == "yes":
        await _process_participation_yes(interaction, thread_id, nation_display)
    else:
        # Must be the first (and only) response — modal open acknowledges the click.
        try:
            await interaction.response.send_modal(
                ParticipationDeclineModal(thread_id, nation_display, is_major, logging_mode, interaction.message)
            )
        except Exception as e:
            print(f"[WARN] Participation No modal failed: {e}")
            try:
                await interaction.user.send(
                    "⚠️ Couldn't open the drop-out form. Please try the **No** button again."
                )
            except Exception:
                pass


async def _process_participation_yes(interaction: discord.Interaction, thread_id: int, nation_display: str):
    # Interaction should already be deferred by handle_participation_response.
    tid = str(thread_id)
    uid = interaction.user.id
    guild = bot.get_guild(cur_gid())

    # Serialize per-game so concurrent Yes clicks don't clobber each other's confirmed_ids.
    async with _get_reservation_lock(tid):
        games_data = get_cached_games_data() or await read_json(GAMES_FILE)
        storage_key, game = _find_game_entry(games_data, tid) if games_data else (None, None)
        if not game:
            return await _reply_participation_dm(interaction, "❌ Game not found.")

        role_id = game.get("temp_gamer_pass_role")
        info_channel_id = (MODE_CONFIG.get(game.get("mode"), {}) or {}).get("game_info_channel_id")

        role_note = ""
        if guild and role_id:
            member = guild.get_member(uid)
            role = guild.get_role(role_id)
            if member and role:
                try:
                    await member.add_roles(role, reason="Confirmed game participation")
                except Exception as e:
                    role_note = f"\n⚠️ I couldn't assign your pass role automatically (`{e}`). Please ping the host."

        confirmed = {int(x) for x in game.get("confirmed_ids", []) if str(x).isdigit()}
        confirmed.add(uid)
        game["confirmed_ids"] = list(confirmed)
        game["declined_ids"] = [x for x in game.get("declined_ids", []) if int(x) != uid]
        game["dropped_out"] = [x for x in game.get("dropped_out", []) if int(x) != uid]
        if isinstance(game.get("drop_reasons"), dict):
            game["drop_reasons"].pop(str(uid), None)
        # Single-game upsert — avoids the global games lock held by full-map write_json.
        try:
            await save_single_game(storage_key or tid, game, rewrite_reservations=False)
        except TimeoutError as e:
            print(f"[WARN] Participation Yes save timed out for {uid} in {tid}: {e}")
            return await _reply_participation_dm(
                interaction,
                "⏳ The bot is busy saving game data right now. Please click **Yes** again in a few seconds.",
            )
        except Exception as e:
            print(f"[WARN] Participation Yes save failed for {uid} in {tid}: {e}")
            return await _reply_participation_dm(
                interaction,
                "⚠️ Couldn't save your confirmation. Please click **Yes** again in a moment.",
            )

    info_txt = f" Head to <#{info_channel_id}> for the ID, Password & Checksum." if info_channel_id else ""
    vc_labels = []
    vc_map = game.get("reservation_vc_map", {}) or {}
    for slot_key, holder in (game.get("reservations", {}) or {}).items():
        if str(holder) != str(uid):
            continue
        entry = vc_map.get(str(slot_key), {})
        label = f"<#{entry.get('id')}>" if entry.get("id") else entry.get("name")
        if label and label not in vc_labels:
            vc_labels.append(label)
    vc_txt = f"\n🔊 Join your voice channel: {', '.join(vc_labels)}." if vc_labels else ""
    await _reply_participation_dm(
        interaction,
        f"✅ You're confirmed for **{nation_display}**!{info_txt}\n"
        f"📝 Please rename yourself to your nation.{vc_txt}{role_note}",
    )

    await _disable_participation_buttons(interaction.message, note="✅ You confirmed you're playing.")
    record_attendance_event(
        _attendance_stable_id(game, tid), "participation_yes", user_id=uid, details={"nation": nation_display}
    )
    schedule_participation_tracker_update(tid)


class ParticipationDeclineModal(discord.ui.Modal, title="Dropping out?"):
    reason = discord.ui.TextInput(
        label="Why can't you make it?",
        style=discord.TextStyle.long,
        placeholder="Let the host know why you're dropping out this late...",
        required=True,
        max_length=300,
    )

    def __init__(self, thread_id, nation_display, is_major, logging_mode, source_message):
        super().__init__()
        self.thread_id = int(thread_id)
        self.nation_display = nation_display
        self.is_major = is_major
        self.logging_mode = logging_mode
        self.source_message = source_message

    async def on_submit(self, interaction: discord.Interaction):
        await _process_participation_decline(
            interaction, self.thread_id, self.nation_display,
            self.is_major, self.logging_mode, self.reason.value, self.source_message,
        )


async def _process_participation_decline(interaction, thread_id, nation_display, is_major, logging_mode, reason, source_message):
    # Modal submit also has a 3s acknowledge window — defer before MySQL / Discord API work.
    try:
        if not interaction.response.is_done():
            await interaction.response.defer()
    except Exception as e:
        print(f"[WARN] Participation decline defer failed: {e}")

    tid = str(thread_id)
    uid = interaction.user.id
    guild = bot.get_guild(cur_gid())
    is_casual = (logging_mode == "Casual")

    async with _get_reservation_lock(tid):
        games_data = get_cached_games_data() or await read_json(GAMES_FILE)
        storage_key, game = _find_game_entry(games_data, tid) if games_data else (None, None)
        if not game:
            return await _reply_participation_dm(interaction, "❌ Game not found.")

        game.setdefault("drop_reasons", {})[str(uid)] = reason

        if is_major:
            # Majors can never unreserve after start; the snapshot applies their warnings.
            declined = {int(x) for x in game.get("declined_ids", []) if str(x).isdigit()}
            declined.add(uid)
            game["declined_ids"] = list(declined)
            if is_casual:
                user_msg = (
                    f"⚠️ **{nation_display}** is a **Major**, so you **cannot unreserve** after the game has started.\n"
                    f"You'll receive **2 warning points** at the attendance snapshot — you may **dispute them** by opening a "
                    f"ticket in <#{G.TICKET_CHANNEL_ID}> **after the game concludes**.\n"
                    f"Your attempt to drop out has been forwarded to the host."
                )
                host_line = f"🚪 **Major tried to bail — Casual** · <@{uid}> reserved **{nation_display}** (Major)."
            else:
                user_msg = (
                    f"⚠️ **{nation_display}** is a **Major**, so you **cannot unreserve** after the game has started.\n"
                    f"You will receive **2 warning points** at the attendance snapshot, and these **cannot be disputed**.\n"
                    f"Your attempt to drop out has been forwarded to the host."
                )
                host_line = f"🚪 **Major tried to bail — Strict** · <@{uid}> reserved **{nation_display}** (Major)."
        else:
            if is_casual:
                # Minor + Casual: excused. Kept in the locked list as proof, excluded from the snapshot.
                dropped = {int(x) for x in game.get("dropped_out", []) if str(x).isdigit()}
                dropped.add(uid)
                game["dropped_out"] = list(dropped)
                game["declined_ids"] = [x for x in game.get("declined_ids", []) if int(x) != uid]
                if guild:
                    member = guild.get_member(uid)
                    role_id = game.get("temp_gamer_pass_role")
                    role = guild.get_role(role_id) if role_id else None
                    if member and role and role in member.roles:
                        try:
                            await member.remove_roles(role, reason="Dropped out before snapshot")
                        except Exception:
                            pass
                user_msg = (
                    f"✅ You've been removed from the active lineup for **{nation_display}**. **No penalty** will be applied.\n"
                    f"You'll stay on the locked reservation list as a record, but you won't be counted in the final snapshot.\n"
                    f"Thanks for letting the host know — your reason has been forwarded."
                )
                host_line = f"🚪 **Dropped out — Minor / Casual** · <@{uid}> ({nation_display}). Excused; kept in list as proof."
            else:
                # Minor + Strict: cannot unreserve; snapshot warns; dispute via ticket after the game.
                declined = {int(x) for x in game.get("declined_ids", []) if str(x).isdigit()}
                declined.add(uid)
                game["declined_ids"] = list(declined)
                user_msg = (
                    f"⚠️ The game has already started, so you **cannot unreserve** **{nation_display}**.\n"
                    f"You'll receive your no-show warning at the attendance snapshot. You can open a ticket in "
                    f"<#{G.TICKET_CHANNEL_ID}> to have it **removed after the game concludes**.\n"
                    f"Your reason has been forwarded to the host."
                )
                host_line = f"🚪 **Dropping out — Minor / Strict** · <@{uid}> ({nation_display})."

        # VIP: still can't unreserve Majors / Strict Minors after start, but never threaten warns.
        vip_member = guild.get_member(uid) if guild else None
        if (is_major or not is_casual) and _member_has_vip(vip_member):
            user_msg = (
                f"👑 As a **VIP**, you won't receive a session warning for this.\n"
                f"Your reservation for **{nation_display}** stays on the locked list; "
                f"the host has been notified of your reason."
            )
            host_line = f"👑 **VIP dropout notice** · <@{uid}> ({nation_display}). No warning (VIP)."

        try:
            await save_single_game(storage_key or tid, game, rewrite_reservations=False)
        except TimeoutError as e:
            print(f"[WARN] Participation No save timed out for {uid} in {tid}: {e}")
            return await _reply_participation_dm(
                interaction,
                "⏳ The bot is busy saving game data right now. Please try the **No** button again in a few seconds.",
            )
        except Exception as e:
            print(f"[WARN] Participation No save failed for {uid} in {tid}: {e}")
            return await _reply_participation_dm(
                interaction,
                "⚠️ Couldn't save your drop-out. Please try the **No** button again in a moment.",
            )

    await _reply_participation_dm(interaction, user_msg)
    await _disable_participation_buttons(source_message, note="🚫 You chose not to participate.")
    record_attendance_event(
        _attendance_stable_id(game, tid),
        "participation_no",
        user_id=uid,
        details={
            "nation": nation_display,
            "reason": reason,
            "major": bool(is_major),
            "outcome": "excused" if (not is_major and is_casual) else "declined",
        },
    )
    if not ATTENDANCE_WEB_ONLY:
        await _forward_participation_to_host(game, f"{host_line}\n> **Reason:** {reason}")
    schedule_participation_tracker_update(tid)


# ==========================================================================
# HOT-JOIN SYSTEM
# --------------------------------------------------------------------------
# A purple panel is posted in the reservation thread at /game_start. Players
# press "Request Hot-Join", pick a nation, and the request is forwarded to the
# host (pinged) in the Host Control Center with Approve / Decline buttons.
# Approve runs the same flow as a website late join (VC + pass + instant info access, no
# Yes/No prompt). Decline DMs the player that their request was declined.
# ==========================================================================
async def _execute_late_join(guild: discord.Guild, thread_id: str, user: discord.Member,
                             nation: str, join_label: str = "Hot Join"):
    """Core late/hot-join logic shared by the website's late join and hot-join approvals.

    Reserves the nation (clearing prior slots), marks presence, grants the Gamer
    Pass, and builds a pass-only voice channel. Returns (ok, summary_or_error)."""
    thread_id = str(thread_id)
    games_data = await read_json(GAMES_FILE)
    storage_key, target_game = _find_game_entry(games_data, thread_id)
    if not target_game:
        return False, "❌ Game not found."

    if target_game.get("status") in ("ended", "cancelled") or not target_game.get("game_started"):
        return False, "❌ Hot-join is no longer available for this game."

    game_name = target_game.get("thread_name", "Active Game")
    game_mode = target_game.get("mode", "Historical")

    if not await is_user_authenticated(user, thread_id):
        return False, RESERVATION_REJECTED_UNVERIFIED_MESSAGE

    reservations = target_game.get("reservations", {})

    # Refuse (before mutating anything) if the target nation is held by someone else.
    holder = reservations.get(nation)
    if holder is not None and str(holder) != str(user.id) and not str(nation).startswith("_FILL_"):
        return False, f"⚠️ **{nation}** is already taken by <@{holder}>. Please clear them first."

    # 1. Clear the user from any previous reservation (prevents double slots), then assign.
    for n, uid in list(reservations.items()):
        if str(uid) == str(user.id):
            del reservations[n]
    reservations[nation] = user.id
    target_game["reservations"] = reservations

    if "late_join_nations" not in target_game:
        target_game["late_join_nations"] = []
    if nation not in target_game["late_join_nations"]:
        target_game["late_join_nations"].append(nation)

    if "present_ids" not in target_game:
        target_game["present_ids"] = []
    if user.id not in target_game["present_ids"]:
        target_game["present_ids"].append(user.id)

    if "game_warns" in target_game and user.id in target_game["game_warns"]:
        target_game["game_warns"].remove(user.id)

    if "action_logs" not in target_game:
        target_game["action_logs"] = []
    target_game["action_logs"].append(f"**{user.display_name}**: {join_label} ({nation})")
    if len(target_game["action_logs"]) > 10:
        target_game["action_logs"].pop(0)

    await save_single_game(storage_key or thread_id, target_game, rewrite_reservations=True)
    record_attendance_event(
        _attendance_stable_id(target_game, thread_id), "late_join", user_id=user.id,
        details={"nation": nation, "kind": join_label},
    )
    action_summary = f"✅ **{user.mention}** has been hot-joined into **{game_name}** as **{nation}**.\n"

    # 2. Grant the Gamer Pass (instant info-channel + VC access, no prompt).
    pass_role = None
    try:
        pass_role_id = target_game.get("temp_gamer_pass_role")
        if pass_role_id:
            pass_role = guild.get_role(int(pass_role_id))
            if pass_role and pass_role not in user.roles:
                await user.add_roles(pass_role)
                action_summary += f"🎟️ Granted **{pass_role.name}**.\n"
    except Exception as e:
        print(f"[HotJoin] Role assignment failed: {e}")

    # 3. Locate / create the region category + a pass-only voice channel.
    target_category_name = get_category_name_for_nation(nation, game_mode)
    target_category = discord.utils.get(guild.categories, name=target_category_name)
    created_category = False
    new_vc = None
    try:
        if not target_category:
            target_category = await guild.create_category(name=target_category_name)
            created_category = True
            action_summary += f"📁 Created missing Category: **{target_category_name}**.\n"

        if target_category:
            clean_name = nation.replace("_FILL_", "") if nation.startswith("_FILL_") else nation
            existing_channel = discord.utils.get(
                target_category.voice_channels, name=clean_name
            )
            if not existing_channel:
                overwrites = {
                    guild.default_role: discord.PermissionOverwrite(view_channel=False, connect=False),
                    guild.me: discord.PermissionOverwrite(view_channel=True, connect=True, manage_channels=True)
                }
                if pass_role:
                    overwrites[pass_role] = discord.PermissionOverwrite(view_channel=True, connect=True, speak=True)
                try:
                    hoi4_mp_role = guild.get_role(int(globals().get("HOI4_MP_ROLE_ID", 0)))
                    if hoi4_mp_role:
                        overwrites[hoi4_mp_role] = discord.PermissionOverwrite(view_channel=False, connect=False)
                except Exception:
                    pass
                new_vc = await target_category.create_voice_channel(name=clean_name, overwrites=overwrites)
                await new_vc.edit(position=len(target_category.channels))
                action_summary += f"🔊 Created new VC in **{target_category.name}**: **{new_vc.name}** (Pass only).\n"
            else:
                action_summary += f"🔊 Voice channel **{clean_name}** already exists.\n"
    except Exception as e:
        print(f"[HotJoin] VC creation failed: {e}")
        action_summary += "⚠️ Failed to create Voice Channel or Category (Check bot permissions).\n"

    # Game end only deletes IDs stored on the game. Late-join channels used to be omitted.
    if new_vc is not None or created_category:
        vc_ids = [int(x) for x in (target_game.get("temp_vc_channels") or []) if str(x).isdigit()]
        cat_ids = [int(x) for x in (target_game.get("temp_vc_categories") or []) if str(x).isdigit()]
        if new_vc is not None and int(new_vc.id) not in vc_ids:
            vc_ids.append(int(new_vc.id))
        if created_category and target_category is not None and int(target_category.id) not in cat_ids:
            cat_ids.append(int(target_category.id))
        target_game["temp_vc_channels"] = vc_ids
        target_game["temp_vc_categories"] = cat_ids
        try:
            await save_single_game(storage_key or thread_id, target_game, rewrite_reservations=False)
        except Exception as e:
            print(f"[HotJoin] Could not store late-join VC ids: {e}")

    # 4. Refresh the reservation board + public log.
    try:
        schedule_reservation_update(int(thread_id))
        schedule_log_update(int(thread_id))
        schedule_participation_tracker_update(int(thread_id))
    except Exception as e:
        print(f"[HotJoin] UI update failed: {e}")

    return True, action_summary


def _resolve_hotjoin_nation(mode: str, raw: str) -> str | None:
    """Case-insensitive validation of a requested nation for a mode. None if invalid."""
    raw = (raw or "").strip()
    if not raw:
        return None
    if mode == "Other":
        return raw  # free-form mode
    try:
        all_nations = get_all_nations_for_mode(mode)
    except Exception:
        all_nations = []
    return next((n for n in all_nations if n.lower() == raw.lower()), None)






class HotJoinButton(discord.ui.DynamicItem[discord.ui.Button],
                    template=r"hotjoin:(?P<action>request|approve|decline):(?P<thread>\d+)(?::(?P<user>\d+))?"):
    """Persistent (restart-proof) buttons for the hot-join panel and host approvals."""

    def __init__(self, action: str, thread_id: int, user_id=None):
        self.action = action
        self.thread_id = int(thread_id)
        self.user_id = int(user_id) if user_id else None
        if action == "request":
            button = discord.ui.Button(
                label="Request Hot-Join", style=discord.ButtonStyle.primary,
                emoji="🔥", custom_id=f"hotjoin:request:{thread_id}",
            )
        elif action == "approve":
            button = discord.ui.Button(
                label="Approve", style=discord.ButtonStyle.success,
                emoji="✅", custom_id=f"hotjoin:approve:{thread_id}:{user_id}",
            )
        else:  # decline
            button = discord.ui.Button(
                label="Decline", style=discord.ButtonStyle.danger,
                emoji="🚫", custom_id=f"hotjoin:decline:{thread_id}:{user_id}",
            )
        super().__init__(button)

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(match["action"], int(match["thread"]), match["user"] if match["user"] else None)

    async def callback(self, interaction: discord.Interaction):
        if self.action == "request":
            await handle_hotjoin_request(interaction, self.thread_id)
        else:
            await handle_hotjoin_decision(interaction, self.thread_id, self.user_id, approve=(self.action == "approve"))


async def handle_hotjoin_request(interaction: discord.Interaction, thread_id: int):
    """Old Hot-Join panels (in reservation threads): hot-join is on the map now."""
    await interaction.response.send_message(
        f"🔥 Hot-join is on the website now — pick a free nation on the map: {_map_game_url(thread_id)}",
        ephemeral=True,
    )


_hotjoin_decision_locks: dict[str, asyncio.Lock] = {}


async def handle_hotjoin_decision(interaction: discord.Interaction, thread_id: int, user_id: int, approve: bool):
    key = f"{thread_id}:{user_id}"
    lock = _hotjoin_decision_locks.setdefault(key, asyncio.Lock())
    async with lock:
        await _handle_hotjoin_decision_locked(interaction, thread_id, user_id, approve)


async def _handle_hotjoin_decision_locked(
    interaction: discord.Interaction, thread_id: int, user_id: int, approve: bool
):
    """Host pressed Approve/Decline on a hot-join request."""
    await interaction.response.defer(ephemeral=True)
    games_data = await read_json(GAMES_FILE)
    storage_key, game = _find_game_entry(games_data, thread_id)
    if not game:
        return await interaction.followup.send("❌ Game not found.", ephemeral=True)
    if not _can_end_assigned_game(interaction.user, game):
        return await interaction.followup.send(
            f"❌ Only the assigned game host (<@{game.get('host_id')}>) or Host Management "
            "can decide hot-join requests.",
            ephemeral=True,
        )

    requests = game.get("hotjoin_requests", {})
    req = requests.get(str(user_id)) if isinstance(requests, dict) else None
    if not req or req.get("status") != "pending":
        await _disable_message_buttons(interaction.message, note="_This request is no longer active._")
        return await interaction.followup.send("⚠️ This request is no longer active.", ephemeral=True)

    nation = req.get("nation")
    guild = interaction.guild
    member = guild.get_member(int(user_id)) if guild else None
    if member is None and guild:
        try:
            member = await guild.fetch_member(int(user_id))
        except Exception:
            member = None
    if member is None:
        req["status"] = "failed"
        game["hotjoin_requests"] = requests
        await save_single_game(storage_key or str(thread_id), game, rewrite_reservations=False)
        await _disable_message_buttons(interaction.message, note="_Requester left the server._")
        return await interaction.followup.send("❌ That player is no longer in the server.", ephemeral=True)

    if not approve:
        req["status"] = "declined"
        game["hotjoin_requests"] = requests
        await save_single_game(storage_key or str(thread_id), game, rewrite_reservations=False)
        try:
            await member.send("🚫 Your hot-join request has been declined.")
        except Exception:
            pass
        await _disable_message_buttons(interaction.message, note=f"🚫 Declined by {interaction.user.mention}.")
        return await interaction.followup.send(f"🚫 Declined {member.mention}'s hot-join request.", ephemeral=True)

    # --- APPROVE → run the late-join flow ---
    ok, summary = await _execute_late_join(
        guild, storage_key or str(thread_id), member, nation, join_label="Hot Join"
    )
    if not ok:
        # Leave the request pending so the host can retry after resolving the conflict.
        return await interaction.followup.send(summary, ephemeral=True)

    req["status"] = "approved"
    # Re-read to avoid clobbering the reservation changes _execute_late_join just wrote.
    games_data = await read_json(GAMES_FILE)
    storage_key, refreshed_game = _find_game_entry(games_data, storage_key or thread_id)
    game = refreshed_game or game
    reqs = game.get("hotjoin_requests", {})
    if not isinstance(reqs, dict):
        reqs = {}
    reqs[str(user_id)] = req
    game["hotjoin_requests"] = reqs
    await save_single_game(storage_key or str(thread_id), game, rewrite_reservations=False)

    game_info_channel_id = MODE_CONFIG.get(game.get("mode", ""), {}).get("game_info_channel_id")
    info_hint = f" Check <#{game_info_channel_id}> for the ID, Password & Checksum." if game_info_channel_id else ""
    try:
        await member.send(
            f"✅ Your hot-join request as **{nation}** was **approved**! "
            f"You've been given your Game Pass and voice channel.{info_hint}")
    except Exception:
        pass

    await _disable_message_buttons(interaction.message, note=f"✅ Approved by {interaction.user.mention}.")
    await interaction.followup.send(summary, ephemeral=True)


async def _disable_message_buttons(msg, note: str = None):
    """Strip buttons off a guild message (host panel request) and optionally append a note."""
    try:
        if msg is None:
            return
        content = msg.content or ""
        if note:
            content = f"{content}\n{note}".strip()
        await msg.edit(content=content, view=None)
    except Exception:
        pass


# =============================================================================
# CRASH REPORT SUBMISSION SYSTEM (DM-based log upload → mod developer)
# =============================================================================
CRASH_REPORT_DEV_ROLE_ID = 0   # pinged on delivery (Server settings)
CRASH_REPORT_CHANNEL_ID = 0    # crash-report log channel (Server settings)
CRASH_REPORT_ALLOWED_ARCHIVE_EXTS = {".zip", ".rar", ".7z"}
CRASH_REPORT_MIN_ARCHIVE_BYTES = 500 * 1024  # 500 KB — real crash folders include minidump + logs
CRASH_REPORT_COMMEND_COOLDOWN_SEC = 6 * 3600  # 6 hours between Roleplay commend rewards
CRASH_REPORT_COMMEND_COOLDOWN_KEY = "crash_report_commend_cooldowns"
CRASH_REPORT_MAX_DISCORD_UPLOAD_BYTES = 25 * 1024 * 1024  # Discord bot attachment cap (25 MB)
CRASH_REPORT_MIN_GAME_LOG_BYTES = 2048          # real game.log is usually much larger
CRASH_REPORT_MIN_ERROR_LOG_BYTES = 32
CRASH_REPORT_MIN_LOGS_UNCOMPRESSED_BYTES = 50 * 1024  # whole logs/ tree should not be tiny

_HOI4_LOG_CONTENT_MARKERS = (
    b"hearts of iron",
    b"hoi4",
    b"paradox",
    b"[system]",
    b"application:",
    b"stacktrace",
    b"error",
)





def _log_bytes_look_like_hoi4(data: bytes) -> bool:
    """Heuristic: real HOI4 logs mention Paradox / HOI4 / system channels."""
    if not data:
        return False
    sample = data[:16384].lower()
    return any(marker in sample for marker in _HOI4_LOG_CONTENT_MARKERS)


def _validate_hoi4_zip_archive(data: bytes) -> tuple[bool, str | None]:
    """Verify ZIP structure and that log files look genuine (not just empty renamed files)."""
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            game_log_info = None
            error_log_info = None
            has_minidump = False
            logs_uncompressed = 0

            for info in zf.infolist():
                if info.is_dir():
                    continue
                norm = info.filename.replace("\\", "/").lower().lstrip("/")
                if norm.endswith("logs/game.log"):
                    game_log_info = info
                elif norm.endswith("logs/error.log"):
                    error_log_info = info
                elif norm.endswith("minidump.dmp") and "logs" in norm:
                    has_minidump = True
                if norm.startswith("logs/") or "/logs/" in norm:
                    logs_uncompressed += info.file_size

            if not game_log_info and not error_log_info:
                return False, (
                    "❌ Your archive doesn't appear to contain HOI4 log files. Please ZIP the entire "
                    "`logs` folder so it includes `error.log` or `game.log`."
                )

            if game_log_info:
                try:
                    game_body = zf.read(game_log_info.filename)
                except Exception:
                    return False, "❌ Could not read `game.log` inside your archive. Please re-zip your logs folder."
                if len(game_body) < CRASH_REPORT_MIN_GAME_LOG_BYTES:
                    return False, (
                        "❌ `game.log` in your archive is too small to be a real session log. "
                        "Please ZIP the full `logs` folder from your HOI4 directory."
                    )
                if not _log_bytes_look_like_hoi4(game_body):
                    return False, (
                        "❌ `game.log` does not look like a genuine Hearts of Iron IV log. "
                        "Please upload your real `Documents\\Paradox Interactive\\Hearts of Iron IV\\logs` folder."
                    )

            if not game_log_info:
                if not error_log_info:
                    return False, (
                        "❌ Please include `game.log` (preferred) or both `error.log` and your crash `minidump.dmp`."
                    )
                try:
                    error_body = zf.read(error_log_info.filename)
                except Exception:
                    return False, "❌ Could not read `error.log` inside your archive."
                if len(error_body) < CRASH_REPORT_MIN_ERROR_LOG_BYTES and not has_minidump:
                    return False, (
                        "❌ `error.log` alone is too small — include `game.log` or your full crash logs folder."
                    )
                if not has_minidump and logs_uncompressed < CRASH_REPORT_MIN_LOGS_UNCOMPRESSED_BYTES:
                    return False, (
                        "❌ The `logs` folder in your archive looks incomplete. "
                        "ZIP the entire logs folder (including `minidump.dmp` if present)."
                    )

            return True, None
    except (zipfile.BadZipFile, OSError, ValueError):
        return False, "❌ Invalid or corrupted `.zip` file. Please create a new archive of your logs folder."




async def _validate_crash_report_bytes(filename: str, data: bytes) -> tuple[bool, str | None]:
    """Anti-farming checks on raw archive bytes (extension, size, HOI4 log paths)."""
    ext = os.path.splitext(filename or "")[1].lower()
    if ext not in CRASH_REPORT_ALLOWED_ARCHIVE_EXTS:
        return False, (
            "❌ Invalid file type. Please compress your logs folder into a **.zip** file and upload the archive."
        )
    if len(data) < CRASH_REPORT_MIN_ARCHIVE_BYTES:
        return False, (
            "❌ File too small. Please ensure you are zipping the entire crash folder "
            "containing your minidump and logs."
        )
    if ext != ".zip":
        return False, (
            "❌ Please upload a **.zip** archive so we can verify your log files (`error.log` / `game.log`)."
        )
    ok, err = _validate_hoi4_zip_archive(data)
    if not ok:
        return False, err
    return True, None




def _crash_report_build_embed(user: discord.User, sess: dict) -> discord.Embed:
    verified = bool(sess.get("verified"))
    badge = "[✅ HOI4 Verified]" if verified else "[❌ Unverified]"
    embed = discord.Embed(
        title="🚨 New Crash Report",
        color=discord.Color.red(),
        timestamp=discord.utils.utcnow(),
    )
    embed.add_field(
        name="Reporter",
        value=f"{user.mention} — **{user.name}** (`{user.id}`)",
        inline=False,
    )
    embed.add_field(name="Verification", value=badge, inline=True)
    thread_id = sess.get("thread_id")
    if thread_id:
        game_lines = [
            f"**{sess.get('game_mode', 'Unknown')}**", sess.get("thread_name", "—"), sess.get("game_link") or f"<#{thread_id}>",
        ]
        embed.add_field(name="Game", value="\n".join(game_lines), inline=False)
        if sess.get("host_id"):
            embed.add_field(name="Host", value=f"<@{sess['host_id']}>", inline=True)
    embed.add_field(
        name="What happened before the crash",
        value=(sess.get("what_happened") or "—")[:1024],
        inline=False,
    )
    notes = (sess.get("additional_notes") or "").strip()
    if notes:
        embed.add_field(name="Additional notes", value=notes[:1024], inline=False)
    return embed


def _crash_report_build_files(sess: dict) -> list[discord.File]:
    files = []
    for att_info in sess.get("attachments", []):
        data = att_info.get("data")
        filename = att_info.get("filename") or "crash_report.zip"
        if data:
            files.append(discord.File(io.BytesIO(data), filename=filename))
    return files


def _crash_report_attachment_links(sess: dict) -> str:
    lines = []
    for att_info in sess.get("attachments", []):
        name = att_info.get("filename") or "archive"
        url = att_info.get("url")
        if url:
            lines.append(f"• [{name}]({url})")
        else:
            lines.append(f"• `{name}`")
    return "\n".join(lines) if lines else "—"


async def _get_crash_commend_cooldowns() -> dict:
    try:
        config = await read_json(BOT_CONFIG_FILE)
        raw = config.get(CRASH_REPORT_COMMEND_COOLDOWN_KEY, {})
        return raw if isinstance(raw, dict) else {}
    except Exception as e:
        print(f"[WARN] Crash commend cooldown read failed: {e}")
        return {}


async def _crash_commend_on_cooldown(user_id: int) -> bool:
    cooldowns = await _get_crash_commend_cooldowns()
    last = cooldowns.get(str(user_id))
    if not last:
        return False
    try:
        return (time.time() - float(last)) < CRASH_REPORT_COMMEND_COOLDOWN_SEC
    except (TypeError, ValueError):
        return False


async def _record_crash_commend_award(user_id: int):
    try:
        config = await read_json(BOT_CONFIG_FILE)
        cooldowns = config.get(CRASH_REPORT_COMMEND_COOLDOWN_KEY, {})
        if not isinstance(cooldowns, dict):
            cooldowns = {}
        cooldowns[str(user_id)] = time.time()
        config[CRASH_REPORT_COMMEND_COOLDOWN_KEY] = cooldowns
        await write_json(BOT_CONFIG_FILE, config)
    except Exception as e:
        print(f"[WARN] Crash commend cooldown record failed: {e}")








async def _check_hoi4_verified_for_crash_report(user: discord.abc.User) -> bool:
    """True if the user holds RP or Hist Verified on Discord or in MySQL."""
    guild = bot.get_guild(cur_gid())
    if guild:
        member = guild.get_member(user.id)
        if member is None:
            try:
                member = await guild.fetch_member(user.id)
            except Exception:
                member = None
        if member:
            for track in VERIFIED_TRACKS:
                verified_role = guild.get_role(_verified_role_id(track, fallback=False))
                if verified_role and verified_role in member.roles:
                    return True
    try:
        stats = await get_mysql_player_stats(str(user.id))
        return bool(stats.get("hoi4_verified") or stats.get("hist_verified"))
    except Exception as e:
        print(f"[WARN] Crash report verification DB check failed: {e}")
        return False


def _crash_report_game_context_from_dict(game: dict | None, thread_id: int) -> dict:
    game = game or {}
    return {
        "thread_id": int(thread_id),
        "game_mode": game.get("mode", "Unknown"),
        "thread_name": game.get("thread_name") or f"Game {thread_id}",
        "host_id": game.get("host_id"),
        "game_link": _game_discord_ref(game, thread_id),
    }


















async def _award_crash_report_merit(user_id: int, verified: bool) -> int:
    """Award Merit Points for an accepted crash report.

    Verified users get CRASH_REPORT_MERIT_VERIFIED; unverified users get
    CRASH_REPORT_MERIT_UNVERIFIED.
    Returns the number of merit points awarded (0 on failure). DB errors must not
    block report delivery."""
    amount = CRASH_REPORT_MERIT_VERIFIED if verified else CRASH_REPORT_MERIT_UNVERIFIED
    try:
        result = await _apply_merit_change(user_id, amount, reason="Crash report submission")
        try:
            log_embed = discord.Embed(
                title="🎖️ Crash Report Merit Awarded",
                color=discord.Color.gold(),
                timestamp=discord.utils.utcnow(),
            )
            log_embed.add_field(name="Target", value=f"<@{user_id}>", inline=True)
            log_embed.add_field(name="Amount", value=f"+{amount} Merit", inline=True)
            log_embed.add_field(name="New Total", value=str(result["new"]), inline=True)
            log_embed.add_field(name="Reason", value="Accepted crash report submission", inline=False)
            log_ref = await send_host_log_embed(log_embed)
        except Exception as log_error:
            log_ref = None
            print(f"[WARN] Crash report merit log failed for {user_id}: {log_error}")
        record_moderation_event(
            user_id,
            "merit",
            amount=amount,
            reason="Accepted crash report submission",
            automatic=True,
            details={"kind": "crash-report"},
            log=log_ref,
        )
        return amount
    except Exception as e:
        print(f"[WARN] Crash report merit award failed for {user_id}: {e}")
        return 0


async def _forward_crash_report_to_developer(user: discord.User, sess: dict) -> bool:
    """Post crash report to #crash-reports and ping the Mod Developer role."""
    embed = _crash_report_build_embed(user, sess)
    files = _crash_report_build_files(sess)
    total_bytes = sum(len(a.get("data") or b"") for a in sess.get("attachments", []))
    too_large = total_bytes > _crash_upload_limit()
    dev_ping = f"<@&{G.CRASH_REPORT_DEV_ROLE_ID}>"
    game_tag = ""
    if sess.get("thread_id"):
        game_link = sess.get("game_link") or f"<#{sess['thread_id']}>"
        game_tag = f" — **{sess.get('game_mode', 'Unknown')}** ({game_link})"
    header = f"{dev_ping} **New crash report** from {user.mention}{game_tag}"

    if too_large:
        embed.add_field(
            name="Attachments (exceeds 25 MB upload limit)",
            value=_crash_report_attachment_links(sess),
            inline=False,
        )
        files = []

    # Primary: dedicated crash-reports channel.
    try:
        channel = bot.get_channel(G.CRASH_REPORT_CHANNEL_ID)
        if channel is None:
            channel = await bot.fetch_channel(G.CRASH_REPORT_CHANNEL_ID)
        if channel:
            for f in files:
                f.fp.seek(0)
            await channel.send(content=header, embed=embed, files=files or None)
            print(f"[CrashReport] Delivered to crash-reports channel {G.CRASH_REPORT_CHANNEL_ID}")
            return True
    except Exception as e:
        print(f"[WARN] Crash report channel post failed: {type(e).__name__}: {e}")

    # Fallback: host-log channel (embed + links if upload failed).
    try:
        link_embed = _crash_report_build_embed(user, sess)
        if too_large or not files:
            link_embed.add_field(
                name="Attachments" if not too_large else "Attachments (exceeds 25 MB upload limit)",
                value=_crash_report_attachment_links(sess),
                inline=False,
            )
        else:
            for f in files:
                f.fp.seek(0)
            channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
            if channel is None:
                channel = await bot.fetch_channel(G.HOST_LOG_CHANNEL_ID)
            if channel:
                await channel.send(content=header, embed=link_embed, files=files)
                print(f"[CrashReport] Delivered via host-log fallback {G.HOST_LOG_CHANNEL_ID}")
                return True
        await send_host_log_embed(link_embed, content=f"{header} (`{user.id}`)")
        print("[CrashReport] Delivered via host-log webhook fallback")
        return True
    except Exception as e:
        print(f"[WARN] Crash report fallback delivery failed: {type(e).__name__}: {e}")

    return False




