# ————— 100% LIVE Discord role resolution (web token minting) —————
# The casino supports RP (Roleplay) gamemodes only, so ONLY the RP-relevant
# roles grant web permissions. MP Trusted & Verified roles
# deliberately do NOT count. Evaluated against the caller's CURRENT guild
# roles at mint time — NO users-table / database role reads.
_LIVE_ROLE_IDS: dict[str, int] = {
    "vip": ROLE_IDS["VIP_ROLE_ID"],
    "trusted": ROLE_IDS["HOI4_RP_TRUSTED"],       # RP Trusted only
    "verified": ROLE_IDS["HOI4_VERIFIED"],        # HOI4 (RP) Verified only
    "authenticated": ROLE_IDS["AUTHENTICATED"],   # Authenticated V.2 (Steam)
}


def _live_role_flags(member) -> dict:
    """Pure LIVE Discord guild-role resolution for web token minting.

    Evaluates the caller's CURRENT `member.roles` array directly — no
    database role checks, no cached users-table fallbacks. Returns:
      is_vip / is_trusted / is_verified / is_authenticated
      role_tier       — numeric rank derived from the flags
                        (vip=0 · trusted=1 · verified|auth=2 · none=3)
      can_roll_majors — any granted role (or administrator)
    """
    role_ids: set[int] = set()
    role_names: list[str] = []
    is_admin = False
    if isinstance(member, discord.Member):
        # Audit hygiene: a member can carry dozens of cosmetic guild roles,
        # which flooded the [ROLE-CHECK] log. Only roles the bot actually
        # tracks (ROLE_IDS + host + senior-management role lists) are shown.
        tracked_role_ids = (
            set(ROLE_IDS.values())
            | set(ALLOWED_HOST_ROLES)
            | set(SENIOR_MANAGEMENT_ROLES)
        )
        for role in member.roles:
            role_ids.add(role.id)
            if role.id in tracked_role_ids:
                role_names.append(role.name)
        is_admin = bool(member.guild_permissions.administrator)

    def _has(role_id: int) -> bool:
        return bool(role_id) and role_id in role_ids

    is_vip = _has(_LIVE_ROLE_IDS["vip"]) or is_admin
    is_trusted = _has(_LIVE_ROLE_IDS["trusted"])
    is_verified = _has(_LIVE_ROLE_IDS["verified"])
    is_authenticated = _has(_LIVE_ROLE_IDS["authenticated"])

    if is_vip:
        role_tier = _ROLE_TIER_NUM["vip"]
    elif is_trusted:
        role_tier = _ROLE_TIER_NUM["trusted"]
    elif is_verified or is_authenticated:
        role_tier = _ROLE_TIER_NUM["verified"]
    else:
        role_tier = _ROLE_TIER_NUM["none"]

    uid = getattr(member, "id", 0) or 0
    name = getattr(member, "name", None) or "unknown"
    print(
        f"[ROLE-CHECK] User {uid} ({name}) | Tracked Roles: {role_names} | "
        f"Flags: VIP={is_vip}, Trusted={is_trusted}, Verified={is_verified}, "
        f"Auth={is_authenticated} | Tier={role_tier}"
    )

    return {
        "is_vip": is_vip,
        "is_trusted": is_trusted,
        "is_verified": is_verified,
        "is_authenticated": is_authenticated,
        "role_tier": role_tier,
        "can_roll_majors": bool(
            is_vip or is_trusted or is_verified or is_authenticated
        ),
    }


