class PlayerSelect(discord.ui.UserSelect):
    def __init__(self, game_id: str, action_type: str):
        super().__init__(placeholder="Choose a player...", min_values=1, max_values=1)
        self.game_id = game_id
        self.action_type = action_type

    async def callback(self, interaction: discord.Interaction):
        # This handles the logic when a player is picked from the dropdown
        target_member = self.values[0]

        if self.action_type in ["add", "remove"]:
            # Logic for Attendance
            await modify_attendance(interaction, self.game_id, self.action_type, target_member)
        else:
            # Logic for Modal-based actions (Warn, Commend, etc.)
            # You can trigger your Modals here based on self.action_type
            await interaction.response.send_message(f"Processing {self.action_type} for {target_member.display_name}...", ephemeral=True)

class PlayerSelectView(discord.ui.View):
    def __init__(self, game_id: str, action_type: str):
        super().__init__(timeout=60)
        self.add_item(PlayerSelect(game_id, action_type))


# Rebuild prompt string from the canonical HOI4_TAGS dict (defined near Fortunes).
TAGS_PROMPT_STRING = "\n".join([f"- {tag}: {country}" for tag, country in HOI4_TAGS.items()])


def _discord_handle(user) -> str:
    """Human-readable Discord handle (Name#0000 when discriminator exists)."""
    if user is None:
        return "Unknown"
    name = getattr(user, "name", None) or getattr(user, "display_name", None) or str(user)
    discr = getattr(user, "discriminator", None)
    if discr and str(discr) not in ("0", "0000"):
        return f"{name}#{discr}"
    return str(name)


def _reservation_mention(value) -> str:
    """Board-safe user renderer for reservation list lines.

    The stored reservation value IS the Discord snowflake
    (`game_reservations.user_id` == discord id — the bot's `users` table
    keys on the same `discord_id`, so no extra join is needed for the ID).

    Renders the validated snowflake DIRECTLY as the native `<@id>` mention:
    Discord resolves the user's current handle itself, host removals on the
    live map match the same id, and NO member-cache lookup can silently strip the ID down to
    '@unknown-user'.
      · digit string / int / whole float → `<@id>` (15–21 digit snowflake)
      · any other non-empty legacy string  → verbatim `@text` (legacy rows
        that stored a handle instead of a snowflake)
      · empty / zero                         → '@unknown-user' safety net ONLY
    """
    raw = value
    # Tolerate numeric snowflakes that lost their type through JSON layers
    # (float in scientific notation included) without losing any digit.
    if isinstance(raw, float) and raw.is_integer() and raw > 0:
        raw = int(raw)
    if isinstance(raw, int):
        raw = str(raw)
    raw = str(raw or "").strip()
    if raw.isdigit() and int(raw) > 0:
        return f"<@{raw}>"
    if raw and not raw.isdigit():
        # Legacy rows that stored a handle instead of a snowflake.
        return f"@{raw}"
    return "@unknown-user"


def _resolve_nation_tag(search_term: str) -> tuple[str, str]:
    """Return (TAG, nation_display) from a user-typed nation/tag string."""
    raw = (search_term or "").strip()
    upper = raw.upper()
    if upper in HOI4_TAGS:
        return upper, HOI4_TAGS[upper]
    lower = raw.lower()
    if lower in HOI4_NATION_ALIASES:
        nation = HOI4_NATION_ALIASES[lower]
        tag = _hoi4_tag_for_nation(nation) or upper
        return tag, nation
    for tag, country in HOI4_TAGS.items():
        if country.lower() == lower:
            return tag, country
    # Unknown / custom — treat typed value as both tag guess and nation label.
    tag = upper if len(upper) == 3 and upper.isalpha() else (_hoi4_tag_for_nation(raw) or upper[:3].upper())
    return tag, raw.title() if raw else upper


def _extract_nation_log_lines(chat_log_text: str, target_tag: str) -> list[str]:
    """Pull HOI4 log lines belonging to a country tag (main + any coop voices)."""
    extracted = []
    tag = (target_tag or "").upper()
    if not tag or not chat_log_text:
        return extracted
    for line in chat_log_text.splitlines():
        upper_line = line.upper()
        stripped = upper_line.strip()
        if stripped.startswith(tag) and (len(stripped) == len(tag) or not stripped[len(tag)].isalpha()):
            extracted.append(line)
            continue
        # Fused forms: SOVPlayerName: message / SOVPlayer joined
        if stripped.startswith(tag):
            extracted.append(line)
            continue
        if "):" in upper_line and "(" in upper_line:
            name_section = upper_line.split("):")[0].split("(")[-1]
            clean_name = "".join(c for c in name_section if c.isalpha())
            if clean_name.startswith(tag):
                extracted.append(line)
    return extracted


def _rp_payload_from_log_line(line: str, tag: str) -> str:
    """Extract only the player-written message body, excluding join/leave system events."""
    text = (line or "").strip()
    if not text:
        return ""
    if "):" in text:
        payload = text.split("):", 1)[1].strip()
        return "" if re.fullmatch(r"(joined|connected|reconnected|left|disconnected|quit)\.?", payload, re.IGNORECASE) else payload
    tag_pos = text.upper().find((tag or "").upper())
    colon_pos = text.find(":", max(tag_pos, 0))
    if colon_pos >= 0:
        payload = text[colon_pos + 1:].strip()
        return "" if re.fullmatch(r"(joined|connected|reconnected|left|disconnected|quit)\.?", payload, re.IGNORECASE) else payload
    return ""


def _authoritative_nation_rp_stats(log_text: str, tag: str) -> dict:
    extracted = _extract_nation_log_lines(log_text, tag)
    payloads = [
        payload for payload in (_rp_payload_from_log_line(line, tag) for line in extracted)
        if payload
    ]
    return {
        "tag": tag,
        "rp_lines": len(payloads),
        "rp_words": sum(len(re.findall(r"\b[\w'-]+\b", payload, re.UNICODE)) for payload in payloads),
        "extracted_lines": extracted,
    }


def _build_authoritative_log_audit(log_text: str, reservations: dict | None) -> str:
    """Deterministic counts supplied to Gemini so it never estimates from a partial reading."""
    tags = set()
    for nation in (reservations or {}):
        if str(nation).startswith("_FILL_"):
            continue
        base = str(nation).split("_coop", 1)[0]
        tag = _hoi4_tag_for_nation(base)
        if tag:
            tags.add(tag)
    tags.update(_extract_tags_from_chat_log(log_text))
    for raw_line in log_text.splitlines():
        stripped = raw_line.strip()
        direct = re.match(r"^([A-Z]{3}|D\d{2})[A-Za-z0-9_-]*(?::|\s)", stripped)
        wrapped = re.search(r"\(([A-Z]{3}|D\d{2})[A-Za-z0-9_-]*\):", stripped)
        match = direct or wrapped
        if match:
            tags.add(match.group(1).upper())

    total_lines = len(log_text.splitlines())
    total_words = len(re.findall(r"\b[\w'-]+\b", log_text, re.UNICODE))
    lines = [
        "--- AUTHORITATIVE FULL-DOCUMENT AUDIT (COMPUTED BY THE BOT; DO NOT RECOUNT) ---",
        f"Document size: {len(log_text.encode('utf-8')):,} UTF-8 bytes",
        f"Document lines: {total_lines:,}",
        f"Document words (including log metadata): {total_words:,}",
        "Per-tag counts below include player-written RP payloads only; join/leave events and name prefixes are excluded.",
    ]
    for tag in sorted(tags):
        stats = _authoritative_nation_rp_stats(log_text, tag)
        lines.append(
            f"Tag {tag}: EXACT RP messages/lines = {stats['rp_lines']:,}; "
            f"EXACT RP words = {stats['rp_words']:,}"
        )
    return "\n".join(lines)


def _enforce_authoritative_ai_counts(report: str, log_text: str) -> str:
    """Correct Gemini's numeric claims and append a deterministic count to every tagged block."""
    if not report:
        return report
    pieces = report.split("🔹")
    corrected = [pieces[0]]
    for raw_block in pieces[1:]:
        tag_match = re.search(r"\[\s*([A-Z]{3}|D\d{2})\s*\]", raw_block, re.IGNORECASE)
        if not tag_match:
            corrected.append("🔹" + raw_block)
            continue
        tag = tag_match.group(1).upper()
        stats = _authoritative_nation_rp_stats(log_text, tag)
        line_count = f"{stats['rp_lines']:,}"
        word_count = f"{stats['rp_words']:,}"
        block = re.sub(
            r"\b[\d,]+\s+(?:RP\s+)?(?:messages(?:/lines)?|lines)\b",
            f"{line_count} RP messages/lines",
            raw_block,
            flags=re.IGNORECASE,
        )
        block = re.sub(
            r"\b[\d,]+\s+(?:RP\s+)?words\b",
            f"{word_count} RP words",
            block,
            flags=re.IGNORECASE,
        )
        authoritative_line = (
            f"\n**Authoritative Count:** {line_count} RP messages/lines · "
            f"{word_count} RP words."
        )
        if "**Authoritative Count:**" not in block:
            snippet_pos = block.find("**RP Snippets:**")
            if snippet_pos >= 0:
                block = block[:snippet_pos].rstrip() + authoritative_line + "\n" + block[snippet_pos:]
            else:
                block = block.rstrip() + authoritative_line + "\n"
        corrected.append("🔹" + block)
    return "".join(corrected)


def _analysis_block_matches(block: str, lookup_terms: set[str], target_uids: list, target_tag: str) -> bool:
    """Flexible matcher for AI player blocks (brackets optional, tags, mentions)."""
    if not block or not block.strip():
        return False
    upper = block.upper()
    tag = (target_tag or "").upper()
    if tag:
        patterns = (
            f"[{tag}]",
            f"**{tag}**",
            f"{tag} -",
            f"{tag} –",
            f"{tag}—",
            f"{tag} |",
            f"{tag}:",
        )
        if any(p.upper() in upper for p in patterns):
            return True
        # Lone tag token at start after cleaning markdown
        stripped = upper.lstrip("*# ").strip()
        if stripped.startswith(tag) and (len(stripped) == len(tag) or not stripped[len(tag)].isalnum()):
            return True
    for term in lookup_terms:
        t = (term or "").strip()
        if not t:
            continue
        tu = t.upper()
        if f"[{tu}]" in upper:
            return True
        if len(tu) >= 4 and tu in upper:
            return True
    for uid in target_uids:
        if f"<@{uid}>" in block:
            return True
    return False


async def _find_game_for_commend(thread_ref) -> tuple[str | None, dict]:
    games = await read_json(GAMES_FILE)
    key, game = _find_game_entry(games, thread_ref)
    return key, game or {}


# ==========================================================================
# AI CHAT-LOG GRADING — strict (October 2026; docs/ai-log-analysis.md)
# --------------------------------------------------------------------------
# Hosts said nearly everyone got 2–3 Merit. Now the AI only judges QUALITY
# (how much of a nation's text is real in-character RP, creativity,
# toxicity, low effort) and the bot applies the reward rules below to its own
# exact word counts — the AI can't be generous. Merit is only recommended on
# servers that use it (server settings → Features → Hearts of Valor & Merit).
# ==========================================================================
AI_GRADING_VERSION = 2
AI_COMMEND_TIERS = ((3000, 3), (1500, 2), (750, 1))  # in-character words → commends
AI_MERIT_TIERS = ((500, 4), (350, 3), (200, 2))      # in-character words → Merit points
AI_COMMEND_MIN_CREATIVITY = 7
AI_MERIT_MIN_CREATIVITY = 6
AI_TOXIC_FROM = 4                                    # toxicity at or above this: nothing
AI_NO_RP_WORDS = 20                                  # fewer RP words than this: "0 RP"


def _ai_rules() -> dict:
    """The rules, as shown to hosts on the Games page."""
    return {
        "commend_tiers": [[words, count] for words, count in AI_COMMEND_TIERS],
        "merit_tiers": [[words, count] for words, count in AI_MERIT_TIERS],
        "commend_min_creativity": AI_COMMEND_MIN_CREATIVITY,
        "merit_min_creativity": AI_MERIT_MIN_CREATIVITY,
        "toxic_from": AI_TOXIC_FROM,
    }


def _merit_enabled() -> bool:
    """This server hands out Merit (server settings → Features)."""
    return bool(SERVER_FEATURES.get("valor_merit", True))


def _ai_number(value, low: float, high: float, default: float) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    if number != number:
        return default
    return max(low, min(high, number))


def _ai_reward(meaningful_words: int, creativity: int, toxicity: int, low_effort: bool, merit_enabled: bool) -> dict:
    """The strict reward rules (deterministic): {"commends", "merit", "why"}."""
    def nothing(why: str) -> dict:
        return {"commends": 0, "merit": 0, "why": why}

    if toxicity >= AI_TOXIC_FROM:
        return nothing(f"Toxicity {toxicity}/10 — no reward.")
    if low_effort:
        return nothing("Mostly one-liners, spam or out-of-character chat — no reward.")
    if creativity >= AI_COMMEND_MIN_CREATIVITY:
        for words, count in AI_COMMEND_TIERS:
            if meaningful_words >= words:
                return {"commends": count, "merit": 0,
                        "why": f"{meaningful_words:,} words of in-character RP, creativity {creativity}/10."}
    if merit_enabled and creativity >= AI_MERIT_MIN_CREATIVITY:
        for words, count in AI_MERIT_TIERS:
            if meaningful_words >= words:
                return {"commends": 0, "merit": count,
                        "why": f"{meaningful_words:,} words of in-character RP, creativity {creativity}/10."}
    lowest = AI_MERIT_TIERS[-1][0] if merit_enabled else AI_COMMEND_TIERS[-1][0]
    if meaningful_words < lowest:
        target = "Merit" if merit_enabled else "a commend"
        return nothing(f"{meaningful_words:,} words of in-character RP — {lowest:,} are needed for {target}.")
    if merit_enabled:
        return nothing(f"Creativity {creativity}/10 — Merit needs {AI_MERIT_MIN_CREATIVITY}/10.")
    return nothing(f"Creativity {creativity}/10 — a commend needs {AI_COMMEND_MIN_CREATIVITY}/10 (Merit is off on this server).")


def _ai_log_tags(log_text: str) -> set[str]:
    """Country tags that wrote something in the log."""
    tags = set(_extract_tags_from_chat_log(log_text))
    for raw_line in log_text.splitlines():
        stripped = raw_line.strip()
        match = re.match(r"^([A-Z]{3}|D\d{2})[A-Za-z0-9_-]*(?::|\s)", stripped) or \
            re.search(r"\(([A-Z]{3}|D\d{2})[A-Za-z0-9_-]*\):", stripped)
        if match:
            tags.add(match.group(1).upper())
    return {tag for tag in tags if tag in HOI4_TAGS or re.fullmatch(r"D\d{2}", tag)}


def _ai_player_slots(log_text: str, reservations: dict | None, guild=None) -> list[dict]:
    """Who to grade: every reserved player (fillers aside), plus nations that
    roleplayed in the log without a reservation."""
    slots, reserved_tags = [], set()
    for nation, uid in (reservations or {}).items():
        if str(nation).startswith("_FILL_"):
            continue
        base = str(nation).split("_coop", 1)[0].strip()
        tag = _hoi4_tag_for_nation(base)
        if not tag:
            continue
        member = None
        try:
            if guild is not None and str(uid).isdigit():
                member = guild.get_member(int(uid))
        except Exception:
            member = None
        slots.append({
            "tag": tag, "nation": base, "user_id": str(uid),
            "role": "COOP" if "_coop" in str(nation) else "MAIN",
            "name": _discord_handle(member) if member is not None else None,
        })
        reserved_tags.add(tag)
    for tag in sorted(_ai_log_tags(log_text) - reserved_tags):
        if _authoritative_nation_rp_stats(log_text, tag)["rp_lines"] > 0:
            slots.append({"tag": tag, "nation": HOI4_TAGS.get(tag, tag), "user_id": None, "role": "UNRESERVED", "name": None})
    return slots


def _ai_grading_prompt(log_text: str, slots: list[dict], stats: dict) -> str:
    roster = "\n".join(
        f"- tag {slot['tag']} | {slot['nation']} | {slot['role']} | user_id {slot['user_id'] or 'none'}"
        f"{' | ' + slot['name'] if slot.get('name') else ''} | RP lines {stats[slot['tag']]['rp_lines']} | "
        f"RP words {stats[slot['tag']]['rp_words']}"
        for slot in slots
    )
    return f"""You grade the roleplay (RP) of each player in a Hearts of Iron IV multiplayer chat log.
Be strict: rewards are for standout roleplay, not for taking part.

Return ONLY JSON in exactly this shape:
{{"players": [{{"tag": "SOV", "user_id": "123" or null, "in_character_share": 0.0, "share_of_tag": 1.0,
  "creativity": 0, "toxicity": 0, "low_effort": false, "left_early": false,
  "summary": "one short sentence", "snippets": ["a line copied exactly from the log"]}}]}}

Rules:
- One entry for EVERY row of the roster below, with the same tag and user_id.
- Lines start with the country tag fused to the in-game name (e.g. `SOVNikoloza:`). The tag is the nation.
- in_character_share (0-1): the part of that tag's words that is real in-character roleplay — diplomacy,
  speeches, news, story, characters. Out-of-character chat does NOT count: lag, pauses, "gg", game mechanics,
  coordinating moves, jokes about the game, arguing with players.
- share_of_tag (0-1): when several players share a tag (MAIN + COOP), how much of the tag's in-character RP
  this player wrote (they add up to 1). Otherwise 1.
- creativity (0-10, strict): 3 = bare minimum, 5 = ordinary, 7 = clearly good and original, 9-10 = exceptional.
  Generic, copy-pasted or repetitive text scores low. Alternate history and fiction are fine.
- toxicity (0-10): insults, harassment, slurs, rule-breaking.
- low_effort: true when the RP is mostly short one-liners, spam or filler.
- left_early: true when the player clearly left long before the end.
- snippets: 1-3 representative lines copied exactly from the log (empty for players with no RP).
- Do NOT count words or recommend rewards — the bot does that from your scores and its own counts.
- Read the whole log, to the END marker.

Country tags: {TAGS_PROMPT_STRING}

--- ROSTER (counts computed by the bot) ---
{roster}

--- COMPLETE CHAT LOG: BEGIN ---
{log_text}
--- END OF COMPLETE CHAT LOG ---
"""


def _parse_ai_json(text: str):
    """The AI's JSON (tolerates code fences / extra text). None when unreadable."""
    raw = (text or "").strip()
    raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw)
    try:
        return json.loads(raw)
    except Exception:
        pass
    start, end = raw.find("{"), raw.rfind("}")
    if start >= 0 and end > start:
        try:
            return json.loads(raw[start:end + 1])
        except Exception:
            return None
    return None


async def _gemini_json(prompt: str) -> str:
    """Ask Gemini for JSON (retries while it's overloaded). Raises on failure."""
    last = None
    for attempt in range(3):
        try:
            response = await client.aio.models.generate_content(
                model=GEMINI_MODEL, contents=prompt, config={"response_mime_type": "application/json"},
            )
            return response.text or ""
        except Exception as e:
            last = e
            text = str(e).lower()
            if attempt < 2 and ("503" in text or "unavailable" in text or "overloaded" in text):
                await asyncio.sleep(2.0 * (2 ** attempt))
                continue
            raise
    raise last


def _ai_assemble(slots: list[dict], stats: dict, ai_players: list, merit_enabled: bool) -> list[dict]:
    """Combine the AI's quality scores with the bot's counts and rules."""
    entries = [p for p in (ai_players or []) if isinstance(p, dict)]
    by_key = {(str(p.get("tag") or "").upper(), str(p.get("user_id") or "")): p for p in entries}
    by_tag: dict[str, list] = {}
    for p in entries:
        by_tag.setdefault(str(p.get("tag") or "").upper(), []).append(p)
    per_tag = collections.Counter(slot["tag"] for slot in slots)
    out = []
    for slot in slots:
        tag = slot["tag"]
        count = per_tag[tag]
        ai = by_key.get((tag, str(slot["user_id"] or "")))
        if ai is None and count == 1 and by_tag.get(tag):
            ai = by_tag[tag][0]
        st = stats[tag]
        words = int(st["rp_words"])
        share = _ai_number((ai or {}).get("share_of_tag"), 0, 1, 1 / count) if count > 1 else 1.0
        in_character = _ai_number((ai or {}).get("in_character_share"), 0, 1, 0.0)
        creativity = int(round(_ai_number((ai or {}).get("creativity"), 0, 10, 0)))
        toxicity = int(round(_ai_number((ai or {}).get("toxicity"), 0, 10, 0)))
        low_effort = bool((ai or {}).get("low_effort"))
        meaningful = int(round(words * in_character * share))
        if words < AI_NO_RP_WORDS:
            reward, status = {"commends": 0, "merit": 0, "why": "No real roleplay in the log."}, "no_rp"
        elif ai is None:
            reward, status = {"commends": 0, "merit": 0, "why": "The AI didn't grade this player — a host can review the log."}, "ungraded"
        else:
            reward = _ai_reward(meaningful, creativity, toxicity, low_effort, merit_enabled)
            status = (
                "toxic" if toxicity >= AI_TOXIC_FROM
                else "rewarded" if (reward["commends"] or reward["merit"])
                else "minimal"
            )
        snippets = (ai or {}).get("snippets") if isinstance((ai or {}).get("snippets"), list) else []
        out.append({
            **slot,
            "lines": int(st["rp_lines"]),
            "words": words,
            "meaningful_words": meaningful,
            "in_character_share": round(in_character, 2),
            "creativity": creativity,
            "toxicity": toxicity,
            "low_effort": low_effort,
            "left_early": bool((ai or {}).get("left_early")),
            "graded": ai is not None,
            "summary": str((ai or {}).get("summary") or "")[:300],
            "snippets": [str(line)[:300] for line in snippets[:3]],
            "reward": reward,
            "status": status,
        })
    return out


async def run_ai_log_analysis(log_text: str, reservations: dict | None, guild=None, *,
                              merit_enabled: bool | None = None, slots: list | None = None):
    """Grade a chat log. Returns the analysis dict, or an error message (str)."""
    if not client:
        return "❌ AI is not configured. Missing GENAI_API_KEY."
    if not (log_text or "").strip():
        return "❌ The chat log is empty."
    merit = _merit_enabled() if merit_enabled is None else bool(merit_enabled)
    slots = slots if slots is not None else _ai_player_slots(log_text, reservations, guild)
    if not slots:
        return "❌ Couldn't find any players in the log or the reservations."
    stats = {tag: _authoritative_nation_rp_stats(log_text, tag) for tag in {slot["tag"] for slot in slots}}
    try:
        raw = await _gemini_json(_ai_grading_prompt(log_text, slots, stats))
    except Exception as e:
        print(f"Gemini API Error: {e}")
        return f"❌ The AI couldn't analyze the log: {e}"
    data = _parse_ai_json(raw)
    if not isinstance(data, dict) or not isinstance(data.get("players"), list):
        return "❌ The AI's answer couldn't be read — try again."
    return {
        "version": AI_GRADING_VERSION,
        "at": int(time.time()),
        "merit_enabled": merit,
        "rules": _ai_rules(),
        "players": _ai_assemble(slots, stats, data["players"], merit),
    }


def _ai_identity(player: dict) -> str:
    if player.get("user_id"):
        who = f"<@{player['user_id']}>" + (f" ({player['name']})" if player.get("name") else "")
    else:
        who = player.get("name") or "(Unreserved)"
    return f"**[{player['tag']}] - {who}**"


def _render_ai_block(player: dict) -> str:
    reward = player["reward"]
    if reward["commends"]:
        verdict = f"Worth {reward['commends']} commend(s)"
    elif reward["merit"]:
        verdict = f"Worth {reward['merit']} merit point(s)"
    elif player["status"] in ("no_rp", "toxic"):
        verdict = "Status: " + ("0 RP" if player["status"] == "no_rp" else "Toxic")
    else:
        verdict = "No reward"
    left = " Left early." if player.get("left_early") else ""
    text = (
        f"🔹 {_ai_identity(player)} — {verdict}. {reward['why']}{left} "
        f"{player.get('summary') or ''}\n"
        f"**Authoritative Count:** {player['lines']:,} RP messages/lines · {player['words']:,} RP words "
        f"({player['meaningful_words']:,} in character).\n"
        f"Internal Score: Creativity {player['creativity']}/10, Toxicity {player['toxicity']}/10."
    )
    if player.get("snippets"):
        text += "\n**RP Snippets:**\n" + "\n".join(f"> {line}" for line in player["snippets"])
    return text


def _render_ai_analysis_text(analysis: dict) -> str:
    """The analysis as Discord text (legacy archive buttons, /run_ai_analysis)."""
    players = analysis.get("players") or []
    sections = [
        ("### 🌟 COMMENDATION RECOMMENDATIONS", [p for p in players if p["reward"]["commends"]]),
        ("### 💠 MERIT RECOMMENDATIONS", [p for p in players if p["reward"]["merit"]]),
        ("### 📊 NO REWARD", [p for p in players if p["status"] in ("minimal", "ungraded")]),
        ("### ⚠️ 0 RP / TOXIC", [p for p in players if p["status"] in ("no_rp", "toxic")]),
    ]
    rules = "Strict rules: 750+ in-character words and creativity 7/10 for a commend"
    rules += "; 200+ words and creativity 6/10 for Merit." if analysis.get("merit_enabled") else " (Merit is off on this server)."
    parts = [f"*{rules}*"]
    for title, group in sections:
        parts.append(title)
        parts.append("\n\n".join(_render_ai_block(p) for p in group) if group else "None detected.")
    return "\n\n".join(parts)


async def analyze_single_nation_rp_fallback(
    extracted_lines: list[str],
    tag: str,
    nation: str,
    player_label: str,
) -> str:
    """On-demand grading of one nation (an old archive post's "Request Commend")."""
    body = "\n".join(extracted_lines)
    slot = {"tag": tag, "nation": nation, "user_id": None, "role": "MAIN", "name": player_label}
    analysis = await run_ai_log_analysis(body, None, None, slots=[slot])
    if isinstance(analysis, str):
        return analysis.replace("❌", "❌ Fallback AI scan failed:", 1) if analysis.startswith("❌") else analysis
    return _render_ai_block(analysis["players"][0])


# PLAYER COMMENDATION CHECKER (UPDATED WITH FOOLPROOF ANCHOR EMOJI LOOKUP)
class CommendModal(discord.ui.Modal, title="Check Commendation Eligibility"):
    player_id = discord.ui.TextInput(
        label="Nation You Played",
        placeholder="Enter the nation or country name you played (e.g. Italy, GER)...",
        required=True,
        max_length=50
    )

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        search_term = self.player_id.value.strip()

        if not interaction.message.attachments:
            return await interaction.followup.send("❌ Could not find the chat log attachment.", ephemeral=True)

        attachment = interaction.message.attachments[0]
        try:
            raw_bytes = await attachment.read()
            chat_log_text = raw_bytes.decode('utf-8', errors='ignore')
        except Exception as e:
            return await interaction.followup.send(f"❌ Error reading the log file: {e}", ephemeral=True)

        target_tag, nation_name = _resolve_nation_tag(search_term)

        extracted_lines = _extract_nation_log_lines(chat_log_text, target_tag)

        # Soft fallback: nation name appears in free text even if tag lines are odd.
        if not extracted_lines and nation_name:
            needle = nation_name.lower()
            extracted_lines = [ln for ln in chat_log_text.splitlines() if needle in ln.lower()]

        if not extracted_lines:
            return await interaction.followup.send(
                f"⚠️ I re-scanned the `.txt` and still couldn't find lines for `{target_tag}` / **{nation_name}**. "
                "Double-check the nation spelling, or open a ticket for a host review.",
                ephemeral=True
            )

        status = await interaction.followup.send("🤖 AI is initializing log sequence...", ephemeral=True)

        player_label = _discord_handle(interaction.user)
        try:
            player_log_full = "\n".join(extracted_lines)
            dm_file = discord.File(fp=io.BytesIO(player_log_full.encode()), filename=f"logs_{target_tag}.txt")
            await interaction.user.send(
                content=(
                    f"📑 **Official Log Extraction for Nation `{self.player_id.value}` "
                    f"(Tag: `{target_tag}`)**\nAttached are your direct RP messages from the session:"
                ),
                file=dm_file
            )
        except discord.Forbidden:
            pass

        await asyncio.sleep(1.5)
        await interaction.followup.edit_message(message_id=status.id, content="🤖 Analyzing RP depth, grammar, and timestamps...")
        await asyncio.sleep(1.0)

        thread_id = None
        match = re.search(r"<#(\d+)>", interaction.message.content or "")
        if match:
            thread_id = int(match.group(1))
        # Prefer explicit Game-ID field if present in newer archive posts.
        gid_match = re.search(r"Game[- ]?ID[:\s*`]*(\d+)", interaction.message.content or "", re.I)
        if gid_match:
            thread_id = int(gid_match.group(1))

        found_analysis_blocks = []
        disclaimer = "\n\n⚠️ *If you find my judgement incomplete, please open a ticket and request host to review my case.*"

        lookup_terms = {search_term.lower(), nation_name.lower(), target_tag.lower()}
        for tag, country in HOI4_TAGS.items():
            if country.lower() == nation_name.lower() or tag.lower() == target_tag.lower():
                lookup_terms.add(tag.lower())
                lookup_terms.add(country.lower())

        game_key = None
        game = {}
        target_uids = []
        if thread_id:
            try:
                game_key, game = await _find_game_for_commend(thread_id)
                reservations = game.get("reservations", {}) or {}
                for nation, uid in reservations.items():
                    base = nation.replace("_coop", "").replace("_FILL_", "")
                    if any(term in base.lower() or term in str(uid) for term in lookup_terms):
                        target_uids.append(uid)
                    # Self-request: also match the requester's reserved nation(s).
                    if str(uid) == str(interaction.user.id):
                        target_uids.append(uid)
                        lookup_terms.add(base.lower())
                        t = _hoi4_tag_for_nation(base)
                        if t:
                            lookup_terms.add(t.lower())

                # 1) Prefer the persisted master analysis (survives channel permissions).
                stored = (game.get("ai_analysis_text") or "").strip()
                if stored:
                    for block in stored.split("🔹"):
                        if not block.strip() or "COMMENDATION RECOMMENDATIONS" in block:
                            continue
                        clean_block = block.split("###")[0].strip()
                        if _analysis_block_matches(clean_block, lookup_terms, target_uids, target_tag):
                            found_analysis_blocks.append("🔹 " + clean_block)

                # 2) Also scan host-panel / lobby history as bot (fallback).
                if not found_analysis_blocks:
                    channel_ids = []
                    for cid in (
                        game.get("host_panel_thread_id"),
                        game.get("thread_id"),
                        game.get("lobby_thread_id"),
                        game.get("original_thread_id"),
                        thread_id,
                    ):
                        if cid and int(cid) not in channel_ids:
                            channel_ids.append(int(cid))
                    full_ai_text = ""
                    for cid in channel_ids:
                        try:
                            ch = interaction.guild.get_channel(cid) or await interaction.guild.fetch_channel(cid)
                        except Exception:
                            continue
                        try:
                            async for msg in ch.history(limit=80):
                                if msg.author.id != interaction.client.user.id:
                                    continue
                                if ("🤖 **AI Post-Game Performance Analysis**" in (msg.content or "")
                                        or "Internal Score:" in (msg.content or "")):
                                    full_ai_text = (msg.content or "") + "\n" + full_ai_text
                        except Exception as hist_err:
                            print(f"Commend history read failed for {cid}: {hist_err}")
                    if full_ai_text:
                        for block in full_ai_text.split("🔹"):
                            if not block.strip() or "COMMENDATION RECOMMENDATIONS" in block:
                                continue
                            clean_block = block.split("###")[0].strip()
                            if _analysis_block_matches(clean_block, lookup_terms, target_uids, target_tag):
                                found_analysis_blocks.append("🔹 " + clean_block)
            except Exception as e:
                print(f"Lookup Error: {e}")

        # 3) Safe fallback: country is in the .txt but missing from master AI report → re-scan.
        if not found_analysis_blocks:
            await interaction.followup.edit_message(
                message_id=status.id,
                content=f"🤖 `{target_tag}` wasn't in the master report — re-scanning your `.txt` lines with AI..."
            )
            fallback = await analyze_single_nation_rp_fallback(
                extracted_lines, target_tag, nation_name, f"<@{interaction.user.id}> ({player_label})"
            )
            if fallback and not fallback.startswith("❌"):
                found_analysis_blocks.append(fallback)

        if found_analysis_blocks:
            results_text = "\n\n".join(found_analysis_blocks)
            joined = "\n".join(found_analysis_blocks).lower()
            has_commend = bool(re.search(r"worth\s+(?:[1-3]|\[[xX]\])\s+commend", joined))
            merit_match = re.search(r"worth\s+([234])\s+merit point", joined)

            if has_commend:
                msg = (
                    f"🎉 **AI deemed this Commend Worthy!**\n\n{results_text}\n\n"
                    f"👉 **Please open a ticket and tell the host the AI approved you!**" + disclaimer
                )
            elif merit_match:
                msg = (
                    f"💠 **AI recommends {merit_match.group(1)} Merit Points!**\n\n{results_text}\n\n"
                    f"👉 **Please open a ticket and show the host this recommendation.**" + disclaimer
                )
            else:
                msg = f"❌ **AI did not recommend a commendation or merit award.**\n\n{results_text}" + disclaimer

            return await interaction.followup.edit_message(message_id=status.id, content=msg[:2000])

        msg = (
            "⚠️ **AI Cannot Conclude.** I found your country in the `.txt`, but could not grade it "
            "(master scan missing / AI error). Please ask the host to click **Run AI Analysis**, "
            "or open a ticket."
        )
        return await interaction.followup.edit_message(message_id=status.id, content=msg)


