# AI LOG SCANNER FUNCTION (UPDATED WITH ANCHOR EMOJIS)

_HOI4_LOG_TAG_JOIN = re.compile(
    r'(?:^|[\s\[])([A-Z]{3})[A-Za-z0-9_\-]*\]?\s+(?:has\s+)?(?:joined|connected|reconnected)\b',
    re.MULTILINE | re.IGNORECASE,
)
_HOI4_LOG_TAG_ACTIVITY = re.compile(
    r'(?:^|[\s\[])([A-Z]{3})[A-Za-z0-9_\-]*\]?\s+(?:has\s+)?(?:left|disconnected|quit)\b',
    re.MULTILINE | re.IGNORECASE,
)


def _extract_tags_from_chat_log(log_text: str) -> set[str]:
    """Detect HOI4 country tags from join/leave lines (e.g. MEXNoah joined)."""
    found: set[str] = set()
    if not log_text:
        return found
    valid = set(HOI4_TAGS.keys())
    for pattern in (_HOI4_LOG_TAG_JOIN, _HOI4_LOG_TAG_ACTIVITY):
        for match in pattern.finditer(log_text):
            tag = match.group(1).upper()
            if tag in valid:
                found.add(tag)
    return found


def _nations_missing_attendance_but_in_log(game: dict, log_text: str) -> list[dict]:
    """Reserved players whose country tag appears in logs but who failed the snapshot threshold."""
    present = _normalize_uid_set(game.get("present_ids", []))
    dropped = _normalize_uid_set(game.get("dropped_out", []))
    hit_counts = game.get("presence_hit_counts", {}) or {}
    reservations = game.get("reservations", {}) or {}
    log_tags = _extract_tags_from_chat_log(log_text)
    flagged = []
    for nation, uid in reservations.items():
        if nation.startswith("_FILL_"):
            continue
        try:
            uid_int = int(uid)
        except (TypeError, ValueError):
            continue
        if uid_int in dropped or uid_int in present:
            continue
        base = nation.replace("_FILL_", "").split("_coop", 1)[0]
        tag = _hoi4_tag_for_nation(base)
        if not tag or tag not in log_tags:
            continue
        hits = int(hit_counts.get(str(uid_int), 0))
        flagged.append({
            "nation": base,
            "reservation_key": nation,
            "tag": tag,
            "user_id": uid_int,
            "hits": hits,
        })
    return flagged


class AttendanceLogConfirmView(discord.ui.View):
    """Host-only Yes/No when chat-log tags suggest a player was present but snapshots disagree."""

    def __init__(
        self, game_id: str, user_id: int, nation: str, tag: str, host_id: int,
        reservation_key: str | None = None,
    ):
        super().__init__(timeout=3600)
        self.game_id = str(game_id)
        self.user_id = int(user_id)
        self.nation = nation
        self.tag = tag
        self.host_id = int(host_id)
        self.reservation_key = reservation_key or nation

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.host_id:
            await interaction.response.send_message("❌ Only the host can answer this.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Yes, Log Them", style=discord.ButtonStyle.success, emoji="✅")
    async def yes_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        games_data = await read_json(GAMES_FILE)
        game = games_data.get(self.game_id)
        if not game:
            return await interaction.response.send_message("❌ Game data not found.", ephemeral=True)
        present = _normalize_uid_set(game.get("present_ids", []))
        if self.user_id not in present:
            present.append(self.user_id)
        game["present_ids"] = sorted(set(present))
        stats_data = await read_json(PLAYER_STATS_FILE)
        stats = stats_data.setdefault(str(self.user_id), {"history": [], "total_games": 0})
        context = get_mod_context(game.get("mode")) or get_mod_context("Roleplay")
        warn_key = context["key_warn"]
        commend_key = context["key_commend"]
        applied = int((game.get("applied_warns") or {}).pop(str(self.user_id), 0))
        spent = int((game.get("spent_commends") or {}).pop(str(self.user_id), 0))
        if applied:
            stats[warn_key] = max(0, stats.get(warn_key, 0) - applied)
            if self.user_id in game.get("game_warns", []):
                game["game_warns"].remove(self.user_id)
        if spent:
            stats[commend_key] = stats.get(commend_key, 0) + spent
        already_logged = any(
            h.get("game_id") == self.game_id for h in stats.get("history", [])
            if isinstance(h, dict)
        )
        if not already_logged:
            stats["total_games"] = stats.get("total_games", 0) + 1
            stats.setdefault("history", []).append({
                "date": datetime.datetime.now().strftime("%Y-%m-%d"),
                "nation": self.reservation_key,
                "mode": game.get("mode"),
                "participated": True,
                "game_id": self.game_id,
            })
        await write_json(PLAYER_STATS_FILE, stats_data)
        await _refresh_player_stats_cache()
        games_data[self.game_id] = game
        await write_json(GAMES_FILE, games_data)
        try:
            schedule_log_update(int(self.game_id))
        except Exception:
            pass
        for child in self.children:
            child.disabled = True
        await interaction.response.edit_message(
            content=(
                f"✅ **{self.tag}** ({self.nation}) — <@{self.user_id}> has been marked **present** "
                f"based on chat-log evidence."
            ),
            view=self,
        )

    @discord.ui.button(label="No, Keep Absent", style=discord.ButtonStyle.danger, emoji="❌")
    async def no_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        for child in self.children:
            child.disabled = True
        await interaction.response.edit_message(
            content=(
                f"❌ **{self.tag}** ({self.nation}) — <@{self.user_id}> remains marked **absent**."
            ),
            view=self,
        )


async def _post_attendance_log_mismatch_review(channel, game: dict, log_text: str, host_id: int):
    """After AI analysis, flag nations seen in chat logs but missing from snapshot attendance."""
    flagged = _nations_missing_attendance_but_in_log(game, log_text)
    if not flagged:
        return
    game_id = str(game.get("thread_id") or channel.id)
    if ATTENDANCE_WEB_ONLY:
        # Shown on the web Attendance page as "chat log says they played"
        # hints the host can accept (marks them present) or ignore.
        stable_id = _attendance_stable_id(game, game_id)
        games = await _load_games_resilient()
        key, fresh = _find_game_entry(games, stable_id)
        if fresh:
            existing = {str(s.get("user_id")) for s in (fresh.get("attendance_log_suggestions") or [])}
            suggestions = list(fresh.get("attendance_log_suggestions") or [])
            for entry in flagged:
                if str(entry["user_id"]) in existing:
                    continue
                suggestions.append({
                    "user_id": str(entry["user_id"]), "nation": entry["nation"], "tag": entry["tag"],
                    "hits": entry["hits"], "ts": int(time.time()),
                })
                record_attendance_event(stable_id, "chatlog_hint", user_id=entry["user_id"],
                                        details={"tag": entry["tag"], "nation": entry["nation"], "hits": entry["hits"]})
            fresh["attendance_log_suggestions"] = suggestions
            await save_single_game(key or stable_id, fresh, rewrite_reservations=False)
        view = discord.ui.View()
        view.add_item(discord.ui.Button(label="Review on the web", emoji="📡", style=discord.ButtonStyle.link,
                                        url=_attendance_page_url(stable_id)))
        try:
            await channel.send(
                f"🕵️ <@{host_id}> The chat log suggests **{len(flagged)}** player(s) played but weren't counted "
                f"present. Review them on the Attendance page.",
                view=view,
            )
        except Exception as e:
            print(f"[WARN] Attendance log hint post failed: {e}")
        return
    for entry in flagged:
        content = (
            f"🕵️ **Country-Tag vs. Attendance Mismatch** — <@{host_id}>\n"
            f"Someone with country tag **{entry['tag']}** ({entry['nation']}) was present "
            f"in the chat log (e.g. `{entry['tag']}… joined`), but <@{entry['user_id']}> only "
            f"met **{entry['hits']}/{ATTENDANCE_SAMPLE_COUNT}** attendance snapshot(s) "
            f"(need **{ATTENDANCE_REQUIRED_PRESENT}+**) — so they **didn't meet the requirements "
            f"to be counted as participated**.\n\n"
            f"If this looks like a bot error, should I manually mark <@{entry['user_id']}> as logged present?"
        )
        view = AttendanceLogConfirmView(
            game_id, entry["user_id"], entry["nation"], entry["tag"], host_id,
            entry.get("reservation_key"),
        )
        try:
            await channel.send(content, view=view)
        except Exception as e:
            print(f"[WARN] Attendance log mismatch review failed: {e}")


async def analyze_rp_log_with_gemini(log_text: str, reservations: dict = None, guild=None) -> str:
    """The analysis as Discord text (strict rules; see run_ai_log_analysis)."""
    analysis = await run_ai_log_analysis(log_text, reservations, guild)
    return analysis if isinstance(analysis, str) else _render_ai_analysis_text(analysis)


# MASTER HOST CONTROL CENTER
def _attachment_looks_like_txt(attachment) -> bool:
    """True for HOI4 chat-log style uploads (.txt / text plain), case-insensitive."""
    name = (getattr(attachment, "filename", None) or "").strip().lower()
    ctype = (getattr(attachment, "content_type", None) or "").strip().lower()
    if name.endswith(".txt"):
        return True
    if "text/plain" in ctype and not name.endswith((".png", ".jpg", ".jpeg", ".gif", ".webp", ".zip")):
        return True
    return False


async def _find_txt_log_attachment(*channels, history_limit: int = 150):
    """Scan one or more channels (newest first) for a .txt chat-log attachment.

    Returns (channel, attachment, raw_bytes, text, filename) or (None,)*5.
    Advanced Log Tracker / reminders often push the upload past the old 25-msg window.
    """
    seen_channel_ids = set()
    for channel in channels:
        if channel is None:
            continue
        cid = getattr(channel, "id", None)
        if cid is not None and cid in seen_channel_ids:
            continue
        if cid is not None:
            seen_channel_ids.add(cid)
        try:
            async for message in channel.history(limit=history_limit):
                for attachment in (message.attachments or []):
                    if not _attachment_looks_like_txt(attachment):
                        continue
                    try:
                        raw = await attachment.read()
                    except Exception as e:
                        print(f"[WARN] Could not read attachment {attachment.filename}: {e}")
                        continue
                    if not raw:
                        continue
                    text = raw.decode("utf-8", errors="ignore")
                    fname = attachment.filename or "chat_log.txt"
                    return channel, attachment, raw, text, fname
        except Exception as e:
            print(f"[WARN] history scan failed in #{getattr(channel, 'id', '?')}: {e}")
    return None, None, None, None, None


async def _resolve_game_log_channels(guild, game: dict, interaction_channel=None):
    """Preferred channel order when hunting for an uploaded chat log .txt."""
    channels = []
    if interaction_channel is not None:
        channels.append(interaction_channel)

    async def _add(raw_id):
        if not raw_id:
            return
        try:
            cid = int(raw_id)
        except (TypeError, ValueError):
            return
        ch = guild.get_channel(cid) if guild else None
        if ch is None and guild is not None:
            try:
                ch = await guild.fetch_channel(cid)
            except Exception:
                ch = None
        if ch is not None:
            channels.append(ch)

    if isinstance(game, dict):
        await _add(game.get("host_panel_thread_id"))
        await _add(game.get("thread_id"))
        await _add(game.get("lobby_thread_id"))
        await _add(game.get("original_thread_id"))
    return channels


class MasterHostPanel(discord.ui.View):
    def __init__(self, game_id: str, host_id: int, locked: bool = False):
        super().__init__(timeout=None)
        self.game_id = str(game_id)
        self.host_id = int(host_id)
        self.locked = bool(locked)
        # Explicitly set both states — leaving disabled unset has left stale
        # greyed buttons on some Discord clients after /game_end edits.
        for child in self.children:
            if isinstance(child, discord.ui.Button):
                child.disabled = self.locked
        # Attendance (present / absent / excused, samples, log) is managed on
        # the web Attendance page — always available, even before /game_end.
        self.add_item(discord.ui.Button(
            label="Attendance", emoji="📡", style=discord.ButtonStyle.link,
            url=_attendance_page_url(self.game_id), row=1,
        ))
        # Start / end / cancel live on the web Games page.
        self.add_item(discord.ui.Button(
            label="Game controls", emoji="🎮", style=discord.ButtonStyle.link,
            url=_game_control_url(self.game_id), row=1,
        ))

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.host_id:
            await interaction.response.send_message("❌ Only the assigned host can use these controls.", ephemeral=True)
            return False
        if self.locked:
            await interaction.response.send_message(
                "🔒 These controls unlock after you end the game on the website (Games page).", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Upload Chat Log", style=discord.ButtonStyle.secondary, emoji="📁", row=0)
    async def btn_upload(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_message(
            "📁 **How to upload:** Drag and drop your chat log `.txt` file into this thread! "
            "Once uploaded, click **Run AI Analysis**.", ephemeral=True
        )

    @discord.ui.button(label="Run AI Analysis", style=discord.ButtonStyle.primary, emoji="🤖", row=0)
    async def btn_ai(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer(ephemeral=True)
        await self.execute_analysis(interaction)

    async def execute_analysis(self, interaction: discord.Interaction, log_channel=None):
        """Core backend logic runner. Reusable by both buttons and standalone commands."""
        status = await interaction.followup.send("⏳ Scanning history for `.txt` log...", ephemeral=True)

        chat_log_text = None
        log_filename = "chat_log.txt"
        raw_file_bytes = None
        target_channel = log_channel or interaction.channel

        try:
            games_data = await read_json(GAMES_FILE)
            game = games_data.get(str(self.game_id), {})
            if not game:
                _, game = _find_game_entry(games_data, self.game_id)
                game = game or {}

            scan_channels = await _resolve_game_log_channels(
                interaction.guild, game, interaction_channel=interaction.channel
            )
            if log_channel is not None:
                scan_channels = [log_channel] + [c for c in scan_channels if c is not log_channel]

            found_channel, _att, raw_file_bytes, chat_log_text, log_filename = await _find_txt_log_attachment(
                *scan_channels, history_limit=150
            )
            if found_channel is not None:
                target_channel = found_channel

            if not chat_log_text:
                tried = ", ".join(f"<#{c.id}>" for c in scan_channels if c is not None) or "no channels"
                return await interaction.followup.edit_message(
                    message_id=status.id,
                    content=(
                        "❌ I couldn't find a `.txt` file in the recent history!\n"
                        f"Searched: {tried}\n"
                        "Upload the HOI4 chat log `.txt` into the **Host Control Center** thread, then try again."
                    ),
                )
            await interaction.followup.edit_message(message_id=status.id, content="🤖 Analyzing HOI4 RP Performance... This may take a moment.")

            games_data = await read_json(GAMES_FILE)
            game = games_data.get(str(self.game_id), {})
            if not game:
                _, game = _find_game_entry(games_data, self.game_id)
                game = game or {}
            reservations = game.get("reservations", {})

            analysis = await run_ai_log_analysis(chat_log_text, reservations, interaction.guild)
            ai_reply = analysis if isinstance(analysis, str) else _render_ai_analysis_text(analysis)

            # Persist full analysis so public "Request Commend" can look it up
            # without needing permission to read the private host panel.
            try:
                games_data = await read_json(GAMES_FILE)
                gkey, g = _find_game_entry(games_data, self.game_id)
                if g and gkey:
                    g["ai_analysis_text"] = ai_reply
                    g["ai_analysis_at"] = int(time.time())
                    if isinstance(analysis, dict):
                        analysis["by"] = str(interaction.user.id)
                        g["ai_analysis"] = analysis
                    games_data[gkey] = g
                    await write_json(GAMES_FILE, games_data)
                    game = g
            except Exception as persist_err:
                print(f"[WARN] Could not persist ai_analysis_text: {persist_err}")

            # --- SMART PARAGRAPH SPLITTER ---
            chunks = []
            current_chunk = ""
            for line in ai_reply.split('\n'):
                if len(current_chunk) + len(line) + 1 > 1900:
                    chunks.append(current_chunk)
                    current_chunk = line + "\n"
                else:
                    current_chunk += line + "\n"
            if current_chunk:
                chunks.append(current_chunk)

            await target_channel.send("🤖 **AI Post-Game Performance Analysis**")
            for chunk in chunks:
                await target_channel.send(chunk)

            mode = game.get("mode", "Roleplay")
            base_mode = game.get("base_mode", "Roleplay")

            mode_config = MODE_CONFIG.get(mode, {})
            public_archive_id = mode_config.get("public_log_channel_id")

            if not public_archive_id:
                public_archive_id = _public_log_channel_for_base(base_mode)

            if public_archive := interaction.guild.get_channel(public_archive_id):
                file_to_send = discord.File(fp=io.BytesIO(raw_file_bytes), filename=log_filename)

                lobby_ref = (
                    game.get("lobby_thread_id")
                    or game.get("original_thread_id")
                    or game.get("thread_id")
                    or target_channel.id
                )
                thread_mention = f"<#{lobby_ref}>"
                date_str = datetime.datetime.now().strftime('%m.%d.%Y')

                archive_content = (
                    f"📁 **Public Log Archive** | {mode}\n"
                    f"**Date:** {date_str} | **Host:** <@{self.host_id}>\n"
                    f"**Thread:** {thread_mention}\n"
                    f"**Game-ID:** `{self.game_id}`\n\n"
                    f"✨ *Your AI result for this game is on your profile: {_profile_url()}*"
                )
                archive_msg = await public_archive.send(
                    content=archive_content,
                    file=file_to_send,
                )

                # Forward the same archive post (log + commend buttons) into this thread.
                try:
                    forward_file = discord.File(fp=io.BytesIO(raw_file_bytes), filename=log_filename)
                    await target_channel.send(
                        content=archive_content,
                        file=forward_file,
                    )
                except Exception as e:
                    print(f"[WARN] Could not forward archive post into thread: {e}")

                notified = 0
                for user_id in set(reservations.values()):
                    try:
                        user_id = int(user_id)
                        user = interaction.guild.get_member(user_id) or await interaction.client.fetch_user(user_id)
                        await user.send(
                            f"📁 The chat logs for **{mode}** have been posted in <#{public_archive_id}>.\n\n"
                            f"Your AI result for this game is on your profile: {_profile_url()}\n"
                            f"Archive post: {archive_msg.jump_url}"
                        )
                        notified += 1
                    except Exception as e:
                        print(f"[WARN] Could not DM archive notice to {user_id}: {e}")

                await target_channel.send(f"📨 Archive notice sent to **{notified}** participants.")

            await _post_attendance_log_mismatch_review(
                target_channel, game, chat_log_text, self.host_id)

            if hasattr(target_channel, "name") and "monday" in target_channel.name.lower():
                if host_log_channel := interaction.guild.get_channel(G.HOST_LOG_CHANNEL_ID):
                    log_embed = discord.Embed(
                        title="📊 Monday Session Report",
                        description=ai_reply[:4000],
                        color=discord.Color.dark_gold()
                    )
                    log_embed.add_field(name="Session Thread", value=target_channel.mention)
                    log_embed.set_footer(text=f"Game ID: {self.game_id}")
                    await host_log_channel.send(embed=log_embed)

            await interaction.followup.edit_message(message_id=status.id, content="✅ Analysis successfully posted and `.txt` log forwarded to the archives.")

        except Exception as e:
            print(f"AI Error: {e}")
            await interaction.followup.send(f"❌ **AI Error:** {e}", ephemeral=True)


# SPECIAL AUTOCOMPLETE HELPER FOR MANUALLY PICKING GAMES




# SLASH COMMANDS (LOG FORWARDING & AI RUNNER)



# CORE FUNCTIONS
def _game_status_is_ended(game: dict | None) -> bool:
    if not isinstance(game, dict):
        return False
    return str(game.get("status") or "").strip().lower() == "ended"


HOST_FORUM_CHANNEL_ID = 0


# ==========================================================================
# POST-GAME SESSION FEEDBACK (1–5 star buttons)
# --------------------------------------------------------------------------
# Posted to the mode announcement channel at /game_end. Only players recorded
# in present_ids may vote.
# Votes persist on the game record (survives host-panel ID migration via
# feedback_source_id) and the public embed is edited live after every click.
# ==========================================================================
def _feedback_reserved_ids(game: dict) -> set[int]:
    """Unique Discord IDs that held any reservation slot (main / coop / filler)."""
    reservations = game.get("reservations") or {}
    if not isinstance(reservations, dict):
        return set()
    return _normalize_uid_set(list(reservations.values()))


def _feedback_participant_ids(game: dict) -> set[int]:
    """Authoritative participants recorded by attendance finalization."""
    return _normalize_uid_set(game.get("present_ids") or [])


def _feedback_eligible_ids(game: dict) -> set[int]:
    """Only logged-present players may vote."""
    return _feedback_participant_ids(game)


def _feedback_stats(ratings: dict) -> tuple[float | None, int]:
    """Return (average_or_None, vote_count) from {user_id: stars} map."""
    if not isinstance(ratings, dict) or not ratings:
        return None, 0
    scores = []
    for v in ratings.values():
        try:
            n = int(v)
        except (TypeError, ValueError):
            continue
        if 1 <= n <= 5:
            scores.append(n)
    if not scores:
        return None, 0
    return sum(scores) / len(scores), len(scores)


def _feedback_star_bar(avg: float | None) -> str:
    """Visual 5-star bar from the live average (half-stars rounded to nearest)."""
    if avg is None:
        return "☆☆☆☆☆"
    filled = max(0, min(5, int(round(avg))))
    return "★" * filled + "☆" * (5 - filled)


def build_feedback_embed(game: dict) -> discord.Embed:
    mode = game.get("mode") or "Game"
    thread_name = game.get("thread_name") or mode
    ratings = game.get("feedback_ratings") or {}
    avg, votes = _feedback_stats(ratings)
    participants = game.get("feedback_participants")
    reserved = game.get("feedback_reserved")
    participant_n = (
        len(participants)
        if isinstance(participants, list)
        else len(_feedback_participant_ids(game))
    )
    reserved_n = (
        len(reserved)
        if isinstance(reserved, list)
        else len(_feedback_reserved_ids(game))
    )

    embed = discord.Embed(
        title="⭐ Session Feedback",
        color=discord.Color.gold(),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.description = (
        f"**{thread_name}** has wrapped up.\n"
        f"How was your experience?\n\n"
        f"*Only players logged as participating in this session can vote — "
        f"one rating per player (you can change it anytime).*"
    )

    if avg is None:
        score_line = f"**— / 5** ⭐\n{_feedback_star_bar(None)}"
        footer_votes = "0 votes"
    else:
        score_line = f"**{avg:.1f} / 5** ⭐\n{_feedback_star_bar(avg)}"
        footer_votes = f"{votes} vote{'s' if votes != 1 else ''}"
    footer_votes += (
        f" · {participant_n} participant{'s' if participant_n != 1 else ''}"
        f" · {reserved_n} reserved player{'s' if reserved_n != 1 else ''}"
    )

    embed.add_field(name="Current Score", value=score_line, inline=False)
    embed.set_footer(text=footer_votes)
    return embed


def _find_game_for_feedback(games_data: dict, source_id: str):
    """Locate the game holding this feedback poll (survives panel ID migration)."""
    source_id = str(source_id)
    game = games_data.get(source_id)
    if game and isinstance(game, dict):
        return source_id, game
    for tid, g in (games_data or {}).items():
        if isinstance(g, dict) and str(g.get("feedback_source_id") or "") == source_id:
            return str(tid), g
    return None, None


class GameFeedbackButton(discord.ui.DynamicItem[discord.ui.Button],
                         template=r"feedback:rate:(?P<source>\d+):(?P<stars>[1-5])"):
    """Restart-proof 1–5 rating buttons for the post-game feedback embed."""

    def __init__(self, source_id: int, stars: int):
        self.source_id = int(source_id)
        self.stars = int(stars)
        button = discord.ui.Button(
            label=str(stars),
            emoji="⭐",
            style=discord.ButtonStyle.secondary,
            custom_id=f"feedback:rate:{source_id}:{stars}",
            row=0,
        )
        super().__init__(button)

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(int(match["source"]), int(match["stars"]))

    async def callback(self, interaction: discord.Interaction):
        await handle_game_feedback_vote(interaction, self.source_id, self.stars)


def build_game_feedback_view(source_id: int) -> discord.ui.View:
    view = discord.ui.View(timeout=None)
    for stars in range(1, 6):
        view.add_item(GameFeedbackButton(source_id, stars))
    return view


_feedback_vote_locks: dict[str, asyncio.Lock] = {}


async def handle_game_feedback_vote(interaction: discord.Interaction, source_id: int, stars: int):
    lock = _feedback_vote_locks.setdefault(str(source_id), asyncio.Lock())
    async with lock:
        await _handle_game_feedback_vote_locked(interaction, source_id, stars)


async def _handle_game_feedback_vote_locked(
    interaction: discord.Interaction, source_id: int, stars: int
):
    await interaction.response.defer(ephemeral=True)

    games_data = get_cached_games_data() or await read_json(GAMES_FILE)
    tid, game = _find_game_for_feedback(games_data, str(source_id))
    if not game:
        return await interaction.followup.send(
            "❌ This feedback poll is no longer available.", ephemeral=True)

    eligible = game.get("feedback_eligible")
    if isinstance(eligible, list):
        eligible_set = _normalize_uid_set(eligible)
    else:
        eligible_set = _feedback_eligible_ids(game)

    if interaction.user.id not in eligible_set:
        return await interaction.followup.send(
            "❌ Only players who were logged as participating in this game can submit a rating.",
            ephemeral=True,
        )

    ratings = dict(game.get("feedback_ratings") or {})
    prev = ratings.get(str(interaction.user.id))
    ratings[str(interaction.user.id)] = int(stars)
    game["feedback_ratings"] = ratings

    # +1 Merit Point the FIRST time a player rates this game (no farming on re-votes).
    merit_awarded = list(game.get("feedback_merit_awarded") or [])
    first_vote = str(interaction.user.id) not in merit_awarded

    # save_single_game already retries optimistic-lock races (1020) with
    # exponential backoff via _run_mysql_io; if the DB is still wedged after
    # all attempts, surface a friendly message instead of crashing the button.
    try:
        await save_single_game(tid, game, rewrite_reservations=False)
    except Exception as e:
        print(f"[ERROR] Feedback vote save failed for {interaction.user.id}: {e}")
        return await interaction.followup.send(
            "❌ Couldn't record your vote right now (database busy). Please try again in a few seconds.",
            ephemeral=True,
        )

    merit_note = ""
    if first_vote:
        try:
            res = await _apply_merit_change(
                interaction.user.id, FEEDBACK_VOTE_MERIT,
                reason="Feedback vote", guild=interaction.guild,
            )
            merit_note = f"\n🎖️ **+{FEEDBACK_VOTE_MERIT} Merit Point** (total: {res['new']})."
            merit_awarded.append(str(interaction.user.id))
            game["feedback_merit_awarded"] = merit_awarded
            await save_single_game(tid, game, rewrite_reservations=False)
            try:
                schedule_log_update(
                    int(game.get("lobby_thread_id") or game.get("original_thread_id") or tid)
                )
            except Exception as e:
                print(f"[WARN] Could not refresh public archive after feedback merit: {e}")
        except Exception as e:
            print(f"[WARN] Feedback merit award failed for {interaction.user.id}: {e}")

    # Live-edit the public feedback embed.
    chan_id = game.get("feedback_channel_id")
    msg_id = game.get("feedback_message_id")
    if chan_id and msg_id:
        try:
            channel = bot.get_channel(int(chan_id)) or await bot.fetch_channel(int(chan_id))
            msg = await channel.fetch_message(int(msg_id))
            await msg.edit(
                embed=build_feedback_embed(game),
                view=build_game_feedback_view(int(source_id)),
            )
        except Exception as e:
            print(f"[WARN] Could not refresh feedback embed: {e}")

    avg, votes = _feedback_stats(ratings)
    avg_txt = f"{avg:.1f}/5" if avg is not None else "—/5"
    if prev is not None and int(prev) != int(stars):
        note = f"Updated your rating from **{prev}** → **{stars}** ⭐."
    else:
        note = f"Recorded **{stars}/5** ⭐."
    await interaction.followup.send(
        f"✅ {note}\nLive score: **{avg_txt}** · {votes} vote{'s' if votes != 1 else ''}.{merit_note}",
        ephemeral=True,
    )


async def _post_game_feedback(announce_channel: discord.abc.Messageable, game: dict, source_id: str):
    """Post the feedback embed + buttons and persist message refs on the game."""
    if game.get("feedback_archived"):
        return None
    participants = sorted(_feedback_participant_ids(game))
    reserved = sorted(_feedback_reserved_ids(game))
    game["feedback_source_id"] = str(source_id)
    game["feedback_participants"] = participants
    game["feedback_reserved"] = reserved
    game["feedback_eligible"] = participants
    game["feedback_ratings"] = dict(game.get("feedback_ratings") or {})
    game["ended_at"] = int(game.get("ended_at") or time.time())
    game["hosting_evaluated"] = False

    embed = build_feedback_embed(game)
    view = build_game_feedback_view(int(source_id))
    existing_channel_id = game.get("feedback_channel_id")
    existing_message_id = game.get("feedback_message_id")
    if existing_channel_id and existing_message_id:
        try:
            existing_channel = (
                bot.get_channel(int(existing_channel_id))
                or await bot.fetch_channel(int(existing_channel_id))
            )
            existing_message = await existing_channel.fetch_message(int(existing_message_id))
            await existing_message.edit(embed=embed, view=view)
            return existing_message
        except discord.NotFound:
            pass
        except Exception as e:
            # A lookup glitch must not post a second poll while the first is still up.
            print(f"[WARN] Existing feedback poll lookup failed; leaving the current message: {e}")
            return None

    rate_msg = await announce_channel.send(embed=embed, view=view)

    known_ids = [
        str(item).strip()
        for item in (game.get("feedback_message_ids") or [])
        if str(item).strip().isdigit()
    ]
    if existing_message_id and str(existing_message_id) not in known_ids:
        known_ids.append(str(existing_message_id))
    if str(rate_msg.id) not in known_ids:
        known_ids.append(str(rate_msg.id))
    game["feedback_message_ids"] = known_ids
    game["feedback_channel_id"] = announce_channel.id
    game["feedback_message_id"] = rate_msg.id
    return rate_msg


def _host_history_entry_label(entry) -> str:
    if isinstance(entry, dict):
        return entry.get("label") or entry.get("mention") or str(entry.get("game_id") or "Game")
    return str(entry)


def _host_eval_counts(history: list) -> tuple[int, int, str | None, int]:
    """Return (successful, unsuccessful, streak_type, streak_count) from host history."""
    evaluated = [
        e for e in (history or [])
        if isinstance(e, dict) and e.get("result") in ("successful", "unsuccessful")
    ]
    successful = sum(1 for e in evaluated if e["result"] == "successful")
    unsuccessful = sum(1 for e in evaluated if e["result"] == "unsuccessful")
    streak_type = None
    streak_count = 0
    for e in reversed(evaluated):
        r = e["result"]
        if streak_type is None:
            streak_type = r
            streak_count = 1
        elif r == streak_type:
            streak_count += 1
        else:
            break
    return successful, unsuccessful, streak_type, streak_count


def build_archived_feedback_embed(game: dict, hosting_result: str | None = None) -> discord.Embed:
    """Final snapshot of session feedback for the host chatlog archive."""
    mode = game.get("mode") or "Game"
    thread_name = game.get("thread_name") or mode
    ratings = game.get("feedback_ratings") or {}
    avg, votes = _feedback_stats(ratings)
    host_id = game.get("host_id")
    result = hosting_result or game.get("hosting_result")

    color = discord.Color.gold()
    if result == "successful":
        color = discord.Color.green()
    elif result == "unsuccessful":
        color = discord.Color.red()

    embed = discord.Embed(
        title="⭐ Session Feedback — Archived",
        color=color,
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    host_line = f"<@{host_id}>" if host_id else "Unknown"
    embed.description = (
        f"**{thread_name}** ({mode})\n"
        f"**Host:** {host_line}\n"
        f"*Voting closed — archived from the announcement channel after 48 hours.*"
    )
    if avg is None:
        score_line = f"**— / 5** ⭐\n{_feedback_star_bar(None)}\n`0` vote(s)"
    else:
        score_line = f"**{avg:.1f} / 5** ⭐\n{_feedback_star_bar(avg)}\n`{votes}` vote(s)"
    embed.add_field(name="Final Score", value=score_line, inline=False)

    if result == "successful":
        embed.add_field(
            name="Hosting Evaluation",
            value="✅ **Successful Hosting** (≥ 3.0 / 5)",
            inline=False,
        )
    elif result == "unsuccessful":
        embed.add_field(
            name="Hosting Evaluation",
            value="❌ **Not Successful Hosting** (< 3.0 / 5)",
            inline=False,
        )
    return embed


async def _apply_hosting_evaluation(game_key: str, game: dict) -> None:
    """Mark Successful / Not Successful Hosting from the live feedback average.

    - ≥ HOSTING_SUCCESS_MIN_AVG → Successful → increments hosted_games
    - below that (or no votes) → Not Successful → does not increment hosted_games
    - Hitting 2 successful OR 2 unsuccessful evaluations in a row posts an
      alert embed to HOST_MANAGEMENT_CHANNEL_ID.
    """
    if game.get("hosting_evaluated"):
        return
    if game.get("status") != "ended":
        return

    ratings = game.get("feedback_ratings") or {}
    avg, votes = _feedback_stats(ratings)
    successful = avg is not None and avg >= G.HOSTING_SUCCESS_MIN_AVG
    result = "successful" if successful else "unsuccessful"
    result_label = "Successful Hosting" if successful else "Not Successful Hosting"

    game["hosting_evaluated"] = True
    game["hosting_result"] = result
    game["hosting_eval_avg"] = avg
    game["hosting_eval_votes"] = votes
    game["hosting_evaluated_at"] = int(time.time())
    await save_single_game(game_key, game, rewrite_reservations=False)

    host_id = game.get("host_id")
    if not host_id:
        print(f"⚠️ Hosting eval for {game_key}: no host_id on game.")
        return

    h_stats = await read_json(HOST_STATS_FILE)
    if not isinstance(h_stats, collections.abc.MutableMapping):
        h_stats = {}
    hid = str(host_id)
    entry = h_stats.get(hid) or {
        "hosted_games": 0, "acclamations": 0, "violations": 0, "history": [],
    }
    history = list(entry.get("history") or [])

    # Update matching pending history row, or append a new evaluated one.
    lobby_id = str(
        game.get("lobby_thread_id")
        or game.get("original_thread_id")
        or game.get("feedback_source_id")
        or game_key
    )
    mode = game.get("mode") or "Game"
    updated = False
    for item in history:
        if not isinstance(item, dict):
            continue
        gid = str(item.get("game_id") or "")
        if gid and gid in (lobby_id, str(game_key), str(game.get("host_panel_thread_id") or "")):
            item["result"] = result
            item["avg"] = avg
            item["votes"] = votes
            item["evaluated_at"] = int(time.time())
            updated = True
            break
    if not updated:
        history.append({
            "label": f"{mode} (`{lobby_id}`)",
            "mode": mode,
            "game_id": lobby_id,
            "result": result,
            "avg": avg,
            "votes": votes,
            "ts": int(game.get("ended_at") or time.time()),
            "evaluated_at": int(time.time()),
        })

    if successful:
        entry["hosted_games"] = int(entry.get("hosted_games", 0) or 0) + 1

    entry["history"] = history
    h_stats[hid] = entry
    await write_json(HOST_STATS_FILE, h_stats)

    _succ, _fail, streak_type, streak_count = _host_eval_counts(history)
    avg_txt = f"{avg:.1f}/5" if avg is not None else "no votes"
    print(
        f"⭐ Hosting eval for {game_key}: {result_label} ({avg_txt}, {votes} vote(s)) "
        f"— host {hid} streak={streak_type}:{streak_count}"
    )

    if streak_count == 2 and streak_type in ("successful", "unsuccessful"):
        await _post_host_streak_alert(
            host_id=int(host_id),
            streak_type=streak_type,
            streak_count=streak_count,
            game=game,
            avg=avg,
            votes=votes,
        )


async def _post_host_streak_alert(*, host_id: int, streak_type: str, streak_count: int,
                                  game: dict, avg, votes: int) -> None:
    """Notify Host Management of 2 successful or 2 unsuccessful hostings in a row."""
    channel = bot.get_channel(G.HOST_MANAGEMENT_CHANNEL_ID)
    if channel is None:
        try:
            channel = await bot.fetch_channel(G.HOST_MANAGEMENT_CHANNEL_ID)
        except Exception as e:
            print(f"⚠️ Could not fetch Host Management channel: {e}")
            return

    mode = game.get("mode") or "Game"
    thread_name = game.get("thread_name") or mode
    avg_txt = f"{avg:.1f}/5" if avg is not None else "no votes"
    panel = game.get("host_panel_thread_id")

    if streak_type == "successful":
        embed = discord.Embed(
            title="🌟 Host Streak — 2 Successful Hostings in a Row",
            color=discord.Color.green(),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        embed.description = (
            f"**Host:** <@{host_id}>\n"
            f"This host has now delivered **{streak_count} Successful Hostings** back-to-back "
            f"(session feedback ≥ **{G.HOSTING_SUCCESS_MIN_AVG:.0f}/5**).\n\n"
            f"👍 Management may want to recognize or reward this host."
        )
    else:
        embed = discord.Embed(
            title="⚠️ Host Streak — 2 Unsuccessful Hostings in a Row",
            color=discord.Color.red(),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        embed.description = (
            f"**Host:** <@{host_id}>\n"
            f"This host has now had **{streak_count} Not Successful Hostings** back-to-back "
            f"(session feedback below **{G.HOSTING_SUCCESS_MIN_AVG:.0f}/5**).\n\n"
            f"🚨 **Management team should review and take action** against this host."
        )

    embed.add_field(name="Latest Session", value=f"**{thread_name}** ({mode})", inline=False)
    embed.add_field(name="Latest Score", value=f"**{avg_txt}** · {votes} vote(s)", inline=True)
    if panel:
        embed.add_field(name="Host Panel", value=f"<#{panel}>", inline=True)
    embed.set_footer(text="Auto-generated from Session Feedback evaluations (24h after the game ended)")

    try:
        await channel.send(embed=embed)
    except Exception as e:
        print(f"⚠️ Failed to post host streak alert: {e}")


# ————— A thread per finished game in the host chat-logs forum —————
# When a game ends GameMaster opens a thread for it (date · mode · game id)
# with links to manage it on the website. Everything given for that game
# afterwards — commends, warnings, Merit, bans, Dishonored, the AI analysis —
# and its archived feedback is posted there. The thread is the game's
# "host_panel_thread_id" (the old Host Control Center's slot).
MODE_THREAD_LABELS = {
    "Roleplay": "Roleplay",
    "Roleplay (Millennium Dawn)": "Millennium Dawn",
    "Roleplay (Novum Vexillum)": "Novum Vexillum",
    "Kaiserreich (FFA)": "Kaiserreich FFA",
    "TFR": "The Fire Rises",
    "Historical (Vanilla)": "Historical Vanilla",
    "Historical (TFB)": "Their Finest Bruh",
    "Historical (Oak)": "Hearts of Oak",
    "Historical (Horst)": "Horstorical",
    "Historical (BFFU)": "BFFU 2",
}


def _game_log_thread_name(game: dict, key) -> str:
    ts = int(game.get("game_started_at") or game.get("start_timestamp") or time.time())
    date = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).strftime("%d.%m.%Y")
    mode = str(game.get("mode") or "Game")
    return f"{date} · {MODE_THREAD_LABELS.get(mode, mode)} · #{key}"[:100]


async def _open_game_log_thread(game_key, game: dict):
    """The game's thread in the host chat-logs forum (made when first needed)."""
    if game.get("host_panel_thread_id"):
        existing = await _resolve_host_control_center(game, game_key)
        if existing is not None:
            return existing
    forum_id = int(G.HOST_FORUM_CHANNEL_ID or 0)
    if not forum_id:
        return None
    try:
        forum = bot.get_channel(forum_id) or await bot.fetch_channel(forum_id)
    except Exception as e:
        print(f"[WARN] host chat-logs forum unavailable: {e}")
        return None
    stable = _attendance_stable_id(game, game_key)
    mode = str(game.get("mode") or "Game")
    embed = discord.Embed(
        title=f"🎮 {MODE_THREAD_LABELS.get(mode, mode)} · {_game_log_thread_name(game, game_key).split(' · ')[0]}",
        color=discord.Color.blurple(),
        description=(
            "Manage this game on the website: its attendance, chat log and AI analysis, and the rewards to give.\n"
            "Commends, warnings and anything else given for this game, and its feedback, are posted in this thread."
        ),
    )
    if game.get("host_id"):
        embed.add_field(name="Host", value=f"<@{game['host_id']}>", inline=True)
    embed.add_field(name="Players", value=str(len({str(v) for v in (game.get("reservations") or {}).values()})), inline=True)
    embed.add_field(name="Game ID", value=f"`{game_key}`", inline=True)
    view = discord.ui.View(timeout=None)
    view.add_item(discord.ui.Button(label="Manage this game", style=discord.ButtonStyle.link, url=_game_control_url(stable), emoji="🎮"))
    view.add_item(discord.ui.Button(label="Attendance", style=discord.ButtonStyle.link, url=_attendance_page_url(stable), emoji="📋"))
    name = _game_log_thread_name(game, game_key)
    try:
        if isinstance(forum, discord.ForumChannel):
            thread = (await forum.create_thread(name=name, embed=embed, view=view)).thread
        elif isinstance(forum, discord.TextChannel):
            message = await forum.send(embed=embed, view=view)
            thread = await message.create_thread(name=name)
        else:
            return None
    except discord.HTTPException as e:
        print(f"[WARN] could not open the game thread for {game_key}: {e}")
        return None
    game["host_panel_thread_id"] = thread.id
    await save_single_game(str(game_key), game, rewrite_reservations=False)
    return thread


async def _post_to_game_log_thread(game_key, game: dict, *, embed=None, content=None) -> None:
    """Post in a finished game's thread (opening it if needed)."""
    if not game or str(game.get("status") or "") != "ended":
        return
    try:
        thread = await _open_game_log_thread(game_key, game)
        if thread is not None:
            await asyncio.wait_for(thread.send(content=content, embed=embed), timeout=8.0)
    except Exception as e:
        print(f"[WARN] game thread post failed for {game_key}: {e}")


_feedback_archive_locks: dict[str, asyncio.Lock] = {}


async def _archive_session_feedback(game_key: str, game: dict) -> None:
    """At +48h: delete announcement feedback message and forward final embed to host chatlogs."""
    lock = _feedback_archive_locks.setdefault(str(game_key), asyncio.Lock())
    async with lock:
        games_data = await _load_games_resilient()
        current_key, current = _find_game_entry(games_data, game_key)
        if current:
            game = current
            game_key = str(current_key or game_key)
        if game.get("feedback_archived"):
            return
        message_ids = [
            str(item).strip()
            for item in (game.get("feedback_message_ids") or [])
            if str(item).strip().isdigit()
        ]
        primary_id = str(game.get("feedback_message_id") or "").strip()
        if primary_id.isdigit() and primary_id not in message_ids:
            message_ids.append(primary_id)
        if not message_ids:
            game["feedback_archived"] = True
            await save_single_game(game_key, game, rewrite_reservations=False)
            return

        # The game's own thread in the host chat-logs forum (else the forum itself).
        dest = None
        panel_id = game.get("host_panel_thread_id")
        if panel_id:
            try:
                dest = bot.get_channel(int(panel_id)) or await bot.fetch_channel(int(panel_id))
            except Exception:
                dest = None
        if dest is None:
            dest = await _open_game_log_thread(game_key, game)
        if dest is None:
            try:
                dest = bot.get_channel(G.HOST_FORUM_CHANNEL_ID) or await bot.fetch_channel(G.HOST_FORUM_CHANNEL_ID)
            except Exception as e:
                print(f"⚠️ Feedback archive destination unavailable: {e}")
                return

        archive_embed = build_archived_feedback_embed(game)
        try:
            mode = game.get("mode") or "Game"
            thread_name = (game.get("thread_name") or mode)[:80]
            if isinstance(dest, discord.ForumChannel):
                await dest.create_thread(
                    name=f"Feedback Archive — {thread_name}"[:100],
                    content="📁 **Session Feedback archived** (48h after game end).",
                    embed=archive_embed,
                )
            else:
                await dest.send(
                    content="📁 **Session Feedback archived** (48h after game end).",
                    embed=archive_embed,
                )
        except Exception as e:
            print(f"⚠️ Could not forward archived feedback for {game_key}: {e}")
            return

        # Delete every live poll we posted, not only the latest id.
        chan_id = game.get("feedback_channel_id")
        if chan_id:
            try:
                channel = bot.get_channel(int(chan_id)) or await bot.fetch_channel(int(chan_id))
            except Exception as e:
                print(f"⚠️ Could not open feedback channel for {game_key}: {e}")
                channel = None
            if channel:
                for msg_id in message_ids:
                    try:
                        msg = await channel.fetch_message(int(msg_id))
                        await msg.delete()
                    except discord.NotFound:
                        pass
                    except Exception as e:
                        print(f"⚠️ Could not delete announcement feedback message {msg_id}: {e}")

        game["feedback_archived"] = True
        game["feedback_archived_at"] = int(time.time())
        await save_single_game(game_key, game, rewrite_reservations=False)
        print(f"📁 Archived session feedback for {game_key}.")


async def process_feedback_lifecycle():
    """Scan ended games for due 24h hosting evals and 48h feedback archives."""
    try:
        games = await _load_games_resilient()
    except Exception as e:
        print(f"⚠️ Feedback lifecycle: could not load games: {e}")
        return

    now = int(time.time())
    for key, game in list((games or {}).items()):
        if not isinstance(game, dict):
            continue
        if game.get("status") != "ended":
            continue
        ended_at = game.get("ended_at")
        if not ended_at:
            # Legacy ended games without ended_at: backfill from snowflake so
            # they eventually archive, but only if they still have a live poll.
            if game.get("feedback_message_id") and not game.get("feedback_archived"):
                ended_at = _snowflake_to_unix(game.get("feedback_message_id") or key)
                game["ended_at"] = ended_at
            else:
                continue

        age = now - int(ended_at)

        if not game.get("hosting_evaluated") and age >= FEEDBACK_EVAL_AFTER_SEC:
            try:
                await _apply_hosting_evaluation(str(key), game)
            except Exception as e:
                print(f"⚠️ Hosting evaluation failed for {key}: {e}")
                import traceback
                traceback.print_exc()

        # Re-read flags in case evaluation just ran on the same object.
        if not game.get("feedback_archived") and age >= FEEDBACK_ARCHIVE_AFTER_SEC:
            try:
                await _archive_session_feedback(str(key), game)
            except Exception as e:
                print(f"⚠️ Feedback archive failed for {key}: {e}")
                import traceback
                traceback.print_exc()


@tasks.loop(minutes=5)
async def feedback_lifecycle_loop():
    """Runs once per active server (_feedback_lifecycle_loop_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_feedback_lifecycle_loop_for_guild, "feedback_lifecycle_loop")


async def _feedback_lifecycle_loop_for_guild():
    await process_feedback_lifecycle()


@feedback_lifecycle_loop.before_loop
async def before_feedback_lifecycle_loop():
    await _wait_ready_staggered(25)


_game_end_locks: dict[str, asyncio.Lock] = {}


def _member_is_senior_team(member: discord.Member) -> bool:
    if member.guild_permissions.administrator:
        return True
    return any(role.id in SENIOR_MANAGEMENT_ROLES for role in member.roles)


def _can_end_assigned_game(member: discord.Member, game: dict) -> bool:
    try:
        return int(game.get("host_id")) == member.id or _member_is_senior_team(member)
    except (TypeError, ValueError):
        return _member_is_senior_team(member)


async def _game_end_core(guild, actor, thread_id_str: str, *, progress) -> dict:
    """End a game (formerly /game_end — now the website's Games page, via a
    "game_end" request): finalize attendance and the public log, remove the
    voice channels and Gamer Pass, post the rating poll, DM participants and
    the host, and delete the reservation thread. The game keeps its storage
    key (there is no Host Control Center any more). Safe to repeat: an
    interrupted end resumes."""
    thread_id_str = str(thread_id_str)
    thread = await _resolve_game_thread(guild, thread_id_str)
    lock = _game_end_locks.setdefault(thread_id_str, asyncio.Lock())
    async with lock:
        games_data = await _load_games_resilient()
        game_key, game = _find_game_entry(games_data, thread_id_str)
        if not game:
            raise GameLifecycleError("❌ This game was not found or has already been ended.")
        if not _can_end_assigned_game(actor, game):
            assigned_host_id = game.get("host_id")
            raise GameLifecycleError(f"❌ Only the assigned game host (<@{assigned_host_id}>) or Host Management can end this game.")
        if game.get("game_end_completed_at"):
            raise GameLifecycleError("ℹ️ This game has already ended.")
        resuming_game_end = bool(game.get("game_end_started_at"))
        if resuming_game_end:
            print(
                f"[DIAGNOSTIC] Resuming incomplete /game_end for {thread_id_str}"
            )
        else:
            # Persist the one-way transition before any Discord I/O. Concurrent
            # invocations will now stop here rather than creating duplicate panels.
            game["thread_name"] = getattr(thread, "name", None) or game.get("thread_name") or thread_id_str
            # Lets the web find the game again after the storage-key move below.
            game.setdefault("lobby_thread_id", thread_id_str)
            game.setdefault("original_thread_id", thread_id_str)
            game["status"] = "ended"
            game["ended_at"] = int(time.time())
            game["game_end_started_at"] = game["ended_at"]
            game["hosting_evaluated"] = False
            game["feedback_archived"] = False
            await save_single_game(
                game_key or thread_id_str,
                game,
                rewrite_reservations=False,
            )

    game_mode = game.get("mode")

    # The ONLY publicly-visible message during game end.
    if not resuming_game_end:
        try:
            if thread is not None:
                await thread.send(
                    "## 🏁 Game End Initialized…\n> Wrapping up the session <a:loading:1458048543716671518>"
                )
        except Exception as e:
            print(f"Failed to send public game-end message: {e}")

    await progress("⏳ **Finalizing attendance and public log…**")

    try:
        await _mark_schedule_slot_board_status(game.get("host_id"), game.get("mode"), game.get("start_timestamp"), "ended")
    except Exception as e:
        print(f"[WARN] Could not update schedule board after game end: {e}")

    try:
        # A game that never had /game_start run has no Gamer Pass role, no game
        # VCs, and nobody who ever pressed "Yes" — there is nothing legitimate
        # to attend. Skipping this avoids _scan_voice_presence/_finalize_game_attendance
        # ever being asked to guess "who was playing" for a game that was only
        # ever in the reservation phase (which used to wrongly credit/blame
        # people for a game they never actually joined).
        if game.get("game_started", False):
            await _finalize_game_attendance(guild, thread_id_str)
        schedule_log_update(int(thread_id_str))
    except Exception as e:
        print(f"[WARN] Could not finalize public archive log: {e}")

    # Attendance finalization persists present_ids separately; reload before
    # building feedback eligibility/counts so this command never uses stale data.
    refreshed_games = await _load_games_resilient()
    refreshed_key, refreshed_game = _find_game_entry(refreshed_games, thread_id_str)
    if refreshed_game:
        games_data = refreshed_games
        game = refreshed_game

    mode_config = MODE_CONFIG.get(game_mode)
    if not mode_config:
        raise GameLifecycleError(f"❌ Mode config not found for '{game_mode}'.")

    announce_channel_id = mode_config.get("announcement_channel_id")
    game_info_channel_id = mode_config.get("game_info_channel_id")
    announce_channel = bot.get_channel(announce_channel_id)

    await progress("✅ **Log finalized** — cleaning up voice channels…")

    cat_ids = game.get("temp_vc_categories", [])
    vc_ids = game.get("temp_vc_channels", [])
    role_id = game.get("temp_gamer_pass_role")

    if cat_ids or vc_ids or role_id:
        await cleanup_game_voice_channels(guild, cat_ids, vc_ids, role_id)

    await send_log_message(
        f"🧹 **Auto-VC System**: Deleted **{len(cat_ids)}** categories, **{len(vc_ids)}** VCs, "
        f"and the dynamic Gamer Pass (Game Ended)."
    )

    await progress("✅ **Channels cleaned up** — sending conclusion DMs…")

    # Only players recorded present receive the feedback request and may vote.
    participant_ids = sorted(_feedback_participant_ids(game))

    # Feedback is posted first so DMs can include a jump link.
    rate_msg = None
    if announce_channel:
        try:
            rate_msg = await _post_game_feedback(announce_channel, game, thread_id_str)
            await save_single_game(
                refreshed_key or thread_id_str,
                game,
                rewrite_reservations=False,
            )
        except Exception as e:
            print(f"Failed to send rating message: {e}")

    jump_url = rate_msg.jump_url if rate_msg else (f"<#{announce_channel_id}>" if announce_channel_id else "the announcement channel")
    dm_lines = (
        f"✅ **{game_mode} Game** has been concluded! Thanks for participating!\n"
        f"📝 Your gameplay shall be reviewed for any commendations/warns.\n"
        f"⭐ **Please rate this session (1–5):** {jump_url}"
    )
    members_to_dm = []
    for user_id in participant_ids:
        member = guild.get_member(user_id)
        if member:
            members_to_dm.append(member)
    if not game.get("conclusion_dms_sent"):
        await _send_dms_batched(members_to_dm, dm_lines)
        game["conclusion_dms_sent"] = True
        await save_single_game(
            refreshed_key or thread_id_str,
            game,
            rewrite_reservations=False,
        )

    game_info_channel = bot.get_channel(game_info_channel_id)
    if game_info_channel:
        try: await game_info_channel.purge(limit=100)
        except: pass

    await _delete_announcement(bot, game, mode_config)

    # ==========================================
    # --- DELETE MOD EMBED MESSAGE ---
    # ==========================================
    mod_msg_id = game.get("mod_message_id")
    if mod_msg_id and mode_config:
        mod_chan_id = mode_config.get("mods_channel_id")
        if mod_chan_id:
            try:
                mod_channel = bot.get_channel(mod_chan_id)
                if mod_channel:
                    mod_msg = await mod_channel.fetch_message(mod_msg_id)
                    await mod_msg.delete()
            except discord.NotFound:
                pass # Message already deleted manually
            except Exception as e:
                print(f"Could not delete mod message: {e}")

    # ==========================================
    # --- DELETE RULES EMBED MESSAGE ---
    # ==========================================
    rules_msg_id = game.get("rules_message_id")
    if rules_msg_id and mode_config:
        rules_chan_id = mode_config.get("rules_channel_id")
        if rules_chan_id:
            try:
                # 1. Force IDs to integers (fixes JSON string/float type errors)
                rules_channel = guild.get_channel(int(rules_chan_id))

                if rules_channel:
                    # 2. Fetch and delete
                    rules_msg = await rules_channel.fetch_message(int(rules_msg_id))
                    await rules_msg.delete()
                    print(f"[DIAGNOSTIC] ✅ Successfully deleted rules embed: {rules_msg_id}")
                else:
                    print(f"[DIAGNOSTIC] ❌ Failed: Could not find rules channel ID {rules_chan_id}")

            except discord.NotFound:
                print(f"[DIAGNOSTIC] ⚠️ Rules message {rules_msg_id} was already deleted manually.")
            except Exception as e:
                print(f"[DIAGNOSTIC] ❌ Error deleting rules message: {e}")
    else:
        print("[DIAGNOSTIC] ⚠️ No rules_message_id found in game data to delete.")

    # ==========================================
    # --- FINISH ON THE GAME'S OWN RECORD ---
    # No Host Control Center any more: attendance, corrections and the game's
    # history are on the website (Games / Attendance pages), so the game keeps
    # its own storage key.
    # ==========================================
    completed_games = await _load_games_resilient()
    completed_key, completed_game = _find_game_entry(completed_games, thread_id_str)
    if completed_game:
        completed_game["status"] = "ended"
        completed_game["game_end_completed_at"] = int(time.time())
        await save_single_game(
            completed_key or thread_id_str,
            completed_game,
            rewrite_reservations=False,
        )
    try:
        schedule_log_update(int(thread_id_str))
    except Exception as e:
        print(f"[WARN] Could not refresh public archive after game end: {e}")

    assigned_host = guild.get_member(int(game.get("host_id") or 0))
    if assigned_host is not None:
        await _dm_user_safe(
            assigned_host,
            content=(
                f"✅ **{game_mode} Game Ended!**\n"
                f"Attendance, corrections and the game's history: "
                f"{_attendance_page_url(_attendance_stable_id(completed_game or game, thread_id_str))}"
            ),
            label="game end host DM",
        )
    await progress("✅ Game cleanup complete.")

    # The game's thread in the host chat-logs forum (links to manage it).
    try:
        ended_games = await _load_games_resilient()
        ended_key, ended_game = _find_game_entry(ended_games, thread_id_str)
        if ended_game is not None:
            await _open_game_log_thread(str(ended_key or thread_id_str), ended_game)
    except Exception as e:
        print(f"[WARN] game thread for {thread_id_str} failed: {e}")

    # ==========================================
    # FINALLY, DELETE THE GAME THREAD
    # ==========================================
    if thread is not None:
        try:
            print(f"[DIAGNOSTIC] Deleting original game thread {thread.id} in 2 seconds...")
            await asyncio.sleep(2)
            await thread.delete()
        except Exception as e:
            print(f"Failed to delete thread {thread_id_str}: {e}")

    present_count = len((completed_game or game).get("present_ids") or [])
    players_count = len({str(v) for v in ((completed_game or game).get("reservations") or {}).values()})
    record_attendance_event(
        str((completed_game or game).get("lobby_thread_id") or thread_id_str), "game_ended",
        actor_id=getattr(actor, "id", None), details={"present": present_count, "players": players_count},
    )
    return {
        "title": "🏁 Game ended",
        "summary": f"{present_count} of {players_count} player(s) counted present.",
        "notes": [
            "Voice channels and the Gamer Pass role were removed; the rating poll is posted.",
            "Corrections go through the Attendance page.",
        ],
    }


async def _delete_announcement(client, game: dict, mode_config: dict):
    """Fetch and delete the game announcement message. Returns True on success."""
    msg_id  = game.get("announcement_message_id")
    chan_id = game.get("announcement_channel_id") or mode_config.get("announcement_channel_id")
    if not msg_id or not chan_id:
        return False
    try:
        channel = client.get_channel(chan_id)
        if channel is None:
            channel = await client.fetch_channel(chan_id)
        msg = await channel.fetch_message(msg_id)
        await msg.delete()
        return True
    except discord.NotFound:
        return True   # Already gone, that's fine
    except Exception as e:
        print(f"[WARN] Could not delete announcement message: {e}")
        return False


async def _game_cancel_core(guild, actor, thread_id_str: str, *, reason: str, progress) -> dict:
    """Cancel a game without penalties (formerly /game_cancel — now the
    website's Games page, via a "game_cancel" request): reverts this game's
    no-show warnings and spent commends, rolls back its participation, DMs
    every reserved player the reason, removes the voice channels, Gamer Pass,
    announcement, mod / rules posts and Host Control Center, and deletes the
    reservation thread."""
    thread_id_str = str(thread_id_str)
    thread = await _resolve_game_thread(guild, thread_id_str)
    games_data = await read_json(GAMES_FILE)

    if thread_id_str not in games_data:
        raise GameLifecycleError("❌ Game data not found.")

    game = games_data[thread_id_str]
    mode = game.get("mode")
    mode_config = MODE_CONFIG.get(mode, {})

    game["status"] = "cancelled"
    game["game_started"] = False
    game["thread_name"] = getattr(thread, "name", None) or game.get("thread_name") or thread_id_str
    game["cancel_reason"] = reason
    game["cancelled_at"] = int(time.time())
    game["cancelled_by"] = str(getattr(actor, "id", "") or "")
    await write_json(GAMES_FILE, games_data)

    # ==========================================================================
    # CRITICAL PATH — must always run, no matter what fails below. This is what
    # actually stops duplicate announcements: the moment the DB says "cancelled",
    # the live announcement + reservation thread MUST be torn down so a host who
    # gets no response can't be tricked into re-announcing over a still-live game.
    # Every "best effort" step (logs, DMs, stat refunds) is now individually
    # wrapped so ONE glitch (a rate limit, a missing channel, a bad stats row)
    # can no longer kill the whole cancel and leave the request hanging.
    # ==========================================================================
    dm_count = 0
    warn_removed_users: set = set()
    commend_refunded_users: set = set()
    participation_rolled_back_users: set = set()
    reservations = game.get("reservations", {})
    step_errors: list[str] = []

    # --- CLEANUP VOICE CHANNELS & ROLE ---
    try:
        cat_ids = game.get("temp_vc_categories", [])
        vc_ids = game.get("temp_vc_channels", [])
        role_id = game.get("temp_gamer_pass_role")
        if cat_ids or vc_ids or role_id:
            await cleanup_game_voice_channels(guild, cat_ids, vc_ids, role_id)
        log_chan = bot.get_channel(G.AUDIT_CHANNEL_ID)
        if log_chan:
            await log_chan.send(
                f"🗑️ **Auto-VC System**: Deleted **{len(cat_ids)}** categories, **{len(vc_ids)}** VCs, "
                f"and the dynamic Gamer Pass (Game Cancelled)."
            )
    except Exception as e:
        step_errors.append(f"VC cleanup: {e}")
        print(f"[WARN] game_cancel VC cleanup failed: {e}")

    try:
        await _mark_schedule_slot_board_status(game.get("host_id"), game.get("mode"), game.get("start_timestamp"), "cancelled")
    except Exception as e:
        print(f"[WARN] Could not update schedule board after game cancel: {e}")

    try:
        schedule_log_update(int(thread_id_str))
    except Exception as e:
        print(f"Could not trigger public log: {e}")

    # --- WARN / COMMEND REFUNDS (best-effort; a bad stats row must not abort cancel) ---
    try:
        player_stats = await read_json(PLAYER_STATS_FILE)
        game_warns = game.get("game_warns", [])
        spent_commends = game.get("spent_commends", {})
        applied_warns = game.get("applied_warns", {})
        mod_context = get_mod_context(mode) or get_mod_context("Roleplay")
        warn_key = mod_context["key_warn"]
        commend_key = mod_context["key_commend"]
        ban_key = mod_context["key_ban"]

        for uid_str, amount in spent_commends.items():
            if uid_str in player_stats:
                uid = int(uid_str)
                stats = player_stats[uid_str]
                stats[commend_key] = stats.get(commend_key, 0) + amount
                commend_refunded_users.add(uid)

                if stats[commend_key] >= 5 and not _is_game_banned_any(stats):
                    member = guild.get_member(uid)
                    if member:
                        trusted_role = guild.get_role(mod_context["role_trusted"])
                        verified_role = guild.get_role(mod_context["role_verified"])
                        if trusted_role and verified_role and verified_role in member.roles and trusted_role not in member.roles:
                            try: await member.add_roles(trusted_role, reason="Commendations refunded to 5+ (Game Cancelled)")
                            except: pass

        if game_warns:
            for uid in game_warns:
                uid_str = str(uid)
                if uid_str in player_stats:
                    stats = player_stats[uid_str]

                    user_penalty = int(applied_warns.get(uid_str, 0))
                    user_nation = next((n for n, u in reservations.items() if u == uid), None)
                    if not user_penalty and user_nation:
                        user_penalty = _attendance_no_show_penalty(
                            user_nation, mode, game.get("logging_mode", "Strict")
                        )

                    if stats.get(warn_key, 0) > 0:
                        stats[warn_key] = max(0, stats[warn_key] - user_penalty)
                        warn_removed_users.add(uid)

                        if stats.get(ban_key, False) and stats[warn_key] < G.WARNINGS_FOR_BAN:
                            stats[ban_key] = False
                            member = guild.get_member(uid)
                            if member:
                                try:
                                    b_role = guild.get_role(mod_context["role_banned"])
                                    if b_role: await member.remove_roles(b_role)
                                except: pass

        # Attendance may have finalized before the cancellation. Roll back the
        # persisted participation record and rebuild RP streak state from the
        # remaining non-cancelled games.
        cancelled_ids = {
            str(thread_id_str),
            str(game.get("lobby_thread_id") or ""),
            str(game.get("original_thread_id") or ""),
        }
        for uid in set(reservations.values()):
            uid_str = str(uid)
            stats = player_stats.get(uid_str)
            if not isinstance(stats, dict):
                continue
            history = list(stats.get("history") or [])
            kept_history = [
                entry for entry in history
                if str(entry.get("game_id") or "") not in cancelled_ids
            ]
            removed_count = len(history) - len(kept_history)
            if removed_count:
                stats["history"] = kept_history
                stats["total_games"] = max(
                    0, int(stats.get("total_games", 0) or 0) - removed_count
                )
                participation_rolled_back_users.add(int(uid))

            if "Roleplay" in (mode or ""):
                stats.setdefault("minor_streaks", {})
                stats.setdefault("last_major_nation", {})
                previous_nation = _last_participated_nation_in_mode(
                    games_data, uid, mode, exclude_thread_id=thread_id_str
                )
                if not previous_nation:
                    stats["minor_streaks"].pop(mode, None)
                    stats["last_major_nation"].pop(mode, None)
                elif is_major(previous_nation, mode):
                    stats["minor_streaks"][mode] = 0
                    stats["last_major_nation"][mode] = previous_nation
                else:
                    stats["minor_streaks"][mode] = 1
                    stats["last_major_nation"].pop(mode, None)
                participation_rolled_back_users.add(int(uid))

        if warn_removed_users or commend_refunded_users or participation_rolled_back_users:
            await write_json(PLAYER_STATS_FILE, player_stats)
            await _refresh_player_stats_cache()
    except Exception as e:
        step_errors.append(f"Warn/commend refund: {e}")
        print(f"[WARN] game_cancel warn/commend refund failed: {e}")

    # --- DM PLAYERS (best-effort) ---
    try:
        unique_users = set(reservations.values())
        for uid in unique_users:
            member = guild.get_member(uid)
            if member:
                try:
                    embed = discord.Embed(title=f"🚫 Game Cancelled: {mode}", color=discord.Color.red())
                    embed.add_field(name="Host", value=actor.mention, inline=True)
                    embed.add_field(name="Reason", value=reason, inline=False)

                    if uid in warn_removed_users:
                        embed.add_field(name="⚠️ Correction", value="Your 'No-Show' warning for this game has been automatically removed.", inline=False)

                    if uid in commend_refunded_users:
                        embed.add_field(name="🛡️ Commendation Refunded", value="Hey! The commendation you used to excuse your absence has been fully restored to your account.", inline=False)

                    embed.set_footer(text="No warnings or penalties have been issued.")
                    await member.send(embed=embed)
                    dm_count += 1
                except: pass
    except Exception as e:
        step_errors.append(f"Player DMs: {e}")
        print(f"[WARN] game_cancel player DM loop failed: {e}")

    # --- PURGE GAME-INFO CHANNEL (best-effort) ---
    try:
        game_info_id = mode_config.get("game_info_channel_id")
        game_info_channel = bot.get_channel(game_info_id) if game_info_id else None
        if game_info_channel:
            try: await game_info_channel.purge(limit=100)
            except: pass
    except Exception as e:
        step_errors.append(f"Game-info purge: {e}")
        print(f"[WARN] game_cancel game-info purge failed: {e}")

    # ==========================================
    # --- DELETE THE ANNOUNCEMENT MESSAGE (critical — prevents duplicate announcements) ---
    # ==========================================
    try:
        await _delete_announcement(bot, game, mode_config)
    except Exception as e:
        step_errors.append(f"Announcement delete: {e}")
        print(f"[WARN] game_cancel announcement delete failed: {e}")

    # ==========================================
    # --- DELETE MOD EMBED MESSAGE ---
    # ==========================================
    try:
        mod_msg_id = game.get("mod_message_id")
        if mod_msg_id and mode_config:
            mod_chan_id = mode_config.get("mods_channel_id")
            if mod_chan_id:
                try:
                    mod_channel = bot.get_channel(mod_chan_id)
                    if mod_channel:
                        mod_msg = await mod_channel.fetch_message(mod_msg_id)
                        await mod_msg.delete()
                except discord.NotFound:
                    pass # Message already deleted manually
                except Exception as e:
                    print(f"Could not delete mod message: {e}")
    except Exception as e:
        print(f"[WARN] game_cancel mod-message delete step failed: {e}")

    # ==========================================
    # --- DELETE RULES EMBED MESSAGE ---
    # ==========================================
    try:
        rules_msg_id = game.get("rules_message_id")
        if rules_msg_id and mode_config:
            rules_chan_id = mode_config.get("rules_channel_id")
            if rules_chan_id:
                try:
                    # 1. Force IDs to integers (fixes JSON string/float type errors)
                    rules_channel = guild.get_channel(int(rules_chan_id))

                    if rules_channel:
                        # 2. Fetch and delete
                        rules_msg = await rules_channel.fetch_message(int(rules_msg_id))
                        await rules_msg.delete()
                        print(f"[DIAGNOSTIC] ✅ Successfully deleted rules embed: {rules_msg_id}")
                    else:
                        print(f"[DIAGNOSTIC] ❌ Failed: Could not find rules channel ID {rules_chan_id}")

                except discord.NotFound:
                    print(f"[DIAGNOSTIC] ⚠️ Rules message {rules_msg_id} was already deleted manually.")
                except Exception as e:
                    print(f"[DIAGNOSTIC] ❌ Error deleting rules message: {e}")
        else:
            print("[DIAGNOSTIC] ⚠️ No rules_message_id found in game data to delete.")
    except Exception as e:
        print(f"[WARN] game_cancel rules-message delete step failed: {e}")

    # --- HOST LOG (best-effort) ---
    try:
        log_chan = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
        if log_chan is None:
            log_chan = await bot.fetch_channel(G.HOST_LOG_CHANNEL_ID)
        if log_chan:
            log_embed = discord.Embed(title="🗑️ Game Cancelled", color=discord.Color.dark_red())
            log_embed.add_field(name="Thread", value=str(game.get("thread_name") or thread_id_str), inline=False)
            log_embed.add_field(name="Host", value=actor.mention, inline=True)
            log_embed.add_field(name="Notified", value=f"{dm_count} users", inline=True)
            log_embed.add_field(name="Warns Reverted", value=str(len(warn_removed_users)), inline=True)
            log_embed.add_field(name="Reason", value=reason, inline=False)
            await log_chan.send(embed=log_embed)
    except Exception as e:
        print(f"[WARN] Could not send cancel log: {e}")

    # ==========================================
    # --- DELETE HOST CONTROL CENTER THREAD ---
    # Spawned at /game_start. On /game_end this thread is REUSED as the post-game
    # host panel, but on a cancel there is no post-game report, so it would be left
    # orphaned (a locked panel for a game that never happened). Tear it down too.
    # ==========================================
    try:
        panel_thread_id = game.get("host_panel_thread_id")
        if panel_thread_id:
            try:
                panel_thread = bot.get_channel(int(panel_thread_id))
                if panel_thread is None:
                    panel_thread = await bot.fetch_channel(int(panel_thread_id))
                if panel_thread:
                    await panel_thread.delete()
            except discord.NotFound:
                pass  # Already gone
            except Exception as e:
                print(f"[WARN] Could not delete Host Control Center thread {panel_thread_id}: {e}")
    except Exception as e:
        print(f"[WARN] game_cancel host-panel delete step failed: {e}")

    # --- ALWAYS RESPOND — this is the fix for the "no response at all" bug ---
    summary = f"✅ Game cancelled and archived. DMs sent to {dm_count} players" + (
        " — removing the reservation thread…" if thread is not None else "."
    )
    if step_errors:
        summary += f"\n⚠️ Some non-critical steps had issues (see host logs): {len(step_errors)} warning(s)."
    try:
        await progress(summary)
    except Exception as e:
        print(f"[WARN] game_cancel final followup failed: {e}")

    # ==========================================
    # FINALLY, DELETE THE RESERVATION/GAME THREAD
    # Wrapped like /game_end so a missing-permission / already-deleted edge case
    # is logged instead of aborting the command silently.
    # ==========================================
    if thread is not None:
        try:
            await asyncio.sleep(5)
            await thread.delete()
        except discord.NotFound:
            pass  # Already gone
        except Exception as e:
            print(f"[WARN] Could not delete reservation thread {thread_id_str}: {e}")

    record_attendance_event(
        str(game.get("lobby_thread_id") or thread_id_str), "game_cancelled",
        actor_id=getattr(actor, "id", None),
        details={"reason": reason, "notified": dm_count, "warns_reverted": len(warn_removed_users)},
    )
    notes = [f"{len(warn_removed_users)} no-show warning(s) reverted, {len(commend_refunded_users)} commend refund(s)."]
    if step_errors:
        notes.append(f"{len(step_errors)} non-critical step(s) had issues — see the host log.")
    return {
        "title": "🗑️ Game cancelled",
        "summary": f"No penalties. {dm_count} player(s) were DMed the reason.",
        "notes": notes,
    }


# ==========================================================================
# WEB GAME LIFECYCLE — start / end / cancel from the website's Games page
# (formerly /game_start, /game_end and /game_cancel). A request is checked
# here, marked "running" and carried out in the background; each progress
# line is written to the request row so the page can show it live, and a long
# start (voice channels, DMs) never holds up other web requests.
# ==========================================================================
WEB_REQUEST_RUNNING = "running"
GAME_LIFECYCLE_ACTIONS = ("game_start", "game_end", "game_cancel")
GAME_START_INTERVALS = (20, 30, 40)
_web_lifecycle_running: set[str] = set()
_web_stale_lifecycle_checked = False


def _game_control_url(game_id) -> str:
    return f"{WEB_SITE_URL}/games?game={game_id}"


def _update_web_request_progress_mysql(request_id: str, result) -> None:
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        cur.execute(
            "UPDATE web_schedule_requests SET status = %s, result = %s "
            "WHERE request_id = %s AND status IN ('pending', %s)",
            (WEB_REQUEST_RUNNING, json.dumps(result, ensure_ascii=False), str(request_id), WEB_REQUEST_RUNNING),
        )
        conn.commit()
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _scrub_web_request_payload_mysql(request_id: str, keys: tuple) -> None:
    """Drop secrets (the in-game server password) from a finished request."""
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        paths = ", ".join(["%s"] * len(keys))
        cur.execute(
            f"UPDATE web_schedule_requests SET payload = JSON_REMOVE(payload, {paths}) "
            "WHERE request_id = %s AND payload IS NOT NULL",
            tuple(f"$.{key}" for key in keys) + (str(request_id),),
        )
        conn.commit()
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _fail_stale_running_web_requests_mysql(max_age_sec: int) -> int:
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        now = int(time.time())
        cur.execute(
            "UPDATE web_schedule_requests SET status = 'error', error = %s, processed_at = %s "
            "WHERE status = %s AND created_at < %s",
            (
                "⚠️ The bot restarted while this was running. Check the game's state and try again "
                "(an interrupted end picks up where it stopped).",
                now,
                WEB_REQUEST_RUNNING,
                now - int(max_age_sec),
            ),
        )
        conn.commit()
        return cur.rowcount or 0
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


async def _process_web_game_lifecycle(req: dict):
    """Check a game_start / game_end / game_cancel request, then run it in the
    background (the request stays "running" with live progress)."""
    action = str(req.get("action") or "")
    payload = req.get("payload") or {}
    request_id = str(req.get("request_id") or "")
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None or not _member_is_host(actor):
        return False, None, "❌ Only hosts can start, end or cancel games."
    thread_id = str(payload.get("thread_id") or "").strip()
    games = await _load_games_resilient()
    key, game = _find_game_entry(games, thread_id)
    if not game:
        return False, None, "❌ Game not found — it may have been removed."
    key = str(key or thread_id)
    if not _can_end_assigned_game(actor, game):
        return False, None, f"❌ Only the game's host (<@{game.get('host_id')}>) or Host Management can do that."
    if key in _web_lifecycle_running:
        return False, None, "ℹ️ This game is already being started, ended or cancelled — wait for that to finish."
    status = str(game.get("status") or "").strip().lower()
    kwargs: dict = {}

    if action == "game_start":
        if game.get("game_started"):
            return False, None, "ℹ️ This game has already started."
        if not _can_host_mode(actor, game.get("mode")):
            return False, None, _host_branch_refusal(actor, game.get("mode"))
        if status in ("ended", "cancelled"):
            return False, None, "❌ This game has already ended or was cancelled."
        if _is_draft_game(game) and game["draft"].get("phase") != "COMPLETE":
            pool_left = len(game["draft"].get("pool", {}))
            return False, None, (
                f"❌ The draft isn't finished — {pool_left} player(s) are still in the pool. "
                "Finish it (or clear the pool) first."
            )
        server_id = str(payload.get("server_id") or "").strip()
        password = str(payload.get("password") or "").strip()
        checksum = str(payload.get("checksum") or "").strip().upper()
        try:
            interval = int(payload.get("interval_minutes") or 0)
        except (TypeError, ValueError):
            interval = 0
        if not server_id or len(server_id) > 64:
            return False, None, "❌ Enter the in-game server ID."
        if not password or len(password) > 64:
            return False, None, "❌ Enter the in-game server password."
        if not re.fullmatch(r"[A-Z0-9]{4}", checksum):
            return False, None, "❌ The checksum must be exactly four letters or digits."
        if interval not in GAME_START_INTERVALS:
            return False, None, "❌ Pick an attendance interval: 20, 30 or 40 minutes."
        kwargs = {"game_id": server_id, "password": password, "checksum": checksum, "attendance_delay": interval}
    elif action == "game_end":
        if status == "cancelled":
            return False, None, "❌ This game was cancelled."
        if game.get("game_end_completed_at"):
            return False, None, "ℹ️ This game has already ended."
        if not game.get("game_started") and not game.get("game_end_started_at"):
            return False, None, "❌ This game hasn't started — cancel it instead."
    elif action == "game_cancel":
        reason = str(payload.get("reason") or "").strip()
        if len(reason) < 3 or len(reason) > 1000:
            return False, None, "❌ Give a reason (it's sent to every reserved player)."
        if status == "cancelled":
            return False, None, "ℹ️ This game is already cancelled."
        if status == "ended" or game.get("game_end_started_at"):
            return False, None, "❌ This game has already ended — it can't be cancelled."
        kwargs = {"reason": reason}
    else:
        return False, None, f"❌ Unknown game action: {action}."

    _web_lifecycle_running.add(key)
    state = {"action": action, "state": "running", "steps": [], "started_at": int(time.time())}
    try:
        await _run_mysql_io(
            _update_web_request_progress_mysql, request_id, {"lifecycle": state}, label="web lifecycle start"
        )
    except Exception as e:
        _web_lifecycle_running.discard(key)
        print(f"[WARN] Could not mark web request {request_id} running: {e}")
        return False, None, "❌ The bot couldn't record the request — please try again."
    _spawn_background(
        _run_web_game_lifecycle(request_id, action, key, actor, state, kwargs),
        label=f"web {action} {key}",
    )
    return WEB_REQUEST_RUNNING, None, None


async def _run_web_game_lifecycle(request_id: str, action: str, key: str, actor, state: dict, kwargs: dict):
    guild = bot.get_guild(cur_gid())

    async def progress(text) -> None:
        line = str(text or "").strip()
        if not line:
            return
        state["steps"].append({"text": line[:400], "ts": int(time.time())})
        try:
            await _run_mysql_io(
                _update_web_request_progress_mysql, request_id, {"lifecycle": state}, label="web lifecycle progress"
            )
        except Exception as e:
            print(f"[WARN] web lifecycle progress write failed for {request_id}: {e}")

    status, error = "done", None
    try:
        if action == "game_start":
            outcome = await _game_start_core(guild, actor, key, progress=progress, **kwargs)
        elif action == "game_end":
            outcome = await _game_end_core(guild, actor, key, progress=progress)
        else:
            outcome = await _game_cancel_core(guild, actor, key, progress=progress, **kwargs)
        state.update(outcome or {})
        state["state"] = "done"
    except GameLifecycleError as e:
        status, error = "error", str(e)
        state["state"] = "error"
    except Exception as e:
        import traceback
        traceback.print_exc()
        verb = {"game_start": "starting", "game_end": "ending", "game_cancel": "cancelling"}.get(action, "running")
        status, error = "error", f"❌ The bot hit an error while {verb} the game: {e}"[:600]
        state["state"] = "error"
    finally:
        _web_lifecycle_running.discard(key)
    state["finished_at"] = int(time.time())
    try:
        await _run_mysql_io(
            _finish_web_schedule_request_mysql, request_id, status, {"lifecycle": state}, error,
            label="web lifecycle finish",
        )
        if action == "game_start":
            await _run_mysql_io(
                _scrub_web_request_payload_mysql, request_id, ("password",), label="web lifecycle scrub"
            )
    except Exception as e:
        print(f"[WARN] web lifecycle finish write failed for {request_id}: {e}")
    _audit_log("INFO", f"web {action} game={key} by={getattr(actor, 'id', '?')} -> {status}")


# ==========================================================================
# WEB GAME ACCESS — who may reserve in an announced / running game, from the
# website's Games page (formerly /lock, /unlock, /lockdown, /nation_lock,
# /nation_unlock and /clear). Same game fields the commands used; only the
# game's host or Host Management may change them (the commands let any host).
# ==========================================================================
WEB_ACCESS_LEVELS = ("VIP", "Trusted", "Verified", "All Users")


def _web_access_label(level: str) -> str:
    return "Everyone" if level == "All Users" else _lock_label(level)


async def _process_web_game_access(req: dict):
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None or not _member_is_host(actor):
        return False, None, "❌ Only hosts can change reservation access."
    thread_id = str(payload.get("thread_id") or "").strip()
    games = await _read_games_fresh()
    key, game = _find_game_entry(games, thread_id)
    if not game:
        return False, None, "❌ Game not found — it may have been removed."
    key = str(key or thread_id)
    if not _can_end_assigned_game(actor, game):
        return False, None, f"❌ Only the game's host (<@{game.get('host_id')}>) or Host Management can do that."
    if str(game.get("status") or "").strip().lower() in ("ended", "cancelled"):
        return False, None, "❌ This game has ended or was cancelled."
    if key in _web_lifecycle_running:
        return False, None, "ℹ️ This game is being started, ended or cancelled — try again in a moment."

    op = str(payload.get("op") or "")
    mode = game.get("mode", "")
    notes: list[str] = []
    rewrite = False
    if op == "levels":
        major = str(payload.get("major_level") or "")
        minor = str(payload.get("minor_level") or "")
        if major not in WEB_ACCESS_LEVELS or minor not in WEB_ACCESS_LEVELS:
            return False, None, "❌ Pick who may reserve: VIP+, Trusted+, Verified+ or everyone."
        game["major_lock_level"] = major
        game["minor_lock_level"] = minor
        title = "🔒 Reservation access updated"
        summary = f"Majors: {_web_access_label(major)} · Minors: {_web_access_label(minor)}"
        if game.get("game_started"):
            notes.append("The game has started, so reservations are already closed — this applies if it's reopened.")
    elif op == "lockdown":
        enabled = bool(payload.get("enabled"))
        game["lockdown"] = enabled
        title = "🔒 Lockdown on" if enabled else "🔓 Lockdown off"
        summary = (
            "Players can't reserve on the website. Host tools still work."
            if enabled else "Public reservations are open again."
        )
    elif op in ("nation_lock", "nation_unlock"):
        nation = str(payload.get("nation") or "").strip()
        locked = [str(n) for n in (game.get("locked_regions") or [])]
        if op == "nation_lock":
            if mode != "Other":
                valid = _get_mode_nation_data(mode)[0]
                match = next((n for n in valid if n.lower() == nation.lower()), None)
                if match is None:
                    return False, None, f"❌ '{nation}' isn't a nation in {mode}."
                nation = match
            if not nation:
                return False, None, "❌ Pick a nation."
            if nation in locked:
                return False, None, f"ℹ️ **{nation}** is already locked."
            locked.append(nation)
            holder = (game.get("reservations") or {}).get(nation)
            if holder:
                guild = bot.get_guild(cur_gid())
                holder_member = guild.get_member(int(holder)) if guild is not None and str(holder).isdigit() else None
                who = holder_member.display_name if holder_member is not None else "A player"
                notes.append(f"{who} already holds {nation} — locking doesn't remove them.")
            title, summary = "🔒 Nation locked", f"**{nation}** can't be reserved (it shows ⚫ on the list)."
        else:
            match = next((n for n in locked if n.lower() == nation.lower()), None)
            if match is None:
                return False, None, f"ℹ️ **{nation}** isn't locked."
            if match in (game.get("layout_disabled_nations") or []):
                return False, None, (
                    f"❌ **{match}** isn't playable in this game (its preset leaves it out), so it can't be unlocked."
                )
            locked.remove(match)
            title, summary = "🔓 Nation unlocked", f"**{match}** can be reserved again."
        game["locked_regions"] = locked
    elif op == "clear":
        if game.get("game_started"):
            return False, None, (
                "❌ The game has started — clearing it would break its attendance. "
                "Remove players one by one, or cancel the game."
            )
        count = len({str(v) for v in (game.get("reservations") or {}).values()})
        game["reservations"] = {}
        rewrite = True
        title, summary = "🧹 Reservation list cleared", f"Removed {count} player(s) from the list."
    else:
        return False, None, f"❌ Unknown access change: {op}."

    await save_single_game(key, game, rewrite_reservations=rewrite)
    try:
        schedule_reservation_update(int(key))
        if op == "clear":
            schedule_log_update(int(key))
    except Exception as e:
        print(f"[WARN] web access: list refresh failed for {key}: {e}")
    _audit_log("INFO", f"web access {op} game={key} by={actor.id} payload={json.dumps(payload, ensure_ascii=False)[:300]}")
    return True, {"access": {"title": title, "summary": summary, "notes": notes, "stats": {}, "log_url": None}}, None


# /lock, /unlock, /lockdown, /nation_lock, /nation_unlock and /clear moved to
# the website's Games page (_process_web_game_access above).


# ==========================================================================
# WEB GAME REMINDERS (formerly /remind) — from the website's Games page.
#   early: before the start, DM every reserved player the start time, their
#          nation and what a no-show costs (counts as the automatic one-hour
#          reminder, so players don't get both).
#   late:  after the start, DM every reserved player who isn't in a game voice
#          channel with the Gamer Pass yet, and post the list in the thread.
# ==========================================================================
def _reminder_slot_label(key: str) -> str:
    if key.startswith("_FILL_"):
        return key[6:].replace("_", " ")
    if "_coop" in key:
        return f"{key.split('_coop')[0]} (Co-op)"
    return key


async def _send_game_reminder(guild, actor, key: str, game: dict, kind: str) -> dict:
    """Send one reminder round; returns {title, summary, notes} (raises ModerationError)."""
    mode = game.get("mode") or "Game"
    reservations = {str(k): v for k, v in (game.get("reservations") or {}).items()}
    if not reservations:
        raise ModerationError("⚠️ Nobody has reserved a nation yet — there's no one to remind.")
    start_ts = int(game.get("start_timestamp") or 0)
    by_user: dict[int, list[str]] = {}
    for slot, raw_uid in reservations.items():
        if str(raw_uid).isdigit():
            by_user.setdefault(int(raw_uid), []).append(slot)

    if kind == "early":
        if game.get("game_started"):
            raise ModerationError("ℹ️ The game has started — send a late reminder instead.")
        when = f"<t:{start_ts}:F> (<t:{start_ts}:R>)" if start_ts else "soon"
        checksum = game.get("scheduled_checksum")
        targets = list(by_user.items())
        sent = failed = 0
        for uid, slots in targets:
            member = guild.get_member(uid)
            if member is None:
                failed += 1
                continue
            penalty = max(
                (_attendance_no_show_penalty(s, mode, game.get("logging_mode", "Strict")) for s in slots),
                default=0,
            )
            penalty_text = (
                "Casual logging excuses this reservation from no-show warnings." if penalty == 0
                else "Failure to attend results in **2 Warnings** (Major Nation)." if penalty == 2
                else "Failure to attend results in **1 Warning**."
            )
            content = (
                f"⏰ **Game Reminder: {mode}**\n\n"
                f"🏳️ **Nation:** {', '.join(_reminder_slot_label(s) for s in slots)}\n"
                f"⏳ **Start Time:** The game starts {when}!\n"
                + (f"🔢 **Checksum:** `{checksum}`\n" if checksum else "")
                + f"\n⚠️ **Requirement:** You must show up for the game. {penalty_text}\n"
                f"🚪 **Can't make it?** Unreserve on the website as soon as possible: {_map_game_url(key)}\n\n"
                f"🆘 **Need Help?** Use `/help` in any {_community_name()} Discord channel for rules & mods."
            )
            if await _dm_user_safe(member, content=content, label="early reminder"):
                sent += 1
            else:
                failed += 1
        title = "⏰ Early reminder sent"
        notes = ["Counts as the automatic one-hour reminder — players won't get both."]
    elif kind == "late":
        if not game.get("game_started"):
            raise ModerationError("ℹ️ The game hasn't started — send an early reminder instead.")
        role_id = game.get("temp_gamer_pass_role")
        pass_role = guild.get_role(int(role_id)) if role_id else None
        if pass_role is None:
            raise ModerationError("❌ This game's Gamer Pass role is gone — the bot can't tell who is in voice.")
        in_voice = {m.id for vc in guild.voice_channels for m in vc.members if pass_role in m.roles}
        targets = [(uid, slots) for uid, slots in by_user.items() if uid not in in_voice]
        if not targets:
            return {"title": "✅ Everyone is here", "summary": "All reserved players are in voice with the Gamer Pass.", "notes": []}
        when = f"<t:{start_ts}:R>" if start_ts and start_ts > time.time() else "now"
        sent = failed = 0
        for uid, slots in targets:
            member = guild.get_member(uid)
            label = ", ".join(_reminder_slot_label(s) for s in slots)
            content = (
                f"🔔 **Late Reminder for {mode}:**\n"
                f"You have reserved **{label}**, and the game is starting **{when}**!\n\n"
                "⚠️ **Warning:** If you are not in the Game Lobby, you will receive automated no-show warnings."
            )
            if member is not None and await _dm_user_safe(member, content=content, label="late reminder"):
                sent += 1
            else:
                failed += 1
        thread = await _resolve_game_thread(guild, key)
        if thread is not None:
            lines = ["# Waiting for players... ⏳", "Please join the Game Lobby to avoid penalties.\n"]
            lines += [f"* **{', '.join(_reminder_slot_label(s) for s in slots)}**: <@{uid}>" for uid, slots in targets]
            text = "\n".join(lines)
            try:
                for chunk in [text[i:i + 2000] for i in range(0, len(text), 2000)]:
                    await thread.send(content=chunk)
            except Exception as e:
                print(f"[WARN] late reminder list post failed for {key}: {e}")
        title = "🔔 Late reminder sent"
        notes = [f"{len(targets)} player(s) weren't in voice with the Gamer Pass."]
    else:
        raise ModerationError("❌ Pick an early or a late reminder.")

    games = await _load_games_resilient()
    fresh_key, fresh = _find_game_entry(games, key)
    if fresh is not None:
        history = list(fresh.get("reminder_history") or [])
        history.append({"kind": kind, "ts": int(time.time()), "by": str(getattr(actor, "id", "")), "sent": sent, "failed": failed})
        fresh["reminder_history"] = history[-20:]
        if kind == "early" and not fresh.get("automatic_reminder_sent_at"):
            fresh["automatic_reminder_sent_at"] = int(time.time())
        await save_single_game(fresh_key or key, fresh, rewrite_reservations=False)
    summary = f"DMed {sent} player(s)." + (f" {failed} couldn't be reached (DMs closed or left the server)." if failed else "")
    return {"title": title, "summary": summary, "notes": notes}


async def _process_web_game_remind(req: dict):
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None or not _member_is_host(actor):
        return False, None, "❌ Only hosts can send reminders."
    thread_id = str(payload.get("thread_id") or "").strip()
    games = await _load_games_resilient()
    key, game = _find_game_entry(games, thread_id)
    if not game:
        return False, None, "❌ Game not found — it may have been removed."
    key = str(key or thread_id)
    if not _can_end_assigned_game(actor, game):
        return False, None, f"❌ Only the game's host (<@{game.get('host_id')}>) or Host Management can do that."
    if str(game.get("status") or "").strip().lower() in ("ended", "cancelled"):
        return False, None, "❌ This game has ended or was cancelled."
    try:
        outcome = await _send_game_reminder(bot.get_guild(cur_gid()), actor, key, game, str(payload.get("kind") or ""))
    except ModerationError as e:
        return False, None, str(e)
    _audit_log("INFO", f"web reminder {payload.get('kind')} game={key} by={actor.id}: {outcome['summary']}")
    return True, {"reminder": {**outcome, "stats": {}, "log_url": None}}, None


# ==========================================================================
# WEB HOST MESSAGES (formerly /dm and /dm_participants) — from the website.
#   host_dm:      any host DMs one member from their Database record —
#                 anonymous ("a Game Host") unless they sign it. Logged in the
#                 host log channel and the host_messages table.
#   game_message: the game's host (or Host Management) DMs the players of one
#                 game from the Games page — everyone, or the ones they tick
#                 (reserved players, co-ops, fillers and the draft pool).
#                 Runs in the background with progress; the game keeps its
#                 last messages in message_history.
# ==========================================================================
HOST_MESSAGE_MAX_LEN = 2000
GAME_MESSAGE_HISTORY_KEEP = 20


def _insert_host_message_mysql(sender_id: int, recipient_id: int, message: str, signed: bool, delivered: bool) -> None:
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        cur.execute(
            "INSERT INTO host_messages (guild_id, sender_id, recipient_id, message, signed, delivered, created_at) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s)",
            (str(cur_gid()), str(sender_id), str(recipient_id), message, 1 if signed else 0, 1 if delivered else 0, int(time.time())),
        )
        conn.commit()
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _host_message_text(payload: dict) -> tuple[str | None, str | None]:
    """The message from a web payload → (text, error)."""
    text = str(payload.get("message") or "").strip()
    if not text:
        return None, "❌ Write a message first."
    if len(text) > HOST_MESSAGE_MAX_LEN:
        return None, f"❌ Messages can be at most {HOST_MESSAGE_MAX_LEN} characters."
    return text, None


async def _post_host_log_embed(embed: discord.Embed, label: str) -> None:
    channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
    if channel is None:
        return
    try:
        await channel.send(embed=embed)
    except Exception as e:
        print(f"[WARN] {label} host log post failed: {e}")


def _game_message_recipients(game: dict) -> dict[int, str]:
    """Everyone a game message can reach → what they are in the game
    ("Germany", "Italy (Co-op)", "Filler", "Draft pool")."""
    labels: dict[int, list[str]] = {}
    for slot, raw_uid in (game.get("reservations") or {}).items():
        if str(raw_uid).isdigit():
            labels.setdefault(int(raw_uid), []).append(_reminder_slot_label(str(slot)))
    for raw_uid in ((game.get("draft") or {}).get("pool") or {}):
        if str(raw_uid).isdigit() and int(raw_uid) not in labels:
            labels[int(raw_uid)] = ["Draft pool"]
    return {uid: ", ".join(slots) for uid, slots in labels.items()}


async def _process_web_host_dm(req: dict):
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None or not _member_is_host(actor):
        return False, None, "❌ Only hosts can message members."
    text, error = _host_message_text(payload)
    if error:
        return False, None, error
    raw_uid = str(payload.get("user_id") or "").strip()
    if not raw_uid.isdigit():
        return False, None, "❌ Pick who to message."
    if int(raw_uid) == actor.id:
        return False, None, "❌ You can't message yourself."
    member = await _web_fetch_member(int(raw_uid))
    if member is None:
        return False, None, "❌ They're not in the server — the bot can't DM them."
    if member.bot:
        return False, None, "❌ That's a bot — it can't read messages."
    signed = bool(payload.get("signed"))

    embed = discord.Embed(
        title=f"📩 Message from {actor.display_name} (Game Host)" if signed else "📩 Message from a Game Host",
        description=text,
        color=discord.Color.gold(),
    )
    embed.set_footer(text="This message was sent via the Game Master bot.")
    delivered = await _dm_user_safe(member, embed=embed, label="host message")

    try:
        await _run_mysql_io(
            _insert_host_message_mysql, actor.id, member.id, text, signed, delivered, label="host message record"
        )
    except Exception as e:
        print(f"[WARN] host message record failed: {e}")
    log = discord.Embed(title="📝 Host DM", color=discord.Color.light_grey() if delivered else discord.Color.red())
    log.add_field(name="Sender", value=actor.mention, inline=True)
    log.add_field(name="Recipient", value=member.mention, inline=True)
    log.add_field(name="Shown as", value=actor.display_name if signed else "Anonymous (a Game Host)", inline=True)
    log.add_field(name="Content", value=text[:1024], inline=False)
    if not delivered:
        log.add_field(name="Not delivered", value="Their DMs are closed.", inline=False)
    log.set_footer(text="Sent from the website")
    log.timestamp = datetime.datetime.now(datetime.timezone.utc)
    await _post_host_log_embed(log, "host DM")
    _audit_log("INFO", f"web host DM to={member.id} by={actor.id} signed={signed} delivered={delivered}")

    if not delivered:
        return False, None, f"❌ Couldn't DM {member.display_name} — their DMs are probably closed. (It's in the host log.)"
    return True, {
        "message": {
            "title": "📩 Message sent",
            "summary": f"{member.display_name} got your message " + ("with your name on it." if signed else "from \"a Game Host\"."),
            "notes": ["It's in the host log."],
            "stats": {},
            "log_url": None,
        }
    }, None


async def _process_web_game_message(req: dict):
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None or not _member_is_host(actor):
        return False, None, "❌ Only hosts can message players."
    text, error = _host_message_text(payload)
    if error:
        return False, None, error
    thread_id = str(payload.get("thread_id") or "").strip()
    games = await _load_games_resilient()
    key, game = _find_game_entry(games, thread_id)
    if not game:
        return False, None, "❌ Game not found — it may have been removed."
    key = str(key or thread_id)
    if not _can_end_assigned_game(actor, game):
        return False, None, f"❌ Only the game's host (<@{game.get('host_id')}>) or Host Management can message its players."
    everyone = _game_message_recipients(game)
    if not everyone:
        return False, None, "⚠️ Nobody has signed up for this game yet — there's no one to message."
    picked = payload.get("recipients")
    if isinstance(picked, list):
        wanted = {int(v) for v in picked if str(v).isdigit()}
        targets = [(uid, label) for uid, label in everyone.items() if uid in wanted]
        skipped = len(wanted) - len(targets)
    else:
        targets, skipped = list(everyone.items()), 0
    if not targets:
        return False, None, "❌ None of the players you picked are in this game any more."

    request_id = str(req.get("request_id") or "")
    try:
        await _run_mysql_io(
            _update_web_request_progress_mysql, request_id,
            {"message": {"state": "running", "sent": 0, "failed": 0, "total": len(targets), "started_at": int(time.time())}},
            label="game message start",
        )
    except Exception as e:
        print(f"[WARN] Could not mark game message {request_id} running: {e}")
        return False, None, "❌ The bot couldn't record the request — please try again."
    _spawn_background(
        _run_web_game_message(request_id, actor, key, game, text, targets, skipped), label=f"game message {key}"
    )
    return WEB_REQUEST_RUNNING, None, None


async def _run_web_game_message(request_id: str, actor, key: str, game: dict, text: str, targets: list, skipped: int) -> None:
    status, result, error = "error", None, None
    try:
        guild = bot.get_guild(cur_gid())
        mode = game.get("mode") or "game"
        open_thread = str(game.get("status") or "").lower() not in ("ended", "cancelled")
        embed = discord.Embed(title=f"📢 Message from the host of your {mode} game", description=text, color=discord.Color.gold())
        if open_thread and _game_has_thread(game):
            embed.add_field(name="Game thread", value=f"<#{key}>", inline=True)
        embed.add_field(name="On the website", value=_map_game_url(key), inline=True)
        embed.set_footer(text="Sent to this game's players via the Game Master bot.")

        sent = 0
        unreachable: list[str] = []
        for index, (uid, label) in enumerate(targets, start=1):
            member = guild.get_member(uid) if guild is not None else None
            if member is not None and await _dm_user_safe(member, embed=embed, label="game message"):
                sent += 1
            else:
                who = member.display_name if member is not None else f"#{uid} (left the server)"
                unreachable.append(f"{who} — {label}")
            if index % 5 == 0 and index < len(targets):
                try:
                    await _run_mysql_io(
                        _update_web_request_progress_mysql, request_id,
                        {"message": {"state": "running", "sent": sent, "failed": len(unreachable), "total": len(targets),
                                     "started_at": int(time.time())}},
                        label="game message progress",
                    )
                except Exception:
                    pass

        games = await _load_games_resilient()
        fresh_key, fresh = _find_game_entry(games, key)
        if fresh is not None:
            history = list(fresh.get("message_history") or [])
            history.append({
                "ts": int(time.time()), "by": str(actor.id), "text": text[:500],
                "sent": sent, "failed": len(unreachable), "total": len(targets),
            })
            fresh["message_history"] = history[-GAME_MESSAGE_HISTORY_KEEP:]
            await save_single_game(fresh_key or key, fresh, rewrite_reservations=False)

        log = discord.Embed(title="📢 Game message", color=discord.Color.purple())
        log.add_field(name="Sender", value=actor.mention, inline=True)
        log.add_field(
            name="Game", value=f"<#{key}>" if open_thread and _game_has_thread(game) else f"{mode} ({key})", inline=True,
        )
        log.add_field(name="Delivered", value=f"{sent} of {len(targets)} player(s)", inline=True)
        log.add_field(name="Message", value=text[:1024], inline=False)
        if unreachable:
            failed_text = ", ".join(unreachable)
            log.add_field(name="Not delivered", value=failed_text[:1000] + ("…" if len(failed_text) > 1000 else ""), inline=False)
        log.set_footer(text="Sent from the website")
        log.timestamp = datetime.datetime.now(datetime.timezone.utc)
        await _post_host_log_embed(log, "game message")
        _audit_log("INFO", f"web game message game={key} by={actor.id} sent={sent}/{len(targets)}")

        notes = [f"Couldn't reach {who} (DMs closed or left the server)." for who in unreachable[:10]]
        if len(unreachable) > 10:
            notes.append(f"…and {len(unreachable) - 10} more.")
        if skipped:
            notes.append(f"{skipped} of the players you picked aren't in this game any more — skipped.")
        status = "done"
        result = {
            "message": {
                "title": "📢 Message sent",
                "summary": f"DMed {sent} of {len(targets)} player(s).",
                "notes": notes,
                "stats": {},
                "log_url": None,
            }
        }
    except Exception as e:
        print(f"[ERROR] web game message {key} failed: {e}")
        status, result, error = "error", None, f"❌ Sending stopped with an error: {e}"
    try:
        await _run_mysql_io(_finish_web_schedule_request_mysql, request_id, status, result, error, label="game message ack")
    except Exception as e:
        print(f"⚠️ game message ack failed: {e}")



# ————— Games page: chat-log upload + AI analysis (replaces the Host Control
# Center's "Upload Chat Log" / "Run AI Analysis"). The website stores the
# .txt in game_chat_logs; the bot grades it, archives it, tells the players. —————
_GAME_CHAT_LOGS_DDL = """
CREATE TABLE IF NOT EXISTS game_chat_logs (
    game_id VARCHAR(32) NOT NULL PRIMARY KEY,
    guild_id VARCHAR(32) NOT NULL,
    filename VARCHAR(200) NOT NULL,
    content MEDIUMTEXT NOT NULL,
    bytes INT NOT NULL,
    uploaded_by BIGINT NOT NULL,
    uploaded_at BIGINT NOT NULL,
    INDEX idx_game_chat_logs_guild (guild_id)
)
"""


def _profile_url(gid=None) -> str:
    return f"{WEB_SITE_URL}/profile?guild={gid or cur_gid()}"


def _load_game_chat_log_mysql(game_ids: list) -> dict | None:
    _guild_settings_query_mysql(_GAME_CHAT_LOGS_DDL, commit=True)
    for game_id in dict.fromkeys(str(g) for g in game_ids if g):
        row = _guild_settings_query_mysql(
            "SELECT filename, content, bytes, CAST(uploaded_by AS CHAR) AS uploaded_by, uploaded_at "
            "FROM game_chat_logs WHERE game_id = %s",
            (game_id,), fetch="one",
        )
        if row:
            return row
    return None


async def _process_web_game_log_analysis(req: dict):
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None or not _member_is_host(actor):
        return False, None, "❌ Only hosts can run the AI analysis."
    thread_id = str(payload.get("thread_id") or "").strip()
    games = await _load_games_resilient()
    key, game = _find_game_entry(games, thread_id)
    if not game:
        return False, None, "❌ Game not found — it may have been removed."
    key = str(key or thread_id)
    if not _can_end_assigned_game(actor, game):
        return False, None, f"❌ Only the game's host (<@{game.get('host_id')}>) or Host Management can run its AI analysis."
    if not game.get("game_started") and str(game.get("status") or "").lower() != "ended":
        return False, None, "❌ The game hasn't started yet — upload the chat log once it's played."
    if not client:
        return False, None, "❌ The AI isn't set up on this bot (GENAI_API_KEY is missing)."
    log = await _run_mysql_io(lambda: _load_game_chat_log_mysql([key, thread_id]), label="chat log read")
    if not log or not str(log.get("content") or "").strip():
        return False, None, "❌ Upload the game's chat log (.txt) first."
    request_id = str(req.get("request_id") or "")
    try:
        await _run_mysql_io(
            _update_web_request_progress_mysql, request_id,
            {"analysis": {"state": "running", "started_at": int(time.time())}},
            label="AI analysis start",
        )
    except Exception as e:
        print(f"[WARN] Could not mark AI analysis {request_id} running: {e}")
        return False, None, "❌ The bot couldn't record the request — please try again."
    _spawn_background(_run_web_game_log_analysis(request_id, actor, key, game, log), label=f"AI analysis {key}")
    return WEB_REQUEST_RUNNING, None, None


async def _archive_game_chat_log(game: dict, key: str, text: str, filename: str) -> tuple[bool, int]:
    """Post the log to the mode's public archive and tell the players (once per upload)."""
    mode = game.get("mode", "Roleplay")
    archive_id = (MODE_CONFIG.get(mode) or {}).get("public_log_channel_id") or _public_log_channel_for_base(
        game.get("base_mode", "Roleplay")
    )
    channel = bot.get_channel(int(archive_id)) if archive_id else None
    posted = False
    if channel is not None:
        lobby_ref = game.get("lobby_thread_id") or game.get("original_thread_id") or key
        try:
            await channel.send(
                content=(
                    f"📁 **Public Log Archive** | {mode}\n"
                    f"**Date:** {datetime.datetime.now().strftime('%m.%d.%Y')} | **Host:** <@{game.get('host_id')}>\n"
                    f"**Thread:** <#{lobby_ref}>\n**Game-ID:** `{key}`\n\n"
                    f"✨ *Your AI result for this game is on your profile: {_profile_url()}*"
                ),
                file=discord.File(fp=io.BytesIO(text.encode("utf-8")), filename=filename),
            )
            posted = True
        except Exception as e:
            print(f"[WARN] chat log archive post failed: {e}")
    guild = bot.get_guild(cur_gid())
    notified = 0
    where = f" in <#{archive_id}>" if posted else ""
    for uid in {str(v) for v in (game.get("reservations") or {}).values() if str(v).isdigit()}:
        member = guild.get_member(int(uid)) if guild is not None else None
        if member is None:
            continue
        if await _dm_user_safe(
            member,
            content=(
                f"📁 The chat log for your **{mode}** game is archived{where}.\n"
                f"Your AI result is on your profile: {_profile_url()}"
            ),
            label="chat log archive",
        ):
            notified += 1
    return posted, notified


async def _run_web_game_log_analysis(request_id: str, actor, key: str, game: dict, log: dict) -> None:
    status, result, error = "error", None, None
    try:
        text = str(log.get("content") or "")
        filename = str(log.get("filename") or "chat_log.txt")
        uploaded_at = int(log.get("uploaded_at") or 0)
        analysis = await run_ai_log_analysis(text, game.get("reservations") or {}, bot.get_guild(cur_gid()))
        if isinstance(analysis, str):
            error = analysis
        else:
            analysis["by"] = str(actor.id)
            analysis["log"] = {"filename": filename, "bytes": len(text.encode("utf-8")), "uploaded_at": uploaded_at}
            games = await _load_games_resilient()
            fresh_key, fresh = _find_game_entry(games, key)
            target = fresh if fresh is not None else game
            first_time = int(target.get("chat_log_archived_upload") or 0) != uploaded_at
            target["ai_analysis"] = analysis
            target["ai_analysis_text"] = _render_ai_analysis_text(analysis)
            target["ai_analysis_at"] = analysis["at"]
            if first_time:
                target["chat_log_archived_upload"] = uploaded_at
            await save_single_game(fresh_key or key, target, rewrite_reservations=False)

            notes = []
            if first_time:
                posted, notified = await _archive_game_chat_log(target, key, text, filename)
                notes.append("Archived the log in the public log channel." if posted else "Couldn't post to the public log archive.")
                notes.append(f"Told {notified} player(s) their result is on their profile.")
            host_log = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
            if host_log is not None:
                try:
                    await _post_attendance_log_mismatch_review(host_log, target, text, int(target.get("host_id") or actor.id))
                except Exception as e:
                    print(f"[WARN] chat-log attendance hints failed: {e}")
            players = analysis["players"]
            commends = sum(p["reward"]["commends"] for p in players)
            merit = sum(p["reward"]["merit"] for p in players)
            rewarded = sum(1 for p in players if p["reward"]["commends"] or p["reward"]["merit"])
            embed = discord.Embed(title="🤖 AI chat-log analysis", color=discord.Color.blurple())
            embed.add_field(name="Game", value=f"{target.get('mode') or 'Game'} (`{key}`)", inline=True)
            embed.add_field(name="Run by", value=actor.mention, inline=True)
            embed.add_field(
                name="Recommended",
                value=f"{rewarded} of {len(players)} player(s): {commends} commend(s), {merit} Merit",
                inline=False,
            )
            embed.set_footer(text="Review and give rewards on the website's Games page")
            await _post_host_log_embed(embed, "AI analysis")
            await _post_to_game_log_thread(fresh_key or key, target, embed=embed)
            _audit_log("INFO", f"web AI analysis game={key} by={actor.id} rewarded={rewarded}/{len(players)}")
            status = "done"
            result = {"analysis": {
                "title": "🤖 AI analysis done",
                "summary": f"{rewarded} of {len(players)} player(s) recommended: {commends} commend(s), {merit} Merit.",
                "notes": notes,
                "stats": {},
                "log_url": None,
            }}
    except Exception as e:
        print(f"[ERROR] web AI analysis {key} failed: {e}")
        status, result, error = "error", None, f"❌ The AI analysis stopped with an error: {e}"
    try:
        await _run_mysql_io(_finish_web_schedule_request_mysql, request_id, status, result, error, label="AI analysis ack")
    except Exception as e:
        print(f"⚠️ AI analysis ack failed: {e}")


async def _mark_ai_reward_given(game_id: str, user_id: str, kind: str, amount: int, actor_id: int) -> None:
    """A host gave an AI-recommended reward from the Games page: remember it on the game."""
    try:
        games = await _load_games_resilient()
        key, game = _find_game_entry(games, game_id)
        if not game:
            return
        given = dict(game.get("ai_rewards_given") or {})
        given[str(user_id)] = {"kind": kind, "amount": int(amount), "by": str(actor_id), "at": int(time.time())}
        game["ai_rewards_given"] = given
        await save_single_game(key or game_id, game, rewrite_reservations=False)
    except Exception as e:
        print(f"[WARN] recording AI reward for {user_id} failed: {e}")


