# FORCE LOGGING & RESERVATION MANAGEMENT COMMANDS (Host Only)
async def modify_attendance(interaction: discord.Interaction, target_thread_id: str, action: str, user: discord.Member, nation: str = None):
    """Legacy host-panel Mark Present / Mark Absent — now the same engine as
    the web Attendance page (mode-aware warnings, audit log, host log)."""
    if not interaction.response.is_done():
        await interaction.response.defer(ephemeral=True)
    try:
        result = await apply_attendance_override(
            guild=interaction.guild,
            actor=interaction.user,
            game_id=str(target_thread_id),
            user_id=user.id,
            verdict="present" if action == "add" else "absent",
            reason="Changed from the Discord host panel",
        )
    except ModerationError as e:
        return await interaction.followup.send(str(e), ephemeral=True)
    lines = [f"✅ {result['summary']}"] + [f"• {note}" for note in result["notes"]]
    await interaction.followup.send("\n".join(lines), ephemeral=True)


# ==========================================================================
# WEB ATTENDANCE — overrides and the web request handlers
# --------------------------------------------------------------------------
# Hosts manage attendance on the web Attendance page; the bot does the
# Discord side (voice scans, roles, DMs, warnings) and keeps the record:
#   att_check     live voice check (doesn't count as a sample)
#   att_sample    take the next of the 5 samples now
#   att_override  Present / Absent / Excused (+ reason) for one player —
#                 before finalize it's stored and applied at finalize; after
#                 finalize it changes the result at once and applies or
#                 reverses the no-show warning (mode-aware, VIP immune).
#   att_finalize  finalize early from the samples taken (≥ 2)
# Only the game's assigned host or Host Management can change attendance; any
# host can view it and run a voice check.
# ==========================================================================
ATTENDANCE_VERDICTS = ("present", "absent", "excused", "auto")


def _attendance_current_verdict(game: dict, uid: int) -> str:
    override = (game.get("attendance_overrides") or {}).get(str(uid)) or {}
    if override.get("verdict") == "excused":
        return "excused"
    if uid in _normalize_uid_set(game.get("present_ids", [])):
        return "present"
    if uid in {int(x) for x in game.get("dropped_out", []) if str(x).isdigit()}:
        return "excused"
    return "absent"


async def apply_attendance_override(*, guild, actor, game_id: str, user_id: int, verdict: str, reason: str) -> dict:
    """Set one player's attendance verdict. Raises ModerationError when refused."""
    if verdict not in ATTENDANCE_VERDICTS:
        raise ModerationError("❌ Pick Present, Absent or Excused.")
    reason = (reason or "").strip()
    if len(reason) < 3:
        raise ModerationError("❌ Please give a reason (at least a few words).")
    games = await _load_games_resilient()
    key, game = _find_game_entry(games, game_id)
    if not game:
        raise ModerationError("❌ Game not found.")
    if actor is None or not _can_end_assigned_game(actor, game):
        raise ModerationError("❌ Only the game's host or Host Management can change its attendance.")
    if not game.get("game_started"):
        raise ModerationError("⚠️ This game hasn't started — there's no attendance yet.")
    uid = int(user_id)
    if not any(str(v) == str(uid) for v in (game.get("reservations") or {}).values()):
        raise ModerationError("❌ That player has no reservation in this game.")

    stable_id = _attendance_stable_id(game, key)
    lock = _attendance_finalize_locks.setdefault(stable_id, asyncio.Lock())
    labels = {"present": "Present", "absent": "Absent", "excused": "Excused", "auto": "Automatic"}
    notes: list[str] = []
    async with lock:
        games = await _load_games_resilient()
        key, game = _find_game_entry(games, key or game_id)
        if not game:
            raise ModerationError("❌ Game not found.")
        overrides = dict(game.get("attendance_overrides") or {})
        finalized = bool(game.get("snapshot_done"))
        before = _attendance_current_verdict(game, uid) if finalized else (overrides.get(str(uid)) or {}).get("verdict", "auto")

        if not finalized:
            # Stored now, applied when attendance is finalized.
            if verdict == "auto":
                overrides.pop(str(uid), None)
                notes.append("Back to automatic — the samples decide.")
            else:
                overrides[str(uid)] = {"verdict": verdict, "reason": reason, "by": str(actor.id), "ts": int(time.time())}
                notes.append("Saved — it applies when attendance is finalized.")
            game["attendance_overrides"] = overrides
            await save_single_game(key or str(game_id), game, rewrite_reservations=False)
            summary = f"{labels[verdict]} (applies at finalize)"
        else:
            if verdict == "auto":
                raise ModerationError("ℹ️ Attendance is finalized — pick Present, Absent or Excused.")
            if verdict == before:
                raise ModerationError(f"ℹ️ They're already {labels[verdict].lower()}.")
            notes += await _apply_finalized_attendance_change(guild, game, uid, before, verdict, reason, actor)
            overrides[str(uid)] = {"verdict": verdict, "reason": reason, "by": str(actor.id), "ts": int(time.time())}
            game["attendance_overrides"] = overrides
            await save_single_game(key or str(game_id), game, rewrite_reservations=False)
            summary = f"{labels[before]} → {labels[verdict]}"

    record_attendance_event(
        stable_id, "override", user_id=uid, actor_id=actor.id,
        details={"from": before, "to": verdict, "reason": reason, "finalized": finalized, "notes": notes},
    )
    if finalized:
        try:
            schedule_log_update(int(key or game_id))
        except Exception:
            pass
        try:
            embed = discord.Embed(title="📝 Attendance changed", color=discord.Color.blue(), url=_attendance_page_url(stable_id))
            embed.add_field(name="Player", value=f"<@{uid}>", inline=True)
            embed.add_field(name="Change", value=summary, inline=True)
            embed.add_field(name="Host", value=f"<@{actor.id}>", inline=True)
            embed.add_field(name="Reason", value=_trim_field(reason), inline=False)
            embed.add_field(name="Game", value=str(game.get("thread_name") or stable_id), inline=False)
            if notes:
                embed.add_field(name="Effects", value=_trim_field("\n".join(f"• {n}" for n in notes)), inline=False)
            await send_host_log_embed(embed)
        except Exception as e:
            print(f"[WARN] attendance change log failed: {e}")
    return {"title": "📝 Attendance changed", "summary": summary, "notes": notes, "stats": {}, "log_url": None}


async def _apply_finalized_attendance_change(guild, game: dict, uid: int, before: str, after: str,
                                             reason: str, actor) -> list[str]:
    """After finalize: move the player between present / absent / excused and
    apply or reverse the no-show warning (same penalty rules as finalize).
    Mutates `game`; saves the player's stats. Returns notes."""
    notes: list[str] = []
    ctx = get_mod_context(game.get("mode")) or get_mod_context("Roleplay")
    warn_key, ban_key, label = ctx["key_warn"], ctx["key_ban"], ctx["label"]
    stats = await _load_stats_for_write(str(uid))
    member = guild.get_member(uid) if guild else None
    present = _normalize_uid_set(game.get("present_ids", []))
    applied = game.setdefault("applied_warns", {})
    game.setdefault("game_warns", [])
    game.setdefault("game_bans", [])
    stable_id = _attendance_stable_id(game)

    if before == "present":
        present = [p for p in present if p != uid]
        stats["total_games"] = max(0, int(stats.get("total_games", 0) or 0) - 1)
    if after == "present":
        present = sorted(set(present) | {uid})
        stats["total_games"] = int(stats.get("total_games", 0) or 0) + 1
    game["present_ids"] = present

    if before == "absent":
        # Reverse the no-show warning this game gave them (and its auto-ban).
        given = int(applied.pop(str(uid), 0) or 0)
        if given:
            warns_before = int(stats.get(warn_key, 0) or 0)
            stats[warn_key] = max(0, warns_before - given)
            if uid in game["game_warns"]:
                game["game_warns"].remove(uid)
            notes.append(f"Removed the {given} no-show warning(s) this game gave.")
            record_moderation_event(
                uid, "warn_removed", mode=label, amount=given,
                reason=f"Attendance corrected ({after}): {reason}",
                actor_id=actor.id, thread_id=stable_id,
            )
            record_attendance_event(stable_id, "warning_reverted", user_id=uid, actor_id=actor.id, details={"amount": given})
            if stats.get(ban_key) and warns_before >= G.WARNINGS_FOR_BAN and stats[warn_key] < G.WARNINGS_FOR_BAN and uid in game["game_bans"]:
                stats[ban_key] = False
                game["game_bans"].remove(uid)
                if member is not None:
                    try:
                        role = guild.get_role(ctx["role_banned"])
                        if role and role in member.roles:
                            await member.remove_roles(role, reason=f"Attendance corrected: below {G.WARNINGS_FOR_BAN} warnings")
                    except Exception:
                        pass
                notes.append(f"Below 3 {label} warnings — the automatic game ban was lifted.")
                record_moderation_event(
                    uid, "unban", mode=label, reason="Automatic: attendance corrected, warnings below 3",
                    actor_id=actor.id, thread_id=stable_id, automatic=True,
                )
            if member is not None:
                await _dm_user_safe(
                    member,
                    content=f"✅ The host corrected your attendance for **{game.get('thread_name') or 'a game'}** — "
                            f"your {given} no-show warning(s) were removed.",
                    label="attendance corrected",
                )

    if after == "absent":
        vip = _member_has_vip(member) or _user_is_vip(guild, uid)
        penalty = 0
        if not vip:
            for slot, holder in (game.get("reservations") or {}).items():
                if str(holder) == str(uid):
                    penalty += _attendance_no_show_penalty(slot, game.get("mode"), game.get("logging_mode", "Strict"))
        if vip:
            notes.append("VIP — no no-show warning.")
        elif penalty:
            stats[warn_key] = int(stats.get(warn_key, 0) or 0) + penalty
            applied[str(uid)] = int(applied.get(str(uid), 0) or 0) + penalty
            if uid not in game["game_warns"]:
                game["game_warns"].append(uid)
            notes.append(f"No-show: +{penalty} {label} warning(s) (now {stats[warn_key]}/3).")
            record_moderation_event(
                uid, "warn", mode=label, amount=penalty,
                reason=f"No-show (host marked absent): {reason}",
                actor_id=actor.id, thread_id=stable_id, details={"kind": "no-show"},
            )
            record_attendance_event(stable_id, "no_show_warning", user_id=uid, actor_id=actor.id,
                                    details={"amount": penalty, "reason": reason})
            if stats[warn_key] >= G.WARNINGS_FOR_BAN and not stats.get(ban_key):
                stats[ban_key] = True
                if uid not in game["game_bans"]:
                    game["game_bans"].append(uid)
                if member is not None:
                    try:
                        role = guild.get_role(ctx["role_banned"])
                        if role:
                            await member.add_roles(role, reason=f"Auto-Ban: {G.WARNINGS_FOR_BAN} warns")
                    except Exception:
                        pass
                notes += await _apply_game_ban_wipe(stats, member, ctx, f"Auto-Ban: {G.WARNINGS_FOR_BAN} warns")
                notes.append(f"Reached 3 {label} warnings — automatically game banned.")
                record_moderation_event(
                    uid, "ban", mode=label, reason=f"Automatic: reached {stats[warn_key]} {label} warnings (no-show)",
                    actor_id=actor.id, thread_id=stable_id, automatic=True,
                )
            if member is not None:
                await _dm_user_safe(
                    member,
                    content=f"⚠️ The host marked you as **absent** for **{game.get('thread_name') or 'a game'}** "
                            f"and you received **{penalty} warning(s)**.\n**Reason:** {reason}\n"
                            f"Your current {label} warnings: {stats[warn_key]}/3.",
                    view=build_moderation_feedback_view(),
                    label="attendance absent",
                )
        else:
            notes.append("No warning — this slot carries no no-show penalty in this logging mode.")

    if after == "excused":
        notes.append("Excused — not counted as attended, no warning.")
    await save_mysql_player_stats(str(uid), stats)
    mark_player_summary_dirty(uid)
    return notes


async def _process_web_attendance(req: dict):
    """Web Attendance page → the bot (see the block comment above)."""
    action = req.get("action")
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None or not _member_is_host(actor):
        return False, None, "❌ Only hosts can manage attendance."
    game_id = str(payload.get("game_id") or "")
    games = await _load_games_resilient()
    key, game = _find_game_entry(games, game_id)
    if not game:
        return False, None, "❌ Game not found."
    guild = bot.get_guild(cur_gid())
    stable_id = _attendance_stable_id(game, key)
    players = len({str(v) for v in (game.get("reservations") or {}).values()})

    def outcome(title: str, summary: str, notes=None, **extra) -> tuple:
        return True, {"attendance": {"title": title, "summary": summary, "notes": notes or [], "stats": {},
                                     "log_url": None, **extra}}, None

    if action == "att_check":
        try:
            if hasattr(guild, "chunk"):
                await asyncio.wait_for(guild.chunk(cache=True), timeout=20)
        except Exception:
            pass
        present, details = _scan_voice_states(guild, game)
        check = {"ts": int(time.time()), "by": str(actor.id), "present_ids": [str(p) for p in present], "players": details}
        lock = _attendance_finalize_locks.setdefault(stable_id, asyncio.Lock())
        async with lock:
            games = await _load_games_resilient()
            key2, fresh = _find_game_entry(games, key or game_id)
            if fresh:
                fresh["attendance_live_check"] = check
                await save_single_game(key2 or key or game_id, fresh, rewrite_reservations=False)
        in_voice = sum(1 for d in details.values() if d.get("state") == "present")
        record_attendance_event(stable_id, "live_check", actor_id=actor.id, details={"in_voice": in_voice, "players": players})
        return outcome("🎧 Voice check", f"{in_voice} of {players} players are in voice with the Gamer Pass", live_check=check)

    if not _can_end_assigned_game(actor, game):
        return False, None, "❌ Only the game's host or Host Management can change its attendance."

    if action == "att_sample":
        entry, done, err = await _take_attendance_sample(key or game_id, guild, manual_by=actor.id)
        if entry is None:
            return False, None, err or "❌ Couldn't take a sample."
        # Make sure the sampling loop is running (it finalizes after the last sample).
        _launch_attendance_snapshot(stable_id, int(game.get("snapshot_interval_minutes") or 20), guild_id=_game_guild_id(game), resume=True)
        return outcome(
            "📸 Sample taken",
            f"Sample {entry['index']}/{ATTENDANCE_SAMPLE_COUNT}: {entry['count']} of {players} present",
            ["The next sample is due one interval from now."] if done < ATTENDANCE_SAMPLE_COUNT
            else ["That was the last sample — attendance finalizes in a moment."],
        )

    if action == "att_override":
        try:
            result = await apply_attendance_override(
                guild=guild, actor=actor, game_id=key or game_id,
                user_id=int(str(payload.get("user_id") or "0")),
                verdict=str(payload.get("verdict") or ""),
                reason=str(payload.get("reason") or ""),
            )
        except (ModerationError, ValueError) as e:
            return False, None, str(e)
        return True, {"attendance": result}, None

    if action == "att_finalize":
        if game.get("snapshot_done"):
            return False, None, "ℹ️ Attendance is already finalized."
        logs = list(game.get("presence_snapshots") or [])
        if len(logs) < ATTENDANCE_REQUIRED_PRESENT:
            return False, None, f"⚠️ Take at least {ATTENDANCE_REQUIRED_PRESENT} samples first (or end the game)."
        sets = [{int(u) for u in (e.get("present_ids") or []) if str(u).isdigit()} for e in logs]
        await _finalize_attendance_results(
            key or game_id, guild, game.get("snapshot_interval_minutes", "?"), sets, logs, by=actor.id
        )
        games = await _load_games_resilient()
        _, done_game = _find_game_entry(games, key or game_id)
        present = len((done_game or {}).get("present_ids") or [])
        return outcome("✅ Attendance finalized", f"{present} of {players} present (from {len(logs)} samples)")

    return False, None, f"❌ Unknown attendance action: {action}."


# ADVANCED LOGGING SYSTEM
async def send_command_audit_log(interaction: discord.Interaction, command_name: str, args_data: list):
    # 1. Format the arguments
    args_str = ""
    if args_data:
        for option in args_data:
            if option.get('options'):
                for sub_opt in option['options']:
                     args_str += f"**{sub_opt['name']}**: {sub_opt['value']}\n"
            else:
                val = option.get('value', 'N/A')
                args_str += f"**{option['name']}**: {val}\n"

    if args_str == "": args_str = "None"

    # 2. Build the Embed
    embed = discord.Embed(
        title=f"🤖 Command Used: /{command_name}",
        color=0xf1c40f,
        timestamp=datetime.datetime.now()
    )

    channel_mention = interaction.channel.mention if interaction.channel else "Unknown"
    embed.add_field(name="User", value=f"{interaction.user.mention}\n`{interaction.user.id}`", inline=True)
    embed.add_field(name="Channel", value=channel_mention, inline=True)
    embed.add_field(name="Command Details", value=f">>> {args_str}", inline=False)

    embed.set_footer(text="Advanced Game Logger")

    # 3. Send via the webhook bucket (keeps the bot's global bucket free for autocomplete)
    await send_host_log_embed(embed)

@bot.event
async def on_interaction(interaction: discord.Interaction):
    # We only care about Application Commands (Slash Commands)
    if interaction.type == discord.InteractionType.application_command:
        try:
            # We use specific logic to get the command name and options
            command_name = interaction.command.name if interaction.command else interaction.data.get("name", "Unknown")

            # Get arguments (options)
            # interaction.data['options'] contains the raw arguments passed by the user
            args_data = interaction.data.get("options", [])

            # Send the log
            await send_command_audit_log(interaction, command_name, args_data)

        except Exception as e:
            print(f"Logging Error: {e}")

    # Note: This listener does not stop the command from running.
    # It runs in the background. processing continues as normal.


# MODERATION SYSTEM (Commend/Warn/Ban)
def get_mod_context(mode_input):
    # Normalize input
    mode = "Roleplay" # Default
    if mode_input:
        if "Historical" in mode_input or "TFB" in mode_input or "Oak" in mode_input: mode = "Historical"
        elif "Roleplay" in mode_input: mode = "Roleplay"

    # Define Contexts
    if mode == "Roleplay":
        return {
            "label": "Roleplay",
            "key_warn": "warns",
            "key_commend": "commends",
            "key_ban": "banned",
            "role_trusted": ROLE_IDS["HOI4_RP_TRUSTED"],
            "role_banned": ROLE_IDS["HOI4_RP_BANNED"],
            "role_verified": ROLE_IDS["HOI4_VERIFIED"] # <-- NEW
        }
    elif mode == "Historical":
        return {
            "label": "Historical",
            "key_warn": "hist_warns",
            "key_commend": "hist_commends",
            "key_ban": "hist_banned",
            "role_trusted": ROLE_IDS["HOI4_MP_TRUSTED"],
            "role_banned": ROLE_IDS["HOI4_MP_BANNED"],
            "role_verified": _verified_role_id("Historical"),  # Hist Verified
        }
    return None


# Every game-ban flag (one per mode). A ban in ANY mode blocks every positive
# role (Trusted, Hearts of Valor) until it is lifted.
GAME_BAN_KEYS = ("banned", "hist_banned")


def _is_game_banned_any(stats: dict) -> bool:
    return any((stats or {}).get(key) for key in GAME_BAN_KEYS)


async def _apply_game_ban_wipe(stats: dict, member, ctx: dict, reason: str) -> list[str]:
    """What every game ban (manual or 3-warning automatic) does on top of the
    ban flag: the banned mode's commends and ALL Merit go to 0, and both
    Trusted roles plus Hearts of Valor are removed. Caller saves `stats`.
    Returns human-readable notes."""
    notes: list[str] = []
    label = ctx["label"]
    lost_commends = int(stats.get(ctx["key_commend"], 0) or 0)
    if lost_commends:
        stats[ctx["key_commend"]] = 0
        notes.append(f"Lost {lost_commends} {label} commend(s) (game bans reset positive stats).")
    lost_merit = _merit_points(stats)
    if lost_merit:
        stats["merit_points"] = 0
        notes.append(f"Lost {lost_merit} Merit (game bans reset positive stats).")
    stats["valor_trusted"] = None  # the Hearts of Valor Trusted pick goes with Valor
    if member is not None and getattr(member, "guild", None) is not None:
        positive = [
            member.guild.get_role(role_id)
            for role_id in (ROLE_IDS["HOI4_RP_TRUSTED"], ROLE_IDS["HOI4_MP_TRUSTED"], ROLE_IDS["VALOR"])
        ]
        to_remove = [role for role in positive if role is not None and role in member.roles]
        if to_remove:
            try:
                await member.remove_roles(*to_remove, reason=reason)
                notes.append("Removed " + ", ".join(role.name for role in to_remove) + ".")
            except Exception as e:
                notes.append(f"⚠️ Couldn't remove positive roles: {e}")
    return notes

async def _fetch_current_member(guild: discord.Guild, user: discord.Member):
    try:
        return await asyncio.wait_for(guild.fetch_member(user.id), timeout=5.0)
    except Exception:
        return user


