async def _send_dishonored_host_log(
    *,
    title: str,
    color: discord.Color,
    user: discord.Member,
    admin: discord.abc.User,
    mode: str,
    game_key: str,
    target_game: dict,
    description: str,
    extra_fields: list[tuple[str, str]] | None = None,
):
    """Private-log Dishonored Give/Take the same way /give and /take do: webhook embed, no pings."""
    game_name = target_game.get("thread_name") or str(game_key)
    log_embed = discord.Embed(title=title, color=color)
    log_embed.add_field(name="Target", value=user.mention, inline=True)
    log_embed.add_field(name="Admin", value=admin.mention, inline=True)
    log_embed.add_field(name="Mode", value=mode, inline=True)
    log_embed.add_field(name="Game", value=str(game_name), inline=False)
    log_embed.add_field(name="Reason", value=_trim_field(description or "—"), inline=False)
    for name, value in extra_fields or []:
        log_embed.add_field(name=name, value=_trim_field(value or "—"), inline=False)
    log_embed.set_footer(text=f"Time: {datetime.datetime.now().strftime('%H:%M:%S')}")
    log_ref = await send_host_log_embed(log_embed)
    # Web portfolio record (moderation_events).
    record_moderation_event(
        user.id,
        "dishonored_take" if "Lifted" in title else "dishonored_give",
        mode=mode,
        reason=description,
        actor_id=getattr(admin, "id", None),
        thread_id=game_key if target_game else None,
        details={name: value for name, value in (extra_fields or [])} or None,
        log=log_ref,
    )
    if target_game:
        await _post_to_game_log_thread(game_key, target_game, embed=log_embed)


# ==========================================================================
# MODERATION ENGINE — the web Database page (replaces /give, /take, /sentence)
#
# Rules (October 2026):
#   · Commends and warnings never cancel each other automatically. Hosts clear
#     warnings on purpose: REDEEM (spend N commends to remove N warnings) or
#     TAKE warning (free — for unjustified warnings).
#   · 3 warnings in a mode = automatic game ban; dropping back below 3 lifts
#     only a ban that came from warnings (a manual ban stays).
#   · Every game ban (manual or automatic) resets the banned mode's commends
#     and all Merit to 0 and removes Trusted (RP + MP) and Hearts of Valor;
#     no positive role comes back while any game ban is active.
#   · Dishonored is a time-out: it blocks nations for a while and leaves every
#     stat and role untouched. (Blacklist no longer exists — Dishonored
#     replaced it.)
#   · Merit never converts into commends; 25 Merit + 50 attended games earns
#     Hearts of Valor (see the HEARTS OF VALOR block).
#   · Every action: stats save, Discord roles, player DM, host log, game
#     archive counts and a moderation_events row (web portfolio). Warning /
#     game ban / Dishonored DMs carry Acknowledge + Appeal buttons.
# ==========================================================================
MODERATION_KINDS = ("commend", "merit", "warn", "ban")
MODERATION_OPS = ("give", "take", "redeem")
MODERATION_MAX_AMOUNT = 20
DISHONORED_MIN_DAYS = 1
DISHONORED_MAX_DAYS = 365


class ModerationError(Exception):
    """A user-facing refusal (shown as-is on the web)."""


_MODERATION_TITLES = {
    ("give", "commend"): "🌟 {label} Commendation",
    ("give", "merit"): "🎖️ Merit Awarded",
    ("give", "warn"): "⚠️ {label} Warning",
    ("give", "ban"): "🚨 {label} Game Banned",
    ("take", "commend"): "📉 {label} Commend Removed",
    ("take", "merit"): "📉 Merit Removed",
    ("take", "warn"): "📉 {label} Warning Removed",
    ("take", "ban"): "🔓 {label} Unbanned",
    ("redeem", "warn"): "♻️ {label} Warnings Redeemed",
}
_MODERATION_COLORS = {
    ("give", "commend"): discord.Color.green(),
    ("give", "merit"): discord.Color.gold(),
    ("give", "warn"): discord.Color.orange(),
    ("give", "ban"): discord.Color.red(),
    ("redeem", "warn"): discord.Color.teal(),
}
# moderation_events.action for each operation.
_MODERATION_EVENT_ACTIONS = {
    ("take", "commend"): "commend_removed",
    ("take", "merit"): "merit_removed",
    ("take", "warn"): "warn_removed",
    ("take", "ban"): "unban",
    ("redeem", "warn"): "redeem",
}


async def _moderation_role(member, role_id, add: bool, reason: str) -> str | None:
    """Add/remove one role; returns a plain-text note (or None when nothing changed)."""
    if member is None or not role_id:
        return None
    role = member.guild.get_role(role_id)
    if role is None:
        return f"Role {role_id} not found — check the role configuration."
    has = role in member.roles
    if has == add:
        return None
    try:
        if add:
            await member.add_roles(role, reason=reason)
        else:
            await member.remove_roles(role, reason=reason)
        return f"{'Added' if add else 'Removed'} the {role.name} role."
    except Exception as e:
        return f"Couldn't {'add' if add else 'remove'} the {role.name} role ({e}) — check the bot's role position."


def _moderation_game(games_data: dict, game_id, user_id: int, ctx: dict | None) -> tuple:
    """(game_key, game) for an action tied to a game, or (None, {}) when off-game.
    The game must have ended, the player must have reserved in it and (for
    mode actions) it must be in the same moderation bucket."""
    if not game_id:
        return None, {}
    game_key, game = _find_game_entry(games_data, str(game_id))
    if not game:
        raise ModerationError("❌ That game isn't in the records any more.")
    if game.get("status") != "ended":
        raise ModerationError(f"⚠️ **{game.get('thread_name') or game_key}** hasn't ended yet.")
    reserved = {str(uid) for uid in (game.get("reservations") or {}).values()}
    if str(user_id) not in reserved:
        raise ModerationError("⚠️ That player didn't reserve in the selected game.")
    if ctx is not None:
        game_ctx = get_mod_context(game.get("mode"))
        if not game_ctx or game_ctx["label"] != ctx["label"]:
            raise ModerationError(
                f"❌ That game belongs to the {game_ctx['label'] if game_ctx else 'unknown'} "
                f"moderation bucket, not {ctx['label']}."
            )
    return game_key or str(game_id), game


def _trusted_protected(stats: dict, member, label: str) -> bool:
    """VIP, and a Hearts of Valor holder's approved Trusted pick, keep that
    mode's Trusted below 5 commends (role scan rules)."""
    if member is None or _is_game_banned_any(stats):
        return False
    vip_role_id = ROLE_IDS.get("VIP_ROLE_ID")
    if vip_role_id and member.get_role(vip_role_id):
        return True
    return stats.get("valor_trusted") == label and member.get_role(ROLE_IDS["VALOR"]) is not None


async def apply_moderation_action(
    *,
    guild,
    actor,
    user_id: int,
    op: str,
    kind: str,
    mode: str | None,
    amount: int,
    reason: str,
    game_id=None,
) -> dict:
    """Give / take / redeem one moderation action (see block comment).

    Raises ModerationError with a user-facing message when refused. Returns a
    plain-text summary for the web: {title, summary, notes, stats, log_url}."""
    uid = str(user_id)
    if op not in MODERATION_OPS:
        raise ModerationError("❌ Unknown action.")
    if op == "redeem":
        kind = "warn"
    if kind not in MODERATION_KINDS:
        raise ModerationError("❌ Unknown action type.")
    if str(getattr(actor, "id", "")) == uid:
        raise ModerationError("❌ You can't moderate yourself — ask another host.")
    reason = (reason or "").strip()
    if len(reason) < 3:
        raise ModerationError("❌ Please give a reason (at least a few words).")
    counted = kind in ("commend", "merit", "warn")
    amount = int(amount or 1) if counted else 1
    if amount < 1 or amount > MODERATION_MAX_AMOUNT:
        raise ModerationError(f"❌ Amount must be between 1 and {MODERATION_MAX_AMOUNT}.")
    if op == "redeem" and game_id:
        game_id = None  # redeeming is a player-record action, never tied to a game

    # Merit is one universal pool (no mode).
    ctx = get_mod_context("Roleplay" if kind == "merit" else mode)
    if ctx is None or (kind != "merit" and mode not in DISHONORED_CATEGORIES):
        raise ModerationError("❌ Pick a mode: Roleplay or Historical.")
    label = ctx["label"]
    kc, kw, kb = ctx["key_commend"], ctx["key_warn"], ctx["key_ban"]

    games_data = await read_json(GAMES_FILE)
    game_key, target_game = _moderation_game(
        games_data, game_id, user_id, None if kind == "merit" else ctx
    )
    game_name = (target_game.get("thread_name") or game_key) if game_key else "Not game related"

    member = await _get_member_safe(guild, uid)
    stats = await _load_stats_for_write(uid)
    was_banned = bool(stats.get(kb))
    warns_before = int(stats.get(kw, 0) or 0)
    notes: list[str] = []
    events: list[dict] = []  # extra automatic events (ban / unban)

    async def auto_ban_check():
        """3+ warnings = ban (same wipe as a manual ban)."""
        if int(stats.get(kw, 0) or 0) >= G.WARNINGS_FOR_BAN and not stats.get(kb):
            stats[kb] = True
            notes.append(f"Reached {stats.get(kw)} {label} warnings — automatically game banned.")
            note = await _moderation_role(member, ctx["role_banned"], True, f"Auto-Ban ({label}): {G.WARNINGS_FOR_BAN} warns")
            if note:
                notes.append(note)
            notes.extend(await _apply_game_ban_wipe(stats, member, ctx, f"Auto-Ban ({label}): {G.WARNINGS_FOR_BAN} warns"))
            events.append({"action": "ban", "reason": f"Automatic: reached {stats.get(kw)} {label} warnings"})

    async def auto_unban_check():
        """Lift only a warning ban: banned with 3+ warnings, now below 3."""
        if was_banned and warns_before >= G.WARNINGS_FOR_BAN and int(stats.get(kw, 0) or 0) < G.WARNINGS_FOR_BAN and stats.get(kb):
            stats[kb] = False
            note = await _moderation_role(member, ctx["role_banned"], False, f"Auto-Unban ({label}): warns < {G.WARNINGS_FOR_BAN}")
            if note:
                notes.append(note)
            notes.append(f"{label} warnings are below 3 — the automatic game ban was lifted.")
            events.append({"action": "unban", "reason": f"Automatic: {label} warnings dropped below 3"})

    async def trusted_after_commends():
        """Promote at 5+ commends (Verified, no game ban in any mode); demote
        below 5 (unless VIP / Valor for RP)."""
        commends = int(stats.get(kc, 0) or 0)
        if member is None:
            return
        trusted = member.guild.get_role(ctx["role_trusted"])
        verified = member.guild.get_role(ctx["role_verified"])
        if trusted is None:
            return
        if commends >= 5 and trusted not in member.roles and _is_game_banned_any(stats):
            notes.append(f"Has 5+ {label} commends, but game-banned players can't get Trusted.")
        elif commends >= 5 and trusted not in member.roles:
            if verified is not None and verified in member.roles:
                note = await _moderation_role(member, ctx["role_trusted"], True, f"Reached 5+ {label} commends and is Verified")
                notes.append(note or "")
            else:
                notes.append(f"Has 5+ {label} commends but no Verified role — Trusted not granted yet.")
        elif commends < 5 and trusted in member.roles:
            if _trusted_protected(stats, member, label):
                return
            note = await _moderation_role(member, ctx["role_trusted"], False, f"{label} commends dropped below 5")
            if note:
                notes.append(note)

    key = (op, kind)
    archive_delta = None  # (action, amount | None, active | None)
    if key == ("give", "commend"):
        stats[kc] = int(stats.get(kc, 0) or 0) + amount
        await trusted_after_commends()
        archive_delta = ("commend", amount, None)
    elif kind == "merit":
        current = _merit_points(stats)
        if op == "take" and current < amount:
            raise ModerationError(f"⚠️ They only have {current} Merit.")
        result = await _apply_merit_change(
            uid, amount if op == "give" else -amount, reason=reason, issuer=actor, guild=guild
        )
        stats = result["stats"]
        notes.extend(result.get("notes") or [])
        archive_delta = ("merit", amount if op == "give" else -amount, None)
    elif key == ("give", "warn"):
        stats[kw] = warns_before + amount
        await auto_ban_check()
        archive_delta = ("warn", amount, None)
    elif key == ("give", "ban"):
        if stats.get(kb):
            raise ModerationError(f"⚠️ They're already {label} banned.")
        stats[kb] = True
        ban_reason = f"{label} ban by {getattr(actor, 'display_name', 'a host')}"
        note = await _moderation_role(member, ctx["role_banned"], True, ban_reason)
        if note:
            notes.append(note)
        notes.extend(await _apply_game_ban_wipe(stats, member, ctx, ban_reason))
        archive_delta = ("ban", None, True)
    elif key == ("take", "commend"):
        have = int(stats.get(kc, 0) or 0)
        if have < amount:
            raise ModerationError(f"⚠️ They only have {have} {label} commend(s).")
        stats[kc] = have - amount
        await trusted_after_commends()
        archive_delta = ("commend", -amount, None)
    elif key == ("take", "warn"):
        if warns_before < amount:
            raise ModerationError(f"⚠️ They only have {warns_before} {label} warning(s).")
        stats[kw] = warns_before - amount
        await auto_unban_check()
        archive_delta = ("warn", -amount, None)
    elif key == ("take", "ban"):
        if not stats.get(kb):
            raise ModerationError(f"⚠️ They aren't {label} banned.")
        stats[kb] = False
        note = await _moderation_role(member, ctx["role_banned"], False, f"Unbanned by {getattr(actor, 'display_name', 'a host')}")
        if note:
            notes.append(note)
        archive_delta = ("ban", None, False)
    elif key == ("redeem", "warn"):
        have = int(stats.get(kc, 0) or 0)
        if warns_before < amount:
            raise ModerationError(f"⚠️ They only have {warns_before} {label} warning(s) to clear.")
        if have < amount:
            raise ModerationError(f"⚠️ They only have {have} {label} commend(s) to spend.")
        stats[kc] = have - amount
        stats[kw] = warns_before - amount
        notes.append(f"Spent {amount} {label} commend(s) to clear {amount} warning(s).")
        await auto_unban_check()
        await trusted_after_commends()
    else:
        raise ModerationError("❌ That action isn't supported.")

    notes = [note for note in notes if note]

    # Game archive bookkeeping (the Public Archive shows per-player counts).
    if game_key and archive_delta:
        action_name, delta, active = archive_delta
        if active is None:
            _adjust_game_action_count(target_game, user_id, action_name, delta)
        else:
            _adjust_game_action_count(target_game, user_id, action_name, active=active)
        if key == ("give", "warn"):
            target_game.setdefault("game_warns", [])
            if int(user_id) not in target_game["game_warns"]:
                target_game["game_warns"].append(int(user_id))
        if stats.get(kb) and key in (("give", "warn"), ("give", "ban")):
            target_game.setdefault("game_bans", [])
            if int(user_id) not in target_game["game_bans"]:
                target_game["game_bans"].append(int(user_id))
            _adjust_game_action_count(target_game, user_id, "ban", active=True)
        if key == ("take", "ban") and int(user_id) in (target_game.get("game_bans") or []):
            target_game["game_bans"].remove(int(user_id))
        if key == ("take", "warn") and int(user_id) in (target_game.get("game_warns") or []):
            target_game["game_warns"].remove(int(user_id))

    # Persist (merit already saved its stats; saving again is harmless).
    await save_mysql_player_stats(uid, stats)
    if _player_stats_cache is not None:
        _player_stats_cache[uid] = stats
    if game_key:
        await save_single_game(game_key, target_game, rewrite_reservations=False)
        try:
            await update_public_log(str(game_key))
        except Exception as e:
            print(f"[WARN] moderation public log refresh failed: {e}")

    title = _MODERATION_TITLES[key].format(label=label)
    color = _MODERATION_COLORS.get(key, discord.Color.green())
    stat_line = (
        f"Merit: {_merit_points(stats)}"
        if kind == "merit"
        else f"{label} commends: {stats.get(kc, 0)} · warnings: {stats.get(kw, 0)}"
        + (" · BANNED" if stats.get(kb) else "")
    )
    plain_title = title.split(" ", 1)[-1]  # without the emoji
    if op == "redeem":
        summary = f"{plain_title}: {amount} commend(s) spent, {amount} warning(s) cleared"
    elif counted:
        summary = f"{plain_title}: {'+' if op == 'give' else '−'}{amount}"
    else:
        summary = plain_title

    # Player DM.
    target_user = member or await _resolve_dm_target(int(uid))
    if target_user is not None:
        dm = discord.Embed(title=f"Moderation Update ({'Merit' if kind == 'merit' else label})", color=color)
        dm.add_field(name="Action", value=title.split(" ", 1)[-1], inline=True)
        if counted:
            dm.add_field(name="Amount", value=str(amount), inline=True)
        dm.add_field(name="Game", value=game_name, inline=False)
        dm.add_field(name="Reason", value=_trim_field(reason), inline=False)
        if notes:
            dm.add_field(name="Status change", value=_trim_field("\n".join(f"• {n}" for n in notes)), inline=False)
        # Warnings and game bans get Acknowledge / Appeal buttons.
        feedback = build_moderation_feedback_view() if op == "give" and kind in ("warn", "ban") else None
        await _dm_user_safe(target_user, embed=dm, view=feedback, label="moderation")

    # Host log (+ forward to the game's Host Control Center).
    log_ref = None
    try:
        log_embed = discord.Embed(title=title, color=color)
        log_embed.add_field(name="Target", value=f"<@{uid}>", inline=True)
        log_embed.add_field(name="Admin", value=f"<@{getattr(actor, 'id', 0)}>", inline=True)
        log_embed.add_field(name="Mode", value="Merit" if kind == "merit" else label, inline=True)
        if counted:
            log_embed.add_field(name="Amount", value=str(amount), inline=True)
        log_embed.add_field(name="Game", value=game_name, inline=False)
        log_embed.add_field(name="Reason", value=_trim_field(reason), inline=False)
        log_embed.add_field(name="New Stats", value=stat_line, inline=False)
        if notes:
            log_embed.add_field(name="Status change", value=_trim_field("\n".join(f"• {n}" for n in notes)), inline=False)
        log_embed.set_footer(text="Via the web Database")
        log_ref = await send_host_log_embed(log_embed)
        if game_key:
            await _post_to_game_log_thread(game_key, target_game, embed=log_embed)
    except Exception as e:
        print(f"[WARN] moderation host-log failed: {e}")

    # Web portfolio records (moderation_events).
    record_moderation_event(
        uid,
        _MODERATION_EVENT_ACTIONS.get(key, kind),
        mode=None if kind == "merit" else label,
        amount=amount if counted else None,
        reason=reason,
        actor_id=getattr(actor, "id", None),
        thread_id=game_key,
        details={"game": game_name, **({"notes": notes} if notes else {})},
        log=log_ref,
    )
    for extra in events:
        record_moderation_event(
            uid,
            extra["action"],
            mode=label,
            reason=extra["reason"],
            actor_id=getattr(actor, "id", None),
            thread_id=game_key,
            automatic=True,
            log={"url": log_ref["url"]} if log_ref else None,
        )

    return {
        "title": title,
        "summary": summary,
        "notes": notes,
        "stats": {
            "commends": int(stats.get(kc, 0) or 0),
            "warns": int(stats.get(kw, 0) or 0),
            "banned": bool(stats.get(kb)),
            "merit": _merit_points(stats),
        },
        "log_url": (log_ref or {}).get("url"),
    }


async def apply_dishonored_action(
    *,
    guild,
    actor,
    user_id: int,
    op: str,
    mode: str,
    reason: str,
    days: int = 30,
    all_majors: bool = False,
    majors: list | None = None,
    minors: list | None = None,
    replace: bool = False,
    game_id=None,
) -> dict:
    """Give (op='give') or lift (op='take') a Dishonored restriction.

    Give merges with an active restriction in the same mode unless `replace`;
    the duration is any whole number of days in [DISHONORED_MIN_DAYS,
    DISHONORED_MAX_DAYS]. Raises ModerationError when refused."""
    uid = str(user_id)
    if op not in ("give", "take"):
        raise ModerationError("❌ Unknown Dishonored action.")
    if mode not in DISHONORED_CATEGORIES:
        raise ModerationError("❌ Pick a mode: Roleplay or Historical.")
    if str(getattr(actor, "id", "")) == uid:
        raise ModerationError("❌ You can't moderate yourself — ask another host.")
    reason = (reason or "").strip()
    if len(reason) < 3:
        raise ModerationError("❌ Please give a reason (at least a few words).")

    games_data = await read_json(GAMES_FILE)
    game_key, target_game = _moderation_game(games_data, game_id, user_id, get_mod_context(mode))
    target_user = await _get_member_safe(guild, uid) or await _resolve_dm_target(int(uid))
    if target_user is None:
        raise ModerationError("❌ Couldn't find that Discord user.")

    if op == "take":
        res = await _clear_dishonored_restriction(uid, mode, guild=guild)
        if not res.get("existed"):
            raise ModerationError(f"ℹ️ They have no Dishonored restriction in {mode}.")
        summary = _dishonored_full_summary(res["stats"])
        if game_key:
            _adjust_game_action_count(target_game, user_id, "dishonored", active=False)
        title = "⚖️ Dishonored Title Lifted"
        extra_fields = [("Remaining restrictions", summary)]
        dm_text = (
            f"⚖️ **Dishonored Title Updated**\n"
            f"Your Dishonored restriction in **{mode}** has been **lifted**.\n"
            f"**Reason:** {reason}\n**Remaining restrictions:**\n{summary}"
        )
        notes = [f"Lifted the {mode} restriction."]
    else:
        try:
            days = int(days)
        except (TypeError, ValueError):
            days = 0
        if not (DISHONORED_MIN_DAYS <= days <= DISHONORED_MAX_DAYS):
            raise ModerationError(f"❌ Duration must be {DISHONORED_MIN_DAYS}–{DISHONORED_MAX_DAYS} days.")
        all_nations, major_pool = _dishonored_nations_for_category(mode)
        major_lookup = {name.lower(): name for name in major_pool}
        minor_lookup = {name.lower(): name for name in all_nations if name not in set(major_pool)}
        picked_majors, picked_minors = [], []
        for name in majors or []:
            match = major_lookup.get(str(name).strip().lower())
            if match is None:
                raise ModerationError(f"❌ **{name}** isn't a Major nation in {mode}.")
            if match not in picked_majors:
                picked_majors.append(match)
        for name in minors or []:
            match = minor_lookup.get(str(name).strip().lower())
            if match is None:
                raise ModerationError(f"❌ **{name}** isn't a Minor nation in {mode}.")
            if match not in picked_minors:
                picked_minors.append(match)
        if not all_majors and not picked_majors and not picked_minors:
            raise ModerationError("❌ Pick at least one restriction: All Majors, a Major or a Minor.")

        existing = ((await _load_stats_for_write(uid)).get("dishonored_data") or {}).get(mode) or {}
        if not replace and _dishonored_entry_active(existing):
            all_majors = all_majors or bool(existing.get("all_majors"))
            picked_majors = [] if all_majors else list(dict.fromkeys([*(existing.get("majors") or []), *picked_majors]))
            picked_minors = list(dict.fromkeys([*(existing.get("minors") or []), *picked_minors]))
        elif all_majors:
            picked_majors = []

        res = await _set_dishonored_restriction(
            uid, mode,
            all_majors=all_majors,
            majors=picked_majors,
            minors=picked_minors,
            description=reason,
            issuer_id=getattr(actor, "id", None),
            duration_days=days,
            guild=guild,
        )
        if game_key:
            _adjust_game_action_count(target_game, user_id, "dishonored", active=True)
        entry = (res["stats"].get("dishonored_data") or {}).get(mode) or {}
        restriction = _dishonored_summary(entry, mode)
        summary = _dishonored_full_summary(res["stats"])
        title = "⚖️ Dishonored Title Applied"
        extra_fields = [
            ("Restriction", restriction),
            ("All active restrictions", summary),
            ("Duration", f"{days} days"),
        ]
        notes = [f"Dishonored in {mode} for {days} days. Stats and roles are untouched."]
        dm_text = (
            f"⚖️ **You have been Dishonored**\n{restriction}\n\n"
            f"While this title is active you **cannot reserve** the restricted nations "
            f"listed above. Contact staff if you believe this was issued in error."
        )

    if game_key:
        await save_single_game(game_key, target_game, rewrite_reservations=False)
        try:
            await update_public_log(str(game_key))
        except Exception as e:
            print(f"[WARN] dishonored public log refresh failed: {e}")
    await _dm_user_safe(
        target_user,
        content=dm_text,
        view=build_moderation_feedback_view() if op == "give" else None,
        label="dishonored",
    )
    try:
        await _send_dishonored_host_log(
            title=title,
            color=discord.Color.dark_red() if op == "give" else discord.Color.green(),
            user=target_user,
            admin=actor,
            mode=mode,
            game_key=game_key or "Not game related",
            target_game=target_game,
            description=reason,
            extra_fields=extra_fields,
        )
    except Exception as e:
        print(f"[WARN] dishonored host-log failed: {e}")
    return {"title": title, "summary": summary, "notes": notes, "stats": {}, "log_url": None}


def _publish_web_moderation_options_mysql(options: dict) -> None:
    """Mirror the bot's Dishonored nation lists (the exact names it validates)
    into bot_config so the web Database page offers the same choices."""
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        cur.execute(
            "INSERT INTO bot_config (config_key, config_value) VALUES (%s, %s) "
            "ON DUPLICATE KEY UPDATE config_value = VALUES(config_value)",
            ("web_moderation_options", json.dumps(options, ensure_ascii=False)),
        )
        conn.commit()
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


async def publish_web_moderation_options() -> None:
    options = {"max_amount": MODERATION_MAX_AMOUNT, "dishonored_days": [DISHONORED_MIN_DAYS, DISHONORED_MAX_DAYS], "nations": {}}
    for category in DISHONORED_CATEGORIES:
        all_nations, majors = _dishonored_nations_for_category(category)
        major_set = set(majors)
        options["nations"][category] = {
            "majors": list(majors),
            "minors": sorted(n for n in all_nations if n not in major_set),
        }
    # Every mode's nation names (the Games page's nation lock and late join).
    options["mode_nations"] = {}
    for mode_name in MODE_CONFIG:
        try:
            all_nations, majors = _get_mode_nation_data(mode_name)
        except Exception as e:
            print(f"[WARN] web options: no nation list for {mode_name}: {e}")
            continue
        options["mode_nations"][mode_name] = {
            "majors": [n for n in all_nations if n in majors],
            "minors": sorted(n for n in all_nations if n not in majors),
        }
    # The Presets page starts from each mode's standard nation groups,
    # rulesets and mods.
    options["mode_layouts"] = {}
    options["mode_resources"] = {}
    for mode_name in MODE_CONFIG:
        try:
            options["mode_layouts"][mode_name] = [
                {"name": str(category), "tiers": [{"label": sub, "nations": list(nations)} for sub, nations in subs]}
                for category, subs in _get_archive_layout(mode_name)
            ]
            options["mode_resources"][mode_name] = {
                "mods": _default_resource_entries(mode_name, "mods"),
                "rules": _default_resource_entries(mode_name, "rules"),
            }
        except Exception as e:
            print(f"[WARN] web options: no preset defaults for {mode_name}: {e}")
    # Which server this is (presets are kept per server; the public library
    # shows each shared preset's server name).
    home_guild = bot.get_guild(cur_gid())
    options["server"] = {"id": str(cur_gid()), "name": home_guild.name if home_guild is not None else None}
    options["preset_limits"] = {
        "groups": WEB_PRESET_MAX_GROUPS,
        "tiers": WEB_PRESET_MAX_TIERS,
        "mods": WEB_GAME_MAX_MODS,
        "rules": WEB_SCHEDULE_MAX_RULES,
        "game_rules": WEB_GAME_MAX_RULES,
    }
    try:
        if cur_gid() != GUILD_ID:
            # Another server: its own "guild:<id>" bot_config row, never the home key.
            await _bot_config_mutate(lambda cfg: cfg.__setitem__("web_moderation_options", options))
            return
        await _run_mysql_io(_publish_web_moderation_options_mysql, options, label="web moderation options")
        if _BOT_CONFIG_LOADED:
            # Keep the cached copy current so a later bot_config save can't restore an old list.
            _BOT_CONFIG_ALL["web_moderation_options"] = options
    except Exception as e:
        print(f"[WARN] Could not publish web moderation options: {e}")


async def _process_web_moderation(req: dict):
    """Web Database page → apply_moderation_action / apply_dishonored_action."""
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if not _member_is_host(actor):
        return False, None, "❌ Only members with a Host role can moderate players."
    raw_uid = str(payload.get("user_id") or "")
    if not raw_uid.isdigit():
        return False, None, "❌ Invalid player."
    guild = bot.get_guild(cur_gid())
    try:
        if req.get("action") == "dishonored":
            result = await apply_dishonored_action(
                guild=guild,
                actor=actor,
                user_id=int(raw_uid),
                op=str(payload.get("op") or ""),
                mode=str(payload.get("mode") or ""),
                reason=str(payload.get("reason") or ""),
                days=payload.get("days") or 0,
                all_majors=bool(payload.get("all_majors")),
                majors=[str(n) for n in (payload.get("majors") or [])],
                minors=[str(n) for n in (payload.get("minors") or [])],
                replace=bool(payload.get("replace")),
                game_id=payload.get("game_id") or None,
            )
        else:
            result = await apply_moderation_action(
                guild=guild,
                actor=actor,
                user_id=int(raw_uid),
                op=str(payload.get("op") or ""),
                kind=str(payload.get("kind") or ""),
                mode=payload.get("mode") or None,
                amount=int(payload.get("amount") or 1),
                reason=str(payload.get("reason") or ""),
                game_id=payload.get("game_id") or None,
            )
    except ModerationError as e:
        return False, None, str(e)
    if (payload.get("ai_reward") and payload.get("game_id") and str(payload.get("op")) == "give"
            and str(payload.get("kind")) in ("commend", "merit") and req.get("action") == "moderation"):
        await _mark_ai_reward_given(str(payload["game_id"]), raw_uid, str(payload["kind"]),
                                    int(payload.get("amount") or 1), actor.id)
    return True, {"moderation": result}, None


# ==========================================================================
# HOST RATING — Acclamations / Violations (web Database page; /give_host and
# /take_host were retired in favour of it)
# --------------------------------------------------------------------------
# Counted per host branch (RP / HIST), exactly like commends and warnings:
# Senior Hosts of that branch and Host Management (+ admins) give them; only
# Host Management takes them back; nobody rates themselves. Acclamations
# promote (2 → Assistant becomes Full, 4 → Full becomes Senior), Violations
# strip the branch's rank (3). The two never cancel each other. Taking
# Acclamations back drops the rank they earned; taking Violations back below
# the limit gives a stripped rank back (like the automatic game unban).
# Switched-off ranks (server settings → Host ranks) are skipped. Every action:
# host_stats save, roles, a DM to the host, a host-log embed and a
# moderation_events row (shows on the host's record on the web).
# ==========================================================================
HOST_RATING_KINDS = ("acclamation", "violation")
HOST_RATING_MAX_AMOUNT = 10
_HOST_RATING_EVENT_ACTIONS = {
    ("give", "acclamation"): "host_acclamation",
    ("give", "violation"): "host_violation",
    ("take", "acclamation"): "host_acclamation_removed",
    ("take", "violation"): "host_violation_removed",
}


_HOST_RANK_ORDER = {"None": 0, "Assistant": 1, "Full": 2, "Senior": 3}


def _host_rank_on(branch: str, rank: str) -> bool:
    """Whether this server uses a rank (switched-off ranks have no role)."""
    return bool((HOST_BRANCHES.get(branch) or {}).get("ranks", {}).get(rank))


def _lowest_host_rank(branch: str) -> str:
    """Where a new host starts: Assistant, or Full when Assistant is switched off."""
    return "Assistant" if _host_rank_on(branch, "Assistant") else "Full"


def _rank_for_acclamations(branch: str, acclamations: int) -> str:
    """The rank a number of Acclamations earns in a branch."""
    if _host_rank_on(branch, "Senior") and acclamations >= HOST_PROMOTE_AT["Senior"]:
        return "Senior"
    if acclamations >= HOST_PROMOTE_AT["Full"]:
        return "Full"
    return _lowest_host_rank(branch)


def _can_rate_hosts(member, branch: str | None = None) -> bool:
    """Host Management and admins rate any branch; a Senior Host rates the
    branch they're Senior in (branch None = any branch)."""
    if member is None:
        return False
    if _member_is_staff(member):
        return True
    branches = [branch] if branch else list(HOST_BRANCHES)
    return any(_host_rank(member, b) == "Senior" for b in branches if b in HOST_BRANCHES)


async def apply_host_rating(
    *,
    guild,
    actor,
    target_id: int,
    op: str,
    kind: str,
    amount: int,
    reason: str,
    branch: str = "RP",
    source: str = "Via the web Database",
) -> dict:
    """Give / take host Acclamations or Violations in one branch (RP or HIST).
    Raises ModerationError with a user-facing message when refused. Returns
    {title, summary, notes, stats, log_url, dm_ok}."""
    branch = str(branch or "RP").upper()
    if branch not in HOST_BRANCHES:
        raise ModerationError("❌ Pick a host branch: RP or HIST.")
    if not _can_rate_hosts(actor, branch):
        raise ModerationError(f"❌ Only Senior {branch} Hosts and Host Management can rate {branch} hosts.")
    if op not in ("give", "take"):
        raise ModerationError("❌ Unknown action.")
    if op == "take" and not _member_is_staff(actor):
        raise ModerationError("❌ Only Host Management can take Acclamations or Violations back.")
    if kind not in HOST_RATING_KINDS:
        raise ModerationError("❌ Pick Acclamation or Violation.")
    tid = str(target_id)
    if str(getattr(actor, "id", "")) == tid:
        raise ModerationError("❌ You can't rate yourself — ask another senior.")
    reason = (reason or "").strip()
    if len(reason) < 3:
        raise ModerationError("❌ Please give a reason (at least a few words).")
    try:
        amount = int(amount)
    except (TypeError, ValueError):
        amount = 0
    if amount < 1 or amount > HOST_RATING_MAX_AMOUNT:
        raise ModerationError(f"❌ Amount must be between 1 and {HOST_RATING_MAX_AMOUNT}.")

    cfg = HOST_BRANCHES[branch]
    acc_key, vio_key = cfg["acclamations_key"], cfg["violations_key"]
    target = await _get_member_safe(guild, tid)
    all_stats = await read_json(HOST_STATS_FILE)
    if not isinstance(all_stats, collections.abc.MutableMapping):
        all_stats = {}
    if tid not in all_stats and not (target is not None and _member_is_host(target)):
        raise ModerationError("❌ That user isn't a host.")
    entry = all_stats.setdefault(tid, {"hosted_games": 0})
    for key in ("acclamations", "violations", "hist_acclamations", "hist_violations"):
        entry.setdefault(key, 0)
    notes: list[str] = []
    label = "Acclamation" if kind == "acclamation" else "Violation"
    ranks = cfg["ranks"]
    rank = _host_rank(target, branch) if target is not None else "None"

    async def set_rank(new_rank: str, note: str):
        """Swap this branch's rank role (None = remove it)."""
        if target is None:
            notes.append(f"{note} — skipped, they're not in the server.")
            return
        try:
            old_ids = [rid for r, rid in ranks.items() if rid and target.get_role(rid) and r != new_rank]
            if old_ids:
                await target.remove_roles(*[discord.Object(id=rid) for rid in old_ids], reason=f"Host rating: {note}")
            if new_rank != "None" and ranks.get(new_rank):
                await target.add_roles(discord.Object(id=ranks[new_rank]), reason=f"Host rating: {note}")
            stats = await get_mysql_player_stats(tid)
            stats[cfg["tier_db_field"]] = new_rank
            await save_mysql_player_stats(tid, stats)
            notes.append(note + ".")
        except Exception as e:
            notes.append(f"⚠️ {note} failed: {e}")

    order = _HOST_RANK_ORDER
    if op == "give" and kind == "acclamation":
        entry[acc_key] += amount
        total = entry[acc_key]
        earned = _rank_for_acclamations(branch, total)
        if rank in ("Assistant", "Full") and order[earned] > order[rank]:
            await set_rank(earned, f"Promoted to {earned} {branch} Host (reached {total} Acclamations)")
    elif op == "give":
        entry[vio_key] += amount
        if entry[vio_key] >= G.HOST_TERMINATE_AT and rank != "None":
            await set_rank("None", f"TERMINATED from the {branch} branch: {G.HOST_TERMINATE_AT} Violations reached — {branch} host role stripped")
    else:
        key = acc_key if kind == "acclamation" else vio_key
        if entry[key] < amount:
            raise ModerationError(f"⚠️ They only have {entry[key]} {branch} {label}(s).")
        before = entry[key]
        entry[key] -= amount
        if kind == "acclamation":
            earned = _rank_for_acclamations(branch, entry[acc_key])
            if rank in ("Full", "Senior") and order[earned] < order[rank]:
                await set_rank(earned, f"Back to {earned} {branch} Host ({entry[acc_key]} Acclamations left)")
        elif rank == "None" and before >= G.HOST_TERMINATE_AT and entry[vio_key] < G.HOST_TERMINATE_AT:
            earned = _rank_for_acclamations(branch, entry[acc_key])
            await set_rank(earned, f"{branch} Violations are below {G.HOST_TERMINATE_AT} — {earned} {branch} Host given back")

    await write_json(HOST_STATS_FILE, all_stats)

    status_line = f"{branch}: ⭐ {entry[acc_key]} Acclamations | ⚠️ {entry[vio_key]} Violations"
    summary = f"{branch} Host {label}: {'+' if op == 'give' else '−'}{amount}"
    color = (
        discord.Color.light_grey() if op == "take"
        else discord.Color.green() if kind == "acclamation" else discord.Color.orange()
    )

    dm_ok = False
    dm_target = target or await _resolve_dm_target(int(tid))
    if dm_target is not None:
        dm = discord.Embed(title="Host Performance Update" if op == "give" else "Host Performance Correction", color=color)
        dm.add_field(name="Action", value=label if op == "give" else f"Removed {label}", inline=True)
        dm.add_field(name="Branch", value=f"{branch} hosting", inline=True)
        dm.add_field(name="Amount", value=str(amount), inline=True)
        dm.add_field(name="Reason", value=_trim_field(reason), inline=False)
        dm.add_field(name="Current Status", value=status_line, inline=False)
        if notes:
            dm.add_field(name="Changes", value=_trim_field("\n".join(f"• {n}" for n in notes)), inline=False)
        dm_ok = await _dm_user_safe(dm_target, embed=dm, label="host rating")

    title = f"{'⭐' if kind == 'acclamation' else '⚠️'} {branch} Host {label}{'' if op == 'give' else ' Removed'}"
    log_ref = None
    try:
        log_embed = discord.Embed(title=title, color=color)
        log_embed.add_field(name="Target", value=f"<@{tid}>", inline=True)
        log_embed.add_field(name="Admin", value=f"<@{getattr(actor, 'id', 0)}>", inline=True)
        log_embed.add_field(name="Amount", value=str(amount), inline=True)
        log_embed.add_field(name="Reason", value=_trim_field(reason), inline=False)
        log_embed.add_field(name="New Status", value=status_line, inline=False)
        if notes:
            log_embed.add_field(name="Changes", value=_trim_field("\n".join(f"• {n}" for n in notes)), inline=False)
        log_embed.set_footer(text=source)
        log_ref = await send_host_log_embed(log_embed)
    except Exception as e:
        print(f"[WARN] host rating log failed: {e}")
    record_moderation_event(
        tid,
        _HOST_RATING_EVENT_ACTIONS[(op, kind)],
        mode=branch,
        amount=amount,
        reason=reason,
        actor_id=getattr(actor, "id", None),
        details={"notes": notes, "branch": branch} if notes else {"branch": branch},
        log=log_ref,
    )
    return {
        "title": title,
        "summary": summary,
        "notes": notes,
        "stats": {
            "branch": branch,
            "acclamations": int(entry[acc_key]),
            "violations": int(entry[vio_key]),
            "hosted_games": int(entry.get("hosted_games", 0) or 0),
        },
        "log_url": (log_ref or {}).get("url"),
        "dm_ok": dm_ok,
    }


async def _process_web_host_rating(req: dict):
    """Web Database page → apply_host_rating (Senior Hosts / management only)."""
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    raw_uid = str(payload.get("user_id") or "")
    if not raw_uid.isdigit():
        return False, None, "❌ Invalid host."
    try:
        result = await apply_host_rating(
            guild=bot.get_guild(cur_gid()),
            actor=actor,
            target_id=int(raw_uid),
            op=str(payload.get("op") or ""),
            kind=str(payload.get("kind") or ""),
            amount=int(payload.get("amount") or 1),
            reason=str(payload.get("reason") or ""),
            branch=str(payload.get("branch") or "RP"),
        )
    except ModerationError as e:
        return False, None, str(e)
    result.pop("dm_ok", None)
    return True, {"moderation": result}, None


# ==========================================================================
# GAME VERIFICATION & HOST-TIER MANAGEMENT (now the web Database page —
# /verify, /make_vip and /make_host moved to the MEMBER ROLES section)
# --------------------------------------------------------------------------
# Discord roles are the "live" state; MySQL (`users` table) mirrors them so
# other systems (profile lookups, the recurring role scan) can read stats without
# hitting the Discord API. Both commands are single-row DB writes (see
# get_mysql_player_stats / save_mysql_player_stats) — never a bulk rewrite.
# ==========================================================================
# ==========================================================================
# MEMBER ROLES — RP / Hist Verified and VIP (the web Database page; /verify
# and /make_vip moved there)
# --------------------------------------------------------------------------
# Verification is split by game type: RP Verified (the original "HOI4
# Verified" role, users.hoi4_verified) for Roleplay games and Hist Verified
# (found or created by the bot on startup, users.hist_verified) for
# Historical games. Every grant and removal is a moderation_events row, so
# the website shows who verified someone and when.
#
# Host Management give VIP with a category: Content Creator (their channel
# links), PDX Staff (the member gets a DM with a "This isn't me" button) or
# Highly Trusted (a written reason). Each grant is a row in the shared
# `vip_grants` table — every server running this bot uses the same database,
# so a server's bot sees VIPs given elsewhere: Content Creator and PDX Staff
# VIPs carry over by themselves when the member is in (or joins) this server
# (staff get a notice with a Remove button); Highly Trusted VIPs wait for this
# server's staff to approve them.
# ==========================================================================
VERIFIED_TRACKS = {
    "Roleplay": {"label": "RP Verified", "role_key": "HOI4_VERIFIED", "db_field": "hoi4_verified"},
    "Historical": {"label": "Hist Verified", "role_key": "HIST_VERIFIED", "db_field": "hist_verified"},
}
HIST_VERIFIED_ROLE_NAME = "Hist Verified"
_HIST_VIP_MIGRATED_KEY = "hist_verified_vip_migrated"  # bot_config: current VIPs got Hist Verified once
_WEB_MEMBER_ROLES_KEY = "web_member_roles"            # bot_config: role ids for the website

VIP_CATEGORIES = {
    "content_creator": "Content Creator",
    "pdx_staff": "PDX Staff",
    "highly_trusted": "Highly Trusted",
}
VIP_CATEGORY_ICONS = {"content_creator": "🎥", "pdx_staff": "🛠️", "highly_trusted": "🤝"}
# These carry over to other servers by themselves; Highly Trusted needs approval there.
VIP_TRANSFERABLE = ("content_creator", "pdx_staff")
VIP_MAX_LINKS = 6
VIP_LINK_MAX_LEN = 200
VIP_REASON_MIN = 20
VIP_REASON_MAX = 1000
VIP_NOTE_MAX = 300
VIP_NOTICE_CHANNEL_ID = HOST_MANAGEMENT_CHANNEL_ID  # staff notices with Remove / Approve buttons
VIP_SYNC_INTERVAL_MIN = 30
VIP_LINK_PLATFORMS = (
    ("YouTube", ("youtube.com", "youtu.be")),
    ("Twitch", ("twitch.tv",)),
    ("Kick", ("kick.com",)),
    ("TikTok", ("tiktok.com",)),
    ("X", ("twitter.com", "x.com")),
)
MEMBER_ROLE_OPS = ("verify", "unverify", "vip_grant", "vip_remove", "vip_approve", "vip_decline", "host_tier")
HOST_TIER_CHOICES = ("None",) + HOST_RANKS  # per branch; "None" = no rank in that branch
_VIP_GRANT_COLUMNS = (
    "grant_id", "guild_id", "guild_name", "user_id", "category", "details", "status",
    "source_guild_id", "source_guild_name", "source_grant_id", "granted_by", "granted_at",
    "decided_by", "decided_at", "decision_note", "notice_message_id", "updated_at",
)


def _verified_role_id(track: str, *, fallback: bool = True) -> int:
    """The Verified role of a game type. Until the bot has set up Hist
    Verified, Historical falls back to the old shared role (fallback=True)."""
    info = VERIFIED_TRACKS.get(track) or VERIFIED_TRACKS["Roleplay"]
    role_id = int(ROLE_IDS.get(info["role_key"]) or 0)
    if not role_id and fallback:
        role_id = int(ROLE_IDS["HOI4_VERIFIED"])
    return role_id


def _verified_field_label(db_field: str) -> str:
    return next((info["label"] for info in VERIFIED_TRACKS.values() if info["db_field"] == db_field), db_field)


def _apply_hist_verified_role_id(role_id: int) -> None:
    """Point Historical games' "Verified+" level, the Historical Trusted rule
    and the role scan at the Hist Verified role."""
    ROLE_IDS["HIST_VERIFIED"] = int(role_id)
    for cfg in MODE_CONFIG.values():
        if cfg.get("trusted_role_id") == ROLE_IDS["HOI4_MP_TRUSTED"]:
            cfg["verified_role_id"] = int(role_id)
    GAME_ROLE_CONFIG["HOI4"]["verified_roles"]["hist_verified"] = int(role_id)


async def _setup_member_roles() -> None:
    """Startup: point Historical games at the Hist Verified role chosen in the
    server settings, publish the role ids for the website and (once) give the
    current VIPs Hist Verified — VIP has always meant Verified for every game
    type. Roles are never created here; setup's "Create for me" does that."""
    await bot.wait_until_ready()
    guild = bot.get_guild(cur_gid())
    if guild is None:
        return
    role = guild.get_role(int(ROLE_IDS.get("HIST_VERIFIED") or 0))
    if role is not None:
        _apply_hist_verified_role_id(role.id)
    await _publish_member_role_ids()
    if role is not None:
        await _migrate_vips_to_hist_verified(guild, role)


async def _migrate_vips_to_hist_verified(guild, hist_role) -> None:
    """One time: everyone holding VIP also gets Hist Verified."""
    def claim(cfg):
        if cfg.get(_HIST_VIP_MIGRATED_KEY):
            return False
        cfg[_HIST_VIP_MIGRATED_KEY] = int(time.time())
        return True
    try:
        if not await _bot_config_mutate(claim):
            return
    except Exception as e:
        print(f"[WARN] Hist Verified VIP migration skipped: {e}")
        return
    vip_role = guild.get_role(int(ROLE_IDS.get("VIP_ROLE_ID") or 0))
    if vip_role is None:
        return
    if not guild.chunked:
        try:
            await guild.chunk()
        except Exception:
            pass
    given = 0
    for member in list(vip_role.members):
        if member.bot or hist_role in member.roles:
            continue
        try:
            await member.add_roles(hist_role, reason="VIP: Verified for every game type (verification split)")
            stats = await get_mysql_player_stats(str(member.id))
            stats["hist_verified"] = True
            await save_mysql_player_stats(str(member.id), stats)
            given += 1
            await asyncio.sleep(1.0)
        except Exception as e:
            print(f"[WARN] Hist Verified for VIP {member.id} failed: {e}")
    print(f"✅ Hist Verified given to {given} current VIP(s).")


# ————— RP / Hist Verified (formerly /verify) —————

async def apply_verification(*, guild, actor, user_id: int, track: str, grant: bool, note: str = "",
                             ticket_resolve: bool = False) -> dict:
    """Give or take RP / Hist Verified. Raises ModerationError when refused.
    ticket_resolve: a verification ticket was resolved (its handlers — Ticket
    Support included — were checked by the ticket)."""
    source = "a ticket" if ticket_resolve else "web Database"
    if not ticket_resolve and not _member_is_staff(actor):
        raise ModerationError("❌ Only admins and Host Management can verify players.")
    info = VERIFIED_TRACKS.get(track)
    if info is None:
        raise ModerationError("❌ Pick RP Verified or Hist Verified.")
    label = info["label"]
    role_id = int(ROLE_IDS.get(info["role_key"]) or 0)
    if not role_id:
        raise ModerationError(
            f"❌ The {label} role isn't set up yet — the bot creates it on startup (it needs the Manage Roles permission)."
        )
    note = re.sub(r"\s+", " ", str(note or "")).strip()[:300]
    if not grant and len(note) < 3:
        raise ModerationError("❌ Please give a reason for taking it away.")
    uid = str(user_id)
    member = await _get_member_safe(guild, uid)
    if member is None:
        raise ModerationError("❌ They're not in the server.")
    notes: list[str] = []
    if grant:
        role_note = await _assign_discord_role(
            member, role_id, reason=f"{label} by {getattr(actor, 'display_name', actor)} ({source})"
        )
        if role_note.startswith("❌"):
            raise ModerationError(role_note)
        already = role_note.startswith("ℹ️")
    else:
        role = guild.get_role(role_id)
        already = role is None or role not in member.roles
        if already:
            role_note = f"ℹ️ They didn't have {label}."
        else:
            try:
                await member.remove_roles(role, reason=f"{label} removed by {getattr(actor, 'display_name', actor)}: {note}")
            except Exception as e:
                raise ModerationError(f"❌ Couldn't remove **{role.name}**: {e}")
            role_note = f"✅ Removed **{role.name}**."
            trusted = "HOI4 RP Trusted" if track == "Roleplay" else "HOI4 MP Trusted"
            notes.append(f"Their {trusted} role (if they have it) goes at the next role scan.")
    if already:
        notes.insert(0, role_note)
    stats = await get_mysql_player_stats(uid)
    stats[info["db_field"]] = bool(grant)
    await save_mysql_player_stats(uid, stats)

    title = f"🪪 {label} {'Granted' if grant else 'Removed'}"
    log_ref = None
    try:
        log_embed = discord.Embed(
            title=title,
            color=discord.Color.green() if grant else discord.Color.dark_grey(),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        log_embed.add_field(name="User", value=f"<@{uid}> (`{uid}`)", inline=True)
        log_embed.add_field(name="Type", value=label, inline=True)
        log_embed.add_field(name="Staff", value=f"<@{getattr(actor, 'id', 0)}>", inline=True)
        log_embed.add_field(name="Discord role", value=_trim_field(role_note), inline=False)
        if note:
            log_embed.add_field(name="Reason" if not grant else "Note", value=_trim_field(note), inline=False)
        log_embed.set_footer(text=f"Via {source}")
        log_ref = await send_host_log_embed(log_embed)
    except Exception as e:
        print(f"[WARN] verification log failed: {e}")
    record_moderation_event(
        uid,
        "verified_granted" if grant else "verified_removed",
        mode=track,
        reason=note or None,
        actor_id=getattr(actor, "id", None),
        log=log_ref,
    )
    return {
        "title": title,
        "summary": f"{member.display_name} — {label} {'given' if grant else 'taken away'}.",
        "notes": notes,
        "stats": {},
        "log_url": (log_ref or {}).get("url"),
    }


# ————— VIP (formerly /make_vip) —————

def _vip_rows_mysql(where: str, params: tuple) -> list:
    conn = None
    cursor = None
    try:
        conn = _db_get_connection()
        cursor = conn.cursor(dictionary=True)
        cursor.execute(f"SELECT * FROM vip_grants WHERE {where} ORDER BY granted_at DESC", params)
        rows = cursor.fetchall()
        for row in rows:
            row["details"] = _parse_mysql_json_obj(row.get("details"))
            for key in ("guild_id", "user_id", "source_guild_id", "source_grant_id", "granted_by", "decided_by", "notice_message_id"):
                if row.get(key) is not None:
                    row[key] = str(row[key])
        return rows
    finally:
        if cursor is not None:
            cursor.close()
        if conn is not None:
            conn.close()


def _vip_save_mysql(row: dict) -> None:
    conn = None
    cursor = None
    try:
        conn = _db_get_connection()
        cursor = conn.cursor()
        cols = _VIP_GRANT_COLUMNS
        values = [
            json.dumps(row.get(col) or {}, ensure_ascii=False) if col == "details" else row.get(col)
            for col in cols
        ]
        updates = ", ".join(f"{col} = VALUES({col})" for col in cols if col != "grant_id")
        cursor.execute(
            f"INSERT INTO vip_grants ({', '.join(cols)}) VALUES ({', '.join(['%s'] * len(cols))}) "
            f"ON DUPLICATE KEY UPDATE {updates}",
            values,
        )
        conn.commit()
    finally:
        if cursor is not None:
            cursor.close()
        if conn is not None:
            conn.close()


async def _vip_rows(where: str, params: tuple) -> list:
    return await _run_mysql_io(_vip_rows_mysql, where, params, label="vip grants read")


async def _vip_save(row: dict) -> None:
    row["updated_at"] = int(time.time())
    await _run_mysql_io(_vip_save_mysql, row, label="vip grant write")


async def _vip_local_rows(user_id) -> list:
    """This server's VIP rows for a member, newest first."""
    return await _vip_rows("guild_id = %s AND user_id = %s", (str(cur_gid()), str(user_id)))


def _vip_platform(url: str) -> str:
    match = re.match(r"^https?://([^/:?#]+)", url, re.I)
    host = (match.group(1) if match else "").lower()
    if host.startswith("www."):
        host = host[4:]
    for name, domains in VIP_LINK_PLATFORMS:
        if any(host == domain or host.endswith("." + domain) for domain in domains):
            return name
    return "Other"


def _vip_details(category: str, payload: dict) -> tuple:
    """(details, error) for a VIP grant: the creator's links, the PDX note or
    the Highly Trusted reason."""
    if category == "content_creator":
        raw = payload.get("links") or []
        if not isinstance(raw, list):
            return None, "❌ Add the creator's channel links."
        links, seen = [], set()
        for item in raw:
            url = str((item.get("url") if isinstance(item, dict) else item) or "").strip()
            if not url:
                continue
            if len(url) > VIP_LINK_MAX_LEN or not re.match(r"^https?://[^\s/$.?#][^\s]*$", url, re.I):
                return None, f"❌ `{url[:60]}` isn't a valid link — use the full https:// address."
            if url.lower() in seen:
                continue
            seen.add(url.lower())
            links.append({"platform": _vip_platform(url), "url": url})
        if not links:
            return None, "❌ Add at least one channel link (YouTube, Twitch, Kick…)."
        if len(links) > VIP_MAX_LINKS:
            return None, f"❌ At most {VIP_MAX_LINKS} links."
        return {"links": links}, None
    if category == "pdx_staff":
        note = re.sub(r"\s+", " ", str(payload.get("note") or "")).strip()[:VIP_NOTE_MAX]
        return ({"note": note} if note else {}), None
    if category == "highly_trusted":
        reason = str(payload.get("reason") or "").strip()
        if len(reason) < VIP_REASON_MIN:
            return None, f"❌ Say why they're highly trusted (at least {VIP_REASON_MIN} characters)."
        return {"reason": reason[:VIP_REASON_MAX]}, None
    return None, "❌ Pick a VIP category: Content Creator, PDX Staff or Highly Trusted."


def _vip_details_text(category: str, details: dict) -> str:
    details = details or {}
    if category == "content_creator":
        return "\n".join(f"• {link.get('platform')}: {link.get('url')}" for link in details.get("links") or []) or "—"
    if category == "highly_trusted":
        return details.get("reason") or "—"
    return details.get("note") or "Paradox staff"


async def _vip_give_roles(member, reason: str, *, actor_id=None) -> list:
    """The VIP bundle: VIP, both Verified roles and both Trusted roles.
    A Verified role it adds is recorded like any verification ("Comes
    with VIP"), so the record shows who gave it and when."""
    lines = []
    verified_tracks = {"RP Verified": "Roleplay", "Hist Verified": "Historical"}
    bundle = [
        ("VIP", ROLE_IDS.get("VIP_ROLE_ID")),
        ("RP Verified", ROLE_IDS["HOI4_VERIFIED"]),
        ("Hist Verified", ROLE_IDS.get("HIST_VERIFIED")),
        ("HOI4 RP Trusted", ROLE_IDS["HOI4_RP_TRUSTED"]),
        ("HOI4 MP Trusted", ROLE_IDS["HOI4_MP_TRUSTED"]),
    ]
    for label, role_id in bundle:
        if not role_id:
            lines.append(f"⚠️ {label}: the role isn't set up yet.")
            continue
        note = await _assign_discord_role(member, int(role_id), reason=reason)
        lines.append(f"{label}: {note}")
        if label in verified_tracks and note.startswith("✅"):
            record_moderation_event(
                member.id, "verified_granted", mode=verified_tracks[label], reason="Comes with VIP",
                actor_id=actor_id, automatic=actor_id is None,
            )
        await asyncio.sleep(0.35)
    stats = await get_mysql_player_stats(str(member.id))
    stats["vip"] = True
    stats["hoi4_verified"] = True
    if ROLE_IDS.get("HIST_VERIFIED"):
        stats["hist_verified"] = True
    await save_mysql_player_stats(str(member.id), stats)
    return lines


async def _vip_take_role(member, user_id: str, reason: str) -> str:
    """Take the VIP role (Verified / Trusted stay — they're earned on their own)."""
    note = "ℹ️ They're not in the server — only the record changed."
    if member is not None:
        role = member.guild.get_role(int(ROLE_IDS.get("VIP_ROLE_ID") or 0))
        if role is not None and role in member.roles:
            try:
                await member.remove_roles(role, reason=reason)
                note = f"✅ Removed **{role.name}**."
            except Exception as e:
                note = f"⚠️ Couldn't remove the VIP role: {e}"
        else:
            note = "ℹ️ They didn't have the VIP role."
    stats = await get_mysql_player_stats(str(user_id))
    stats["vip"] = False
    await save_mysql_player_stats(str(user_id), stats)
    return note


async def _vip_log(title: str, color, *, user_id: str, actor_id=None, category=None, details=None, extra=()) -> dict | None:
    try:
        embed = discord.Embed(title=title, color=color, timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed.add_field(name="User", value=f"<@{user_id}> (`{user_id}`)", inline=True)
        if actor_id:
            embed.add_field(name="Staff", value=f"<@{actor_id}>", inline=True)
        if category:
            embed.add_field(name="Category", value=VIP_CATEGORIES.get(category, category), inline=True)
        if category and details is not None:
            embed.add_field(name="Details", value=_trim_field(_vip_details_text(category, details)), inline=False)
        for name, value in extra:
            embed.add_field(name=name, value=_trim_field(value or "—"), inline=False)
        embed.set_footer(text="VIP · web Database")
        return await send_host_log_embed(embed)
    except Exception as e:
        print(f"[WARN] VIP log failed: {e}")
        return None


async def _vip_post_notice(embed, view=None):
    """A staff notice in the management channel; returns the message id."""
    channel = bot.get_channel(G.VIP_NOTICE_CHANNEL_ID)
    if channel is None:
        try:
            channel = await bot.fetch_channel(G.VIP_NOTICE_CHANNEL_ID)
        except Exception:
            channel = None
    if channel is None:
        print(f"[WARN] VIP notice channel {G.VIP_NOTICE_CHANNEL_ID} not found.")
        return None
    try:
        message = await channel.send(embed=embed, view=view, allowed_mentions=discord.AllowedMentions.none())
        return message.id
    except Exception as e:
        print(f"[WARN] VIP notice failed: {e}")
        return None


async def _vip_close_notice(row: dict, text: str) -> None:
    """Mark a staff notice as decided and drop its buttons (best effort)."""
    message_id = row.get("notice_message_id")
    if not message_id:
        return
    try:
        channel = bot.get_channel(G.VIP_NOTICE_CHANNEL_ID) or await bot.fetch_channel(G.VIP_NOTICE_CHANNEL_ID)
        message = await channel.fetch_message(int(message_id))
        embed = message.embeds[0] if message.embeds else discord.Embed(title="VIP")
        embed.add_field(name="Decision", value=text, inline=False)
        await message.edit(embed=embed, view=None)
    except Exception as e:
        print(f"[WARN] closing VIP notice {message_id} failed: {e}")


def _vip_notice_view(grant_id: str, ops) -> discord.ui.View:
    view = discord.ui.View(timeout=None)
    for op in ops:
        view.add_item(VipNoticeButton(op, grant_id))
    return view


def _vip_new_row(**fields) -> dict:
    row = {col: None for col in _VIP_GRANT_COLUMNS}
    row.update(grant_id=uuid.uuid4().hex, guild_id=str(cur_gid()), granted_at=int(time.time()))
    row.update(fields)
    return row


async def apply_vip_grant(*, guild, actor, user_id: int, category: str, payload: dict) -> dict:
    """Give VIP with a category (Host Management only). Raises ModerationError."""
    if not _member_is_staff(actor):
        raise ModerationError("❌ Only Host Management (or admins) can give VIP.")
    if category not in VIP_CATEGORIES:
        raise ModerationError("❌ Pick a VIP category: Content Creator, PDX Staff or Highly Trusted.")
    details, err = _vip_details(category, payload or {})
    if err:
        raise ModerationError(err)
    uid = str(user_id)
    if uid == str(getattr(actor, "id", "")):
        raise ModerationError("❌ You can't give yourself VIP — ask another Host Management member.")
    member = await _get_member_safe(guild, uid)
    if member is None:
        raise ModerationError("❌ They're not in the server — VIP can only be given to members.")
    label = VIP_CATEGORIES[category]
    now = int(time.time())
    notes: list[str] = []
    for row in await _vip_local_rows(uid):
        if row["status"] in ("active", "pending"):
            row.update(status="removed", decided_by=str(actor.id), decided_at=now, decision_note="Replaced by a new VIP grant")
            await _vip_save(row)
            notes.append(f"Replaced their earlier {VIP_CATEGORIES.get(row['category'], row['category'])} VIP.")
            await _vip_close_notice(row, f"Replaced by a new VIP grant from <@{actor.id}>.")
    lines = await _vip_give_roles(member, f"VIP ({label}) by {actor.display_name} via the web Database", actor_id=actor.id)
    grant = _vip_new_row(
        guild_name=(guild.name or "")[:100], user_id=uid, category=category, details=details,
        status="active", granted_by=str(actor.id), granted_at=now,
    )
    await _vip_save(grant)
    notes.extend(line for line in lines if "ℹ️" not in line)
    if category == "pdx_staff":
        dm = discord.Embed(
            title="🌟 You're a VIP here",
            description=(
                f"The staff of **{guild.name}** marked you as **Paradox (PDX) staff** and gave you VIP.\n\n"
                "If that's right, there's nothing to do — welcome! If you're **not** Paradox staff, press the "
                "button below: we'll take the VIP role away and let the staff know."
            ),
            color=discord.Color.gold(),
        )
        view = discord.ui.View(timeout=None)
        view.add_item(VipNotMeButton(grant["grant_id"]))
        dm_ok = await _dm_user_safe(member, embed=dm, view=view, label="vip pdx notice")
        notes.append("They got a DM about it, with a \"This isn't me\" button." if dm_ok else "⚠️ Couldn't DM them (their DMs are closed).")
    log = await _vip_log(
        f"🌟 VIP Granted — {label}", discord.Color.gold(), user_id=uid, actor_id=actor.id,
        category=category, details=details, extra=[("Roles", "\n".join(lines))],
    )
    record_moderation_event(
        uid, "vip_granted", reason=label, actor_id=actor.id,
        details={"category": category, **details}, log=log,
    )
    return {
        "title": f"🌟 VIP — {label}",
        "summary": f"{member.display_name} is now VIP ({label}).",
        "notes": notes,
        "stats": {},
        "log_url": (log or {}).get("url"),
    }


async def apply_vip_remove(*, guild, actor, user_id: int, reason: str, by_self: bool = False) -> dict:
    """Take VIP away (Host Management — or the member, from the PDX DM)."""
    if not by_self and not _member_is_staff(actor):
        raise ModerationError("❌ Only Host Management can take VIP away.")
    reason = re.sub(r"\s+", " ", str(reason or "")).strip()[:300]
    if not by_self and len(reason) < 3:
        raise ModerationError("❌ Please give a reason.")
    uid = str(user_id)
    member = await _get_member_safe(guild, uid)
    rows = [row for row in await _vip_local_rows(uid) if row["status"] == "active"]
    vip_role_id = int(ROLE_IDS.get("VIP_ROLE_ID") or 0)
    has_role = bool(member is not None and vip_role_id and member.get_role(vip_role_id) is not None)
    if not rows and not has_role:
        raise ModerationError("ℹ️ They aren't VIP here.")
    actor_id = str(getattr(actor, "id", "") or "")
    note = await _vip_take_role(member, uid, f"VIP removed: {reason or 'said they are not Paradox staff'}")
    now = int(time.time())
    for row in rows:
        row.update(status="removed", decided_by=actor_id, decided_at=now,
                   decision_note=reason or "Said they aren't Paradox staff")
        await _vip_save(row)
        await _vip_close_notice(row, f"🚫 VIP removed by <@{actor_id}>.")
    category = rows[0]["category"] if rows else None
    title = "✋ VIP Removed — they said they aren't Paradox staff" if by_self else "🚫 VIP Removed"
    log = await _vip_log(
        title, discord.Color.dark_grey(), user_id=uid, actor_id=None if by_self else actor_id,
        category=category, extra=[("Reason", reason or "Pressed \"This isn't me\" on the PDX Staff DM."), ("Role", note)],
    )
    record_moderation_event(
        uid, "vip_removed", reason=reason or "Said they aren't Paradox staff", actor_id=actor_id or None,
        details={"category": category, "by_self": by_self}, log=log,
    )
    if by_self:
        await _vip_post_notice(discord.Embed(
            title="✋ VIP removed — not Paradox staff",
            description=f"<@{uid}> said they aren't Paradox staff, so their **PDX Staff** VIP was taken away.",
            color=discord.Color.orange(),
        ))
    return {
        "title": title,
        "summary": f"<@{uid}> is no longer VIP." if member is None else f"{member.display_name} is no longer VIP.",
        "notes": [note],
        "stats": {},
        "log_url": (log or {}).get("url"),
    }


async def apply_vip_decision(*, guild, actor, user_id: int, approve: bool, note: str = "", grant_id: str | None = None) -> dict:
    """Approve or decline a Highly Trusted VIP carried over from another server."""
    if not _member_is_staff(actor):
        raise ModerationError("❌ Only Host Management can approve VIP from another server.")
    uid = str(user_id)
    pending = [
        row for row in await _vip_local_rows(uid)
        if row["status"] == "pending" and (grant_id is None or row["grant_id"] == grant_id)
    ]
    if not pending:
        raise ModerationError("ℹ️ There's no VIP from another server waiting for approval.")
    row = pending[0]
    label = VIP_CATEGORIES.get(row["category"], row["category"])
    origin = row.get("source_guild_name") or "another server"
    note = re.sub(r"\s+", " ", str(note or "")).strip()[:300]
    notes: list[str] = []
    member = None
    if approve:
        member = await _get_member_safe(guild, uid)
        if member is None:
            raise ModerationError("❌ They're no longer in the server.")
        lines = await _vip_give_roles(
            member, f"VIP ({label}) from {origin}, approved by {actor.display_name}", actor_id=actor.id
        )
        notes.extend(line for line in lines if "ℹ️" not in line)
    row.update(status="active" if approve else "declined", decided_by=str(actor.id),
               decided_at=int(time.time()), decision_note=note or None)
    await _vip_save(row)
    await _vip_close_notice(row, f"{'✅ Approved' if approve else '✖️ Declined'} by <@{actor.id}>.")
    title = f"🌟 VIP from {origin} approved" if approve else f"✖️ VIP from {origin} declined"
    log = await _vip_log(
        title, discord.Color.gold() if approve else discord.Color.dark_grey(), user_id=uid, actor_id=actor.id,
        category=row["category"], details=row.get("details"), extra=[("Note", note)] if note else (),
    )
    record_moderation_event(
        uid, "vip_granted" if approve else "vip_declined", reason=label, actor_id=actor.id,
        details={"category": row["category"], "from_server": origin, **(row.get("details") or {})}, log=log,
    )
    return {
        "title": title,
        "summary": f"<@{uid}> — {label} VIP {'given here' if approve else 'not given here'}.",
        "notes": notes,
        "stats": {},
        "log_url": (log or {}).get("url"),
    }


async def _vip_sync_member(member, *, trigger: str = "sweep"):
    """Carry a VIP given on another server over to this one: Content Creator
    and PDX Staff right away (staff get a notice with Remove VIP), Highly
    Trusted after this server's staff approve it. Each grant is carried over
    once — a VIP removed or declined here stays that way."""
    if member is None or member.bot or member.guild is None or member.guild.id != cur_gid():
        return None
    uid = str(member.id)
    foreign = await _vip_rows(
        "user_id = %s AND guild_id <> %s AND status = 'active' AND source_grant_id IS NULL",
        (uid, str(cur_gid())),
    )
    if not foreign:
        return None
    local = await _vip_local_rows(uid)
    if any(row["status"] in ("active", "pending") for row in local):
        return None
    vip_role_id = int(ROLE_IDS.get("VIP_ROLE_ID") or 0)
    if vip_role_id and member.get_role(vip_role_id) is not None:
        return None  # already VIP here (given before VIP records existed)
    seen = {row.get("source_grant_id") for row in local}
    candidates = [row for row in foreign if row["grant_id"] not in seen]
    if not candidates:
        return None
    candidates.sort(key=lambda row: (row["category"] not in VIP_TRANSFERABLE, -int(row.get("granted_at") or 0)))
    source = candidates[0]
    # Content Creator / PDX Staff carry over by themselves unless the server
    # settings say every carried-over VIP needs approval.
    transferable = source["category"] in VIP_TRANSFERABLE and SERVER_FEATURES.get("vip_auto_carry_over", True)
    label = VIP_CATEGORIES.get(source["category"], source["category"])
    origin = source.get("guild_name") or "another server"
    row = _vip_new_row(
        guild_name=(member.guild.name or "")[:100], user_id=uid, category=source["category"],
        details=source.get("details") or {}, status="active" if transferable else "pending",
        source_guild_id=source["guild_id"], source_guild_name=origin, source_grant_id=source["grant_id"],
    )
    await _vip_save(row)
    joined = " when they joined" if trigger == "join" else ""
    if transferable:
        lines = await _vip_give_roles(member, f"VIP ({label}) carried over from {origin}")
        log = await _vip_log(
            f"🌟 VIP carried over from {origin}", discord.Color.gold(), user_id=uid,
            category=source["category"], details=source.get("details"), extra=[("Roles", "\n".join(lines))],
        )
        record_moderation_event(
            uid, "vip_granted", reason=label, automatic=True,
            details={"category": source["category"], "from_server": origin, **(source.get("details") or {})}, log=log,
        )
        embed = discord.Embed(
            title=f"{VIP_CATEGORY_ICONS.get(source['category'], '🌟')} VIP from another server — {label}",
            description=(
                f"<@{uid}> is a **{label}** VIP on **{origin}**, so they got VIP here automatically{joined}.\n"
                "Press **Remove VIP** if they shouldn't have it here."
            ),
            color=discord.Color.gold(),
        )
        ops = ("remove",)
    else:
        embed = discord.Embed(
            title="🔔 Highly Trusted VIP — needs your approval",
            description=(
                f"<@{uid}> is a **Highly Trusted** VIP on **{origin}**{' and just joined this server' if trigger == 'join' else ''}.\n"
                "Highly Trusted VIP doesn't carry over by itself — approve it to give them VIP here."
            ),
            color=discord.Color.blurple(),
        )
        ops = ("approve", "decline")
    granted_by = source.get("granted_by")
    embed.add_field(
        name=f"Given on {origin}",
        value=f"{f'by <@{granted_by}> · ' if granted_by else ''}<t:{int(source.get('granted_at') or 0)}:D>",
        inline=False,
    )
    embed.add_field(name="Details", value=_trim_field(_vip_details_text(source["category"], source.get("details"))), inline=False)
    message_id = await _vip_post_notice(embed, _vip_notice_view(row["grant_id"], ops))
    if message_id:
        row["notice_message_id"] = str(message_id)
        await _vip_save(row)
    return row["status"]


@bot.event
async def on_member_join(member: discord.Member):
    """A member joining this server: carry over a VIP they hold elsewhere."""
    if member.bot or member.guild is None or not _guild_active(member.guild.id):
        return
    enter_guild(member.guild.id)
    try:
        await _vip_sync_member(member, trigger="join")
    except Exception as e:
        print(f"[WARN] VIP carry-over on join failed for {member.id}: {e}")
    try:
        await _alert_cross_server_bans(member)
    except Exception as e:
        print(f"[WARN] cross-server ban check on join failed for {member.id}: {e}")


@tasks.loop(minutes=VIP_SYNC_INTERVAL_MIN)
async def vip_cross_server_loop():
    """Runs once per active server (_vip_cross_server_loop_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_vip_cross_server_loop_for_guild, "vip_cross_server_loop")


async def _vip_cross_server_loop_for_guild():
    """Catch VIPs given on other servers after the member joined this one."""
    await bot.wait_until_ready()
    guild = bot.get_guild(cur_gid())
    if guild is None or not guild.members:
        return
    try:
        foreign = await _vip_rows(
            "guild_id <> %s AND status = 'active' AND source_grant_id IS NULL", (str(cur_gid()),)
        )
    except Exception as e:
        print(f"⚠️ VIP cross-server read failed: {e}")
        return
    for user_id in dict.fromkeys(row["user_id"] for row in foreign):
        member = guild.get_member(int(user_id)) if str(user_id).isdigit() else None
        if member is None:
            continue
        try:
            await _vip_sync_member(member, trigger="sweep")
        except Exception as e:
            print(f"[WARN] VIP carry-over for {user_id} failed: {e}")
        await asyncio.sleep(1)


class VipNoticeButton(discord.ui.DynamicItem[discord.ui.Button],
                      template=r"vipn:(?P<op>remove|approve|decline):(?P<grant>[0-9a-f]{32})"):
    """Remove / Approve / Decline on a cross-server VIP staff notice (restart-proof)."""

    LOOKS = {
        "remove": ("Remove VIP", discord.ButtonStyle.danger, "🚫"),
        "approve": ("Approve VIP", discord.ButtonStyle.success, "✅"),
        "decline": ("Decline", discord.ButtonStyle.secondary, "✖️"),
    }

    def __init__(self, op: str, grant_id: str):
        self.op = op
        self.grant_id = grant_id
        label, style, emoji = self.LOOKS[op]
        super().__init__(discord.ui.Button(label=label, style=style, emoji=emoji, custom_id=f"vipn:{op}:{grant_id}"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(match["op"], match["grant"])

    async def callback(self, interaction: discord.Interaction):
        if not _member_is_staff(interaction.user):
            return await _interaction_notice(interaction, "❌ Only Host Management can decide this.")
        await interaction.response.defer(ephemeral=True)
        rows = await _vip_rows("grant_id = %s", (self.grant_id,))
        if not rows:
            return await interaction.followup.send("❌ That VIP record no longer exists.", ephemeral=True)
        row = rows[0]
        try:
            if self.op == "remove":
                result = await apply_vip_remove(
                    guild=interaction.guild, actor=interaction.user, user_id=int(row["user_id"]),
                    reason="Removed from the cross-server VIP notice",
                )
            else:
                result = await apply_vip_decision(
                    guild=interaction.guild, actor=interaction.user, user_id=int(row["user_id"]),
                    approve=self.op == "approve", grant_id=self.grant_id,
                )
        except ModerationError as e:
            return await interaction.followup.send(str(e), ephemeral=True)
        await interaction.followup.send(f"{result['title']} — {result['summary']}", ephemeral=True)


class VipNotMeButton(discord.ui.DynamicItem[discord.ui.Button], template=r"vipnotme:(?P<grant>[0-9a-f]{32})(?::g\d+)?"):
    """"This isn't me" on the PDX Staff VIP DM: takes the VIP away and tells staff."""

    def __init__(self, grant_id: str):
        self.grant_id = grant_id
        super().__init__(discord.ui.Button(
            label="This isn't me", style=discord.ButtonStyle.danger, emoji="✋", custom_id=f"vipnotme:{grant_id}{_guild_suffix()}",
        ))

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(match["grant"])

    async def callback(self, interaction: discord.Interaction):
        rows = await _vip_rows("grant_id = %s", (self.grant_id,))
        row = rows[0] if rows else None
        if row is None or row["user_id"] != str(interaction.user.id):
            return await _interaction_notice(interaction, "❌ This button isn't for you.")
        if row["status"] != "active":
            return await _interaction_notice(interaction, "ℹ️ That VIP was already taken away.")
        try:
            await apply_vip_remove(
                guild=bot.get_guild(cur_gid()), actor=interaction.user, user_id=interaction.user.id,
                reason="Said they aren't Paradox staff", by_self=True,
            )
        except ModerationError as e:
            return await _interaction_notice(interaction, str(e))
        try:
            await interaction.response.edit_message(view=None)
        except Exception:
            pass
        await _interaction_notice(interaction, "✅ Thanks — the VIP role was taken away and the staff were told.")


# ————— Host tier (formerly /make_host) —————

async def apply_host_tier(*, guild, actor, user_id: int, tier: str, note: str = "", branch: str = "RP") -> dict:
    """Set a member's rank in one host branch (RP / HIST): Assistant / Full /
    Senior, or "None" to take that branch away. Host Management only; stays on
    this server (host ranks don't carry over). Raises ModerationError."""
    branch = str(branch or "RP").upper()
    if branch not in HOST_BRANCHES:
        raise ModerationError("❌ Pick a host branch: RP or HIST.")
    if tier == "Trial":
        tier = "Assistant"
    if not _member_is_staff(actor):
        raise ModerationError("❌ Only Host Management (or admins) can change host roles.")
    if tier not in HOST_TIER_CHOICES:
        raise ModerationError("❌ Pick a host rank: Assistant, Full, Senior or none.")
    uid = str(user_id)
    if uid == str(getattr(actor, "id", "")):
        raise ModerationError("❌ You can't change your own host role — ask another Host Management member.")
    note = re.sub(r"\s+", " ", str(note or "")).strip()[:300]
    if tier == "None" and len(note) < 3:
        raise ModerationError("❌ Please give a reason for taking the host role away.")
    member = await _get_member_safe(guild, uid)
    if member is None:
        raise ModerationError("❌ They're not in the server.")
    cfg = {"host_tiers": HOST_BRANCHES[branch]["ranks"], "host_tier_db_field": HOST_BRANCHES[branch]["tier_db_field"]}
    if tier != "None" and not cfg["host_tiers"].get(tier):
        ranks_on = (((_rt().settings or {}).get("branches") or {}).get(branch) or {}).get("ranks_on") or {}
        if tier in OPTIONAL_HOST_RANKS and ranks_on.get(tier) is False:
            raise ModerationError(f"❌ {tier} {branch} hosts are switched off in this server's settings (Host ranks).")
        raise ModerationError(f"❌ The {branch} host roles aren't set up yet — pick them in the server settings (Host ranks).")
    before = _host_tier_for_member(member, cfg)
    if before == tier:
        raise ModerationError(
            f"ℹ️ They aren't in the {branch} branch." if tier == "None"
            else f"ℹ️ They're already {tier} {branch} Host."
        )
    reason = f"{branch} host rank → {tier} by {getattr(actor, 'display_name', actor)} (web Database)"
    notes: list[str] = []
    for tier_name, role_id in cfg["host_tiers"].items():
        role = guild.get_role(role_id)
        if role is None or role not in member.roles or tier_name == tier:
            continue
        try:
            await member.remove_roles(role, reason=reason)
            notes.append(f"➖ Removed **{role.name}**")
            await asyncio.sleep(TRUSTED_ROLE_AUDIT_SLEEP_SEC)
        except Exception as e:
            raise ModerationError(f"❌ Couldn't remove **{role.name}**: {e}")
    if tier != "None":
        role_note = await _assign_discord_role(member, cfg["host_tiers"][tier], reason=reason)
        if role_note.startswith("❌"):
            raise ModerationError(role_note)
        notes.append(role_note)
    stats = await get_mysql_player_stats(uid)
    stats[cfg["host_tier_db_field"]] = tier
    await save_mysql_player_stats(uid, stats)
    # Let them use the website's host pages right away (the roster refreshes every few minutes).
    try:
        await web_host_roster_loop.coro()
    except Exception as e:
        print(f"[WARN] host roster refresh after host tier change failed: {e}")

    label = f"No {branch} host role" if tier == "None" else f"{tier} {branch} Host"
    was = f"no {branch} host role" if before == "None" else f"{before} {branch} Host"
    title = f"🎖️ {branch} Host Role Removed" if tier == "None" else f"🎖️ {branch} Host Rank Updated"
    log_ref = None
    try:
        log_embed = discord.Embed(
            title=title, color=discord.Color.blue(), timestamp=datetime.datetime.now(datetime.timezone.utc)
        )
        log_embed.add_field(name="User", value=f"<@{uid}> (`{uid}`)", inline=True)
        log_embed.add_field(name="Change", value=f"{was} → **{label}**", inline=True)
        log_embed.add_field(name="Staff", value=f"<@{getattr(actor, 'id', 0)}>", inline=True)
        log_embed.add_field(name="Role changes", value=_trim_field("\n".join(notes) or "—"), inline=False)
        if note:
            log_embed.add_field(name="Reason" if tier == "None" else "Note", value=_trim_field(note), inline=False)
        log_embed.set_footer(text="Via the web Database")
        log_ref = await send_host_log_embed(log_embed)
    except Exception as e:
        print(f"[WARN] host tier log failed: {e}")
    record_moderation_event(
        uid, "host_tier_set", mode=branch, reason=note or None, actor_id=getattr(actor, "id", None),
        details={"branch": branch, "from": before, "to": tier}, log=log_ref,
    )
    return {
        "title": title,
        "summary": f"{member.display_name}: {was} → {label}.",
        "notes": notes,
        "stats": {},
        "log_url": (log_ref or {}).get("url"),
    }


async def _process_web_member_roles(req: dict):
    """Web Database page → verification / VIP / host tier (formerly /verify,
    /make_vip, /make_host)."""
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None:
        return False, None, "❌ You need to be a member of the Discord server."
    raw_uid = str(payload.get("user_id") or "")
    if not raw_uid.isdigit():
        return False, None, "❌ Invalid player."
    guild = bot.get_guild(cur_gid())
    op = str(payload.get("op") or "")
    try:
        if op in ("verify", "unverify"):
            result = await apply_verification(
                guild=guild, actor=actor, user_id=int(raw_uid), track=str(payload.get("track") or ""),
                grant=op == "verify", note=str(payload.get("reason") or ""),
            )
        elif op == "vip_grant":
            result = await apply_vip_grant(
                guild=guild, actor=actor, user_id=int(raw_uid), category=str(payload.get("category") or ""),
                payload=payload,
            )
        elif op == "vip_remove":
            result = await apply_vip_remove(
                guild=guild, actor=actor, user_id=int(raw_uid), reason=str(payload.get("reason") or ""),
            )
        elif op == "host_tier":
            result = await apply_host_tier(
                guild=guild, actor=actor, user_id=int(raw_uid), tier=str(payload.get("tier") or ""),
                note=str(payload.get("reason") or ""), branch=str(payload.get("branch") or "RP"),
            )
        elif op in ("vip_approve", "vip_decline"):
            result = await apply_vip_decision(
                guild=guild, actor=actor, user_id=int(raw_uid), approve=op == "vip_approve",
                note=str(payload.get("reason") or ""),
            )
        else:
            return False, None, f"❌ Unknown role action: {op}."
    except ModerationError as e:
        return False, None, str(e)
    _audit_log("INFO", f"web member_roles {op} user={raw_uid} by={actor.id}")
    return True, {"moderation": result}, None


def get_category_name_for_nation(nation: str, game_mode: str):
    # 1. Fillers
    if nation.startswith("Filler") or nation.startswith("_FILL_"):
        return "📦 FILLER NATIONS"

    cat_key = globals().get('get_mapped_mode', lambda x: x)(game_mode)
    mode_data = globals().get("NATION_CATEGORIES", {}).get(cat_key, {})

    # 3. Historical (Faction Based)
    if "Historical" in game_mode:
        for faction, groups in mode_data.items():
            if nation in groups.get("Majors", []) or \
               nation in groups.get("Important Minors", []) or \
               nation in groups.get("Minors", []):
                return f"🛡️ {faction.upper()}"
        return "⚠️ UNMAPPED NATIONS"

    # 4. Regional (RP/KR/MD)
    regions_to_use = globals().get("REGION_GROUPS", {})

    # Check Major Locations first
    major_locs = globals().get("MAJOR_LOCATIONS", {})
    if nation in major_locs:
        return f"🎮 {major_locs[nation].upper()}"

    # Check Sub-regions
    for cat_name, sub_regions in regions_to_use.items():
        for sub in sub_regions:
            nations_in_sub = mode_data.get(sub, [])
            if nation in nations_in_sub:
                return f"🎮 {cat_name.upper()}"

    return "⚠️ UNMAPPED NATIONS"

