def _host_settings_summary_line(settings: dict | None) -> str:
    """Compact board suffix for a slot's web-configured randomizer engines.
    Understands both the Phase 5 nested `randomizers` schema and the legacy
    Phase 2 flat schema."""
    if not settings:
        return ""
    parts = []
    randomizers = settings.get("randomizers")
    if isinstance(randomizers, dict):
        # Phase 5 schema — one token per enabled randomizer box.
        for key, token in (
            ("nation", "🎲N"),
            ("ideology", "🚩I"),
            ("path", "🌳P"),
            ("doctrine", "📜D"),
            ("build", "🔨B"),
            ("achievements", "🏆A"),
        ):
            entry = randomizers.get(key)
            if isinstance(entry, dict) and entry.get("enabled"):
                parts.append(token)
        if parts:
            return f" ⚙️{'·'.join(parts)}"
        return ""
    # Legacy Phase 2 schema.
    if settings.get("rocketRoulette"):
        parts.append("🎲RR")
    if settings.get("focusTree"):
        parts.append("🌳FTR")
    if settings.get("chaosWheel"):
        parts.append("🌀CHAOS")
    if not parts:
        return ""
    mode = (settings.get("randomizerMode") or "casual").title()
    return f" ⚙️{'·'.join(parts)}({mode})"








def _schedule_category(mode: str) -> str:
    """Collapse a full game mode into one of the 2 scheduling categories."""
    m = mode or ""
    if "Historical" in m:
        return "Historical"
    # Roleplay variants (MD, KR, TFR) all fall here.
    return "Roleplay"




def _week_monday(d: datetime.date) -> datetime.date:
    """Return the Monday of the week containing date d."""
    return d - datetime.timedelta(days=d.weekday())


def _item_week(item: dict) -> str:
    """Week key (Monday ISO date) for a schedule item; derived from the game
    timestamp (explicit UTC) if the item predates the weekly-table system."""
    w = item.get("week")
    if w:
        return w
    ts = item.get("game_timestamp", 0)
    try:
        d = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).date()
        return _week_monday(d).isoformat()
    except Exception:
        return _week_monday(datetime.date.today()).isoformat()


def _week_range_label(monday_iso: str) -> str:
    """Human label for a week, e.g. '22-28 June' or '29 Jun - 5 Jul'."""
    try:
        monday = datetime.date.fromisoformat(monday_iso)
    except Exception:
        monday = _week_monday(datetime.date.today())
    sunday = monday + datetime.timedelta(days=6)
    if monday.month == sunday.month:
        return f"{monday.day}-{sunday.day} {monday.strftime('%B')}"
    return f"{monday.day} {monday.strftime('%b')} - {sunday.day} {sunday.strftime('%b')}"


def _candidate_schedule_weeks() -> list:
    """The weeks a host is currently allowed to pick from: this week, next week,
    and (from Friday onward) the week after that."""
    today = datetime.date.today()
    this_mon = _week_monday(today)
    options = [this_mon, this_mon + datetime.timedelta(days=7)]
    if today.weekday() >= 4:  # Fri/Sat/Sun → allow booking the week after next
        options.append(this_mon + datetime.timedelta(days=14))
    return options


def _resolve_schedule_week(table_input: str) -> str | None:
    """Resolve a week reference (a Monday-ISO date, any date in that week, or a
    week label such as '19-25 October') into a Monday-ISO week key. Used by
    the web calendar requests; None when it can't be resolved."""
    if not table_input:
        return None
    raw = table_input.strip()
    try:
        return _week_monday(datetime.date.fromisoformat(raw)).isoformat()
    except Exception:
        pass

    cleaned = raw.lower().replace("📅", "").strip()
    for mon in _candidate_schedule_weeks():
        iso = mon.isoformat()
        label = _week_range_label(iso).lower()
        if cleaned in (iso, label) or (cleaned and (cleaned in label or label in cleaned)):
            return iso
    return None


def _find_other_host_conflict(schedule_data, week: str, day: str, category: str, exclude_host_id: int) -> dict | None:
    """Multiple hosts CAN now share the same day/category — this just finds
    whether another host already has one, so we can warn (not block)."""
    day_l = (day or "").lower()
    for item in schedule_data:
        if (_item_week(item) == week
                and (item.get("day") or "").lower() == day_l
                and _schedule_category(item.get("mode", "")) == category
                and item.get("host_id") != exclude_host_id):
            return item
    return None


def _conflict_warning_text(conflict_item: dict) -> str:
    other_host_id = conflict_item.get("host_id")
    other_mode = conflict_item.get("mode", "a game")
    other_ts = conflict_item.get("game_timestamp")
    when = f"<t:{other_ts}:F>" if other_ts else "an unspecified time"
    return (
        f"⚠️ **Heads up — another host already has a game scheduled that day.**\n"
        f"Host: <@{other_host_id}> — **{other_mode}** at {when}.\n\n"
        f"Multiple hosts can now run the same game mode on the same day, so this won't block you — "
        f"would you like to continue with your own scheduling anyway?"
    )


class ScheduleConflictWarningView(discord.ui.View):
    """Shown when a different host already has a same-category game booked for
    the same day/table. This is only a heads-up — continuing never overwrites
    or cancels the other host's slot, both games simply coexist on the board."""

    def __init__(self, on_continue, requester_id: int):
        super().__init__(timeout=180)
        self.on_continue = on_continue
        self.requester_id = requester_id

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.requester_id:
            await interaction.response.send_message("❌ This confirmation isn't for you.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Continue Anyway", style=discord.ButtonStyle.success, emoji="✅")
    async def continue_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        for child in self.children:
            child.disabled = True
        await interaction.response.edit_message(content="✅ Continuing with your scheduling...", view=self)
        await self.on_continue(interaction)

    @discord.ui.button(label="Cancel", style=discord.ButtonStyle.danger, emoji="🚫")
    async def cancel_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        for child in self.children:
            child.disabled = True
        await interaction.response.edit_message(content="🚫 Scheduling cancelled.", view=self)


def _find_day_lock(locked_days: list, week: str, day: str) -> dict | None:
    day_l = (day or "").lower()
    for rec in locked_days:
        if rec.get("week") == week and (rec.get("day") or "").lower() == day_l:
            return rec
    return None


async def _get_day_lock(week: str, day: str) -> dict | None:
    locked_days = await read_json(LOCKED_DAYS_FILE)
    return _find_day_lock(locked_days, week, day)


def _schedule_slot_lookup_key(host_id, mode, timestamp) -> tuple:
    try:
        ts = int(timestamp) if timestamp else 0
    except (TypeError, ValueError):
        ts = 0
    return (int(host_id or 0), str(mode or ""), ts)


async def _mark_schedule_slot_board_status(host_id, mode, game_timestamp, status: str):
    """Persist cancelled/ended on the matching schedule slot and refresh the board.
    Also flips the slot's explicit lifecycle `status` so the board never falls
    back to a stale lookup afterwards."""
    if not game_timestamp or status not in ("cancelled", "ended"):
        return
    schedule_data = await read_json(SCHEDULE_FILE)
    target = _schedule_slot_lookup_key(host_id, mode, game_timestamp)
    updated = False
    for item in schedule_data:
        if _schedule_slot_lookup_key(item.get("host_id"), item.get("mode"), item.get("game_timestamp")) == target:
            item["board_status"] = status
            item["status"] = status
            updated = True
            break
    if updated:
        await write_json(SCHEDULE_FILE, schedule_data)


