def _current_addon(value):
    """A slot's add-on with retired ones swapped for what replaced them."""
    return _RETIRED_ADDONS[value] if value in _RETIRED_ADDONS else value

_schedule_slot_write_lock = asyncio.Lock()

# Shared Host Access Key — an 8-character alphanumeric key minted at /schedule
# time. Any Senior/Authorized Host who presents it can open and edit the
# session's /host panel (multi-host management).
_HOST_KEY_ALPHABET = string.ascii_uppercase + string.digits
_HOST_KEY_LENGTH = 8


def _generate_host_key() -> str:
    """Secure random 8-character alphanumeric host access key."""
    return "".join(secrets.choice(_HOST_KEY_ALPHABET) for _ in range(_HOST_KEY_LENGTH))


async def _save_schedule_slot(slot: dict) -> tuple[bool, str | None]:
    """Persist a schedule slot. Multiple hosts can now share a day/category —
    that's surfaced upfront as a confirmation prompt, not enforced here. The
    only thing that still blocks a save outright is a staff day-lock (checked
    again here as a race-safety net, e.g. if the day got locked while the host
    was filling out the announcement modal)."""
    async with _schedule_slot_write_lock:
        locked = await _get_day_lock(_item_week(slot), slot.get("day"))
        if locked:
            return False, (
                f"⛔ **{slot.get('day')}** was locked by staff while you were scheduling "
                f"and can no longer accept new games."
            )
        schedule_data = list(await read_json(SCHEDULE_FILE))
        persisted_slot = dict(slot)
        # Surface the slot id back onto the caller's dict so /schedule can
        # mint the host-panel token for it immediately.
        slot["slot_id"] = persisted_slot.setdefault("slot_id", uuid.uuid4().hex)
        schedule_data.append(persisted_slot)
        await write_json(SCHEDULE_FILE, schedule_data)
    # Audit trail: prove the exact integer that was written to MySQL — it MUST
    # equal the host's /schedule input (no now()+24h fallback anywhere).
    _audit_log(
        "INFO",
        f"schedule slot persisted slot_id={slot.get('slot_id')} "
        f"game_timestamp={persisted_slot.get('game_timestamp')} "
        f"host={slot.get('host_id')} mode={slot.get('mode')}",
    )
    return True, None


async def _mark_schedule_slot_announced(slot: dict):
    """Mark one exact schedule slot as announced (🟩), matched by host/day/week/timestamp."""
    schedule_data = await read_json(SCHEDULE_FILE)
    target = _slot_autocomplete_value(slot)
    for item in schedule_data:
        if _slot_autocomplete_value(item) == target and not item.get("announced"):
            item["announced"] = True
            item["status"] = "announced"
            await write_json(SCHEDULE_FILE, schedule_data)
            return


async def _update_schedule_slot_draft_config(slot: dict, **fields) -> tuple[bool, str | None]:
    """Patch fields (thread_id, draft_* keys…) onto the schedule entry matching this slot."""
    schedule_data = await read_json(SCHEDULE_FILE)
    for item in reversed(schedule_data):
        if (
            item.get("host_id") == slot.get("host_id")
            and item.get("day") == slot.get("day")
            and _item_week(item) == _item_week(slot)
            and item.get("game_timestamp") == slot.get("game_timestamp")
        ):
            item.update(fields)
            await write_json(SCHEDULE_FILE, schedule_data)
            return True, None
    return False, "❌ Could not find the scheduled slot to update."


# Casino add-on modes (Casino Protocol / All Add-ons) manage their lock
# step-downs dynamically on the web — Host Panel 2-tier locks + /api/access.
# The Discord scheduled-nation-unlock loop SKIPS these add-ons (and the web
# calendar doesn't save per-scope unlocks for them); regular games keep it.
# Empty while the Casino is unavailable (it was ("randomizer",)).
_CASINO_WEB_LOCK_ADDONS = ()


def _game_manages_locks_via_web(game: dict) -> bool:
    """True for Casino add-on games (randomizer_only; `chaos` = All Add-ons
    games announced before that add-on was removed) — their lock
    step-downs are handled dynamically by the web engine, so the Discord
    scheduled-nation-unlock loop must skip them."""
    return bool(game.get("randomizer_only") or game.get("chaos"))




_command_sync_lock = asyncio.Lock()


def _is_senior_member(member: discord.Member | None) -> bool:
    if member is None:
        return False
    return any(role.id in SENIOR_MANAGEMENT_ROLES for role in member.roles)


async def _sync_guild_commands() -> int:
    """Bulk-overwrite the current server's slash commands (other servers get
    the home server's set minus the home-only ones — _sync_server_commands)."""
    return await _sync_server_commands(bot.get_guild(cur_gid()) or discord.Object(id=cur_gid()))




@tasks.loop(seconds=60)
async def check_scheduled_announcements():
    """Runs once per active server (_check_scheduled_announcements_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_check_scheduled_announcements_for_guild, "check_scheduled_announcements")


async def _check_scheduled_announcements_for_guild():
    await bot.wait_until_ready()

    try:
        schedule_data = await read_json(SCHEDULE_FILE)
        if not schedule_data:
            return

        current_time = int(time.time())
        locked_days = await read_json(LOCKED_DAYS_FILE)
        # Hearts of Valor perk: DM Valor holders 1 hour before each announcement.
        try:
            await _send_valor_early_notices(schedule_data, locked_days, current_time)
        except Exception as e:
            print(f"[WARN] Valor early notices failed: {e}")
        games_to_announce = []

        # Find slots whose announce time has arrived and that haven't fired yet.
        # Slots with no announce_timestamp (schedule-only) are never auto-announced.
        # A staff day-lock holds the auto-announce back (it'll fire once unlocked).
        for item in schedule_data:
            ann = item.get("announce_timestamp")
            if ann is None or current_time < ann or item.get("announced"):
                continue
            if _find_day_lock(locked_days, _item_week(item), item.get("day")):
                continue
            games_to_announce.append(item)

        if not games_to_announce:
            return

        # 1. Mark them announced immediately (🟩) so we don't double-post next minute.
        #    They stay on the board as "live" until the day passes.
        for item in games_to_announce:
            item["announced"] = True
        await write_json(SCHEDULE_FILE, schedule_data)

        guild = bot.get_guild(cur_gid())
        if not guild:
            return

        # 2. Fire off the announcements for the games whose time has come
        for item in games_to_announce:
            mode = resolve_mode_name(item.get("mode"))
            if mode != item.get("mode"):
                item["mode"] = mode
            host_id = item["host_id"]
            day = item["day"]
            game_timestamp = item["game_timestamp"]

            host = guild.get_member(host_id)
            if not host:
                print(f"Host {host_id} not found for scheduled game.")
                continue

            mode_config = MODE_CONFIG.get(mode)
            if not mode_config or not mode_config.get("announcement_channel_id"):
                continue

            announce_channel = guild.get_channel(mode_config["announcement_channel_id"])
            if not announce_channel:
                continue

            ping_role_id = mode_config.get("ping_role_id")
            ping_mention = f"<@&{ping_role_id}>" if ping_role_id else "@here"

            # Determine base_mode (whose rules channel / rulesets the game uses)
            base_mode = _announce_base_mode(mode)

            # Raw integer timestamp passed straight through — embeds render it
            # with native <t:...> tags; the compact UTC string is only for the
            # thread name (plain text, tags don't render there).
            date_str = datetime.datetime.fromtimestamp(
                game_timestamp, tz=datetime.timezone.utc
            ).strftime("%m.%d.%Y")

            # --- Resolve the scheduled add-on into per-game flags (mirrors /announce_game) ---
            addon_value = _current_addon(item.get("add_on")) or "none"
            if addon_value in _UNAVAILABLE_ADDONS:
                addon_value = "none"
            randomizer_only = (addon_value == "randomizer")
            fortunes_only = (addon_value == "fortunes")
            submod = SUBMOD_ADDONS.get(addon_value)
            randomizer_mode = item.get("randomizer_mode", "casual") if randomizer_only else None
            randomizer_type = (
                _normalize_randomizer_types(item.get("randomizer_type"))
                if randomizer_only else None
            )
            if randomizer_only and not randomizer_type:
                # Legacy slots scheduled before the flavor step — default to all flavors.
                randomizer_type = list(RANDOMIZER_TYPE_ORDER)

            # Post Mod & Rules Embeds: the preset's / calendar's lists, else the
            # mode's standard ones (casino games always add the casino rules).
            mod_entries = _slot_resource_entries(item, mode, "mods")
            rule_entries = _slot_resource_entries(item, mode, "rules", casino=randomizer_only)
            mod_msg_id = await post_mod_embed(guild, mode, game_timestamp, entries=mod_entries)
            rules_msg_id = await post_rules_embed(guild, base_mode, mode, game_timestamp, False, entries=rule_entries)

            # A preset's own nation groups: nations outside its playable groups
            # are hidden from the list and map, and stay locked.
            nation_layout = item.get("nation_layout") or None
            not_playable = [str(n) for n in item.get("layout_disabled_nations") or []] if nation_layout else []
            locked_at_start = list(dict.fromkeys([*(item.get("locked_regions") or []), *not_playable]))


            # Build the add-on header line + reservation command for the announcement
            if randomizer_only:
                rtype_label = f" — {_randomizer_type_label(randomizer_type)}" if randomizer_type else ""
                rm_label = "Competitive" if randomizer_mode == "competitive" else "Casual"
                addon_line = f"\n🎲 **CASINO PROTOCOL{rtype_label}** ({rm_label})"
                reserve_cmd = "/gamble"
            elif fortunes_only:
                fm_label = "Competitive" if item.get("fortunes_mode") == "competitive" else "Casual"
                addon_line = f"\n🃏 **FORTUNES OF WAR** ({fm_label})"
                reserve_cmd = "/draw"
            elif submod:
                addon_line = f"\n{submod['emoji']} **{submod['label'].upper()} SUBMOD**"
                reserve_cmd = None
            else:
                addon_line = ""
                reserve_cmd = None

            draft_config = _extract_draft_config(item)
            if draft_config:
                addon_line = f"{addon_line}\n🎯 **DRAFT GAME**"
                reserve_cmd = None

            # Short on purpose: the bell header, the time (Discord shows it in
            # each reader's own time zone), the host and the map link. Rules and
            # mods live behind the map's 📜 Rules / 🧩 Mods buttons.
            reserve_label = "Join the Draft Here" if draft_config else "Reserve Here"
            announcement_content = (
                f"# {ANNOUNCE_BELL_EMOJI} Game Announcement {ANNOUNCE_BELL_EMOJI}\n"
                f"||{ping_mention}||{addon_line}\n"
                f"**:clock4: <t:{game_timestamp}:F> (<t:{game_timestamp}:R>)**\n"
                f"**:video_game: Host - {host.mention}**\n"
                f"**:pencil: {reserve_label} - __MAP_LINK__**"
            )
            # No reservation thread any more: the game is saved under the
            # announcement post's id, and players reserve on the website.
            anno_message = await announce_channel.send(
                content=announcement_content.replace("__MAP_LINK__", "*(Creating link...)*")
            )
            game_key = str(anno_message.id)
            thread_name = f"{mode} Game - {day} - {date_str}"
            await anno_message.edit(content=announcement_content.replace("__MAP_LINK__", _map_game_url(game_key)))

            # Save to GAMES_FILE just like standard /announce_game
            games_data = await read_json(GAMES_FILE)
            games_data[game_key] = {
                "guild_id": str(cur_gid()),
                "no_thread": True,
                "mode": mode,
                "base_mode": base_mode,
                "thread_name": thread_name,
                "host_id": host.id,
                "message_ids": [],
                "announcement_message_id": anno_message.id,
                "announcement_channel_id": announce_channel.id,
                "mod_message_id": mod_msg_id,
                "rules_message_id": rules_msg_id,
                "reservations": {},
                "major_lock_level": item.get("major_lock_level", "Trusted"),
                "minor_lock_level": item.get("minor_lock_level", "All Users"),
                "locked_majors": True,
                # Nations the host locked on the web calendar start locked
                # (plus a preset's not-playable nations, for good).
                "locked_regions": locked_at_start,
                "nation_lock_releases": _nation_lock_releases_from_slot(item),
                "preset_id": item.get("preset_id"),
                "preset_name": item.get("preset_name"),
                "nation_layout": nation_layout,
                "layout_disabled_nations": not_playable,
                "managed_mods": mod_entries,
                "managed_rulesets": rule_entries,
                "late_join_nations": [],
                "game_started": False,
                "coops_unlocked_by_host": False,
                "fillers_unlocked_by_host": False,
                "lockdown": False,
                "fortunes_drawn": {},
                "fortunes_drawn_nations": {},
                "fortunes_pending": {},
                "fortunes_redraw_count": {},
                "fortunes_mode": item.get("fortunes_mode", "casual") if fortunes_only else None,
                "randomizer_only": randomizer_only,
                "fortunes_only": fortunes_only,
                "randomizer_type": randomizer_type,
                "randomizer_mode": randomizer_mode,
                "randomizer_reroll_count": {},
                "submod": addon_value if submod else None,
                "logging_mode": item.get("logging_mode", "Strict"),
                "start_timestamp": game_timestamp,
                "automatic_reminder": bool(item.get("automatic_reminder")),
                "scheduled_checksum": item.get("scheduled_checksum"),
                "automated_unlock": bool(item.get("automated_unlock")),
                "automated_unlocks": dict(item.get("automated_unlocks") or {}),
            }
            if draft_config:
                new_game = games_data[game_key]
                new_game["is_draft"] = True
                new_game["draft"] = _new_draft_state(
                    teams=_draft_build_teams(draft_config, new_game),
                    coin_flip=bool(draft_config.get("coin_flip")),
                    first_picker=draft_config.get("first_picker"),
                    pool_cap=get_draft_pool_capacity(
                        mode, len(not_playable),
                        hidden_majors=len(set(not_playable) & set(get_major_nations_for_mode(mode))),
                    ),
                )
            await write_json(GAMES_FILE, games_data)
            item["thread_id"] = anno_message.id
            await _update_schedule_slot_draft_config(item, thread_id=anno_message.id)
            # Timestamp sync audit — the scheduled slot's integer must land
            # verbatim in games.start_timestamp.
            _audit_log(
                "INFO",
                f"auto-announce game={game_key} start_timestamp={int(game_timestamp)} "
                f"slot_game_timestamp={int(item.get('game_timestamp') or 0)} "
                f"match={int(item.get('game_timestamp') or 0) == int(game_timestamp)}",
            )
            print(f"Automated announcement posted for {mode} hosted by {host.display_name}.")

    except Exception as e:
        print(f"Error in check_scheduled_announcements loop: {e}")


def _resolve_web_lock_tier(slot: dict, settings: dict | None, now: int) -> int:
    """Resolve the ACTIVE 2-tier lock tier for a session (pure integer math).

        time_until_game = game_timestamp - now
        current_tier   = 2 if time_until_game <= step_down_threshold else 1

    The step-down threshold comes from the web Host Panel's `locks` config
    (48h/24h/12h/6h before game start, or a custom epoch). Tier 1 applies from
    game creation; Tier 2 (degraded roles) applies once the threshold passes.
    """
    g_time = int(slot.get("game_timestamp") or 0)
    if not g_time:
        return 1
    locks = (settings or {}).get("locks")
    if not isinstance(locks, dict) or not locks.get("enabled"):
        return 1
    threshold_cfg = locks.get("threshold") or {}
    try:
        threshold_seconds = int(threshold_cfg.get("seconds") or 0)
    except (TypeError, ValueError):
        threshold_seconds = 0
    if threshold_cfg.get("mode") == "custom":
        threshold_seconds = max(0, g_time - threshold_seconds)
    threshold_seconds = max(0, threshold_seconds)
    if threshold_seconds <= 0:
        return 1  # no threshold configured — Tier 1 stays active
    time_until_game = g_time - now
    return 2 if time_until_game <= threshold_seconds else 1


@tasks.loop(seconds=60)
async def automated_lock_tier_loop():
    """Runs once per active server (_automated_lock_tier_loop_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_automated_lock_tier_loop_for_guild, "automated_lock_tier_loop")


async def _automated_lock_tier_loop_for_guild():
    """1-minute lock-tier transitions for automated 2-tier access locks.

    Every pending session with automated locks configured is evaluated:
        time_until_game = game_timestamp - current_unix_timestamp
    and `current_tier` is flipped to 2 the moment the host's step-down
    threshold passes (Tier 1 → Tier 2). The result is persisted to
    schedule_slots.current_tier so the web reservation endpoint can enforce
    the ACTIVE tier's entry-level role gating instantly."""
    await bot.wait_until_ready()
    now = int(time.time())
    try:
        host_settings_raw = await _run_mysql_io(
            _fetch_host_settings_mysql, label="lock-tier settings read"
        )
        settings_lookup = {
            str(k): (row or {}).get("settings") or {}
            for k, row in (host_settings_raw or {}).items()
        }

        schedule_data = await read_json(SCHEDULE_FILE)
        schedule_changed = False
        for slot in schedule_data:
            if not slot.get("automated_unlock"):
                continue
            if slot.get("status") in ("cancelled", "ended"):
                continue
            settings = settings_lookup.get(str(slot.get("slot_id") or ""))
            # Casino add-ons always use web-managed locks; other modes only
            # transition when the host actually saved a locks config.
            if slot.get("add_on") not in _CASINO_WEB_LOCK_ADDONS and not settings:
                continue
            tier = _resolve_web_lock_tier(slot, settings, now)
            if int(slot.get("current_tier") or 1) != tier:
                slot["current_tier"] = tier
                schedule_changed = True
                _audit_log(
                    "INFO",
                    f"lock tier transition slot={slot.get('slot_id')} "
                    f"current_tier={tier} game_timestamp={slot.get('game_timestamp')} "
                    f"time_until_game={int(slot.get('game_timestamp') or 0) - now}",
                )
        if schedule_changed:
            await write_json(SCHEDULE_FILE, schedule_data)

        # Mirror the tier onto live casino game dicts so bot-side flows can
        # read it too (reservations enforce via the web endpoint).
        slot_by_thread = {
            str(s.get("thread_id")): s
            for s in schedule_data
            if s.get("thread_id")
        }
        games_data = await read_json(GAMES_FILE)
        games_changed = False
        for thread_id, game in games_data.items():
            if not _game_manages_locks_via_web(game):
                continue
            slot = slot_by_thread.get(str(thread_id))
            tier = int(slot.get("current_tier") or 1) if slot else 1
            if int(game.get("current_tier") or 1) != tier:
                game["current_tier"] = tier
                games_changed = True
        if games_changed:
            await write_json(GAMES_FILE, games_data)
    except Exception as e:
        print(f"Error in automated_lock_tier_loop: {e}")


def _nation_lock_releases_from_slot(slot: dict) -> list:
    """Timed nation-lock groups of a web-scheduled slot, in the shape the
    announced game dict keeps for scheduled_nation_unlock_loop. Groups with
    no release time stay locked until the host unlocks them (Games page)."""
    releases = []
    for group in (slot or {}).get("nation_locks") or []:
        if not isinstance(group, dict):
            continue
        release_ts = group.get("release_timestamp")
        nations = [str(n) for n in group.get("nations") or [] if n]
        if not release_ts or not nations:
            continue
        releases.append({
            "label": str(group.get("label") or "Locked nations"),
            "nations": nations,
            "unlock_timestamp": int(release_ts),
            "applied": False,
        })
    return releases


def _apply_nation_lock_releases(game: dict, now: int) -> list:
    """Release every due timed nation-lock group on one game dict. Returns
    (label, released_names) per group released this tick; names the host
    already unlocked by hand are simply skipped."""
    releases = game.get("nation_lock_releases") or []
    if not releases or game.get("status") in ("ended", "cancelled"):
        return []
    locked = list(game.get("locked_regions") or [])
    released = []
    # A preset's not-playable nations never unlock.
    not_playable = set(game.get("layout_disabled_nations") or [])
    for release in releases:
        if release.get("applied") or now < int(release.get("unlock_timestamp") or 0):
            continue
        group = set(release.get("nations") or []) - not_playable
        released.append((
            str(release.get("label") or "Locked nations"),
            [name for name in locked if name in group],
        ))
        locked = [name for name in locked if name not in group]
        release["applied"] = True
        release["applied_at"] = now
    if released:
        game["locked_regions"] = locked
    return released


def _short_nation_list(names: list, limit: int = 25) -> str:
    """Comma list capped for Discord's message limit ("A, B and 12 more")."""
    if len(names) <= limit:
        return ", ".join(names)
    return f"{', '.join(names[:limit])} and {len(names) - limit} more"


@tasks.loop(seconds=60)
async def scheduled_nation_unlock_loop():
    """Runs once per active server (_scheduled_nation_unlock_loop_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_scheduled_nation_unlock_loop_for_guild, "scheduled_nation_unlock_loop")


async def _scheduled_nation_unlock_loop_for_guild():
    """Apply restart-safe scheduled Major/Minor lock-level changes.

    Casino add-on games (add_on randomizer — randomizer_only games)
    are SKIPPED: their 2-tier step-down unlocks are managed dynamically on the
    web Host Panel and enforced by /api/access, so no Discord-side unlock
    messages are dispatched for them. Regular games keep this system."""
    await bot.wait_until_ready()
    now = int(time.time())
    try:
        schedule_data = await read_json(SCHEDULE_FILE)
        schedule_changed = False
        for slot in schedule_data:
            if not slot.get("automated_unlock"):
                continue
            if slot.get("add_on") in _CASINO_WEB_LOCK_ADDONS:
                continue
            unlocks = slot.get("automated_unlocks") or {}
            for scope in ("major", "minor"):
                config = unlocks.get(scope)
                if (
                    not config
                    or config.get("applied")
                    or now < int(config.get("unlock_timestamp") or 0)
                ):
                    continue
                slot[f"{scope}_lock_level"] = config.get("target_level", "All Users")
                config["applied"] = True
                config["applied_at"] = now
                schedule_changed = True
        if schedule_changed:
            await write_json(SCHEDULE_FILE, schedule_data)

        games_data = await read_json(GAMES_FILE)
        games_changed = False
        # thread_id -> notice lines posted in the reservation thread.
        notices: dict = {}
        for thread_id, game in games_data.items():
            # Timed host nation locks (web calendar) release on their own clock,
            # independent of automated_unlock and Casino web-managed tiers.
            for label, names in _apply_nation_lock_releases(game, now):
                games_changed = True
                if names:
                    notices.setdefault(thread_id, []).append(
                        f"🔓 **{label}** unlocked by the host's schedule: "
                        f"{_short_nation_list(names)}."
                    )
            if not game.get("automated_unlock") or game.get("status") in ("ended", "cancelled"):
                continue
            if _game_manages_locks_via_web(game):
                continue
            unlocks = game.get("automated_unlocks") or {}
            for scope in ("major", "minor"):
                config = unlocks.get(scope)
                if (
                    not config
                    or config.get("applied")
                    or now < int(config.get("unlock_timestamp") or 0)
                ):
                    continue
                game[f"{scope}_lock_level"] = config.get("target_level", "All Users")
                config["applied"] = True
                config["applied_at"] = now
                games_changed = True
                notices.setdefault(thread_id, []).append(
                    f"🔓 **{scope.title()} Nations** automatically unlocked to "
                    f"**{_lock_label(game.get(f'{scope}_lock_level'))}**."
                )

        if games_changed:
            await write_json(GAMES_FILE, games_data)

        for thread_id, lines in notices.items():
            try:
                schedule_reservation_update(int(thread_id))
                game = games_data.get(thread_id) or {}
                if not _game_has_thread(game):
                    # The map shows the unlock; the host hears about it by DM.
                    host = await _web_fetch_member(int(game.get("host_id") or 0))
                    if host is not None:
                        title = game.get("thread_name") or game.get("mode") or "your game"
                        await _dm_user_safe(
                            host, content=f"**{title}**\n" + "\n".join(lines), label="scheduled unlock",
                        )
                    continue
                thread = bot.get_channel(int(thread_id))
                if not thread:
                    try:
                        thread = await bot.fetch_channel(int(thread_id))
                    except Exception:
                        thread = None
                if thread:
                    await thread.send("\n".join(lines))
            except Exception as notify_error:
                print(f"[WARN] Scheduled nation unlock notification failed for {thread_id}: {notify_error}")
    except Exception as e:
        print(f"Error in scheduled_nation_unlock_loop: {e}")


# =============================================================================
# DRAFT MODE on the website (formerly /reserve in draft games, /start_draft,
# /draft_pick and /empty_draft_pool). Every change comes through
# web_schedule_requests, so the bot stays the only writer of game["draft"]:
#   draft_join     any verified player: join (or update) the pool as a Major
#                  or a Minor, with an optional note for the host / captains
#   draft_leave    leave the pool (until you've been placed)
#   draft_pick     the captain on the clock places a pool player on one of
#                  their team's free nations / co-ops / a filler
#   draft_control  the game's host or Host Management: start (coin toss), finish
#                  (clear the leftover pool), remove a player, place anyone
#                  anywhere (doesn't use a captain's turn), change a captain
# =============================================================================
DRAFT_WEB_ACTIONS = ("draft_join", "draft_leave", "draft_pick", "draft_control")


def _draft_outcome(title: str, summary: str, notes=None) -> dict:
    return {"draft": {"title": title, "summary": summary, "notes": list(notes or []), "stats": {}, "log_url": None}}


def _draft_log(draft: dict, **entry) -> None:
    history = list(draft.get("history") or [])
    history.append({"ts": int(time.time()), **entry})
    draft["history"] = history[-DRAFT_HISTORY_MAX:]


async def _draft_post(guild, key: str, text: str) -> None:
    """A line in the game's Discord thread (best effort)."""
    try:
        thread = await _resolve_game_thread(guild, key)
        if thread is not None:
            await thread.send(text, allowed_mentions=discord.AllowedMentions(users=True))
    except Exception as e:
        print(f"[WARN] draft: thread post failed for {key}: {e}")


async def _draft_notify_turn(guild, key: str, game: dict) -> None:
    """Tell the thread (and DM the captain) whose pick it is."""
    draft = game["draft"]
    team = _draft_turn_team(game)
    if draft.get("phase") != "DRAFTING" or team is None:
        return
    remaining = int(draft.get("picks_remaining_this_turn") or 1)
    link = _map_game_url(key)
    await _draft_post(
        guild, key,
        f"👉 **{team.get('name')}**'s turn — <@{team.get('captain_id')}>, {remaining} pick(s). Pick on the map: {link}",
    )
    captain = await _web_fetch_member(int(team.get("captain_id") or 0))
    if captain is not None:
        await _dm_user_safe(
            captain,
            content=(
                f"🎯 Your turn to draft for **{team.get('name')}** ({remaining} pick(s)) in "
                f"**{game.get('mode')}**. Open the map and pick from the pool: {link}"
            ),
            label="draft turn",
        )


async def _draft_notify_complete(guild, key: str, game: dict) -> None:
    leftover = len((game.get("draft") or {}).get("pool") or {})
    tail = (
        f" {leftover} player(s) couldn't be placed — the host can clear them on the Games page."
        if leftover else ""
    )
    await _draft_post(guild, key, f"🎉 **THE DRAFT IS COMPLETE!** The host can now start the game on the website.{tail}")


def _draft_free_seat(slot: str, valid) -> str:
    """A co-op or filler seat the page picked may have just been taken (two
    quick drops): use the next free seat of the same kind instead."""
    if slot in valid:
        return slot
    if slot.startswith("_FILL_"):
        return next((key for key in valid if key.startswith("_FILL_")), slot)
    if "_coop" in slot:
        base = slot.split("_coop")[0]
        return next((key for key in valid if "_coop" in key and key.split("_coop")[0] == base), slot)
    return slot


async def _draft_place(game: dict, user_id: int, slot: str, *, team_key, actor) -> tuple[Optional[str], str]:
    """Move a pool player onto a free slot (a captain's team slot, or — with
    team_key None — anything playable, for the host). Returns (error, the
    slot actually used)."""
    draft = game["draft"]
    if str(user_id) not in (draft.get("pool") or {}):
        return "❌ That player isn't in the draft pool any more.", slot
    valid = [value for _label, value in _draft_assignment_entries(game, team_key)]
    slot = _draft_free_seat(slot, valid)
    if slot not in valid:
        return (
            "❌ That slot is taken, locked or not part of your team — pick another."
            if team_key is not None else "❌ That slot is taken or isn't playable in this game."
        ), slot
    target = await _web_fetch_member(user_id)
    if target is None:
        return "❌ That player is no longer in the server.", slot
    if not slot.startswith("_FILL_"):
        mode = game.get("mode", "")
        base = slot.split("_coop")[0]
        reason = await _dishonored_block_for_member(target, mode, base, base in set(get_major_nations_for_mode(mode)))
        if reason:
            return f"❌ {target.display_name} can't play {base}: {reason}", slot
    del draft["pool"][str(user_id)]
    game.setdefault("reservations", {})[slot] = user_id
    _draft_log(
        draft, kind="pick" if team_key is not None else "host_place",
        user_id=str(user_id), slot=slot, team=team_key, by=str(getattr(actor, "id", "")),
    )
    return None, slot


async def _process_web_draft(req: dict):
    action = str(req.get("action") or "")
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if actor is None:
        return False, None, "❌ You need to be a member of the Discord server."
    thread_id = str(payload.get("thread_id") or "").strip()
    games = await _read_games_fresh()
    key, game = _find_game_entry(games, thread_id)
    if not _is_draft_game(game):
        return False, None, "❌ This isn't a draft game (or it no longer exists)."
    key = str(key or thread_id)
    if str(game.get("status") or "").strip().lower() in ("ended", "cancelled"):
        return False, None, "❌ This game has ended or was cancelled."
    if game.get("game_started"):
        return False, None, "❌ The game has started — the draft is closed."
    if key in _web_lifecycle_running:
        return False, None, "ℹ️ This game is being started or cancelled — try again in a moment."

    draft = game["draft"]
    if not isinstance(draft.get("teams"), list) or not draft.get("teams"):
        draft["teams"] = _draft_teams(game)  # a draft from before the website
    guild = bot.get_guild(cur_gid())
    mode = game.get("mode", "")
    now = int(time.time())
    pool = draft.setdefault("pool", {})
    phase = draft.get("phase", "ENLISTING")
    uid = str(actor.id)
    notify_turn = notify_complete = False
    posts: list[str] = []

    if action == "draft_join":
        choice = str(payload.get("preference") or "").lower()
        if choice not in DRAFT_POOL_CHOICES:
            return False, None, "❌ Choose Major, Minor, Major Co-op or Filler."
        if phase != "ENLISTING":
            return False, None, "❌ The draft has already begun — the pool is closed. Ask the host if you still want in."
        if game.get("lockdown"):
            return False, None, LOCKDOWN_MESSAGE
        ban_role = (MODE_CONFIG.get(mode) or {}).get("banned_role_id")
        stats = (get_cached_player_stats() or {}).get(uid, {})
        if (ban_role and any(role.id == ban_role for role in getattr(actor, "roles", []))) or stats.get("banned"):
            return False, None, f"❌ You are banned from {mode} games."
        if not await is_user_authenticated(actor, int(key) if key.isdigit() else None):
            return False, None, RESERVATION_REJECTED_UNVERIFIED_MESSAGE
        if any(str(holder) == uid for holder in (game.get("reservations") or {}).values()):
            return False, None, "⚠️ You already have a slot in this game."
        cap = int(draft.get("pool_cap") or get_draft_pool_capacity(mode))
        updating = uid in pool
        if not updating and len(pool) >= cap:
            return False, None, f"❌ The draft pool is full ({len(pool)}/{cap})."
        note = re.sub(r"\s+", " ", str(payload.get("note") or "")).strip()[:DRAFT_NOTE_MAX]
        preference = DRAFT_POOL_CHOICES[choice]
        pool[uid] = {
            "preference": preference,
            "note": note,
            "reserved_by": actor.id,
            "reserved_at": int((pool.get(uid) or {}).get("reserved_at") or now),
            "name": actor.display_name,
        }
        _draft_log(draft, kind="join", user_id=uid, preference=preference)
        label = preference.replace(" Nation", "")
        outcome = _draft_outcome(
            "🎯 Entry updated" if updating else "🎯 You're in the draft pool",
            f"As a {label} · {len(pool)}/{cap} in the pool. The captains pick once the host starts the draft.",
        )
        rewrite = False
    elif action == "draft_leave":
        if uid not in pool:
            return False, None, "ℹ️ You aren't in the draft pool."
        del pool[uid]
        _draft_log(draft, kind="leave", user_id=uid)
        notify_complete = _draft_check_complete(game)
        outcome = _draft_outcome("👋 You left the draft pool", "You can join again while sign-ups are open.")
        rewrite = False
    elif action == "draft_pick":
        if phase != "DRAFTING":
            return False, None, "❌ The draft isn't running — the host starts it from the Games page."
        team = _draft_turn_team(game)
        if team is None:
            return False, None, "❌ Nobody is on the clock right now."
        if int(team.get("captain_id") or 0) != actor.id:
            mine = next((t for t in draft["teams"] if int(t.get("captain_id") or 0) == actor.id), None)
            return False, None, (
                f"❌ It's {team.get('name')}'s turn — wait for your pick." if mine
                else "❌ Only the team captains pick players."
            )
        try:
            target_id = int(payload.get("user_id"))
        except (TypeError, ValueError):
            return False, None, "❌ Pick a player from the pool."
        slot = str(payload.get("slot") or "").strip()
        err, slot = await _draft_place(game, target_id, slot, team_key=team.get("key"), actor=actor)
        if err:
            return False, None, err
        _draft_advance_turn(game)
        notify_complete = _draft_check_complete(game)
        notify_turn = not notify_complete
        label = _pretty_reservation_name(slot)
        posts.append(f"✅ **{team.get('name')}** drafted <@{target_id}> → **{label}**.")
        outcome = _draft_outcome("✅ Drafted", f"<@{target_id}> → {label} for {team.get('name')}.")
        rewrite = True
    elif action == "draft_control":
        if not _can_end_assigned_game(actor, game):
            return False, None, f"❌ Only the game's host (<@{game.get('host_id')}>) or Host Management can run the draft."
        op = str(payload.get("op") or "")
        rewrite = False
        if op == "start":
            if phase != "ENLISTING":
                return False, None, "ℹ️ The draft has already started."
            if not pool:
                return False, None, "❌ Nobody is in the draft pool yet."
            teams = draft["teams"]
            draft["phase"] = "DRAFTING"
            if draft.get("coin_flip"):
                first = random.choice(teams)
                draft["current_turn"] = first.get("key")
                draft["picks_remaining_this_turn"] = DRAFT_COIN_FLIP_OPENING_PICKS
                draft["coin_toss"] = {"winner": first.get("key"), "ts": now}
                opener = (
                    f"🪙 The coin toss went to **{first.get('name')}** — they open with "
                    f"{DRAFT_COIN_FLIP_OPENING_PICKS} picks, then the teams alternate."
                )
            else:
                first = _draft_team(game, draft.get("first_picker")) or teams[0]
                draft["current_turn"] = first.get("key")
                draft["picks_remaining_this_turn"] = 1
                opener = f"**{first.get('name')}** picks first, then the teams alternate."
            if not _draft_assignment_entries(game, draft["current_turn"]):
                draft["picks_remaining_this_turn"] = 1
                _draft_advance_turn(game)
            _draft_log(draft, kind="start", by=uid)
            notify_complete = _draft_check_complete(game)
            notify_turn = not notify_complete
            posts.append(f"🚨 **DRAFT STARTED!** {opener}")
            outcome = _draft_outcome("🚨 Draft started", opener)
        elif op == "finish":
            leftover = list(pool.keys())
            draft["pool"] = {}
            draft["phase"] = "COMPLETE"
            draft["current_turn"] = None
            draft["picks_remaining_this_turn"] = 0
            _draft_log(draft, kind="finish", by=uid, cleared=len(leftover))
            for leftover_id in leftover:
                member = await _web_fetch_member(int(leftover_id))
                if member is not None:
                    await _dm_user_safe(
                        member,
                        content=f"📋 The draft for **{mode}** has concluded — you weren't placed this time.",
                        label="draft leftover",
                    )
            posts.append(
                f"🧹 The host finished the draft{f' and cleared {len(leftover)} un-drafted player(s)' if leftover else ''}. "
                "Draft is **COMPLETE**."
            )
            outcome = _draft_outcome("🏁 Draft finished", f"Cleared {len(leftover)} player(s) from the pool. The game can be started now.")
        elif op == "remove":
            target_id = str(payload.get("user_id") or "")
            if target_id not in pool:
                return False, None, "ℹ️ That player isn't in the pool."
            del pool[target_id]
            _draft_log(draft, kind="remove", user_id=target_id, by=uid)
            notify_complete = _draft_check_complete(game)
            member = await _web_fetch_member(int(target_id)) if target_id.isdigit() else None
            if _roster_notify_on(payload):
                await _roster_notify_player(
                    member, game, key, actor,
                    title="🚫 Taken out of the draft pool",
                    text=f"**{actor.display_name}** took you out of the draft pool for this game.",
                    color=discord.Color.red(), label="draft remove",
                )
            outcome = _draft_outcome("🗑️ Removed from the pool", f"<@{target_id}> is out of the draft pool.")
        elif op == "assign":
            try:
                target_id = int(payload.get("user_id"))
            except (TypeError, ValueError):
                return False, None, "❌ Pick a player from the pool."
            slot = str(payload.get("slot") or "").strip()
            err, slot = await _draft_place(game, target_id, slot, team_key=None, actor=actor)
            if err:
                return False, None, err
            notify_complete = _draft_check_complete(game)
            label = _pretty_reservation_name(slot)
            posts.append(f"🛠️ The host placed <@{target_id}> on **{label}**.")
            outcome = _draft_outcome("✅ Player placed", f"<@{target_id}> → {label}. Captains' turns are unchanged.")
            rewrite = True
        elif op == "captain":
            team = _draft_team(game, payload.get("team"))
            if team is None:
                return False, None, "❌ Pick a team."
            new_id = str(payload.get("user_id") or "")
            new_captain = await _web_fetch_member(int(new_id)) if new_id.isdigit() else None
            if new_captain is None:
                return False, None, "❌ The new captain has to be a member of the server."
            if any(int(t.get("captain_id") or 0) == new_captain.id for t in draft["teams"] if t is not team):
                return False, None, "❌ They already captain the other team."
            team["captain_id"] = str(new_captain.id)
            _draft_log(draft, kind="captain", team=team.get("key"), user_id=new_id, by=uid)
            await _dm_user_safe(
                new_captain,
                content=f"🎖️ You're now the captain of **{team.get('name')}** in the **{mode}** draft: {_map_game_url(key)}",
                label="draft captain",
            )
            posts.append(f"🎖️ <@{new_captain.id}> is now the **{team.get('name')}** captain.")
            outcome = _draft_outcome("🎖️ Captain changed", f"{new_captain.display_name} captains {team.get('name')}.")
            notify_turn = draft.get("phase") == "DRAFTING" and draft.get("current_turn") == team.get("key")
        else:
            return False, None, f"❌ Unknown draft action: {op}."
    else:
        return False, None, f"❌ Unknown draft request: {action}."

    await save_single_game(key, game, rewrite_reservations=rewrite)
    if rewrite:
        schedule_reservation_update(int(key))
        placed = (draft.get("history") or [{}])[-1]
        member = await _web_fetch_member(int(placed.get("user_id") or 0)) if placed.get("user_id") else None
        host_placed = action == "draft_control"
        slot_txt = _pretty_reservation_name(placed.get("slot") or "")
        if member is not None and not host_placed:
            team = _draft_team(game, placed.get("team"))
            team_txt = f" for **{team.get('name')}**" if team else ""
            await _dm_user_safe(
                member,
                content=f"📋 You've been drafted onto **{slot_txt}**{team_txt} in **{mode}**!",
                label="draft placed",
            )
        elif host_placed and _roster_notify_on(payload):
            await _roster_notify_player(
                member, game, key, actor,
                title="📋 You were placed in the draft",
                text=f"**{actor.display_name}** placed you on **{slot_txt}**.",
                color=discord.Color.green(), label="draft placed",
            )
    await update_draft_pool_message(int(key))
    for text in posts:
        await _draft_post(guild, key, text)
    if notify_complete:
        await _draft_notify_complete(guild, key, game)
    elif notify_turn:
        await _draft_notify_turn(guild, key, game)
    _audit_log("INFO", f"web {action} game={key} by={actor.id} payload={json.dumps(payload, ensure_ascii=False)[:200]}")
    return True, outcome, None


