def _all_command_names() -> list[str]:
    """Every registered slash-command name (guild + global), de-duplicated."""
    names = set()
    try:
        for cmd in bot.tree.get_commands(guild=discord.Object(id=cur_gid())):
            names.add(cmd.name)
    except Exception:
        pass
    try:
        for cmd in bot.tree.get_commands():
            names.add(cmd.name)
    except Exception:
        pass
    return sorted(names)




# ----------- Search logs -------------

LOG_CHANNEL_ID = 0
LOG_SEARCH_MESSAGE_LIMIT = 5000
LOG_SEARCH_RESULT_LIMIT = 50
LOG_SEARCH_TIMEOUT_SECONDS = 55



_scheduled_reminder_claim_lock = asyncio.Lock()


def _automatic_reminder_due(game: dict, now: int) -> bool:
    start_ts = int(game.get("start_timestamp") or 0)
    return bool(
        game.get("automatic_reminder")
        and not game.get("automatic_reminder_sent_at")
        and start_ts
        and start_ts - 3600 <= now < start_ts
        and game.get("status") not in ("ended", "cancelled")
        and not game.get("game_started")
    )


@tasks.loop(seconds=60)
async def scheduled_game_reminder_loop():
    """Runs once per active server (_scheduled_game_reminder_loop_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_scheduled_game_reminder_loop_for_guild, "scheduled_game_reminder_loop")


async def _scheduled_game_reminder_loop_for_guild():
    """Claim and send restart-safe one-hour reminders for announced games."""
    await bot.wait_until_ready()
    now = int(time.time())
    games = await _load_games_resilient()
    guild = bot.get_guild(cur_gid())
    if not guild:
        return

    for storage_key, snapshot in games.items():
        start_ts = int(snapshot.get("start_timestamp") or 0)
        if not _automatic_reminder_due(snapshot, now):
            continue

        async with _scheduled_reminder_claim_lock:
            _, game = await _get_game_data(str(storage_key))
            claimed_at = int(game.get("automatic_reminder_claimed_at") or 0)
            if game.get("automatic_reminder_sent_at"):
                continue
            if claimed_at and now - claimed_at < 600:
                continue
            game["automatic_reminder_claimed_at"] = now
            await save_single_game(str(storage_key), game, rewrite_reservations=False)

        checksum = game.get("scheduled_checksum") or "not provided"
        message = (
            f"⏰ **Game reminder:** your game starts <t:{start_ts}:F> (<t:{start_ts}:R>).\n"
            f"🔢 **Checksum:** `{checksum}`\n\n"
            "Please prepare your game and mods now. If you cannot attend, unreserve on the website "
            f"as soon as possible: {_map_game_url(storage_key)}"
        )
        seen = set()
        attempted = {
            int(uid) for uid in game.get("automatic_reminder_dm_ids", [])
            if str(uid).isdigit()
        }
        for raw_uid in (game.get("reservations") or {}).values():
            try:
                uid = int(raw_uid)
            except (TypeError, ValueError):
                continue
            if uid in seen or uid in attempted:
                continue
            seen.add(uid)
            member = guild.get_member(uid)
            if not member:
                continue
            try:
                async with _discord_api_sem:
                    await member.send(message)
            except Exception as e:
                print(f"[WARN] Scheduled reminder DM failed for {uid}: {e}")
            attempted.add(uid)
            game["automatic_reminder_dm_ids"] = sorted(attempted)
            await save_single_game(str(storage_key), game, rewrite_reservations=False)
            await asyncio.sleep(0.3)

        game["automatic_reminder_sent_at"] = int(time.time())
        game.pop("automatic_reminder_claimed_at", None)
        await save_single_game(str(storage_key), game, rewrite_reservations=False)


@tasks.loop(minutes=5)
async def schedule_updater():
    """Runs once per active server (_schedule_updater_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_schedule_updater_for_guild, "schedule_updater")


