def _build_audit_event_embed(ev: dict) -> discord.Embed:
    """Rich embed for one audit event — the requested field layout."""
    uid = int(ev.get("user_id") or 0)
    username = str(ev.get("username") or "unknown")
    embed = discord.Embed(
        title=f"[AUDIT LOG] {ev.get('event_type') or 'EVENT'}",
        color=0x1a1a2e,
    )
    embed.add_field(name="User", value=f"<@{uid}>" if uid else "Unknown", inline=True)
    embed.add_field(name="Discord Username", value=username, inline=True)
    embed.add_field(name="Discord ID", value=str(uid) if uid else "Unknown", inline=True)
    embed.add_field(name="VIP", value="YES" if ev.get("is_vip") else "NO", inline=True)
    embed.add_field(name="Ban Status", value="BANNED" if ev.get("is_banned") else "CLEAR", inline=True)
    payload = str(ev.get("payload") or "").strip()
    if payload:
        embed.add_field(name="Payload", value=f"```json\n{payload[:900]}\n```", inline=False)
    return embed


@tasks.loop(seconds=AUDIT_EVENTS_INTERVAL_SEC)
async def audit_events_sync_loop():
    """Drain the web-written audit_events queue and post rich embeds to the
    dedicated audit channel. The web app never calls Discord directly — this
    loop IS the GameMaster webhook integration."""
    try:
        events = await _run_mysql_io(_fetch_audit_events_mysql, label="audit events read")
        if not events:
            return
        channel = bot.get_channel(G.AUDIT_CHANNEL_ID)
        if channel is None:
            try:
                channel = await bot.fetch_channel(G.AUDIT_CHANNEL_ID)
            except Exception:
                channel = None
        if channel is None:
            print(f"[WARN] audit channel {G.AUDIT_CHANNEL_ID} not reachable — events stay queued")
            return
        processed = []
        for ev in events:
            try:
                await channel.send(embed=_build_audit_event_embed(ev))
                processed.append(int(ev["id"]))
            except Exception as e:
                print(f"[WARN] audit embed post failed: {e}")
                break  # retry remaining events next tick
        if processed:
            await _run_mysql_io(_delete_audit_events_mysql, processed, label="audit events ack")
    except Exception as e:
        print(f"Error in audit_events_sync_loop: {e}")


