@tasks.loop(seconds=USERNAME_BACKFILL_INTERVAL_SEC)
async def username_backfill_loop():
    """Heal NULL web_sessions.username rows from live Discord users."""
    rows = await _run_mysql_io(
        _fetch_null_username_sessions_mysql, label="username backfill read"
    )
    if not rows:
        return
    healed = 0
    for game_id, user_id in rows:
        if not user_id:
            continue
        try:
            user = bot.get_user(int(user_id))
            if user is None:
                user = await bot.fetch_user(int(user_id))
                # Respect the GET /users/{id} rate limit for uncached users.
                await asyncio.sleep(1.1)
            if user and getattr(user, "name", None):
                await _run_mysql_io(
                    _set_session_username_mysql,
                    str(game_id),
                    int(user_id),
                    str(user.name),
                    label="username backfill write",
                )
                healed += 1
                print(
                    f"[USERNAME_BACKFILL] set username for user_id={user_id} game_id={game_id}"
                )
        except Exception as e:
            print(f"[WARN] username backfill failed for {user_id}: {e}")
    if healed:
        print(f"[USERNAME_BACKFILL] healed {healed} session username(s)")


