@tasks.loop(seconds=RESERVATION_SYNC_INTERVAL_SEC)
async def reservation_sync_loop():
    """Drain the web reservation sync queue → refresh Discord reservation embeds.

    Merge semantics: MySQL `game_reservations` rows are merged ON TOP of the
    game dict's existing reservation map (never wholesale-replaced) so legacy
    bot-only keys are never dropped. Events with action='unreserve' (or an
    empty slot_key) remove the user's reservation instead. Failed threads stay
    queued for the next tick; sync failures never roll back the underlying
    reservation."""
    try:
        events = await _run_mysql_io(
            _fetch_reservation_sync_queue_mysql, label="reservation sync read"
        )
        if not events:
            return
        by_thread = {}
        for ev in events:
            by_thread.setdefault(str(ev.get("thread_id") or ""), []).append(ev)

        processed_ids = []
        for thread_id, thread_events in by_thread.items():
            if not thread_id:
                processed_ids.extend(int(ev["id"]) for ev in thread_events if ev.get("id"))
                continue
            _, scope_game = _find_game_entry(_all_games(), thread_id)
            scope_token = _CURRENT_GUILD.set(_game_guild_id(scope_game) if scope_game else GUILD_ID)
            try:
                games_data = await read_json(GAMES_FILE)
                game = games_data.get(thread_id)
                if not isinstance(game, dict):
                    print(f"[WARN] reservation sync: game {thread_id} not found — event dropped")
                else:
                    # 1 player = 1 nation. The latest event per user is
                    # authoritative; every OTHER reservation row for that
                    # user in this thread is deleted (legacy duplicates like
                    # CSR + Palestine for one player). Events with an invalid
                    # user id (0 / non-numeric) are dropped with a warning —
                    # they must never render as a broken '@unknown-user'
                    # mention on the board.
                    #
                    # Unreserve events (action='unreserve' or an empty
                    # slot_key) remove the user's reservation entirely; a
                    # later reserve event in the same batch re-adds them
                    # (latest event per user wins).
                    final_slot_by_uid = {}
                    for ev in sorted(
                        thread_events, key=lambda e: int(e.get("id") or 0)
                    ):
                        raw_uid = str(ev.get("user_id") or "").strip()
                        if not raw_uid.isdigit() or int(raw_uid) <= 0:
                            print(
                                f"[WARN] reservation sync: invalid user id "
                                f"({raw_uid!r}) for thread {thread_id} — event skipped"
                            )
                            continue
                        uid = int(raw_uid)
                        is_unreserve = (
                            str(ev.get("action") or "").strip().lower() == "unreserve"
                            or str(ev.get("slot_key") or "").strip() == ""
                        )
                        if is_unreserve:
                            final_slot_by_uid[uid] = None
                            continue
                        final_slot_by_uid[uid] = str(ev.get("slot_key") or "").strip()

                    existing = game.get("reservations") or {}
                    if not isinstance(existing, dict):
                        existing = {}
                    # Purge stale dict keys held by the same user, then apply
                    # the final assignment (or removal) — the embed can never
                    # show one player under two nations.
                    merged_count = 0
                    for uid, final_slot in final_slot_by_uid.items():
                        for stale in [
                            k for k, v in existing.items() if v == uid
                        ]:
                            existing.pop(stale, None)
                        if final_slot is None:
                            # Web-initiated unreserve: drop the user's rows.
                            await _run_mysql_io(
                                _delete_reservation_rows_for_user_mysql,
                                thread_id, uid,
                                label="reservation unreserve delete",
                            )
                        else:
                            await _run_mysql_io(
                                _delete_reservation_rows_except_mysql,
                                thread_id, uid, final_slot,
                                label="reservation dedupe",
                            )
                            existing[final_slot] = uid
                        merged_count += 1
                    game["reservations"] = existing
                    await save_single_game(thread_id, game, rewrite_reservations=True)
                    schedule_reservation_update(thread_id)
                    _audit_log(
                        "INFO",
                        f"reservation sync applied thread={thread_id} events={merged_count}",
                    )
            except Exception as e:
                # Leave these events queued — retry on the next tick.
                print(f"[WARN] reservation sync failed for {thread_id}: {e}")
                continue
            finally:
                _CURRENT_GUILD.reset(scope_token)
            processed_ids.extend(int(ev["id"]) for ev in thread_events if ev.get("id"))

        if processed_ids:
            await _run_mysql_io(
                _delete_reservation_sync_rows_mysql, processed_ids,
                label="reservation sync ack",
            )
    except Exception as e:
        print(f"Error in reservation_sync_loop: {e}")


