def _fetch_web_session_receipt_data(thread_id: str, user_id: int) -> dict | None:
    """Read the saved web run payload (username, role flags, progress JSON)
    for the receipt DM builder.

    RESILIENT TO SCHEMA DRIFT: tables created before the identity columns
    existed lack username / is_vip — the full SELECT would raise 1054
    (Unknown column). Fall back to a minimal SELECT so the receipt DM still
    builds (username simply resolves to None for the embed/audit)."""
    conn = None
    cursor = None
    try:
        conn = _db_get_connection()
        cursor = conn.cursor(dictionary=True)
        row = None
        try:
            cursor.execute(
                "SELECT username, role_tier, is_vip, progress FROM web_sessions "
                "WHERE game_id = %s AND user_id = %s LIMIT 1",
                (str(thread_id), int(user_id)),
            )
            row = cursor.fetchone()
        except Exception:
            try:
                cursor.execute(
                    "SELECT progress, role_tier FROM web_sessions "
                    "WHERE game_id = %s AND user_id = %s LIMIT 1",
                    (str(thread_id), int(user_id)),
                )
                row = cursor.fetchone()
            except Exception:
                row = None
        return dict(row) if row else None
    except Exception as e:
        print(f"[WARN] Could not read web session receipt data: {e}")
        return None
    finally:
        if cursor is not None:
            try:
                cursor.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _format_web_receipt_lines(progress: dict | None) -> str:
    """Compact House Rules summary from the web run's saved results."""
    results = (progress or {}).get("results") or {}
    if not isinstance(results, dict):
        results = {}
    lines = []
    for key, label in (
        ("ideology", "Ideology"),
        ("path", "Focus Path"),
        ("doctrine", "Doctrine"),
        ("build", "Build Order"),
        ("achievements", "Achievement"),
    ):
        value = results.get(key)
        if value:
            lines.append(f"**{label}:** {value}")
    return "\n".join(lines) if lines else "Standard roll — no extra modifiers."


async def _post_receipt_dm_audit(
    user_id: int, thread_id: str, status: str, receipt_url: str, error: str | None
) -> None:
    """Structured audit-channel log for every receipt DM dispatch attempt
    (the host log channel): User Mention, Game ID, Status
    (SUCCESS / DM_CLOSED / FAILED), Generated Receipt URL, raw exception."""
    try:
        channel = bot.get_channel(G.AUDIT_CHANNEL_ID)
        if channel is None:
            channel = await bot.fetch_channel(G.AUDIT_CHANNEL_ID)
    except Exception:
        channel = None
    if channel is None:
        print(f"[WARN] audit channel {G.AUDIT_CHANNEL_ID} not reachable — receipt DM audit dropped")
        return
    color = 0x22c55e if status == "SUCCESS" else (0xeab308 if status == "DM_CLOSED" else 0xef4444)
    embed = discord.Embed(title="[AUDIT LOG] RECEIPT_DM_DISPATCH", color=color)
    embed.add_field(name="User", value=f"<@{user_id}>", inline=True)
    embed.add_field(name="Game ID", value=str(thread_id), inline=True)
    embed.add_field(name="Status", value=status, inline=True)
    embed.add_field(name="Receipt URL", value=receipt_url, inline=False)
    if error:
        embed.add_field(name="Error", value=f"```{str(error)[:500]}```", inline=False)
    try:
        await channel.send(embed=embed)
    except Exception as e:
        print(f"[WARN] receipt DM audit post failed: {e}")


@tasks.loop(seconds=RECEIPT_DM_INTERVAL_SEC)
async def receipt_dm_loop():
    """Drain the receipt-DM queue: DM each finalized player their receipt
    embed + 24h multi-use receipt link, then audit-log the dispatch.

    SILENT ON EMPTY TICKS — logging happens ONLY when a queue item is
    dequeued, during active DM dispatch ([DM] ...), or on real exceptions."""
    try:
        events = await _run_mysql_io(_fetch_receipt_dm_queue_mysql, label="receipt dm read")
        if not events:
            return
        processed = []
        for ev in events:
            ev_id = int(ev.get("id") or 0)
            thread_id = str(ev.get("thread_id") or "")
            try:
                user_id = int(ev.get("user_id") or 0)
            except (TypeError, ValueError):
                user_id = 0
            if not thread_id or user_id <= 0:
                processed.append(ev_id)
                continue
            try:
                offline = thread_id == "offline"
                if offline:
                    # OFFLINE casino run — no game thread, no reservation. The
                    # roll summary travels in the queue row's payload column
                    # (written by POST /api/receipt/enqueue).
                    raw_payload = ev.get("payload")
                    try:
                        payload = json.loads(raw_payload) if isinstance(raw_payload, str) and raw_payload else None
                    except Exception:
                        payload = None
                    nation = (payload or {}).get("nation") if isinstance(payload, dict) else None
                    nation = str(nation).strip() if nation else None
                    progress = {
                        "results": (payload or {}).get("results") or {}
                    } if isinstance(payload, dict) else None
                    username = None
                    role_tier = 3
                    is_vip = False
                    data = None
                else:
                    nation = await _run_mysql_io(
                        _fetch_user_reservation_slot, thread_id, user_id,
                        label="receipt dm nation lookup",
                    )
                    data = await _run_mysql_io(
                        _fetch_web_session_receipt_data, thread_id, user_id,
                        label="receipt dm session data",
                    )
                    progress = data.get("progress") if data else None
                    try:
                        progress = json.loads(progress) if isinstance(progress, str) and progress else None
                    except Exception:
                        progress = None
                    username = (data or {}).get("username")
                    try:
                        role_tier = int((data or {}).get("role_tier") or 3)
                    except (TypeError, ValueError):
                        role_tier = 3
                    is_vip = bool((data or {}).get("is_vip"))
                if not nation:
                    print(f"[WARN] receipt dm: no reservation for {user_id} in {thread_id} — event dropped")
                    processed.append(ev_id)
                    continue
                # DEDUPE GUARD — when the receipt DM was already dispatched
                # for this session (bot-native receipt, host override DM, or a
                # prior queue drain), acknowledge the row WITHOUT re-DMing or
                # touching the audit embed. A reload can never re-spam the
                # player, and the audit message is edited in place only on
                # REAL modifications (override / re-roll).
                try:
                    already_sent = bool(await _run_mysql_io(
                        _fetch_session_receipt_dm_sent, thread_id, user_id,
                        label="receipt dm sent check",
                    ))
                except Exception:
                    already_sent = False
                if already_sent:
                    print(
                        f"[DM] Skipping duplicate receipt DM for {user_id} in "
                        f"{thread_id} (receipt_dm_sent=1)"
                    )
                    processed.append(ev_id)
                    continue
                if offline:
                    # No resumeable web receipt exists for offline runs — the
                    # DM IS the receipt record; link back to the casino.
                    receipt_url = BASE_URL
                else:
                    # Reuse the EXACT 24-hour multi-use receipt link generator
                    # used by /gamble (receipt_view tokens are never burned).
                    receipt_token = await _generate_web_access_token(
                        user_id,
                        can_roll_majors=True,
                        role_tier=role_tier,
                        game_id=thread_id,
                        username=username,
                        is_vip=is_vip,
                        receipt_view=True,
                        ttl_seconds=RECEIPT_VIEW_TOKEN_TTL_SEC,
                    )
                    receipt_url = f"{BASE_URL}/?token={receipt_token}&gameId={thread_id}"
                flag = NATION_FLAGS.get(nation, "🏳️")
                rules_summary = _format_web_receipt_lines(progress)
                receipt_note = (
                    "*This DM is your receipt record — good luck, Commander!*"
                    if offline
                    else "*This link stays valid for 24 hours and can be reopened anytime.*"
                )
                dm_embed = discord.Embed(
                    title="🧾 House Receipt — Casino Run Complete",
                    description=(
                        f"**Nation:** {flag} {nation}\n"
                        f"{rules_summary}\n\n"
                        f"🔗 **Receipt:** {receipt_url}\n"
                        f"{receipt_note}"
                    ),
                    color=0x22c55e,
                )
                print(f"[DM] Attempting DM to user_id={user_id}")
                dm_user = await _resolve_dm_target(user_id)
                if dm_user is None:
                    err = "could not resolve Discord user"
                    print(f"[DM] Failed to send DM to {user_id}: {err}")
                    await _post_receipt_dm_audit(user_id, thread_id, "FAILED", receipt_url, err)
                else:
                    try:
                        await dm_user.send(embed=dm_embed)
                        print(f"[DM] Successfully sent receipt DM to {user_id}")
                        await _post_receipt_dm_audit(user_id, thread_id, "SUCCESS", receipt_url, None)
                        # RECEIPT-DM DEDUPE — flag the session so the web
                        # enqueue endpoints stop re-queuing on every Stage 5
                        # mount (the queue row is acked below).
                        await _run_mysql_io(
                            _set_session_receipt_dm_sent, thread_id, user_id, True,
                            label="receipt dm sent flag",
                        )
                    except discord.Forbidden as err:
                        print(f"[DM] Failed to send DM to {user_id} (DMs closed): {err}")
                        await _post_receipt_dm_audit(user_id, thread_id, "DM_CLOSED", receipt_url, str(err))
                        # Terminal state — a closed inbox will never accept a
                        # re-DM; flag as handled so receipt reloads stop
                        # spamming DM_CLOSED audit entries.
                        await _run_mysql_io(
                            _set_session_receipt_dm_sent, thread_id, user_id, True,
                            label="receipt dm sent flag",
                        )
                    except Exception as err:
                        print(f"[DM] Failed to send DM to {user_id}: {err}")
                        await _post_receipt_dm_audit(user_id, thread_id, "FAILED", receipt_url, str(err))

                # MANDATORY AUDIT MIRROR — the receipt audit channel receives
                # the audit copy (GREEN for the original completion). The
                # shared helper posts once and EDITS in place on any later
                # modification, so reloads can never double-post. OFFLINE runs
                # have no game thread — the dispatch audit above is the only
                # log.
                if not offline:
                    web_results = (progress or {}).get("results") or {}
                    if not isinstance(web_results, dict):
                        web_results = {}
                    specialty_payload = web_results.get("specialty")
                    specialty_category = None
                    if isinstance(specialty_payload, dict):
                        specialty_category = specialty_payload.get("category")
                    await _post_receipt_audit_mirror(
                        user_id=user_id,
                        thread_id=thread_id,
                        nation=nation,
                        modules={
                            "ideology": web_results.get("ideology"),
                            "path": web_results.get("path"),
                            "doctrine": web_results.get("doctrine"),
                            "build": web_results.get("build"),
                            "achievements": web_results.get("achievements"),
                        },
                        receipt_url=receipt_url,
                        modified=False,
                        username=username,
                        specialty_category=specialty_category,
                    )
            except Exception as e:
                # Leave the event queued for the next tick.
                print(f"[WARN] receipt dm failed for {thread_id}/{user_id}: {e}")
                continue
            processed.append(ev_id)
        if processed:
            await _run_mysql_io(
                _delete_receipt_dm_rows_mysql, processed, label="receipt dm ack"
            )
    except Exception as e:
        print(f"Error in receipt_dm_loop: {e}")


async def _find_schedule_slot(slot_id: str):
    """Fresh lookup of one schedule-board slot by its slot id (the same id
    stored as host_settings.game_id and host_access_tokens.game_id)."""
    try:
        schedule_data = await read_json(SCHEDULE_FILE)
    except Exception:
        return None
    return next(
        (s for s in schedule_data if str(s.get("slot_id") or "") == str(slot_id)),
        None,
    )


class HostPanelReopenButton(
    discord.ui.DynamicItem[discord.ui.Button],
    template=r"host_reopen:(?P<slot_id>[0-9a-fA-F]+)",
):
    """Restart-proof GATED button posted to the private Casino log whenever a
    host saves the web Host Scheduling Panel.

    Clicking it re-verifies the CLICKING user against the slot's scheduling
    host directly in Discord — ONLY that host receives the panel link
    (delivered ephemeral, minted fresh on click). Everyone else gets an
    ephemeral denial, so the panel can never be reopened by anyone other than
    the host who scheduled and configured the game."""

    def __init__(self, slot_id: str):
        self.slot_id = str(slot_id)
        super().__init__(
            discord.ui.Button(
                label="Open Host Scheduling Panel",
                style=discord.ButtonStyle.primary,
                emoji="⚙️",
                custom_id=f"host_reopen:{self.slot_id}",
            )
        )

    @classmethod
    async def from_custom_id(cls, interaction, item, match, /):
        return cls(match["slot_id"])

    async def callback(self, interaction: discord.Interaction):
        try:
            slot = await _find_schedule_slot(self.slot_id)
            if not slot:
                return await interaction.response.send_message(
                    "❌ This session is no longer on the schedule board, so its "
                    "Host Scheduling Panel cannot be reopened. Schedule it again on "
                    f"the Host Calendar: {HOST_CALENDAR_URL}",
                    ephemeral=True,
                )
            try:
                host_id = int(slot.get("host_id") or 0)
            except (TypeError, ValueError):
                host_id = 0
            if not host_id or interaction.user.id != host_id:
                _audit_log(
                    "WARN",
                    f"host panel reopen DENIED slot={self.slot_id} "
                    f"requester={interaction.user.id} host={host_id}",
                )
                return await interaction.response.send_message(
                    "🔒 This Host Scheduling Panel is reserved for the host who "
                    "scheduled and configured this game.",
                    ephemeral=True,
                )

            # Only the scheduling host gets here — mint a FRESH 3-day token on
            # click (never reuse a stale one) and deliver the link ephemerally.
            token = await _generate_host_access_token(
                self.slot_id, host_id, is_senior=_is_senior_member(interaction.user)
            )
            panel_url = f"{BASE_URL}/host?gameId={self.slot_id}&token={token}"
            _audit_log(
                "INFO",
                f"host panel reopen link minted slot={self.slot_id} host={host_id}",
            )
            g_time = int(slot.get("game_timestamp") or 0)
            embed = discord.Embed(
                title="⚙️ Host Scheduling Panel",
                description=(
                    f"**{slot.get('mode') or 'Unknown'}** · <t:{g_time}:F> (<t:{g_time}:R>)\n\n"
                    "Your saved configuration loads exactly as you left it."
                ),
                color=0x1a1a2e,
            )
            view = discord.ui.View()
            view.add_item(
                discord.ui.Button(
                    label="Open Host Scheduling Panel",
                    style=discord.ButtonStyle.link,
                    url=panel_url,
                    emoji="⚙️",
                )
            )
            await interaction.response.send_message(embed=embed, view=view, ephemeral=True)
        except Exception as e:
            print(f"[ERROR] HostPanelReopenButton callback: {e}")
            try:
                if interaction.response.is_done():
                    await interaction.followup.send(
                        "❌ Could not open the Host Scheduling Panel right now. "
                        "Try again in a moment.",
                        ephemeral=True,
                    )
                else:
                    await interaction.response.send_message(
                        "❌ Could not open the Host Scheduling Panel right now. "
                        "Try again in a moment.",
                        ephemeral=True,
                    )
            except Exception:
                pass


async def _post_host_config_save_log(game_id: str, slot: dict, settings: dict) -> None:
    """Follow-up (Phase 6): whenever the host saves the web Host Scheduling
    Panel, post a private log entry in the Casino log channel. The entry
    carries a GATED reopen button (HostPanelReopenButton) — clicking it
    verifies the clicking user against the scheduling host in Discord, so
    ONLY the host who scheduled and configured the panel can receive the
    panel link again. The web panel then loads the exact saved configuration
    — the host reopens the panel exactly as they left it.

    No raw link is ever posted publicly: the message goes only to the private
    Casino log channel, and the panel link itself is delivered ephemeral to
    the verified host on click."""
    try:
        host_id = int(slot.get("host_id") or 0)
    except (TypeError, ValueError):
        host_id = 0
    if not host_id:
        print("[WARN] Host config save log skipped — slot has no host_id")
        return

    host_username = str(slot.get("host_username") or "").strip()
    host_line = f"@{host_username}" if host_username else f"<@{host_id}>"
    g_time = int(slot.get("game_timestamp") or 0)
    summary = _host_settings_summary_line(settings) or " *(defaults)*"
    embed = discord.Embed(
        title="⚙️ Host Configuration Saved",
        description=(
            f"**Host:** {host_line}\n"
            f"**Mode:** {slot.get('mode') or 'Unknown'} · **Time:** <t:{g_time}:F>\n"
            f"**Session:** `{game_id}`\n\n"
            f"**Saved settings:**{summary}\n\n"
            "Click the button below to receive your panel link — it is reserved "
            "for the scheduling host, and your configuration loads exactly as "
            "you left it."
        ),
        color=0x1a1a2e,
    )
    if g_time:
        embed.add_field(name="Game Time", value=f"<t:{g_time}:F>", inline=True)
    view = discord.ui.View(timeout=None)
    view.add_item(HostPanelReopenButton(str(game_id)))

    channel = bot.get_channel(RECEIPT_LOG_CHANNEL_ID)
    if not channel:
        try:
            channel = await bot.fetch_channel(RECEIPT_LOG_CHANNEL_ID)
        except Exception:
            channel = None
    if not channel:
        print("[WARN] Host config save log — Casino log channel not found")
        return
    try:
        await channel.send(embed=embed, view=view)
        _audit_log(
            "INFO",
            f"host config save log posted slot={game_id} host={host_id} "
            f"channel={RECEIPT_LOG_CHANNEL_ID}",
        )
    except Exception as e:
        print(f"[WARN] Host config save log post failed: {e}")


@tasks.loop(seconds=HOST_CONFIG_SYNC_INTERVAL_SEC)
async def host_config_sync_loop():
    """Poll dirty host_settings rows and push web-panel config to the Discord
    scheduling board (and the live game dict once the thread exists). Each
    successfully synced web save also posts a private panel link for the
    scheduling host to the Casino log channel."""
    try:
        raw = await _run_mysql_io(
            _fetch_host_settings_mysql, label="host settings sync read"
        )
        pending = {
            gid: row for gid, row in (raw or {}).items() if row.get("dirty")
        }
        if pending:
            schedule_data = await read_json(SCHEDULE_FILE)
            games_data = await read_json(GAMES_FILE)
            games_changed = False
            for gid, row in pending.items():
                settings = row.get("settings") or {}
                slot = next(
                    (s for s in schedule_data if str(s.get("slot_id") or "") == str(gid)),
                    None,
                )
                if slot is not None:
                    thread_id = str(slot.get("thread_id") or "")
                    game = games_data.get(thread_id)
                    if isinstance(game, dict):
                        _apply_host_settings_to_game(game, settings, slot.get("add_on"))
                        games_changed = True
                        schedule_reservation_update(thread_id)
                cleared = False
                try:
                    await _run_mysql_io(
                        _clear_host_settings_dirty_mysql, gid,
                        label="host settings dirty clear",
                    )
                    cleared = True
                except Exception as clear_err:
                    print(f"[WARN] host settings dirty clear failed: {clear_err}")
                # Phase 6 follow-up: post the host's private panel link ONCE
                # per save (only after the dirty flag clears — a failed clear
                # re-processes next loop and must not double-post).
                if cleared and slot is not None:
                    await _post_host_config_save_log(str(gid), slot, settings)
            if games_changed:
                await write_json(GAMES_FILE, games_data)
            # Board re-render picks up the new settings summary itself.
    except Exception as e:
        print(f"⚠️ host_config_sync_loop error: {e}")


async def before_host_config_sync_loop():
    await bot.wait_until_ready()


# ————— Web Scheduling Calendar (web /schedule → Discord board) —————
# The web calendar replaces the /schedule wizard. It never writes
# schedule_slots itself: the bot rewrites that table from its in-memory cache
# on every save, so a direct web insert would be silently deleted. The web
# queues a row in web_schedule_requests instead; this loop re-validates it
# with the /schedule rules (live host roles, day locks, mode, timestamps),
# saves through _save_schedule_slot, DMs the host their panel link, and
# writes the outcome back so the page can show success or the exact error.
# Short: the live map's host tools wait on this queue while a host drags
# players around (the pending-row query is a cheap indexed lookup).
WEB_SCHEDULE_SYNC_INTERVAL_SEC = 3
WEB_HOST_ROSTER_INTERVAL_MIN = 5
WEB_SCHEDULE_MAX_LOCK_GROUPS = 12
WEB_SCHEDULE_MAX_LOCKED_NATIONS = 400
_LOCK_LEVEL_RANK = {"VIP": 0, "Trusted": 1, "Verified": 2, "All Users": 3}
_WEB_SCHEDULE_MODE_VALUES = {choice.value for choice in SCHEDULE_MODE_CHOICES}
_WEB_SCHEDULE_ADDON_VALUES = {choice.value for choice in SCHEDULE_ADDON_CHOICES}


def _member_is_host(member) -> bool:
    """Same gate as is_host(): server admins or any ALLOWED_HOST_ROLES role."""
    if member is None:
        return False
    try:
        if member.guild_permissions.administrator:
            return True
    except Exception:
        pass
    return any(role.id in ALLOWED_HOST_ROLES for role in getattr(member, "roles", []))


async def _web_fetch_member(user_id: int):
    guild = bot.get_guild(cur_gid())
    if guild is None or not user_id:
        return None
    member = guild.get_member(user_id)
    if member is None:
        try:
            member = await guild.fetch_member(user_id)
        except Exception:
            member = None
    return member


def _replace_web_host_roster_mysql(rows: list) -> None:
    """Upsert the current host list and drop everyone not refreshed now."""
    conn = None
    cur = None
    try:
        now = int(time.time())
        conn = _db_get_connection()
        cur = conn.cursor()
        conn.start_transaction()
        gid = str(cur_gid())
        if rows:
            cur.executemany(
                "INSERT INTO web_host_roster (guild_id, user_id, username, display_name, is_senior, branches, updated_at) "
                "VALUES (%s, %s, %s, %s, %s, %s, %s) "
                "ON DUPLICATE KEY UPDATE username = VALUES(username), "
                "display_name = VALUES(display_name), is_senior = VALUES(is_senior), "
                "branches = VALUES(branches), updated_at = VALUES(updated_at)",
                [(gid, uid, name, display, senior, branches, now) for uid, name, display, senior, branches in rows],
            )
        cur.execute("DELETE FROM web_host_roster WHERE guild_id = %s AND updated_at < %s", (gid, now))
        conn.commit()
    except Exception as e:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        print(f"[WARN] Could not refresh web_host_roster: {e}")
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _fetch_pending_web_schedule_requests_mysql(limit: int = 20) -> list:
    conn = None
    cursor = None
    try:
        conn = _db_get_connection()
        cursor = conn.cursor(dictionary=True)
        cursor.execute(
            "SELECT request_id, action, slot_id, host_id, payload, created_at, guild_id "
            "FROM web_schedule_requests WHERE status = 'pending' "
            "ORDER BY created_at ASC LIMIT %s",
            (int(limit),),
        )
        rows = cursor.fetchall()
        for row in rows:
            row["payload"] = _parse_mysql_json(row.get("payload"))
        return rows
    except Exception as e:
        print(f"[WARN] Could not read web_schedule_requests: {e}")
        return []
    finally:
        if cursor is not None:
            try:
                cursor.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _finish_web_schedule_request_mysql(request_id: str, status: str, result, error) -> None:
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        cur.execute(
            "UPDATE web_schedule_requests SET status = %s, result = %s, error = %s, "
            "processed_at = %s WHERE request_id = %s",
            (
                status,
                json.dumps(result, ensure_ascii=False) if result is not None else None,
                error,
                int(time.time()),
                str(request_id),
            ),
        )
        conn.commit()
    except Exception as e:
        # Left pending → re-processed next tick; create/cancel are idempotent.
        print(f"[WARN] Could not acknowledge web schedule request {request_id}: {e}")
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _web_parse_nation_locks(raw, game_timestamp: int):
    """Validate the web calendar's nation lock groups.

    Returns (groups, locked_regions, error). Each group is {label, nations,
    release_timestamp|None}; locked_regions is the de-duplicated union the
    announced game starts with (the same list /lock writes to). A nation
    listed in two groups stays in the first one only."""
    if raw in (None, ""):
        return [], [], None
    if not isinstance(raw, list) or len(raw) > WEB_SCHEDULE_MAX_LOCK_GROUPS:
        return [], [], f"❌ At most {WEB_SCHEDULE_MAX_LOCK_GROUPS} nation lock groups are allowed."
    groups = []
    union = []
    seen = set()
    for entry in raw:
        if not isinstance(entry, dict) or not isinstance(entry.get("nations") or [], list):
            return [], [], "❌ Invalid nation lock group."
        label = str(entry.get("label") or "").strip()[:40] or "Locked nations"
        nations = []
        for name in entry.get("nations") or []:
            name = str(name or "").strip()[:128]
            if not name or name in seen:
                continue
            seen.add(name)
            nations.append(name)
        if not nations:
            continue
        release = entry.get("release_timestamp")
        if release is not None:
            release = _normalize_epoch_seconds(release)
            if release is None or release >= game_timestamp:
                return [], [], f"❌ **{label}** must unlock before the game starts."
        groups.append({"label": label, "nations": nations, "release_timestamp": release})
        union.extend(nations)
    if len(union) > WEB_SCHEDULE_MAX_LOCKED_NATIONS:
        return [], [], f"❌ At most {WEB_SCHEDULE_MAX_LOCKED_NATIONS} nations can be locked."
    return groups, union, None


WEB_PRESET_MAX_GROUPS = 24
WEB_PRESET_MAX_TIERS = 4


def _web_parse_resource_entries(raw, limit: int, noun: str):
    """Validate a web list of rules or mods ({name, link}). None = not set
    (the mode's standard list). Returns (entries | None, error)."""
    if raw is None:
        return None, None
    if not isinstance(raw, list) or len(raw) > limit:
        return None, f"❌ At most {limit} {noun} are allowed."
    entries = []
    for entry in raw:
        if not isinstance(entry, dict):
            return None, f"❌ Invalid {noun[:-1]}."
        name = str(entry.get("name") or "").strip()[:100]
        link = str(entry.get("link") or "").strip()
        if not name or len(link) > 400 or not re.fullmatch(r"https?://\S+", link, re.IGNORECASE):
            return None, f"❌ Every {noun[:-1]} needs a name and a valid http(s) link."
        entries.append({"name": name, "link": link})
    return entries, None


def _web_parse_nation_layout(raw, mode: str):
    """Validate a preset's own nation groups. Returns (layout | None,
    not_playable, error). layout keeps the playable groups only, as
    [{name, tiers: [{label | None, nations}]}] in the host's order. Every
    nation of the mode that isn't in a playable group (a group turned off,
    or never placed) is not playable in that game: hidden and locked."""
    if raw in (None, ""):
        return None, [], None
    if not isinstance(raw, list) or not raw or len(raw) > WEB_PRESET_MAX_GROUPS:
        return None, [], f"❌ Nation groups: 1–{WEB_PRESET_MAX_GROUPS} groups."
    all_nations = list(_get_mode_nation_data(mode)[0])
    valid = {n.lower(): n for n in all_nations}
    seen: set[str] = set()
    names: set[str] = set()
    layout = []
    for group in raw:
        if not isinstance(group, dict) or not isinstance(group.get("tiers") or [], list):
            return None, [], "❌ Invalid nation group."
        name = str(group.get("name") or "").strip()[:40]
        if not name:
            return None, [], "❌ Every nation group needs a name."
        if name.lower() in names:
            return None, [], f"❌ Two nation groups are called **{name}**."
        names.add(name.lower())
        if len(group.get("tiers") or []) > WEB_PRESET_MAX_TIERS:
            return None, [], f"❌ **{name}** can have at most {WEB_PRESET_MAX_TIERS} sub-groups."
        tiers = []
        for tier in group.get("tiers") or []:
            if not isinstance(tier, dict) or not isinstance(tier.get("nations") or [], list):
                return None, [], f"❌ Invalid sub-group in **{name}**."
            nations = []
            for raw_name in tier.get("nations") or []:
                match = valid.get(str(raw_name or "").strip().lower())
                if match is None:
                    return None, [], f"❌ '{str(raw_name)[:60]}' isn't a nation in {mode}."
                if match in seen:
                    return None, [], f"❌ **{match}** is in two groups — a nation can only be in one."
                seen.add(match)
                nations.append(match)
            if nations:
                tiers.append({"label": str(tier.get("label") or "").strip()[:40] or None, "nations": nations})
        if group.get("enabled", True) is not False and tiers:
            layout.append({"name": name, "tiers": tiers})
    playable = {n for group in layout for tier in group["tiers"] for n in tier["nations"]}
    if not playable:
        return None, [], "❌ Turn on at least one nation group that has nations in it."
    return layout, [n for n in all_nations if n not in playable], None


def _web_parse_draft(raw, mode: str, add_on, nation_layout):
    """Draft game settings from the calendar: two named teams, each with a
    captain and the nation groups it drafts from (the preset's playable
    groups, else the mode's standard ones), plus the pick order. Returns
    (slot fields, error); a normal game clears every draft field."""
    if raw in (None, "", False):
        return {"is_draft": False, "draft_teams": None, "draft_coin_flip": None, "draft_first_picker": None}, None
    if not isinstance(raw, dict):
        return None, "❌ Invalid draft settings."
    if add_on in DRAFT_BLOCKED_ADDONS:
        return None, "❌ Draft games can't use the Casino, Fortunes of War or All Add-ons add-ons."
    teams = raw.get("teams")
    if not isinstance(teams, list) or len(teams) != 2:
        return None, "❌ A draft needs exactly two teams."
    if nation_layout:
        available = {str(group["name"]).lower(): str(group["name"]) for group in nation_layout}
    else:
        available = {str(category).lower(): str(category) for category, _subs in _get_archive_layout(mode)}
    names: set[str] = set()
    captains: set[str] = set()
    used: set[str] = set()
    out = []
    for team in teams:
        if not isinstance(team, dict):
            return None, "❌ Invalid draft team."
        name = str(team.get("name") or "").strip()[:30]
        if not name:
            return None, "❌ Give both draft teams a name."
        if name.lower() in names:
            return None, "❌ The two draft teams need different names."
        names.add(name.lower())
        captain = str(team.get("captain_id") or "").strip()
        if not captain.isdigit():
            return None, f"❌ Pick a captain for **{name}**."
        if captain in captains:
            return None, "❌ The two draft teams need different captains."
        captains.add(captain)
        groups = []
        for raw_group in team.get("groups") or []:
            match = available.get(str(raw_group).strip().lower())
            if match is None:
                return None, f"❌ '{str(raw_group)[:40]}' isn't one of this game's nation groups."
            if match.lower() in used:
                return None, f"❌ **{match}** is in both draft teams."
            used.add(match.lower())
            groups.append(match)
        if not groups:
            return None, f"❌ Put at least one nation group in **{name}**."
        # Text: the website reads slot_data with JavaScript numbers.
        out.append({"name": name, "groups": groups, "captain_id": captain})
    coin_flip = raw.get("coin_flip") is not False
    first = raw.get("first_picker")
    first = first if isinstance(first, int) and not isinstance(first, bool) and first in (0, 1) else 0
    return {
        "is_draft": True,
        "draft_teams": out,
        "draft_coin_flip": coin_flip,
        "draft_first_picker": None if coin_flip else first,
    }, None


async def _dm_web_schedule_confirmation(member, slot: dict, panel_url: str) -> None:
    """DM the host what the /schedule wizard used to show ephemerally: the
    shared host access key and the Host Scheduling Panel link."""
    g_time = int(slot.get("game_timestamp") or 0)
    embed = discord.Embed(
        title="📅 Game Scheduled from the Web Calendar",
        description=(
            f"**{slot.get('mode')}** · <t:{g_time}:F> (<t:{g_time}:R>) is now on the schedule board.\n\n"
            f"Your shared host access key is: `{slot.get('host_key')}`\n"
            "Open the Host Scheduling Panel to configure casino modules, re-roll "
            "budgets and entry-level gating.\n*Link valid for 3 days.*"
        ),
        color=0x1a1a2e,
    )
    ann_ts = slot.get("announce_timestamp")
    embed.add_field(
        name="Announcement",
        value=f"Auto-posts <t:{ann_ts}:F>" if ann_ts else "Not set — edit the game on the calendar to pick a time",
        inline=True,
    )
    if slot.get("locked_regions"):
        embed.add_field(
            name="Host-locked nations", value=str(len(slot["locked_regions"])), inline=True
        )
    if slot.get("preset_name"):
        embed.add_field(name="Preset", value=str(slot["preset_name"]), inline=True)
    view = discord.ui.View()
    view.add_item(
        discord.ui.Button(
            label="Open Host Scheduling Panel",
            style=discord.ButtonStyle.link,
            url=panel_url,
            emoji="⚙️",
        )
    )
    await _dm_user_safe(member, embed=embed, view=view, label="web schedule confirmation")


def _member_is_staff(member) -> bool:
    """Same gate as is_admin_staff(): server admins or Host Management."""
    if member is None:
        return False
    try:
        if member.guild_permissions.administrator:
            return True
    except Exception:
        pass
    return _is_senior_member(member)


def _web_time_fields(payload: dict, now: int):
    """Validate the game time + board day/week of a web request.
    Returns ((game_timestamp, day, week_key), error)."""
    g_time = _normalize_epoch_seconds(payload.get("game_timestamp"))
    if g_time is None:
        return None, "❌ Invalid game time."
    if g_time <= now:
        return None, "❌ The game time has already passed — pick a later time."
    day = str(payload.get("day") or "").strip().capitalize()
    if day not in DAY_ORDER:
        return None, "❌ Invalid day."
    week_key = _resolve_schedule_week(str(payload.get("week") or ""))
    if week_key is None:
        return None, "❌ Invalid week."
    return (g_time, day, week_key), None


async def _web_day_lock_error(week_key: str, day: str) -> str | None:
    locked = await _get_day_lock(week_key, day)
    if not locked:
        return None
    reason_txt = f" ({locked.get('reason')})" if locked.get("reason") else ""
    return (
        f"⛔ {day} (week of {_week_range_label(week_key)}) is locked by staff"
        f"{reason_txt} and cannot be scheduled."
    )


async def _build_web_schedule_fields(payload: dict, keep_day: tuple | None = None):
    """Validate a web calendar payload with the /schedule rules and return
    (slot_fields, error). slot_fields holds every schedule-slot field the web
    form controls — not slot_id / host / host_key. `keep_day` = (week, day)
    of the slot being edited: a staff lock added after booking never blocks
    edits that keep the game on that day."""
    mode = str(payload.get("mode") or "").strip()
    if mode not in _WEB_SCHEDULE_MODE_VALUES:
        return None, f"❌ Unknown game mode: {mode or '(none)'}."

    now = int(time.time())
    time_fields, err = _web_time_fields(payload, now)
    if err:
        return None, err
    g_time, day, week_key = time_fields

    logging_mode = str(payload.get("logging_mode") or "Strict")
    if logging_mode not in ("Strict", "Casual"):
        return None, "❌ Logging mode must be Strict or Casual."

    add_on = payload.get("add_on") or None
    if add_on is not None and add_on not in _WEB_SCHEDULE_ADDON_VALUES:
        return None, f"❌ Unknown add-on: {add_on}."
    if add_on in _UNAVAILABLE_ADDONS:
        return None, "❌ Casino and Fortunes of War are currently unavailable."
    if add_on in HOME_ONLY_ADDONS and cur_gid() != GUILD_ID:
        return None, "❌ The Casino and Fortunes of War add-ons are only available on TommyKay's server."

    major_level = payload.get("major_lock_level") or "Trusted"
    minor_level = payload.get("minor_lock_level") or "All Users"
    if major_level not in _LOCK_LEVEL_RANK or minor_level not in _LOCK_LEVEL_RANK:
        return None, "❌ Invalid nation lock level."

    if keep_day != (week_key, day):
        lock_err = await _web_day_lock_error(week_key, day)
        if lock_err:
            return None, lock_err

    announce_ts = payload.get("announce_timestamp")
    if announce_ts is None:
        # Manual announcing (/announce_game) is gone — every game announces itself.
        return None, "❌ Pick when the game should be announced (or announce it right away)."
    if announce_ts is not None:
        announce_ts = _normalize_epoch_seconds(announce_ts)
        if announce_ts is None or announce_ts >= g_time:
            return None, "❌ The announcement must be posted before the game starts."
        # "Announce right away" (or a time that passed while queued) fires on
        # the next check_scheduled_announcements tick.
        announce_ts = max(announce_ts, now)

    # Casino add-ons manage their 2-tier step-down on the web Host Panel;
    # regular games get the same per-scope unlocks the Discord wizard saved.
    casino = add_on in _CASINO_WEB_LOCK_ADDONS
    automated_unlocks = {}
    raw_unlocks = payload.get("automated_unlocks") if payload.get("automated_unlock") else None
    if not casino and isinstance(raw_unlocks, dict):
        for scope, current in (("major", major_level), ("minor", minor_level)):
            config = raw_unlocks.get(scope)
            if not config:
                continue
            target = config.get("target_level") if isinstance(config, dict) else None
            unlock_ts = _normalize_epoch_seconds(config.get("unlock_timestamp")) if isinstance(config, dict) else None
            if target not in _LOCK_LEVEL_RANK or unlock_ts is None:
                return None, f"❌ Invalid {scope} nation unlock."
            if _LOCK_LEVEL_RANK[target] <= _LOCK_LEVEL_RANK[current]:
                return None, (
                    f"❌ The {scope} nation unlock must open access wider than "
                    f"**{_lock_label(current)}**."
                )
            if unlock_ts >= g_time:
                return None, f"❌ {scope.title()} nations must unlock before the game starts."
            automated_unlocks[scope] = {
                "target_level": target,
                "unlock_timestamp": unlock_ts,
                "applied": False,
            }
    automated_unlock = bool(payload.get("automated_unlock")) if casino else bool(automated_unlocks)

    automatic_reminder = bool(payload.get("automatic_reminder"))
    checksum = None
    if automatic_reminder:
        checksum = str(payload.get("scheduled_checksum") or "").strip().upper()
        if not re.fullmatch(r"[A-Z0-9]{4}", checksum):
            return None, "❌ The reminder checksum must be exactly four letters or digits."

    nation_locks, locked_regions, lock_err = _web_parse_nation_locks(payload.get("nation_locks"), g_time)
    if lock_err:
        return None, lock_err

    # Game mode preset (Presets page): its own nation groups, rules and mods.
    nation_layout, not_playable, layout_err = _web_parse_nation_layout(payload.get("nation_layout"), mode)
    if layout_err:
        return None, layout_err
    if not_playable:
        # Not-playable nations stay locked for good — keep them out of the
        # timed lock groups so a release can't open them.
        hidden = set(not_playable)
        nation_locks = [
            {**group, "nations": [n for n in group["nations"] if n not in hidden]}
            for group in nation_locks
        ]
        nation_locks = [group for group in nation_locks if group["nations"]]
        locked_regions = [n for n in locked_regions if n not in hidden]
    rules, err = _web_parse_resource_entries(payload.get("rules"), WEB_SCHEDULE_MAX_RULES, "rulesets")
    if err:
        return None, err
    mods, err = _web_parse_resource_entries(payload.get("mods"), WEB_GAME_MAX_MODS, "mods")
    if err:
        return None, err
    preset_id = str(payload.get("preset_id") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{32}", preset_id):
        preset_id = None
    preset_name = (str(payload.get("preset_name") or "").strip()[:60] or None) if preset_id else None

    # Draft game: teams map nation groups to captains (see _process_web_draft).
    draft_fields, err = _web_parse_draft(payload.get("draft"), mode, add_on, nation_layout)
    if err:
        return None, err
    for team in draft_fields.get("draft_teams") or []:
        if await _web_fetch_member(int(team["captain_id"])) is None:
            return None, f"❌ The {team['name']} captain isn't a member of the server any more."

    fields = {
        "mode": mode,
        "day": day,
        "week": week_key,
        "game_timestamp": g_time,
        "logging_mode": logging_mode,
        "automated_unlock": automated_unlock,
        "automated_unlocks": automated_unlocks,
        "add_on": add_on,
        "category": _schedule_category(mode),
        "major_lock_level": major_level,
        "minor_lock_level": minor_level,
        "announce_timestamp": announce_ts,
        "automatic_reminder": automatic_reminder,
        "scheduled_checksum": checksum,
        "locked_regions": locked_regions,
        "nation_locks": nation_locks,
        "preset_id": preset_id,
        "preset_name": preset_name,
        "nation_layout": nation_layout,
        "layout_disabled_nations": not_playable,
        "rules": rules,
        "mods": mods,
        **draft_fields,
        "fortunes_mode": (
            ("competitive" if payload.get("fortunes_mode") == "competitive" else "casual")
            if add_on == "fortunes" else None
        ),
    }
    return fields, None


async def _web_resolve_new_host(payload: dict, owner_id: int, requester):
    """Optional host handover on an edit. Returns (host_member, error)."""
    raw = payload.get("new_host_id")
    if raw in (None, "", str(owner_id), owner_id):
        return await _web_fetch_member(owner_id), None
    try:
        new_host_id = int(raw)
    except (TypeError, ValueError):
        return None, "❌ Invalid new host."
    new_host = await _web_fetch_member(new_host_id)
    if not _member_is_host(new_host):
        return None, "❌ The new host needs a Host role in the server."
    return new_host, None


async def _process_web_schedule_create(req: dict) -> tuple[bool, dict | None, str | None]:
    """Turn one web calendar request into a schedule slot (the /schedule rules)."""
    payload = req.get("payload") or {}
    host_id = int(req.get("host_id") or 0)
    slot_id = str(req.get("slot_id") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{32}", slot_id):
        return False, None, "❌ Invalid request — please schedule again from the calendar."

    # Idempotent: a crash between saving and acknowledging re-runs the request.
    if await _find_schedule_slot(slot_id):
        return True, {"slot_id": slot_id}, None

    member = await _web_fetch_member(host_id)
    if not _member_is_host(member):
        return False, None, "❌ Only members with a Host role can schedule games."

    fields, err = await _build_web_schedule_fields(payload)
    if err:
        return False, None, err
    if not _mode_enabled(fields["mode"]):
        return False, None, f"❌ {fields['mode']} is turned off in this server's settings."
    if not _can_host_mode(member, fields["mode"]):
        return False, None, _host_branch_refusal(member, fields["mode"])
    slot = {
        "slot_id": slot_id,
        "guild_id": str(cur_gid()),
        "host_id": host_id,
        "host_username": member.name or str(host_id),
        "host_key": _generate_host_key(),
        "status": "scheduled",
        "source": "web",
        **fields,
    }
    if slot["fortunes_mode"] is None:
        del slot["fortunes_mode"]
    _audit_log(
        "INFO",
        f"web schedule create slot={slot_id} timestamp={slot['game_timestamp']} host={host_id} "
        f"mode={slot['mode']} day={slot['day']} week={slot['week']} timezone={payload.get('timezone')}",
    )
    saved, err = await _save_schedule_slot(slot)
    if not saved:
        return False, None, err

    token = await _generate_host_access_token(
        slot_id, host_id, is_senior=_is_senior_member(member)
    )
    panel_url = f"{BASE_URL}/host?gameId={slot_id}&token={token}"
    await _dm_web_schedule_confirmation(member, slot, panel_url)
    return True, {"slot_id": slot_id, "panel_url": panel_url}, None


def _shift_pending_unlocks(container: dict, delta: int) -> None:
    """Move not-yet-applied automated unlocks / nation-lock releases with the
    game when an announced game is rescheduled (they were set as 'N hours
    before the game')."""
    if not delta:
        return
    for config in (container.get("automated_unlocks") or {}).values():
        if isinstance(config, dict) and not config.get("applied") and config.get("unlock_timestamp"):
            config["unlock_timestamp"] = int(config["unlock_timestamp"]) + delta
    for release in container.get("nation_lock_releases") or []:
        if isinstance(release, dict) and not release.get("applied") and release.get("unlock_timestamp"):
            release["unlock_timestamp"] = int(release["unlock_timestamp"]) + delta
    for group in container.get("nation_locks") or []:
        if isinstance(group, dict) and group.get("release_timestamp"):
            group["release_timestamp"] = int(group["release_timestamp"]) + delta


async def _refresh_announcement_after_edit(game: dict, thread_id: str, changes: dict, day: str) -> None:
    """Rewrite the public announcement + thread name after a day/time/host
    change (what /edit_announcement used to do)."""
    mode = game.get("mode", "Game")
    message_id = game.get("announcement_message_id")
    channel_id = game.get("announcement_channel_id") or (MODE_CONFIG.get(mode) or {}).get("announcement_channel_id")
    if message_id and channel_id and ("time" in changes or "host" in changes):
        try:
            channel = bot.get_channel(int(channel_id)) or await bot.fetch_channel(int(channel_id))
            message = await channel.fetch_message(int(message_id))
            content = message.content
            if "time" in changes:
                content = re.sub(r"<t:\d+:", f"<t:{changes['time']['new']}:", content)
            if "host" in changes:
                content = content.replace(f"<@{changes['host']['old']}>", f"<@{changes['host']['new']}>")
            if content != message.content:
                await message.edit(content=content)
        except Exception as e:
            print(f"[WARN] web edit: could not update announcement for {thread_id}: {e}")
    if "time" in changes or "day" in changes:
        try:
            start = int(game.get("start_timestamp") or 0)
            date_str = datetime.datetime.fromtimestamp(start, tz=datetime.timezone.utc).strftime("%m.%d.%Y")
            if not _game_has_thread(game):
                # Same format as the announcement loop.
                game["thread_name"] = f"{mode} Game - {day} - {date_str}"[:100]
                return
            thread = bot.get_channel(int(thread_id)) or await bot.fetch_channel(int(thread_id))
            # Same format as the announcement loop / /announce_game.
            name = f"{mode} Game - {day} - {date_str} Reservations"
            await thread.edit(name=name[:100])
            game["thread_name"] = name[:100]
        except Exception as e:
            print(f"[WARN] web edit: could not rename thread {thread_id}: {e}")


async def _web_edit_announced_slot(slot: dict, payload: dict, requester, new_host):
    """Day / time / host change of an announced game: updates the game, the
    announcement, the thread name and the board, and DMs reserved players."""
    slot_id = str(slot.get("slot_id"))
    games_data = await read_json(GAMES_FILE)
    thread_id = str(slot.get("thread_id") or "")
    if thread_id not in games_data:
        thread_id = next(
            (
                tid for tid, game in games_data.items()
                if game.get("host_id") == slot.get("host_id")
                and game.get("start_timestamp") == slot.get("game_timestamp")
            ),
            "",
        )
    game = games_data.get(thread_id)
    if not game:
        return False, None, "❌ Couldn't find this game's Discord thread any more."
    if game.get("game_started") or game.get("status") in ("ended", "cancelled"):
        return False, None, "❌ This game has already started or ended and can't be edited."

    time_fields, err = _web_time_fields(payload, int(time.time()))
    if err:
        return False, None, err
    new_ts, new_day, new_week = time_fields
    old_ts = int(game.get("start_timestamp") or slot.get("game_timestamp") or 0)
    old_day = slot.get("day") or "?"
    old_host_id = int(game.get("host_id") or slot.get("host_id") or 0)

    changes = {}
    if new_ts != old_ts:
        changes["time"] = {"old": old_ts, "new": new_ts}
    if new_day != old_day:
        changes["day"] = {"old": old_day, "new": new_day}
    if new_host is not None and new_host.id != old_host_id:
        changes["host"] = {"old": old_host_id, "new": new_host.id}
    if not changes:
        return True, {"slot_id": slot_id}, None
    if (new_week, new_day) != (_item_week(slot), slot.get("day")):
        lock_err = await _web_day_lock_error(new_week, new_day)
        if lock_err:
            return False, None, lock_err

    delta = new_ts - old_ts
    game["start_timestamp"] = new_ts
    _shift_pending_unlocks(game, delta)
    if "host" in changes:
        game["host_id"] = new_host.id
    await _refresh_announcement_after_edit(game, thread_id, changes, new_day)
    await write_json(GAMES_FILE, games_data)

    async with _schedule_slot_write_lock:
        schedule_data = list(await read_json(SCHEDULE_FILE))
        for item in schedule_data:
            if str(item.get("slot_id") or "") == slot_id:
                item.update({"game_timestamp": new_ts, "day": new_day, "week": new_week})
                item["thread_id"] = thread_id
                _shift_pending_unlocks(item, delta)
                if "host" in changes:
                    item["host_id"] = new_host.id
                    item["host_username"] = new_host.name or str(new_host.id)
                break
        await write_json(SCHEDULE_FILE, schedule_data)

    schedule_reservation_update(int(thread_id))
    guild = bot.get_guild(cur_gid())
    notified = await _dm_reservation_schedule_changes(guild, game, thread_id, changes) if guild else 0
    _audit_log(
        "INFO",
        f"web edit (announced) slot={slot_id} thread={thread_id} by={requester.id} "
        f"changes={sorted(changes)} new_ts={new_ts}",
    )
    return True, {"slot_id": slot_id, "notified": notified}, None


async def _process_web_schedule_update(req: dict) -> tuple[bool, dict | None, str | None]:
    """Edit a scheduled game. Before the announcement every setting can
    change; after it, only the day, time and host (players get a DM)."""
    payload = req.get("payload") or {}
    requester_id = int(req.get("host_id") or 0)
    slot_id = str(req.get("slot_id") or "").strip()
    requester = await _web_fetch_member(requester_id)
    if not _member_is_host(requester):
        return False, None, "❌ Only members with a Host role can edit games."
    slot = await _find_schedule_slot(slot_id)
    if slot is None:
        return False, None, "❌ This game is no longer on the schedule."
    try:
        owner_id = int(slot.get("host_id") or 0)
    except (TypeError, ValueError):
        owner_id = 0
    if owner_id != requester_id and not _member_is_staff(requester):
        return False, None, "❌ You can only edit games you are hosting."
    new_host, err = await _web_resolve_new_host(payload, owner_id, requester)
    if err:
        return False, None, err

    if slot.get("announced") or slot.get("thread_id"):
        if new_host is not None and new_host.id != owner_id and not _can_host_mode(new_host, slot.get("mode")):
            return False, None, _host_branch_refusal(new_host, slot.get("mode"), who=new_host.display_name)
        return await _web_edit_announced_slot(slot, payload, requester, new_host)

    fields, err = await _build_web_schedule_fields(payload, keep_day=(_item_week(slot), slot.get("day")))
    if err:
        return False, None, err
    game_host = new_host or requester
    if game_host is not None and not _can_host_mode(game_host, fields["mode"]):
        who = "You" if game_host.id == requester_id else game_host.display_name
        return False, None, _host_branch_refusal(game_host, fields["mode"], who=who)
    async with _schedule_slot_write_lock:
        schedule_data = list(await read_json(SCHEDULE_FILE))
        target = next(
            (item for item in schedule_data if str(item.get("slot_id") or "") == slot_id), None
        )
        if target is None:
            return False, None, "❌ This game is no longer on the schedule."
        if target.get("announced") or target.get("thread_id"):
            return False, None, "❌ This game was just announced — open it again to edit the time."
        target.update(fields)
        if fields.get("fortunes_mode") is None:
            target.pop("fortunes_mode", None)
        if new_host is not None and new_host.id != owner_id:
            target["host_id"] = new_host.id
            target["host_username"] = new_host.name or str(new_host.id)
        await write_json(SCHEDULE_FILE, schedule_data)
    _audit_log(
        "INFO",
        f"web edit slot={slot_id} by={requester_id} host={target.get('host_id')} "
        f"timestamp={fields['game_timestamp']} timezone={payload.get('timezone')}",
    )
    return True, {"slot_id": slot_id}, None


async def _process_web_schedule_cancel(req: dict) -> tuple[bool, dict | None, str | None]:
    """Remove a not-yet-announced slot from the board."""
    host_id = int(req.get("host_id") or 0)
    slot_id = str(req.get("slot_id") or "").strip()
    member = await _web_fetch_member(host_id)
    if not _member_is_host(member):
        return False, None, "❌ Only members with a Host role can cancel games."
    async with _schedule_slot_write_lock:
        schedule_data = list(await read_json(SCHEDULE_FILE))
        slot = next(
            (s for s in schedule_data if str(s.get("slot_id") or "") == slot_id), None
        )
        if slot is None:
            return True, {"slot_id": slot_id}, None
        try:
            owner_id = int(slot.get("host_id") or 0)
        except (TypeError, ValueError):
            owner_id = 0
        if owner_id != host_id and not _member_is_staff(member):
            return False, None, "❌ You can only cancel games you are hosting."
        if slot.get("announced") or slot.get("thread_id"):
            return False, None, (
                "❌ This game is already announced — cancel it from the Games page on the website."
            )
        await write_json(
            SCHEDULE_FILE,
            [s for s in schedule_data if str(s.get("slot_id") or "") != slot_id],
        )
    _audit_log("INFO", f"web schedule cancel slot={slot_id} by={host_id} host={owner_id}")
    return True, {"slot_id": slot_id}, None


async def _process_web_day_lock(req: dict, lock: bool) -> tuple[bool, dict | None, str | None]:
    """Staff day lock / unlock from the calendar (formerly /lock_day, /unlock_day)."""
    payload = req.get("payload") or {}
    member = await _web_fetch_member(int(req.get("host_id") or 0))
    if not _member_is_staff(member):
        return False, None, "❌ Only staff can lock or unlock days."
    day = str(payload.get("day") or "").strip().capitalize()
    week_key = _resolve_schedule_week(str(payload.get("week") or ""))
    if day not in DAY_ORDER or week_key is None:
        return False, None, "❌ Invalid day."
    locked_days = list(await read_json(LOCKED_DAYS_FILE))
    existing = _find_day_lock(locked_days, week_key, day)
    if lock and not existing:
        locked_days.append({
            "week": week_key,
            "day": day,
            "reason": str(payload.get("reason") or "").strip()[:200] or None,
            "locked_by": member.id,
            "ts": int(time.time()),
        })
    elif not lock and existing:
        locked_days = [record for record in locked_days if record is not existing]
    else:
        return True, {"week": week_key, "day": day}, None  # already in that state
    await write_json(LOCKED_DAYS_FILE, locked_days)
    _audit_log("INFO", f"web day {'lock' if lock else 'unlock'} {week_key} {day} by={member.id}")
    return True, {"week": week_key, "day": day}, None

# =============================================================================
# TICKETS — merged in from the TicketMaster bot (Hearts of Iron IV only)
# -----------------------------------------------------------------------------
# Players press the ticket panel (/spawn); GameMaster makes a private channel
# for them and the staff who handle that kind of ticket:
#   Verification (RP / Historical)    Ticket Support + Host Management
#   Host application (RP / HIST)      Host Management only
#   Report host                       Host Management only — the reported host
#                                     is always kept out, even if they're management
#   Appeal / player report / commend / question
#                                     every host + Host Management; the host of
#                                     the game it's about is pinged
#   Bug report / suggestion           Developers + Host Management
# Server admins can do everything. Resolving a verification ticket gives the
# branch's Verified role; resolving a host application gives the branch's
# Assistant host role. Inactive tickets (server settings → Tickets): a ping
# after 24 hours without messages, closed as unresolved 24 hours later.
# Roles and channels come from each server's settings (Tickets step).
# =============================================================================
TICKET_CATEGORY_ID = 0             # Server settings → Tickets
TICKET_LOG_CHANNEL_ID = 0          # closed-ticket transcripts
TICKET_PRIVATE_LOG_CHANNEL_ID = 0  # host applications / host reports
TICKET_SUPPORT_ROLES: list[int] = []
DEVELOPER_ROLES: list[int] = []
TICKET_REMIND_AFTER_SEC = 24 * 3600
TICKET_CLOSE_AFTER_SEC = 24 * 3600   # after the reminder: 48 hours in total
TICKET_SWEEP_MINUTES = 30
TICKET_FLOW_TIMEOUT = 900
# "TicketMaster": tickets opened by the old ticket bot before the merge.
TICKET_TOPIC_TAGS = ("GameMaster", "TicketMaster")
_TICKET_TYPE_RE = re.compile(r"type=(?P<type>[^|]+?)\s*(?:\||$)")
_TICKET_FIELD_RE = re.compile(r"\b(opener|host|target)=(\d+)")
_TICKET_REMINDERS_KEY = "ticket_reminders"  # bot_config: channel id → when the inactivity ping went out
_TICKET_COUNTER_KEY = "ticket_counter"

# kind → its name, who handles it, whether the transcript is private, what resolving gives.
TICKET_KINDS: dict[str, dict] = {
    "Verification": {"label": "RP Verification", "staff": ("support", "management"), "private": False, "grant": ("verify", "Roleplay")},
    "Hist-Verification": {"label": "Historical Verification", "staff": ("support", "management"), "private": False, "grant": ("verify", "Historical")},
    "Host-App": {"label": "RP Host Application", "staff": ("management",), "private": True, "grant": ("host", "RP")},
    "Hist-Host-App": {"label": "HIST Host Application", "staff": ("management",), "private": True, "grant": ("host", "HIST")},
    "Report-Host": {"label": "Host Report", "staff": ("management",), "private": True, "grant": None},
    "Appeal": {"label": "Appeal", "staff": ("hosts", "management"), "private": False, "grant": None},
    "Behavior": {"label": "Player Report", "staff": ("hosts", "management"), "private": False, "grant": None},
    "Commend": {"label": "Commend Request", "staff": ("hosts", "management"), "private": False, "grant": None},
    "Question": {"label": "General Question", "staff": ("hosts", "management"), "private": False, "grant": None},
    "Bug": {"label": "Bug Report / Suggestion", "staff": ("developers", "management"), "private": False, "grant": None},
}

TICKET_VERIFY_PROOF = (
    "• Internet speed test — at least **20 Mb/s down and up**\n"
    "• Hardware specs — a Task Manager (Performance tab) screenshot\n"
    "• Proof you own **all Hearts of Iron IV DLCs**"
)
TICKET_INSTRUCTIONS = {
    "Verification": (
        "**Verification is optional — it only unlocks major nations.** Everyone can join our games and play a minor "
        "nation without it. A major carries most of the game's load, so a crash or lag spike there can end the session "
        "for everyone.\n\n**Post the following here:**\n" + TICKET_VERIFY_PROOF + "\n\nStaff will check it and give you "
        "the role right here."
    ),
    "Hist-Verification": (
        "**Historical Verified unlocks major nations in Historical games.**\n\n**Post the following here:**\n"
        + TICKET_VERIFY_PROOF
        + "\n• A screenshot of your Steam library showing **at least 500 hours** in Hearts of Iron IV\n\n"
        "Staff will check it and give you the role right here."
    ),
    "Host-App": (
        "**Please answer all of these:**\n1. Where are you (EU or elsewhere)?\n2. Hardware specs\n3. A speed test\n"
        "4. Do you own all HOI4 DLCs?\n5. Why do you want to become a host?\n6. Any hosting experience?"
    ),
}
TICKET_INSTRUCTIONS["Hist-Host-App"] = TICKET_INSTRUCTIONS["Host-App"]

_ticket_counter_lock = asyncio.Lock()
_ticket_user_locks: dict[int, asyncio.Lock] = {}
_closing_tickets: set[int] = set()


def _ticket_kind_label(kind: str | None) -> str:
    return (TICKET_KINDS.get(kind or "") or {}).get("label") or str(kind or "Ticket")


def _ticket_role_groups() -> dict[str, list]:
    return {
        "support": list(TICKET_SUPPORT_ROLES),
        "management": list(SENIOR_MANAGEMENT_ROLES),
        "hosts": list(ALLOWED_HOST_ROLES),
        "developers": list(DEVELOPER_ROLES),
    }


def _ticket_staff_roles(kind: str | None, *, for_ping: bool = False) -> list[int]:
    """Role ids that handle a kind of ticket (unknown kinds: Host Management).
    for_ping leaves out "every host" — a reminder pings the managers instead."""
    spec = TICKET_KINDS.get(kind or "") or {"staff": ("management",)}
    groups = _ticket_role_groups()
    out: list[int] = []
    for group in spec["staff"]:
        if for_ping and group == "hosts":
            continue
        for rid in groups[group]:
            if rid and int(rid) not in out:
                out.append(int(rid))
    return out


def _member_handles_ticket(member, kind: str | None) -> bool:
    """Server admins, or a role that handles this kind of ticket."""
    if member is None:
        return False
    try:
        if member.guild_permissions.administrator:
            return True
    except Exception:
        pass
    allowed = set(_ticket_staff_roles(kind))
    return any(role.id in allowed for role in getattr(member, "roles", []))


def _ticket_topic(num: int, kind: str, opener_id: int, *, host_id=None, target_id=None) -> str:
    parts = [f"GameMaster | #{num:04d} | type={kind} | opener={int(opener_id)}"]
    if host_id:
        parts.append(f"host={int(host_id)}")
    if target_id:
        parts.append(f"target={int(target_id)}")
    return " | ".join(parts)


def _parse_ticket_topic(topic) -> dict | None:
    """{kind, opener, host, target} of a ticket channel (also the old ticket bot's)."""
    if not topic or not any(tag in topic for tag in TICKET_TOPIC_TAGS):
        return None
    match = _TICKET_TYPE_RE.search(topic)
    fields = {key: int(value) for key, value in _TICKET_FIELD_RE.findall(topic)}
    if not match or "opener" not in fields:
        return None
    return {"kind": match.group("type").strip(), "opener": fields["opener"], "host": fields.get("host"), "target": fields.get("target")}


def _find_open_ticket(guild, user_id: int, kind: str):
    for channel in getattr(guild, "text_channels", []):
        if not channel.name.startswith("ticket-"):
            continue
        meta = _parse_ticket_topic(channel.topic)
        if meta and meta["opener"] == int(user_id) and meta["kind"].lower() == kind.lower():
            return channel
    return None


async def _next_ticket_number(guild) -> int:
    """Per server; the first one continues after the highest ticket channel there."""
    async with _ticket_counter_lock:
        config = await read_json(BOT_CONFIG_FILE)
        current = config.get(_TICKET_COUNTER_KEY)
        if not isinstance(current, int):
            found = [int(m.group(1)) for ch in getattr(guild, "text_channels", []) if (m := re.match(r"ticket-(\d+)-", ch.name))]
            current = max(found, default=0)
        number = current + 1
        config[_TICKET_COUNTER_KEY] = number
        await write_json(BOT_CONFIG_FILE, config)
        return number


async def _ticket_reply(interaction, content: str, *, view=None) -> None:
    """Ephemeral answer whether or not the interaction was answered already."""
    kwargs = {"content": content, "ephemeral": True}
    if view is not None:
        kwargs["view"] = view
    try:
        if interaction.response.is_done():
            await interaction.followup.send(**kwargs)
        else:
            await interaction.response.send_message(**kwargs)
    except discord.HTTPException as e:
        print(f"[WARN] ticket reply failed: {e}")


async def _ticket_deny_duplicate(interaction, kind: str) -> bool:
    existing = _find_open_ticket(interaction.guild, interaction.user.id, kind) if interaction.guild else None
    if existing is None:
        return False
    await _ticket_reply(
        interaction,
        f"❌ You already have an open **{_ticket_kind_label(kind)}** ticket: {existing.mention}\nPlease continue there.",
    )
    return True


async def _create_ticket(interaction, kind: str, *, fields: dict | None = None, host_id=None, target=None, game_name=None):
    """Make the ticket channel. Returns it, or None (the user was told why)."""
    if not interaction.response.is_done():
        try:
            await interaction.response.defer(ephemeral=True, thinking=True)
        except discord.HTTPException:
            pass
    guild, user = interaction.guild, interaction.user
    if guild is None:
        await _ticket_reply(interaction, "❌ Tickets can only be opened inside the server.")
        return None
    if not _guild_active(guild.id):
        await _ticket_reply(interaction, "❌ GameMaster isn't set up in this server yet.")
        return None
    spec = TICKET_KINDS[kind]
    lock = _ticket_user_locks.setdefault(user.id, asyncio.Lock())
    async with lock:
        existing = _find_open_ticket(guild, user.id, kind)
        if existing is not None:
            await _ticket_reply(interaction, f"❌ You already have an open **{spec['label']}** ticket: {existing.mention}")
            return None
        # A reported host is never pinged into (or shown) the report about them.
        if kind == "Report-Host":
            host_id = None
        number = await _next_ticket_number(guild)
        allow = discord.PermissionOverwrite(
            view_channel=True, send_messages=True, read_message_history=True, attach_files=True, embed_links=True,
        )
        overwrites = {
            guild.default_role: discord.PermissionOverwrite(view_channel=False),
            guild.me: discord.PermissionOverwrite(
                view_channel=True, send_messages=True, read_message_history=True, attach_files=True,
                embed_links=True, manage_channels=True,
            ),
            user: allow,
        }
        for rid in _ticket_staff_roles(kind):
            role = guild.get_role(rid)
            if role is not None:
                overwrites[role] = allow
        if host_id:
            host_member = await _get_member_safe(guild, host_id)
            if host_member is not None:
                overwrites[host_member] = allow  # the game's host always sees the ticket they're pinged in
        if kind == "Report-Host" and target is not None:
            overwrites[target] = discord.PermissionOverwrite(view_channel=False)  # wins over their roles
        category = guild.get_channel(G.TICKET_CATEGORY_ID) if G.TICKET_CATEGORY_ID else None
        if not isinstance(category, discord.CategoryChannel):
            category = None
        name = f"ticket-{number:04d}-{kind.lower()}"
        topic = _ticket_topic(number, kind, user.id, host_id=host_id, target_id=getattr(target, "id", None))
        try:
            channel = await guild.create_text_channel(
                name, category=category, overwrites=overwrites, topic=topic,
                reason=f"{spec['label']} ticket opened by {user}",
            )
        except discord.Forbidden:
            await _ticket_reply(interaction, "❌ I'm not allowed to make the ticket channel (Manage Channels). Please tell staff.")
            return None
        except discord.HTTPException as e:
            print(f"[WARN] ticket channel create failed: {e}")
            await _ticket_reply(interaction, "❌ Discord refused to make the ticket channel — please try again in a moment.")
            return None

    lines = [f"**Player:** {user.mention}"]
    if target is not None:
        lines.append(f"**About:** {target.mention}")
    if game_name:
        lines.append(f"**Game:** {game_name}")
    for label, value in (fields or {}).items():
        if value:
            lines.append(f"**{label}:**\n{value}")
    embed = discord.Embed(title=f"#{number:04d} - {spec['label']}", description="\n".join(lines)[:4000], color=0x2ECC71)
    if TICKET_INSTRUCTIONS.get(kind):
        embed.add_field(name="What to do", value=TICKET_INSTRUCTIONS[kind][:1024], inline=False)
    embed.set_footer(text="Staff: close it with the buttons below when it's done.")
    content = user.mention + (f" | 🔔 Host of that game: <@{host_id}>" if host_id else "")
    try:
        await channel.send(
            content, embed=embed, view=TicketControlView(),
            allowed_mentions=discord.AllowedMentions(users=True, roles=False, everyone=False),
        )
    except discord.HTTPException as e:
        print(f"[WARN] ticket opening message failed in #{channel.name}: {e}")
    await _ticket_reply(interaction, f"✅ Ticket created: {channel.mention}")
    return channel


async def _ticket_grant(channel, closer, meta: dict) -> None:
    """What resolving gives: the Verified role, or the Assistant host role."""
    grant = (TICKET_KINDS.get(meta["kind"]) or {}).get("grant")
    if not grant:
        return
    action, which = grant
    try:
        if action == "verify":
            result = await apply_verification(
                guild=channel.guild, actor=closer, user_id=meta["opener"], track=which, grant=True,
                note=f"Ticket #{channel.name}", ticket_resolve=True,
            )
        else:
            result = await apply_host_tier(
                guild=channel.guild, actor=closer, user_id=meta["opener"], tier=_lowest_host_rank(which),
                note=f"Host application ticket #{channel.name}", branch=which,
            )
        notes = [str(note) for note in result.get("notes") or [] if note]
        await channel.send("✅ " + str(result.get("summary") or "Done.") + ("\n" + "\n".join(notes) if notes else ""))
    except ModerationError as e:
        await channel.send(f"⚠️ {str(e).lstrip('❌ℹ️ ')} — give it by hand on the website's Database page.")
    except Exception as e:
        print(f"[WARN] ticket grant failed in #{channel.name}: {e}")
        await channel.send("⚠️ Couldn't give the role — please give it by hand on the website's Database page.")


async def _ticket_transcript(channel, closer_name: str, status: str, meta: dict | None, why: str | None = None) -> None:
    """HTML transcript to the ticket log (private log for host applications /
    reports) and to the player by DM."""
    try:
        messages = [message async for message in channel.history(limit=None, oldest_first=True)]
    except discord.HTTPException as e:
        print(f"[WARN] ticket history read failed for #{channel.name}: {e}")
        messages = []
    kind = (meta or {}).get("kind")
    parts = [
        "<!DOCTYPE html><html><head><meta charset='UTF-8'>",
        f"<title>{html.escape(channel.name)}</title><style>body{{background:#36393f;color:#dcddde;font-family:sans-serif;"
        "padding:20px}.m{border-bottom:1px solid #40444b;padding:10px}.a{font-weight:bold;color:#fff}"
        ".t{color:#72767d;font-size:.8em}a{color:#00b0f4}</style></head><body>",
        f"<h1>{html.escape(channel.name)}</h1><p>{html.escape(_ticket_kind_label(kind))} · closed by "
        f"<b>{html.escape(closer_name)}</b> · {html.escape(status)}{(' · ' + html.escape(why)) if why else ''}</p>",
    ]
    for message in messages:
        text = html.escape(message.content) if message.content else (
            "<i>[embed]</i>" if message.embeds else "<i>[message text not available]</i>"
        )
        files = "".join(
            f'<br><a href="{html.escape(att.url)}">[file: {html.escape(att.filename)}]</a>' for att in message.attachments
        )
        parts.append(
            f"<div class='m'><span class='t'>{message.created_at.strftime('%Y-%m-%d %H:%M')}</span> "
            f"<span class='a'>{html.escape(message.author.display_name)}</span><br>{text}{files}</div>"
        )
    parts.append("</body></html>")
    data = "".join(parts).encode("utf-8")
    private = bool((TICKET_KINDS.get(kind or "") or {}).get("private"))
    log_id = (G.TICKET_PRIVATE_LOG_CHANNEL_ID if private else G.TICKET_LOG_CHANNEL_ID) or G.TICKET_LOG_CHANNEL_ID
    log_channel = channel.guild.get_channel(log_id) if log_id else None
    if log_channel is not None:
        embed = discord.Embed(title="Ticket closed", color=0xE74C3C if status == "Unresolved" else 0x2ECC71)
        embed.add_field(name="Ticket", value=channel.name)
        embed.add_field(name="Type", value=_ticket_kind_label(kind))
        embed.add_field(name="Closed by", value=closer_name)
        if meta:
            embed.add_field(name="Opened by", value=f"<@{meta['opener']}>")
        if why:
            embed.add_field(name="Why", value=why[:1024], inline=False)
        try:
            await log_channel.send(embed=embed, file=discord.File(io.BytesIO(data), filename=f"{channel.name}.html"))
        except discord.HTTPException as e:
            print(f"[WARN] ticket transcript post failed: {e}")
    if meta:
        opener = await _get_member_safe(channel.guild, meta["opener"])
        if opener is not None:
            try:
                await asyncio.wait_for(
                    opener.send(
                        f"Your ticket **{channel.name}** was closed ({status}). The transcript is attached.",
                        file=discord.File(io.BytesIO(data), filename=f"{channel.name}.html"),
                    ),
                    timeout=10,
                )
            except Exception as e:
                print(f"[WARN] ticket transcript DM failed: {e}")


async def _finish_ticket(channel, closer, status: str, meta: dict | None, *, why: str | None = None, grant: bool = True) -> None:
    """Grant (when resolved), transcript, delete — each step guarded so a
    ticket always closes."""
    if channel.id in _closing_tickets:
        return
    _closing_tickets.add(channel.id)
    try:
        if grant and status == "Resolved" and meta:
            try:
                await asyncio.wait_for(_ticket_grant(channel, closer, meta), timeout=45)
            except Exception as e:
                print(f"[WARN] ticket grant step failed for #{channel.name}: {e}")
        try:
            await asyncio.wait_for(
                _ticket_transcript(channel, getattr(closer, "display_name", str(closer)), status, meta, why), timeout=120,
            )
        except Exception as e:
            print(f"[WARN] ticket transcript failed for #{channel.name}: {e}")
        try:
            await channel.delete(reason=f"Ticket closed ({status}) by {closer}")
        except discord.HTTPException as e:
            print(f"[WARN] ticket channel delete failed for #{channel.name}: {e}")
    finally:
        _closing_tickets.discard(channel.id)


async def _ticket_close_from_interaction(interaction, status: str) -> None:
    channel = interaction.channel
    meta = _parse_ticket_topic(getattr(channel, "topic", None))
    if meta is None or not str(getattr(channel, "name", "")).startswith("ticket-"):
        return await _ticket_reply(interaction, "❌ This channel isn't a ticket.")
    if not _member_handles_ticket(interaction.user, meta["kind"]):
        if meta["opener"] == interaction.user.id:
            return await _ticket_reply(interaction, "❌ You can't close your own ticket — staff will close it.")
        return await _ticket_reply(interaction, "❌ Only the staff who handle this kind of ticket can close it.")
    if channel.id in _closing_tickets:
        return await _ticket_reply(interaction, "⏳ This ticket is already being closed.")
    await _ticket_reply(interaction, f"Closing this ticket as **{status}**…")
    await _finish_ticket(channel, interaction.user, status, meta)


class TicketControlView(discord.ui.View):
    """Close buttons in every ticket (same ids as the old ticket bot, so its
    open tickets keep working)."""

    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="Close & Resolve", style=discord.ButtonStyle.success, emoji="✅", custom_id="hoi4_tick_res")
    async def resolve(self, interaction: discord.Interaction, button: discord.ui.Button):
        await _ticket_close_from_interaction(interaction, "Resolved")

    @discord.ui.button(label="Close (Unresolved)", style=discord.ButtonStyle.danger, emoji="⛔", custom_id="hoi4_tick_unres")
    async def unresolve(self, interaction: discord.Interaction, button: discord.ui.Button):
        await _ticket_close_from_interaction(interaction, "Unresolved")


# ————— Opening a ticket (the panel and its steps) —————

class TicketDetailsModal(discord.ui.Modal):
    """The last step of every flow: what it's about, then the ticket is made."""

    def __init__(self, kind: str, *, title: str, question: str, host_id=None, target=None, game_name=None,
                 sub_topic: str | None = None, short_question: str | None = None):
        super().__init__(title=title[:45], timeout=TICKET_FLOW_TIMEOUT)
        self.kind, self.host_id, self.target, self.game_name, self.sub_topic = kind, host_id, target, game_name, sub_topic
        self.short = None
        if short_question:
            self.short = discord.ui.TextInput(label=short_question[:45], max_length=100, required=True)
            self.add_item(self.short)
        self.details = discord.ui.TextInput(label=question[:45], style=discord.TextStyle.paragraph, max_length=1500, required=True)
        self.add_item(self.details)

    async def on_submit(self, interaction: discord.Interaction):
        fields = {}
        if self.sub_topic:
            fields["Type"] = self.sub_topic
        if self.short is not None:
            fields["Summary"] = self.short.value
        fields["Details"] = self.details.value
        await _create_ticket(
            interaction, self.kind, fields=fields, host_id=self.host_id, target=self.target, game_name=self.game_name,
        )


def _ticket_branches() -> list[str]:
    return [b for b in ("RP", "HIST") if (HOST_BRANCHES.get(b) or {}).get("enabled", True)]


def _ticket_game_branch(mode: str) -> str:
    cfg = MODE_CONFIG.get(mode) or {}
    return cfg.get("branch") or ("HIST" if "Historical" in str(mode or "") else "RP")


async def _ticket_recent_games(branch: str) -> list[dict]:
    """Up to 25 played games of a branch, newest first (last 30 days)."""
    games = await _load_games_resilient()
    since = time.time() - 30 * 86400
    out = []
    for key, game in (games or {}).items():
        if not isinstance(game, collections.abc.Mapping):
            continue
        if _ticket_game_branch(game.get("mode", "")) != branch:
            continue
        started = float(game.get("game_started_at") or game.get("start_timestamp") or 0)
        if started < since or not (game.get("game_started") or game.get("status") == "ended"):
            continue
        out.append({
            "id": str(key),
            "name": str(game.get("thread_name") or game.get("mode") or key).replace(" Reservations", ""),
            "host_id": int(game["host_id"]) if str(game.get("host_id") or "").isdigit() else None,
            "ts": started,
        })
    out.sort(key=lambda entry: entry["ts"], reverse=True)
    return out[:25]


class TicketGameSelect(discord.ui.Select):
    def __init__(self, games: list[dict], next_step):
        self.games, self.next_step = games, next_step
        options = [
            discord.SelectOption(
                label=game["name"][:100], value=str(index), emoji="🎮",
                description=datetime.datetime.fromtimestamp(game["ts"], tz=datetime.timezone.utc).strftime("%d %b %Y %H:%M UTC"),
            )
            for index, game in enumerate(games)
        ]
        super().__init__(placeholder="Which game?", options=options)

    async def callback(self, interaction: discord.Interaction):
        game = self.games[int(self.values[0])]
        await self.next_step(interaction, game)


class TicketGameRouter(discord.ui.View):
    """"Which game is this about?" — a branch, then a recent game (or none)."""

    def __init__(self, next_step):
        super().__init__(timeout=TICKET_FLOW_TIMEOUT)
        self.next_step = next_step
        for branch in _ticket_branches():
            button = discord.ui.Button(
                label="Roleplay game" if branch == "RP" else "Historical game",
                emoji="🎭" if branch == "RP" else "⚔️",
                style=discord.ButtonStyle.primary if branch == "RP" else discord.ButtonStyle.success,
            )
            button.callback = self._picker(branch)
            self.add_item(button)
        none = discord.ui.Button(label="No game / not listed", emoji="❓", style=discord.ButtonStyle.secondary)
        none.callback = self._none
        self.add_item(none)

    def _picker(self, branch: str):
        async def callback(interaction: discord.Interaction):
            games = await _ticket_recent_games(branch)
            if not games:
                return await self.next_step(interaction, None)
            view = discord.ui.View(timeout=TICKET_FLOW_TIMEOUT)
            view.add_item(TicketGameSelect(games, self.next_step))
            await interaction.response.send_message("Pick the game:", view=view, ephemeral=True)
        return callback

    async def _none(self, interaction: discord.Interaction):
        await self.next_step(interaction, None)


class TicketUserPick(discord.ui.View):
    """Pick a member (who the report is about)."""

    def __init__(self, placeholder: str, next_step, *, must_be_host: bool = False):
        super().__init__(timeout=TICKET_FLOW_TIMEOUT)
        self.next_step, self.must_be_host = next_step, must_be_host
        select = discord.ui.UserSelect(placeholder=placeholder)
        select.callback = self._picked
        self.select = select
        self.add_item(select)

    async def _picked(self, interaction: discord.Interaction):
        member = self.select.values[0]
        if member.id == interaction.user.id:
            return await _ticket_reply(interaction, "❌ Pick someone other than yourself.")
        if self.must_be_host and not _member_is_host(member):
            return await _ticket_reply(interaction, "❌ That member isn't a host.")
        await self.next_step(interaction, member)


class TicketChoice(discord.ui.View):
    """A few buttons; each calls next_step(interaction, value)."""

    def __init__(self, choices: list[tuple[str, str, str]], next_step):
        super().__init__(timeout=TICKET_FLOW_TIMEOUT)
        for value, label, emoji in choices:
            button = discord.ui.Button(label=label, emoji=emoji, style=discord.ButtonStyle.primary)

            async def callback(interaction: discord.Interaction, value=value):
                await next_step(interaction, value)
            button.callback = callback
            self.add_item(button)


GAME_SUPPORT_OPTIONS = (
    ("Host-App", "Host application", "🎤"),
    ("Report-Host", "Report a host", "⚠️"),
    ("Appeal", "Appeal a ban or warning", "⚖️"),
    ("Behavior", "Report a player", "😠"),
    ("Commend", "Request a commend", "⭐"),
)


class TicketGameSupportSelect(discord.ui.Select):
    def __init__(self):
        super().__init__(
            placeholder="What do you need?",
            options=[discord.SelectOption(label=label, value=kind, emoji=emoji) for kind, label, emoji in GAME_SUPPORT_OPTIONS],
        )

    async def callback(self, interaction: discord.Interaction):
        await _ticket_game_support(interaction, self.values[0])


async def _ticket_game_support(interaction: discord.Interaction, choice: str) -> None:
    if choice == "Host-App":
        async def branch_picked(inter, branch):
            kind = "Host-App" if branch == "RP" else "Hist-Host-App"
            if await _ticket_deny_duplicate(inter, kind):
                return
            await _create_ticket(inter, kind)
        branches = _ticket_branches()
        if len(branches) == 1:
            return await branch_picked(interaction, branches[0])
        choices = [(b, "Roleplay (RP) host" if b == "RP" else "Historical (HIST) host", "🎭" if b == "RP" else "⚔️") for b in branches]
        return await interaction.response.send_message("Which branch do you want to host?", view=TicketChoice(choices, branch_picked), ephemeral=True)

    if await _ticket_deny_duplicate(interaction, choice):
        return

    async def game_picked(inter, game):
        game_name = game["name"] if game else None
        host_id = game["host_id"] if game else None
        if choice == "Report-Host":
            async def host_picked(i2, member):
                await i2.response.send_modal(TicketDetailsModal(
                    "Report-Host", title="Report a host", question="What happened?", target=member, game_name=game_name,
                ))
            return await inter.response.send_message(
                "Which host is this about?", view=TicketUserPick("Pick the host…", host_picked, must_be_host=True), ephemeral=True,
            )
        if choice == "Appeal":
            return await inter.response.send_modal(TicketDetailsModal(
                "Appeal", title="Appeal a ban or warning", question="What are you appealing, and why?",
                host_id=host_id, game_name=game_name,
            ))
        if choice == "Commend":
            async def type_picked(i2, review):
                await i2.response.send_modal(TicketDetailsModal(
                    "Commend", title=f"Request: {review}", question="Why do you deserve it?", host_id=host_id,
                    game_name=game_name, sub_topic=review,
                ))
            return await inter.response.send_message(
                "Which commend?",
                view=TicketChoice([("RP Review", "RP review", "🎭"), ("Sportsmanship Review", "Sportsmanship", "🤝")], type_picked),
                ephemeral=True,
            )
        # Behavior: who, what kind, then the evidence.
        async def player_picked(i2, member):
            async def behaviour_picked(i3, behaviour):
                await i3.response.send_modal(TicketDetailsModal(
                    "Behavior", title=f"Report: {behaviour}", question="Evidence (what happened, screenshots after)",
                    host_id=host_id, target=member, game_name=game_name, sub_topic=behaviour,
                ))
            await i2.response.send_message(
                "What kind of behaviour?",
                view=TicketChoice(
                    [("Rule break", "Rule break", "📜"), ("Trolling", "Trolling", "🤡"), ("Toxic", "Toxic", "☣️"), ("Lack of RP", "Lack of RP", "🎭")],
                    behaviour_picked,
                ),
                ephemeral=True,
            )
        await inter.response.send_message("Who is this about?", view=TicketUserPick("Pick the player…", player_picked), ephemeral=True)

    await interaction.response.send_message("Which game is this about?", view=TicketGameRouter(game_picked), ephemeral=True)


