async def _roster_dm_host_override(game: dict, actor, target, slot_label: str, kind: str, last: str) -> None:
    """Tell the game's host that a player was force-added past a warning."""
    try:
        host = await _web_fetch_member(int(game.get("host_id") or 0))
        if host is None:
            return
        if kind == "major":
            text = (
                f"⚠️ **Major Streak Override**\n{actor.mention} added {target.mention} "
                f"(**{target.display_name}**) to **{slot_label}** in your game, even though they "
                f"recently played a Major (**{last}**) and were due to play a Minor."
            )
        else:
            played = f"(**{last}**)" if last else "the same Minor"
            text = (
                f"⚠️ **Minor Repeat Override**\n{actor.mention} added {target.mention} "
                f"(**{target.display_name}**) to **{slot_label}** in your game, even though they most "
                f"recently played this same Minor {played} and shouldn't take it twice in a row."
            )
        await _dm_user_safe(host, content=text, label="roster override")
    except Exception as e:
        print(f"[WARN] roster: host override DM failed: {e}")


def _roster_notify_on(payload: dict) -> bool:
    """Host Tool → Notify players: DM the players a change touches. Requests
    from before the switch (no "notify" key) count as on."""
    return (payload or {}).get("notify") is not False


async def _roster_notify_player(member, game: dict, game_key, actor, *, title: str, text: str,
                                color: discord.Color, label: str) -> bool:
    """One Host Tool change, as a DM: what happened, which game, who did it,
    and a button to the map. Hosts aren't DMed about their own moves."""
    if member is None or (actor is not None and getattr(member, "id", None) == getattr(actor, "id", None)):
        return False
    mode = str((game or {}).get("mode") or "Game")
    embed = discord.Embed(title=title, description=text, color=color)
    ts = int((game or {}).get("start_timestamp") or 0)
    when = f" · <t:{ts}:F>" if ts > 0 else ""
    embed.add_field(name="Game", value=f"{MODE_THREAD_LABELS.get(mode, mode)}{when}", inline=False)
    who = getattr(actor, "display_name", None)
    embed.set_footer(text=f"Changed by {who} with the Host Tool" if who else "Changed by the host")
    view = discord.ui.View()
    view.add_item(discord.ui.Button(label="Open the map", url=_map_game_url(game_key), style=discord.ButtonStyle.link))
    return await _dm_user_safe(member, embed=embed, view=view, label=label)


def _roster_payload_ids(payload: dict):
    """(thread_id, user_id) of a roster request, or an error message."""
    thread_id = str(payload.get("thread_id") or "").strip()
    if not thread_id.isdigit():
        return None, None, "❌ Invalid game."
    try:
        user_id = int(payload.get("user_id"))
    except (TypeError, ValueError):
        return None, None, "❌ Invalid player."
    if user_id <= 0:
        return None, None, "❌ Invalid player."
    return thread_id, user_id, None


async def _roster_after_change(thread_id: str) -> None:
    schedule_reservation_update(int(thread_id))
    schedule_participation_tracker_update(thread_id)
    schedule_log_update(int(thread_id))


async def _roster_drop_player_state(thread_id: str, user_id: int) -> None:
    """What /remove did besides the reservation: flip the casino receipt log
    red and clear the player's web run so a new /gamble link starts clean."""
    try:
        await _mark_receipt_log_unreserved(int(thread_id), user_id)
    except Exception as e:
        print(f"[WARN] roster: receipt log update failed: {e}")
    try:
        await _run_mysql_io(
            _purge_web_session_mysql, int(thread_id), user_id,
            label="web session purge (web host remove)",
        )
    except Exception as e:
        print(f"[WARN] roster: web session purge failed: {e}")


async def _process_web_roster_assign(req: dict):
    """Put a player on a nation, co-op slot or filler (formerly /add,
    /add_coop, /add_filler). A taken nation needs occupied='swap' (the other
    player takes the mover's old slot) or 'replace' (they're removed)."""
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if not _member_is_host(actor):
        return False, None, "❌ Only members with a Host role can manage players."
    thread_id, user_id, err = _roster_payload_ids(payload)
    if err:
        return False, None, err
    kind = str(payload.get("kind") or "")
    if kind not in ("nation", "coop", "filler"):
        return False, None, "❌ Invalid slot type."
    occupied = payload.get("occupied")
    force = bool(payload.get("force"))
    notify = _roster_notify_on(payload)
    nation = str(payload.get("nation") or "").strip()

    games_data = await _read_games_fresh()
    game = games_data.get(thread_id)
    if not isinstance(game, dict):
        return False, None, "❌ This game no longer exists."
    if game.get("status") in ("ended", "cancelled"):
        return False, None, "❌ This game has ended."
    target = await _web_fetch_member(user_id)
    if target is None:
        return False, None, "❌ That player is no longer in the server."
    mode = game.get("mode", "")
    if not await is_user_authenticated(target, int(thread_id)):
        return False, None, f"🔒 {target.display_name} isn't Steam verified via LegionMaster yet."

    res = game.get("reservations") or {}
    if kind == "nation":
        if mode != "Other" and nation not in _roster_valid_nations(mode):
            return False, None, f"❌ '{nation}' isn't a nation in {mode}."
        key = nation
    elif kind == "coop":
        if nation not in res:
            return False, None, f"❌ **{nation}** must be reserved before it can get a co-op."
        coop_major = nation in get_major_nations_for_mode(mode)
        if mode == "Other" or not coop_major:
            return False, None, "❌ Co-op slots are only for major nations."
        coop_keys = [
            f"{nation}_coop" if index == 1 else f"{nation}_coop_{index}"
            for index in range(1, WEB_ROSTER_MAX_COOP_SLOTS + 1)
        ]
        key = next((k for k in coop_keys if str(res.get(k)) == str(user_id)), None) or next(
            (k for k in coop_keys if k not in res), None
        )
        if key is None:
            return False, None, f"❌ All {WEB_ROSTER_MAX_COOP_SLOTS} co-op slots for **{nation}** are taken."
    else:
        filler_name = str(payload.get("filler_name") or "").strip()[:40]
        if not filler_name:
            return False, None, "❌ Give the filler a name."
        key = f"_FILL_{filler_name.replace(' ', '_')}"
        if key in res and str(res[key]) != str(user_id):
            if "Filler" not in filler_name:
                return False, None, f"❌ **{filler_name}** is already on the list — use a different name."
            key = next((f"{key}_{i}" for i in range(1, 50) if f"{key}_{i}" not in res), None)
            if key is None:
                return False, None, "❌ Too many fillers with that name."

    current_key = _roster_slot_of(res, user_id)
    if current_key == key:
        return True, {"slot_key": key, "unchanged": True}, None
    occupant = res.get(key) if kind == "nation" else None
    if occupant is not None and str(occupant) == str(user_id):
        occupant = None
    if occupant is not None and occupied not in ("swap", "replace"):
        return False, None, f"❌ **{nation}** is already taken — choose swap or replace."

    nation_is_major = False
    if kind != "filler":
        try:
            nation_is_major = is_major(nation, mode)
        except Exception:
            nation_is_major = False
    override_kind = None
    last_played = ""
    if kind == "coop":
        if _is_on_major_cooldown(games_data, user_id, mode, thread_id) and not _member_has_vip(target):
            override_kind = "major"
            last_played = _last_major_nation(games_data, user_id, mode, thread_id)
    elif kind == "nation":
        if nation_is_major and _is_on_major_cooldown(games_data, user_id, mode, thread_id) and not _member_has_vip(target):
            override_kind = "major"
            last_played = _last_major_nation(games_data, user_id, mode, thread_id)
        elif (not nation_is_major) and _is_minor_repeat(games_data, user_id, mode, nation, thread_id) and not _member_has_vip(target):
            override_kind = "minor"
            last_played = _last_participated_nation_in_mode(games_data, user_id, mode, thread_id)

    if not force:
        warnings = []
        if kind == "nation":
            stats = (get_cached_player_stats() or await read_json(PLAYER_STATS_FILE) or {}).get(str(user_id), {})
            dish_reason = await _dishonored_block_for_member(target, mode, nation, nation_is_major, stats=stats)
            if dish_reason:
                warnings.append(f"Dishonored Title would normally block this: {dish_reason}")
        if override_kind == "major":
            warnings.append(f"{target.display_name} recently played Major {last_played} and was due a Minor.")
        elif override_kind == "minor":
            warnings.append(
                f"{target.display_name} played {last_played} in their last {mode} game "
                "(no same Minor twice in a row)."
            )
        if warnings:
            return WEB_REQUEST_CONFIRM, {"warnings": warnings}, None

    # A running game: the late-join flow (Gamer Pass + a voice channel, marked
    # late on the attendance roster) — formerly /late_join.
    if game.get("game_started") and kind in ("nation", "filler"):
        if occupant is not None:
            return False, None, (
                f"❌ **{nation}** is taken — remove that player first (a late join can't swap or replace)."
            )
        ok, summary = await _execute_late_join(bot.get_guild(cur_gid()), thread_id, target, key, join_label="Late Join")
        if not ok:
            return False, None, summary
        label = _pretty_reservation_name(key)
        if notify:
            await _roster_notify_player(
                target, game, thread_id, actor,
                title="🎮 Added to a running game",
                text=(
                    f"**{actor.display_name}** added you to the running game as **{label}**"
                    + (f" (you were on **{_pretty_reservation_name(current_key)}**)" if current_key else "")
                    + ". You have the Gamer Pass, so hop into your voice channel."
                ),
                color=discord.Color.orange(), label="late join",
            )
            if kind != "filler":
                await _roster_send_mode_info_dm(target, mode, nation)
        if force and override_kind:
            await _roster_dm_host_override(game, actor, target, label, override_kind, last_played)
        _audit_log("INFO", f"web late join thread={thread_id} by={actor.id} user={user_id} slot={key} from={current_key}")
        return True, {"slot_key": key, "moved_from": current_key, "displaced": None, "late_join": True}, None

    # Apply on a fresh read: the board may have changed while we checked.
    games_data = await _read_games_fresh()
    game = games_data.get(thread_id)
    if not isinstance(game, dict):
        return False, None, "❌ This game no longer exists."
    res = game.get("reservations") or {}
    fresh_holder = res.get(key)
    if fresh_holder is not None and str(fresh_holder) == str(user_id):
        fresh_holder = None
    if _roster_slot_of(res, user_id) != current_key or str(fresh_holder) != str(occupant):
        return False, None, "❌ The board changed while this was being checked — try again."
    for stale in [k for k, v in res.items() if str(v) == str(user_id)]:
        del res[stale]
    swapped_to = None
    if occupant is not None:
        del res[key]
        if occupied == "swap" and current_key and current_key not in res:
            res[current_key] = occupant
            swapped_to = current_key
    res[key] = user_id
    game["reservations"] = res
    # Draft games: a host placing a pooled player takes them out of the pool
    # (the host can place anyone at any time; captains' turns are unchanged).
    left_pool = _is_draft_game(game) and game["draft"].get("pool", {}).pop(str(user_id), None) is not None
    if left_pool:
        _draft_log(game["draft"], kind="host_place", user_id=str(user_id), slot=key, team=None, by=str(actor.id))
        _draft_check_complete(game)
    await save_single_game(thread_id, game, rewrite_reservations=True)
    await _roster_after_change(thread_id)
    if left_pool:
        await update_draft_pool_message(int(thread_id))
    if occupant is not None and swapped_to is None:
        await _roster_drop_player_state(thread_id, int(occupant))

    label = _pretty_reservation_name(key)
    displaced = await _web_fetch_member(int(occupant)) if occupant is not None else None
    if notify:
        by = f"**{actor.display_name}**"
        other = f"**{displaced.display_name}**" if displaced is not None else "the other player"
        if swapped_to:
            title, color = "🔁 Your slot was swapped", discord.Color.blurple()
            text = f"{by} swapped you with {other}: you're now **{label}** (you were on **{_pretty_reservation_name(current_key)}**)."
        elif current_key:
            title, color = "🔄 You were moved", discord.Color.blurple()
            text = f"{by} moved you from **{_pretty_reservation_name(current_key)}** to **{label}**."
        else:
            title, color = "📋 You were added to a game", discord.Color.green()
            text = f"{by} added you to the game as **{label}**."
        if occupant is not None and not swapped_to:
            text += f" {other} was taken off that slot."
        await _roster_notify_player(target, game, thread_id, actor, title=title, text=text, color=color, label="roster change")
        if kind != "filler":
            await _roster_send_mode_info_dm(target, mode, nation)
        if displaced is not None:
            if swapped_to:
                await _roster_notify_player(
                    displaced, game, thread_id, actor,
                    title="🔁 Your slot was swapped",
                    text=(
                        f"{by} swapped you with **{target.display_name}**: you're now "
                        f"**{_pretty_reservation_name(swapped_to)}** (you were on **{label}**)."
                    ),
                    color=discord.Color.blurple(), label="roster displaced",
                )
            else:
                await _roster_notify_player(
                    displaced, game, thread_id, actor,
                    title="🚫 You were removed from a game",
                    text=f"{by} gave **{label}** to **{target.display_name}**, so you're no longer in this game.",
                    color=discord.Color.red(), label="roster displaced",
                )
    if force and override_kind:
        await _roster_dm_host_override(game, actor, target, label, override_kind, last_played)
    _audit_log(
        "INFO",
        f"web roster assign thread={thread_id} by={actor.id} user={user_id} slot={key} "
        f"from={current_key} displaced={occupant} swapped_to={swapped_to} forced={force} notified={notify}",
    )
    return True, {"slot_key": key, "moved_from": current_key, "displaced": str(occupant) if occupant else None}, None


async def _process_web_roster_remove(req: dict):
    """Take a player off the game (formerly /remove)."""
    payload = req.get("payload") or {}
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if not _member_is_host(actor):
        return False, None, "❌ Only members with a Host role can manage players."
    thread_id, user_id, err = _roster_payload_ids(payload)
    if err:
        return False, None, err
    games_data = await _read_games_fresh()
    game = games_data.get(thread_id)
    if not isinstance(game, dict):
        return False, None, "❌ This game no longer exists."
    res = game.get("reservations") or {}
    keys = [k for k, v in res.items() if str(v) == str(user_id)]
    if not keys:
        return True, {"removed": None}, None
    for key in keys:
        del res[key]
    game["reservations"] = res
    await save_single_game(thread_id, game, rewrite_reservations=True)
    await _roster_after_change(thread_id)
    await _roster_drop_player_state(thread_id, user_id)
    if _roster_notify_on(payload):
        await _roster_notify_player(
            await _web_fetch_member(user_id), game, thread_id, actor,
            title="🚫 You were removed from a game",
            text=f"**{actor.display_name}** removed you from **{_pretty_reservation_name(keys[0])}**.",
            color=discord.Color.red(), label="roster remove",
        )
    _audit_log("INFO", f"web roster remove thread={thread_id} by={actor.id} user={user_id} slots={keys}")
    return True, {"removed": keys[0]}, None


# ————— Host Override Panel sync (Phase 4) —————
# The web /host/override panel writes host_override_requests rows. This loop:
#   · action 'dm'    → mints a single-use web token and DMs the override link
#                      to the target player.
#   · action 'apply' → merges host-executed roll results back into the game
#                      data (fresh = full overwrite + reservation; partial =
#                      only the newly rolled module fields).
#   · action 'execute' rows are handled synchronously by the web API (it mints
#     the web token itself); they arrive here with dirty=0 and are skipped.
HOST_OVERRIDE_SYNC_INTERVAL_SEC = 10


def _fetch_dirty_override_requests() -> list:
    conn = None
    cursor = None
    try:
        conn = _db_get_connection()
        cursor = conn.cursor(dictionary=True)
        cursor.execute(
            "SELECT request_id, game_id, target_user_id, host_user_id, mode, action, payload "
            "FROM host_override_requests WHERE dirty = 1"
        )
        out = []
        for row in cursor.fetchall():
            entry = dict(row)
            entry["payload"] = _parse_mysql_json(row.get("payload")) or {}
            out.append(entry)
        return out
    except Exception as e:
        print(f"[WARN] Could not read host_override_requests: {e}")
        return []
    finally:
        if cursor is not None:
            try:
                cursor.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _mark_override_request_processed(request_id: str) -> None:
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        cur.execute(
            "UPDATE host_override_requests SET dirty = 0, processed_at = %s WHERE request_id = %s",
            (int(time.time()), str(request_id)),
        )
        conn.commit()
    except Exception as e:
        print(f"[WARN] Could not mark override request processed: {e}")
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


async def _handle_override_dm_request(row: dict) -> None:
    """Mint a single-use web token for the target player and DM the override
    link (config payload embedded via `?config=`)."""
    game_id = str(row.get("game_id") or "")
    target_uid = int(row.get("target_user_id") or 0)
    payload = row.get("payload") or {}
    if not target_uid:
        return
    guild = bot.get_guild(cur_gid())
    if not guild:
        return
    try:
        member = guild.get_member(target_uid) or await guild.fetch_member(target_uid)
    except Exception as e:
        print(f"[WARN] Override DM: could not resolve member {target_uid}: {e}")
        return

    username, is_banned = _member_identity_flags(member)
    roles = _live_role_flags(member)
    config_payload = dict(payload.get("config") or {})
    config_payload.setdefault("gameId", game_id)
    config_payload.setdefault("overrideTarget", str(target_uid))
    # The FULL config payload rides along as JSON on the token row so
    # /api/access can compute the grant entry stage + re-roll allowances.
    grant_config = json.dumps(config_payload, ensure_ascii=False)
    web_token = await _generate_web_access_token(
        target_uid,
        can_roll_majors=roles["can_roll_majors"],
        role_tier=roles["role_tier"],
        game_id=str(game_id),
        username=username,
        is_vip=roles["is_vip"],
        is_trusted=roles["is_trusted"],
        is_verified=roles["is_verified"],
        is_authenticated=roles["is_authenticated"],
        is_banned=is_banned,
        # HOST OVERRIDE GRANT: /api/access must NOT route this link to
        # Stage 5 (the target's session may be FINALIZED) — the override
        # config in the URL drives the stage instead.
        is_grant=True,
        grant_config=grant_config,
    )
    config_payload = dict(payload.get("config") or {})
    config_payload.setdefault("gameId", game_id)
    config_payload.setdefault("overrideTarget", str(target_uid))
    raw = json.dumps(config_payload, ensure_ascii=False, separators=(",", ":"))
    encoded = base64.urlsafe_b64encode(raw.encode("utf-8")).decode("ascii").rstrip("=")
    url = f"{BASE_URL}/?token={web_token}&config={encoded}"

    embed = discord.Embed(
        title="🛠️ Host Override Roll",
        description=(
            "A host issued a custom roll for your session — press the button below to open it.\n\n"
            f"*Single-use link · expires in {WEB_ACCESS_TOKEN_TTL_SEC}s · open it immediately.*"
        ),
        color=0x1a1a2e,
    )
    view = discord.ui.View()
    view.add_item(
        discord.ui.Button(
            label="Open Override Roll",
            style=discord.ButtonStyle.link,
            url=url,
            emoji="🎲",
        )
    )
    await _dm_user_safe(member, embed=embed, view=view, label="host override link")


async def _log_host_override_receipt(
    member, game: dict, thread_id, chosen: str, roll_like: dict, rtype, merged: dict
) -> None:
    """Phase 4 receipt logging for host-executed overrides — DMs the TARGET
    player and posts/updates the green log-channel embed (same contract as
    Phase 3, but without an interaction object)."""
    user_id = member.id
    mode = game.get("mode", "")
    receipt_url = _build_house_receipt_url(thread_id, user_id, chosen, roll_like, rtype, mode)
    rules_summary = _receipt_rules_summary(roll_like, rtype)
    flag = roll_like.get("flag") or "🏳️"

    dm_embed = discord.Embed(
        title="🧾 House Receipt — Host Override",
        description=(
            f"**Nation:** {flag} {chosen}\n"
            f"{rules_summary}\n\n"
            f"🔗 **Static receipt:** {receipt_url}\n"
            "*Issued via host override — keep it for your records.*"
        ),
        color=0x22c55e,
    )
    print(f"[DM] Attempting DM to user_id={user_id}")
    dm_user = await _resolve_dm_target(user_id, preferred=member)
    if dm_user is None:
        print(f"[DM] Failed to send DM to {user_id}: could not resolve Discord user")
    else:
        try:
            await dm_user.send(embed=dm_embed)
            print(f"[DM] Successfully sent receipt DM to {user_id}")
            # RECEIPT-DM DEDUPE — the override receipt was just DM'd, so
            # the web enqueue endpoints must not re-DM on later receipt
            # link mounts.
            await _run_mysql_io(
                _set_session_receipt_dm_sent, str(thread_id), user_id, True,
                label="receipt dm sent flag",
            )
        except discord.Forbidden as err:
            print(f"[DM] Failed to send DM to {user_id} (DMs closed): {err}")
        except Exception as err:
            print(f"[DM] Failed to send DM to {user_id}: {err}")

    # MANDATORY AUDIT MIRROR — a host override is a MODIFIED run → the
    # shared helper EDITS the previously persisted audit message in place
    # and flips it RED ([AUDIT LOG] CASINO RECEIPT — MODIFIED / OVERRIDE).
    modules = {
        "ideology": (
            f"{roll_like['ideology'][1]} {roll_like['ideology'][0]}"
            if roll_like.get("ideology") else merged.get("ideology")
        ),
        "path": (
            roll_like["path"]["name"]
            if roll_like.get("path") else merged.get("path")
        ),
        "build": (
            merged.get("build")
            or (format_build_slots(roll_like["rocket"]) if roll_like.get("rocket") else None)
        ),
        "doctrine": merged.get("doctrine"),
        "achievements": (
            merged.get("achievement")
            or (str(roll_like["achievement"]) if roll_like.get("achievement") else None)
        ),
    }
    username = getattr(member, "display_name", None) or getattr(member, "name", None)
    message_id = await _post_or_edit_receipt_audit(
        user_id=user_id,
        thread_id=thread_id,
        nation=f"{flag} {chosen}",
        modules=modules,
        receipt_url=receipt_url,
        modified=True,
        username=username,
        footer_text=f"Mode: {mode} · Host Override",
    )

    receipt_ids = game.get("receipt_log_ids")
    if not isinstance(receipt_ids, dict):
        receipt_ids = {}
    receipt_ids[str(user_id)] = int(message_id) if message_id else None
    game["receipt_log_ids"] = receipt_ids


async def _handle_override_apply_request(row: dict) -> None:
    """Merge host-executed roll results into the game data.

    mode 'fresh'   → assign the rolled nation to the target (replacing any
                     prior reservation) and overwrite their stored roll.
    mode 'partial' → update ONLY the module fields present in the results,
                     preserving every un-rolled field on the receipt."""
    game_id = str(row.get("game_id") or "")
    target_uid = int(row.get("target_user_id") or 0)
    mode = str(row.get("mode") or "fresh")
    payload = row.get("payload") or {}
    results = payload.get("results") or {}
    if not game_id or not target_uid:
        return

    games_data = await read_json(GAMES_FILE)
    storage_key, game = _find_game_entry(games_data, game_id)
    if not game:
        print(f"[WARN] Override apply: game {game_id} not found.")
        return

    nation = results.get("nation")
    ideology = results.get("ideology")
    path = results.get("path")

    reservations = dict(game.get("reservations") or {})
    if mode == "fresh":
        # Drop any prior reservation held by the target, then assign the roll.
        for nat, uid in list(reservations.items()):
            if str(uid) == str(target_uid):
                del reservations[nat]
        if nation:
            reservations[str(nation)] = int(target_uid)
        game["reservations"] = reservations

        store = dict(game.get("randomizer_last_roll") or {})
        if nation:
            store[str(target_uid)] = {
                "nation": _randomizer_last_roll_nation_key(nation),
                "ideology": ideology or "",
                "path": path,
            }
        else:
            store.pop(str(target_uid), None)
        game["randomizer_last_roll"] = store
        web_rolls = dict(game.get("web_override_rolls") or {})
        web_rolls[str(target_uid)] = {}
    else:
        # Partial — merge only the fields present in the results.
        store = dict(game.get("randomizer_last_roll") or {})
        entry = dict(store.get(str(target_uid)) or {})
        if nation:
            entry["nation"] = _randomizer_last_roll_nation_key(nation)
        if ideology:
            entry["ideology"] = ideology
        if path:
            entry["path"] = path
        store[str(target_uid)] = entry
        game["randomizer_last_roll"] = store

    web_rolls = dict(game.get("web_override_rolls") or {})
    merged = dict(web_rolls.get(str(target_uid)) or {})
    for key in ("nation", "ideology", "path", "build", "doctrine", "achievement"):
        value = results.get(key)
        if value:
            merged[key] = value
    web_rolls[str(target_uid)] = merged
    game["web_override_rolls"] = web_rolls

    await write_json(GAMES_FILE, games_data)
    try:
        schedule_reservation_update(int(game_id))
    except Exception:
        pass

    # Receipt logging (DM target + green log embed + message id persistence).
    guild = bot.get_guild(cur_gid())
    member = None
    if guild:
        try:
            member = guild.get_member(target_uid) or await guild.fetch_member(target_uid)
        except Exception:
            member = None
    if member is None:
        return
    chosen = nation or next(
        (n for n, uid in reservations.items() if str(uid) == str(target_uid)), None
    ) or "N/A"
    rtype = game.get("randomizer_type") or "all"
    roll_like = {
        "flag": NATION_FLAGS.get(chosen, "🏳️"),
        "ideology": _ideology_tuple(ideology) if ideology else None,
        "path": {"name": path} if path else None,
        "rocket": None,
    }
    await _log_host_override_receipt(member, game, game_id, chosen, roll_like, rtype, merged)


@tasks.loop(seconds=HOST_OVERRIDE_SYNC_INTERVAL_SEC)
async def host_override_sync_loop():
    """Poll dirty host_override_requests: DM override links to players and
    apply host-executed roll results back into the game data."""
    try:
        rows = await _run_mysql_io(
            _fetch_dirty_override_requests, label="override requests read"
        )
        for row in rows or []:
            request_id = str(row.get("request_id") or "")
            action = str(row.get("action") or "none")
            if not request_id:
                continue
            try:
                if action == "dm":
                    await _handle_override_dm_request(row)
                elif action == "apply":
                    await _handle_override_apply_request(row)
            except Exception as handler_err:
                print(f"[WARN] host override handler failed ({action}): {handler_err}")
            finally:
                try:
                    await _run_mysql_io(
                        _mark_override_request_processed, request_id,
                        label="override request processed",
                    )
                except Exception as mark_err:
                    print(f"[WARN] override processed flag failed: {mark_err}")
    except Exception as e:
        print(f"⚠️ host_override_sync_loop error: {e}")


async def before_host_override_sync_loop():
    await bot.wait_until_ready()


@tasks.loop(minutes=15)
async def player_stats_cache_refresh():
    """Runs once per active server (_player_stats_cache_refresh_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_player_stats_cache_refresh_for_guild, "player_stats_cache_refresh")


async def _player_stats_cache_refresh_for_guild():
    await _refresh_player_stats_cache()
    guild = bot.get_guild(cur_gid())
    if not guild:
        return
    for uid, stats in list((get_cached_player_stats() or {}).items()):
        if not isinstance(stats, dict) or not stats.get("dishonored"):
            continue
        if _has_active_dishonored(stats):
            continue
        stats["dishonored"] = False
        try:
            await save_mysql_player_stats(str(uid), stats)
            member = guild.get_member(int(uid)) if str(uid).isdigit() else None
            if member:
                await _sync_dishonored_role(member, stats)
        except Exception as e:
            print(f"[WARN] Dishonored sentence expiry sync failed for {uid}: {e}")

@player_stats_cache_refresh.before_loop
async def before_player_stats_cache_refresh():
    await _wait_ready_staggered(20)


def _trim_field(text: str, limit: int = 1024) -> str:
    if not text:
        return "None"
    if len(text) <= limit:
        return text
    return text[: limit - 15] + "\n… (truncated)"


def _host_tier_for_member(member: discord.Member, game_cfg: dict) -> str:
    """Which tier role (if any) this member currently holds for one game."""
    held_ids = {r.id for r in member.roles}
    # Highest rank wins if someone holds two.
    for tier_name, role_id in reversed(list(game_cfg["host_tiers"].items())):
        if role_id and role_id in held_ids:
            return tier_name
    return "None"


def _host_rank(member, branch: str) -> str:
    """A member's rank in one host branch ("None" if they're not in it)."""
    if member is None or branch not in HOST_BRANCHES:
        return "None"
    return _host_tier_for_member(member, {"host_tiers": HOST_BRANCHES[branch]["ranks"]})


def _host_branches_of(member) -> list:
    """The host branches a member is in (staff count as both)."""
    if member is None:
        return []
    if _member_is_staff(member):
        return list(HOST_BRANCHES)
    return [branch for branch in HOST_BRANCHES if _host_rank(member, branch) != "None"]


def _host_branch_for_mode(mode) -> str:
    """RP for Roleplay games, HIST for Historical games (same split as the
    Trusted / Verified roles: the mode's Trusted role decides)."""
    name = MODE_NAME_ALIASES.get(str(mode or ""), str(mode or ""))
    cfg = MODE_CONFIG.get(name) or {}
    if cfg.get("branch") in ("RP", "HIST"):
        return cfg["branch"]
    if cfg.get("trusted_role_id") == ROLE_IDS["HOI4_MP_TRUSTED"]:
        return "HIST"
    if cfg:
        return "RP"
    return "HIST" if "Historical" in name else "RP"


def _can_host_mode(member, mode) -> bool:
    """Hosts host only their own branch's games; staff host anything. Until
    a branch's roles exist, any host may host it."""
    if member is None or not _member_is_host(member):
        return False
    if _member_is_staff(member):
        return True
    branch = _host_branch_for_mode(mode)
    if not any(HOST_BRANCHES[branch]["ranks"].values()):
        return True
    return _host_rank(member, branch) != "None"


def _host_branch_refusal(member, mode, *, who: str = "You") -> str:
    branch = _host_branch_for_mode(mode)
    kind = "Roleplay" if branch == "RP" else "Historical"
    return f"❌ {mode} is a {kind} game — {who} need{'' if who == 'You' else 's'} an {branch} host rank (or Host Management) to host it."


ROLE_SCAN_LAST_KEY = "web_role_scan_last"  # bot_config: the last preview and the last applied run
ROLE_SCAN_DAILY_TIME_UTC = datetime.time(hour=4, minute=0, tzinfo=datetime.timezone.utc)
ROLE_SCAN_MAX_CHANGES = 400
ROLE_SCAN_CHANGE_KINDS = (
    "trusted_add", "trusted_remove", "valor_add", "valor_remove", "dishonored_add", "dishonored_remove", "record",
)


async def _run_role_verification_scan(*, apply: bool = True, trigger: str = "manual", actor_id=None):
    """Cross-check the statistics-backed roles of every relevant member:
    Trusted (5+ commends / VIP / Valor pick, with that game type's Verified
    role and no game ban), Hearts of Valor, Dishonored, and the database's
    Verified / host-tier flags (Discord roles are the truth for those).

    apply=False is a preview: nothing changes on Discord or in the database;
    the result lists what an apply run would do. Returns
    {members_checked, members_scanned, changes, counts, errors, applied, ...}
    or None when the guild is unavailable."""
    guild = bot.get_guild(cur_gid())
    if not guild:
        try:
            guild = await bot.fetch_guild(cur_gid())
        except Exception as e:
            print(f"⚠️ Role audit skipped: guild unavailable ({e}).")
            return None

    try:
        if hasattr(guild, "chunk"):
            await guild.chunk(cache=True)
    except Exception as e:
        print(f"⚠️ Role audit: guild chunk failed: {e}")

    try:
        await _refresh_player_stats_cache()
    except Exception as e:
        print(f"⚠️ Role scan stats refresh failed; using warm cache ({e}).")
    player_stats = get_cached_player_stats()
    if not player_stats:
        player_stats = await read_json(PLAYER_STATS_FILE)

    # Only bother inspecting members who hold at least one role we care about,
    # OR who have Merit/Dishonored state in the database that needs role sync.
    watched_role_ids = {ROLE_IDS["VALOR"], *_dishonored_role_ids()}
    for cfg in GAME_ROLE_CONFIG.values():
        watched_role_ids.add(cfg["verified_role_id"])
        watched_role_ids.update(rid for rid in cfg["verified_roles"].values() if rid)
        watched_role_ids.update(cfg["trusted_roles"].keys())
        watched_role_ids.update(cfg["host_tiers"].values())
    for branch_cfg in HOST_BRANCHES.values():
        watched_role_ids.update(rid for rid in branch_cfg["ranks"].values() if rid)

    db_sync_uids = set()
    for uid, st in (player_stats or {}).items():
        if not isinstance(st, dict):
            continue
        if int(st.get("merit_points", 0) or 0) >= G.MERIT_VALOR_THRESHOLD or _has_active_dishonored(st):
            if str(uid).isdigit():
                db_sync_uids.add(int(uid))

    changes: list[dict] = []
    errors: list[str] = []
    members_checked = 0
    members_scanned = 0

    def note(member, kind: str, role: str, detail: str) -> None:
        changes.append({
            "user_id": str(member.id), "name": member.display_name, "kind": kind, "role": role, "detail": detail,
        })

    members_to_scan = list(guild.members)
    for uid in db_sync_uids:
        m = guild.get_member(uid)
        if m and m not in members_to_scan:
            members_to_scan.append(m)

    valor_role = guild.get_role(ROLE_IDS["VALOR"])
    dishonored_ids = _dishonored_role_ids()

    for member in members_to_scan:
        if member.bot:
            continue
        members_checked += 1
        member_role_ids = {r.id for r in member.roles}
        needs_merit_sync = member.id in db_sync_uids
        if not (member_role_ids & watched_role_ids) and not needs_merit_sync:
            continue

        members_scanned += 1
        uid_str = str(member.id)
        stats = player_stats.get(uid_str)
        if stats is None:
            try:
                stats = await get_mysql_player_stats(uid_str)
            except Exception as e:
                errors.append(f"{member.display_name}: stats fetch failed ({e})")
                continue
            if apply:
                player_stats[uid_str] = stats
        if not apply:
            stats = dict(stats)  # a preview never touches the cached stats

        changed = False

        # Hearts of Valor holders who got RP Trusted under the old automatic
        # rule keep it as their approved Valor pick (one-time carry-over).
        if (
            ROLE_IDS["VALOR"] in member_role_ids
            and ROLE_IDS["HOI4_RP_TRUSTED"] in member_role_ids
            and not stats.get("valor_trusted")
            and int(stats.get("commends", 0) or 0) < G.MIN_TRUSTED_COMMENDS
        ):
            stats["valor_trusted"] = "Roleplay"
            changed = True

        # --- 1. TRUSTED ROLE AUDIT: both grant missing and remove invalid roles ---
        for cfg in GAME_ROLE_CONFIG.values():
            for role_id, commend_key in cfg["trusted_roles"].items():
                role_obj = guild.get_role(role_id)
                if not role_obj:
                    errors.append(f"Trusted role ID {role_id} not found")
                    continue
                has_role = role_id in member_role_ids
                # Each Trusted role needs the Verified role of its own game
                # type (the old shared role until Hist Verified is set up).
                verified_field = cfg["trusted_verified"].get(role_id, "hoi4_verified")
                verified_role = cfg["verified_roles"].get(verified_field) or cfg["verified_role_id"]
                verified = verified_role in member_role_ids
                commends = int(stats.get(commend_key, 0) or 0)
                vip_role_id = ROLE_IDS.get("VIP_ROLE_ID")
                has_vip = bool(vip_role_id and vip_role_id in member_role_ids)
                # The Trusted role the host team approved as a Valor perk.
                valor_entitled = (
                    ROLE_IDS["VALOR"] in member_role_ids
                    and _VALOR_TRUSTED_LABEL_ROLE.get(stats.get("valor_trusted") or "") == role_id
                )
                # A game ban in ANY mode blocks every Trusted role.
                mode_banned = _is_game_banned_any(stats)
                should_have = (
                    verified
                    and not mode_banned
                    and (commends >= G.MIN_TRUSTED_COMMENDS or has_vip or valor_entitled)
                )
                if should_have == has_role:
                    continue
                if should_have:
                    why = "VIP" if has_vip else "Hearts of Valor pick" if valor_entitled else f"{commends} commends"
                else:
                    why = (
                        "game banned" if mode_banned
                        else f"no {_verified_field_label(verified_field)}" if not verified
                        else f"{commends} commends (needs {G.MIN_TRUSTED_COMMENDS})"
                    )
                if apply:
                    try:
                        if should_have:
                            await member.add_roles(role_obj, reason=f"Statistics role scan: {why}")
                        else:
                            await member.remove_roles(role_obj, reason=f"Statistics role scan: {why}")
                        await asyncio.sleep(TRUSTED_ROLE_AUDIT_SLEEP_SEC)
                    except Exception as e:
                        errors.append(f"{member.display_name}: failed syncing {role_obj.name} ({e})")
                        continue
                note(member, "trusted_add" if should_have else "trusted_remove", role_obj.name, why)
                if should_have:
                    member_role_ids.add(role_id)
                else:
                    member_role_ids.discard(role_id)

        # --- 2 & 3. VERIFIED + HOST TIER DB SYNC (Discord roles are the source of truth) ---
        for cfg in GAME_ROLE_CONFIG.values():
            # RP Verified + Hist Verified (Hist once the bot has set its role up).
            for db_field, verified_role in cfg["verified_roles"].items():
                if not verified_role:
                    continue
                desired_verified = verified_role in member_role_ids
                if bool(stats.get(db_field, False)) != desired_verified:
                    stats[db_field] = desired_verified
                    changed = True
                    note(member, "record", _verified_field_label(db_field),
                         f"database says {'not ' if desired_verified else ''}verified — fixed to match Discord")

        for branch, branch_cfg in HOST_BRANCHES.items():
            if not any(branch_cfg["ranks"].values()):
                continue
            current_tier = _host_rank(member, branch)
            if (stats.get(branch_cfg["tier_db_field"]) or "None") != current_tier:
                stats[branch_cfg["tier_db_field"]] = current_tier
                changed = True
                note(member, "record", f"{branch} host rank", f"database fixed to {current_tier}")

        # --- 4. MERIT / DISHONORED ROLE SYNC (database is the source of truth) ---
        try:
            active_dishonored = _has_active_dishonored(stats)
            if bool(stats.get("dishonored")) != active_dishonored:
                stats["dishonored"] = active_dishonored
                changed = True
            had_valor = ROLE_IDS["VALOR"] in member_role_ids
            had_dish = bool(dishonored_ids & member_role_ids)
            if apply:
                warnings = await _sync_valor_role(member, stats)
                await _sync_dishonored_role(member, stats)
                refreshed_role_ids = {role.id for role in member.roles}
                now_valor = ROLE_IDS["VALOR"] in refreshed_role_ids
                now_dish = bool(dishonored_ids & refreshed_role_ids)
            else:
                # The same rules as _sync_valor_role / _sync_dishonored_role.
                banned = _is_game_banned_any(stats)
                meets = _qualifies_for_valor(member.id, stats)
                now_valor = had_valor
                if valor_role is not None:
                    if had_valor and (banned or not meets):
                        now_valor = False
                    elif not had_valor and meets and not banned and _current_warnings(stats) == 0:
                        now_valor = True
                now_dish = active_dishonored if dishonored_ids else had_dish
                warnings = []
            if had_valor != now_valor:
                note(member, "valor_add" if now_valor else "valor_remove", "Hearts of Valor",
                     f"{_merit_points(stats)} Merit" if now_valor else (
                         "game banned" if _is_game_banned_any(stats) else "requirements no longer met"))
            if had_dish != now_dish:
                note(member, "dishonored_add" if now_dish else "dishonored_remove", "Dishonored",
                     "a restriction is active" if now_dish else "no active restriction")
            for warning in warnings or []:
                errors.append(f"{member.display_name}: {warning}")
        except Exception as e:
            errors.append(f"{member.display_name}: merit/dishonored sync failed ({e})")

        if changed and apply:
            try:
                await save_mysql_player_stats(uid_str, stats)
            except Exception as e:
                errors.append(f"{member.display_name}: DB save failed ({e})")

    if apply:
        # Keep the warm cache authoritative after the sweep.
        try:
            await _refresh_player_stats_cache()
        except Exception:
            pass

    counts = {kind: sum(1 for change in changes if change["kind"] == kind) for kind in ROLE_SCAN_CHANGE_KINDS}
    result = {
        "applied": apply,
        "trigger": trigger,
        "by": str(actor_id) if actor_id else None,
        "finished_at": int(time.time()),
        "members_checked": members_checked,
        "members_scanned": members_scanned,
        "counts": counts,
        "total": len(changes),
        "changes": changes[:ROLE_SCAN_MAX_CHANGES],
        "errors": errors[:50],
    }

    if apply:
        def lines(*kinds):
            picked = [c for c in changes if c["kind"] in kinds]
            return _trim_field("\n".join(f"<@{c['user_id']}> — {c['role']} ({c['detail']})" for c in picked))
        embed = discord.Embed(
            title="🛡️ Statistics Role Scan Complete" + (" (daily)" if trigger == "daily" else ""),
            color=discord.Color.blurple(),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        embed.add_field(
            name="🔎 Scan Coverage",
            value=(
                f"Checked **{members_checked:,}** non-bot users.\n"
                f"Evaluated **{members_scanned:,}** users with relevant roles/statistics."
                + (f"\nRun by <@{actor_id}> on the website." if actor_id else "")
            ),
            inline=False,
        )
        embed.add_field(name="✅ Trusted Roles Added", value=lines("trusted_add"), inline=False)
        embed.add_field(name="🚫 Trusted Roles Removed", value=lines("trusted_remove"), inline=False)
        embed.add_field(name="✅ Records Synced", value=lines("record"), inline=False)
        embed.add_field(
            name="⭐ Valor / Dishonored",
            value=lines("valor_add", "valor_remove", "dishonored_add", "dishonored_remove"),
            inline=False,
        )
        if errors:
            embed.add_field(name="⚠️ Errors", value=_trim_field("\n".join(errors)), inline=False)
        embed.set_footer(text=f"Checked {members_checked:,} users · {len(changes):,} change(s)")
        try:
            await send_host_log_embed(embed)
        except Exception as e:
            print(f"[WARN] role scan log failed: {e}")
    return result


_role_scan_lock = asyncio.Lock()


async def _remember_role_scan(result: dict) -> None:
    """Keep the last preview and the last applied run for the website."""
    def save(cfg):
        last = cfg.get(ROLE_SCAN_LAST_KEY)
        last = dict(last) if isinstance(last, dict) else {}
        last["apply" if result.get("applied") else "preview"] = result
        cfg[ROLE_SCAN_LAST_KEY] = last
    try:
        await _bot_config_mutate(save)
    except Exception as e:
        print(f"[WARN] saving the role scan result failed: {e}")


async def _run_web_role_scan(request_id: str, apply: bool, actor) -> None:
    try:
        async with _role_scan_lock:
            result = await _run_role_verification_scan(apply=apply, trigger="web", actor_id=getattr(actor, "id", None))
        if result is None:
            status, payload, error = "error", None, "❌ The bot couldn't reach the server to check roles."
        else:
            await _remember_role_scan(result)
            status, payload, error = "done", {"role_scan": result}, None
    except Exception as e:
        print(f"[ERROR] web role scan failed: {e}")
        status, payload, error = "error", None, f"❌ The role check failed: {e}"
    try:
        await _run_mysql_io(_finish_web_schedule_request_mysql, request_id, status, payload, error, label="web role scan ack")
    except Exception as e:
        print(f"⚠️ web role scan ack failed: {e}")


async def _process_web_role_scan(req: dict):
    """Web Database page → role check (formerly /scan): mode "preview" shows
    what would change, "apply" does it. Host Management only; runs in the
    background (the request stays "running" until it's done)."""
    actor = await _web_fetch_member(int(req.get("host_id") or 0))
    if not _member_is_staff(actor):
        return False, None, "❌ Only Host Management (or admins) can run the role check."
    mode = str((req.get("payload") or {}).get("mode") or "")
    if mode not in ("preview", "apply"):
        return False, None, "❌ Choose preview or apply."
    if _role_scan_lock.locked():
        return False, None, "ℹ️ A role check is already running — wait a moment and try again."
    request_id = str(req.get("request_id") or "")
    try:
        await _run_mysql_io(
            _update_web_request_progress_mysql, request_id,
            {"role_scan": {"state": "running", "applied": mode == "apply", "started_at": int(time.time())}},
            label="web role scan start",
        )
    except Exception as e:
        print(f"[WARN] Could not mark role scan {request_id} running: {e}")
        return False, None, "❌ The bot couldn't record the request — please try again."
    _spawn_background(_run_web_role_scan(request_id, mode == "apply", actor), label=f"web role scan {mode}")
    return WEB_REQUEST_RUNNING, None, None


@tasks.loop(time=ROLE_SCAN_DAILY_TIME_UTC)
async def daily_role_scan_loop():
    """Runs once per active server (_daily_role_scan_loop_for_guild)."""
    await bot.wait_until_ready()
    await _run_for_active_guilds(_daily_role_scan_loop_for_guild, "daily_role_scan_loop")


async def _daily_role_scan_loop_for_guild():
    """The role check runs by itself once a day (04:00 UTC) and applies."""
    await bot.wait_until_ready()
    if _role_scan_lock.locked() or not SERVER_FEATURES.get("daily_role_check", True):
        return
    try:
        async with _role_scan_lock:
            result = await _run_role_verification_scan(apply=True, trigger="daily")
        if result is not None:
            await _remember_role_scan(result)
    except Exception as e:
        print(f"⚠️ daily role scan failed: {e}")


@tree.error
async def on_app_command_error(interaction: discord.Interaction, error: app_commands.AppCommandError):
    cmd = interaction.command.qualified_name if interaction.command else "unknown"
    user_id = interaction.user.id if interaction.user else "?"
    if isinstance(error, app_commands.CheckFailure):
        # The check already sent its own denial. A second response is what
        # raises Discord 40060 (interaction already acknowledged).
        if interaction.response.is_done():
            return
        try:
            await interaction.response.send_message(
                "❌ You can't use this command.",
                ephemeral=True,
            )
        except discord.HTTPException:
            pass
        return
    if isinstance(error, app_commands.CommandInvokeError):
        orig = error.original
        # Interaction expired / deferred followup token died (usually because the
        # command hung on MySQL longer than Discord's ~15 min interaction lifetime).
        if isinstance(orig, discord.NotFound) and getattr(orig, "code", None) == 10062:
            _audit_log("ERROR", f"Interaction expired (10062) cmd={cmd} user={user_id}")
            return
        if isinstance(orig, discord.HTTPException) and getattr(orig, "code", None) == 50027:
            _audit_log(
                "ERROR",
                f"Invalid webhook token (50027) cmd={cmd} user={user_id} — "
                f"interaction expired while the command was stuck (often dead MySQL).",
            )
            return
        if isinstance(orig, TimeoutError):
            _audit_log("ERROR", f"Command timeout cmd={cmd} user={user_id}: {orig}")
            try:
                msg = (
                    f"⚠️ `/{cmd}` timed out waiting on the database. "
                    f"If this keeps happening, restart the bot (stale MySQL connections). "
                    f"Do NOT re-run blindly — it may have partially completed."
                )
                if interaction.response.is_done():
                    await interaction.followup.send(msg, ephemeral=True)
                else:
                    await interaction.response.send_message(msg, ephemeral=True)
            except Exception:
                pass
            return
    _audit_log("ERROR", f"Command {cmd} user={user_id}: {error}")

    # SAFETY NET: an uncaught exception mid-command (after defer()) used to leave
    # the interaction stuck on "thinking..." forever — the host would see NO
    # response and assume the command silently failed. That previously caused a
    # real incident (host re-ran /announce_game after a crashed /game_cancel,
    # creating duplicate live announcements for the same game). Always try to
    # tell the user something went wrong instead of leaving them guessing.
    try:
        msg = f"⚠️ Something went wrong running `/{cmd}`. Please check with staff before retrying — do NOT re-run the command blindly, it may have partially completed."
        if interaction.response.is_done():
            await interaction.followup.send(msg, ephemeral=True)
        else:
            await interaction.response.send_message(msg, ephemeral=True)
    except Exception:
        pass  # Interaction may have already expired — nothing more we can do.


def _ping_mysql_once():
    """Run SELECT 1 on a pooled connection; raises on any failure."""
    conn = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor()
        cur.execute("SELECT 1")
        cur.fetchone()
        cur.close()
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


_db_watchdog_failures = 0

# After this many CONSECUTIVE failed health checks (each one also attempts and
# fails a full pool rebuild), the in-process self-healing has provably lost —
# the only remaining fix is the same one done manually: restart the whole
# process. The panel (Apollo/Pterodactyl crash detection) auto-restarts the
# container when the process exits non-zero, giving a fully automated recovery.
# 6 checks × 60s = ~6 minutes of sustained, unrecoverable DB failure, so a
# genuine long MySQL-server outage becomes at worst a slow restart cycle
# (~7 min apart), not a tight crash-loop.
DB_WATCHDOG_RESTART_THRESHOLD = 6
_self_restart_started = False


async def _self_restart(reason: str):
    """Last-resort automated restart: announce it, then hard-exit non-zero so
    the hosting panel's crash detection boots a fresh container.

    Uses os._exit (not sys.exit) on purpose — the reason we're here is stuck
    MySQL threads, and a normal interpreter shutdown would block forever
    waiting on those exact threads."""
    global _self_restart_started
    if _self_restart_started:
        return
    _self_restart_started = True

    banner = (
        f"🔄 SELF-RESTART TRIGGERED: {reason}\n"
        f"   In-process recovery (pool rebuilds) failed repeatedly — exiting so the "
        f"panel restarts the bot automatically."
    )
    print(banner, flush=True)

    # Best-effort alert to the host log before we die (never let it block the exit).
    try:
        channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
        if channel:
            await asyncio.wait_for(
                channel.send(
                    f"🔄 **AUTOMATED SELF-RESTART**\n"
                    f"**Reason:** {reason}\n"
                    f"MySQL has been unrecoverable for {DB_WATCHDOG_RESTART_THRESHOLD}+ minutes and "
                    f"pool rebuilds keep failing. Restarting the whole bot now — it should be back "
                    f"online in under a minute. No action needed."
                ),
                timeout=10,
            )
    except Exception as e:
        print(f"[WARN] Could not send self-restart alert: {e}", flush=True)

    # Give Discord's HTTP session a moment to flush the message, then die hard.
    await asyncio.sleep(2)
    os._exit(1)


@tasks.loop(seconds=60)
async def db_health_watchdog():
    """Self-healing DB watchdog: ping MySQL every minute; rebuild the pool after
    2 consecutive failures so the bot recovers without a manual restart. If even
    pool rebuilds keep failing (DB_WATCHDOG_RESTART_THRESHOLD consecutive checks),
    escalate to a full automated process restart via the hosting panel."""
    global _db_watchdog_failures
    try:
        await asyncio.wait_for(asyncio.to_thread(_ping_mysql_once), timeout=15)
        if _db_watchdog_failures:
            print("✅ MySQL health restored.")
        _db_watchdog_failures = 0
    except Exception as e:
        _db_watchdog_failures += 1
        print(f"⚠️ MySQL health check failed ({_db_watchdog_failures} consecutive): {e}")
        if _db_watchdog_failures >= 2:
            try:
                await asyncio.wait_for(
                    asyncio.to_thread(_rebuild_db_pool, f"watchdog: {_db_watchdog_failures} consecutive ping failures"),
                    timeout=30,
                )
                # Verify the fresh pool actually works before declaring victory.
                await asyncio.wait_for(asyncio.to_thread(_ping_mysql_once), timeout=15)
                print("✅ MySQL pool rebuilt and verified healthy.")
                _db_watchdog_failures = 0
                return
            except Exception as e2:
                # DB server itself is down/unreachable — keep trying every minute.
                print(f"❌ MySQL pool rebuild failed (server may be down, will retry): {e2}")

        # ESCALATION: rebuilds aren't fixing it. The same situation that used to
        # require a manual panel restart — do it automatically instead.
        if _db_watchdog_failures >= DB_WATCHDOG_RESTART_THRESHOLD:
            await _self_restart(
                f"MySQL unrecoverable after {_db_watchdog_failures} consecutive failed health "
                f"checks (pool rebuilds also failing)"
            )


@db_health_watchdog.before_loop
async def before_db_health_watchdog():
    await bot.wait_until_ready()


# ==========================================================================
# SERVER SETTINGS (website setup) — multi-server GameMaster.
#
# Any server can add the bot; its owner sets it up on the website (/servers).
# Each server's settings live in `guild_settings` (JSON + version) with every
# change in `guild_settings_history`. The bot mirrors each server's roles,
# channels and its own permissions into `web_guild_snapshot` so the setup
# pickers and health check show the real server.
#
# Every server has a GuildRuntime (see PER-SERVER RUNTIME near the top):
# _apply_settings turns its website settings into the role / channel / rule
# values the rest of the bot reads for that server. A server is *active*
# (the bot works there) once its setup is finished; the home server always
# is. Website changes are picked up within GUILD_SETTINGS_POLL_SEC.
# ==========================================================================
GUILD_SETTINGS_SCHEMA = 1
GUILD_SETTINGS_POLL_SEC = 30
