def _sid(value) -> str | None:
    """A Discord id as a string, or None."""
    text = str(value or "").strip()
    return text if text.isdigit() and text != "0" else None


def _iid(value) -> int:
    text = _sid(value)
    return int(text) if text else 0


def _sids(values) -> list[str]:
    out: list[str] = []
    for value in values or []:
        text = _sid(value)
        if text and text not in out:
            out.append(text)
    return out


def _parse_md_links(entries) -> list[dict]:
    """MODE_CONFIG's "[Name](https://…)" strings → [{name, link}]."""
    out = []
    for entry in entries or []:
        match = re.match(r"^\[(.+?)\]\((https?://[^\s)]+)\)$", str(entry).strip())
        if match:
            out.append({"name": match.group(1), "link": match.group(2)})
    return out


def _md_links(entries) -> list[str]:
    out = []
    for entry in entries or []:
        name = str((entry or {}).get("name") or "").strip()[:100]
        link = str((entry or {}).get("link") or "").strip()[:500]
        if name and link.startswith(("http://", "https://")):
            out.append(f"[{name}]({link})")
    return out


def _public_log_channel_for_base(base_mode) -> int:
    """A game's public chat-log archive when its mode has none set."""
    historical = "Historical" in str(base_mode or "")
    for key, branch in BUILTIN_MODES:
        if (branch == "HIST") == historical:
            channel_id = (MODE_CONFIG.get(key) or {}).get("public_log_channel_id")
            if channel_id:
                return int(channel_id)
    return 0


def _default_mode_mod_links(key: str) -> list[dict]:
    """A mode's public mods (TommyKay's own submods / rule docs aren't defaults)."""
    if key in _DEFAULT_MODE_MOD_LINKS:
        return [dict(entry) for entry in _DEFAULT_MODE_MOD_LINKS[key]]
    source = (_RUNTIMES[GUILD_ID].dicts["MODE_CONFIG"] if _RUNTIME_INSTALLED else MODE_CONFIG).get(key) or {}
    return [entry for entry in _parse_md_links(source.get("mod_links")) if "tommykay" not in entry["name"].lower()]


def _default_guild_settings(name: str = "") -> dict:
    """A fresh server's settings: nothing mapped yet, TommyKay's numbers."""
    return {
        "schema": GUILD_SETTINGS_SCHEMA,
        "general": {"community_name": str(name or "")[:60]},
        "access": {
            "senior_staff_roles": [], "staff_can_edit_settings": False,
            # Tickets: Ticket Support (verification tickets) and Developers (bugs / suggestions).
            "ticket_support_roles": [], "developer_roles": [],
        },
        "branches": {
            b: {"enabled": True, "ranks": {r: None for r in HOST_RANKS}, "ranks_on": {r: True for r in OPTIONAL_HOST_RANKS}}
            for b in SETTINGS_BRANCHES
        },
        "roles": {
            "verified": {b: None for b in SETTINGS_BRANCHES},
            "trusted": {b: None for b in SETTINGS_BRANCHES},
            "game_ban": {b: None for b in SETTINGS_BRANCHES},
            "dishonored": {b: None for b in SETTINGS_BRANCHES},
            "ping": {b: None for b in SETTINGS_BRANCHES},
            "vip": None, "valor": None, "crash_report_ping": None,
        },
        "channels": {key: None for key in SETTINGS_CHANNEL_KEYS},
        "lobby_voices": [],
        "voice": {b: {"after_category": None, "before_category": None} for b in SETTINGS_BRANCHES},
        "modes": {
            key: {
                # A new server switches on only the modes it runs.
                "enabled": False, **{field: None for field in MODE_CHANNEL_FIELDS},
                "mod_links": _default_mode_mod_links(key),
                "rule_links": [],
            }
            for key, _ in BUILTIN_MODES
        },
        "rules": dict(SETTINGS_RULE_DEFAULTS),
        "features": {
            "valor_merit": True, "daily_role_check": True, "vip_auto_carry_over": True,
            "cross_server_ban_alerts": True, "ticket_inactivity_close": True,
        },
        "addons": {"casino_panel_channel": None, "randomizer_log_channel": None, "fortunes_log_channel": None},
    }


def _settings_from_constants(name: str = "") -> dict:
    """The home server's current values as settings (the one-time seed)."""
    with guild_scope(GUILD_ID):
        sc = _rt(GUILD_ID).scalars if _RUNTIME_INSTALLED else globals()
        s = _default_guild_settings(name)
        rank_ids = {rid for cfg in HOST_BRANCHES.values() for rid in cfg["ranks"].values() if rid}
        s["access"]["senior_staff_roles"] = _sids(SENIOR_MANAGEMENT_ROLES)
        s["access"]["staff_can_edit_settings"] = True
        s["access"]["ticket_support_roles"] = _sids(TICKET_SUPPORT_ROLES)
        s["access"]["developer_roles"] = _sids(DEVELOPER_ROLES)
        for branch in SETTINGS_BRANCHES:
            cfg = HOST_BRANCHES[branch]
            s["branches"][branch] = {
                "enabled": bool(cfg.get("enabled", True)),
                "ranks": {rank: _sid(cfg["ranks"].get(rank)) for rank in HOST_RANKS},
                "ranks_on": {rank: True for rank in OPTIONAL_HOST_RANKS},
            }
        s["roles"]["verified"] = {"RP": _sid(ROLE_IDS.get("HOI4_VERIFIED")), "HIST": _sid(ROLE_IDS.get("HIST_VERIFIED"))}
        s["roles"]["trusted"] = {"RP": _sid(ROLE_IDS.get("HOI4_RP_TRUSTED")), "HIST": _sid(ROLE_IDS.get("HOI4_MP_TRUSTED"))}
        s["roles"]["game_ban"] = {"RP": _sid(ROLE_IDS.get("HOI4_RP_BANNED")), "HIST": _sid(ROLE_IDS.get("HOI4_MP_BANNED"))}
        s["roles"]["vip"] = _sid(ROLE_IDS.get("VIP_ROLE_ID"))
        s["roles"]["valor"] = _sid(ROLE_IDS.get("VALOR"))
        s["roles"]["dishonored"] = {"RP": _sid(ROLE_IDS.get("DISHONORED")), "HIST": _sid(ROLE_IDS.get("HIST_DISHONORED"))}
        for branch in SETTINGS_BRANCHES:
            first = next(
                (MODE_CONFIG.get(key) or {} for key, b in BUILTIN_MODES if b == branch and (MODE_CONFIG.get(key) or {}).get("ping_role_id")),
                {},
            )
            s["roles"]["ping"][branch] = _sid(first.get("ping_role_id"))
        s["roles"]["crash_report_ping"] = _sid(sc["CRASH_REPORT_DEV_ROLE_ID"])
        s["channels"] = {
            "host_log": _sid(sc["HOST_LOG_CHANNEL_ID"]), "staff_notices": _sid(sc["HOST_MANAGEMENT_CHANNEL_ID"]),
            "schedule_panel": _sid(sc["SCHEDULE_CHANNEL_ID"]),
            "host_chatlogs_forum": _sid(sc["HOST_FORUM_CHANNEL_ID"]), "tickets": _sid(sc["TICKET_CHANNEL_ID"]),
            "crash_reports": _sid(sc["CRASH_REPORT_CHANNEL_ID"]),
            "ticket_category": _sid(sc["TICKET_CATEGORY_ID"]), "ticket_log": _sid(sc["TICKET_LOG_CHANNEL_ID"]),
            "ticket_private_log": _sid(sc["TICKET_PRIVATE_LOG_CHANNEL_ID"]),
        }
        s["lobby_voices"] = _sids(LOBBY_VC_IDS)
        s["voice"] = {
            b: {"after_category": _sid(GAME_VOICE_ANCHORS[b][0]), "before_category": _sid(GAME_VOICE_ANCHORS[b][1])}
            for b in SETTINGS_BRANCHES
        }
        for key, _ in BUILTIN_MODES:
            cfg = MODE_CONFIG.get(key) or {}
            s["modes"][key] = {
                "enabled": bool(cfg.get("enabled", True)),
                **{field: _sid(cfg.get(src)) for field, src in MODE_CHANNEL_FIELDS.items()},
                "mod_links": _parse_md_links(cfg.get("mod_links")),
                "rule_links": _parse_md_links(cfg.get("rule_links")),
            }
        s["rules"] = {
            "trusted_commends": sc["MIN_TRUSTED_COMMENDS"], "warnings_for_ban": sc["WARNINGS_FOR_BAN"],
            "host_full_at": HOST_PROMOTE_AT["Full"], "host_senior_at": HOST_PROMOTE_AT["Senior"],
            "host_strip_at": sc["HOST_TERMINATE_AT"], "valor_merit": sc["MERIT_VALOR_THRESHOLD"],
            "valor_games": sc["MERIT_VALOR_GAMES_REQUIRED"], "hosting_success_avg": float(sc["HOSTING_SUCCESS_MIN_AVG"]),
        }
        s["addons"] = {
            "casino_panel_channel": _sid(CASINO_PANEL_CHANNEL_ID),
            "randomizer_log_channel": _sid(RANDOMIZER_LOG_CHANNEL_ID),
            "fortunes_log_channel": _sid(FORTUNES_LOG_CHANNEL_ID),
        }
        return s


def _normalize_guild_settings(raw, name: str = "") -> dict:
    """Stored settings → a complete, type-checked dict (missing parts take the
    defaults, so older rows keep working after new settings are added)."""
    raw = raw if isinstance(raw, dict) else {}
    s = _default_guild_settings(name)

    def section(key):
        value = raw.get(key)
        return value if isinstance(value, dict) else {}

    general = section("general")
    if isinstance(general.get("community_name"), str):
        s["general"]["community_name"] = general["community_name"].strip()[:60]
    access = section("access")
    for key in ("senior_staff_roles", "ticket_support_roles", "developer_roles"):
        s["access"][key] = _sids(access.get(key))
    s["access"]["staff_can_edit_settings"] = bool(access.get("staff_can_edit_settings"))
    branches = section("branches")
    for b in SETTINGS_BRANCHES:
        entry = branches.get(b) if isinstance(branches.get(b), dict) else {}
        ranks = entry.get("ranks") if isinstance(entry.get("ranks"), dict) else {}
        ranks_on = entry.get("ranks_on") if isinstance(entry.get("ranks_on"), dict) else {}
        s["branches"][b] = {
            "enabled": bool(entry.get("enabled", True)),
            "ranks": {rank: _sid(ranks.get(rank)) for rank in HOST_RANKS},
            "ranks_on": {rank: bool(ranks_on.get(rank, True)) for rank in OPTIONAL_HOST_RANKS},
        }
    if not any(s["branches"][b]["enabled"] for b in SETTINGS_BRANCHES):
        s["branches"]["RP"]["enabled"] = True
    roles = section("roles")
    for key in ("verified", "trusted", "game_ban", "dishonored", "ping"):
        if key == "dishonored" and not isinstance(roles.get(key), dict):
            # Older settings: one Dishonored role for both branches.
            s["roles"][key] = {b: _sid(roles.get(key)) for b in SETTINGS_BRANCHES}
            continue
        per = roles.get(key) if isinstance(roles.get(key), dict) else {}
        s["roles"][key] = {b: _sid(per.get(b)) for b in SETTINGS_BRANCHES}
    for key in ("vip", "valor", "crash_report_ping"):
        s["roles"][key] = _sid(roles.get(key))
    channels = section("channels")
    s["channels"] = {key: _sid(channels.get(key)) for key in SETTINGS_CHANNEL_KEYS}
    if not s["channels"]["schedule_panel"]:
        s["channels"]["schedule_panel"] = _sid(channels.get("schedule_board"))  # the old board's channel
    # Older settings: one lobby channel.
    lobbies = raw.get("lobby_voices")
    s["lobby_voices"] = _sids(lobbies if isinstance(lobbies, list) else [channels.get("lobby_voice")])
    voice = section("voice")
    for b in SETTINGS_BRANCHES:
        entry = voice.get(b) if isinstance(voice.get(b), dict) else {}
        s["voice"][b] = {"after_category": _sid(entry.get("after_category")), "before_category": _sid(entry.get("before_category"))}
    modes = section("modes")
    for key, _ in BUILTIN_MODES:
        entry = modes.get(key) if isinstance(modes.get(key), dict) else None
        if entry is None:
            continue
        s["modes"][key] = {
            "enabled": bool(entry.get("enabled", True)),
            **{field: _sid(entry.get(field)) for field in MODE_CHANNEL_FIELDS},
            "mod_links": _parse_md_links(_md_links(entry.get("mod_links")))[:20],
            "rule_links": _parse_md_links(_md_links(entry.get("rule_links")))[:20],
        }
    # Older settings: the branch's notification ping from its modes' ping roles.
    for b in SETTINGS_BRANCHES:
        if not s["roles"]["ping"][b]:
            s["roles"]["ping"][b] = next(
                (s["modes"][key]["ping_role"] for key, branch in BUILTIN_MODES if branch == b and s["modes"][key].get("ping_role")),
                None,
            )
    rules = section("rules")
    for key, default in SETTINGS_RULE_DEFAULTS.items():
        low, high = SETTINGS_RULE_LIMITS[key]
        try:
            value = float(rules.get(key, default)) if isinstance(default, float) else int(rules.get(key, default))
        except (TypeError, ValueError):
            value = default
        s["rules"][key] = min(high, max(low, value))
    features = section("features")
    for key in s["features"]:
        if key in features:
            s["features"][key] = bool(features[key])
    addons = section("addons")
    s["addons"] = {key: _sid(addons.get(key)) for key in s["addons"]}
    return s


# ————— Per-server runtimes —————

def _install_guild_runtime() -> None:
    """Import time (end of module): the values written in this file become the
    home server's runtime, and the module-level dicts / lists become proxies
    that read the current server's copy."""
    global _RUNTIME_INSTALLED
    if _RUNTIME_INSTALLED:
        return
    g = globals()
    home = GuildRuntime(GUILD_ID)
    for name in _PER_GUILD_DICTS:
        home.dicts[name] = g[name]
    for name in _PER_GUILD_LISTS:
        home.lists[name] = g[name]
    for name in _PER_GUILD_SCALARS:
        home.scalars[name] = g[name]
    for key, branch in BUILTIN_MODES:
        cfg = home.dicts["MODE_CONFIG"].get(key)
        if cfg is not None:
            cfg.setdefault("branch", branch)
            cfg.setdefault("enabled", True)
        _DEFAULT_MODE_MOD_LINKS[key] = [
            entry for entry in _parse_md_links((cfg or {}).get("mod_links")) if "tommykay" not in entry["name"].lower()
        ]
        if cfg is not None:
            _HOME_MODE_SEED[key] = {
                "enabled": bool(cfg.get("enabled", True)),
                **{field: _sid(cfg.get(src)) for field, src in MODE_CHANNEL_FIELDS.items()},
                "mod_links": _parse_md_links(cfg.get("mod_links")),
                "rule_links": _parse_md_links(cfg.get("rule_links")),
            }
    _RUNTIMES[GUILD_ID] = home
    for name in _PER_GUILD_DICTS:
        g[name] = _GuildDict(name)
    for name in _PER_GUILD_LISTS:
        g[name] = _GuildList(name)
    _RUNTIME_INSTALLED = True


def _new_runtime(gid: int) -> GuildRuntime:
    """A server's runtime before its settings are applied: the home server's
    structure with every role / channel id empty and the default numbers."""
    rt = GuildRuntime(gid)
    home = _RUNTIMES[GUILD_ID].dicts
    rt.dicts["ROLE_IDS"] = {key: 0 for key in home["ROLE_IDS"]}
    modes: dict = {}
    fresh_by_source: dict[int, dict] = {}
    for key, branch in BUILTIN_MODES:
        source = home["MODE_CONFIG"].get(key) or {}
        fresh = {
            field: (0 if field.endswith("_id") else json.loads(json.dumps(value)))
            for field, value in source.items()
        }
        fresh.update(branch=branch, enabled=False, mod_links=_md_links(_default_mode_mod_links(key)), rule_links=[])
        modes[key] = fresh
        fresh_by_source[id(source)] = fresh
    for key, source in home["MODE_CONFIG"].items():
        if key not in modes:
            modes[key] = fresh_by_source.get(id(source)) or {
                field: (0 if field.endswith("_id") else json.loads(json.dumps(value))) for field, value in source.items()
            }
    rt.dicts["MODE_CONFIG"] = modes
    branches = json.loads(json.dumps(home["HOST_BRANCHES"]))
    for cfg in branches.values():
        cfg["enabled"] = True
        cfg["ranks"] = {rank: 0 for rank in HOST_RANKS}
    rt.dicts["HOST_BRANCHES"] = branches
    base = home["GAME_ROLE_CONFIG"]["HOI4"]
    rt.dicts["GAME_ROLE_CONFIG"] = {
        "HOI4": {
            "label": base.get("label", "Hearts of Iron 4"),
            "verified_role_id": 0,
            "verified_db_field": base.get("verified_db_field", "hoi4_verified"),
            "verified_roles": {"hoi4_verified": 0, "hist_verified": 0},
            "trusted_verified": {},
            "trusted_roles": {},
            "host_tier_db_field": base.get("host_tier_db_field", "hoi4_host_tier"),
            "host_tiers": branches["RP"]["ranks"],
        }
    }
    rt.dicts["CHANNELS"] = {key: 0 for key in home["CHANNELS"]}
    rt.dicts["GAME_VOICE_ANCHORS"] = {b: (0, 0) for b in SETTINGS_BRANCHES}
    rt.dicts["HOST_PROMOTE_AT"] = {"Full": SETTINGS_RULE_DEFAULTS["host_full_at"], "Senior": SETTINGS_RULE_DEFAULTS["host_senior_at"]}
    rt.dicts["SERVER_FEATURES"] = {
        "valor_merit": True, "daily_role_check": True, "vip_auto_carry_over": True, "cross_server_ban_alerts": True,
        "ticket_inactivity_close": True,
    }
    for name in _PER_GUILD_LISTS:
        rt.lists[name] = []
    rt.scalars = {name: 0 for name in _PER_GUILD_SCALARS}
    rt.scalars.update(
        MIN_TRUSTED_COMMENDS=SETTINGS_RULE_DEFAULTS["trusted_commends"],
        WARNINGS_FOR_BAN=SETTINGS_RULE_DEFAULTS["warnings_for_ban"],
        HOST_TERMINATE_AT=SETTINGS_RULE_DEFAULTS["host_strip_at"],
        MERIT_VALOR_THRESHOLD=SETTINGS_RULE_DEFAULTS["valor_merit"],
        MERIT_VALOR_GAMES_REQUIRED=SETTINGS_RULE_DEFAULTS["valor_games"],
        HOSTING_SUCCESS_MIN_AVG=SETTINGS_RULE_DEFAULTS["hosting_success_avg"],
        HOST_LOG_WEBHOOK_URL=None,
    )
    return rt


def _apply_settings(rt: GuildRuntime, settings: dict) -> None:
    """Turn a server's settings into its runtime values (everything is updated
    in place, so MODE_CONFIG aliases like "Historical" follow)."""
    global CASINO_PANEL_CHANNEL_ID, RANDOMIZER_LOG_CHANNEL_ID, RECEIPT_LOG_CHANNEL_ID, RECEIPT_AUDIT_CHANNEL_ID
    global FORTUNES_LOG_CHANNEL_ID
    s = settings
    roles = s["roles"]
    d, lists, sc = rt.dicts, rt.lists, rt.scalars

    # Staff, host ranks, host-page roles.
    lists["SENIOR_MANAGEMENT_ROLES"][:] = [int(r) for r in s["access"]["senior_staff_roles"]]
    # Host Management also manages the voice channels made for each game.
    lists["GAME_VOICE_MANAGER_ROLES"][:] = list(lists["SENIOR_MANAGEMENT_ROLES"])
    lists["TICKET_SUPPORT_ROLES"][:] = [int(r) for r in s["access"]["ticket_support_roles"]]
    lists["DEVELOPER_ROLES"][:] = [int(r) for r in s["access"]["developer_roles"]]
    branches = d["HOST_BRANCHES"]
    for b in SETTINGS_BRANCHES:
        branches[b]["enabled"] = bool(s["branches"][b]["enabled"])
        for rank in HOST_RANKS:
            rid = _iid(s["branches"][b]["ranks"][rank])
            # A switched-off rank has no role: nobody is promoted to it or given it.
            on = rank not in OPTIONAL_HOST_RANKS or s["branches"][b]["ranks_on"].get(rank, True)
            branches[b]["ranks"][rank] = rid if branches[b]["enabled"] and on else 0
    rank_ids = [rid for b in SETTINGS_BRANCHES for rid in branches[b]["ranks"].values() if rid]
    lists["ALLOWED_HOST_ROLES"][:] = list(dict.fromkeys(rank_ids + list(lists["SENIOR_MANAGEMENT_ROLES"])))
    d["GAME_ROLE_CONFIG"]["HOI4"]["host_tiers"] = branches["RP"]["ranks"]

    # Player roles.
    role_ids = d["ROLE_IDS"]
    role_ids["HOI4_VERIFIED"] = _iid(roles["verified"]["RP"])
    role_ids["HIST_VERIFIED"] = _iid(roles["verified"]["HIST"])
    role_ids["HOI4_RP_TRUSTED"] = _iid(roles["trusted"]["RP"])
    role_ids["HOI4_MP_TRUSTED"] = _iid(roles["trusted"]["HIST"])
    role_ids["HOI4_RP_BANNED"] = _iid(roles["game_ban"]["RP"])
    role_ids["HOI4_MP_BANNED"] = _iid(roles["game_ban"]["HIST"])
    role_ids["VIP_ROLE_ID"] = _iid(roles["vip"])
    role_ids["VALOR"] = _iid(roles["valor"])
    role_ids["DISHONORED"] = _iid(roles["dishonored"]["RP"])
    role_ids["HIST_DISHONORED"] = _iid(roles["dishonored"]["HIST"])
    sc["CRASH_REPORT_DEV_ROLE_ID"] = _iid(roles["crash_report_ping"])
    sc["TRUSTED_ROLE"] = role_ids["HOI4_RP_TRUSTED"]
    sc["GAME_BANNED_ROLE"] = role_ids["HOI4_RP_BANNED"]
    lists["ALL_BAN_IDS"][:] = [rid for rid in (role_ids["HOI4_RP_BANNED"], role_ids["HOI4_MP_BANNED"]) if rid]
    hoi4 = d["GAME_ROLE_CONFIG"]["HOI4"]
    hoi4["verified_role_id"] = role_ids["HOI4_VERIFIED"]
    hoi4["verified_roles"] = {"hoi4_verified": role_ids["HOI4_VERIFIED"], "hist_verified": role_ids["HIST_VERIFIED"]}
    hoi4["trusted_roles"] = {
        rid: field for rid, field in ((role_ids["HOI4_RP_TRUSTED"], "commends"), (role_ids["HOI4_MP_TRUSTED"], "hist_commends")) if rid
    }
    hoi4["trusted_verified"] = {
        rid: field for rid, field in ((role_ids["HOI4_RP_TRUSTED"], "hoi4_verified"), (role_ids["HOI4_MP_TRUSTED"], "hist_verified")) if rid
    }

    # Channels.
    ch = s["channels"]
    host_log = _iid(ch["host_log"])
    sc["HOST_LOG_CHANNEL_ID"] = host_log
    d["CHANNELS"]["HOST_LOG_CHANNEL"] = host_log
    sc["HOST_TEAM_CHANNEL_ID"] = host_log
    sc["HOST_LOG_WEBHOOK_URL"] = (
        _HOST_LOG_WEBHOOK_ENV if rt.gid == GUILD_ID and host_log else None
    )
    sc["HOST_MANAGEMENT_CHANNEL_ID"] = _iid(ch["staff_notices"])
    sc["VIP_NOTICE_CHANNEL_ID"] = sc["HOST_MANAGEMENT_CHANNEL_ID"]
    # One audit log for everything: host actions, slash commands, role changes.
    sc["AUDIT_CHANNEL_ID"] = host_log
    sc["LOG_CHANNEL_ID"] = host_log
    sc["ROLE_AUDIT_LOG_CHANNEL_ID"] = host_log
    sc["SCHEDULE_CHANNEL_ID"] = _iid(ch["schedule_panel"])
    sc["HOST_FORUM_CHANNEL_ID"] = _iid(ch["host_chatlogs_forum"])
    sc["TICKET_CHANNEL_ID"] = _iid(ch["tickets"])
    sc["CRASH_REPORT_CHANNEL_ID"] = _iid(ch["crash_reports"])
    lists["LOBBY_VC_IDS"][:] = [int(cid) for cid in s["lobby_voices"]]
    sc["LOBBY_VC_ID"] = lists["LOBBY_VC_IDS"][0] if lists["LOBBY_VC_IDS"] else 0
    sc["TICKET_CATEGORY_ID"] = _iid(ch["ticket_category"])
    sc["TICKET_LOG_CHANNEL_ID"] = _iid(ch["ticket_log"])
    sc["TICKET_PRIVATE_LOG_CHANNEL_ID"] = _iid(ch["ticket_private_log"])
    for b in SETTINGS_BRANCHES:
        d["GAME_VOICE_ANCHORS"][b] = (_iid(s["voice"][b]["after_category"]), _iid(s["voice"][b]["before_category"]))
    if rt.gid == GUILD_ID:
        # Casino / add-on channels exist only on the home server.
        addons = s["addons"]
        CASINO_PANEL_CHANNEL_ID = _iid(addons["casino_panel_channel"])
        RANDOMIZER_LOG_CHANNEL_ID = _iid(addons["randomizer_log_channel"])
        RECEIPT_LOG_CHANNEL_ID = RANDOMIZER_LOG_CHANNEL_ID
        RECEIPT_AUDIT_CHANNEL_ID = RANDOMIZER_LOG_CHANNEL_ID
        FORTUNES_LOG_CHANNEL_ID = _iid(addons["fortunes_log_channel"])

    # Game modes (in place: "Historical" and the old names share these dicts).
    for key, branch in BUILTIN_MODES:
        cfg = d["MODE_CONFIG"].get(key)
        if cfg is None:
            continue
        mode = s["modes"][key]
        cfg["branch"] = branch
        cfg["enabled"] = bool(mode["enabled"]) and bool(s["branches"][branch]["enabled"])
        for field, src in MODE_CHANNEL_FIELDS.items():
            cfg[src] = _iid(mode[field])
        # The mode's own ping role, else the branch's notification ping.
        cfg["ping_role_id"] = _iid(mode["ping_role"]) or _iid(roles["ping"][branch])
        cfg["trusted_role_id"] = _iid(roles["trusted"][branch])
        cfg["verified_role_id"] = _iid(roles["verified"][branch]) or role_ids["HOI4_VERIFIED"]
        cfg["banned_role_id"] = _iid(roles["game_ban"][branch])
        cfg["mod_links"] = _md_links(mode["mod_links"])
        cfg["rule_links"] = _md_links(mode["rule_links"])

    # Rule numbers and features.
    rules = s["rules"]
    sc["MIN_TRUSTED_COMMENDS"] = int(rules["trusted_commends"])
    sc["WARNINGS_FOR_BAN"] = int(rules["warnings_for_ban"])
    d["HOST_PROMOTE_AT"]["Full"] = int(rules["host_full_at"])
    d["HOST_PROMOTE_AT"]["Senior"] = max(int(rules["host_senior_at"]), d["HOST_PROMOTE_AT"]["Full"])
    sc["HOST_TERMINATE_AT"] = int(rules["host_strip_at"])
    sc["MERIT_VALOR_THRESHOLD"] = int(rules["valor_merit"])
    sc["MERIT_VALOR_GAMES_REQUIRED"] = int(rules["valor_games"])
    sc["HOSTING_SUCCESS_MIN_AVG"] = float(rules["hosting_success_avg"])
    d["SERVER_FEATURES"].update(s["features"])
    rt.settings = s


# Add-ons that need the home server's casino / Fortunes commands.
HOME_ONLY_ADDONS = {"randomizer", "fortunes"}


def _community_name() -> str:
    """The current server's community name (server settings → Basics)."""
    name = ((_rt().settings or {}).get("general") or {}).get("community_name")
    if name:
        return str(name)
    guild = bot.get_guild(cur_gid())
    return guild.name if guild is not None else "the server's"


def _guild_active(gid=None) -> bool:
    """GameMaster works in this server (home, or setup finished)."""
    return _rt(gid).active


def _active_guilds() -> list:
    """The servers GameMaster works in right now (Discord guild objects)."""
    return [guild for guild in bot.guilds if _guild_active(guild.id)]


def _game_guild_id(game: dict | None) -> int:
    """The server a game belongs to (older games: the home server)."""
    return _as_gid((game or {}).get("guild_id"))


def _mode_enabled(mode) -> bool:
    """A game mode is off when the server turned it (or its branch) off."""
    name = MODE_NAME_ALIASES.get(str(mode or ""), str(mode or ""))
    return bool((MODE_CONFIG.get(name) or {}).get("enabled", True))


def _settings_changes(before: dict, after: dict, prefix: str = "") -> list[dict]:
    """Which settings differ: [{path, before, after}] (leaves only)."""
    changes: list[dict] = []
    keys = list(dict.fromkeys(list((before or {}).keys()) + list((after or {}).keys())))
    for key in keys:
        a = (before or {}).get(key)
        b = (after or {}).get(key)
        path = f"{prefix}.{key}" if prefix else str(key)
        if isinstance(a, dict) and isinstance(b, dict):
            changes.extend(_settings_changes(a, b, path))
        elif a != b:
            changes.append({"path": path, "before": a, "after": b})
    return changes


# ————— MySQL (worker threads only) —————

def _guild_settings_query_mysql(sql: str, params: tuple = (), *, fetch: str | None = None, commit: bool = False):
    conn = None
    cur = None
    try:
        conn = _db_get_connection()
        cur = conn.cursor(dictionary=True)
        cur.execute(sql, params)
        result = None
        if fetch == "one":
            result = cur.fetchone()
        elif fetch == "all":
            result = cur.fetchall()
        elif fetch == "rowcount":
            result = cur.rowcount
        if commit:
            conn.commit()
        return result
    finally:
        if cur is not None:
            try:
                cur.close()
            except Exception:
                pass
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _settings_row(row: dict | None) -> dict | None:
    if row and isinstance(row.get("settings"), (str, bytes, bytearray)):
        try:
            row["settings"] = json.loads(row["settings"])
        except Exception:
            row["settings"] = None
    return row


def _load_guild_settings_row_mysql(guild_id: int) -> dict | None:
    return _settings_row(_guild_settings_query_mysql(
        "SELECT guild_id, guild_name, status, settings, version, is_home, bot_present FROM guild_settings WHERE guild_id = %s",
        (str(guild_id),), fetch="one",
    ))


def _load_all_guild_settings_mysql() -> dict[str, dict]:
    rows = _guild_settings_query_mysql(
        "SELECT guild_id, guild_name, status, settings, version, is_home, bot_present FROM guild_settings",
        fetch="all",
    ) or []
    return {str(row["guild_id"]): _settings_row(row) for row in rows}


def _guild_presence_mysql(guild_id: int, name: str, icon, owner_id, *, present: bool, home: bool) -> None:
    now = int(time.time())
    if present:
        _guild_settings_query_mysql(
            "INSERT INTO guild_settings (guild_id, guild_name, icon, owner_id, status, is_home, bot_present, version, "
            "joined_at, created_at, updated_at) VALUES (%s, %s, %s, %s, 'needs_setup', %s, 1, 0, %s, %s, %s) "
            "ON DUPLICATE KEY UPDATE guild_name = VALUES(guild_name), icon = VALUES(icon), owner_id = VALUES(owner_id), "
            "is_home = VALUES(is_home), joined_at = IF(bot_present = 0, VALUES(joined_at), joined_at), bot_present = 1, "
            "left_at = NULL",
            (str(guild_id), (name or "")[:100], icon, str(owner_id) if owner_id else None, 1 if home else 0, now, now, now),
            commit=True,
        )
    else:
        _guild_settings_query_mysql(
            "UPDATE guild_settings SET bot_present = 0, left_at = %s WHERE guild_id = %s",
            (now, str(guild_id)), commit=True,
        )


def _mark_absent_guilds_mysql(present_ids: list[str]) -> None:
    now = int(time.time())
    if present_ids:
        marks = ", ".join(["%s"] * len(present_ids))
        _guild_settings_query_mysql(
            f"UPDATE guild_settings SET bot_present = 0, left_at = %s WHERE bot_present = 1 AND guild_id NOT IN ({marks})",
            (now, *present_ids), commit=True,
        )


def _save_guild_settings_mysql(guild_id: int, settings: dict, expected_version: int, *, status: str | None,
                               actor_name: str, summary: str, changes: list) -> int | None:
    """Optimistic save (only if nobody saved in between) + a history row.
    Returns the new version, or None when the version moved on."""
    now = int(time.time())
    new_version = int(expected_version) + 1
    rows = _guild_settings_query_mysql(
        "UPDATE guild_settings SET settings = %s, version = %s, updated_at = %s, updated_by = NULL"
        + (", status = %s, setup_completed_at = COALESCE(setup_completed_at, %s)" if status else "")
        + " WHERE guild_id = %s AND version = %s",
        (json.dumps(settings, ensure_ascii=False), new_version, now)
        + ((status, now) if status else ())
        + (str(guild_id), int(expected_version)),
        fetch="rowcount", commit=True,
    )
    if not rows:
        return None
    _guild_settings_query_mysql(
        "INSERT INTO guild_settings_history (guild_id, version, actor_id, actor_name, summary, changes, created_at) "
        "VALUES (%s, %s, NULL, %s, %s, %s, %s)",
        (str(guild_id), new_version, actor_name[:100], summary[:500], json.dumps(changes[:200], ensure_ascii=False), now),
        commit=True,
    )
    return new_version


def _settings_versions_mysql() -> list[dict]:
    return _guild_settings_query_mysql(
        "SELECT guild_id, version, status FROM guild_settings WHERE bot_present = 1", fetch="all",
    ) or []


def _history_since_mysql(guild_id: int, version: int) -> list[dict]:
    return _guild_settings_query_mysql(
        "SELECT version, actor_id, actor_name, summary FROM guild_settings_history "
        "WHERE guild_id = %s AND version > %s ORDER BY version LIMIT 10",
        (str(guild_id), int(version)), fetch="all",
    ) or []


def _write_guild_snapshot_mysql(guild_id: int, data: dict) -> None:
    _guild_settings_query_mysql(
        "INSERT INTO web_guild_snapshot (guild_id, data, updated_at) VALUES (%s, %s, %s) "
        "ON DUPLICATE KEY UPDATE data = VALUES(data), updated_at = VALUES(updated_at)",
        (str(guild_id), json.dumps(data, ensure_ascii=False), int(time.time())), commit=True,
    )


# ————— Snapshot: what the website's pickers and health check see —————

def _channel_kind(channel) -> str | None:
    if isinstance(channel, discord.CategoryChannel):
        return "category"
    if isinstance(channel, discord.ForumChannel):
        return "forum"
    if isinstance(channel, discord.StageChannel):
        return "stage"
    if isinstance(channel, discord.VoiceChannel):
        return "voice"
    if isinstance(channel, discord.TextChannel):
        return "news" if channel.is_news() else "text"
    return None


def _guild_snapshot(guild, settings: dict | None) -> dict:
    me = guild.me
    roles = [
        {
            "id": str(role.id), "name": role.name, "position": role.position,
            "color": f"#{role.colour.value:06x}" if role.colour.value else None,
            "managed": bool(role.managed), "mentionable": bool(role.mentionable), "hoist": bool(role.hoist),
            "everyone": role.is_default(), "members": len(role.members),
        }
        for role in sorted(guild.roles, key=lambda r: -r.position)
    ]
    channels = []
    for channel in guild.channels:
        kind = _channel_kind(channel)
        if kind is None:
            continue
        perms = channel.permissions_for(me) if me is not None else None
        channels.append({
            "id": str(channel.id), "name": channel.name, "type": kind,
            "parent_id": str(channel.category_id) if getattr(channel, "category_id", None) else None,
            "position": channel.position,
            "bot": {
                "view": bool(perms and perms.view_channel),
                "send": bool(perms and perms.send_messages),
                "embed": bool(perms and perms.embed_links),
                "attach": bool(perms and perms.attach_files),
                "threads": bool(perms and perms.create_public_threads and perms.send_messages_in_threads),
                "manage": bool(perms and perms.manage_channels),
                "connect": bool(perms and perms.connect),
                "move": bool(perms and perms.move_members),
            },
        })
    staff_roles = {int(r) for r in ((settings or {}).get("access") or {}).get("senior_staff_roles") or [] if str(r).isdigit()}
    staff = sorted({
        str(member.id)
        for rid in staff_roles
        if (role := guild.get_role(rid)) is not None
        for member in role.members
        if not member.bot
    })
    top = me.top_role if me is not None else None
    return {
        "guild": {
            "id": str(guild.id), "name": guild.name,
            "icon": guild.icon.key if guild.icon else None,
            "owner_id": str(guild.owner_id) if guild.owner_id else None,
            "member_count": guild.member_count or 0,
            "system_channel_id": str(guild.system_channel.id) if guild.system_channel else None,
            "community": "COMMUNITY" in (guild.features or []),
        },
        "roles": roles,
        "channels": sorted(channels, key=lambda c: (c["position"], c["name"])),
        "bot": {
            "user_id": str(me.id) if me else None,
            "permissions": str(me.guild_permissions.value) if me else "0",
            "top_role_id": str(top.id) if top else None,
            "top_role_position": top.position if top else 0,
        },
        "staff_user_ids": staff,
        "updated_at": int(time.time()),
    }


async def _refresh_guild_snapshot(guild) -> None:
    try:
        settings = _rt(guild.id).settings
        await _run_mysql_io(_write_guild_snapshot_mysql, guild.id, _guild_snapshot(guild, settings), label="guild snapshot write")
    except Exception as e:
        print(f"[WARN] guild snapshot {guild.id} failed: {e}")


def _schedule_snapshot(guild_id: int) -> None:
    """Debounced snapshot: a burst of role / channel changes writes once."""
    task = _snapshot_pending.get(guild_id)
    if task is not None and not task.done():
        return

    async def later():
        await asyncio.sleep(GUILD_SNAPSHOT_DEBOUNCE_SEC)
        guild = bot.get_guild(guild_id)
        if guild is not None:
            await _refresh_guild_snapshot(guild)

    _snapshot_pending[guild_id] = asyncio.create_task(later())


def _setup_url(guild_id) -> str:
    return f"{WEB_SITE_URL}/servers?guild={guild_id}"


async def _welcome_new_guild(guild) -> None:
    """Tell the owner where to set the bot up (DM, else the system channel)."""
    embed = discord.Embed(
        title=f"👋 GameMaster joined {guild.name}",
        description=(
            "Thanks for adding GameMaster! Set it up on the website — map your staff and host roles, "
            "pick your host branches (RP / Historical), game modes and channels:\n\n"
            f"**[Open setup]({_setup_url(guild.id)})**\n\n"
            "Only the server owner, admins and people the owner allows can change the settings. "
            "GameMaster switches on in this server as soon as setup is finished."
        ),
        color=discord.Color.gold(),
    )
    embed.set_footer(text="GameMaster · server setup")
    owner = guild.owner
    if owner is None and guild.owner_id:
        try:
            owner = await bot.fetch_user(guild.owner_id)
        except Exception:
            owner = None
    if owner is not None and await _dm_user_safe(owner, embed=embed, label="setup welcome"):
        return
    channel = guild.system_channel
    if channel is not None and channel.permissions_for(guild.me).send_messages:
        try:
            await channel.send(embed=embed)
        except Exception as e:
            print(f"[WARN] setup welcome in {guild.id} failed: {e}")


async def _record_guild(guild, *, present: bool = True) -> None:
    icon = guild.icon.key if guild.icon else None
    await _run_mysql_io(
        lambda: _guild_presence_mysql(
            guild.id, guild.name, icon, guild.owner_id, present=present, home=guild.id == GUILD_ID,
        ),
        label="guild presence",
    )


async def _save_bot_settings(gid: int, settings: dict, *, summary: str, status: str | None = None) -> bool:
    """Settings changes the bot makes itself (the home seed, roles it created).
    Re-reads and retries once if the website saved in between."""
    rt = _rt(gid)
    for _ in range(2):
        row = await _run_mysql_io(_load_guild_settings_row_mysql, gid, label="guild settings read")
        if row is None:
            return False
        before = _normalize_guild_settings(row.get("settings"), row.get("guild_name") or "")
        changes = _settings_changes(before, settings)
        if not changes and not status:
            return True
        expected = int(row.get("version") or 0)
        version = await _run_mysql_io(
            lambda: _save_guild_settings_mysql(
                gid, settings, expected, status=status, actor_name="GameMaster bot", summary=summary, changes=changes,
            ),
            label="guild settings save",
        )
        if version is not None:
            rt.version = version
            if status:
                rt.status = status
            return True
    return False


def _load_runtime_from_row(guild, row: dict | None) -> GuildRuntime:
    """Build / refresh a server's runtime from its guild_settings row."""
    rt = _rt(guild.id)
    rt.present = True
    name = (row or {}).get("guild_name") or guild.name
    if row and row.get("settings"):
        _apply_settings(rt, _normalize_guild_settings(row["settings"], name))
        rt.version = int(row.get("version") or 0)
    elif guild.id != GUILD_ID:
        _apply_settings(rt, _default_guild_settings(name))
        rt.version = int((row or {}).get("version") or 0)
    rt.status = str((row or {}).get("status") or "needs_setup")
    return rt


async def _publish_guild_web_data(guild) -> None:
    """What the website reads per server: role ids and the Database page options."""
    with guild_scope(guild.id):
        await _publish_member_role_ids()
        try:
            await publish_web_moderation_options()
        except Exception as e:
            print(f"[WARN] moderation options for {guild.id} failed: {e}")


async def _sync_server_commands(guild) -> int:
    """Give a server GameMaster's slash commands (the home server's set minus
    HOME_ONLY_COMMANDS) and sync them. Returns how many it has."""
    target = discord.Object(id=guild.id)
    if guild.id != GUILD_ID:
        bot.tree.clear_commands(guild=target)
        for command in bot.tree.get_commands(guild=discord.Object(id=GUILD_ID)):
            if command.name in HOME_ONLY_COMMANDS:
                continue
            bot.tree.add_command(command, guild=target, override=True)
    try:
        synced = await bot.tree.sync(guild=target)
    except Exception as e:
        await _record_command_sync(guild.id, None, str(e))
        raise
    _command_guilds.add(guild.id)
    await _record_command_sync(guild.id, len(synced), None)
    return len(synced)


def _home_modes_to_add(stored) -> list[str]:
    """Built-in modes missing from the home server's saved settings (added to
    the bot after the settings were first saved)."""
    if isinstance(stored, str):
        try:
            stored = json.loads(stored)
        except Exception:
            stored = None
    if not isinstance(stored, dict):
        return []
    modes = stored.get("modes") if isinstance(stored.get("modes"), dict) else {}
    return [key for key, _ in BUILTIN_MODES if key not in modes and key in _HOME_MODE_SEED]


def _fresh_home_settings(name: str) -> dict:
    """The home server's first settings: nothing mapped, like any server.
    The game modes' mod and rule links and the rule numbers carry over."""
    copied = _settings_from_constants(name)
    fresh = _default_guild_settings(name)
    for key, _branch in BUILTIN_MODES:
        fresh["modes"][key]["mod_links"] = list(copied["modes"][key].get("mod_links") or [])
        fresh["modes"][key]["rule_links"] = list(copied["modes"][key].get("rule_links") or [])
    fresh["rules"] = dict(copied["rules"])
    return fresh


async def _bootstrap_server_settings() -> None:
    """Startup: record every server the bot is in, give each its runtime
    (blank settings for the home server the first time), mirror roles /
    channels for the website, and switch on every server whose setup is
    finished."""
    await bot.wait_until_ready()
    home = bot.get_guild(GUILD_ID)
    for guild in list(bot.guilds):
        try:
            await _record_guild(guild)
        except Exception as e:
            print(f"[WARN] recording guild {guild.id} failed: {e}")
    try:
        await _run_mysql_io(_mark_absent_guilds_mysql, [str(g.id) for g in bot.guilds], label="guild presence sweep")
    except Exception as e:
        print(f"[WARN] guild presence sweep failed: {e}")

    try:
        rows = await _run_mysql_io(_load_all_guild_settings_mysql, label="guild settings read")
    except Exception as e:
        print(f"⚠️ Loading server settings failed — servers stay off until it works: {e}")
        rows = {}
    home_row = rows.get(str(GUILD_ID))
    seeded = bool(home_row and home_row.get("settings"))
    for guild in list(bot.guilds):
        try:
            _load_runtime_from_row(guild, rows.get(str(guild.id)))
        except Exception as e:
            print(f"⚠️ Settings for {guild.id} could not be applied: {e}")
    if seeded:
        print(f"⚙️ Home server settings v{_rt(GUILD_ID).version} applied.")

    # Hist Verified and the website's role ids for the home server; VIPs get Hist Verified once.
    with guild_scope(GUILD_ID):
        await _setup_member_roles()

    if home is not None:
        try:
            if not seeded:
                current = _fresh_home_settings(home.name)
                current["general"]["community_name"] = home.name[:60]
                ok = await _save_bot_settings(
                    GUILD_ID, current, summary="Started blank settings for this server", status="needs_setup",
                )
                if ok:
                    _apply_settings(_rt(GUILD_ID), _normalize_guild_settings(current, home.name))
                    _rt(GUILD_ID).status = "needs_setup"
                print("⚙️ Server settings started blank — finish setup on the website." if ok else "⚠️ Starting server settings failed.")
            elif _rt(GUILD_ID).settings is not None:
                # Game modes added to the bot since the settings were saved (switched off).
                added_modes = _home_modes_to_add(home_row.get("settings"))
                if added_modes:
                    merged = json.loads(json.dumps(_rt(GUILD_ID).settings))
                    fresh_modes = _fresh_home_settings(home.name)["modes"]
                    for key in added_modes:
                        merged["modes"][key] = fresh_modes[key]
                    if await _save_bot_settings(GUILD_ID, merged, summary="Added new game modes: " + ", ".join(added_modes)):
                        _rt(GUILD_ID).settings = merged
                        _apply_settings(_rt(GUILD_ID), merged)
        except Exception as e:
            print(f"⚠️ Saving server settings failed: {e}")

    for guild in list(bot.guilds):
        await _refresh_guild_snapshot(guild)
        if guild.id != GUILD_ID and _guild_active(guild.id):
            try:
                await _publish_guild_web_data(guild)
                count = await _sync_server_commands(guild)
                print(f"✅ {guild.name}: GameMaster is on ({count} commands).")
            except Exception as e:
                print(f"⚠️ Switching on {guild.id} failed: {e}")
    if not guild_settings_loop.is_running():
        guild_settings_loop.start()
    await _bot_status_started()


async def _guild_switched_on(guild) -> None:
    """A server finished setup: publish its web data, give it commands and say hello."""
    await _publish_guild_web_data(guild)
    try:
        count = await _sync_server_commands(guild)
    except Exception as e:
        print(f"⚠️ Command sync for {guild.id} failed: {e}")
        count = 0
    with guild_scope(guild.id):
        channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
        if channel is not None:
            embed = discord.Embed(
                title="✅ GameMaster is on",
                description=(
                    "Setup is finished — hosts can log in on the website and schedule games, and "
                    f"{count} slash commands are available here. Change anything in the "
                    f"[server settings]({_setup_url(guild.id)})."
                ),
                color=discord.Color.green(),
            )
            try:
                await channel.send(embed=embed)
            except Exception as e:
                print(f"[WARN] switch-on notice in {guild.id} failed: {e}")


@tasks.loop(seconds=GUILD_SETTINGS_POLL_SEC)
async def guild_settings_loop():
    """Pick up settings saved on the website: apply them to that server's
    runtime, post what changed to its host log, and switch servers on when
    their setup is finished. Also refresh every server's snapshot now and
    then (Host Management membership decides who may edit settings)."""
    global _last_snapshot_sweep
    await bot.wait_until_ready()
    try:
        rows = await _run_mysql_io(_settings_versions_mysql, label="guild settings versions")
    except Exception as e:
        print(f"[WARN] guild settings poll failed: {e}")
        return
    for row in rows:
        guild = bot.get_guild(_iid(row.get("guild_id")))
        if guild is None:
            continue
        rt = _rt(guild.id)
        version = int(row.get("version") or 0)
        status = str(row.get("status") or "needs_setup")
        if version <= rt.version and status == rt.status:
            continue
        try:
            fresh = await _run_mysql_io(_load_guild_settings_row_mysql, guild.id, label="guild settings read")
            was_active = rt.active
            before = rt.settings
            previous = rt.version
            _load_runtime_from_row(guild, fresh)
            history = await _run_mysql_io(_history_since_mysql, guild.id, previous, label="settings history")
            print(f"⚙️ {guild.name}: settings v{previous} → v{rt.version} applied.")
            if rt.active and not was_active:
                await _guild_switched_on(guild)
            elif rt.active:
                await _publish_guild_web_data(guild)
            if rt.active:
                await _ensure_schedule_panel(guild)
            _schedule_snapshot(guild.id)
            web_changes = [h for h in history if h.get("actor_id")]
            if web_changes and before is not None and rt.active:
                changed = _settings_changes(before, rt.settings or {})
                with guild_scope(guild.id):
                    embed = discord.Embed(
                        title="⚙️ Server settings changed on the website",
                        description="\n".join(
                            f"• **{h.get('actor_name') or 'Someone'}**: {h.get('summary') or 'settings updated'}" for h in web_changes
                        )[:3500],
                        color=discord.Color.blurple(),
                    )
                    embed.add_field(name="Fields changed", value=str(len(changed)), inline=True)
                    embed.add_field(name="Settings", value=f"[Open]({_setup_url(guild.id)})", inline=True)
                    try:
                        await send_host_log_embed(embed)
                    except Exception as e:
                        print(f"[WARN] settings change notice failed: {e}")
        except Exception as e:
            print(f"⚠️ Applying new settings for {guild.id} failed: {e}")
    if time.time() - _last_snapshot_sweep > GUILD_SNAPSHOT_REFRESH_MIN * 60:
        _last_snapshot_sweep = time.time()
        for guild in list(bot.guilds):
            await _refresh_guild_snapshot(guild)
            await asyncio.sleep(0.5)


async def _publish_member_role_ids() -> None:
    """The role ids the website reads (web_member_roles) for the current server."""
    guild = bot.get_guild(cur_gid())

    def publish(cfg):
        cfg[_WEB_MEMBER_ROLES_KEY] = {
            "rp_verified": str(ROLE_IDS["HOI4_VERIFIED"]) if ROLE_IDS["HOI4_VERIFIED"] else None,
            "hist_verified": str(ROLE_IDS["HIST_VERIFIED"]) if ROLE_IDS.get("HIST_VERIFIED") else None,
            "vip": str(ROLE_IDS.get("VIP_ROLE_ID") or "") or None,
            # The player card's Trusted / Hearts of Valor checks (multi-server).
            "rp_trusted": str(ROLE_IDS.get("HOI4_RP_TRUSTED") or "") or None,
            "hist_trusted": str(ROLE_IDS.get("HOI4_MP_TRUSTED") or "") or None,
            "valor": str(ROLE_IDS.get("VALOR") or "") or None,
            "host_ranks": {
                branch: {rank: str(rid) if rid else None for rank, rid in cfg_b["ranks"].items()}
                for branch, cfg_b in HOST_BRANCHES.items()
            },
            "guild_name": guild.name if guild else None,
        }
    try:
        await _bot_config_mutate(publish)
    except Exception as e:
        print(f"[WARN] publishing member role ids failed: {e}")


@bot.event
async def on_guild_join(guild: discord.Guild):
    print(f"➕ Joined server {guild.name} ({guild.id})")
    try:
        await _record_guild(guild)
        row = await _run_mysql_io(_load_guild_settings_row_mysql, guild.id, label="guild settings read")
        if row is not None and not row.get("settings"):
            expected = int(row.get("version") or 0)
            await _run_mysql_io(
                lambda: _save_guild_settings_mysql(
                    guild.id, _default_guild_settings(guild.name), expected, status=None,
                    actor_name="GameMaster bot", summary="Joined the server — waiting for setup", changes=[],
                ),
                label="guild settings init",
            )
            row = await _run_mysql_io(_load_guild_settings_row_mysql, guild.id, label="guild settings read")
        rt = _load_runtime_from_row(guild, row)
        await _refresh_guild_snapshot(guild)
        if rt.active:
            # Re-added after setup was finished: straight back on.
            await _guild_switched_on(guild)
            return
    except Exception as e:
        print(f"[WARN] recording new server {guild.id} failed: {e}")
    await _welcome_new_guild(guild)


@bot.event
async def on_guild_remove(guild: discord.Guild):
    print(f"➖ Left server {guild.name} ({guild.id})")
    rt = _RUNTIMES.get(guild.id)
    if rt is not None:
        rt.present = False
    _command_guilds.discard(guild.id)
    try:
        await _record_guild(guild, present=False)
    except Exception as e:
        print(f"[WARN] recording server removal {guild.id} failed: {e}")


