@bot.event
async def on_member_update(before: discord.Member, after: discord.Member):
    # Host Management membership decides who may edit settings on the website.
    if before.roles != after.roles:
        settings = _rt(after.guild.id).settings
        staff = {int(r) for r in ((settings or {}).get("access") or {}).get("senior_staff_roles") or []}
        changed = {r.id for r in before.roles} ^ {r.id for r in after.roles}
        if settings is None or changed & staff:
            _schedule_snapshot(after.guild.id)


# ————— Cross-server ban alerts —————
# Records are separate per server, but when someone game-banned on another
# server joins, this server's staff get a notice (server settings → Features).

def _cross_server_bans_mysql(user_id: int, here: int) -> list[dict]:
    """Game bans this player has on other servers: [{guild_id, modes, since}]."""
    found: dict[str, dict] = {}
    if here != GUILD_ID:
        row = _guild_settings_query_mysql(
            "SELECT banned, hist_banned FROM users WHERE discord_id = %s", (str(user_id),), fetch="one",
        )
        if row and (row.get("banned") or row.get("hist_banned")):
            found[str(GUILD_ID)] = {"banned": bool(row.get("banned")), "hist_banned": bool(row.get("hist_banned"))}
    rows = _guild_settings_query_mysql(
        "SELECT guild_id, banned, hist_banned FROM guild_users "
        "WHERE discord_id = %s AND guild_id <> %s AND (banned = 1 OR hist_banned = 1)",
        (str(user_id), str(here)), fetch="all",
    ) or []
    for row in rows:
        found[str(row["guild_id"])] = {"banned": bool(row.get("banned")), "hist_banned": bool(row.get("hist_banned"))}
    if not found:
        return []
    marks = ", ".join(["%s"] * len(found))
    since_rows = _guild_settings_query_mysql(
        f"SELECT guild_id, MAX(created_at) AS since FROM moderation_events "
        f"WHERE user_id = %s AND action = 'ban' AND guild_id IN ({marks}) GROUP BY guild_id",
        (int(user_id), *found.keys()), fetch="all",
    ) or []
    since = {str(row["guild_id"]): int(row.get("since") or 0) for row in since_rows}
    names = _guild_settings_query_mysql(
        f"SELECT guild_id, guild_name FROM guild_settings WHERE guild_id IN ({marks})", tuple(found.keys()), fetch="all",
    ) or []
    name_by_id = {str(row["guild_id"]): row.get("guild_name") for row in names}
    out = []
    for gid, flags in found.items():
        modes = [label for label, key in (("Roleplay", "banned"), ("Historical", "hist_banned")) if flags[key]]
        out.append({"guild_id": gid, "name": name_by_id.get(gid) or "another server", "modes": modes, "since": since.get(gid) or None})
    return out


async def _alert_cross_server_bans(member) -> None:
    """A member joined: tell staff about game bans they have on other servers."""
    if not SERVER_FEATURES.get("cross_server_ban_alerts", True):
        return
    bans = await _run_mysql_io(_cross_server_bans_mysql, member.id, cur_gid(), label="cross-server ban check")
    if not bans:
        return
    channel = bot.get_channel(G.HOST_MANAGEMENT_CHANNEL_ID) or bot.get_channel(G.HOST_LOG_CHANNEL_ID)
    if channel is None:
        return
    lines = []
    for ban in bans:
        when = f" · since <t:{ban['since']}:D>" if ban.get("since") else ""
        lines.append(f"• **{ban['name']}** — game-banned from {' and '.join(ban['modes'])} games{when}")
    embed = discord.Embed(
        title="⚠️ Joined while game-banned on another server",
        description=(
            f"{member.mention} (`{member.id}`) just joined. They are game-banned on "
            f"{len(bans)} other server{'s' if len(bans) != 1 else ''} that use GameMaster:\n\n"
            + "\n".join(lines)
            + "\n\nRecords are separate per server, so nothing changes here automatically — "
            f"check their [record on the website]({WEB_SITE_URL}/database?player={member.id}) and decide."
        ),
        color=discord.Color.orange(),
    )
    embed.set_footer(text="Cross-server ban alert · switch off in the server settings (Features)")
    try:
        await channel.send(embed=embed)
    except Exception as e:
        print(f"[WARN] cross-server ban alert in {cur_gid()} failed: {e}")


# ————— Which server an interaction is for —————
_GUILD_SUFFIX_RE = re.compile(r":g(\d{15,25})$")
_SNOWFLAKE_RE = re.compile(r"\d{17,20}")


def _guild_suffix() -> str:
    """Appended to DM button ids so a click knows its server (none on the home server)."""
    gid = cur_gid()
    return "" if gid == GUILD_ID else f":g{gid}"


def _interaction_guild(interaction) -> int:
    """The server an interaction belongs to: a ":g<id>" button suffix, else
    the server it happened in, else (DMs) the game whose thread id the button
    carries, else the home server."""
    data = getattr(interaction, "data", None) or {}
    custom_id = str(data.get("custom_id") or "") if isinstance(data, dict) else ""
    match = _GUILD_SUFFIX_RE.search(custom_id)
    if match:
        return int(match.group(1))
    if getattr(interaction, "guild_id", None):
        return int(interaction.guild_id)
    games = _all_games()
    for token in _SNOWFLAKE_RE.findall(custom_id):
        _, game = _find_game_entry(games, token)
        if game:
            return _game_guild_id(game)
    return GUILD_ID


async def _tree_interaction_check(interaction) -> bool:
    """Every slash command / autocomplete: run for the server it was used in."""
    enter_guild(_interaction_guild(interaction))
    return True


_ORIGINAL_VIEW_TASK = discord.ui.View._scheduled_task
_ORIGINAL_MODAL_TASK = discord.ui.Modal._scheduled_task


async def _view_task_for_guild(self, item, interaction):
    enter_guild(_interaction_guild(interaction))
    return await _ORIGINAL_VIEW_TASK(self, item, interaction)


async def _modal_task_for_guild(self, interaction, *args, **kwargs):
    enter_guild(_interaction_guild(interaction))
    return await _ORIGINAL_MODAL_TASK(self, interaction, *args, **kwargs)


def _install_interaction_routing() -> None:
    """Buttons, menus, modals and commands each run for their own server."""
    discord.ui.View._scheduled_task = _view_task_for_guild
    discord.ui.Modal._scheduled_task = _modal_task_for_guild
    bot.tree.interaction_check = _tree_interaction_check


async def _run_for_active_guilds(func, label: str) -> None:
    """Run `func()` once for every server GameMaster works in, each in its scope."""
    for guild in list(bot.guilds):
        if not _guild_active(guild.id):
            continue
        with guild_scope(guild.id):
            try:
                await func()
            except Exception as e:
                print(f"⚠️ {label} ({guild.id}) failed: {e}")


# ————— Website requests: create a role / channel during setup —————
SERVER_SETUP_OPS = ("create_role", "create_channel", "refresh", "sync_commands", "resend_welcome", "test_post", "schedule_panel")
SERVER_SETUP_CHANNEL_KINDS = ("text", "voice", "category", "forum")


def _can_edit_server_settings(member, settings: dict | None) -> bool:
    if member is None:
        return False
    if member.guild.owner_id == member.id or member.guild_permissions.administrator:
        return True
    access = (settings or {}).get("access") or {}
    if not access.get("staff_can_edit_settings"):
        return False
    staff = {int(r) for r in access.get("senior_staff_roles") or [] if str(r).isdigit()}
    return any(role.id in staff for role in member.roles)


async def _process_web_server_setup(req: dict):
    """The setup wizard's "Create for me": a role or channel in any server the
    bot is in, by its owner, an admin or (when allowed) Host Management."""
    payload = req.get("payload") or {}
    guild = bot.get_guild(_iid(payload.get("guild_id")))
    if guild is None:
        return False, None, "❌ GameMaster isn't in that server any more — add it again first."
    user_id = int(req.get("host_id") or 0)
    member = guild.get_member(user_id)
    if member is None:
        try:
            member = await guild.fetch_member(user_id)
        except Exception:
            member = None
    row = await _run_mysql_io(_load_guild_settings_row_mysql, guild.id, label="guild settings read")
    if not _can_edit_server_settings(member, (row or {}).get("settings")):
        return False, None, "❌ Only the server owner, admins (or Host Management, when the owner allows it) can do that."
    op = str(payload.get("op") or "")
    if op not in SERVER_SETUP_OPS:
        return False, None, "❌ Unknown setup action."
    reason = f"GameMaster setup by {member.display_name} ({member.id})"
    created = None
    done = None
    try:
        if op == "sync_commands":
            if guild.id != GUILD_ID and not _guild_active(guild.id):
                return False, None, "❌ Finish setup first — GameMaster gives a server its commands when setup is done."
            count = await _sync_server_commands(guild)
            done = f"Re-synced {count} slash commands"
        elif op == "schedule_panel":
            try:
                with guild_scope(guild.id):
                    done = await _post_schedule_panel(guild)
            except ModerationError as e:
                return False, None, str(e)
        elif op == "resend_welcome":
            await _welcome_new_guild(guild)
            done = "Sent the setup welcome again (to the owner's DMs, else the system channel)"
        elif op == "test_post":
            with guild_scope(guild.id):
                channel = bot.get_channel(G.HOST_LOG_CHANNEL_ID)
            if channel is None or getattr(channel, "guild", None) != guild:
                return False, None, "❌ No host log channel is set — pick one in Channels."
            try:
                await channel.send(embed=discord.Embed(
                    title="🧪 Test message",
                    description=f"GameMaster can post here. Sent from the server dashboard by {member.mention}.",
                    color=discord.Color.green(),
                ))
            except discord.Forbidden:
                return False, None, f"❌ GameMaster can't post in #{channel.name} — give it View Channel and Send Messages there."
            done = f"Posted a test message in #{channel.name}"
        elif op == "create_role":
            name = str(payload.get("name") or "").strip()[:100]
            if not name:
                return False, None, "❌ Give the role a name."
            color = str(payload.get("color") or "").lstrip("#")
            colour = discord.Colour(int(color, 16)) if re.fullmatch(r"[0-9a-fA-F]{6}", color) else discord.Colour.default()
            role = await guild.create_role(
                name=name, colour=colour, mentionable=bool(payload.get("mentionable")), hoist=bool(payload.get("hoist")),
                reason=reason,
            )
            created = {"id": str(role.id), "name": role.name, "kind": "role"}
        elif op == "create_channel":
            kind = str(payload.get("kind") or "text")
            if kind not in SERVER_SETUP_CHANNEL_KINDS:
                return False, None, "❌ Unknown channel type."
            name = str(payload.get("name") or "").strip()[:100]
            if not name:
                return False, None, "❌ Give the channel a name."
            parent = guild.get_channel(_iid(payload.get("parent_id")))
            category = parent if isinstance(parent, discord.CategoryChannel) else None
            if kind == "category":
                channel = await guild.create_category(name=name, reason=reason)
            elif kind == "voice":
                channel = await guild.create_voice_channel(name=name, category=category, reason=reason)
            elif kind == "forum":
                channel = await guild.create_forum(name=name, category=category, reason=reason)
            else:
                channel = await guild.create_text_channel(name=name, category=category, reason=reason)
            created = {"id": str(channel.id), "name": channel.name, "kind": kind}
    except discord.Forbidden:
        return False, None, "❌ GameMaster is missing a permission for that (Manage Roles / Manage Channels)."
    except discord.HTTPException as e:
        text = str(e)
        if op == "create_channel" and str(payload.get("kind")) == "forum":
            return False, None, "❌ Discord only allows forum channels in Community servers — pick a text channel instead."
        return False, None, f"❌ Discord refused: {text[:200]}"
    await _refresh_guild_snapshot(guild)
    _audit_log("INFO", f"server setup {op} guild={guild.id} by={user_id} created={created}")
    summary = (
        f"Created {created['kind']} {created['name']}" if created
        else done or "Refreshed the server's roles and channels"
    )
    return True, {"setup": {"title": "✅ Done", "summary": summary, "created": created}}, None


# ==========================================================================
# STATUS — heartbeat, uptime and incidents (the website's public /status page
# and each server's dashboard), plus each server's last slash-command sync.
# ==========================================================================
BOT_HEARTBEAT_SEC = 60
BOT_OFFLINE_AFTER_SEC = 180   # no heartbeat for this long = offline
_STATUS_DDL = (
    """CREATE TABLE IF NOT EXISTS bot_heartbeat (
        id TINYINT NOT NULL PRIMARY KEY,
        started_at BIGINT NOT NULL,
        beat_at BIGINT NOT NULL,
        latency_ms INT NULL,
        guilds INT NOT NULL DEFAULT 0,
        active_guilds INT NOT NULL DEFAULT 0
    )""",
    """CREATE TABLE IF NOT EXISTS bot_uptime_days (
        day DATE NOT NULL PRIMARY KEY,
        minutes INT NOT NULL DEFAULT 0
    )""",
    """CREATE TABLE IF NOT EXISTS bot_incidents (
        id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
        kind VARCHAR(16) NOT NULL,
        started_at BIGINT NOT NULL,
        ended_at BIGINT NULL,
        detail VARCHAR(300) NULL,
        INDEX idx_bot_incidents_started (started_at)
    )""",
    """CREATE TABLE IF NOT EXISTS guild_bot_status (
        guild_id VARCHAR(32) NOT NULL PRIMARY KEY,
        commands_synced_at BIGINT NULL,
        commands_count INT NULL,
        commands_error VARCHAR(300) NULL,
        updated_at BIGINT NOT NULL
    )""",
)
_status_tables_ready = False
_bot_start_recorded = False


def _status_tables_mysql() -> None:
    global _status_tables_ready
    if _status_tables_ready:
        return
    for ddl in _STATUS_DDL:
        _guild_settings_query_mysql(ddl, commit=True)
    _status_tables_ready = True


def _bot_started_mysql(now: int) -> str | None:
    """A (re)start: time offline since the last heartbeat becomes an outage;
    a quick restart is noted as one. Returns the incident kind recorded."""
    _status_tables_mysql()
    row = _guild_settings_query_mysql("SELECT beat_at FROM bot_heartbeat WHERE id = 1", fetch="one")
    last = int((row or {}).get("beat_at") or 0)
    kind = None
    if last and now - last > BOT_OFFLINE_AFTER_SEC:
        kind = "outage"
        _guild_settings_query_mysql(
            "INSERT INTO bot_incidents (kind, started_at, ended_at, detail) VALUES (%s, %s, %s, %s)",
            (kind, last, now, "GameMaster was offline"), commit=True,
        )
    elif last:
        kind = "restart"
        _guild_settings_query_mysql(
            "INSERT INTO bot_incidents (kind, started_at, ended_at, detail) VALUES (%s, %s, %s, %s)",
            (kind, now, now, "GameMaster restarted"), commit=True,
        )
    _guild_settings_query_mysql(
        "INSERT INTO bot_heartbeat (id, started_at, beat_at, guilds, active_guilds) VALUES (1, %s, %s, 0, 0) "
        "ON DUPLICATE KEY UPDATE started_at = VALUES(started_at), beat_at = VALUES(beat_at)",
        (now, now), commit=True,
    )
    return kind


def _bot_beat_mysql(now: int, latency_ms, guilds: int, active: int) -> None:
    """One heartbeat: online now, plus a minute of uptime for today (UTC)."""
    _status_tables_mysql()
    _guild_settings_query_mysql(
        "UPDATE bot_heartbeat SET beat_at = %s, latency_ms = %s, guilds = %s, active_guilds = %s WHERE id = 1",
        (now, latency_ms, guilds, active), commit=True,
    )
    day = datetime.datetime.fromtimestamp(now, tz=datetime.timezone.utc).date().isoformat()
    _guild_settings_query_mysql(
        "INSERT INTO bot_uptime_days (day, minutes) VALUES (%s, 1) "
        "ON DUPLICATE KEY UPDATE minutes = LEAST(1440, minutes + 1)",
        (day,), commit=True,
    )


def _command_sync_mysql(guild_id: int, count, error) -> None:
    _status_tables_mysql()
    now = int(time.time())
    _guild_settings_query_mysql(
        "INSERT INTO guild_bot_status (guild_id, commands_synced_at, commands_count, commands_error, updated_at) "
        "VALUES (%s, %s, %s, %s, %s) ON DUPLICATE KEY UPDATE "
        "commands_synced_at = COALESCE(VALUES(commands_synced_at), commands_synced_at), "
        "commands_count = COALESCE(VALUES(commands_count), commands_count), "
        "commands_error = VALUES(commands_error), updated_at = VALUES(updated_at)",
        (str(guild_id), now if count is not None else None, count, (error or None) and str(error)[:300], now),
        commit=True,
    )


async def _record_command_sync(guild_id: int, count, error) -> None:
    """Best effort — a status write never breaks a command sync."""
    try:
        await _run_mysql_io(lambda: _command_sync_mysql(guild_id, count, error), label="command sync status")
    except Exception as e:
        print(f"[WARN] command sync status for {guild_id} failed: {e}")


def _latency_ms():
    latency = getattr(bot, "latency", None)
    if not isinstance(latency, (int, float)) or latency != latency or latency in (float("inf"), float("-inf")):
        return None
    return int(latency * 1000)


async def _bot_status_started() -> None:
    """Startup (once per run): record the restart / outage and start beating."""
    global _bot_start_recorded
    if not _bot_start_recorded:
        _bot_start_recorded = True
        try:
            kind = await _run_mysql_io(lambda: _bot_started_mysql(int(time.time())), label="bot status start")
            if kind == "outage":
                print("📉 Recorded an outage since the last heartbeat.")
        except Exception as e:
            print(f"[WARN] bot status start failed: {e}")
    if not bot_heartbeat_loop.is_running():
        bot_heartbeat_loop.start()
    if not ticket_inactivity_loop.is_running():
        ticket_inactivity_loop.start()
    for guild in _active_guilds():
        await _ensure_schedule_panel(guild)


@tasks.loop(seconds=BOT_HEARTBEAT_SEC)
async def bot_heartbeat_loop():
    await bot.wait_until_ready()
    try:
        await _run_mysql_io(
            lambda: _bot_beat_mysql(int(time.time()), _latency_ms(), len(bot.guilds), len(_active_guilds())),
            label="bot heartbeat",
        )
    except Exception as e:
        print(f"[WARN] heartbeat failed: {e}")


@bot.event
async def on_resumed():
    """Gateway resume often happens after network blips that also kill MySQL sockets."""
    try:
        await asyncio.wait_for(asyncio.to_thread(_ping_mysql_once), timeout=10)
        print("✅ MySQL pool healthy after Discord gateway resume")
    except Exception as e:
        print(f"⚠️ MySQL pool unhealthy after gateway resume: {e} — rebuilding now")
        try:
            await asyncio.wait_for(
                asyncio.to_thread(_rebuild_db_pool, "gateway resume health check failed"),
                timeout=30,
            )
        except Exception as e2:
            print(f"❌ Pool rebuild after resume failed (watchdog will keep retrying): {e2}")


